/**
 * My Account — Profile, Security, and Preferences
 * Modeled after Sage Accounting's My Account page.
 */

import { useState, useEffect } from 'react';
import { AppLayout } from '@/components/layout/AppLayout';
import { User, Lock, Settings2, Loader2, Save, Eye, EyeOff } from 'lucide-react';
import { apiFetch } from '@/lib/apiFetch';
import { useAuth } from '@/contexts/AuthContext';
import { useTheme } from '@/contexts/ThemeContext';
import toast from 'react-hot-toast';

// ── Types ─────────────────────────────────────────────────────────────────────

interface ProfileForm {
  firstName: string;
  lastName: string;
  email: string;
  phone: string;
  mobile: string;
}

interface PasswordForm {
  oldPassword: string;
  newPassword: string;
  confirmPassword: string;
}

interface Preferences {
  rowsPerPage: string;
  navMode: string;
}

type TabId = 'profile' | 'security' | 'preferences';

// ── Constants ─────────────────────────────────────────────────────────────────

const INPUT_CLS =
  'w-full px-3 py-2 rounded-lg bg-[var(--ff-bg-primary)] border border-[var(--ff-border-primary)] text-[var(--ff-text-primary)] text-sm focus:border-teal-500 focus:ring-1 focus:ring-teal-500 outline-none disabled:opacity-50 disabled:cursor-not-allowed';
const LABEL_CLS = 'block text-xs font-medium text-[var(--ff-text-secondary)] mb-1';
const SECTION_CLS = 'bg-[var(--ff-surface-primary)] border border-[var(--ff-border-primary)] rounded-xl p-6';

const PAGE_TABS: { id: TabId; label: string; icon: React.ReactNode }[] = [
  { id: 'profile', label: 'Profile', icon: <User className="h-4 w-4" /> },
  { id: 'security', label: 'Security', icon: <Lock className="h-4 w-4" /> },
  { id: 'preferences', label: 'Preferences', icon: <Settings2 className="h-4 w-4" /> },
];

// ── Component ─────────────────────────────────────────────────────────────────

export default function MyAccountPage() {
  const { user, refreshUser } = useAuth();
  const { theme, toggleTheme } = useTheme();

  const [activeTab, setActiveTab] = useState<TabId>('profile');

  // Profile state
  const [profile, setProfile] = useState<ProfileForm>({
    firstName: '', lastName: '', email: '', phone: '', mobile: '',
  });
  const [profileLoading, setProfileLoading] = useState(true);
  const [profileSaving, setProfileSaving] = useState(false);

  // Password state
  const [pwForm, setPwForm] = useState<PasswordForm>({
    oldPassword: '', newPassword: '', confirmPassword: '',
  });
  const [pwSaving, setPwSaving] = useState(false);
  const [showOld, setShowOld] = useState(false);
  const [showNew, setShowNew] = useState(false);
  const [showConfirm, setShowConfirm] = useState(false);

  // Preferences state
  const [prefs, setPrefs] = useState<Preferences>({ rowsPerPage: '20', navMode: 'top' });
  const [prefsSaving, setPrefsSaving] = useState(false);

  // ── Effects ───────────────────────────────────────────────────────────────

  useEffect(() => {
    void loadProfile();
    void loadPreferences();
  }, []);

  async function loadProfile() {
    setProfileLoading(true);
    try {
      const res = await apiFetch('/api/auth/profile');
      const json = await res.json();
      if (json.success && json.data) {
        const d = json.data;
        setProfile({
          firstName: d.firstName ?? '',
          lastName: d.lastName ?? '',
          email: d.email ?? '',
          phone: d.phone ?? '',
          mobile: d.mobile ?? '',
        });
      }
    } catch {
      toast.error('Failed to load profile');
    } finally {
      setProfileLoading(false);
    }
  }

  async function loadPreferences() {
    try {
      const res = await apiFetch('/api/auth/preferences');
      const json = await res.json();
      if (json.success && json.data) {
        setPrefs(prev => ({
          rowsPerPage: json.data.rowsPerPage ?? prev.rowsPerPage,
          navMode: json.data.navMode ?? prev.navMode,
        }));
      }
    } catch {
      // Preferences are non-critical — silently ignore
    }
  }

  // ── Handlers ──────────────────────────────────────────────────────────────

  async function handleProfileSave() {
    if (!profile.firstName.trim() || !profile.lastName.trim()) {
      toast.error('First name and last name are required');
      return;
    }
    setProfileSaving(true);
    try {
      const res = await apiFetch('/api/auth/profile', {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          firstName: profile.firstName,
          lastName: profile.lastName,
          phone: profile.phone,
          mobile: profile.mobile,
        }),
      });
      const json = await res.json();
      if (!res.ok) {
        toast.error(json.error?.message ?? json.message ?? 'Failed to save profile');
        return;
      }
      await refreshUser();
      toast.success('Profile updated successfully');
    } catch {
      toast.error('Failed to save profile');
    } finally {
      setProfileSaving(false);
    }
  }

  async function handlePasswordChange() {
    if (!pwForm.oldPassword || !pwForm.newPassword || !pwForm.confirmPassword) {
      toast.error('All password fields are required');
      return;
    }
    if (pwForm.newPassword !== pwForm.confirmPassword) {
      toast.error('New passwords do not match');
      return;
    }
    setPwSaving(true);
    try {
      const res = await apiFetch('/api/auth/change-password', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(pwForm),
      });
      const json = await res.json();
      if (!res.ok) {
        toast.error(json.error?.message ?? json.message ?? 'Failed to change password');
        return;
      }
      setPwForm({ oldPassword: '', newPassword: '', confirmPassword: '' });
      toast.success('Password changed successfully');
    } catch {
      toast.error('Failed to change password');
    } finally {
      setPwSaving(false);
    }
  }

  async function handlePrefsSave() {
    setPrefsSaving(true);
    try {
      const res = await apiFetch('/api/auth/preferences', {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ preferences: prefs }),
      });
      const json = await res.json();
      if (!res.ok) {
        toast.error(json.error?.message ?? json.message ?? 'Failed to save preferences');
        return;
      }
      toast.success('Preferences saved');
    } catch {
      toast.error('Failed to save preferences');
    } finally {
      setPrefsSaving(false);
    }
  }

  // ── Render ────────────────────────────────────────────────────────────────

  return (
    <AppLayout>
      <div className="p-4 lg:p-6 space-y-6 max-w-3xl">

        {/* Header */}
        <div className="flex items-center gap-3">
          <div className="p-2 rounded-lg bg-teal-500/10">
            <User className="h-6 w-6 text-teal-500" />
          </div>
          <div>
            <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">My Account</h1>
            <p className="text-sm text-[var(--ff-text-secondary)]">
              {user?.name ?? 'Manage your profile and settings'}
            </p>
          </div>
        </div>

        {/* Tabs */}
        <div className="flex gap-1 overflow-x-auto border-b border-[var(--ff-border-primary)]">
          {PAGE_TABS.map(tab => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id)}
              className={`flex items-center gap-2 px-4 py-2.5 text-sm font-medium whitespace-nowrap border-b-2 transition-colors ${
                activeTab === tab.id
                  ? 'border-teal-500 text-teal-500'
                  : 'border-transparent text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)]'
              }`}
            >
              {tab.icon} {tab.label}
            </button>
          ))}
        </div>

        {/* Tab Content */}
        <div className="space-y-6">
          {activeTab === 'profile' && <ProfileTab
            profile={profile}
            loading={profileLoading}
            saving={profileSaving}
            onChange={setProfile}
            onSave={() => void handleProfileSave()}
          />}
          {activeTab === 'security' && <SecurityTab
            form={pwForm}
            saving={pwSaving}
            showOld={showOld} showNew={showNew} showConfirm={showConfirm}
            setShowOld={setShowOld} setShowNew={setShowNew} setShowConfirm={setShowConfirm}
            onChange={setPwForm}
            onSave={() => void handlePasswordChange()}
          />}
          {activeTab === 'preferences' && <PreferencesTab
            prefs={prefs}
            saving={prefsSaving}
            theme={theme}
            onToggleTheme={toggleTheme}
            onChange={setPrefs}
            onSave={() => void handlePrefsSave()}
          />}
        </div>

      </div>
    </AppLayout>
  );
}

// ── Profile Tab ───────────────────────────────────────────────────────────────

function ProfileTab({ profile, loading, saving, onChange, onSave }: {
  profile: ProfileForm;
  loading: boolean;
  saving: boolean;
  onChange: (p: ProfileForm) => void;
  onSave: () => void;
}) {
  if (loading) {
    return <div className="flex justify-center py-12"><Loader2 className="h-8 w-8 animate-spin text-teal-500" /></div>;
  }

  const set = (field: keyof ProfileForm) => (e: React.ChangeEvent<HTMLInputElement>) =>
    onChange({ ...profile, [field]: e.target.value });

  return (
    <section className={SECTION_CLS}>
      <h2 className="text-lg font-semibold text-[var(--ff-text-primary)] mb-4">Personal Information</h2>
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        <div>
          <label className={LABEL_CLS}>First Name *</label>
          <input className={INPUT_CLS} value={profile.firstName} onChange={set('firstName')} placeholder="First name" />
        </div>
        <div>
          <label className={LABEL_CLS}>Last Name *</label>
          <input className={INPUT_CLS} value={profile.lastName} onChange={set('lastName')} placeholder="Last name" />
        </div>
        <div className="md:col-span-2">
          <label className={LABEL_CLS}>Email Address</label>
          <input className={INPUT_CLS} value={profile.email} disabled readOnly
            title="Email cannot be changed here" />
          <p className="text-xs text-[var(--ff-text-secondary)] mt-1">Contact support to change your email address.</p>
        </div>
        <div>
          <label className={LABEL_CLS}>Phone</label>
          <input className={INPUT_CLS} value={profile.phone} onChange={set('phone')} placeholder="+27 11 000 0000" />
        </div>
        <div>
          <label className={LABEL_CLS}>Mobile</label>
          <input className={INPUT_CLS} value={profile.mobile} onChange={set('mobile')} placeholder="+27 82 000 0000" />
        </div>
      </div>
      <div className="mt-6 flex justify-end">
        <button
          onClick={onSave}
          disabled={saving}
          className="flex items-center gap-2 px-4 py-2 bg-teal-600 hover:bg-teal-700 text-white rounded-lg text-sm font-medium transition-colors disabled:opacity-50"
        >
          {saving ? <Loader2 className="h-4 w-4 animate-spin" /> : <Save className="h-4 w-4" />}
          Save Profile
        </button>
      </div>
    </section>
  );
}

// ── Security Tab ──────────────────────────────────────────────────────────────

function SecurityTab({ form, saving, showOld, showNew, showConfirm, setShowOld, setShowNew, setShowConfirm, onChange, onSave }: {
  form: PasswordForm;
  saving: boolean;
  showOld: boolean; showNew: boolean; showConfirm: boolean;
  setShowOld: (v: boolean) => void; setShowNew: (v: boolean) => void; setShowConfirm: (v: boolean) => void;
  onChange: (f: PasswordForm) => void;
  onSave: () => void;
}) {
  const set = (field: keyof PasswordForm) => (e: React.ChangeEvent<HTMLInputElement>) =>
    onChange({ ...form, [field]: e.target.value });

  const pwInput = (field: keyof PasswordForm, show: boolean, toggle: () => void, placeholder: string) => (
    <div className="relative">
      <input
        type={show ? 'text' : 'password'}
        className={INPUT_CLS + ' pr-10'}
        value={form[field]}
        onChange={set(field)}
        placeholder={placeholder}
        autoComplete="new-password"
      />
      <button type="button" onClick={toggle}
        className="absolute right-3 top-1/2 -translate-y-1/2 text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)]">
        {show ? <EyeOff className="h-4 w-4" /> : <Eye className="h-4 w-4" />}
      </button>
    </div>
  );

  return (
    <section className={SECTION_CLS}>
      <h2 className="text-lg font-semibold text-[var(--ff-text-primary)] mb-4">Change Password</h2>
      <div className="space-y-4 max-w-md">
        <div>
          <label className={LABEL_CLS}>Current Password</label>
          {pwInput('oldPassword', showOld, () => setShowOld(!showOld), 'Enter current password')}
        </div>
        <div>
          <label className={LABEL_CLS}>New Password</label>
          {pwInput('newPassword', showNew, () => setShowNew(!showNew), 'Enter new password')}
        </div>
        <div>
          <label className={LABEL_CLS}>Confirm New Password</label>
          {pwInput('confirmPassword', showConfirm, () => setShowConfirm(!showConfirm), 'Repeat new password')}
        </div>
        <p className="text-xs text-[var(--ff-text-secondary)]">
          Password must be at least 8 characters with uppercase, lowercase, and a number.
        </p>
      </div>
      <div className="mt-6 flex justify-end">
        <button
          onClick={onSave}
          disabled={saving}
          className="flex items-center gap-2 px-4 py-2 bg-teal-600 hover:bg-teal-700 text-white rounded-lg text-sm font-medium transition-colors disabled:opacity-50"
        >
          {saving ? <Loader2 className="h-4 w-4 animate-spin" /> : <Lock className="h-4 w-4" />}
          Change Password
        </button>
      </div>
    </section>
  );
}

// ── Preferences Tab ───────────────────────────────────────────────────────────

function PreferencesTab({ prefs, saving, theme, onToggleTheme, onChange, onSave }: {
  prefs: Preferences;
  saving: boolean;
  theme: 'dark' | 'light';
  onToggleTheme: () => void;
  onChange: (p: Preferences) => void;
  onSave: () => void;
}) {
  return (
    <section className={SECTION_CLS}>
      <h2 className="text-lg font-semibold text-[var(--ff-text-primary)] mb-4">Display Preferences</h2>
      <div className="space-y-6">

        {/* Rows per page */}
        <div className="flex items-center justify-between">
          <div>
            <p className="text-sm font-medium text-[var(--ff-text-primary)]">Rows per page</p>
            <p className="text-xs text-[var(--ff-text-secondary)]">Default number of rows shown in lists</p>
          </div>
          <select
            value={prefs.rowsPerPage}
            onChange={e => onChange({ ...prefs, rowsPerPage: e.target.value })}
            className="px-3 py-2 rounded-lg bg-[var(--ff-bg-primary)] border border-[var(--ff-border-primary)] text-[var(--ff-text-primary)] text-sm focus:border-teal-500 outline-none"
          >
            {['10', '15', '20', '25', '50'].map(n => (
              <option key={n} value={n}>{n} rows</option>
            ))}
          </select>
        </div>

        <hr className="border-[var(--ff-border-primary)]" />

        {/* Theme toggle */}
        <div className="flex items-center justify-between">
          <div>
            <p className="text-sm font-medium text-[var(--ff-text-primary)]">Theme</p>
            <p className="text-xs text-[var(--ff-text-secondary)]">Currently: {theme === 'dark' ? 'Dark mode' : 'Light mode'}</p>
          </div>
          <button
            type="button"
            role="switch"
            aria-checked={theme === 'dark'}
            onClick={onToggleTheme}
            className={`relative inline-flex h-5 w-9 flex-shrink-0 rounded-full transition-colors ${theme === 'dark' ? 'bg-teal-600' : 'bg-gray-600'}`}
          >
            <span className={`inline-block h-4 w-4 transform rounded-full bg-white transition-transform mt-0.5 ${theme === 'dark' ? 'translate-x-4 ml-0.5' : 'translate-x-0.5'}`} />
          </button>
        </div>

        <hr className="border-[var(--ff-border-primary)]" />

        {/* Nav mode */}
        <div className="flex items-center justify-between">
          <div>
            <p className="text-sm font-medium text-[var(--ff-text-primary)]">Navigation mode</p>
            <p className="text-xs text-[var(--ff-text-secondary)]">Top bar or side bar navigation layout</p>
          </div>
          <select
            value={prefs.navMode}
            onChange={e => onChange({ ...prefs, navMode: e.target.value })}
            className="px-3 py-2 rounded-lg bg-[var(--ff-bg-primary)] border border-[var(--ff-border-primary)] text-[var(--ff-text-primary)] text-sm focus:border-teal-500 outline-none"
          >
            <option value="top">Top navigation</option>
            <option value="side">Side navigation</option>
          </select>
        </div>

      </div>
      <div className="mt-6 flex justify-end">
        <button
          onClick={onSave}
          disabled={saving}
          className="flex items-center gap-2 px-4 py-2 bg-teal-600 hover:bg-teal-700 text-white rounded-lg text-sm font-medium transition-colors disabled:opacity-50"
        >
          {saving ? <Loader2 className="h-4 w-4 animate-spin" /> : <Save className="h-4 w-4" />}
          Save Preferences
        </button>
      </div>
    </section>
  );
}

