const { neon } = require('@neondatabase/serverless');
const sql = neon(process.env.DATABASE_URL);
(async () => {
  // Migration 257
  await sql.query(\`CREATE TABLE IF NOT EXISTS user_preferences (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id VARCHAR(255) NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    key TEXT NOT NULL,
    value TEXT NOT NULL,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW(),
    UNIQUE(user_id, key)
  )\`);
  await sql.query('CREATE INDEX IF NOT EXISTS idx_user_prefs_user ON user_preferences(user_id)');
  await sql.query('ALTER TABLE users ADD COLUMN IF NOT EXISTS mobile VARCHAR(50)');
  console.log('257 done');

  // Migration 258
  await sql.query(\`CREATE TABLE IF NOT EXISTS company_invitations (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    company_id UUID NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
