/**
 * User Access Service
 * Manages company users and invitations — mirrors Sage's "Control User Access".
 */

import crypto from 'crypto';
import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

const VALID_ROLES = ['owner', 'admin', 'manager', 'viewer'] as const;
type CompanyRole = (typeof VALID_ROLES)[number];

// ── Types ─────────────────────────────────────────────────────────────────────

export interface CompanyUserRecord {
  userId: string;
  name: string;
  email: string;
  role: string;
  joinedAt: string;
}

export interface PendingInvitation {
  id: string;
  companyId: string;
  email: string;
  role: string;
  invitedBy: string;
  expiresAt: string;
  createdAt: string;
}

export interface InvitationResult {
  autoAdded: boolean;
  invitation?: PendingInvitation;
}

// ── Helpers ───────────────────────────────────────────────────────────────────

function isValidRole(role: string): role is CompanyRole {
  return (VALID_ROLES as readonly string[]).includes(role);
}

async function countOwners(companyId: string): Promise<number> {
  const rows = (await sql`
    SELECT COUNT(*) AS cnt FROM company_users
    WHERE company_id = ${companyId}::UUID AND role = 'owner'
  `) as Row[];
  return parseInt(rows[0]?.cnt ?? '0', 10);
}

function toIso(val: Date | string | null): string | null {
  if (!val) return null;
  if (val instanceof Date) return val.toISOString();
  return val;
}

// ── Company Users ─────────────────────────────────────────────────────────────

export async function listCompanyUsers(companyId: string): Promise<CompanyUserRecord[]> {
  const rows = (await sql`
    SELECT
      cu.user_id,
      u.first_name,
      u.last_name,
      u.email,
      cu.role,
      cu.created_at
    FROM company_users cu
    JOIN users u ON u.id = cu.user_id::VARCHAR
    WHERE cu.company_id = ${companyId}::UUID
    ORDER BY cu.created_at ASC
  `) as Row[];

  return rows.map((r: Row) => ({
    userId: r.user_id,
    name: `${r.first_name ?? ''} ${r.last_name ?? ''}`.trim() || r.email,
    email: r.email,
    role: r.role,
    joinedAt: toIso(r.created_at) ?? '',
  }));
}

export async function updateCompanyUserRole(
  companyId: string,
  userId: string,
  newRole: string,
): Promise<void> {
  if (!isValidRole(newRole)) {
    throw new Error(`Invalid role. Must be one of: ${VALID_ROLES.join(', ')}`);
  }

  // Prevent stripping last owner
  const currentRows = (await sql`
    SELECT role FROM company_users
    WHERE company_id = ${companyId}::UUID AND user_id = ${userId}::UUID
  `) as Row[];

  const currentRole = currentRows[0]?.role as string | undefined;
  if (currentRole === 'owner' && newRole !== 'owner') {
    const ownerCount = await countOwners(companyId);
    if (ownerCount <= 1) {
      throw new Error('Cannot change role: this is the last owner of the company.');
    }
  }

  await sql`
    UPDATE company_users
    SET role = ${newRole}
    WHERE company_id = ${companyId}::UUID AND user_id = ${userId}::UUID
  `;
  log.info('Company user role updated', { companyId, userId, newRole }, 'accounting');
}

export async function removeCompanyUser(companyId: string, userId: string): Promise<void> {
  // Prevent removing last owner
  const rows = (await sql`
    SELECT role FROM company_users
    WHERE company_id = ${companyId}::UUID AND user_id = ${userId}::UUID
  `) as Row[];

  if (rows[0]?.role === 'owner') {
    const ownerCount = await countOwners(companyId);
    if (ownerCount <= 1) {
      throw new Error('Cannot remove the last owner of the company.');
    }
  }

  await sql`
    DELETE FROM company_users
    WHERE company_id = ${companyId}::UUID AND user_id = ${userId}::UUID
  `;
  log.info('Company user removed', { companyId, userId }, 'accounting');
}

// ── Invitations ───────────────────────────────────────────────────────────────

export async function createInvitation(
  companyId: string,
  email: string,
  role: string,
  invitedBy: string,
): Promise<InvitationResult> {
  if (!isValidRole(role)) {
    throw new Error(`Invalid role. Must be one of: ${VALID_ROLES.join(', ')}`);
  }

  // Check if a user with this email already exists
  const existing = (await sql`
    SELECT id FROM users WHERE email = ${email} LIMIT 1
  `) as Row[];

  if (existing.length > 0) {
    const existingUserId = existing[0].id as string;

    // Check if already in company
    const alreadyMember = (await sql`
      SELECT 1 FROM company_users
      WHERE company_id = ${companyId}::UUID AND user_id = ${existingUserId}::UUID
    `) as Row[];

    if (alreadyMember.length > 0) {
      throw new Error('This user is already a member of the company.');
    }

    // Auto-add directly
    await sql`
      INSERT INTO company_users (company_id, user_id, role)
      VALUES (${companyId}::UUID, ${existingUserId}::UUID, ${role})
      ON CONFLICT (company_id, user_id) DO NOTHING
    `;
    log.info('User auto-added to company', { companyId, email, role }, 'accounting');
    return { autoAdded: true };
  }

  // Create invitation row — upsert on (company_id, email) to allow re-invite
  const token = crypto.randomBytes(32).toString('hex');
  const expiresAt = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString();

  const rows = (await sql`
    INSERT INTO company_invitations (company_id, email, role, invited_by, token, expires_at)
    VALUES (${companyId}::UUID, ${email}, ${role}, ${invitedBy}, ${token}, ${expiresAt}::TIMESTAMPTZ)
    ON CONFLICT (company_id, email) DO UPDATE SET
      role = EXCLUDED.role,
      invited_by = EXCLUDED.invited_by,
      token = EXCLUDED.token,
      expires_at = EXCLUDED.expires_at,
      accepted_at = NULL,
      created_at = NOW()
    RETURNING *
  `) as Row[];

  const inv = rows[0];
  log.info('Invitation created', { companyId, email, role }, 'accounting');
  return {
    autoAdded: false,
    invitation: mapInvitation(inv),
  };
}

export async function listPendingInvitations(companyId: string): Promise<PendingInvitation[]> {
  const rows = (await sql`
    SELECT * FROM company_invitations
    WHERE company_id = ${companyId}::UUID
      AND accepted_at IS NULL
      AND expires_at > NOW()
    ORDER BY created_at DESC
  `) as Row[];
  return rows.map(mapInvitation);
}

export async function cancelInvitation(invitationId: string, companyId: string): Promise<void> {
  await sql`
    DELETE FROM company_invitations
    WHERE id = ${invitationId}::UUID AND company_id = ${companyId}::UUID
  `;
  log.info('Invitation cancelled', { invitationId, companyId }, 'accounting');
}

export async function acceptInvitation(token: string, userId: string): Promise<void> {
  const rows = (await sql`
    SELECT * FROM company_invitations
    WHERE token = ${token}
      AND accepted_at IS NULL
      AND expires_at > NOW()
    LIMIT 1
  `) as Row[];

  if (rows.length === 0) {
    throw new Error('Invitation not found or has expired.');
  }

  const inv = rows[0];

  await sql`
    INSERT INTO company_users (company_id, user_id, role)
    VALUES (${inv.company_id}::UUID, ${userId}::UUID, ${inv.role})
    ON CONFLICT (company_id, user_id) DO NOTHING
  `;

  await sql`
    UPDATE company_invitations SET accepted_at = NOW() WHERE id = ${inv.id}::UUID
  `;

  log.info('Invitation accepted', { token, userId, companyId: inv.company_id }, 'accounting');
}

// ── Mapper ────────────────────────────────────────────────────────────────────

function mapInvitation(r: Row): PendingInvitation {
  return {
    id: r.id,
    companyId: r.company_id,
    email: r.email,
    role: r.role,
    invitedBy: r.invited_by,
    expiresAt: toIso(r.expires_at) ?? '',
    createdAt: toIso(r.created_at) ?? '',
  };
}

/**
 * User Access Control — mirrors Sage Accounting "Control User Access".
 */

import { useState, useEffect, useCallback } from 'react';
import { AppLayout } from '@/components/layout/AppLayout';
import { Users, UserPlus, Trash2, Shield, Mail, Clock } from 'lucide-react';
import { apiFetch } from '@/lib/apiFetch';
import { useAuth } from '@/contexts/AuthContext';

interface CompanyUser { userId: string; name: string; email: string; role: string; joinedAt: string; }
interface PendingInvitation { id: string; email: string; role: string; expiresAt: string; createdAt: string; }

const ROLES = ['owner', 'admin', 'manager', 'viewer'] as const;
const ADMIN_ROLES = ['owner', 'admin'];
const ROLE_BADGE: Record<string, string> = {
  owner: 'bg-teal-900 text-teal-300', admin: 'bg-blue-900 text-blue-300',
  manager: 'bg-purple-900 text-purple-300', viewer: 'bg-gray-700 text-gray-300',
};

export default function UserAccessPage() {
  const { user } = useAuth();
  const [users, setUsers] = useState<CompanyUser[]>([]);
  const [invitations, setInvitations] = useState<PendingInvitation[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [inviteEmail, setInviteEmail] = useState('');
  const [inviteRole, setInviteRole] = useState<string>('viewer');
  const [inviting, setInviting] = useState(false);
  const [feedback, setFeedback] = useState<string | null>(null);
  const [confirmRemove, setConfirmRemove] = useState<string | null>(null);

  const myEntry = users.find((u) => u.userId === user?.id);
  const myRole = myEntry?.role ?? '';
  const isAdmin = ADMIN_ROLES.includes(myRole);
  const ownerCount = users.filter((u) => u.role === 'owner').length;

  const loadData = useCallback(async () => {
    setLoading(true); setError(null);
    try {
      const ur = await (await apiFetch('/api/accounting/company-users')).json();
      setUsers(ur.data ?? []);
      if (isAdmin) {
        const ir = await (await apiFetch('/api/accounting/company-invitations')).json();
        setInvitations(ir.data ?? []);
      }
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Failed to load data.');
    } finally { setLoading(false); }
  }, [isAdmin]);

  useEffect(() => { loadData(); }, [loadData]);

  const showFeedback = (msg: string) => {
    setFeedback(msg);
    setTimeout(() => setFeedback(null), 4000);
  };

  async function handleRoleChange(userId: string, role: string) {
    try {
      const j = await (await apiFetch('/api/accounting/company-users', { method: 'PUT', body: JSON.stringify({ userId, role }) })).json();
      setUsers(j.data ?? []); showFeedback('Role updated.');
    } catch (e) { showFeedback(e instanceof Error ? e.message : 'Update failed.'); }
  }

  async function handleRemove(userId: string) {
    try {
      const j = await (await apiFetch('/api/accounting/company-users', { method: 'DELETE', body: JSON.stringify({ userId }) })).json();
      setUsers(j.data ?? []); showFeedback('User removed.');
    } catch (e) { showFeedback(e instanceof Error ? e.message : 'Remove failed.'); }
    finally { setConfirmRemove(null); }
  }

  async function handleInvite(e: React.FormEvent) {
    e.preventDefault();
    if (!inviteEmail.trim()) return;
    setInviting(true);
    try {
      const j = await (await apiFetch('/api/accounting/company-invitations', {
        method: 'POST', body: JSON.stringify({ email: inviteEmail.trim(), role: inviteRole }),
      })).json();
      if (j.data?.autoAdded) {
        showFeedback(`${inviteEmail} was found and added directly to this company.`);
        loadData();
      } else {
        showFeedback(`Invitation sent to ${inviteEmail}.`);
        const ir = await (await apiFetch('/api/accounting/company-invitations')).json();
        setInvitations(ir.data ?? []);
      }
      setInviteEmail('');
    } catch (e) { showFeedback(e instanceof Error ? e.message : 'Invite failed.'); }
    finally { setInviting(false); }
  }

  async function handleCancelInvite(invitationId: string) {
    try {
      await apiFetch('/api/accounting/company-invitations', { method: 'DELETE', body: JSON.stringify({ invitationId }) });
      setInvitations((prev) => prev.filter((i) => i.id !== invitationId));
      showFeedback('Invitation cancelled.');
    } catch (e) { showFeedback(e instanceof Error ? e.message : 'Cancel failed.'); }
  }

  const fmt = (iso: string) => new Date(iso).toLocaleDateString('en-ZA', { day: '2-digit', month: 'short', year: 'numeric' });

  return (
    <AppLayout>
      <div className="min-h-screen bg-gray-950 px-4 py-8 sm:px-8">
        <div className="mx-auto max-w-4xl space-y-8">

          <div className="flex items-center gap-3">
            <Shield className="h-7 w-7 text-teal-400" />
            <div>
              <h1 className="text-2xl font-bold text-white">User Access Control</h1>
              <p className="text-sm text-gray-400">Manage who can access this company and what they can do.</p>
            </div>
          </div>

          {feedback && <div className="rounded-lg border border-teal-700 bg-teal-900/40 px-4 py-3 text-sm text-teal-300">{feedback}</div>}
          {error && <div className="rounded-lg border border-red-700 bg-red-900/30 px-4 py-3 text-sm text-red-300">{error}</div>}

          {/* Current Users */}
          <div className="rounded-xl border border-gray-800 bg-gray-900">
            <div className="flex items-center gap-2 border-b border-gray-800 px-6 py-4">
              <Users className="h-5 w-5 text-teal-400" />
              <h2 className="font-semibold text-white">Company Users</h2>
            </div>
            {loading ? (
              <div className="px-6 py-10 text-center text-gray-500">Loading...</div>
            ) : (
              <div className="overflow-x-auto">
                <table className="w-full text-sm">
                  <thead>
                    <tr className="border-b border-gray-800 text-left text-gray-500">
                      <th className="px-6 py-3 font-medium">Name</th>
                      <th className="px-6 py-3 font-medium">Email</th>
                      <th className="px-6 py-3 font-medium">Role</th>
                      <th className="px-6 py-3 font-medium">Joined</th>
                      {isAdmin && <th className="px-6 py-3 font-medium">Actions</th>}
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-gray-800">
                    {users.map((u) => {
                      const isSelf = u.userId === user?.id;
                      const isLastOwner = u.role === 'owner' && ownerCount <= 1;
                      return (
                        <tr key={u.userId} className="hover:bg-gray-800/40">
                          <td className="px-6 py-3 text-white">
                            {u.name}{isSelf && <span className="ml-2 text-xs text-gray-500">(you)</span>}
                          </td>
                          <td className="px-6 py-3 text-gray-400">{u.email}</td>
                          <td className="px-6 py-3">
                            {isAdmin && !isSelf ? (
                              <select value={u.role} onChange={(e) => handleRoleChange(u.userId, e.target.value)}
                                className="rounded border border-gray-700 bg-gray-800 px-2 py-1 text-xs text-white focus:border-teal-500 focus:outline-none">
                                {ROLES.map((r) => <option key={r} value={r}>{r}</option>)}
                              </select>
                            ) : (
                              <span className={`inline-flex rounded-full px-2 py-0.5 text-xs font-medium ${ROLE_BADGE[u.role] ?? 'bg-gray-700 text-gray-300'}`}>{u.role}</span>
                            )}
                          </td>
                          <td className="px-6 py-3 text-gray-400">{fmt(u.joinedAt)}</td>
                          {isAdmin && (
                            <td className="px-6 py-3">
                              {!isSelf && !isLastOwner && (
                                confirmRemove === u.userId ? (
                                  <span className="flex items-center gap-2">
                                    <button onClick={() => handleRemove(u.userId)} className="text-xs text-red-400 hover:text-red-300">Confirm</button>
                                    <button onClick={() => setConfirmRemove(null)} className="text-xs text-gray-500 hover:text-gray-300">Cancel</button>
                                  </span>
                                ) : (
                                  <button onClick={() => setConfirmRemove(u.userId)} className="text-gray-500 hover:text-red-400">
                                    <Trash2 className="h-4 w-4" />
                                  </button>
                                )
                              )}
                            </td>
                          )}
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              </div>
            )}
          </div>

          {/* Invite User (admin/owner only) */}
          {isAdmin && (
            <div className="rounded-xl border border-gray-800 bg-gray-900">
              <div className="flex items-center gap-2 border-b border-gray-800 px-6 py-4">
                <UserPlus className="h-5 w-5 text-teal-400" />
                <h2 className="font-semibold text-white">Invite a User</h2>
              </div>
              <div className="px-6 py-5">
                <form onSubmit={handleInvite} className="flex flex-wrap items-end gap-3">
                  <div className="flex-1 min-w-[220px]">
                    <label className="mb-1 block text-xs font-medium text-gray-400">Email address</label>
                    <input type="email" value={inviteEmail} onChange={(e) => setInviteEmail(e.target.value)}
                      placeholder="colleague@example.com" required
                      className="w-full rounded-lg border border-gray-700 bg-gray-800 px-3 py-2 text-sm text-white placeholder-gray-500 focus:border-teal-500 focus:outline-none" />
                  </div>
                  <div>
                    <label className="mb-1 block text-xs font-medium text-gray-400">Role</label>
                    <select value={inviteRole} onChange={(e) => setInviteRole(e.target.value)}
                      className="rounded-lg border border-gray-700 bg-gray-800 px-3 py-2 text-sm text-white focus:border-teal-500 focus:outline-none">
                      {ROLES.map((r) => <option key={r} value={r}>{r}</option>)}
                    </select>
                  </div>
                  <button type="submit" disabled={inviting}
                    className="rounded-lg bg-teal-600 px-4 py-2 text-sm font-medium text-white hover:bg-teal-500 disabled:opacity-50">
                    {inviting ? 'Sending...' : 'Invite'}
                  </button>
                </form>
              </div>
              {invitations.length > 0 && (
                <div className="border-t border-gray-800 px-6 py-4">
                  <p className="mb-3 text-xs font-medium uppercase tracking-wide text-gray-500">Pending Invitations</p>
                  <ul className="space-y-2">
                    {invitations.map((inv) => (
                      <li key={inv.id} className="flex items-center justify-between rounded-lg border border-gray-700/50 bg-gray-800/40 px-4 py-3">
                        <div className="flex items-center gap-3">
                          <Mail className="h-4 w-4 text-gray-500" />
                          <div>
                            <p className="text-sm text-white">{inv.email}</p>
                            <div className="flex items-center gap-2 text-xs text-gray-500">
                              <span className={`inline-flex rounded-full px-2 py-0.5 font-medium ${ROLE_BADGE[inv.role] ?? 'bg-gray-700 text-gray-300'}`}>{inv.role}</span>
                              <Clock className="h-3 w-3" />
                              <span>Expires {fmt(inv.expiresAt)}</span>
                            </div>
                          </div>
                        </div>
                        <button onClick={() => handleCancelInvite(inv.id)} className="text-xs text-gray-500 hover:text-red-400">Cancel</button>
                      </li>
                    ))}
                  </ul>
                </div>
              )}
            </div>
          )}

        </div>
      </div>
    </AppLayout>
  );
}

/**
 * /login — Email + password sign-in page.
 * Redirects to /accounting on success; shows inline error on failure.
 * Unauthenticated users land here via middleware or manual navigation.
 */

import { useState, FormEvent } from 'react';
import { useRouter } from 'next/router';
import Link from 'next/link';
import { BookOpen, Eye, EyeOff } from 'lucide-react';
import { useAuth } from '@/contexts/AuthContext';
import { LoadingSpinner } from '@/components/ui/LoadingSpinner';

export default function LoginPage() {
  const router = useRouter();
  const { login, error, clearError } = useAuth();

  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [submitting, setSubmitting] = useState(false);

  const returnTo =
    typeof router.query.returnTo === 'string' && router.query.returnTo.startsWith('/')
      ? router.query.returnTo
      : '/accounting';

  const handleSubmit = async (e: FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    clearError();
    setSubmitting(true);

    try {
      await login(email.trim().toLowerCase(), password);
      await router.push(returnTo);
    } catch {
      // Error is already set in AuthContext — no further action needed here
    } finally {
      setSubmitting(false);
    }
  };

  const isBusy = submitting;

  return (
    <div className="min-h-screen bg-gray-950 flex items-center justify-center px-4">
      <div className="w-full max-w-sm">

        {/* Logo */}
        <div className="flex flex-col items-center mb-8">
          <img src="/logo.png" alt="ISAFlow" className="h-16 w-auto brightness-0 invert mb-4" />
          <p className="text-sm text-gray-500 mt-1">Sign in to your account</p>
        </div>

        {/* Registration success banner */}
        {router.query.registered === '1' && (
          <div className="mb-4 px-3 py-2.5 bg-green-500/10 border border-green-500/30 rounded-lg">
            <p className="text-sm text-green-400">Account created successfully! Please sign in.</p>
          </div>
        )}

        {/* Card */}
        <div className="bg-gray-900 border border-gray-700 rounded-2xl p-6 shadow-xl">
          <form onSubmit={(e) => void handleSubmit(e)} noValidate>

            {/* Email */}
            <div className="mb-4">
              <label
                htmlFor="email"
                className="block text-xs font-medium text-gray-400 mb-1.5"
              >
                Email address
              </label>
              <input
                id="email"
                type="email"
                autoComplete="email"
                required
                value={email}
                onChange={e => { clearError(); setEmail(e.target.value); }}
                disabled={isBusy}
