// ISAFlow E2E QA Test Script
// Runs all 3 test flows using Playwright

const { chromium } = require('playwright');

const BASE_URL = 'https://app.isaflow.co.za';
const ADMIN_EMAIL = 'admin@isaflow.co.za';
const ADMIN_PASS = 'Admin123!';
const TIMESTAMP = Date.now();
const NEW_USER_EMAIL = `testnewco_${TIMESTAMP}@test.com`;
const INVITED_USER_EMAIL = `testinvited_${TIMESTAMP}@test.com`;
const EXISTING_INVITE_EMAIL = 'testinvite1@isaflow.co.za';

const results = [];
let inviteUrl = null;

function log(step, action, expected, actual, result, notes = '') {
  const r = { step, action, expected, actual, result, notes };
  results.push(r);
  const icon = result === 'PASS' ? '✓' : '✗';
  console.log(`[${icon}] Step ${step}: ${action}`);
  if (result === 'FAIL') {
    console.log(`    Expected: ${expected}`);
    console.log(`    Actual:   ${actual}`);
    if (notes) console.log(`    Notes:    ${notes}`);
  }
}

async function waitAndGet(page, timeout = 3000) {
  await page.waitForTimeout(timeout);
  return page.url();
}

async function loginAs(page, email, password) {
  await page.goto(`${BASE_URL}/login`);
  await page.waitForTimeout(2000);
  await page.fill('input[type="email"]', email);
  await page.fill('input[type="password"]', password);
  await page.click('button[type="submit"]');
  await page.waitForTimeout(4000);
  return page.url();
}

async function runTests() {
  const browser = await chromium.launch({
    headless: true,
    executablePath: undefined, // use playwright's bundled chromium
    args: ['--no-sandbox', '--disable-setuid-sandbox']
  });

  console.log('\n=== ISAFlow QA Test Suite ===\n');
  console.log(`Timestamp: ${TIMESTAMP}`);
  console.log(`New user email: ${NEW_USER_EMAIL}`);
  console.log(`Invited user email: ${INVITED_USER_EMAIL}`);
  console.log('');

  // ============================================================
  // FLOW 1: Invite existing user to a company
  // ============================================================
  console.log('--- FLOW 1: Invite existing user ---\n');

  const page1 = await browser.newPage();

  // Step 1: Login as admin
  try {
    const url = await loginAs(page1, ADMIN_EMAIL, ADMIN_PASS);
    if (url.includes('/accounting') || url.includes('/dashboard')) {
      log(1, 'Login as admin', '/accounting dashboard', url, 'PASS');
    } else {
      log(1, 'Login as admin', '/accounting dashboard', url, 'FAIL');
    }
  } catch (e) {
    log(1, 'Login as admin', '/accounting dashboard', 'Error', 'FAIL', e.message);
  }

  // Step 2: Navigate to User Access
  try {
    await page1.goto(`${BASE_URL}/accounting/user-access`);
    await page1.waitForTimeout(3000);
    const url = page1.url();
    const pageText = await page1.evaluate(() => document.body.innerText.substring(0, 2000));

    if (url.includes('user-access') && (pageText.toLowerCase().includes('user') || pageText.toLowerCase().includes('access') || pageText.toLowerCase().includes('invite'))) {
      log(2, 'Navigate to User Access', 'User access page loads', url, 'PASS', pageText.substring(0, 200));
    } else if (url.includes('login')) {
      log(2, 'Navigate to User Access', 'User access page loads', 'Redirected to login', 'FAIL');
    } else {
      log(2, 'Navigate to User Access', 'User access page loads', url, 'PASS', 'Page loaded - ' + pageText.substring(0, 100));
    }
  } catch (e) {
    log(2, 'Navigate to User Access', 'User access page loads', 'Error', 'FAIL', e.message);
  }

  // Step 3: Invite test user
  try {
    // Take screenshot to see current state
    await page1.screenshot({ path: '/home/hein/Workspace/IsaFlow/tmp/step3-before.png' });

    const pageText = await page1.evaluate(() => document.body.innerText);
    console.log('  Page text sample:', pageText.substring(0, 500));

    // Look for email input field
    const emailInputs = await page1.$$('input[type="email"], input[placeholder*="email" i], input[name*="email" i]');
    console.log(`  Found ${emailInputs.length} email input(s)`);

    if (emailInputs.length > 0) {
      // Find the one that's in an invite form (not a login form)
      let inviteEmailInput = null;
      for (const inp of emailInputs) {
        const visible = await inp.isVisible();
        if (visible) {
          inviteEmailInput = inp;
          break;
        }
      }

      if (inviteEmailInput) {
        await inviteEmailInput.fill(EXISTING_INVITE_EMAIL);

        // Look for role selector
        const roleSelects = await page1.$$('select, [role="combobox"], [data-testid*="role"]');
        console.log(`  Found ${roleSelects.length} selects/comboboxes`);

        // Try to set role to viewer
        for (const sel of roleSelects) {
          const visible = await sel.isVisible();
          if (visible) {
            const tagName = await sel.evaluate(el => el.tagName.toLowerCase());
            if (tagName === 'select') {
              await sel.selectOption({ label: 'Viewer' }).catch(() =>
                sel.selectOption({ value: 'viewer' }).catch(() =>
                  sel.selectOption({ index: 1 })
                )
              );
            }
            break;
          }
        }

        // Look for invite button
        const buttons = await page1.$$('button');
        let inviteBtn = null;
        for (const btn of buttons) {
          const text = await btn.evaluate(el => el.textContent.toLowerCase().trim());
          const visible = await btn.isVisible();
          if (visible && (text.includes('invite') || text.includes('add user') || text.includes('send'))) {
            inviteBtn = btn;
            console.log(`  Found invite button: "${text}"`);
            break;
          }
        }

        if (inviteBtn) {
          await inviteBtn.click();
          await page1.waitForTimeout(3000);

          // Take screenshot after click
          await page1.screenshot({ path: '/home/hein/Workspace/IsaFlow/tmp/step3-after.png' });

          const afterText = await page1.evaluate(() => document.body.innerText);
          console.log('  After invite text:', afterText.substring(0, 500));

          // Check for invite link
          const linkPattern = /https?:\/\/[^\s]+invite[^\s]*/gi;
          const matches = afterText.match(linkPattern);

          if (matches) {
            inviteUrl = matches[0];
            console.log('  Found invite URL:', inviteUrl);
          }

          // Look for copy button
          const copyBtns = await page1.$$('button');
          for (const btn of copyBtns) {
            const text = await btn.evaluate(el => el.textContent.toLowerCase().trim());
            const visible = await btn.isVisible();
            if (visible && (text.includes('copy') || text.includes('link'))) {
              console.log(`  Found copy button: "${text}"`);
              break;
            }
          }

          const success = afterText.toLowerCase().includes('invited') ||
                          afterText.toLowerCase().includes('added') ||
                          afterText.toLowerCase().includes('pending') ||
                          afterText.toLowerCase().includes('success') ||
                          afterText.toLowerCase().includes(EXISTING_INVITE_EMAIL.toLowerCase());

          log(3, `Invite ${EXISTING_INVITE_EMAIL} as viewer`, 'Invitation appears in list',
            success ? 'Invitation shown' : 'No clear confirmation',
            success ? 'PASS' : 'FAIL',
            afterText.substring(0, 300));
        } else {
          log(3, `Invite ${EXISTING_INVITE_EMAIL} as viewer`, 'Invite button found', 'No invite button found', 'FAIL', pageText.substring(0, 300));
        }
      } else {
        log(3, `Invite ${EXISTING_INVITE_EMAIL} as viewer`, 'Email input found', 'No visible email input', 'FAIL', pageText.substring(0, 300));
      }
    } else {
      // Maybe need to find the invite form differently
      const html = await page1.evaluate(() => document.body.innerHTML.substring(0, 3000));
      log(3, `Invite ${EXISTING_INVITE_EMAIL} as viewer`, 'Email input in invite form', 'No email input found', 'FAIL', pageText.substring(0, 300));
    }
  } catch (e) {
    log(3, `Invite ${EXISTING_INVITE_EMAIL} as viewer`, 'Invitation sent', 'Error', 'FAIL', e.message);
  }

  // Step 4: Verify invitation
  log(4, 'Verify invitation (Flow 1)', 'Invitation created',
    results.find(r => r.step === 3)?.result === 'PASS' ? 'Invitation created successfully' : 'Failed to create invitation',
    results.find(r => r.step === 3)?.result === 'PASS' ? 'PASS' : 'FAIL');

  await page1.close();

  // ============================================================
  // FLOW 2: New user registration + new company
  // ============================================================
  console.log('\n--- FLOW 2: New user + new company ---\n');

  const page2 = await browser.newPage();

  // Step 5: Register new user
  try {
    await page2.goto(`${BASE_URL}/register`);
    await page2.waitForTimeout(2000);

    const url = page2.url();
    const pageText = await page2.evaluate(() => document.body.innerText);
    console.log('  Register page URL:', url);
    console.log('  Register page text:', pageText.substring(0, 300));

    await page2.screenshot({ path: '/home/hein/Workspace/IsaFlow/tmp/step5-register.png' });

    // Fill in registration form
    // First name
    const firstNameInputs = await page2.$$('input[name*="first" i], input[placeholder*="first" i], input[id*="first" i]');
    if (firstNameInputs.length > 0) await firstNameInputs[0].fill('Test');

    // Last name
    const lastNameInputs = await page2.$$('input[name*="last" i], input[placeholder*="last" i], input[id*="last" i]');
    if (lastNameInputs.length > 0) await lastNameInputs[0].fill('NewCompany');

    // Email
    const emailInputs = await page2.$$('input[type="email"], input[name*="email" i]');
    if (emailInputs.length > 0) await emailInputs[0].fill(NEW_USER_EMAIL);

    // Password
    const passwordInputs = await page2.$$('input[type="password"]');
    if (passwordInputs.length >= 1) await passwordInputs[0].fill('TestPass123!');
    if (passwordInputs.length >= 2) await passwordInputs[1].fill('TestPass123!');

    await page2.screenshot({ path: '/home/hein/Workspace/IsaFlow/tmp/step5-filled.png' });

    // Click register button
    const buttons = await page2.$$('button[type="submit"], button');
    for (const btn of buttons) {
      const text = await btn.evaluate(el => el.textContent.toLowerCase().trim());
      const visible = await btn.isVisible();
      if (visible && (text.includes('register') || text.includes('sign up') || text.includes('create account') || text.includes('create'))) {
        console.log(`  Clicking register button: "${text}"`);
        await btn.click();
        break;
      }
    }

    await page2.waitForTimeout(4000);
    const afterUrl = page2.url();
    const afterText = await page2.evaluate(() => document.body.innerText);

    await page2.screenshot({ path: '/home/hein/Workspace/IsaFlow/tmp/step5-after.png' });
    console.log('  After registration URL:', afterUrl);
    console.log('  After registration text:', afterText.substring(0, 500));

    const success = afterUrl.includes('/login') ||
                    afterText.toLowerCase().includes('success') ||
                    afterText.toLowerCase().includes('verify') ||
                    afterText.toLowerCase().includes('check your email') ||
                    afterText.toLowerCase().includes('created');

    log(5, `Register new user ${NEW_USER_EMAIL}`, 'Redirect to login with success', afterUrl,
      success ? 'PASS' : 'FAIL', afterText.substring(0, 200));

  } catch (e) {
    log(5, `Register new user ${NEW_USER_EMAIL}`, 'Redirect to login with success', 'Error', 'FAIL', e.message);
  }

  // Step 6: Login as new user
  try {
    const url = await loginAs(page2, NEW_USER_EMAIL, 'TestPass123!');
    await page2.screenshot({ path: '/home/hein/Workspace/IsaFlow/tmp/step6-after-login.png' });

    const pageText = await page2.evaluate(() => document.body.innerText);
    console.log('  After new user login URL:', url);
    console.log('  After new user login text:', pageText.substring(0, 500));

    if (url.includes('/onboarding')) {
      log(6, 'Login as new user', '/onboarding page', url, 'PASS');
    } else if (url.includes('/login')) {
      // Check if there's an error
      const errorText = await page2.evaluate(() => {
        const errors = document.querySelectorAll('[role="alert"], .error, .alert-error, [class*="error"]');
        return Array.from(errors).map(e => e.textContent).join(' ');
      });
      log(6, 'Login as new user', '/onboarding page', `Still on login - ${errorText || 'unknown error'}`, 'FAIL', pageText.substring(0, 300));
    } else {
      log(6, 'Login as new user', '/onboarding page', url, 'FAIL', 'Expected /onboarding, got: ' + url);
    }
  } catch (e) {
    log(6, 'Login as new user', '/onboarding redirect', 'Error', 'FAIL', e.message);
  }

  // Step 7: Complete onboarding
  try {
    const currentUrl = page2.url();
    if (!currentUrl.includes('/onboarding')) {
      log(7, 'Complete onboarding', '/accounting after setup', 'Skipped - not on onboarding page', 'FAIL', `Current URL: ${currentUrl}`);
    } else {
      // Fill company name
      await page2.waitForTimeout(2000);
      await page2.screenshot({ path: '/home/hein/Workspace/IsaFlow/tmp/step7-onboarding.png' });

      const pageText = await page2.evaluate(() => document.body.innerText);
      console.log('  Onboarding page text:', pageText.substring(0, 500));

      // Fill company name
      const companyInputs = await page2.$$('input[name*="company" i], input[placeholder*="company" i], input[id*="company" i], input[name*="name" i]');
      console.log(`  Found ${companyInputs.length} company name inputs`);

      if (companyInputs.length > 0) {
        await companyInputs[0].fill('Test Company E2E');
      }

      // Click continue/next buttons repeatedly
      let stepCount = 0;
      let completed = false;

      while (stepCount < 10 && !completed) {
        await page2.screenshot({ path: `/home/hein/Workspace/IsaFlow/tmp/step7-onboarding-${stepCount}.png` });

        const currentStepUrl = page2.url();
        const stepText = await page2.evaluate(() => document.body.innerText);
        console.log(`  Onboarding step ${stepCount} URL: ${currentStepUrl}`);

        if (!currentStepUrl.includes('/onboarding')) {
          if (currentStepUrl.includes('/accounting')) {
            completed = true;
            break;
          }
          break;
        }

        // Find and click Continue/Next/Complete button
        const buttons = await page2.$$('button');
        let clicked = false;
        for (const btn of buttons) {
          const text = await btn.evaluate(el => el.textContent.toLowerCase().trim());
          const visible = await btn.isVisible();
          const disabled = await btn.evaluate(el => el.disabled);
          if (visible && !disabled && (
            text.includes('continue') ||
            text.includes('next') ||
            text.includes('complete') ||
            text.includes('finish') ||
            text.includes('setup') ||
            text.includes('create')
          )) {
            console.log(`  Clicking button: "${text}"`);
            await btn.click();
            clicked = true;
            break;
          }
        }

        if (!clicked) {
          console.log('  No continue button found, onboarding might be stuck');
          break;
        }

        await page2.waitForTimeout(2000);
        stepCount++;

        const newUrl = page2.url();
        if (newUrl.includes('/accounting') && !newUrl.includes('/onboarding')) {
          completed = true;
          break;
        }
      }

      const finalUrl = page2.url();
      await page2.screenshot({ path: '/home/hein/Workspace/IsaFlow/tmp/step7-final.png' });
      console.log('  Final URL after onboarding:', finalUrl);

      if (finalUrl.includes('/accounting')) {
        log(7, 'Complete onboarding wizard', '/accounting dashboard', finalUrl, 'PASS');
      } else {
        const finalText = await page2.evaluate(() => document.body.innerText);
        log(7, 'Complete onboarding wizard', '/accounting dashboard', finalUrl, 'FAIL', finalText.substring(0, 300));
      }
    }
  } catch (e) {
    log(7, 'Complete onboarding wizard', '/accounting dashboard', 'Error', 'FAIL', e.message);
  }

  await page2.close();

  // ============================================================
  // FLOW 3: New user via invitation link
  // ============================================================
  console.log('\n--- FLOW 3: New user via invitation ---\n');

  const page3 = await browser.newPage();

  // Step 8: Login as admin
  try {
    const url = await loginAs(page3, ADMIN_EMAIL, ADMIN_PASS);
    if (url.includes('/accounting') || url.includes('/dashboard')) {
      log(8, 'Login as admin (Flow 3)', '/accounting dashboard', url, 'PASS');
    } else {
      log(8, 'Login as admin (Flow 3)', '/accounting dashboard', url, 'FAIL');
    }
  } catch (e) {
    log(8, 'Login as admin (Flow 3)', '/accounting dashboard', 'Error', 'FAIL', e.message);
  }

  // Step 9: Create invitation for invited user
  let capturedInviteUrl = null;
  try {
    await page3.goto(`${BASE_URL}/accounting/user-access`);
    await page3.waitForTimeout(3000);

    await page3.screenshot({ path: '/home/hein/Workspace/IsaFlow/tmp/step9-user-access.png' });

    const pageText = await page3.evaluate(() => document.body.innerText);
    console.log('  User access page text:', pageText.substring(0, 500));

    // Fill in invite email
    const emailInputs = await page3.$$('input[type="email"], input[placeholder*="email" i], input[name*="email" i]');
    let inviteEmailInput = null;
    for (const inp of emailInputs) {
      const visible = await inp.isVisible();
      if (visible) {
        inviteEmailInput = inp;
        break;
      }
    }

    if (inviteEmailInput) {
      await inviteEmailInput.fill(INVITED_USER_EMAIL);

      // Set role to manager
      const roleSelects = await page3.$$('select');
      for (const sel of roleSelects) {
        const visible = await sel.isVisible();
        if (visible) {
          await sel.selectOption({ label: 'Manager' }).catch(() =>
            sel.selectOption({ value: 'manager' }).catch(() =>
              sel.selectOption({ index: 2 }).catch(() => null)
            )
          );
          break;
        }
      }

      // Also try combobox/dropdown
      const roleCombo = await page3.$$('[role="combobox"]');
      for (const combo of roleCombo) {
        const visible = await combo.isVisible();
        if (visible) {
          await combo.click();
          await page3.waitForTimeout(500);
          const options = await page3.$$('[role="option"]');
          for (const opt of options) {
            const optText = await opt.evaluate(el => el.textContent.toLowerCase());
            if (optText.includes('manager')) {
              await opt.click();
              break;
            }
          }
          break;
        }
      }

      // Click invite button
      const buttons = await page3.$$('button');
      for (const btn of buttons) {
        const text = await btn.evaluate(el => el.textContent.toLowerCase().trim());
        const visible = await btn.isVisible();
        if (visible && (text.includes('invite') || text.includes('add user') || text.includes('send'))) {
          console.log(`  Clicking invite button: "${text}"`);
          await btn.click();
          break;
        }
      }

      await page3.waitForTimeout(3000);
      await page3.screenshot({ path: '/home/hein/Workspace/IsaFlow/tmp/step9-after-invite.png' });

      const afterText = await page3.evaluate(() => document.body.innerText);
      console.log('  After invite text:', afterText.substring(0, 800));

      // Try to find invite link in the page
      const allLinks = await page3.$$('a[href*="invite"], a[href*="token"]');
      for (const link of allLinks) {
        const href = await link.evaluate(el => el.href);
        console.log('  Found invite link:', href);
        capturedInviteUrl = href;
        break;
      }

      // Also check clipboard via copy button
      const copyBtns = await page3.$$('button');
      for (const btn of copyBtns) {
        const text = await btn.evaluate(el => el.textContent.toLowerCase().trim());
        const visible = await btn.isVisible();
        if (visible && (text.includes('copy') || text.includes('link'))) {
          console.log(`  Found copy button: "${text}"`);
          // Grant clipboard permissions and click
          await btn.click();
          await page3.waitForTimeout(500);
          break;
        }
      }

      // Try to get invite URL from page HTML/attributes
      const inviteData = await page3.evaluate(() => {
        // Look for any element containing invite URL
        const allText = document.body.innerHTML;
        const match = allText.match(/https?:\/\/[^"'\s>]*(?:invite|token)[^"'\s>]*/gi);
        return match ? match[0] : null;
      });

      if (inviteData) {
        capturedInviteUrl = inviteData;
        console.log('  Captured invite URL from HTML:', capturedInviteUrl);
      }

      // If no URL yet, check for input fields with URL
      if (!capturedInviteUrl) {
        const urlInputs = await page3.$$('input[readonly], input[value*="invite"], input[value*="token"]');
        for (const inp of urlInputs) {
          const val = await inp.evaluate(el => el.value);
          if (val && (val.includes('invite') || val.includes('token'))) {
            capturedInviteUrl = val;
            console.log('  Found invite URL in input:', capturedInviteUrl);
            break;
          }
        }
      }

      // Try API approach - check network requests for invite URL
      const success = afterText.toLowerCase().includes('invited') ||
                      afterText.toLowerCase().includes('pending') ||
                      afterText.toLowerCase().includes('success') ||
                      afterText.toLowerCase().includes(INVITED_USER_EMAIL.toLowerCase());

      log(9, `Invite ${INVITED_USER_EMAIL} as manager`, 'Pending invitation with copy link',
        capturedInviteUrl ? `Invite URL: ${capturedInviteUrl}` : (success ? 'Invited but no URL found' : 'No confirmation'),
        success || capturedInviteUrl ? 'PASS' : 'FAIL',
        afterText.substring(0, 300));
    } else {
      log(9, `Invite ${INVITED_USER_EMAIL} as manager`, 'Email input found', 'No visible email input', 'FAIL', pageText.substring(0, 300));
    }
  } catch (e) {
    log(9, `Invite ${INVITED_USER_EMAIL} as manager`, 'Pending invitation', 'Error', 'FAIL', e.message);
  }

  // Step 10: Open invite link
  if (!capturedInviteUrl) {
    // Try to get invite URL via the API
    try {
      const apiResponse = await page3.evaluate(async (email) => {
        const res = await fetch('/api/invitations?email=' + email);
        if (res.ok) return res.json();
        return null;
      }, INVITED_USER_EMAIL);
      console.log('  API invitation response:', JSON.stringify(apiResponse));
    } catch (e) {
      console.log('  Could not fetch via API:', e.message);
    }

    log(10, 'Open invite link', 'Invite landing page with company/role info', 'No invite URL to open', 'FAIL', 'Invite URL was not captured in step 9');
    log(11, 'Register via invitation', 'Register page with pre-filled email', 'Skipped - no invite URL', 'FAIL');
    log(12, 'Login as invited user', '/accounting (not /onboarding)', 'Skipped - no invite URL', 'FAIL');
  } else {
    // Step 10: Open invite link
    const page4 = await browser.newPage();
    try {
      await page4.goto(capturedInviteUrl);
      await page4.waitForTimeout(3000);

      const url = page4.url();
      const pageText = await page4.evaluate(() => document.body.innerText);
      await page4.screenshot({ path: '/home/hein/Workspace/IsaFlow/tmp/step10-invite-landing.png' });

      console.log('  Invite landing URL:', url);
      console.log('  Invite landing text:', pageText.substring(0, 500));

      const hasCompany = pageText.toLowerCase().includes('company') || pageText.toLowerCase().includes('isaflow');
      const hasRole = pageText.toLowerCase().includes('manager') || pageText.toLowerCase().includes('role');
      const hasButtons = pageText.toLowerCase().includes('sign in') || pageText.toLowerCase().includes('create account');

      if (hasButtons) {
        log(10, 'Open invite link', 'Landing page with company/role and sign in/create buttons', url, 'PASS', pageText.substring(0, 300));
      } else {
        log(10, 'Open invite link', 'Landing page with company/role and sign in/create buttons', url, 'FAIL', pageText.substring(0, 300));
      }

      // Step 11: Register via invitation - click Create Account
      try {
        const buttons = await page4.$$('button, a');
        for (const btn of buttons) {
