// ISAFlow E2E QA Test Script
// Runs all 3 test flows using Playwright

const { chromium } = require('playwright');

const BASE_URL = 'https://app.isaflow.co.za';
const ADMIN_EMAIL = 'admin@isaflow.co.za';
const ADMIN_PASS = 'Admin123!';
const TIMESTAMP = Date.now();
const NEW_USER_EMAIL = `testnewco_${TIMESTAMP}@test.com`;
const INVITED_USER_EMAIL = `testinvited_${TIMESTAMP}@test.com`;
const EXISTING_INVITE_EMAIL = 'testinvite1@isaflow.co.za';

const results = [];
let inviteUrl = null;

function log(step, action, expected, actual, result, notes = '') {
  const r = { step, action, expected, actual, result, notes };
  results.push(r);
  const icon = result === 'PASS' ? '✓' : '✗';
  console.log(`[${icon}] Step ${step}: ${action}`);
  if (result === 'FAIL') {
    console.log(`    Expected: ${expected}`);
    console.log(`    Actual:   ${actual}`);
    if (notes) console.log(`    Notes:    ${notes}`);
  }
}

async function waitAndGet(page, timeout = 3000) {
  await page.waitForTimeout(timeout);
  return page.url();
}

async function loginAs(page, email, password) {
  await page.goto(`${BASE_URL}/login`);
  await page.waitForTimeout(2000);
  await page.fill('input[type="email"]', email);
  await page.fill('input[type="password"]', password);
  await page.click('button[type="submit"]');
  await page.waitForTimeout(4000);
  return page.url();
}

async function runTests() {
  const browser = await chromium.launch({
    headless: true,
    executablePath: undefined, // use playwright's bundled chromium
    args: ['--no-sandbox', '--disable-setuid-sandbox']
  });

  console.log('\n=== ISAFlow QA Test Suite ===\n');
  console.log(`Timestamp: ${TIMESTAMP}`);
  console.log(`New user email: ${NEW_USER_EMAIL}`);
  console.log(`Invited user email: ${INVITED_USER_EMAIL}`);
  console.log('');

  // ============================================================
  // FLOW 1: Invite existing user to a company
  // ============================================================
  console.log('--- FLOW 1: Invite existing user ---\n');

  const page1 = await browser.newPage();

  // Step 1: Login as admin
  try {
    const url = await loginAs(page1, ADMIN_EMAIL, ADMIN_PASS);
    if (url.includes('/accounting') || url.includes('/dashboard')) {
      log(1, 'Login as admin', '/accounting dashboard', url, 'PASS');
    } else {
      log(1, 'Login as admin', '/accounting dashboard', url, 'FAIL');
    }
  } catch (e) {
    log(1, 'Login as admin', '/accounting dashboard', 'Error', 'FAIL', e.message);
  }

  // Step 2: Navigate to User Access
  try {
    await page1.goto(`${BASE_URL}/accounting/user-access`);
    await page1.waitForTimeout(3000);
    const url = page1.url();
    const pageText = await page1.evaluate(() => document.body.innerText.substring(0, 2000));

    if (url.includes('user-access') && (pageText.toLowerCase().includes('user') || pageText.toLowerCase().includes('access') || pageText.toLowerCase().includes('invite'))) {
      log(2, 'Navigate to User Access', 'User access page loads', url, 'PASS', pageText.substring(0, 200));
    } else if (url.includes('login')) {
      log(2, 'Navigate to User Access', 'User access page loads', 'Redirected to login', 'FAIL');
    } else {
      log(2, 'Navigate to User Access', 'User access page loads', url, 'PASS', 'Page loaded - ' + pageText.substring(0, 100));
    }
  } catch (e) {
    log(2, 'Navigate to User Access', 'User access page loads', 'Error', 'FAIL', e.message);
  }

  // Step 3: Invite test user
  try {
    // Take screenshot to see current state
    await page1.screenshot({ path: '/home/hein/Workspace/IsaFlow/tmp/step3-before.png' });

    const pageText = await page1.evaluate(() => document.body.innerText);
    console.log('  Page text sample:', pageText.substring(0, 500));

    // Look for email input field
    const emailInputs = await page1.$$('input[type="email"], input[placeholder*="email" i], input[name*="email" i]');
    console.log(`  Found ${emailInputs.length} email input(s)`);

    if (emailInputs.length > 0) {
      // Find the one that's in an invite form (not a login form)
      let inviteEmailInput = null;
      for (const inp of emailInputs) {
        const visible = await inp.isVisible();
        if (visible) {
          inviteEmailInput = inp;
          break;
        }
      }

      if (inviteEmailInput) {
        await inviteEmailInput.fill(EXISTING_INVITE_EMAIL);

        // Look for role selector
        const roleSelects = await page1.$$('select, [role="combobox"], [data-testid*="role"]');
        console.log(`  Found ${roleSelects.length} selects/comboboxes`);

        // Try to set role to viewer
        for (const sel of roleSelects) {
          const visible = await sel.isVisible();
          if (visible) {
            const tagName = await sel.evaluate(el => el.tagName.toLowerCase());
            if (tagName === 'select') {
              await sel.selectOption({ label: 'Viewer' }).catch(() =>
                sel.selectOption({ value: 'viewer' }).catch(() =>
                  sel.selectOption({ index: 1 })
                )
              );
            }
            break;
          }
        }

        // Look for invite button
        const buttons = await page1.$$('button');
        let inviteBtn = null;
        for (const btn of buttons) {
          const text = await btn.evaluate(el => el.textContent.toLowerCase().trim());
          const visible = await btn.isVisible();
          if (visible && (text.includes('invite') || text.includes('add user') || text.includes('send'))) {
            inviteBtn = btn;
            console.log(`  Found invite button: "${text}"`);
            break;
          }
        }

        if (inviteBtn) {
          await inviteBtn.click();
          await page1.waitForTimeout(3000);

          // Take screenshot after click
          await page1.screenshot({ path: '/home/hein/Workspace/IsaFlow/tmp/step3-after.png' });

          const afterText = await page1.evaluate(() => document.body.innerText);
          console.log('  After invite text:', afterText.substring(0, 500));

          // Check for invite link
          const linkPattern = /https?:\/\/[^\s]+invite[^\s]*/gi;
          const matches = afterText.match(linkPattern);

          if (matches) {
            inviteUrl = matches[0];
            console.log('  Found invite URL:', inviteUrl);
          }

          // Look for copy button
          const copyBtns = await page1.$$('button');
          for (const btn of copyBtns) {
            const text = await btn.evaluate(el => el.textContent.toLowerCase().trim());
            const visible = await btn.isVisible();
            if (visible && (text.includes('copy') || text.includes('link'))) {
              console.log(`  Found copy button: "${text}"`);
              break;
            }
          }

          const success = afterText.toLowerCase().includes('invited') ||
                          afterText.toLowerCase().includes('added') ||
                          afterText.toLowerCase().includes('pending') ||
                          afterText.toLowerCase().includes('success') ||
                          afterText.toLowerCase().includes(EXISTING_INVITE_EMAIL.toLowerCase());

          log(3, `Invite ${EXISTING_INVITE_EMAIL} as viewer`, 'Invitation appears in list',
            success ? 'Invitation shown' : 'No clear confirmation',
            success ? 'PASS' : 'FAIL',
            afterText.substring(0, 300));
        } else {
          log(3, `Invite ${EXISTING_INVITE_EMAIL} as viewer`, 'Invite button found', 'No invite button found', 'FAIL', pageText.substring(0, 300));
