      if (f.notes) console.log(`  Notes:    ${f.notes.substring(0, 200)}`);
      console.log('');
    }
  }

  // Save results as JSON
  const fs = require('fs');
  fs.writeFileSync('/home/hein/Workspace/IsaFlow/tmp/qa-results.json', JSON.stringify({
    timestamp: TIMESTAMP,
    results,
    summary: { passed, total, flow1Pass, flow2Pass, flow3Pass }
  }, null, 2));

  console.log('Results saved to: /home/hein/Workspace/IsaFlow/tmp/qa-results.json');
  console.log('Screenshots saved to: /home/hein/Workspace/IsaFlow/tmp/');
}

runTests().catch(e => {
  console.error('Fatal error:', e);
  process.exit(1);
});

