// ISAFlow E2E QA Test Script v2
// Fixes: login flow, button detection, invite URL capture

const { chromium } = require('playwright');

const BASE_URL = 'https://app.isaflow.co.za';
const ADMIN_EMAIL = 'admin@isaflow.co.za';
const ADMIN_PASS = 'Admin123!';
const TIMESTAMP = Date.now();
const NEW_USER_EMAIL = `testnewco_${TIMESTAMP}@test.com`;
const INVITED_USER_EMAIL = `testinvited_${TIMESTAMP}@test.com`;
const EXISTING_INVITE_EMAIL = 'testinvite1@isaflow.co.za';

const results = [];

function log(step, action, expected, actual, result, notes = '') {
  const r = { step, action, expected, actual, result, notes };
  results.push(r);
  const icon = result === 'PASS' ? '✓' : '✗';
  console.log(`[${icon}] Step ${step}: ${action} -> ${result}`);
  if (result === 'FAIL') {
    console.log(`    Expected: ${expected}`);
    console.log(`    Actual:   ${actual}`);
    if (notes) console.log(`    Notes:    ${notes.substring(0, 200)}`);
  } else {
    console.log(`    Actual:   ${actual.substring ? actual.substring(0, 100) : actual}`);
  }
}

async function loginAs(page, email, password) {
  await page.goto(`${BASE_URL}/login`);
  await page.waitForLoadState('networkidle');

  // Wait for form
  await page.waitForSelector('input[type="email"]', { timeout: 10000 });

  // Clear and fill email
  await page.click('input[type="email"]');
  await page.fill('input[type="email"]', '');
  await page.type('input[type="email"]', email, { delay: 50 });

  // Clear and fill password
  await page.click('input[type="password"]');
  await page.fill('input[type="password"]', '');
  await page.type('input[type="password"]', password, { delay: 50 });

  // Verify values
  const emailVal = await page.$eval('input[type="email"]', el => el.value);
  const passVal = await page.$eval('input[type="password"]', el => el.value);
  console.log(`  Filled email: "${emailVal}", password length: ${passVal.length}`);

  // Click submit
  await page.click('button[type="submit"]');

  // Wait for navigation
  try {
    await page.waitForNavigation({ timeout: 8000 });
  } catch (e) {
    // May not navigate if there's an error
  }
  await page.waitForTimeout(2000);

  const url = page.url();
  const text = await page.evaluate(() => document.body.innerText.substring(0, 500));
  console.log(`  Post-login URL: ${url}`);
  if (url.includes('/login')) {
    console.log(`  Still on login - page text: ${text.substring(0, 200)}`);
  }
  return { url, text };
}

async function clickButtonByText(page, ...textOptions) {
  const buttons = await page.$$('button, [role="button"]');
  for (const btn of buttons) {
    const text = await btn.evaluate(el => el.textContent.toLowerCase().trim());
    const visible = await btn.isVisible();
    const disabled = await btn.evaluate(el => el.disabled || el.getAttribute('disabled') !== null);
    for (const opt of textOptions) {
      if (visible && !disabled && text.includes(opt.toLowerCase())) {
        console.log(`  Clicking button: "${text}"`);
        await btn.click();
        return text;
      }
    }
  }
  return null;
}

async function getInviteUrlFromPage(page) {
  // Check input[readonly] fields
  const readonlyInputs = await page.$$('input[readonly]');
  for (const inp of readonlyInputs) {
    const val = await inp.evaluate(el => el.value);
    if (val && val.startsWith('http') && (val.includes('invite') || val.includes('token'))) {
      return val;
    }
  }

  // Check HTML for URLs containing invite/token
  const inviteUrl = await page.evaluate(() => {
    const html = document.body.innerHTML;
    const match = html.match(/https?:\/\/[^"'\s<>]*(?:invite|token)[^"'\s<>]*/gi);
    return match ? match[0] : null;
  });
  if (inviteUrl) return inviteUrl;

  // Check all visible text for URLs
  const textUrl = await page.evaluate(() => {
    const text = document.body.innerText;
    const match = text.match(/https?:\/\/[^\s]*(invite|token)[^\s]*/gi);
    return match ? match[0] : null;
  });
  return textUrl;
}

async function runTests() {
  const browser = await chromium.launch({
    headless: true,
    args: ['--no-sandbox', '--disable-setuid-sandbox', '--disable-web-security']
  });

  console.log('\n=== ISAFlow QA Test Suite v2 ===\n');
  console.log(`Date: ${new Date().toISOString().split('T')[0]}`);
  console.log(`Timestamp: ${TIMESTAMP}`);
  console.log(`New user email: ${NEW_USER_EMAIL}`);
  console.log(`Invited user email: ${INVITED_USER_EMAIL}`);
  console.log('');

  // ============================================================
  // FLOW 1: Invite existing user to a company
  // ============================================================
  console.log('--- FLOW 1: Invite existing user ---\n');

  const page1 = await browser.newPage();
  // Listen for console errors
  page1.on('console', msg => {
    if (msg.type() === 'error') console.log(`  [console.error] ${msg.text()}`);
  });

  // Step 1: Login as admin
  try {
    const { url, text } = await loginAs(page1, ADMIN_EMAIL, ADMIN_PASS);
    if (url.includes('/accounting') || url.includes('/dashboard')) {
      log(1, 'Login as admin', '/accounting dashboard', url, 'PASS');
    } else if (url.includes('/onboarding')) {
      log(1, 'Login as admin', '/accounting dashboard', url, 'FAIL', 'Admin redirected to onboarding - may have no company');
    } else {
      log(1, 'Login as admin', '/accounting dashboard', url, 'FAIL', text.substring(0, 200));
    }
  } catch (e) {
    log(1, 'Login as admin', '/accounting dashboard', 'Error', 'FAIL', e.message);
  }

  // Step 2: Navigate to User Access
  try {
    await page1.goto(`${BASE_URL}/accounting/user-access`);
    await page1.waitForLoadState('networkidle');
    await page1.waitForTimeout(2000);
    const url = page1.url();
    await page1.screenshot({ path: '/home/hein/Workspace/IsaFlow/tmp/v2-step2-user-access.png' });

    if (url.includes('/login')) {
      log(2, 'Navigate to User Access', 'User access page loads', 'Redirected to login - auth failed', 'FAIL');
    } else {
      const text = await page1.evaluate(() => document.body.innerText.substring(0, 500));
      log(2, 'Navigate to User Access', 'User access page loads', url, 'PASS', text.substring(0, 150));
    }
  } catch (e) {
    log(2, 'Navigate to User Access', 'User access page loads', 'Error', 'FAIL', e.message);
  }

  // Step 3: Invite test user
  let step3Pass = false;
  let capturedInviteUrl1 = null;
  try {
    if (results.find(r => r.step === 2)?.result === 'FAIL') {
      log(3, `Invite ${EXISTING_INVITE_EMAIL} as viewer`, 'Invitation appears', 'Skipped - not on user-access page', 'FAIL');
    } else {
      const pageHtml = await page1.evaluate(() => document.body.innerHTML);
      const pageText = await page1.evaluate(() => document.body.innerText);
      console.log('  User access page text:', pageText.substring(0, 600));

      // Look for all inputs on the page
      const inputs = await page1.$$('input');
      for (const inp of inputs) {
        const type = await inp.evaluate(el => el.type);
        const placeholder = await inp.evaluate(el => el.placeholder);
        const name = await inp.evaluate(el => el.name);
        const visible = await inp.isVisible();
        console.log(`  Input: type=${type} placeholder="${placeholder}" name="${name}" visible=${visible}`);
      }

      // Try to find any form with email
      const emailInput = page1.locator('input[type="email"]').first();
      const emailVisible = await emailInput.isVisible().catch(() => false);
      console.log(`  Email input visible: ${emailVisible}`);

      if (emailVisible) {
        await emailInput.fill(EXISTING_INVITE_EMAIL);

        // Find role select
        const roleSelectors = [
          'select[name*="role" i]',
          'select',
          '[role="combobox"]',
          'input[name*="role" i]'
        ];

        for (const selector of roleSelectors) {
          const el = page1.locator(selector).first();
          const visible = await el.isVisible().catch(() => false);
          if (visible) {
            const tagName = await el.evaluate(el => el.tagName.toLowerCase()).catch(() => '');
            console.log(`  Found role selector: ${selector}, tagName: ${tagName}`);
            if (tagName === 'select') {
              try { await el.selectOption('viewer'); } catch (e) {
              try { await el.selectOption('Viewer'); } catch (e) {
              try { await el.selectOption({ index: 1 }); } catch (e) {}}}
            }
            break;
          }
        }

        const clicked = await clickButtonByText(page1, 'invite', 'add user', 'send invite', 'send');
        if (clicked) {
          await page1.waitForTimeout(3000);
          await page1.screenshot({ path: '/home/hein/Workspace/IsaFlow/tmp/v2-step3-after-invite.png' });

          const afterText = await page1.evaluate(() => document.body.innerText);
          console.log('  After invite text:', afterText.substring(0, 600));

          capturedInviteUrl1 = await getInviteUrlFromPage(page1);
          console.log('  Captured invite URL (flow 1):', capturedInviteUrl1);

          const success = afterText.toLowerCase().includes('invited') ||
                          afterText.toLowerCase().includes('pending') ||
                          afterText.toLowerCase().includes('success') ||
                          afterText.toLowerCase().includes(EXISTING_INVITE_EMAIL.toLowerCase()) ||
                          afterText.toLowerCase().includes('added');

          step3Pass = success;
          log(3, `Invite ${EXISTING_INVITE_EMAIL} as viewer`, 'Invitation appears',
            success ? `Confirmed: ${afterText.substring(0, 100)}` : 'No confirmation found',
            success ? 'PASS' : 'FAIL', afterText.substring(0, 300));
        } else {
          log(3, `Invite ${EXISTING_INVITE_EMAIL} as viewer`, 'Invite button clicked', 'No invite button found', 'FAIL', pageText.substring(0, 300));
        }
      } else {
        // Maybe there's a different UI - look for "Invite User" button first
        const inviteBtn = await clickButtonByText(page1, 'invite user', 'add member', 'add user', 'invite');
        if (inviteBtn) {
          await page1.waitForTimeout(1000);
          await page1.screenshot({ path: '/home/hein/Workspace/IsaFlow/tmp/v2-step3-modal.png' });
          // Now fill the modal
          const modalEmail = page1.locator('input[type="email"]').first();
          const modalVisible = await modalEmail.isVisible().catch(() => false);
          if (modalVisible) {
            await modalEmail.fill(EXISTING_INVITE_EMAIL);
            // Try to submit
            const submitted = await clickButtonByText(page1, 'invite', 'send', 'confirm', 'add');
            if (submitted) {
              await page1.waitForTimeout(3000);
              const afterText = await page1.evaluate(() => document.body.innerText);
              log(3, `Invite ${EXISTING_INVITE_EMAIL} as viewer`, 'Invitation appears',
                'Submitted via modal', 'PASS', afterText.substring(0, 200));
              step3Pass = true;
            } else {
              log(3, `Invite ${EXISTING_INVITE_EMAIL} as viewer`, 'Invite form submitted', 'Could not submit modal', 'FAIL');
            }
          } else {
            log(3, `Invite ${EXISTING_INVITE_EMAIL} as viewer`, 'Email input in modal', 'Modal email not visible', 'FAIL');
          }
        } else {
          log(3, `Invite ${EXISTING_INVITE_EMAIL} as viewer`, 'Email input or invite button', 'Neither found', 'FAIL', pageText.substring(0, 400));
        }
      }
    }
  } catch (e) {
    log(3, `Invite ${EXISTING_INVITE_EMAIL} as viewer`, 'Invitation sent', 'Error', 'FAIL', e.message);
  }

  log(4, 'Verify invitation (Flow 1)', 'Invitation created',
    step3Pass ? 'Invitation created successfully' : 'Invitation creation failed',
    step3Pass ? 'PASS' : 'FAIL',
    capturedInviteUrl1 ? `Invite URL: ${capturedInviteUrl1}` : 'No invite URL captured');

  await page1.close();

  // ============================================================
  // FLOW 2: New user registration + new company
  // ============================================================
  console.log('\n--- FLOW 2: New user + new company ---\n');

  const page2 = await browser.newPage();

  // Step 5: Register new user
  try {
    await page2.goto(`${BASE_URL}/register`);
    await page2.waitForLoadState('networkidle');
    await page2.waitForTimeout(1000);

    await page2.screenshot({ path: '/home/hein/Workspace/IsaFlow/tmp/v2-step5-register.png' });
    const pageText = await page2.evaluate(() => document.body.innerText);
    console.log('  Register page text:', pageText.substring(0, 400));

    // Fill form fields
    const firstNameInput = page2.locator('input').filter({ hasText: '' }).first();

    // Use more specific selectors
    await page2.fill('input[name="firstName"], input[placeholder*="First" i], input[id*="first" i]', 'Test').catch(async () => {
      // Try positional - first text input
      const inputs = await page2.$$('input[type="text"], input:not([type])');
      if (inputs[0]) await inputs[0].fill('Test');
    });

    await page2.fill('input[name="lastName"], input[placeholder*="Last" i], input[id*="last" i]', 'NewCompany').catch(async () => {
      const inputs = await page2.$$('input[type="text"], input:not([type])');
      if (inputs[1]) await inputs[1].fill('NewCompany');
    });

    await page2.fill('input[type="email"]', NEW_USER_EMAIL);

    const pwdInputs = await page2.$$('input[type="password"]');
    if (pwdInputs[0]) await pwdInputs[0].fill('TestPass123!');
    if (pwdInputs[1]) await pwdInputs[1].fill('TestPass123!');

    await page2.screenshot({ path: '/home/hein/Workspace/IsaFlow/tmp/v2-step5-filled.png' });

    // Submit
    await page2.click('button[type="submit"]');
    try {
      await page2.waitForNavigation({ timeout: 8000 });
    } catch (e) {}
    await page2.waitForTimeout(2000);

    const afterUrl = page2.url();
    const afterText = await page2.evaluate(() => document.body.innerText);
    await page2.screenshot({ path: '/home/hein/Workspace/IsaFlow/tmp/v2-step5-after.png' });
    console.log('  After registration URL:', afterUrl);
    console.log('  After registration text:', afterText.substring(0, 300));

    const success = afterUrl.includes('/login') || afterText.toLowerCase().includes('success') ||
                    afterText.toLowerCase().includes('created');

    log(5, `Register new user ${NEW_USER_EMAIL}`, 'Redirect to login with success', afterUrl, success ? 'PASS' : 'FAIL', afterText.substring(0, 150));
  } catch (e) {
    log(5, `Register new user ${NEW_USER_EMAIL}`, 'Redirect to login with success', 'Error', 'FAIL', e.message);
  }

  // Step 6: Login as new user -> expect /onboarding
  try {
    const { url, text } = await loginAs(page2, NEW_USER_EMAIL, 'TestPass123!');
    await page2.screenshot({ path: '/home/hein/Workspace/IsaFlow/tmp/v2-step6-after-login.png' });

    if (url.includes('/onboarding')) {
      const onboardingText = await page2.evaluate(() => document.body.innerText.substring(0, 400));
      log(6, 'Login as new user', '/onboarding page', url, 'PASS', onboardingText.substring(0, 150));
    } else {
      log(6, 'Login as new user', '/onboarding page', url, 'FAIL', text.substring(0, 200));
    }
  } catch (e) {
    log(6, 'Login as new user', '/onboarding redirect', 'Error', 'FAIL', e.message);
  }

  // Step 7: Complete onboarding
  try {
    if (!page2.url().includes('/onboarding')) {
      log(7, 'Complete onboarding wizard', '/accounting dashboard', 'Skipped - not on /onboarding', 'FAIL', `Current URL: ${page2.url()}`);
    } else {
      await page2.screenshot({ path: '/home/hein/Workspace/IsaFlow/tmp/v2-step7-onboarding-start.png' });
      const onboardingText = await page2.evaluate(() => document.body.innerText);
      console.log('  Onboarding text:', onboardingText.substring(0, 500));

      // List ALL inputs
      const allInputs = await page2.$$('input, textarea');
      for (const inp of allInputs) {
        const type = await inp.evaluate(el => el.type);
        const name = await inp.evaluate(el => el.name);
        const placeholder = await inp.evaluate(el => el.placeholder);
        const id = await inp.evaluate(el => el.id);
        const visible = await inp.isVisible();
        console.log(`  Input: type=${type} name=${name} placeholder="${placeholder}" id=${id} visible=${visible}`);
      }

      // Fill company name - first visible text/non-password input
      let filledCompanyName = false;
      for (const inp of allInputs) {
        const type = await inp.evaluate(el => el.type);
        const visible = await inp.isVisible();
        const name = await inp.evaluate(el => el.name);
        const placeholder = await inp.evaluate(el => el.placeholder);
        const required = await inp.evaluate(el => el.required);
        if (visible && (type === 'text' || type === '' || type === 'search') &&
            (name.toLowerCase().includes('company') || name.toLowerCase().includes('name') ||
             placeholder.toLowerCase().includes('company') || required)) {
          console.log(`  Filling company name in: name=${name} placeholder="${placeholder}"`);
          await inp.fill('Test Company E2E');
          filledCompanyName = true;
          break;
        }
      }

      if (!filledCompanyName && allInputs.length > 0) {
        // Just fill the first visible input
        for (const inp of allInputs) {
          const visible = await inp.isVisible();
          if (visible) {
            await inp.fill('Test Company E2E');
            filledCompanyName = true;
            console.log('  Filled first visible input with company name');
            break;
          }
        }
      }

      await page2.screenshot({ path: '/home/hein/Workspace/IsaFlow/tmp/v2-step7-filled.png' });

      // Now click through all steps
      let stepCount = 0;
      let reachedAccounting = false;

      while (stepCount < 15 && !reachedAccounting) {
        const currentUrl = page2.url();
        console.log(`  Onboarding iteration ${stepCount}, URL: ${currentUrl}`);

        if (!currentUrl.includes('/onboarding')) {
          if (currentUrl.includes('/accounting')) {
            reachedAccounting = true;
          }
          break;
        }

        // List all buttons
        const buttons = await page2.$$('button');
        const buttonTexts = [];
        for (const btn of buttons) {
          const text = await btn.evaluate(el => el.textContent.trim());
          const visible = await btn.isVisible();
          const disabled = await btn.evaluate(el => el.disabled);
          buttonTexts.push(`"${text}" visible=${visible} disabled=${disabled}`);
        }
        console.log('  Buttons:', buttonTexts.join(', '));

        // Try Continue first, then other options
        let clicked = null;
        for (const btnText of ['Continue', 'Next', 'Complete Setup', 'Finish', 'Create Company', 'Save']) {
          const btns = await page2.$$('button');
          for (const btn of btns) {
            const text = await btn.evaluate(el => el.textContent.trim());
            const visible = await btn.isVisible();
            const disabled = await btn.evaluate(el => el.disabled);
            if (visible && !disabled && text.toLowerCase() === btnText.toLowerCase()) {
              console.log(`  Clicking: "${text}"`);
              await btn.click();
              clicked = text;
              break;
            }
          }
          if (clicked) break;
        }

        // Partial match if exact didn't work
        if (!clicked) {
          for (const btnText of ['continue', 'next', 'complete', 'finish', 'create', 'save', 'proceed']) {
            const btns = await page2.$$('button');
            for (const btn of btns) {
              const text = await btn.evaluate(el => el.textContent.toLowerCase().trim());
              const visible = await btn.isVisible();
              const disabled = await btn.evaluate(el => el.disabled);
              if (visible && !disabled && text.includes(btnText)) {
                console.log(`  Clicking (partial): "${text}"`);
                await btn.click();
                clicked = text;
                break;
              }
            }
            if (clicked) break;
          }
        }

        if (!clicked) {
          // Check if there are validation errors
          const errorText = await page2.evaluate(() => {
            const errors = document.querySelectorAll('[class*="error"], [class*="invalid"], [role="alert"]');
            return Array.from(errors).map(e => e.textContent.trim()).filter(t => t).join('; ');
          });
          console.log(`  No clickable button found. Errors: "${errorText}"`);
          await page2.screenshot({ path: `/home/hein/Workspace/IsaFlow/tmp/v2-step7-stuck-${stepCount}.png` });
          break;
        }

        await page2.waitForTimeout(2000);
        await page2.screenshot({ path: `/home/hein/Workspace/IsaFlow/tmp/v2-step7-onboarding-${stepCount}.png` });

        const newUrl = page2.url();
        if (newUrl.includes('/accounting') && !newUrl.includes('/onboarding')) {
          reachedAccounting = true;
          break;
        }

        stepCount++;
      }

      const finalUrl = page2.url();
      await page2.screenshot({ path: '/home/hein/Workspace/IsaFlow/tmp/v2-step7-final.png' });
      console.log('  Final URL:', finalUrl);

      if (finalUrl.includes('/accounting') && !finalUrl.includes('/onboarding')) {
        log(7, 'Complete onboarding wizard', '/accounting dashboard', finalUrl, 'PASS');
      } else {
        const finalText = await page2.evaluate(() => document.body.innerText);
        log(7, 'Complete onboarding wizard', '/accounting dashboard', finalUrl, 'FAIL', finalText.substring(0, 300));
      }
    }
  } catch (e) {
    log(7, 'Complete onboarding wizard', '/accounting dashboard', 'Error', 'FAIL', e.message);
  }

  await page2.close();

  // ============================================================
  // FLOW 3: New user via invitation link
  // ============================================================
  console.log('\n--- FLOW 3: New user via invitation ---\n');

  const page3 = await browser.newPage();

  // Intercept network to capture invite URLs
  let networkInviteUrl = null;
  page3.on('response', async (response) => {
    const url = response.url();
    if (url.includes('/api/') && url.includes('invit')) {
      try {
        const body = await response.json().catch(() => null);
        if (body) {
          console.log(`  API response from ${url}:`, JSON.stringify(body).substring(0, 300));
          // Look for invite URL in response
          const bodyStr = JSON.stringify(body);
          const match = bodyStr.match(/https?:\/\/[^"]*(?:invite|token)[^"]*/i);
          if (match) networkInviteUrl = match[0];
          // Also check for inviteLink, inviteUrl, link fields
          const findUrl = (obj) => {
            if (typeof obj === 'string' && obj.startsWith('http') && (obj.includes('invite') || obj.includes('token'))) return obj;
            if (typeof obj === 'object' && obj !== null) {
              for (const v of Object.values(obj)) {
                const found = findUrl(v);
                if (found) return found;
              }
            }
            return null;
          };
          const foundUrl = findUrl(body);
          if (foundUrl) networkInviteUrl = foundUrl;
        }
      } catch (e) {}
    }
  });

  // Step 8: Login as admin
  try {
    const { url, text } = await loginAs(page3, ADMIN_EMAIL, ADMIN_PASS);
    if (url.includes('/accounting') || url.includes('/dashboard')) {
      log(8, 'Login as admin (Flow 3)', '/accounting dashboard', url, 'PASS');
    } else {
      log(8, 'Login as admin (Flow 3)', '/accounting dashboard', url, 'FAIL', text.substring(0, 200));
    }
  } catch (e) {
    log(8, 'Login as admin (Flow 3)', '/accounting dashboard', 'Error', 'FAIL', e.message);
  }

  // Step 9: Invite user and get link
  let capturedInviteUrl = null;
  try {
    await page3.goto(`${BASE_URL}/accounting/user-access`);
    await page3.waitForLoadState('networkidle');
    await page3.waitForTimeout(2000);
    await page3.screenshot({ path: '/home/hein/Workspace/IsaFlow/tmp/v2-step9-user-access.png' });

    const url = page3.url();
    if (url.includes('/login')) {
      log(9, `Invite ${INVITED_USER_EMAIL} as manager`, 'Pending invitation with link', 'Redirected to login', 'FAIL');
