    const pwdInputs = await page2.$$('input[type="password"]');
    if (pwdInputs[0]) await pwdInputs[0].fill('TestPass123!');
    if (pwdInputs[1]) await pwdInputs[1].fill('TestPass123!');

    await page2.screenshot({ path: '/home/hein/Workspace/IsaFlow/tmp/v2-step5-filled.png' });

    // Submit
    await page2.click('button[type="submit"]');
    try {
      await page2.waitForNavigation({ timeout: 8000 });
    } catch (e) {}
    await page2.waitForTimeout(2000);

    const afterUrl = page2.url();
    const afterText = await page2.evaluate(() => document.body.innerText);
    await page2.screenshot({ path: '/home/hein/Workspace/IsaFlow/tmp/v2-step5-after.png' });
    console.log('  After registration URL:', afterUrl);
    console.log('  After registration text:', afterText.substring(0, 300));

    const success = afterUrl.includes('/login') || afterText.toLowerCase().includes('success') ||
