// ISAFlow E2E QA Test Script v3
// Fixes: admin password = admin123, better onboarding error capture, invite URL via API

const { chromium } = require('playwright');

const BASE_URL = 'https://app.isaflow.co.za';
const ADMIN_EMAIL = 'admin@isaflow.co.za';
const ADMIN_PASS = 'admin123';
const TIMESTAMP = Date.now();
const NEW_USER_EMAIL = `testnewco_${TIMESTAMP}@test.com`;
const INVITED_USER_EMAIL = `testinvited_${TIMESTAMP}@test.com`;
const EXISTING_INVITE_EMAIL = 'testinvite1@isaflow.co.za';

const results = [];

function log(step, action, expected, actual, result, notes = '') {
  const r = { step, action, expected, actual: String(actual), result, notes: String(notes) };
  results.push(r);
  const icon = result === 'PASS' ? '✓' : '✗';
  console.log(`[${icon}] Step ${step}: ${action} -> ${result}`);
  if (result === 'FAIL') {
    console.log(`    Expected: ${expected}`);
    console.log(`    Actual:   ${String(actual).substring(0, 120)}`);
    if (notes) console.log(`    Notes:    ${String(notes).substring(0, 200)}`);
  } else {
    console.log(`    OK: ${String(actual).substring(0, 100)}`);
  }
}

async function loginAs(page, email, password) {
  await page.goto(`${BASE_URL}/login`);
  await page.waitForLoadState('networkidle');
  await page.waitForSelector('input[type="email"]', { timeout: 10000 });

  await page.fill('input[type="email"]', email);
  await page.fill('input[type="password"]', password);

  const emailVal = await page.$eval('input[type="email"]', el => el.value);
  const passVal = await page.$eval('input[type="password"]', el => el.value);
  console.log(`  Login: email="${emailVal}" pass_len=${passVal.length}`);

  await page.click('button[type="submit"]');
  try { await page.waitForNavigation({ timeout: 8000 }); } catch (e) {}
  await page.waitForTimeout(2000);

  const url = page.url();
  const text = await page.evaluate(() => document.body.innerText.substring(0, 300));
  console.log(`  Post-login URL: ${url}`);
  if (url.includes('/login')) console.log(`  Still on login: ${text.substring(0, 150)}`);
  return { url, text };
}

async function clickBtnText(page, ...texts) {
  const buttons = await page.$$('button, [role="button"]');
  for (const btn of buttons) {
    const t = await btn.evaluate(el => el.textContent.toLowerCase().trim());
    const visible = await btn.isVisible();
    const disabled = await btn.evaluate(el => el.disabled);
    for (const opt of texts) {
      if (visible && !disabled && t.includes(opt.toLowerCase())) {
        console.log(`  Clicking: "${await btn.evaluate(el => el.textContent.trim())}"`);
        await btn.click();
        return t;
      }
    }
  }
  return null;
}

async function runTests() {
  const browser = await chromium.launch({
    headless: true,
    args: ['--no-sandbox', '--disable-setuid-sandbox']
  });

  console.log('\n=== ISAFlow QA Test Suite v3 ===\n');
  console.log(`Date: ${new Date().toISOString().split('T')[0]}`);
  console.log(`New user: ${NEW_USER_EMAIL}`);
  console.log(`Invited user: ${INVITED_USER_EMAIL}`);
  console.log('');

  // ====================================================
  // FLOW 1: Invite existing user
  // ====================================================
  console.log('--- FLOW 1: Invite existing user ---\n');
  const page1 = await browser.newPage();

  // Capture API responses for invite URL
  let apiInviteUrl = null;
  page1.on('response', async (resp) => {
    if ((resp.url().includes('/api/') && resp.url().includes('invit')) ||
        (resp.url().includes('/api/') && resp.url().includes('user'))) {
      try {
        const body = await resp.json().catch(() => null);
        if (body) {
          const bodyStr = JSON.stringify(body);
          if (bodyStr.includes('invite') || bodyStr.includes('token')) {
            console.log(`  API[${resp.url().split('/api/')[1]}]:`, bodyStr.substring(0, 300));
          }
          // Extract URL
          const findUrl = (obj) => {
            if (typeof obj === 'string' && obj.startsWith('http') && (obj.includes('invite') || obj.includes('token'))) return obj;
            if (typeof obj === 'object' && obj !== null) {
              for (const v of Object.values(obj)) { const f = findUrl(v); if (f) return f; }
            }
            return null;
          };
          const u = findUrl(body);
          if (u && !apiInviteUrl) { apiInviteUrl = u; console.log('  Captured API invite URL:', u); }
        }
      } catch (e) {}
    }
  });

  // Step 1: Admin login
  try {
    const { url, text } = await loginAs(page1, ADMIN_EMAIL, ADMIN_PASS);
    if (url.includes('/accounting') || url.includes('/dashboard')) {
      log(1, 'Login as admin', '/accounting dashboard', url, 'PASS');
    } else {
      log(1, 'Login as admin', '/accounting dashboard', url, 'FAIL', text.substring(0, 150));
    }
  } catch (e) {
    log(1, 'Login as admin', '/accounting dashboard', 'Error: ' + e.message, 'FAIL');
  }

  // Step 2: User Access page
  try {
    await page1.goto(`${BASE_URL}/accounting/user-access`);
    await page1.waitForLoadState('networkidle');
    await page1.waitForTimeout(2000);
    const url = page1.url();
    await page1.screenshot({ path: '/home/hein/Workspace/IsaFlow/tmp/v3-step2-user-access.png' });

    if (url.includes('/login')) {
      log(2, 'Navigate to User Access', 'User access page', 'Redirected to login', 'FAIL');
    } else {
      const text = await page1.evaluate(() => document.body.innerText.substring(0, 400));
      console.log('  User access page:', text.substring(0, 300));
      log(2, 'Navigate to User Access', 'User access page', url, 'PASS', text.substring(0, 100));
    }
  } catch (e) {
    log(2, 'Navigate to User Access', 'User access page', 'Error: ' + e.message, 'FAIL');
  }

  // Step 3: Invite testinvite1
  let step3Pass = false;
  let inviteUrl1 = null;
  try {
    if (results.find(r => r.step === 2)?.result !== 'PASS') {
      log(3, `Invite ${EXISTING_INVITE_EMAIL} viewer`, 'Invitation appears', 'Skipped (step 2 failed)', 'FAIL');
    } else {
      const pageText = await page1.evaluate(() => document.body.innerText);

      // List all inputs
      const inputs = await page1.$$('input');
      for (const inp of inputs) {
        const t = await inp.evaluate(el => el.type), n = await inp.evaluate(el => el.name),
              p = await inp.evaluate(el => el.placeholder), v = await inp.isVisible();
        console.log(`  Input: type=${t} name="${n}" placeholder="${p}" visible=${v}`);
      }

      const emailInput = page1.locator('input[type="email"]').first();
      const emailVisible = await emailInput.isVisible().catch(() => false);

      if (emailVisible) {
        await emailInput.fill(EXISTING_INVITE_EMAIL);

        // Try role select
        const selects = await page1.$$('select');
        for (const sel of selects) {
          if (await sel.isVisible()) {
            try { await sel.selectOption('viewer'); } catch (e) {
            try { await sel.selectOption('Viewer'); } catch (e) { await sel.selectOption({ index: 1 }).catch(() => {}); }}
            console.log('  Role set to viewer');
            break;
          }
        }

        // Monitor API
        const apiPromise = page1.waitForResponse(
          r => r.url().includes('/api/') && (r.url().includes('invit') || r.url().includes('user-access')),
          { timeout: 8000 }
        ).catch(() => null);

        await clickBtnText(page1, 'invite', 'add user', 'send invite');
        const apiResp = await apiPromise;
        if (apiResp) {
          const body = await apiResp.json().catch(() => null);
          if (body) {
            console.log('  Invite API response:', JSON.stringify(body).substring(0, 400));
            // Look for invite link
            const findUrl = (obj) => {
              if (typeof obj === 'string' && obj.length > 20 && (obj.includes('invite') || obj.includes('token'))) {
                return obj.startsWith('http') ? obj : (obj.startsWith('/') ? `${BASE_URL}${obj}` : null);
              }
              if (typeof obj === 'object' && obj !== null) {
                for (const [k, v] of Object.entries(obj)) {
                  if (['link', 'url', 'inviteLink', 'inviteUrl', 'shareLink', 'token'].some(kw => k.toLowerCase().includes(kw))) {
                    if (typeof v === 'string' && v.length > 10) {
                      return v.startsWith('http') ? v : `${BASE_URL}${v}`;
                    }
                  }
                  const found = findUrl(v);
                  if (found) return found;
                }
              }
              return null;
            };
            inviteUrl1 = findUrl(body);
          }
        }

        await page1.waitForTimeout(3000);
        await page1.screenshot({ path: '/home/hein/Workspace/IsaFlow/tmp/v3-step3-after-invite.png' });

        if (!inviteUrl1) inviteUrl1 = apiInviteUrl;

        // Check page for URLs
        if (!inviteUrl1) {
          const readonlyInputs = await page1.$$('input[readonly]');
          for (const inp of readonlyInputs) {
            const val = await inp.evaluate(el => el.value);
            if (val && val.startsWith('http')) { inviteUrl1 = val; break; }
          }
        }

        const afterText = await page1.evaluate(() => document.body.innerText);
        console.log('  After invite:', afterText.substring(0, 500));
        console.log('  Invite URL:', inviteUrl1);

        const success = afterText.toLowerCase().includes('pending') ||
                        afterText.toLowerCase().includes('invited') ||
                        afterText.toLowerCase().includes('success') ||
                        afterText.toLowerCase().includes(EXISTING_INVITE_EMAIL.toLowerCase()) ||
                        inviteUrl1;

        step3Pass = !!success;
        log(3, `Invite ${EXISTING_INVITE_EMAIL} viewer`, 'Invitation appears',
          inviteUrl1 ? `URL: ${inviteUrl1.substring(0, 80)}` : (success ? 'Invited (no URL)' : 'No confirmation'),
          success ? 'PASS' : 'FAIL', afterText.substring(0, 200));
      } else {
        // Try opening invite modal first
        const opened = await clickBtnText(page1, 'invite user', 'add member', 'invite member', 'add user', 'invite');
        if (opened) {
          await page1.waitForTimeout(800);
          const modalEmail = page1.locator('input[type="email"]').first();
          if (await modalEmail.isVisible().catch(() => false)) {
            await modalEmail.fill(EXISTING_INVITE_EMAIL);
            const apiProm = page1.waitForResponse(r => r.url().includes('/api/'), { timeout: 8000 }).catch(() => null);
            await clickBtnText(page1, 'invite', 'send', 'confirm');
            const resp = await apiProm;
            if (resp) {
              const body = await resp.json().catch(() => null);
              console.log('  Modal invite API:', JSON.stringify(body || {}).substring(0, 300));
            }
            await page1.waitForTimeout(3000);
            const afterText = await page1.evaluate(() => document.body.innerText);
            const success = afterText.toLowerCase().includes('pending') || afterText.toLowerCase().includes('invited') ||
                            afterText.toLowerCase().includes(EXISTING_INVITE_EMAIL.toLowerCase());
            step3Pass = !!success;
            log(3, `Invite ${EXISTING_INVITE_EMAIL} viewer`, 'Invitation appears',
              success ? 'Invited via modal' : 'No confirmation', success ? 'PASS' : 'FAIL', afterText.substring(0, 200));
          } else {
            log(3, `Invite ${EXISTING_INVITE_EMAIL} viewer`, 'Modal email input', 'Not visible', 'FAIL');
          }
        } else {
          const t = await page1.evaluate(() => document.body.innerText);
          log(3, `Invite ${EXISTING_INVITE_EMAIL} viewer`, 'Email input or invite btn', 'Not found', 'FAIL', t.substring(0, 300));
        }
      }
    }
  } catch (e) {
    log(3, `Invite ${EXISTING_INVITE_EMAIL} viewer`, 'Invitation sent', 'Error: ' + e.message, 'FAIL');
  }

  log(4, 'Verify invitation (Flow 1)', 'Invitation created',
    step3Pass ? 'Invitation created' : 'Failed',
    step3Pass ? 'PASS' : 'FAIL',
    inviteUrl1 ? `Invite URL: ${inviteUrl1}` : 'No invite URL');

  await page1.close();

  // ====================================================
  // FLOW 2: New user registration + company
  // ====================================================
  console.log('\n--- FLOW 2: New user + new company ---\n');
  const page2 = await browser.newPage();

  // Monitor API calls during onboarding
  const onboardingApiCalls = [];
  page2.on('response', async (resp) => {
    if (resp.url().includes('/api/')) {
      try {
        const body = await resp.json().catch(() => null);
        const entry = { url: resp.url(), status: resp.status(), body: body ? JSON.stringify(body).substring(0, 300) : null };
        onboardingApiCalls.push(entry);
        if (resp.status() >= 400 || (resp.url().includes('compan') || resp.url().includes('onboard'))) {
          console.log(`  API [${resp.status()}] ${resp.url().split('/api/')[1]}: ${entry.body}`);
        }
      } catch (e) {}
    }
  });

  // Step 5: Register
  try {
    await page2.goto(`${BASE_URL}/register`);
    await page2.waitForLoadState('networkidle');

    const inputs = await page2.$$('input');
    const inputInfo = [];
    for (const inp of inputs) {
      inputInfo.push({
        type: await inp.evaluate(el => el.type),
        name: await inp.evaluate(el => el.name),
        placeholder: await inp.evaluate(el => el.placeholder),
        id: await inp.evaluate(el => el.id)
      });
    }
    console.log('  Register inputs:', JSON.stringify(inputInfo));

    // Fill by position (form is: firstName, lastName, email, password, confirmPassword)
    if (inputInfo[0]) await inputs[0].fill('Test');
    if (inputInfo[1]) await inputs[1].fill('NewCompany');
    await page2.fill('input[type="email"]', NEW_USER_EMAIL);
    const pwds = await page2.$$('input[type="password"]');
    if (pwds[0]) await pwds[0].fill('TestPass123!');
    if (pwds[1]) await pwds[1].fill('TestPass123!');

    await page2.click('button[type="submit"]');
    try { await page2.waitForNavigation({ timeout: 8000 }); } catch (e) {}
    await page2.waitForTimeout(2000);

    const afterUrl = page2.url();
    const afterText = await page2.evaluate(() => document.body.innerText);
    log(5, `Register ${NEW_USER_EMAIL}`, '/login with success', afterUrl,
      afterUrl.includes('/login') ? 'PASS' : 'FAIL', afterText.substring(0, 150));
  } catch (e) {
    log(5, `Register ${NEW_USER_EMAIL}`, '/login with success', 'Error: ' + e.message, 'FAIL');
  }

  // Step 6: Login -> /onboarding
  try {
    const { url, text } = await loginAs(page2, NEW_USER_EMAIL, 'TestPass123!');
    if (url.includes('/onboarding')) {
      log(6, 'Login as new user', '/onboarding', url, 'PASS');
    } else {
      log(6, 'Login as new user', '/onboarding', url, 'FAIL', text.substring(0, 150));
    }
  } catch (e) {
    log(6, 'Login as new user', '/onboarding', 'Error: ' + e.message, 'FAIL');
  }

  // Step 7: Complete onboarding
  try {
    if (!page2.url().includes('/onboarding')) {
      log(7, 'Complete onboarding', '/accounting', 'Not on /onboarding, skipped', 'FAIL', page2.url());
    } else {
      const allInputs = await page2.$$('input');
      console.log('  Filling first visible input with company name');
      for (const inp of allInputs) {
        if (await inp.isVisible()) {
          await inp.fill('Test Company E2E');
          break;
        }
      }

      // Walk through all 7 steps
      let stepNum = 0, done = false, lastError = '';
      while (stepNum < 15 && !done) {
        const url = page2.url();
        if (!url.includes('/onboarding')) { done = url.includes('/accounting'); break; }

        const btns = await page2.$$('button');
        const btnList = [];
        for (const b of btns) {
          const t = await b.evaluate(el => el.textContent.trim());
          const v = await b.isVisible();
          const d = await b.evaluate(el => el.disabled);
          btnList.push({ t, v, d });
        }
        console.log(`  Step ${stepNum} buttons:`, btnList.map(b => `"${b.t}"(d=${b.d})`).join(', '));

        // Look for error messages
        const errorText = await page2.evaluate(() => {
          const errs = document.querySelectorAll('[class*="error"], [class*="invalid"], [role="alert"], .text-red-500, .text-red-400');
          return Array.from(errs).map(e => e.textContent.trim()).filter(t => t).join(' | ');
        });
        if (errorText) console.log(`  Errors on step ${stepNum}:`, errorText);

        // Prefer Continue > Complete Setup > Skip
        let clicked = false;
        for (const target of ['Continue', 'Complete Setup', 'Skip', 'Next']) {
          const btn = btnList.find(b => b.v && !b.d && b.t === target);
          if (btn) {
            const btnEl = await page2.$(`button:has-text("${target}")`);
            if (btnEl) {
              await btnEl.click();
              clicked = true;
              console.log(`  Clicked "${target}"`);
              break;
            }
          }
        }

        if (!clicked) {
          // Catch "Saving..." state - wait for it to finish
          const savingBtn = btnList.find(b => b.v && b.t.includes('Saving'));
          if (savingBtn) {
            console.log('  Waiting for saving to complete...');
            await page2.waitForTimeout(5000);
            const urlAfter = page2.url();
            if (urlAfter.includes('/accounting')) { done = true; break; }
            // Check for errors
            const errAfter = await page2.evaluate(() => {
              const errs = document.querySelectorAll('[class*="error"], [class*="invalid"], [role="alert"], .text-red-500, .text-red-400');
              return Array.from(errs).map(e => e.textContent.trim()).filter(t => t).join(' | ');
            });
            lastError = errAfter || 'Stuck on saving';
            console.log('  After saving wait:', urlAfter, 'Error:', lastError);
            break;
          }
          lastError = `No clickable button at step ${stepNum}`;
          await page2.screenshot({ path: `/home/hein/Workspace/IsaFlow/tmp/v3-step7-stuck-${stepNum}.png` });
          break;
        }

        await page2.waitForTimeout(2000);
        stepNum++;
      }

      const finalUrl = page2.url();
      await page2.screenshot({ path: '/home/hein/Workspace/IsaFlow/tmp/v3-step7-final.png' });

      // Also get all API calls during onboarding
      const failedCalls = onboardingApiCalls.filter(c => c.status >= 400);
      if (failedCalls.length > 0) {
        console.log('  Failed API calls during onboarding:');
        failedCalls.forEach(c => console.log(`    [${c.status}] ${c.url}: ${c.body}`));
      }

      if (finalUrl.includes('/accounting') && !finalUrl.includes('/onboarding')) {
        log(7, 'Complete onboarding wizard', '/accounting', finalUrl, 'PASS');
      } else {
        const finalText = await page2.evaluate(() => document.body.innerText.substring(0, 300));
        const errInfo = failedCalls.map(c => `[${c.status}] ${c.url.split('/api/')[1]}: ${c.body}`).join('; ');
        log(7, 'Complete onboarding wizard', '/accounting', finalUrl, 'FAIL',
          lastError || errInfo || finalText);
      }
    }
  } catch (e) {
    log(7, 'Complete onboarding wizard', '/accounting', 'Error: ' + e.message, 'FAIL');
  }

  await page2.close();

  // ====================================================
  // FLOW 3: New user via invitation link
  // ====================================================
  console.log('\n--- FLOW 3: New user via invitation ---\n');
  const page3 = await browser.newPage();

  let capturedInviteUrl = null;
  const inviteApiCalls = [];
  page3.on('response', async (resp) => {
    if (resp.url().includes('/api/')) {
      try {
        const body = await resp.json().catch(() => null);
        if (body) {
          const bodyStr = JSON.stringify(body);
          inviteApiCalls.push({ url: resp.url(), status: resp.status(), body: bodyStr.substring(0, 400) });
          if (bodyStr.includes('invite') || bodyStr.includes('token') || bodyStr.includes('link')) {
            console.log(`  API [${resp.status()}] ${resp.url().split('/api/')[1]}: ${bodyStr.substring(0, 300)}`);
          }
          // Extract URL
          const findUrl = (obj) => {
            if (typeof obj === 'string') {
              if (obj.startsWith('http') && (obj.includes('invite') || obj.includes('token'))) return obj;
              if (obj.startsWith('/invite') || obj.startsWith('/auth/invite')) return `${BASE_URL}${obj}`;
            }
            if (typeof obj === 'object' && obj !== null) {
              for (const [k, v] of Object.entries(obj)) {
                if (['link', 'url', 'inviteLink', 'inviteUrl', 'shareUrl', 'href'].some(kw => k.toLowerCase().includes(kw))) {
                  if (typeof v === 'string' && v.length > 5) {
                    return v.startsWith('http') ? v : `${BASE_URL}${v}`;
                  }
                }
                const found = findUrl(v);
                if (found) return found;
              }
            }
            return null;
          };
          const u = findUrl(body);
          if (u && !capturedInviteUrl) { capturedInviteUrl = u; console.log('  Captured invite URL:', u); }
        }
      } catch (e) {}
    }
  });

  // Step 8: Admin login
  try {
    const { url, text } = await loginAs(page3, ADMIN_EMAIL, ADMIN_PASS);
    if (url.includes('/accounting') || url.includes('/dashboard')) {
      log(8, 'Login as admin (Flow 3)', '/accounting', url, 'PASS');
    } else {
      log(8, 'Login as admin (Flow 3)', '/accounting', url, 'FAIL', text.substring(0, 150));
    }
  } catch (e) {
    log(8, 'Login as admin (Flow 3)', '/accounting', 'Error: ' + e.message, 'FAIL');
  }

  // Step 9: Invite and capture link
  try {
    if (results.find(r => r.step === 8)?.result !== 'PASS') {
      log(9, `Invite ${INVITED_USER_EMAIL} manager`, 'Pending invite with link', 'Skipped (step 8 failed)', 'FAIL');
    } else {
      await page3.goto(`${BASE_URL}/accounting/user-access`);
      await page3.waitForLoadState('networkidle');
      await page3.waitForTimeout(2000);
      await page3.screenshot({ path: '/home/hein/Workspace/IsaFlow/tmp/v3-step9-page.png' });

      const pageText = await page3.evaluate(() => document.body.innerText);
      console.log('  User-access text:', pageText.substring(0, 500));

      const emailInput = page3.locator('input[type="email"]').first();
      if (await emailInput.isVisible().catch(() => false)) {
        await emailInput.fill(INVITED_USER_EMAIL);

        // Role: manager
        const selects = await page3.$$('select');
        for (const sel of selects) {
          if (await sel.isVisible()) {
            try { await sel.selectOption('manager'); } catch (e) {
            try { await sel.selectOption('Manager'); } catch (e) {
              await sel.selectOption({ index: 2 }).catch(() => {});
            }}
            const val = await sel.evaluate(el => el.value);
            console.log(`  Role select value: "${val}"`);
            break;
          }
        }

