const INVITED_USER_EMAIL = `testinvited_${TIMESTAMP}@test.com`;
const EXISTING_INVITE_EMAIL = 'testinvite1@isaflow.co.za';

const results = [];

function log(step, action, expected, actual, result, notes = '') {
  const r = { step, action, expected, actual: String(actual), result, notes: String(notes) };
  results.push(r);
  const icon = result === 'PASS' ? '✓' : '✗';
  console.log(`[${icon}] Step ${step}: ${action} -> ${result}`);
  if (result === 'FAIL') {
    console.log(`    Expected: ${expected}`);
    console.log(`    Actual:   ${String(actual).substring(0, 120)}`);
    if (notes) console.log(`    Notes:    ${String(notes).substring(0, 200)}`);
  } else {
    console.log(`    OK: ${String(actual).substring(0, 100)}`);
  }
}

async function loginAs(page, email, password) {
  await page.goto(`${BASE_URL}/login`);
  await page.waitForLoadState('networkidle');
  await page.waitForSelector('input[type="email"]', { timeout: 10000 });

  await page.fill('input[type="email"]', email);
  await page.fill('input[type="password"]', password);

  const emailVal = await page.$eval('input[type="email"]', el => el.value);
  const passVal = await page.$eval('input[type="password"]', el => el.value);
  console.log(`  Login: email="${emailVal}" pass_len=${passVal.length}`);

  await page.click('button[type="submit"]');
  try { await page.waitForNavigation({ timeout: 8000 }); } catch (e) {}
  await page.waitForTimeout(2000);

  const url = page.url();
  const text = await page.evaluate(() => document.body.innerText.substring(0, 300));
  console.log(`  Post-login URL: ${url}`);
  if (url.includes('/login')) console.log(`  Still on login: ${text.substring(0, 150)}`);
  return { url, text };
}

async function clickBtnText(page, ...texts) {
  const buttons = await page.$$('button, [role="button"]');
  for (const btn of buttons) {
    const t = await btn.evaluate(el => el.textContent.toLowerCase().trim());
    const visible = await btn.isVisible();
    const disabled = await btn.evaluate(el => el.disabled);
    for (const opt of texts) {
      if (visible && !disabled && t.includes(opt.toLowerCase())) {
        console.log(`  Clicking: "${await btn.evaluate(el => el.textContent.trim())}"`);
        await btn.click();
        return t;
      }
    }
  }
  return null;
}

