  console.log(`Flow 3 (New user via invitation): ${f3p ? 'PASS' : 'FAIL'} — ${f3p ? 'Invite flow completed' : `Failed at step ${f3f?.step}: ${(f3f?.notes||f3f?.actual||'').substring(0,120)}`}`);

  if (results.some(r => r.result === 'FAIL')) {
    console.log('\n=== FAILURE DETAILS ===\n');
    for (const r of results.filter(r => r.result === 'FAIL')) {
      console.log(`Step ${r.step} FAIL: ${r.action}`);
      console.log(`  Expected: ${r.expected}`);
      console.log(`  Actual:   ${r.actual}`);
      if (r.notes) console.log(`  Notes:    ${r.notes.substring(0, 300)}`);
      console.log('');
    }
  }

  const fs = require('fs');
  fs.writeFileSync('/home/hein/Workspace/IsaFlow/tmp/qa-results-v3.json', JSON.stringify({ results, summary: { passed, total, f1p, f2p, f3p } }, null, 2));
  console.log('Saved: /home/hein/Workspace/IsaFlow/tmp/qa-results-v3.json');
}

runTests().catch(e => { console.error('Fatal:', e); process.exit(1); });

