  if (!capturedInviteUrl) {
    log(10, 'Open invite link', 'Landing page', 'No URL captured in step 9', 'FAIL');
    log(11, 'Register via invite', '/register with token', 'Skipped', 'FAIL');
    log(12, 'Login as invited user', '/accounting (not /onboarding)', 'Skipped', 'FAIL');
  } else {
