          await page4.screenshot({ path: '/home/hein/Workspace/IsaFlow/tmp/v3-step11-filled.png' });

          await page4.click('button[type="submit"]').catch(async () => {
            await clickBtnText(page4, 'create account', 'register', 'sign up');
          });
          try { await page4.waitForNavigation({ timeout: 8000 }); } catch (e) {}
          await page4.waitForTimeout(2000);

          const afterRegUrl = page4.url();
