              if (loginUrl.includes('/accounting') && !loginUrl.includes('/onboarding')) {
                log(12, 'Login as invited user', '/accounting (NOT /onboarding)', loginUrl, 'PASS');
              } else if (loginUrl.includes('/onboarding')) {
