          log(11, 'Register via invite link', '/register', regUrl, 'FAIL', regText.substring(0, 200));
          log(12, 'Login as invited user', '/accounting', 'Skipped', 'FAIL');
        }
      } catch (e) {
        log(11, 'Register via invite link', '/register', 'Error: ' + e.message, 'FAIL');
        log(12, 'Login as invited user', '/accounting', 'Skipped', 'FAIL');
      }
    } catch (e) {
      log(10, 'Open invite link', 'Landing page', 'Error: ' + e.message, 'FAIL');
      log(11, 'Register via invite', '/register', 'Skipped', 'FAIL');
      log(12, 'Login as invited user', '/accounting', 'Skipped', 'FAIL');
    }
    await page4.close();
  }

  await page3.close();
  await browser.close();

  // ====================================================
  // FINAL REPORT
  // ====================================================
  console.log('\n\n════════════════════════════════════════');
  console.log('     QA REPORT: ISAFlow E2E v3');
  console.log('════════════════════════════════════════\n');
  console.log(`Date: ${new Date().toISOString().split('T')[0]}\n`);

  console.log('| Step | Action | Expected | Actual | Result |');
  console.log('|------|--------|----------|--------|--------|');
  for (const r of results) {
    const a = (r.actual || '').length > 70 ? r.actual.substring(0, 70) + '...' : (r.actual || '');
