  const passed = results.filter(r => r.result === 'PASS').length;
  const total = results.length;
  console.log(`\n**Summary:** ${passed}/${total} steps passed\n`);

  const f1 = results.filter(r => r.step <= 4);
  const f2 = results.filter(r => r.step >= 5 && r.step <= 7);
  const f3 = results.filter(r => r.step >= 8 && r.step <= 12);
  const f1p = f1.every(r => r.result === 'PASS');
  const f2p = f2.every(r => r.result === 'PASS');
  const f3p = f3.every(r => r.result === 'PASS');
  const f1f = f1.find(r => r.result === 'FAIL');
  const f2f = f2.find(r => r.result === 'FAIL');
  const f3f = f3.find(r => r.result === 'FAIL');

  console.log(`Flow 1 (Invite existing user): ${f1p ? 'PASS' : 'FAIL'} — ${f1p ? 'All steps passed' : `Failed at step ${f1f?.step}: ${(f1f?.notes||f1f?.actual||'').substring(0,120)}`}`);
  console.log(`Flow 2 (New user + new company): ${f2p ? 'PASS' : 'FAIL'} — ${f2p ? 'Registration + onboarding completed' : `Failed at step ${f2f?.step}: ${(f2f?.notes||f2f?.actual||'').substring(0,120)}`}`);
  console.log(`Flow 3 (New user via invitation): ${f3p ? 'PASS' : 'FAIL'} — ${f3p ? 'Invite flow completed' : `Failed at step ${f3f?.step}: ${(f3f?.notes||f3f?.actual||'').substring(0,120)}`}`);

  if (results.some(r => r.result === 'FAIL')) {
    console.log('\n=== FAILURE DETAILS ===\n');
    for (const r of results.filter(r => r.result === 'FAIL')) {
      console.log(`Step ${r.step} FAIL: ${r.action}`);
      console.log(`  Expected: ${r.expected}`);
      console.log(`  Actual:   ${r.actual}`);
      if (r.notes) console.log(`  Notes:    ${r.notes.substring(0, 300)}`);
      console.log('');
    }
  }

  const fs = require('fs');
  fs.writeFileSync('/home/hein/Workspace/IsaFlow/tmp/qa-results-v3.json', JSON.stringify({ results, summary: { passed, total, f1p, f2p, f3p } }, null, 2));
  console.log('Saved: /home/hein/Workspace/IsaFlow/tmp/qa-results-v3.json');
}

runTests().catch(e => { console.error('Fatal:', e); process.exit(1); });

