// ISAFlow E2E QA Test Script v4
// Fixes:
// 1. React-controlled inputs: use dispatchEvent to trigger onChange
// 2. Onboarding: wait longer after Complete Setup, check for errors
// 3. Invite form: target the specific invite email input by label/context

const { chromium } = require('playwright');

const BASE_URL = 'https://app.isaflow.co.za';
const ADMIN_EMAIL = 'admin@isaflow.co.za';
const ADMIN_PASS = 'admin123';
const TIMESTAMP = Date.now();
const NEW_USER_EMAIL = `testnewco_${TIMESTAMP}@test.com`;
const INVITED_USER_EMAIL = `testinvited_${TIMESTAMP}@test.com`;
const EXISTING_INVITE_EMAIL = 'testinvite1@isaflow.co.za';

const results = [];

function log(step, action, expected, actual, result, notes = '') {
  const r = { step, action, expected, actual: String(actual), result, notes: String(notes) };
  results.push(r);
  const icon = result === 'PASS' ? '✓' : '✗';
  console.log(`[${icon}] Step ${step}: ${action} -> ${result}`);
  if (result === 'FAIL') {
    console.log(`    Expected: ${expected}`);
    console.log(`    Actual:   ${String(actual).substring(0, 120)}`);
    if (notes) console.log(`    Notes:    ${String(notes).substring(0, 250)}`);
  } else {
    console.log(`    OK: ${String(actual).substring(0, 100)}`);
  }
}

// Fill a React-controlled input properly
async function fillReactInput(page, selector, value) {
  await page.focus(selector);
  await page.evaluate((sel, val) => {
    const el = document.querySelector(sel);
    if (!el) return;
    const nativeInputValueSetter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
    nativeInputValueSetter.call(el, val);
    el.dispatchEvent(new Event('input', { bubbles: true }));
    el.dispatchEvent(new Event('change', { bubbles: true }));
  }, selector, value);
}

async function loginAs(page, email, password) {
  await page.goto(`${BASE_URL}/login`);
  await page.waitForLoadState('networkidle');
  await page.waitForSelector('input[type="email"]', { timeout: 10000 });
  await page.fill('input[type="email"]', email);
  await page.fill('input[type="password"]', password);
  const ev = await page.$eval('input[type="email"]', el => el.value);
  const pv = await page.$eval('input[type="password"]', el => el.value);
  console.log(`  Login: email="${ev}" pass_len=${pv.length}`);
  await page.click('button[type="submit"]');
  try { await page.waitForNavigation({ timeout: 8000 }); } catch (e) {}
  await page.waitForTimeout(2000);
  const url = page.url();
  const text = await page.evaluate(() => document.body.innerText.substring(0, 300));
  console.log(`  Post-login URL: ${url}`);
  if (url.includes('/login')) console.log(`  Still on login: ${text.substring(0, 120)}`);
  return { url, text };
}

async function runTests() {
  const browser = await chromium.launch({
    headless: true,
    args: ['--no-sandbox', '--disable-setuid-sandbox']
  });

  console.log('\n=== ISAFlow QA Test Suite v4 ===\n');
  console.log(`Date: ${new Date().toISOString().split('T')[0]}`);
  console.log(`Timestamp: ${TIMESTAMP}`);
  console.log(`New user: ${NEW_USER_EMAIL}`);
  console.log(`Invited user: ${INVITED_USER_EMAIL}`);
  console.log('');

  // ====================================================
  // FLOW 1: Invite existing user
  // ====================================================
  console.log('--- FLOW 1: Invite existing user ---\n');
  const page1 = await browser.newPage();

  // Capture invite token from API responses
  let inviteToken1 = null;
  page1.on('response', async (resp) => {
    if (!resp.url().includes('/api/')) return;
    try {
      const body = await resp.json().catch(() => null);
      if (!body) return;
      const bodyStr = JSON.stringify(body);
      if (resp.status() >= 200 && resp.status() < 300 && (bodyStr.includes('token') || bodyStr.includes('invite'))) {
        console.log(`  API[${resp.status()}] ${resp.url().split('/api/')[1]}: ${bodyStr.substring(0, 300)}`);
        // Extract token
        const findToken = (obj) => {
          if (typeof obj === 'string' && obj.length > 20 && /^[a-z0-9_\-]{20,}$/i.test(obj)) return obj;
          if (typeof obj === 'object' && obj !== null) {
            for (const [k, v] of Object.entries(obj)) {
              if (k === 'token' || k === 'inviteToken') {
                if (typeof v === 'string') return v;
              }
              const f = findToken(v);
              if (f) return f;
            }
          }
          return null;
        };
        const token = findToken(body);
        if (token && !inviteToken1) { inviteToken1 = token; console.log('  Captured token:', token); }
      }
    } catch (e) {}
  });

  // Step 1
  try {
    const { url } = await loginAs(page1, ADMIN_EMAIL, ADMIN_PASS);
    log(1, 'Login as admin', '/accounting', url, url.includes('/accounting') ? 'PASS' : 'FAIL',
      url.includes('/login') ? 'Invalid credentials' : '');
  } catch (e) { log(1, 'Login as admin', '/accounting', 'Error', 'FAIL', e.message); }

  // Step 2
  try {
    await page1.goto(`${BASE_URL}/accounting/user-access`);
    await page1.waitForLoadState('networkidle');
    await page1.waitForTimeout(2000);
    const url = page1.url();
    if (url.includes('/login')) {
      log(2, 'Navigate to User Access', 'User access page', 'Redirected to login', 'FAIL');
    } else {
      const text = await page1.evaluate(() => document.body.innerText.substring(0, 200));
      log(2, 'Navigate to User Access', 'User access page', url, 'PASS', text.substring(0, 100));
    }
  } catch (e) { log(2, 'Navigate to User Access', 'User access page', 'Error', 'FAIL', e.message); }

  // Step 3: Invite testinvite1
  let step3Pass = false;
  let inviteUrlForStep3 = null;
  try {
    if (results.find(r => r.step === 2)?.result !== 'PASS') {
      log(3, `Invite ${EXISTING_INVITE_EMAIL}`, 'Invitation', 'Skipped', 'FAIL');
    } else {
      // Find the invite form email input specifically (it's in a form with onSubmit)
      // Use label text to find it: "Email address" -> then next input
      const inviteFormEmail = await page1.evaluate(() => {
        // Find the invite form specifically (not the user table selects)
        const form = document.querySelector('form');
        if (form) {
          const emailInput = form.querySelector('input[type="email"]');
          return emailInput ? emailInput.id || emailInput.name || 'form-email' : null;
        }
        return null;
      });
      console.log('  Invite form email selector:', inviteFormEmail);

      // Fill email via React native setter
      await page1.evaluate((email) => {
        const forms = document.querySelectorAll('form');
        for (const form of forms) {
          const emailInput = form.querySelector('input[type="email"]');
          if (emailInput) {
            const setter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
            setter.call(emailInput, email);
            emailInput.dispatchEvent(new Event('input', { bubbles: true }));
            emailInput.dispatchEvent(new Event('change', { bubbles: true }));
            console.log('Filled invite form email');
            break;
          }
        }
      }, EXISTING_INVITE_EMAIL);

      // Set role to viewer via the form's select (not the user table selects)
      await page1.evaluate(() => {
        const forms = document.querySelectorAll('form');
        for (const form of forms) {
          const roleSelect = form.querySelector('select');
          if (roleSelect) {
            const setter = Object.getOwnPropertyDescriptor(window.HTMLSelectElement.prototype, 'value').set;
