  await page.click('button[type="submit"]');
  await page.waitForTimeout(3000);
  console.log('Login URL:', page.url());

  await page.goto(`${BASE}/accounting/user-access`);
  await page.waitForLoadState('networkidle');
  await page.waitForTimeout(2000);

  // Check what inputs exist in the invite form
  const formInfo = await page.evaluate(() => {
    const form = document.querySelector('form');
    if (!form) return 'No form';
    const inputs = Array.from(form.querySelectorAll('input, select'));
    return inputs.map(el => ({
      tag: el.tagName,
      type: el.type || '',
      placeholder: el.placeholder || '',
      value: el.value,
      reactFiberKey: Object.keys(el).find(k => k.startsWith('__reactFiber')) || 'none'
    }));
  });
  console.log('Form inputs:', JSON.stringify(formInfo, null, 2));

  // Use Playwright's native fill which properly triggers React events
  const emailInput = page.locator('form input[type="email"]');
  await emailInput.waitFor({ state: 'visible' });

  // Click to focus, then type
  await emailInput.click({ clickCount: 3 });
  await emailInput.type(INVITED, { delay: 30 });

  // Verify React state is updated
  const emailVal = await emailInput.inputValue();
  console.log('Email input value after type:', emailVal);

  // Handle role select
  const roleSelect = page.locator('form select').first();
  await roleSelect.waitFor({ state: 'visible' });
  await roleSelect.selectOption('manager');
  const roleVal = await roleSelect.inputValue();
  console.log('Role select value:', roleVal);

  // Wait a moment for React state to update
  await page.waitForTimeout(500);

  // Check React state via fiber
  const reactState = await page.evaluate(() => {
    const form = document.querySelector('form');
    if (!form) return null;
    const emailEl = form.querySelector('input[type="email"]');
    // Try to get React internal state
    const fiberKey = Object.keys(emailEl).find(k => k.startsWith('__reactFiber'));
    if (fiberKey) {
      let fiber = emailEl[fiberKey];
      // Walk up to find state hook
      while (fiber) {
        if (fiber.memoizedState) {
          return { found: true, value: emailEl.value };
        }
        fiber = fiber.return;
      }
    }
    return { value: emailEl.value };
  });
  console.log('React state check:', reactState);

  // Submit via API directly using fetch (simulating what React form would do)
  const apiResult = await page.evaluate(async (email) => {
    // Get the current session cookies are already set
    const resp = await fetch('/api/accounting/company-invitations', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ email, role: 'manager' })
    });
    const body = await resp.json();
    return { status: resp.status, body };
  }, INVITED);
  console.log('Direct API call result:', JSON.stringify(apiResult).substring(0, 400));

  await browser.close();
}
run().catch(e => console.error('Error:', e.message));
