const { chromium } = require('playwright');
const BASE = 'https://app.isaflow.co.za';

async function run() {
  const browser = await chromium.launch({ headless: true, args: ['--no-sandbox'] });
  const page = await browser.newPage();

  page.on('framenavigated', f => { if (f === page.mainFrame()) console.log('NAV:', f.url()); });

  await page.goto(`${BASE}/login`);
  await page.waitForLoadState('networkidle');
  await page.fill('input[type="email"]', 'admin@isaflow.co.za');
  await page.fill('input[type="password"]', 'admin123');
  await page.click('button[type="submit"]');
  await page.waitForTimeout(3000);
  console.log('Login URL:', page.url());

  // Test: can we navigate from /accounting to /onboarding via router.push?
  const navResult = await page.evaluate(() => {
    return new Promise((resolve) => {
      // Get the Next.js router
      const router = window.__NEXT_DATA__?.props?.pageProps?.__NEXT_ROUTER;
      console.log('Next data:', JSON.stringify(window.__NEXT_DATA__?.page));

      // Try direct router push
      const start = Date.now();
      const check = setInterval(() => {
        if (window.location.pathname === '/onboarding' || Date.now() - start > 5000) {
          clearInterval(check);
          resolve({ pathname: window.location.pathname, took: Date.now() - start });
        }
      }, 100);

      // Navigate
      window.history.pushState({}, '', '/onboarding');
      window.dispatchEvent(new PopStateEvent('popstate', { state: null }));
    });
  });
  console.log('Navigation test result:', navResult);

  // Check if window.location changed
  const locResult = await page.evaluate(() => window.location.pathname);
  console.log('Current pathname:', locResult);

  // Now test from /onboarding: can router.push go to /accounting?
  await page.goto(`${BASE}/onboarding`);
  await page.waitForLoadState('networkidle');
  await page.waitForTimeout(2000);

  // Try programmatic navigation
  const testNav = await page.evaluate(() => {
    return new Promise((resolve) => {
      const start = Date.now();

      // Try multiple navigation methods
      const results = {};

      // Method 1: window.location.href
      // DON'T do this as it causes a full reload

      // Method 2: Get next.js router instance from React fiber
      const appEl = document.querySelector('#__next');
      if (appEl) {
        const fiberKey = Object.keys(appEl).find(k => k.startsWith('__reactFiber'));
        let fiber = appEl[fiberKey];
        let router = null;
        while (fiber && !router) {
          if (fiber.memoizedProps?.router) { router = fiber.memoizedProps.router; break; }
          fiber = fiber.child || fiber.return;
        }
        results.hasRouter = !!router;
        if (router) {
          results.currentRoute = router.route;
          results.asPath = router.asPath;
        }
      }

      resolve(results);
    });
  });
  console.log('Router test:', testNav);

  await browser.close();
}
run().catch(e => console.error(e.message));
