/**
 * Smart Setup pre-step: choose between manual entry and document upload.
 */

import { useRef, useState } from 'react';
import { Keyboard, ScanLine, Upload, Loader2, CheckCircle2, AlertCircle } from 'lucide-react';
import { apiFetch } from '@/lib/apiFetch';
import type { WizardData } from './WizardSteps';

type SetFn = <K extends keyof WizardData>(k: K, v: WizardData[K]) => void;

interface Props {
  onManual: () => void;
  onExtracted: (data: Partial<WizardData>) => void;
}

type UploadState =
  | { status: 'idle' }
  | { status: 'loading' }
  | { status: 'success' }
  | { status: 'error'; message: string };

function fileToDataUrl(file: File): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload  = () => resolve(reader.result as string);
    reader.onerror = () => reject(new Error('Failed to read file'));
    reader.readAsDataURL(file);
  });
}

export function SmartSetupChoice({ onManual, onExtracted }: Props) {
  const fileRef = useRef<HTMLInputElement>(null);
  const [uploadState, setUploadState] = useState<UploadState>({ status: 'idle' });
  const [showUploadArea, setShowUploadArea] = useState(false);

  const handleFile = async (file: File) => {
    const allowed = [
      'image/jpeg', 'image/png', 'image/webp', 'image/gif',
      'application/pdf',
    ];
    if (!allowed.includes(file.type)) {
      setUploadState({ status: 'error', message: 'Please upload a JPEG, PNG, WebP, or PDF file.' });
      return;
    }
    if (file.size > 20 * 1024 * 1024) {
      setUploadState({ status: 'error', message: 'File is too large. Maximum size is 20 MB.' });
      return;
    }

    setUploadState({ status: 'loading' });

    let dataUrl: string;
    try {
      dataUrl = await fileToDataUrl(file);
    } catch {
      setUploadState({ status: 'error', message: 'Could not read the file. Please try again.' });
      return;
    }

    try {
      const res = await apiFetch('/api/onboarding/extract', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ image: dataUrl }),
      });

      const body = await res.json() as { success: boolean; data?: Partial<WizardData>; error?: { message?: string } };

      if (!res.ok || !body.success) {
        const msg = body.error?.message ?? 'AI extraction failed. Please enter details manually.';
        setUploadState({ status: 'error', message: msg });
        return;
      }

      setUploadState({ status: 'success' });

      // Brief success flash before transitioning
      setTimeout(() => {
        onExtracted(body.data ?? {});
      }, 800);
    } catch {
      setUploadState({ status: 'error', message: 'AI extraction is currently unavailable. Please enter details manually.' });
    }
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) void handleFile(file);
    // Reset so the same file can be re-selected after an error
    e.target.value = '';
  };

  const handleDrop = (e: React.DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    const file = e.dataTransfer.files[0];
    if (file) void handleFile(file);
  };

  const isLoading = uploadState.status === 'loading';
  const isSuccess = uploadState.status === 'success';

  return (
    <div className="max-w-2xl mx-auto">
      <div className="mb-6 text-center">
