/**
 * Smart Setup pre-step: choose between manual entry and document upload.
 */

import { useRef, useState } from 'react';
import { Keyboard, ScanLine, Upload, Loader2, CheckCircle2, AlertCircle } from 'lucide-react';
import { apiFetch } from '@/lib/apiFetch';
import type { WizardData } from './WizardSteps';

type SetFn = <K extends keyof WizardData>(k: K, v: WizardData[K]) => void;

interface Props {
  onManual: () => void;
  onExtracted: (data: Partial<WizardData>) => void;
}

type UploadState =
  | { status: 'idle' }
  | { status: 'loading' }
  | { status: 'success' }
  | { status: 'error'; message: string };

function fileToDataUrl(file: File): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload  = () => resolve(reader.result as string);
    reader.onerror = () => reject(new Error('Failed to read file'));
    reader.readAsDataURL(file);
  });
}

export function SmartSetupChoice({ onManual, onExtracted }: Props) {
  const fileRef = useRef<HTMLInputElement>(null);
  const [uploadState, setUploadState] = useState<UploadState>({ status: 'idle' });
  const [showUploadArea, setShowUploadArea] = useState(false);

  const handleFile = async (file: File) => {
    const allowed = [
      'image/jpeg', 'image/png', 'image/webp', 'image/gif',
      'application/pdf',
    ];
    if (!allowed.includes(file.type)) {
      setUploadState({ status: 'error', message: 'Please upload a JPEG, PNG, WebP, or PDF file.' });
      return;
    }
    if (file.size > 20 * 1024 * 1024) {
      setUploadState({ status: 'error', message: 'File is too large. Maximum size is 20 MB.' });
      return;
    }

    setUploadState({ status: 'loading' });

    let dataUrl: string;
    try {
      dataUrl = await fileToDataUrl(file);
    } catch {
      setUploadState({ status: 'error', message: 'Could not read the file. Please try again.' });
      return;
    }

    try {
      const res = await apiFetch('/api/onboarding/extract', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ image: dataUrl }),
      });

      const body = await res.json() as { success: boolean; data?: Partial<WizardData>; error?: { message?: string } };

      if (!res.ok || !body.success) {
        const msg = body.error?.message ?? 'AI extraction failed. Please enter details manually.';
        setUploadState({ status: 'error', message: msg });
        return;
      }

      setUploadState({ status: 'success' });

      // Brief success flash before transitioning
      setTimeout(() => {
        onExtracted(body.data ?? {});
      }, 800);
    } catch {
      setUploadState({ status: 'error', message: 'AI extraction is currently unavailable. Please enter details manually.' });
    }
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) void handleFile(file);
    // Reset so the same file can be re-selected after an error
    e.target.value = '';
  };

  const handleDrop = (e: React.DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    const file = e.dataTransfer.files[0];
    if (file) void handleFile(file);
  };

  const isLoading = uploadState.status === 'loading';
  const isSuccess = uploadState.status === 'success';

  return (
    <div className="max-w-2xl mx-auto">
      <div className="mb-6 text-center">
        <h2 className="text-xl font-semibold text-white">How would you like to set up?</h2>
        <p className="text-sm text-gray-400 mt-1">
          Get started in seconds with AI extraction, or fill in details yourself.
        </p>
      </div>

      {/* Choice cards */}
      {!showUploadArea && (
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
          {/* Manual entry */}
          <button
            onClick={onManual}
            className="group flex flex-col items-center gap-3 bg-gray-800 border border-gray-700 hover:border-teal-500 rounded-2xl p-6 text-center transition-all duration-200 hover:shadow-lg hover:shadow-teal-500/10"
          >
            <div className="w-12 h-12 rounded-xl bg-gray-700 group-hover:bg-teal-600/20 flex items-center justify-center transition-colors">
              <Keyboard className="w-6 h-6 text-gray-400 group-hover:text-teal-400 transition-colors" />
            </div>
            <div>
              <p className="font-semibold text-white text-sm">Type Details Manually</p>
              <p className="text-xs text-gray-400 mt-1">
                Enter your company information step by step
              </p>
            </div>
          </button>

          {/* Upload document */}
          <button
            onClick={() => setShowUploadArea(true)}
            className="group flex flex-col items-center gap-3 bg-gray-800 border border-gray-700 hover:border-teal-500 rounded-2xl p-6 text-center transition-all duration-200 hover:shadow-lg hover:shadow-teal-500/10"
          >
            <div className="w-12 h-12 rounded-xl bg-gray-700 group-hover:bg-teal-600/20 flex items-center justify-center transition-colors">
              <ScanLine className="w-6 h-6 text-gray-400 group-hover:text-teal-400 transition-colors" />
            </div>
            <div>
              <p className="font-semibold text-white text-sm">Upload Document</p>
              <p className="text-xs text-gray-400 mt-1">
                Upload a CIPC certificate or company letterhead and we&#39;ll extract the details for you
              </p>
            </div>
          </button>
        </div>
      )}

      {/* Upload area */}
      {showUploadArea && (
        <div className="bg-gray-800 border border-gray-700 rounded-2xl p-6">
          {isLoading && (
            <div className="flex flex-col items-center gap-3 py-6">
              <Loader2 className="w-10 h-10 text-teal-500 animate-spin" />
              <p className="text-sm text-gray-300 font-medium">Analysing document...</p>
              <p className="text-xs text-gray-500">This may take up to 30 seconds</p>
            </div>
          )}

          {isSuccess && (
            <div className="flex flex-col items-center gap-3 py-6">
              <CheckCircle2 className="w-10 h-10 text-teal-400" />
              <p className="text-sm text-gray-300 font-medium">Details extracted!</p>
              <p className="text-xs text-gray-500">Opening your pre-filled form...</p>
            </div>
          )}

          {!isLoading && !isSuccess && (
            <>
              <div
                onDragOver={e => e.preventDefault()}
                onDrop={handleDrop}
                className="border-2 border-dashed border-gray-600 hover:border-teal-500 rounded-xl p-10 text-center cursor-pointer transition-colors"
                onClick={() => fileRef.current?.click()}
              >
                <Upload className="w-10 h-10 text-gray-500 mx-auto mb-3" />
                <p className="text-sm text-gray-300 font-medium">
                  Drag &amp; drop your document here
                </p>
                <p className="text-xs text-gray-500 mt-1">
                  CIPC certificate, letterhead, or company registration
                </p>
                <p className="text-xs text-gray-600 mt-1">JPEG, PNG, WebP, or PDF — max 20 MB</p>
              </div>

              {uploadState.status === 'error' && (
                <div className="mt-4 flex items-start gap-2 px-3 py-2.5 bg-red-500/10 border border-red-500/30 rounded-lg">
                  <AlertCircle className="w-4 h-4 text-red-400 shrink-0 mt-0.5" />
                  <p className="text-sm text-red-400">{uploadState.message}</p>
                </div>
              )}

              <div className="flex items-center justify-between mt-4">
                <button
                  onClick={() => { setShowUploadArea(false); setUploadState({ status: 'idle' }); }}
                  className="text-sm text-gray-400 hover:text-white transition-colors"
                >
                  Back
                </button>
                <button
                  onClick={() => fileRef.current?.click()}
                  className="flex items-center gap-2 bg-teal-600 hover:bg-teal-500 text-white text-sm font-medium px-4 py-2 rounded-lg transition-colors"
                >
                  <Upload className="w-4 h-4" /> Browse files
                </button>
              </div>
            </>
          )}
        </div>
      )}

      <input
        ref={fileRef}
        type="file"
        accept="image/jpeg,image/png,image/webp,image/gif,application/pdf"
        className="hidden"
        onChange={handleInputChange}
      />

      {/* Fallback link when upload area visible */}
      {showUploadArea && !isLoading && !isSuccess && (
        <p className="text-center text-xs text-gray-500 mt-4">
          Prefer to type?{' '}
          <button onClick={onManual} className="text-teal-400 hover:text-teal-300 underline">
            Enter details manually
          </button>
        </p>
      )}
    </div>
  );
}

/**
 * POST /api/onboarding/extract
 * Accepts a base64 document image and calls the local Qwen3 VLM to
 * extract company registration details.
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';

export const config = {
  api: { bodyParser: { sizeLimit: '20mb' } },
};

// ── VLM config ────────────────────────────────────────────────────────────────

const VLM_BASE_URL  = process.env.VLLM_BASE_URL  ?? 'http://localhost:8100/v1';
const VLM_MODEL     = process.env.VLLM_MODEL      ?? 'Qwen/Qwen3-VL-8B-Instruct';
const VLM_API_KEY   = process.env.VLLM_API_KEY    ?? 'EMPTY';
const VLM_TIMEOUT   = parseInt(process.env.VLLM_TIMEOUT ?? '120000', 10);

const SYSTEM_PROMPT = `You are a document data extraction assistant specialised in South African business \
documents (CIPC certificates, letterheads, company registrations, VAT certificates). \
Extract structured company information from the provided document image and return ONLY a valid \
JSON object — no markdown, no prose, no explanation. \
If a field cannot be found, return an empty string for that field. \
Return the JSON object with exactly these keys: \
name, tradingName, registrationNumber, vatNumber, taxNumber, \
addressLine1, addressLine2, city, province, postalCode, country, \
phone, email, website.`;

const USER_PROMPT = `Extract all company details visible in this document. \
Focus on: company name, trading name, CIPC registration number, VAT number, \
income tax reference number, physical/postal address, phone, email, and website. \
Respond with only the JSON object.`;

// ── Extracted data type ───────────────────────────────────────────────────────

interface ExtractedCompany {
  name: string;
  tradingName: string;
  registrationNumber: string;
  vatNumber: string;
  taxNumber: string;
  addressLine1: string;
  addressLine2: string;
  city: string;
  province: string;
  postalCode: string;
  country: string;
  phone: string;
  email: string;
  website: string;
}

function parseVlmJson(raw: string): ExtractedCompany {
  // Strip ```json ... ``` fences if present
  const stripped = raw
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/\s*```\s*$/, '')
    .trim();

  const parsed: unknown = JSON.parse(stripped);

  if (typeof parsed !== 'object' || parsed === null) {
    throw new Error('VLM returned non-object JSON');
  }

  const obj = parsed as Record<string, unknown>;

  const str = (key: string): string =>
    typeof obj[key] === 'string' ? (obj[key] as string) : '';

  return {
    name:               str('name'),
    tradingName:        str('tradingName'),
    registrationNumber: str('registrationNumber'),
    vatNumber:          str('vatNumber'),
    taxNumber:          str('taxNumber'),
    addressLine1:       str('addressLine1'),
    addressLine2:       str('addressLine2'),
    city:               str('city'),
    province:           str('province'),
    postalCode:         str('postalCode'),
    country:            str('country') || 'South Africa',
    phone:              str('phone'),
    email:              str('email'),
    website:            str('website'),
  };
}

// ── Handler ───────────────────────────────────────────────────────────────────

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method!, ['POST']);
  }

  const { image } = req.body as { image?: unknown };

  if (typeof image !== 'string' || !image.startsWith('data:')) {
    return apiResponse.badRequest(res, 'image must be a base64 data URL string');
  }

  log.info('VLM extract request received', { size: image.length }, 'onboarding/extract');

  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), VLM_TIMEOUT);

  let vlmText: string;

  try {
    const vlmRes = await fetch(`${VLM_BASE_URL}/chat/completions`, {
      method: 'POST',
      signal: controller.signal,
      headers: {
        'Content-Type': 'application/json',
        Authorization: `Bearer ${VLM_API_KEY}`,
      },
      body: JSON.stringify({
        model: VLM_MODEL,
        messages: [
          { role: 'system', content: SYSTEM_PROMPT },
          {
            role: 'user',
            content: [
              { type: 'text',      text: USER_PROMPT },
              { type: 'image_url', image_url: { url: image } },
            ],
          },
        ],
        max_tokens: 2000,
        temperature: 0.1,
      }),
    });

    clearTimeout(timer);

    if (!vlmRes.ok) {
      const body = await vlmRes.text();
      log.error('VLM request failed', { status: vlmRes.status, body }, 'onboarding/extract');
      return apiResponse.error(
        res,
        'SERVICE_UNAVAILABLE' as never,
        'AI extraction is currently unavailable. Please enter details manually.',
      );
    }

    const vlmBody = await vlmRes.json() as {
      choices?: Array<{ message?: { content?: string } }>;
    };

    vlmText = vlmBody.choices?.[0]?.message?.content ?? '';

    if (!vlmText) {
      return apiResponse.badRequest(res, 'VLM returned an empty response');
    }
  } catch (err: unknown) {
    clearTimeout(timer);
    const isAbort = err instanceof Error && err.name === 'AbortError';
    log.error('VLM fetch error', { err }, 'onboarding/extract');
    return apiResponse.error(
      res,
      'SERVICE_UNAVAILABLE' as never,
      isAbort
        ? 'AI extraction timed out. Please try again or enter details manually.'
        : 'AI extraction is currently unavailable. Please enter details manually.',
    );
  }

  let extracted: ExtractedCompany;
  try {
    extracted = parseVlmJson(vlmText);
  } catch (parseErr) {
    log.error('VLM JSON parse error', { vlmText, parseErr }, 'onboarding/extract');
    return apiResponse.badRequest(
      res,
      'AI extraction returned an unexpected format. Please enter details manually.',
    );
  }

  log.info('VLM extract success', { name: extracted.name }, 'onboarding/extract');
  return apiResponse.success(res, extracted);
}

