/**
 * Onboarding wizard step components (Steps 1-7).
 */

import { useRef } from 'react';
import { Upload, X } from 'lucide-react';

// ── Types ───────────────────────────────────────────────────────────────────

export interface DocFile {
  type: string; name: string; data: string; mimeType: string; size: number;
}

export interface WizardData {
  name: string; tradingName: string; registrationNumber: string;
  vatNumber: string; taxNumber: string;
  addressLine1: string; addressLine2: string; city: string;
  province: string; postalCode: string; country: string;
  phone: string; email: string; website: string;
  logoData: string;
  bankName: string; bankAccountNumber: string;
  bankBranchCode: string; bankAccountType: string;
  financialYearStart: number; vatPeriod: string; defaultCurrency: string;
  documents: DocFile[];
}

export const INITIAL_WIZARD: WizardData = {
  name: '', tradingName: '', registrationNumber: '', vatNumber: '', taxNumber: '',
  addressLine1: '', addressLine2: '', city: '', province: '', postalCode: '',
  country: 'South Africa', phone: '', email: '', website: '', logoData: '',
  bankName: '', bankAccountNumber: '', bankBranchCode: '', bankAccountType: 'Current',
  financialYearStart: 3, vatPeriod: 'Bi-Monthly', defaultCurrency: 'ZAR',
  documents: [],
};

export type SetFn = <K extends keyof WizardData>(k: K, v: WizardData[K]) => void;

// ── Constants ───────────────────────────────────────────────────────────────

const PROVINCES = [
  'Eastern Cape', 'Free State', 'Gauteng', 'KwaZulu-Natal', 'Limpopo',
  'Mpumalanga', 'North West', 'Northern Cape', 'Western Cape',
];
const SA_BANKS = [
  'ABSA', 'Capitec', 'FNB', 'Investec', 'Nedbank', 'Standard Bank',
  'TymeBank', 'African Bank', 'Discovery Bank', 'Bank Zero',
];
export const MONTHS = [
  'January','February','March','April','May','June',
  'July','August','September','October','November','December',
];
export const DOC_SLOTS = [
  { type: 'cipc_certificate', label: 'CIPC Registration Certificate' },
  { type: 'tax_clearance', label: 'SARS Tax Clearance Certificate' },
  { type: 'bbbee_certificate', label: 'B-BBEE Certificate' },
  { type: 'vat_registration', label: 'VAT Registration Certificate' },
];

    e.preventDefault();
    const file = e.dataTransfer.files[0];
    if (file) void handleFile(file);
  };

  const isLoading = uploadState.status === 'loading';
  const isSuccess = uploadState.status === 'success';

  return (
    <div className="max-w-2xl mx-auto">
      <div className="mb-6 text-center">
        <h2 className="text-xl font-semibold text-white">How would you like to set up?</h2>
        <p className="text-sm text-gray-400 mt-1">
          Get started in seconds with AI extraction, or fill in details yourself.
        </p>
      </div>

      {/* Choice cards */}
      {!showUploadArea && (
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
          {/* Manual entry */}
          <button
            onClick={onManual}
            className="group flex flex-col items-center gap-3 bg-gray-800 border border-gray-700 hover:border-teal-500 rounded-2xl p-6 text-center transition-all duration-200 hover:shadow-lg hover:shadow-teal-500/10"
          >
            <div className="w-12 h-12 rounded-xl bg-gray-700 group-hover:bg-teal-600/20 flex items-center justify-center transition-colors">
              <Keyboard className="w-6 h-6 text-gray-400 group-hover:text-teal-400 transition-colors" />
            </div>
            <div>
              <p className="font-semibold text-white text-sm">Type Details Manually</p>
              <p className="text-xs text-gray-400 mt-1">
                Enter your company information step by step
              </p>
            </div>
          </button>

          {/* Upload document */}
          <button
            onClick={() => setShowUploadArea(true)}
            className="group flex flex-col items-center gap-3 bg-gray-800 border border-gray-700 hover:border-teal-500 rounded-2xl p-6 text-center transition-all duration-200 hover:shadow-lg hover:shadow-teal-500/10"
          >
            <div className="w-12 h-12 rounded-xl bg-gray-700 group-hover:bg-teal-600/20 flex items-center justify-center transition-colors">
              <ScanLine className="w-6 h-6 text-gray-400 group-hover:text-teal-400 transition-colors" />
            </div>
            <div>
              <p className="font-semibold text-white text-sm">Upload Document</p>
              <p className="text-xs text-gray-400 mt-1">
                Upload a CIPC certificate or company letterhead and we&#39;ll extract the details for you
              </p>
            </div>
          </button>
        </div>
      )}

      {/* Upload area */}
      {showUploadArea && (
        <div className="bg-gray-800 border border-gray-700 rounded-2xl p-6">
          {isLoading && (
            <div className="flex flex-col items-center gap-3 py-6">
              <Loader2 className="w-10 h-10 text-teal-500 animate-spin" />
              <p className="text-sm text-gray-300 font-medium">Analysing document...</p>
              <p className="text-xs text-gray-500">This may take up to 30 seconds</p>
            </div>
          )}

          {isSuccess && (
            <div className="flex flex-col items-center gap-3 py-6">
              <CheckCircle2 className="w-10 h-10 text-teal-400" />
              <p className="text-sm text-gray-300 font-medium">Details extracted!</p>
              <p className="text-xs text-gray-500">Opening your pre-filled form...</p>
            </div>
          )}

          {!isLoading && !isSuccess && (
            <>
              <div
                onDragOver={e => e.preventDefault()}
                onDrop={handleDrop}
                className="border-2 border-dashed border-gray-600 hover:border-teal-500 rounded-xl p-10 text-center cursor-pointer transition-colors"
                onClick={() => fileRef.current?.click()}
