export function getActiveTabId(
  pathname: string,
  query: Record<string, string | string[] | undefined>,
): string {
  if (pathname === '/accounting') return 'dashboard';
  if (pathname.startsWith('/accounting/migration')) return 'import';
  if (pathname.startsWith('/accounting/sage-migration')) return 'import';

  // Customers
  if (
    pathname.startsWith('/accounting/customers') ||
    pathname.startsWith('/accounting/customer-') ||
    pathname.startsWith('/accounting/recurring-invoices') ||
    pathname.startsWith('/accounting/credit-notes') ||
    pathname.startsWith('/accounting/write-offs') ||
    pathname.startsWith('/accounting/debtors-manager') ||
    pathname.startsWith('/accounting/ar-aging') ||
    pathname.startsWith('/accounting/statement-run') ||
    pathname.startsWith('/accounting/dunning') ||
    pathname === '/accounting/reports/sales-by-customer' ||
    pathname === '/accounting/reports/unallocated-receipts' ||
    (pathname.startsWith('/accounting/adjustments') && query.type === 'customer')
  ) {
    return 'customers';
  }

  // Suppliers
  if (
    pathname.startsWith('/accounting/suppliers') ||
    pathname.startsWith('/accounting/supplier-') ||
    pathname.startsWith('/accounting/purchase-orders') ||
    pathname.startsWith('/accounting/batch-payments') ||
    pathname.startsWith('/accounting/ap-aging') ||
    pathname === '/accounting/reports/purchases-by-supplier' ||
    pathname === '/accounting/reports/unallocated-payments' ||
    (pathname.startsWith('/accounting/adjustments') && query.type === 'supplier')
  ) {
    return 'suppliers';
  }

  // Items
  if (
    pathname.startsWith('/accounting/items') ||
    pathname.startsWith('/accounting/item-') ||
    pathname === '/accounting/reports/item-listing' ||
    pathname === '/accounting/reports/sales-by-item' ||
    pathname === '/accounting/reports/purchases-by-item' ||
    pathname === '/accounting/reports/item-movement' ||
    pathname === '/accounting/reports/item-valuation' ||
    pathname === '/accounting/reports/item-quantities'
  ) {
    return 'items';
  }

  // Banking
  if (pathname.startsWith('/accounting/bank-')) return 'banking';

  // Accounts
  if (
    pathname.startsWith('/accounting/chart-of-accounts') ||
    pathname.startsWith('/accounting/journal-entries') ||
    pathname.startsWith('/accounting/recurring-journals') ||
    pathname.startsWith('/accounting/fiscal-periods') ||
    pathname.startsWith('/accounting/default-accounts') ||
    pathname.startsWith('/accounting/currencies') ||
    pathname.startsWith('/accounting/exchange-rates')
  ) {
    return 'accounts';
  }

  // VAT
  if (
    pathname.startsWith('/accounting/vat-') ||
    pathname.startsWith('/accounting/drc-vat') ||
    pathname === '/accounting/reports/vat-return'
  ) {
    return 'vat';
  }

  // Accountant's Area
  if (
    pathname.startsWith('/accounting/trial-balance') ||
    pathname.startsWith('/accounting/opening-balances') ||
    pathname.startsWith('/accounting/assets') ||
    pathname.startsWith('/accounting/depreciation') ||
    pathname.startsWith('/accounting/year-end') ||
    pathname.startsWith('/accounting/cost-centres') ||
    pathname.startsWith('/accounting/business-units') ||
    pathname.startsWith('/accounting/budgets') ||
    pathname === '/accounting/reports/audit-trail'
  ) {
    return 'accountants';
  }

  // Group
  if (pathname.startsWith('/accounting/group')) return 'group';

  // SARS
  if (pathname.startsWith('/accounting/sars')) return 'sars';

  // Tools
  if (
    pathname.startsWith('/accounting/document-capture') ||
    pathname.startsWith('/accounting/approvals') ||
    pathname.startsWith('/accounting/company-settings') ||
    pathname.startsWith('/accounting/my-account') ||
    pathname.startsWith('/accounting/cash-flow-forecast') ||
    pathname.startsWith('/accounting/time-tracking') ||
    pathname.startsWith('/accounting/user-access')
  ) {
    return 'tools';
  }

  if (pathname.startsWith('/accounting/reports')) return 'reports';

  // Payroll
  if (pathname.startsWith('/payroll')) return 'payroll';

  return 'dashboard';
}

export function isLinkActive(href: string, asPath: string): boolean {
  const parts = href.split('?');
  const itemPath = parts[0] as string;
  const qs = parts[1];
  return asPath.startsWith(itemPath) && (!qs || asPath.includes(qs));
}

/**
 * /register — Create a new ISAFlow account.
 * Supports ?invite=[token] to pre-fill email and show an invite banner.
 * On success, redirects to /login with a success banner (preserving invite token).
 */

import { useState, useEffect, FormEvent } from 'react';
import { useRouter } from 'next/router';
import Link from 'next/link';
import { Eye, EyeOff, Building2 } from 'lucide-react';
import { LoadingSpinner } from '@/components/ui/LoadingSpinner';

interface StrengthResult {
  score: number;
  label: string;
  hint: string;
}

function checkClientPasswordStrength(password: string): StrengthResult {
  if (password.length < 8) {
    return { score: 0, label: 'Too short', hint: 'Must be at least 8 characters' };
  }

  let score = 1;

  const hasLower = /[a-z]/.test(password);
  const hasUpper = /[A-Z]/.test(password);
  if (hasLower && hasUpper) score = 2;
  else {
    return { score: 1, label: 'Weak', hint: 'Add uppercase and lowercase letters' };
  }

  const hasNumber = /[0-9]/.test(password);
  if (hasNumber) score = 3;
  else {
    return { score: 2, label: 'Fair', hint: 'Add a number' };
  }

  const hasSpecial = /[^a-zA-Z0-9]/.test(password);
  if (hasSpecial) score = 4;
  else {
    return { score: 3, label: 'Good', hint: 'Add a special character for maximum strength' };
  }

  return { score: 4, label: 'Strong', hint: '' };
}

interface InviteData {
  email: string;
  companyName: string;
  role: string;
}

const STRENGTH_COLORS = ['bg-red-500', 'bg-red-500', 'bg-yellow-500', 'bg-green-500', 'bg-teal-500'];

export default function RegisterPage() {
  const router = useRouter();

  const inviteToken =
    typeof router.query.invite === 'string' ? router.query.invite : null;

  const [firstName, setFirstName] = useState('');
  const [lastName, setLastName] = useState('');
  const [email, setEmail] = useState('');
  const [emailLocked, setEmailLocked] = useState(false);
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirm, setShowConfirm] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState('');
  const [inviteData, setInviteData] = useState<InviteData | null>(null);

  const strength = password ? checkClientPasswordStrength(password) : null;

  // Load invite data when token is present
  useEffect(() => {
    if (!inviteToken) return;

    fetch(`/api/invite/${inviteToken}`)
      .then((r) => (r.ok ? r.json() : null))
      .then((json) => {
        if (json?.data) {
          const data = json.data as InviteData;
          setInviteData(data);
          setEmail(data.email);
          setEmailLocked(true);
        }
      })
      .catch(() => null);
  }, [inviteToken]);

  const handleSubmit = async (e: FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setError('');
    setSubmitting(true);

    try {
      const res = await fetch('/api/auth/register', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          firstName: firstName.trim(),
          lastName: lastName.trim(),
          email: email.trim().toLowerCase(),
          password,
          confirmPassword,
        }),
      });

      const data = await res.json();

      if (!res.ok) {
        setError(data.error?.message || data.message || 'Registration failed');
        return;
      }

      // Redirect to login, preserving invite token so the banner shows
      const loginUrl = inviteToken
        ? `/login?registered=1&invite=${inviteToken}`
        : '/login?registered=1';
      await router.push(loginUrl);
    } catch {
      setError('Network error. Please try again.');
    } finally {
      setSubmitting(false);
    }
  };

  const canSubmit = firstName && lastName && email && password && confirmPassword && !submitting;

  return (
    <div className="min-h-screen bg-gray-950 flex items-center justify-center px-4">
      <div className="w-full max-w-sm">

        {/* Logo */}
        <div className="flex flex-col items-center mb-8">
          <img src="/logo.png" alt="ISAFlow" className="h-16 w-auto brightness-0 invert mb-4" />
          <p className="text-sm text-gray-500 mt-1">Create your account</p>
        </div>

        {/* Invite banner */}
        {inviteData && (
          <div className="mb-4 px-4 py-3 bg-teal-900/30 border border-teal-700/50 rounded-lg flex items-start gap-3">
            <Building2 className="h-4 w-4 text-teal-400 mt-0.5 flex-shrink-0" />
            <p className="text-sm text-teal-300">
              Create an account to join{' '}
              <span className="font-medium text-white">{inviteData.companyName}</span>
              {' '}as <span className="font-medium">{inviteData.role}</span>.
            </p>
          </div>
        )}

        {/* Card */}
        <div className="bg-gray-900 border border-gray-700 rounded-2xl p-6 shadow-xl">
          <form onSubmit={(e) => void handleSubmit(e)} noValidate>

            {/* First Name + Last Name */}
            <div className="flex gap-3 mb-4">
              <div className="flex-1">
                <label htmlFor="firstName" className="block text-xs font-medium text-gray-400 mb-1.5">
                  First name
                </label>
                <input
                  id="firstName"
                  type="text"
                  autoComplete="given-name"
                  required
                  value={firstName}
                  onChange={e => { setError(''); setFirstName(e.target.value); }}
                  disabled={submitting}
                  className="w-full bg-gray-800 border border-gray-600 rounded-lg px-3 py-2.5 text-sm text-white placeholder-gray-500 focus:outline-none focus:ring-2 focus:ring-teal-500 focus:border-transparent disabled:opacity-50 transition"
                  placeholder="John"
                />
              </div>
              <div className="flex-1">
                <label htmlFor="lastName" className="block text-xs font-medium text-gray-400 mb-1.5">
                  Last name
                </label>
                <input
                  id="lastName"
                  type="text"
                  autoComplete="family-name"
                  required
                  value={lastName}
                  onChange={e => { setError(''); setLastName(e.target.value); }}
                  disabled={submitting}
                  className="w-full bg-gray-800 border border-gray-600 rounded-lg px-3 py-2.5 text-sm text-white placeholder-gray-500 focus:outline-none focus:ring-2 focus:ring-teal-500 focus:border-transparent disabled:opacity-50 transition"
                  placeholder="Doe"
                />
              </div>
            </div>

            {/* Email */}
            <div className="mb-4">
              <label htmlFor="email" className="block text-xs font-medium text-gray-400 mb-1.5">
                Email address
              </label>
              <input
                id="email"
                type="email"
                autoComplete="email"
                required
                value={email}
                onChange={e => { setError(''); setEmail(e.target.value); }}
                disabled={submitting || emailLocked}
                readOnly={emailLocked}
                className={`w-full bg-gray-800 border rounded-lg px-3 py-2.5 text-sm text-white placeholder-gray-500 focus:outline-none focus:ring-2 focus:ring-teal-500 focus:border-transparent transition ${
                  emailLocked
                    ? 'border-teal-700/50 text-gray-400 cursor-not-allowed'
                    : 'border-gray-600 disabled:opacity-50'
                }`}
                placeholder="you@example.com"
              />
              {emailLocked && (
                <p className="mt-1 text-xs text-gray-500">
                  Email address is set by the invitation.
                </p>
              )}
            </div>

            {/* Password */}
            <div className="mb-4">
              <label htmlFor="password" className="block text-xs font-medium text-gray-400 mb-1.5">
                Password
              </label>
              <div className="relative">
                <input
                  id="password"
                  type={showPassword ? 'text' : 'password'}
                  autoComplete="new-password"
                  required
                  value={password}
                  onChange={e => { setError(''); setPassword(e.target.value); }}
                  disabled={submitting}
                  className="w-full bg-gray-800 border border-gray-600 rounded-lg px-3 py-2.5 pr-10 text-sm text-white placeholder-gray-500 focus:outline-none focus:ring-2 focus:ring-teal-500 focus:border-transparent disabled:opacity-50 transition"
                  placeholder="Choose a password"
                />
                <button
                  type="button"
                  tabIndex={-1}
                  onClick={() => setShowPassword(v => !v)}
                  className="absolute inset-y-0 right-0 flex items-center px-3 text-gray-500 hover:text-gray-300 transition-colors"
                  aria-label={showPassword ? 'Hide password' : 'Show password'}
                >
                  {showPassword ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
                </button>
              </div>

              {/* Password strength indicator */}
              {password && strength && (
                <div className="mt-2">
                  <div className="flex gap-1 mb-1">
                    {[0, 1, 2, 3].map(i => (
                      <div
                        key={i}
                        className={`h-1 flex-1 rounded-full transition-colors ${
                          i < strength.score ? STRENGTH_COLORS[strength.score] : 'bg-gray-700'
                        }`}
                      />
                    ))}
                  </div>
                  {strength.hint && (
                    <p className="text-xs text-gray-500">{strength.hint}</p>
                  )}
                </div>
              )}
            </div>

            {/* Confirm Password */}
            <div className="mb-6">
              <label htmlFor="confirmPassword" className="block text-xs font-medium text-gray-400 mb-1.5">
                Confirm password
              </label>
              <div className="relative">
                <input
                  id="confirmPassword"
                  type={showConfirm ? 'text' : 'password'}
                  autoComplete="new-password"
                  required
                  value={confirmPassword}
                  onChange={e => { setError(''); setConfirmPassword(e.target.value); }}
                  disabled={submitting}
                  className="w-full bg-gray-800 border border-gray-600 rounded-lg px-3 py-2.5 pr-10 text-sm text-white placeholder-gray-500 focus:outline-none focus:ring-2 focus:ring-teal-500 focus:border-transparent disabled:opacity-50 transition"
                  placeholder="Confirm your password"
                />
                <button
                  type="button"
                  tabIndex={-1}
                  onClick={() => setShowConfirm(v => !v)}
                  className="absolute inset-y-0 right-0 flex items-center px-3 text-gray-500 hover:text-gray-300 transition-colors"
                  aria-label={showConfirm ? 'Hide password' : 'Show password'}
                >
                  {showConfirm ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
                </button>
              </div>
            </div>

            {/* Error message */}
            {error && (
              <div className="mb-4 px-3 py-2.5 bg-red-500/10 border border-red-500/30 rounded-lg">
                <p className="text-sm text-red-400">{error}</p>
              </div>
            )}

            {/* Submit */}
            <button
              type="submit"
              disabled={!canSubmit}
              className="w-full flex items-center justify-center gap-2 bg-teal-600 hover:bg-teal-500 disabled:bg-teal-800 disabled:cursor-not-allowed text-white font-medium text-sm px-4 py-2.5 rounded-lg transition-colors"
            >
              {submitting ? (
                <>
                  <LoadingSpinner size="sm" />
                  <span>Creating account...</span>
                </>
              ) : (
                'Create Account'
              )}
            </button>
          </form>
        </div>

        {/* Footer link */}
        <p className="text-center text-sm text-gray-500 mt-6">
          Already have an account?{' '}
          <Link
            href={inviteToken ? `/login?invite=${inviteToken}` : '/login'}
            className="text-teal-400 hover:text-teal-300 transition-colors"
          >
            Sign in
          </Link>
        </p>

      </div>
    </div>
  );
}

/**
 * /onboarding — 7-step company setup wizard with Smart Setup pre-step.
 * Standalone layout (no AppLayout), matches login dark theme.
 */

import { useState, useEffect, useCallback } from 'react';
import { useRouter } from 'next/router';
import {
  Check, Building2, MapPin, Image, Landmark,
  Settings, FileText, ChevronLeft, ChevronRight, Loader2,
} from 'lucide-react';
import { apiFetch } from '@/lib/apiFetch';
import {
  type WizardData, INITIAL_WIZARD, MONTHS, DOC_SLOTS,
  Step1, Step2, Step3, Step4, Step5, Step6, Step7,
} from '@/components/onboarding/WizardSteps';
import { SmartSetupChoice } from '@/components/onboarding/SmartSetupChoice';

const STEPS = [
  { icon: Building2, title: 'Company Details',       sub: 'Tell us about your business' },
  { icon: MapPin,    title: 'Address & Contact',      sub: 'Where can we reach you?' },
  { icon: Image,     title: 'Logo Upload',            sub: 'Brand your workspace' },
  { icon: Landmark,  title: 'Banking Details',        sub: 'Your primary bank account' },
  { icon: Settings,  title: 'Financial Preferences',  sub: 'Year-end, VAT & currency' },
  { icon: FileText,  title: 'Statutory Documents',    sub: 'Upload key certificates' },
  { icon: Check,     title: 'Review & Complete',      sub: 'Confirm and get started' },
];

export default function OnboardingWizard() {
  const router = useRouter();

  // step === -1 is the Smart Setup pre-step (choice screen)
  const [step, setStep]             = useState(-1);
  const [d, setD]                   = useState<WizardData>(INITIAL_WIZARD);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError]           = useState('');
  const [authChecked, setAuthChecked] = useState(false);

  // Auth check — then verify user doesn't already have companies (e.g. via invitation)
  useEffect(() => {
    apiFetch('/api/auth/me').then(async (r) => {
      if (!r.ok) { void router.replace('/login'); return; }
      const body = await r.json();
      if (body.data?.onboardingCompleted) { void router.replace('/accounting'); return; }

      // Invited users already have a company — skip onboarding for them
      try {
        const compRes = await apiFetch('/api/accounting/companies?action=user-companies');
        if (compRes.ok) {
          const compBody = await compRes.json();
          const companies: unknown[] = compBody.data ?? [];
          if (companies.length > 0) {
            await apiFetch('/api/onboarding/complete', { method: 'POST' });
            void router.replace('/accounting');
            return;
          }
        }
      } catch {
        // Non-fatal — fall through to show the wizard
      }

      setAuthChecked(true);
    }).catch(() => void router.replace('/login'));
  }, [router]);

  const set = useCallback(<K extends keyof WizardData>(k: K, v: WizardData[K]) => {
    setD(prev => ({ ...prev, [k]: v }));
  }, []);

  // Smart Setup: merge extracted fields and jump to step 0
  const handleExtracted = useCallback((extracted: Partial<WizardData>) => {
    setD(prev => ({ ...prev, ...extracted }));
    setStep(0);
  }, []);

  const hasCipc     = d.documents.some(doc => doc.type === 'cipc_certificate');
  const canContinue = step === 0 ? d.name.trim().length > 0
                    : step === 5 ? hasCipc   // CIPC is required on documents step
                    : true;
  const isLast      = step === STEPS.length - 1;
  const skippable   = step >= 1 && step <= 4; // steps 1-4 skippable, step 5 (documents) not
  const isPreStep   = step === -1;

  const next = () => { if (canContinue) setStep(s => Math.min(s + 1, STEPS.length - 1)); };
  const back = () => setStep(s => Math.max(s - 1, 0));

  const handleSubmit = async () => {
    setSubmitting(true);
    setError('');
    try {
      // 1. Create company
      const compRes = await apiFetch('/api/accounting/companies', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          name: d.name, tradingName: d.tradingName,
          registrationNumber: d.registrationNumber, vatNumber: d.vatNumber,
          taxNumber: d.taxNumber, addressLine1: d.addressLine1,
          addressLine2: d.addressLine2, city: d.city, province: d.province,
          postalCode: d.postalCode, country: d.country, phone: d.phone,
          email: d.email, website: d.website, logoData: d.logoData || undefined,
          bankName: d.bankName || undefined,
          bankAccountNumber: d.bankAccountNumber || undefined,
          bankBranchCode: d.bankBranchCode || undefined,
          bankAccountType: d.bankAccountType,
          financialYearStart: d.financialYearStart,
          vatPeriod: d.vatPeriod, defaultCurrency: d.defaultCurrency,
        }),
      });
      if (!compRes.ok) {
        const body = await compRes.json();
        throw new Error(body.error?.message || 'Failed to create company');
      }
      const compData = await compRes.json();
      const companyId = compData.data?.id;

      // 2. Upload documents (non-blocking — company is already created)
      if (d.documents.length > 0 && companyId) {
        try {
          await apiFetch('/api/onboarding/documents', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ companyId, documents: d.documents }),
          });
        } catch {
          // Document upload failure is non-critical — user can upload later
        }
      }

      // 3. Mark onboarding complete
      await apiFetch('/api/onboarding/complete', { method: 'POST' });

      // 4. Navigate — full reload so the middleware picks up the new ff_onboarding_done cookie
      window.location.href = '/accounting';
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Something went wrong');
      setSubmitting(false);
    }
  };

  if (!authChecked) {
    return (
      <div className="min-h-screen bg-gray-950 flex items-center justify-center">
        <Loader2 className="w-8 h-8 text-teal-500 animate-spin" />
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-950 text-white px-4 py-8">
      {/* Logo */}
      <div className="max-w-2xl mx-auto mb-8">
        <img src="/logo.png" alt="ISAFlow" className="h-10 w-auto brightness-0 invert" />
      </div>

      {/* Progress — only shown during the 7-step wizard (step 0-6) */}
      {!isPreStep && (
        <div className="max-w-2xl mx-auto mb-8">
          <div className="flex items-center justify-between">
            {STEPS.map((s, i) => (
              <div key={i} className="flex items-center flex-1 last:flex-none">
                <button
                  onClick={() => i < step && setStep(i)}
                  disabled={i > step}
                  className={`w-9 h-9 rounded-full flex items-center justify-center text-sm font-medium shrink-0 transition-colors ${
                    i < step  ? 'bg-teal-600 text-white cursor-pointer' :
                    i === step ? 'bg-teal-500 text-white ring-2 ring-teal-400' :
                    'bg-gray-800 text-gray-500'
                  }`}
                >
                  {i < step ? <Check className="w-4 h-4" /> : i + 1}
                </button>
                {i < STEPS.length - 1 && (
                  <div className={`h-0.5 flex-1 mx-1 ${i < step ? 'bg-teal-600' : 'bg-gray-800'}`} />
                )}
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Pre-step: Smart Setup choice */}
      {isPreStep && (
        <SmartSetupChoice
          onManual={() => setStep(0)}
          onExtracted={handleExtracted}
        />
      )}

      {/* Wizard card */}
      {!isPreStep && (
        <div className="max-w-2xl mx-auto">
          <div className="mb-4">
            <h2 className="text-xl font-semibold">{STEPS[step]?.title}</h2>
            <p className="text-sm text-gray-400">{STEPS[step]?.sub}</p>
          </div>

          <div className="bg-gray-900 border border-gray-700 rounded-2xl p-6 shadow-xl min-h-[320px]">
            {step === 0 && <Step1 d={d} set={set} />}
            {step === 1 && <Step2 d={d} set={set} />}
            {step === 2 && <Step3 d={d} set={set} />}
            {step === 3 && <Step4 d={d} set={set} />}
            {step === 4 && <Step5 d={d} set={set} />}
            {step === 5 && <Step6 d={d} set={set} />}
            {step === 6 && <Step7 d={d} />}
          </div>

          {/* Error */}
          {error && (
            <div className="mt-4 px-3 py-2.5 bg-red-500/10 border border-red-500/30 rounded-lg">
              <p className="text-sm text-red-400">{error}</p>
            </div>
          )}

          {/* Navigation */}
          <div className="flex justify-between mt-6">
            <button
              onClick={step === 0 ? () => setStep(-1) : back}
              className="flex items-center gap-1.5 text-sm text-gray-400 hover:text-white transition-colors"
            >
              <ChevronLeft className="w-4 h-4" /> Back
            </button>
            <div className="flex gap-3">
              {skippable && !isLast && (
                <button onClick={next} className="text-sm text-gray-400 hover:text-white transition-colors">
                  Skip
                </button>
              )}
              {isLast ? (
                <button
                  onClick={() => void handleSubmit()}
                  disabled={submitting}
                  className="flex items-center gap-2 bg-teal-600 hover:bg-teal-500 disabled:bg-teal-800 text-white font-medium text-sm px-6 py-2.5 rounded-lg transition-colors"
                >
                  {submitting ? <><Loader2 className="w-4 h-4 animate-spin" /> Saving...</> : 'Complete Setup'}
                </button>
              ) : (
                <button
                  onClick={next}
                  disabled={!canContinue}
                  className="flex items-center gap-1.5 bg-teal-600 hover:bg-teal-500 disabled:bg-teal-800 disabled:cursor-not-allowed text-white font-medium text-sm px-5 py-2.5 rounded-lg transition-colors"
                >
                  Continue <ChevronRight className="w-4 h-4" />
                </button>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

/**
 * Onboarding wizard step components (Steps 1-7).
 */

import { useRef } from 'react';
import { Upload, X } from 'lucide-react';

// ── Types ───────────────────────────────────────────────────────────────────

export interface DocFile {
  type: string; name: string; data: string; mimeType: string; size: number;
}

export interface Director {
  name: string;
  idNumber: string;
  role: string; // e.g. 'Director', 'Managing Director', 'Member'
}

export interface WizardData {
  name: string; tradingName: string; registrationNumber: string;
  vatNumber: string; taxNumber: string;
  addressLine1: string; addressLine2: string; city: string;
  province: string; postalCode: string; country: string;
  phone: string; email: string; website: string;
  logoData: string;
  bankName: string; bankAccountNumber: string;
  bankBranchCode: string; bankAccountType: string;
  financialYearStart: number; vatPeriod: string; defaultCurrency: string;
  directors: Director[];
  documents: DocFile[];
}

export const INITIAL_WIZARD: WizardData = {
  name: '', tradingName: '', registrationNumber: '', vatNumber: '', taxNumber: '',
  addressLine1: '', addressLine2: '', city: '', province: '', postalCode: '',
  country: 'South Africa', phone: '', email: '', website: '', logoData: '',
  bankName: '', bankAccountNumber: '', bankBranchCode: '', bankAccountType: 'Current',
  financialYearStart: 3, vatPeriod: 'Bi-Monthly', defaultCurrency: 'ZAR',
  directors: [],
  documents: [],
};

export type SetFn = <K extends keyof WizardData>(k: K, v: WizardData[K]) => void;

// ── Constants ───────────────────────────────────────────────────────────────

const PROVINCES = [
  'Eastern Cape', 'Free State', 'Gauteng', 'KwaZulu-Natal', 'Limpopo',
  'Mpumalanga', 'North West', 'Northern Cape', 'Western Cape',
];
const SA_BANKS = [
  'ABSA', 'Capitec', 'FNB', 'Investec', 'Nedbank', 'Standard Bank',
  'TymeBank', 'African Bank', 'Discovery Bank', 'Bank Zero',
];
export const MONTHS = [
  'January','February','March','April','May','June',
  'July','August','September','October','November','December',
];
export const DOC_SLOTS = [
  { type: 'cipc_certificate', label: 'CIPC Registration Certificate', required: true },
  { type: 'tax_clearance', label: 'SARS Tax Clearance Certificate', required: false },
  { type: 'bbbee_certificate', label: 'B-BBEE Certificate', required: false },
  { type: 'vat_registration', label: 'VAT Registration Certificate', required: false },
  { type: 'director_id', label: 'Director ID / Passport Copy', required: false },
];
const DIRECTOR_ROLES = ['Director', 'Managing Director', 'Member', 'Chairperson', 'Secretary'];

// ── Shared UI ───────────────────────────────────────────────────────────────

const inputCls = 'w-full bg-gray-800 border border-gray-600 rounded-lg px-3 py-2.5 text-sm text-white placeholder-gray-500 focus:outline-none focus:ring-2 focus:ring-teal-500 focus:border-transparent transition';
const labelCls = 'block text-xs font-medium text-gray-400 mb-1.5';

function Field({ label, value, onChange, placeholder, required, type = 'text' }: {
  label: string; value: string; onChange: (v: string) => void;
  placeholder?: string; required?: boolean; type?: string;
}) {
  return (
    <div>
      <label className={labelCls}>{label}{required && <span className="text-red-400 ml-0.5">*</span>}</label>
      <input type={type} value={value} onChange={e => onChange(e.target.value)}
        placeholder={placeholder} className={inputCls} />
    </div>
  );
}

function Select({ label, value, onChange, children }: {
  label: string; value: string | number; onChange: (v: string) => void;
  children: React.ReactNode;
}) {
  return (
    <div>
      <label className={labelCls}>{label}</label>
      <select value={value} onChange={e => onChange(e.target.value)} className={inputCls}>
        {children}
      </select>
    </div>
  );
}

// ── Step 1: Company Details ─────────────────────────────────────────────────

export function Step1({ d, set }: { d: WizardData; set: SetFn }) {
  const addDirector = () => set('directors', [...d.directors, { name: '', idNumber: '', role: 'Director' }]);
  const updateDirector = (i: number, field: keyof Director, val: string) => {
    const updated = d.directors.map((dir, idx) => idx === i ? { ...dir, [field]: val } : dir);
    set('directors', updated);
  };
  const removeDirector = (i: number) => set('directors', d.directors.filter((_, idx) => idx !== i));

  return (
    <div className="grid gap-4">
      <Field label="Company Name" value={d.name} onChange={v => set('name', v)} placeholder="Acme (Pty) Ltd" required />
      <Field label="Trading Name" value={d.tradingName} onChange={v => set('tradingName', v)} placeholder="Acme" />
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
        <Field label="Registration Number (CIPC)" value={d.registrationNumber} onChange={v => set('registrationNumber', v)} />
        <Field label="VAT Number" value={d.vatNumber} onChange={v => set('vatNumber', v)} />
        <Field label="Income Tax Number" value={d.taxNumber} onChange={v => set('taxNumber', v)} />
      </div>

      {/* Directors */}
      <div className="mt-2">
        <div className="flex items-center justify-between mb-2">
          <label className={labelCls}>Directors / Members</label>
          <button type="button" onClick={addDirector}
            className="text-xs text-teal-400 hover:text-teal-300 transition-colors">
            + Add Director
          </button>
        </div>
        {d.directors.length === 0 && (
          <p className="text-xs text-gray-500">No directors added yet.</p>
        )}
        {d.directors.map((dir, i) => (
          <div key={i} className="grid grid-cols-[1fr_1fr_auto_auto] gap-2 mb-2 items-end">
            <div>
              {i === 0 && <label className="block text-xs text-gray-500 mb-1">Full Name</label>}
              <input value={dir.name} onChange={e => updateDirector(i, 'name', e.target.value)}
                placeholder="Full name" className={inputCls} />
            </div>
            <div>
              {i === 0 && <label className="block text-xs text-gray-500 mb-1">ID / Passport Number</label>}
              <input value={dir.idNumber} onChange={e => updateDirector(i, 'idNumber', e.target.value)}
                placeholder="ID number" className={inputCls} />
            </div>
            <div>
              {i === 0 && <label className="block text-xs text-gray-500 mb-1">Role</label>}
              <select value={dir.role} onChange={e => updateDirector(i, 'role', e.target.value)} className={inputCls}>
                {DIRECTOR_ROLES.map(r => <option key={r} value={r}>{r}</option>)}
              </select>
            </div>
            <button type="button" onClick={() => removeDirector(i)}
              className="text-red-400 hover:text-red-300 p-2">
              <X className="w-4 h-4" />
            </button>
          </div>
        ))}
      </div>
    </div>
  );
}

// ── Step 2: Address & Contact ───────────────────────────────────────────────

export function Step2({ d, set }: { d: WizardData; set: SetFn }) {
  return (
    <div className="grid gap-4">
      <Field label="Address Line 1" value={d.addressLine1} onChange={v => set('addressLine1', v)} />
      <Field label="Address Line 2" value={d.addressLine2} onChange={v => set('addressLine2', v)} />
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
        <Field label="City" value={d.city} onChange={v => set('city', v)} />
        <Select label="Province" value={d.province} onChange={v => set('province', v)}>
          <option value="">Select...</option>
          {PROVINCES.map(p => <option key={p} value={p}>{p}</option>)}
        </Select>
        <Field label="Postal Code" value={d.postalCode} onChange={v => set('postalCode', v)} />
      </div>
      <Field label="Country" value={d.country} onChange={v => set('country', v)} />
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
        <Field label="Phone" value={d.phone} onChange={v => set('phone', v)} type="tel" />
        <Field label="Email" value={d.email} onChange={v => set('email', v)} type="email" />
        <Field label="Website" value={d.website} onChange={v => set('website', v)} />
      </div>
    </div>
  );
}

// ── Step 3: Logo Upload ─────────────────────────────────────────────────────

export function Step3({ d, set }: { d: WizardData; set: SetFn }) {
  const fileRef = useRef<HTMLInputElement>(null);

  const handleFile = (file: File) => {
    if (!file.type.match(/^image\/(jpeg|png|webp)$/)) return;
    if (file.size > 2 * 1024 * 1024) return;
    const reader = new FileReader();
    reader.onload = () => set('logoData', reader.result as string);
    reader.readAsDataURL(file);
  };

  return (
    <div className="flex flex-col items-center gap-4">
      {d.logoData ? (
        <div className="relative">
          <img src={d.logoData} alt="Logo" className="w-32 h-32 rounded-lg object-contain bg-gray-800" />
          <button onClick={() => set('logoData', '')}
