/**
 * /invite/[token] — Invitation landing page.
 * Public page (no AppLayout). Validates the token and lets the user
 * sign in, register, or (if already logged in) accept directly.
 */

import { useEffect, useState } from 'react';
import { useRouter } from 'next/router';
import Link from 'next/link';
import { Building2, UserCheck, LogIn, UserPlus, AlertTriangle, Loader2 } from 'lucide-react';
import { LoadingSpinner } from '@/components/ui/LoadingSpinner';

interface InviteData {
  email: string;
  companyName: string;
  role: string;
  invitedBy: string;
}

interface AuthUser {
  id: string;
  email: string;
}

type PageState = 'loading' | 'valid' | 'invalid' | 'accepting' | 'accepted' | 'error';

const ROLE_LABELS: Record<string, string> = {
  owner: 'Owner', admin: 'Administrator', manager: 'Manager', viewer: 'Viewer',
};

export default function InvitePage() {
  const router = useRouter();
  const { token } = router.query as { token?: string };

  const [pageState, setPageState] = useState<PageState>('loading');
  const [inviteData, setInviteData] = useState<InviteData | null>(null);
  const [currentUser, setCurrentUser] = useState<AuthUser | null>(null);
  const [errorMsg, setErrorMsg] = useState('');

  // Load invite info + check current auth state in parallel
  useEffect(() => {
    if (!token) return;

    async function load() {
      try {
        const [inviteRes, meRes] = await Promise.all([
          fetch(`/api/invite/${token}`),
          fetch('/api/auth/me'),
        ]);

        if (!inviteRes.ok) {
          setPageState('invalid');
          return;
        }

        const inviteJson = await inviteRes.json() as { data: InviteData };
        setInviteData(inviteJson.data);

        if (meRes.ok) {
          const meJson = await meRes.json() as { data: { user: AuthUser } };
          setCurrentUser(meJson.data?.user ?? null);
        }

        setPageState('valid');
      } catch {
        setPageState('error');
        setErrorMsg('Failed to load invitation. Please try again.');
      }
    }

    void load();
  }, [token]);

  async function handleAccept() {
    if (!token) return;
    setPageState('accepting');

    try {
      const res = await fetch(`/api/invite/${token}`, { method: 'POST' });
      const json = await res.json() as { success: boolean; error?: { message: string } };

      if (!res.ok) {
        setErrorMsg(json.error?.message ?? 'Failed to accept invitation');
        setPageState('error');
        return;
      }

      setPageState('accepted');
      // Give a moment to show success, then redirect
      setTimeout(() => { void router.push('/accounting'); }, 1500);
    } catch {
      setErrorMsg('Network error. Please try again.');
      setPageState('error');
    }
  }

  const roleLabel = inviteData ? (ROLE_LABELS[inviteData.role] ?? inviteData.role) : '';

  return (
    <div className="min-h-screen bg-gray-950 flex items-center justify-center px-4">
      <div className="w-full max-w-md">

        {/* Logo */}
        <div className="flex flex-col items-center mb-8">
          <img src="/logo.png" alt="ISAFlow" className="h-16 w-auto brightness-0 invert mb-4" />
        </div>

        {/* Loading state */}
        {pageState === 'loading' && (
          <div className="flex items-center justify-center py-16">
            <LoadingSpinner size="lg" />
          </div>
        )}

        {/* Invalid token */}
        {pageState === 'invalid' && (
          <div className="bg-gray-900 border border-gray-700 rounded-2xl p-8 text-center shadow-xl">
            <AlertTriangle className="h-12 w-12 text-amber-400 mx-auto mb-4" />
            <h1 className="text-xl font-bold text-white mb-2">Invitation Not Found</h1>
            <p className="text-gray-400 text-sm mb-6">
              This invitation link is invalid, has already been used, or has expired.
            </p>
            <Link
              href="/login"
              className="inline-block rounded-lg bg-teal-600 px-6 py-2.5 text-sm font-medium text-white hover:bg-teal-500 transition-colors"
            >
              Go to Sign In
            </Link>
          </div>
        )}

        {/* Error state */}
        {pageState === 'error' && (
          <div className="bg-gray-900 border border-red-800 rounded-2xl p-8 text-center shadow-xl">
            <AlertTriangle className="h-12 w-12 text-red-400 mx-auto mb-4" />
            <h1 className="text-xl font-bold text-white mb-2">Something Went Wrong</h1>
            <p className="text-gray-400 text-sm mb-6">{errorMsg}</p>
            <button
              onClick={() => window.location.reload()}
              className="rounded-lg bg-gray-700 px-6 py-2.5 text-sm font-medium text-white hover:bg-gray-600 transition-colors"
            >
              Try Again
            </button>
          </div>
        )}

        {/* Accepted */}
        {pageState === 'accepted' && (
          <div className="bg-gray-900 border border-teal-700 rounded-2xl p-8 text-center shadow-xl">
            <UserCheck className="h-12 w-12 text-teal-400 mx-auto mb-4" />
            <h1 className="text-xl font-bold text-white mb-2">Welcome Aboard!</h1>
            <p className="text-gray-400 text-sm">
              You have joined{' '}
              <span className="text-white font-medium">{inviteData?.companyName}</span>.
              Redirecting to your dashboard…
            </p>
          </div>
        )}

        {/* Valid invitation card */}
        {(pageState === 'valid' || pageState === 'accepting') && inviteData && (
          <div className="bg-gray-900 border border-gray-700 rounded-2xl shadow-xl overflow-hidden">

            {/* Header */}
            <div className="bg-teal-900/30 border-b border-teal-800/50 px-6 py-5 text-center">
              <Building2 className="h-10 w-10 text-teal-400 mx-auto mb-3" />
              <h1 className="text-xl font-bold text-white mb-1">You&apos;re Invited!</h1>
              <p className="text-sm text-gray-400">
                <span className="text-gray-300">{inviteData.invitedBy}</span> has invited you to join
              </p>
              <p className="text-lg font-semibold text-teal-300 mt-1">{inviteData.companyName}</p>
            </div>

            {/* Role badge */}
            <div className="px-6 py-4 flex items-center justify-center gap-2 border-b border-gray-800">
              <span className="text-sm text-gray-400">as</span>
              <span className="inline-flex rounded-full bg-teal-900 px-3 py-1 text-sm font-medium text-teal-300">
                {roleLabel}
              </span>
            </div>

            <div className="px-6 py-6 space-y-3">

              {/* Already logged in — show Join button */}
              {currentUser ? (
                <>
                  <p className="text-center text-sm text-gray-400 mb-4">
                    Signed in as{' '}
                    <span className="text-white">{currentUser.email}</span>
                  </p>
                  <button
                    onClick={() => void handleAccept()}
                    disabled={pageState === 'accepting'}
                    className="w-full flex items-center justify-center gap-2 rounded-lg bg-teal-600 px-4 py-3 text-sm font-medium text-white hover:bg-teal-500 disabled:opacity-60 transition-colors"
                  >
                    {pageState === 'accepting' ? (
                      <>
                        <Loader2 className="h-4 w-4 animate-spin" />
                        <span>Joining…</span>
                      </>
                    ) : (
                      <>
                        <UserCheck className="h-4 w-4" />
                        <span>Join {inviteData.companyName}</span>
                      </>
                    )}
                  </button>
                  <p className="text-center text-xs text-gray-600 pt-1">
                    Not you?{' '}
                    <Link href="/login" className="text-teal-500 hover:text-teal-400">
                      Sign in with a different account
                    </Link>
                  </p>
                </>
              ) : (
                /* Not logged in — two CTAs */
                <>
                  <Link
                    href={`/login?invite=${token}`}
                    className="w-full flex items-center justify-center gap-2 rounded-lg bg-teal-600 px-4 py-3 text-sm font-medium text-white hover:bg-teal-500 transition-colors"
                  >
                    <LogIn className="h-4 w-4" />
                    Sign in to accept
                  </Link>
                  <Link
                    href={`/register?invite=${token}`}
                    className="w-full flex items-center justify-center gap-2 rounded-lg border border-gray-600 px-4 py-3 text-sm font-medium text-gray-300 hover:bg-gray-800 hover:text-white transition-colors"
                  >
                    <UserPlus className="h-4 w-4" />
                    Create an account
                  </Link>
                  <p className="text-center text-xs text-gray-600 pt-1">
                    Invitation sent to{' '}
                    <span className="text-gray-400">{inviteData.email}</span>
                  </p>
                </>
              )}
            </div>
          </div>
        )}

      </div>
    </div>
  );
}

/**
 * User Access Control — mirrors Sage Accounting "Control User Access".
 */

import { useState, useEffect, useCallback } from 'react';
import { AppLayout } from '@/components/layout/AppLayout';
import { Users, UserPlus, Trash2, Shield, Mail, Clock, Copy, Check } from 'lucide-react';
import { apiFetch } from '@/lib/apiFetch';
import { useAuth } from '@/contexts/AuthContext';

interface CompanyUser { userId: string; name: string; email: string; role: string; joinedAt: string; }
interface PendingInvitation { id: string; email: string; role: string; token: string; expiresAt: string; createdAt: string; }

const ROLES = ['owner', 'admin', 'manager', 'viewer'] as const;
const ADMIN_ROLES = ['owner', 'admin'];
const ROLE_BADGE: Record<string, string> = {
  owner: 'bg-teal-900 text-teal-300', admin: 'bg-blue-900 text-blue-300',
  manager: 'bg-purple-900 text-purple-300', viewer: 'bg-gray-700 text-gray-300',
};

export default function UserAccessPage() {
  const { user } = useAuth();
  const [users, setUsers] = useState<CompanyUser[]>([]);
  const [invitations, setInvitations] = useState<PendingInvitation[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [inviteEmail, setInviteEmail] = useState('');
  const [inviteRole, setInviteRole] = useState<string>('viewer');
  const [inviting, setInviting] = useState(false);
  const [feedback, setFeedback] = useState<string | null>(null);
  const [confirmRemove, setConfirmRemove] = useState<string | null>(null);
  const [copiedId, setCopiedId] = useState<string | null>(null);

  const myEntry = users.find((u) => u.userId === user?.id);
  const myRole = myEntry?.role ?? '';
  const isAdmin = ADMIN_ROLES.includes(myRole);
  const ownerCount = users.filter((u) => u.role === 'owner').length;

  const loadData = useCallback(async () => {
    setLoading(true); setError(null);
    try {
      const ur = await (await apiFetch('/api/accounting/company-users')).json();
      setUsers(ur.data ?? []);
      if (isAdmin) {
        const ir = await (await apiFetch('/api/accounting/company-invitations')).json();
        setInvitations(ir.data ?? []);
      }
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Failed to load data.');
    } finally { setLoading(false); }
  }, [isAdmin]);

  useEffect(() => { loadData(); }, [loadData]);

  const showFeedback = (msg: string) => {
    setFeedback(msg);
    setTimeout(() => setFeedback(null), 4000);
  };

  async function handleRoleChange(userId: string, role: string) {
    try {
      const j = await (await apiFetch('/api/accounting/company-users', { method: 'PUT', body: JSON.stringify({ userId, role }) })).json();
      setUsers(j.data ?? []); showFeedback('Role updated.');
    } catch (e) { showFeedback(e instanceof Error ? e.message : 'Update failed.'); }
  }

  async function handleRemove(userId: string) {
    try {
      const j = await (await apiFetch('/api/accounting/company-users', { method: 'DELETE', body: JSON.stringify({ userId }) })).json();
      setUsers(j.data ?? []); showFeedback('User removed.');
    } catch (e) { showFeedback(e instanceof Error ? e.message : 'Remove failed.'); }
    finally { setConfirmRemove(null); }
  }

  async function handleInvite(e: React.FormEvent) {
    e.preventDefault();
    if (!inviteEmail.trim()) return;
    setInviting(true);
    try {
      const j = await (await apiFetch('/api/accounting/company-invitations', {
        method: 'POST', body: JSON.stringify({ email: inviteEmail.trim(), role: inviteRole }),
      })).json();
      if (j.data?.autoAdded) {
        showFeedback(`${inviteEmail} was found and added directly to this company.`);
        loadData();
      } else {
        showFeedback(`Invitation sent to ${inviteEmail}.`);
        const ir = await (await apiFetch('/api/accounting/company-invitations')).json();
        setInvitations(ir.data ?? []);
      }
      setInviteEmail('');
    } catch (e) { showFeedback(e instanceof Error ? e.message : 'Invite failed.'); }
    finally { setInviting(false); }
  }

  async function handleCancelInvite(invitationId: string) {
    try {
      await apiFetch('/api/accounting/company-invitations', { method: 'DELETE', body: JSON.stringify({ invitationId }) });
      setInvitations((prev) => prev.filter((i) => i.id !== invitationId));
      showFeedback('Invitation cancelled.');
    } catch (e) { showFeedback(e instanceof Error ? e.message : 'Cancel failed.'); }
  }

  function handleCopyLink(inv: PendingInvitation) {
    const link = `${window.location.origin}/invite/${inv.token}`;
    void navigator.clipboard.writeText(link).then(() => {
      setCopiedId(inv.id);
      setTimeout(() => setCopiedId(null), 2000);
    });
  }

  const fmt = (iso: string) => new Date(iso).toLocaleDateString('en-ZA', { day: '2-digit', month: 'short', year: 'numeric' });

  return (
    <AppLayout>
      <div className="min-h-screen bg-gray-950 px-4 py-8 sm:px-8">
        <div className="mx-auto max-w-4xl space-y-8">

          <div className="flex items-center gap-3">
            <Shield className="h-7 w-7 text-teal-400" />
            <div>
              <h1 className="text-2xl font-bold text-white">User Access Control</h1>
              <p className="text-sm text-gray-400">Manage who can access this company and what they can do.</p>
            </div>
          </div>

          {feedback && <div className="rounded-lg border border-teal-700 bg-teal-900/40 px-4 py-3 text-sm text-teal-300">{feedback}</div>}
          {error && <div className="rounded-lg border border-red-700 bg-red-900/30 px-4 py-3 text-sm text-red-300">{error}</div>}

          {/* Current Users */}
          <div className="rounded-xl border border-gray-800 bg-gray-900">
            <div className="flex items-center gap-2 border-b border-gray-800 px-6 py-4">
              <Users className="h-5 w-5 text-teal-400" />
              <h2 className="font-semibold text-white">Company Users</h2>
            </div>
            {loading ? (
              <div className="px-6 py-10 text-center text-gray-500">Loading...</div>
            ) : (
              <div className="overflow-x-auto">
                <table className="w-full text-sm">
                  <thead>
                    <tr className="border-b border-gray-800 text-left text-gray-500">
                      <th className="px-6 py-3 font-medium">Name</th>
                      <th className="px-6 py-3 font-medium">Email</th>
                      <th className="px-6 py-3 font-medium">Role</th>
                      <th className="px-6 py-3 font-medium">Joined</th>
                      {isAdmin && <th className="px-6 py-3 font-medium">Actions</th>}
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-gray-800">
                    {users.map((u) => {
                      const isSelf = u.userId === user?.id;
                      const isLastOwner = u.role === 'owner' && ownerCount <= 1;
                      return (
                        <tr key={u.userId} className="hover:bg-gray-800/40">
                          <td className="px-6 py-3 text-white">
                            {u.name}{isSelf && <span className="ml-2 text-xs text-gray-500">(you)</span>}
                          </td>
                          <td className="px-6 py-3 text-gray-400">{u.email}</td>
                          <td className="px-6 py-3">
                            {isAdmin && !isSelf ? (
                              <select value={u.role} onChange={(e) => handleRoleChange(u.userId, e.target.value)}
                                className="rounded border border-gray-700 bg-gray-800 px-2 py-1 text-xs text-white focus:border-teal-500 focus:outline-none">
                                {ROLES.map((r) => <option key={r} value={r}>{r}</option>)}
                              </select>
                            ) : (
                              <span className={`inline-flex rounded-full px-2 py-0.5 text-xs font-medium ${ROLE_BADGE[u.role] ?? 'bg-gray-700 text-gray-300'}`}>{u.role}</span>
                            )}
                          </td>
                          <td className="px-6 py-3 text-gray-400">{fmt(u.joinedAt)}</td>
                          {isAdmin && (
                            <td className="px-6 py-3">
                              {!isSelf && !isLastOwner && (
                                confirmRemove === u.userId ? (
                                  <span className="flex items-center gap-2">
                                    <button onClick={() => handleRemove(u.userId)} className="text-xs text-red-400 hover:text-red-300">Confirm</button>
                                    <button onClick={() => setConfirmRemove(null)} className="text-xs text-gray-500 hover:text-gray-300">Cancel</button>
                                  </span>
                                ) : (
                                  <button onClick={() => setConfirmRemove(u.userId)} className="text-gray-500 hover:text-red-400">
                                    <Trash2 className="h-4 w-4" />
                                  </button>
                                )
                              )}
                            </td>
                          )}
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              </div>
            )}
          </div>

          {/* Invite User (admin/owner only) */}
          {isAdmin && (
            <div className="rounded-xl border border-gray-800 bg-gray-900">
              <div className="flex items-center gap-2 border-b border-gray-800 px-6 py-4">
                <UserPlus className="h-5 w-5 text-teal-400" />
                <h2 className="font-semibold text-white">Invite a User</h2>
              </div>
              <div className="px-6 py-5">
                <form onSubmit={handleInvite} className="flex flex-wrap items-end gap-3">
                  <div className="flex-1 min-w-[220px]">
                    <label className="mb-1 block text-xs font-medium text-gray-400">Email address</label>
