() => {
  // Find the anti-forgery token and any other auth tokens on the page
  const token = document.querySelector('input[name="__RequestVerificationToken"]')?.value;
  const cookies = document.cookie;
  const meta = {};
  document.querySelectorAll('meta').forEach(m => {
    if (m.name) meta[m.name] = m.content;
  });

  // Also check for any hidden inputs
  const hiddenInputs = {};
  document.querySelectorAll('input[type="hidden"]').forEach(i => {
    if (i.name && i.value) hiddenInputs[i.name] = i.value.substring(0, 50);
  });

  return { token, hiddenInputs, meta, hasCookies: cookies.includes('.ASPXAUTH') };
}

