async () => {
  const apis = [
    { name: 'Customers', url: '/services/Customer/GetWithFilter', body: {"FilterId":0,"Search":"","Skip":0,"Take":5,"OrderBy":"Name asc"} },
    { name: 'Suppliers', url: '/services/Supplier/GetWithFilter', body: {"FilterId":0,"Search":"","Skip":0,"Take":5,"OrderBy":"Name asc"} },
    { name: 'TaxInvoices', url: '/services/TaxInvoice/GetWithFilter', body: {"FilterId":0,"Search":"","Skip":0,"Take":5} },
    { name: 'SupplierInvoices', url: '/services/SupplierInvoice/GetWithFilter', body: {"FilterId":0,"Search":"","Skip":0,"Take":5} },
    { name: 'BankAccounts', url: '/services/BankAccount/GetWithFilter', body: {"FilterId":0,"Search":"","Skip":0,"Take":5} },
    { name: 'Accounts_All', url: '/services/Account/GetWithFilter', body: {"FilterId":2,"Search":"","Skip":0,"Take":5} },
    { name: 'Company', url: '/services/Company/Current', body: null },
  ];

  const results = [];
  for (const api of apis) {
    try {
      const opts = api.body 
        ? { method: 'POST', headers: {'Content-Type':'application/json;charset=UTF-8'}, body: JSON.stringify(api.body), credentials: 'include' }
        : { method: 'GET', credentials: 'include' };
      const res = await fetch(api.url, opts);
      const json = await res.json();
      results.push({ 
        name: api.name, 
        status: res.status,
        totalResults: json.TotalResults ?? json.length ?? 'N/A',
        sampleKeys: json.Results ? Object.keys(json.Results[0] || {}).join(', ') : Object.keys(json).join(', '),
      });
    } catch (e) {
      results.push({ name: api.name, status: 'error', error: e.message });
    }
  }
  return results;
}

