// Wraps handler with auth + super_admin role check + error handler
export function withAdmin(handler: (req: AuthenticatedNextApiRequest, res: NextApiResponse) => Promise<void>): NextApiHandler {
  return withAuth(withRole('super_admin')((async (req: AuthenticatedNextApiRequest, res: NextApiResponse) => {
    return withErrorHandler(handler as any)(req, res);
  }) as any) as any) as NextApiHandler;
}
