import { NextApiRequest, NextApiResponse } from 'next';
import { log } from '@/lib/logger';

/**
 * Standard API Response Types
 */
export interface ApiSuccessResponse<T = any> {
  success: true;
  data: T;
  message?: string;
  meta?: {
    timestamp?: string;
    requestId?: string;
    [key: string]: any;
  };
}

export interface ApiErrorResponse {
  success: false;
  error: {
    code: string;
    message: string;
    details?: any;
  };
  meta?: {
    timestamp?: string;
    requestId?: string;
    [key: string]: any;
  };
}

export interface ApiPaginatedResponse<T = any> extends ApiSuccessResponse<T[]> {
  pagination: {
    page: number;
    pageSize: number;
    total: number;
    totalPages: number;
  };
}

export type ApiResponse<T = any> = ApiSuccessResponse<T> | ApiErrorResponse;

/**
 * Standard error codes
 */
export enum ErrorCode {
  // Client errors (400-499)
  BAD_REQUEST = 'BAD_REQUEST',
  UNAUTHORIZED = 'UNAUTHORIZED',
  FORBIDDEN = 'FORBIDDEN',
  NOT_FOUND = 'NOT_FOUND',
  METHOD_NOT_ALLOWED = 'METHOD_NOT_ALLOWED',
  CONFLICT = 'CONFLICT',
  VALIDATION_ERROR = 'VALIDATION_ERROR',
  RATE_LIMIT = 'RATE_LIMIT',
  PAYLOAD_TOO_LARGE = 'PAYLOAD_TOO_LARGE',

  // Server errors (500-599)
  INTERNAL_ERROR = 'INTERNAL_ERROR',
  DATABASE_ERROR = 'DATABASE_ERROR',
  SERVICE_UNAVAILABLE = 'SERVICE_UNAVAILABLE',
  GATEWAY_TIMEOUT = 'GATEWAY_TIMEOUT',

  // Business logic errors
  BUSINESS_RULE_VIOLATION = 'BUSINESS_RULE_VIOLATION',
  INSUFFICIENT_PERMISSIONS = 'INSUFFICIENT_PERMISSIONS',
  RESOURCE_LOCKED = 'RESOURCE_LOCKED',
  DEPENDENCY_ERROR = 'DEPENDENCY_ERROR',
}

/**
 * HTTP status code mapping
 */
const STATUS_CODE_MAP: Record<ErrorCode, number> = {
  // Client errors
  [ErrorCode.BAD_REQUEST]: 400,
  [ErrorCode.UNAUTHORIZED]: 401,
  [ErrorCode.FORBIDDEN]: 403,
  [ErrorCode.NOT_FOUND]: 404,
  [ErrorCode.METHOD_NOT_ALLOWED]: 405,
  [ErrorCode.CONFLICT]: 409,
  [ErrorCode.VALIDATION_ERROR]: 422,
  [ErrorCode.RATE_LIMIT]: 429,
  [ErrorCode.PAYLOAD_TOO_LARGE]: 413,

  // Server errors
  [ErrorCode.INTERNAL_ERROR]: 500,
  [ErrorCode.DATABASE_ERROR]: 500,
  [ErrorCode.SERVICE_UNAVAILABLE]: 503,
  [ErrorCode.GATEWAY_TIMEOUT]: 504,

  // Business logic errors (usually 400 or 422)
  [ErrorCode.BUSINESS_RULE_VIOLATION]: 422,
  [ErrorCode.INSUFFICIENT_PERMISSIONS]: 403,
  [ErrorCode.RESOURCE_LOCKED]: 423,
  [ErrorCode.DEPENDENCY_ERROR]: 424,
};

/**
 * API Response Helper Class
 */
export class ApiResponseHelper {
  private static generateMeta(additionalMeta?: Record<string, any>) {
    return {
      timestamp: new Date().toISOString(),
      ...additionalMeta,
    };
  }

  /**
   * Send success response
   */
  static success<T>(
    res: NextApiResponse,
    data: T,
    message?: string,
    statusCode = 200,
    meta?: Record<string, any>
  ): void {
    const response: ApiSuccessResponse<T> = {
      success: true,
      data,
      ...(message && { message }),
      meta: this.generateMeta(meta),
    };

    res.status(statusCode).json(response);
  }

  /**
   * Send created response (201)
   */
  static created<T>(
    res: NextApiResponse,
    data: T,
    message = 'Resource created successfully',
    meta?: Record<string, any>
  ): void {
    this.success(res, data, message, 201, meta);
  }

  /**
   * Send no content response (204)
   */
  static noContent(res: NextApiResponse): void {
    res.status(204).end();
  }

  /**
   * Send paginated response
   */
  static paginated<T>(
    res: NextApiResponse,
    data: T[],
    pagination: {
      page: number;
      pageSize: number;
      total: number;
    },
    message?: string,
    meta?: Record<string, any>
  ): void {
    const totalPages = Math.ceil(pagination.total / pagination.pageSize);

    const response: ApiPaginatedResponse<T> = {
      success: true,
      data,
      pagination: {
        ...pagination,
        totalPages,
      },
      ...(message && { message }),
      meta: this.generateMeta(meta),
    };

    res.status(200).json(response);
  }

  /**
   * Send error response
   */
  static error(
    res: NextApiResponse,
    code: ErrorCode,
    message: string,
    details?: any,
    meta?: Record<string, any>
  ): void {
    const statusCode = STATUS_CODE_MAP[code] || 500;

    const response: ApiErrorResponse = {
      success: false,
      error: {
        code,
        message,
        ...(details && { details }),
      },
      meta: this.generateMeta(meta),
    };

    res.status(statusCode).json(response);
  }

  /**
   * Send bad request error response (400)
   */
  static badRequest(
    res: NextApiResponse,
    message: string,
    details?: any
  ): void {
    this.error(res, ErrorCode.BAD_REQUEST, message, details);
  }

  /**
   * Send validation error response
   */
  static validationError(
    res: NextApiResponse,
    errors: Record<string, string | string[]>,
    message = 'Validation failed'
  ): void {
    this.error(res, ErrorCode.VALIDATION_ERROR, message, errors);
  }

  /**
   * Send not found error response
   */
  static notFound(
    res: NextApiResponse,
    resource: string,
    identifier?: string | number
  ): void {
    const message = identifier
      ? `${resource} with identifier '${identifier}' not found`
      : `${resource} not found`;

    this.error(res, ErrorCode.NOT_FOUND, message);
  }

  /**
   * Send unauthorized error response
   */
  static unauthorized(
    res: NextApiResponse,
    message = 'Authentication required'
  ): void {
    this.error(res, ErrorCode.UNAUTHORIZED, message);
  }

  /**
   * Send forbidden error response
   */
  static forbidden(
    res: NextApiResponse,
    message = 'You do not have permission to perform this action'
  ): void {
    this.error(res, ErrorCode.FORBIDDEN, message);
  }

  /**
   * Send method not allowed error response
   */
  static methodNotAllowed(
    res: NextApiResponse,
    method: string,
    allowedMethods: string[]
  ): void {
    res.setHeader('Allow', allowedMethods.join(', '));
    this.error(
      res,
      ErrorCode.METHOD_NOT_ALLOWED,
      `Method ${method} not allowed. Allowed methods: ${allowedMethods.join(', ')}`
    );
  }

  /**
   * Send internal server error response
   */
  static internalError(
    res: NextApiResponse,
    error: Error | unknown,
    message = 'An internal error occurred'
  ): void {
    // Log the actual error for debugging
    log.error('Internal Server Error', error instanceof Error ? { message: error.message, stack: error.stack } : { error }, 'ApiResponse');

    // In production, don't expose internal error details
    const isDevelopment = process.env.NODE_ENV === 'development';
    const errorDetails = isDevelopment && error instanceof Error
      ? { stack: error.stack, originalMessage: error.message }
      : undefined;

    this.error(res, ErrorCode.INTERNAL_ERROR, message, errorDetails);
  }

  /**
   * Send database error response
   */
  static databaseError(
    res: NextApiResponse,
    error: Error | unknown,
    message = 'A database error occurred'
  ): void {
    // Log the actual error for debugging
    log.error('Database Error', error instanceof Error ? { message: error.message } : { error }, 'ApiResponse');

    // In production, don't expose database error details
    const isDevelopment = process.env.NODE_ENV === 'development';
    const errorDetails = isDevelopment && error instanceof Error
      ? { originalMessage: error.message }
      : undefined;

    this.error(res, ErrorCode.DATABASE_ERROR, message, errorDetails);
  }

  /**
   * Handle CORS headers
   */
  static setCorsHeaders(
    res: NextApiResponse,
    origin = '',
    methods = ['GET', 'POST', 'PUT', 'DELETE', 'PATCH', 'OPTIONS'],
    headers = ['Content-Type', 'Authorization']
  ): void {
    const allowedOrigins = [
      'https://fin.fibreflow.app',
      ...(process.env.NODE_ENV === 'development'
        ? ['http://localhost:3101', 'http://localhost:3004']
        : []),
    ];
    const safeOrigin = origin && allowedOrigins.includes(origin) ? origin : '';
    if (!safeOrigin) return;
    res.setHeader('Access-Control-Allow-Origin', safeOrigin);
    res.setHeader('Access-Control-Allow-Methods', methods.join(', '));
    res.setHeader('Access-Control-Allow-Headers', headers.join(', '));
  }

  /**
   * Handle OPTIONS request for CORS
   */
  static handleOptions(req: NextApiRequest, res: NextApiResponse): void {
    this.setCorsHeaders(res, req.headers.origin || '');
    res.status(200).end();
  }
}

/**
 * Convenience exports for common responses
 */
export const apiResponse = {
  success: ApiResponseHelper.success.bind(ApiResponseHelper),
  created: ApiResponseHelper.created.bind(ApiResponseHelper),
  noContent: ApiResponseHelper.noContent.bind(ApiResponseHelper),
  paginated: ApiResponseHelper.paginated.bind(ApiResponseHelper),
  error: ApiResponseHelper.error.bind(ApiResponseHelper),
  badRequest: ApiResponseHelper.badRequest.bind(ApiResponseHelper),
  validationError: ApiResponseHelper.validationError.bind(ApiResponseHelper),
  notFound: ApiResponseHelper.notFound.bind(ApiResponseHelper),
  unauthorized: ApiResponseHelper.unauthorized.bind(ApiResponseHelper),
  forbidden: ApiResponseHelper.forbidden.bind(ApiResponseHelper),
  methodNotAllowed: ApiResponseHelper.methodNotAllowed.bind(ApiResponseHelper),
  internalError: ApiResponseHelper.internalError.bind(ApiResponseHelper),
  databaseError: ApiResponseHelper.databaseError.bind(ApiResponseHelper),
  setCorsHeaders: ApiResponseHelper.setCorsHeaders.bind(ApiResponseHelper),
  handleOptions: ApiResponseHelper.handleOptions.bind(ApiResponseHelper),
};

export default apiResponse;

import {
  createContext,
  useContext,
  useEffect,
  useState,
  ReactNode,
  useCallback,
} from 'react';
import type { AuthRole } from '@/lib/auth/types';

/**
 * Authenticated user shape returned from /api/auth/me
 */
export interface AuthUser {
  id: string;
  email: string;
  firstName: string;
  lastName: string;
  name: string;
  role: AuthRole;
  permissions: string[];
  isActive: boolean;
  profilePicture?: string | null;
  department?: string;
  onboardingCompleted?: boolean;
}

interface AuthContextType {
  /** Currently authenticated user, or null if not logged in */
  user: AuthUser | null;
  /** True while the initial session check is in progress */
  loading: boolean;
  /** Last authentication error message */
  error: string | null;
  /** True when a valid user session exists */
  isAuthenticated: boolean;

  /** Sign in with email and password */
  login: (email: string, password: string) => Promise<void>;
  /** Sign out and redirect to /sign-in */
  logout: () => Promise<void>;
  /** Re-fetch the current user from /api/auth/me */
  refreshUser: () => Promise<void>;
  /** Clear the current error state */
  clearError: () => void;

  /** Check if the user has a specific permission string */
  hasPermission: (permission: string) => boolean;
  /** Check if the user has the given role or higher */
  hasRole: (role: AuthRole) => boolean;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

/**
 * Map the raw API response into a typed AuthUser
 */
function mapApiUser(raw: Record<string, unknown>): AuthUser {
  const firstName = (raw.firstName as string) || (raw.first_name as string) || '';
  const lastName = (raw.lastName as string) || (raw.last_name as string) || '';
  const name =
    (raw.name as string) ||
    (firstName && lastName ? `${firstName} ${lastName}`.trim() : (raw.email as string));

  return {
    id: raw.id as string,
    email: raw.email as string,
    firstName,
    lastName,
    name,
    role: (raw.role as AuthRole) || 'viewer',
    permissions: (raw.permissions as string[]) || [],
    isActive: raw.isActive !== false && raw.is_active !== false,
    profilePicture: (raw.profilePicture as string) || (raw.profile_picture as string) || null,
    department: (raw.department as string) || undefined,
    onboardingCompleted: raw.onboardingCompleted === true || raw.onboarding_completed === true,
  };
}

// Role hierarchy for permission checks
const ROLE_HIERARCHY: Record<AuthRole, number> = {
  super_admin: 6,
  system: 5,
  admin: 4,
  manager: 3,
  storeman: 2,
  technician: 2,
  viewer: 1,
};

export function AuthProvider({ children }: { children: ReactNode }) {
  const [user, setUser] = useState<AuthUser | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  /**
   * Fetch current session from the API
   */
  const checkAuth = useCallback(async () => {
    try {
      const res = await fetch('/api/auth/me', { credentials: 'include' });

      if (res.ok) {
        const data = await res.json();
        // Support both { data: { user } } and { data: user } shapes
        const raw = data.data?.user ?? data.data ?? data.user;
        if (raw) {
          setUser(mapApiUser(raw));
        } else {
          setUser(null);
        }
      } else {
        setUser(null);
      }
    } catch {
      setUser(null);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    checkAuth();

    // Re-fetch user when tab regains focus (picks up RBAC changes)
    const onFocus = () => checkAuth();
    window.addEventListener('focus', onFocus);

    // Also poll every 5 minutes as a fallback
    const interval = setInterval(checkAuth, 5 * 60 * 1000);

    return () => {
      window.removeEventListener('focus', onFocus);
      clearInterval(interval);
    };
  }, [checkAuth]);

  /**
   * Sign in with email/password credentials
   */
  const login = async (email: string, password: string) => {
    setLoading(true);
    setError(null);

    try {
      const res = await fetch('/api/auth/login', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email, password }),
        credentials: 'include',
      });

      const data = await res.json();

      if (!res.ok) {
        throw new Error(data.error?.message || data.message || 'Login failed');
      }

      const raw = data.data?.user ?? data.data ?? data.user;
      setUser(raw ? mapApiUser(raw) : null);
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Login failed';
      setError(message);
      throw err;
    } finally {
      setLoading(false);
    }
  };

  /**
   * Sign out and clear session cookie
   */
  const logout = async () => {
    try {
      await fetch('/api/auth/logout', {
        method: 'POST',
        credentials: 'include',
      });
    } finally {
      setUser(null);
      if (typeof window !== 'undefined') {
        window.location.href = '/login';
      }
    }
  };

  const refreshUser = async () => {
    await checkAuth();
  };

  const clearError = () => {
    setError(null);
  };

  /**
   * Check if the current user holds a specific permission string.
   * Users with the 'all' permission pass all checks.
   */
  const hasPermission = (permission: string): boolean => {
    if (!user) return false;
    return user.permissions.includes('all') || user.permissions.includes(permission);
  };

  /**
   * Check if the current user's role meets or exceeds the required role level.
   */
  const hasRole = (role: AuthRole): boolean => {
    if (!user) return false;
    const userLevel = ROLE_HIERARCHY[user.role] ?? 0;
    const requiredLevel = ROLE_HIERARCHY[role] ?? 0;
    return userLevel >= requiredLevel;
  };

  const value: AuthContextType = {
    user,
    loading,
    error,
    isAuthenticated: user !== null,
    login,
    logout,
    refreshUser,
    clearError,
    hasPermission,
    hasRole,
  };

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
}

export function useAuth() {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
}

/**
 * Standalone AppLayout for the Accounting app.
 * Supports two nav modes: top-bar (Sage-style, default) or sidebar.
 * User preference persisted in localStorage.
 */

import { useState, useEffect, useRef, ReactNode } from 'react';
import { useRouter } from 'next/router';
import {
  BookOpen,
  ChevronLeft,
  ChevronRight,
  Menu,
  LogOut,
  User,
  Moon,
  Sun,
  PanelLeft,
  PanelTop,
  Download,
  X as XIcon,
} from 'lucide-react';
import dynamic from 'next/dynamic';
import { useAuth } from '@/contexts/AuthContext';
import { useTheme } from '@/contexts/ThemeContext';
import { useCompany } from '@/contexts/CompanyContext';
import { LoadingSpinner } from '@/components/ui/LoadingSpinner';
import { CompanySwitcher } from '@/components/layout/CompanySwitcher';
import { SidebarNav } from '@/components/layout/SidebarNav';

const AccountingNav = dynamic(
  () => import('@/components/accounting/AccountingNav').then(mod => ({ default: mod.AccountingNav })),
);

const SIDEBAR_COLLAPSED_KEY = 'accounting-sidebar-collapsed';
const NAV_MODE_KEY = 'accounting-nav-mode';
const PWA_INSTALL_DISMISSED_KEY = 'isaflow-pwa-install-dismissed';

type NavMode = 'top' | 'side';

// ─── Props ──────────────────────────────────────────────────────────────────

interface AppLayoutProps {
  children: ReactNode;
}

// ─── Component ──────────────────────────────────────────────────────────────

export function AppLayout({ children }: AppLayoutProps) {
  const router = useRouter();
  const { user, loading, logout } = useAuth();
  const { theme, toggleTheme } = useTheme();
  const { companyRole } = useCompany();

  // Nav mode preference
  const [navMode, setNavMode] = useState<NavMode>('top');

  // Mobile sidebar open state (used in both modes for mobile)
  const [mobileOpen, setMobileOpen] = useState(false);

  // Desktop collapsed state (sidebar mode only)
  const [collapsed, setCollapsed] = useState(false);
  const [hydrated, setHydrated] = useState(false);

  // PWA install prompt
  const deferredPromptRef = useRef<Event | null>(null);
  const [showInstallBanner, setShowInstallBanner] = useState(false);

  useEffect(() => {
    const savedMode = localStorage.getItem(NAV_MODE_KEY) as NavMode | null;
    if (savedMode === 'top' || savedMode === 'side') setNavMode(savedMode);
    const savedCollapsed = localStorage.getItem(SIDEBAR_COLLAPSED_KEY);
    if (savedCollapsed !== null) setCollapsed(JSON.parse(savedCollapsed) as boolean);
    setHydrated(true);
  }, []);

  // Listen for PWA install prompt
  useEffect(() => {
    const dismissed = localStorage.getItem(PWA_INSTALL_DISMISSED_KEY);
    if (dismissed) return;

    const handler = (e: Event) => {
      e.preventDefault();
      deferredPromptRef.current = e;
      setShowInstallBanner(true);
    };
    window.addEventListener('beforeinstallprompt', handler);
    return () => window.removeEventListener('beforeinstallprompt', handler);
  }, []);

  useEffect(() => {
    if (hydrated) {
      localStorage.setItem(NAV_MODE_KEY, navMode);
      localStorage.setItem(SIDEBAR_COLLAPSED_KEY, JSON.stringify(collapsed));
    }
  }, [collapsed, navMode, hydrated]);

  // Close mobile nav on route change
  useEffect(() => {
    setMobileOpen(false);
  }, [router.pathname]);

  const toggleNavMode = () => setNavMode(m => m === 'top' ? 'side' : 'top');

  const handleInstall = async () => {
    const prompt = deferredPromptRef.current as (Event & { prompt: () => Promise<void> }) | null;
    if (!prompt) return;
    await prompt.prompt();
    deferredPromptRef.current = null;
    setShowInstallBanner(false);
  };

  const dismissInstall = () => {
    setShowInstallBanner(false);
    localStorage.setItem(PWA_INSTALL_DISMISSED_KEY, '1');
  };

  const userInitials = user
    ? (`${user.firstName?.[0] ?? ''}${user.lastName?.[0] ?? ''}`.toUpperCase() || user.email?.[0]?.toUpperCase() || 'U')
    : 'U';

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-950">
        <div className="text-center">
          <LoadingSpinner size="lg" className="mx-auto mb-4" />
          <p className="text-gray-400 text-sm">Loading...</p>
        </div>
      </div>
    );
  }

  // ─── Sidebar content (shared between mobile + desktop sidebar) ────────────

  const SidebarContent = (
    <>
      {/* Logo */}
      <div className={`flex items-center px-4 py-4 border-b border-gray-200 dark:border-gray-700 ${collapsed ? 'justify-center' : ''}`}>
        {collapsed ? (
          <div className="w-8 h-8 bg-teal-600 rounded-lg flex items-center justify-center flex-shrink-0">
            <BookOpen className="w-4 h-4 text-white" />
          </div>
        ) : (
          <img src="/logo.png" alt="ISAFlow" className="h-9 w-auto dark:brightness-0 dark:invert" />
        )}
      </div>

      {/* Nav — uses same TABS config as top nav */}
      <SidebarNav collapsed={collapsed} />

      {/* User area */}
      <div className={`border-t border-gray-200 dark:border-gray-700 p-3 ${collapsed ? 'flex flex-col items-center gap-2' : ''}`}>
        {user && !collapsed && (
          <div className="flex items-center gap-2 px-2 py-2 mb-1">
            <div className="w-7 h-7 bg-teal-700 rounded-full flex items-center justify-center flex-shrink-0">
              <span className="text-xs text-white font-semibold">{userInitials}</span>
            </div>
            <div className="flex-1 min-w-0">
              <p className="text-xs font-medium text-gray-900 dark:text-white truncate">
                {user.firstName} {user.lastName}
              </p>
              <p className="text-xs text-gray-500 truncate capitalize">{companyRole || user.role}</p>
            </div>
          </div>
        )}
        <button
          onClick={() => void logout()}
          title={collapsed ? 'Log out' : undefined}
          className={`
            flex items-center gap-2 w-full px-3 py-2 rounded-lg text-sm text-gray-500 dark:text-gray-400
            hover:text-gray-900 dark:hover:text-white hover:bg-gray-100 dark:hover:bg-gray-700/50 transition-colors
            ${collapsed ? 'justify-center' : ''}
          `}
        >
          <LogOut className="w-4 h-4 flex-shrink-0" />
          {!collapsed && <span>Log out</span>}
        </button>
      </div>
    </>
  );

  const showSidebar = navMode === 'side';

  return (
    <div className="flex h-screen bg-white dark:bg-gray-950 overflow-hidden">

      {/* ── Desktop sidebar (only in side mode) ──────────────────────────── */}
      {showSidebar && (
        <aside
          className={`
            hidden lg:flex flex-col bg-gray-50 dark:bg-gray-900 border-r border-gray-200 dark:border-gray-700
            transition-all duration-300 flex-shrink-0
            ${collapsed ? 'w-16' : 'w-64'}
          `}
        >
          {SidebarContent}

          {/* Collapse toggle */}
          <button
            onClick={() => setCollapsed(c => !c)}
            className="flex items-center justify-center h-10 border-t border-gray-200 dark:border-gray-700 text-gray-400 hover:text-gray-900 dark:hover:text-white hover:bg-gray-100 dark:hover:bg-gray-700/50 transition-colors"
            title={collapsed ? 'Expand sidebar' : 'Collapse sidebar'}
          >
            {collapsed
              ? <ChevronRight className="w-4 h-4" />
              : <ChevronLeft className="w-4 h-4" />
            }
          </button>
        </aside>
      )}

      {/* ── Mobile sidebar overlay (always available for mobile) ──────── */}
      {mobileOpen && (
        <div
          className="fixed inset-0 z-30 bg-black/60 lg:hidden"
          onClick={() => setMobileOpen(false)}
        />
      )}
      <aside
        className={`
          fixed inset-y-0 left-0 z-40 w-64 bg-gray-50 dark:bg-gray-900 border-r border-gray-200 dark:border-gray-700
          flex flex-col lg:hidden transition-transform duration-300
          ${mobileOpen ? 'translate-x-0' : '-translate-x-full'}
        `}
      >
        {SidebarContent}
      </aside>

      {/* ── Main area ────────────────────────────────────────────────────── */}
      <div className="flex-1 flex flex-col min-w-0">

        {/* PWA install banner */}
        {showInstallBanner && (
          <div className="bg-teal-600 text-white px-4 py-2 flex items-center justify-between text-sm flex-shrink-0">
            <div className="flex items-center gap-2">
              <Download className="w-4 h-4" />
              <span>Install IsaFlow for a faster, app-like experience</span>
            </div>
            <div className="flex items-center gap-2">
              <button onClick={handleInstall} className="px-3 py-1 bg-white/20 hover:bg-white/30 rounded text-xs font-medium transition-colors">
                Install
              </button>
              <button onClick={dismissInstall} className="p-1 hover:bg-white/20 rounded transition-colors" aria-label="Dismiss">
                <XIcon className="w-3.5 h-3.5" />
              </button>
            </div>
          </div>
        )}

        {/* Header bar */}
        <header className="bg-gray-50 dark:bg-gray-900 border-b border-gray-200 dark:border-gray-700 h-14 flex items-center px-4 gap-3 flex-shrink-0">
          {/* Mobile hamburger */}
          <button
            className="lg:hidden text-gray-400 hover:text-gray-900 dark:hover:text-white transition-colors"
            onClick={() => setMobileOpen(o => !o)}
            aria-label="Open menu"
          >
            <Menu className="w-5 h-5" />
          </button>

          {/* Logo (in top-nav mode, show logo here; in side mode it's in the sidebar) */}
          <img src="/logo.png" alt="ISAFlow" className="h-8 w-auto hidden sm:block dark:brightness-0 dark:invert" />

          {/* Company switcher */}
          <CompanySwitcher />

          <div className="flex-1" />

          {/* Nav mode toggle */}
          <button
            onClick={toggleNavMode}
            className="p-2 rounded-lg text-gray-400 hover:text-gray-900 dark:hover:text-white hover:bg-gray-100 dark:hover:bg-gray-700/50 transition-colors"
            title={navMode === 'top' ? 'Switch to sidebar navigation' : 'Switch to top navigation'}
          >
            {navMode === 'top' ? <PanelLeft className="w-4 h-4" /> : <PanelTop className="w-4 h-4" />}
          </button>

          {/* Theme toggle */}
          <button
            onClick={toggleTheme}
            className="p-2 rounded-lg text-gray-400 hover:text-gray-900 dark:hover:text-white hover:bg-gray-100 dark:hover:bg-gray-700/50 transition-colors"
            title={theme === 'dark' ? 'Switch to light mode' : 'Switch to dark mode'}
          >
            {theme === 'dark' ? <Sun className="w-4 h-4" /> : <Moon className="w-4 h-4" />}
          </button>

          {/* User info */}
          {user && (
            <div className="flex items-center gap-2 text-sm text-gray-500 dark:text-gray-400">
              <User className="w-4 h-4" />
              <span className="hidden sm:inline truncate max-w-[160px]">
                {user.firstName} {user.lastName}
              </span>
            </div>
          )}

          {/* Logout (visible in top-nav mode where sidebar user area is hidden) */}
          {!showSidebar && (
            <button
              onClick={() => void logout()}
              className="p-2 rounded-lg text-gray-400 hover:text-red-500 transition-colors"
              title="Log out"
            >
              <LogOut className="w-4 h-4" />
            </button>
          )}
        </header>

        {/* Horizontal nav bar (only in top mode) */}
        {!showSidebar && (
          <div className="relative z-40">
            <AccountingNav />
          </div>
        )}

        {/* Page content */}
        <main className="flex-1 overflow-y-auto bg-white dark:bg-gray-950 p-4 lg:p-6 relative z-0">
          {children}
        </main>
      </div>
    </div>
  );
}

