/**
 * Admin Dashboard Service
 * Cross-company aggregate statistics for the ISAFlow Admin Platform
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';

export interface DashboardStats {
  companies: {
    total: number;
    active: number;
    suspended: number;
    new_this_month: number;
  };
  users: {
    total: number;
    active: number;
    suspended: number;
    new_this_month: number;
  };
  activity: {
    logins_today: number;
    api_calls_today: number;
  };
}

export async function getDashboardStats(): Promise<DashboardStats> {
  try {
    const [companiesRow] = await sql`
      SELECT
        COUNT(*)::int AS total,
        COUNT(*) FILTER (WHERE status = 'active')::int AS active,
        COUNT(*) FILTER (WHERE status = 'suspended')::int AS suspended,
        COUNT(*) FILTER (
          WHERE created_at >= date_trunc('month', NOW())
        )::int AS new_this_month
      FROM companies
    `;

    const [usersRow] = await sql`
      SELECT
        COUNT(*)::int AS total,
        COUNT(*) FILTER (WHERE is_active = true)::int AS active,
        COUNT(*) FILTER (WHERE is_active = false)::int AS suspended,
        COUNT(*) FILTER (
          WHERE created_at >= date_trunc('month', NOW())
        )::int AS new_this_month
      FROM users
    `;

    const [activityRow] = await sql`
      SELECT
        COUNT(*) FILTER (
          WHERE created_at >= date_trunc('day', NOW())
        )::int AS logins_today
      FROM user_sessions
    `;

    return {
      companies: {
        total: companiesRow?.total ?? 0,
        active: companiesRow?.active ?? 0,
        suspended: companiesRow?.suspended ?? 0,
        new_this_month: companiesRow?.new_this_month ?? 0,
      },
      users: {
        total: usersRow?.total ?? 0,
        active: usersRow?.active ?? 0,
        suspended: usersRow?.suspended ?? 0,
        new_this_month: usersRow?.new_this_month ?? 0,
      },
      activity: {
        logins_today: activityRow?.logins_today ?? 0,
        api_calls_today: 0,
      },
    };
  } catch (err) {
    log.error('getDashboardStats failed', { error: err }, 'adminDashboardService');
    throw err;
  }
}

