/**
 * Admin Audit Service
 * Records and retrieves admin actions from admin_audit_log.
 * Every mutating admin action should call logAdminAction.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import type { AuditLogEntry, PaginatedResult } from '../types/admin.types';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

export interface AuditLogFilters {
  admin_user_id?: string;
  target_type?: string;
  target_id?: string;
  action?: string;
  from_date?: string;
  to_date?: string;
  page?: number;
  limit?: number;
}

/**
 * Write an admin action to the audit log.
 * Fire-and-forget safe — errors are logged but not re-thrown so they
 * never block the primary action being audited.
 */
export async function logAdminAction(
  adminUserId: string,
  action: string,
  targetType: string,
  targetId: string | null,
  details: Record<string, unknown>,
  ipAddress: string | null
): Promise<void> {
  try {
    await sql`
      INSERT INTO admin_audit_log (admin_user_id, action, target_type, target_id, details, ip_address)
      VALUES (
        ${adminUserId},
        ${action},
        ${targetType},
        ${targetId},
        ${JSON.stringify(details)},
        ${ipAddress}
      )
    `;
  } catch (error) {
    log.error(
      'Failed to write admin audit log entry',
      { adminUserId, action, targetType, targetId, error: error instanceof Error ? error.message : String(error) },
      'AuditService'
    );
  }
}

/**
 * Retrieve paginated audit log entries with optional filters.
 * JOINs with users table to include admin display name.
 */
export async function getAuditLog(
  filters: AuditLogFilters
): Promise<PaginatedResult<AuditLogEntry>> {
  const page = Math.max(1, filters.page ?? 1);
  const limit = Math.min(100, Math.max(1, filters.limit ?? 25));
  const offset = (page - 1) * limit;

  // Build WHERE conditions as an array and join with AND
  // Using parameterised sql tags per condition to avoid concatenation
  // We run two queries: count + data

  // Count query
  const countResult = await sql`
    SELECT COUNT(*) AS total
    FROM admin_audit_log a
    WHERE (${filters.admin_user_id ?? null}::uuid IS NULL OR a.admin_user_id = ${filters.admin_user_id ?? null}::uuid)
      AND (${filters.target_type ?? null}::text IS NULL OR a.target_type = ${filters.target_type ?? null})
      AND (${filters.target_id ?? null}::uuid IS NULL OR a.target_id = ${filters.target_id ?? null}::uuid)
      AND (${filters.action ?? null}::text IS NULL OR a.action ILIKE ${filters.action ? `%${filters.action}%` : null})
      AND (${filters.from_date ?? null}::timestamptz IS NULL OR a.created_at >= ${filters.from_date ?? null}::timestamptz)
      AND (${filters.to_date ?? null}::timestamptz IS NULL OR a.created_at <= ${filters.to_date ?? null}::timestamptz)
  `;

  const total = parseInt((countResult[0] as Row).total as string, 10);

  // Data query with JOIN for admin name
  const rows = await sql`
    SELECT
      a.id,
      a.admin_user_id,
      COALESCE(u.first_name || ' ' || u.last_name, u.email, 'Unknown') AS admin_name,
      a.action,
      a.target_type,
      a.target_id,
      a.details,
      a.ip_address,
      a.created_at
    FROM admin_audit_log a
    LEFT JOIN users u ON u.id = a.admin_user_id
    WHERE (${filters.admin_user_id ?? null}::uuid IS NULL OR a.admin_user_id = ${filters.admin_user_id ?? null}::uuid)
      AND (${filters.target_type ?? null}::text IS NULL OR a.target_type = ${filters.target_type ?? null})
      AND (${filters.target_id ?? null}::uuid IS NULL OR a.target_id = ${filters.target_id ?? null}::uuid)
      AND (${filters.action ?? null}::text IS NULL OR a.action ILIKE ${filters.action ? `%${filters.action}%` : null})
      AND (${filters.from_date ?? null}::timestamptz IS NULL OR a.created_at >= ${filters.from_date ?? null}::timestamptz)
      AND (${filters.to_date ?? null}::timestamptz IS NULL OR a.created_at <= ${filters.to_date ?? null}::timestamptz)
    ORDER BY a.created_at DESC
    LIMIT ${limit} OFFSET ${offset}
  `;

  log.info(`Fetched ${rows.length} audit log entries (page ${page})`, {}, 'AuditService');

  const items: AuditLogEntry[] = (rows as Row[]).map((row) => ({
    id: row.id as string,
    admin_user_id: row.admin_user_id as string,
    admin_name: row.admin_name as string,
    action: row.action as string,
    target_type: row.target_type as string,
    target_id: row.target_id as string | null,
    details: (row.details ?? {}) as Record<string, unknown>,
    ip_address: row.ip_address as string | null,
    created_at: row.created_at instanceof Date
      ? row.created_at.toISOString()
      : (row.created_at as string),
  }));

  return {
    items,
    total,
    page,
    limit,
    total_pages: Math.ceil(total / limit),
  };
}

