/**
 * Admin Company Service
 * Cross-company management operations for ISAFlow Admin Platform
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';

export interface CompanyListFilters {
  search?: string;
  status?: string;
  plan?: string;
  page?: number;
  limit?: number;
  sort_by?: string;
  sort_dir?: 'asc' | 'desc';
}

export interface CompanySummary {
  id: string;
  name: string;
  registration_number: string | null;
  status: string;
  plan: string | null;
  owner_email: string | null;
  user_count: number;
  created_at: string;
}

export interface CompanyDetail extends CompanySummary {
  vat_number: string | null;
  industry: string | null;
  address: string | null;
  phone: string | null;
  website: string | null;
  suspension_reason: string | null;
  suspended_at: string | null;
}

export interface CompanyUser {
  id: string;
  email: string;
  first_name: string;
  last_name: string;
  role: string;
  is_active: boolean;
  joined_at: string;
}

export interface CompanyListResult {
  data: CompanySummary[];
  total: number;
  page: number;
  limit: number;
}

export async function listCompanies(
  filters: CompanyListFilters = {}
): Promise<CompanyListResult> {
  const page = Math.max(1, filters.page ?? 1);
  const limit = Math.min(100, Math.max(1, filters.limit ?? 25));
  const offset = (page - 1) * limit;

  try {
    const rows = await sql`
      SELECT
        c.id,
        c.name,
        c.registration_number,
        COALESCE(c.status, 'active') AS status,
        c.plan,
        u.email AS owner_email,
        COUNT(cu.user_id)::int AS user_count,
        c.created_at
      FROM companies c
      LEFT JOIN company_users cu ON cu.company_id = c.id
      LEFT JOIN users u ON u.id = c.owner_id
      WHERE (
        ${filters.search ? sql`(
          c.name ILIKE ${'%' + filters.search + '%'}
          OR c.registration_number ILIKE ${'%' + filters.search + '%'}
          OR u.email ILIKE ${'%' + filters.search + '%'}
        )` : sql`TRUE`}
      )
      AND (
        ${filters.status ? sql`COALESCE(c.status, 'active') = ${filters.status}` : sql`TRUE`}
      )
      AND (
        ${filters.plan ? sql`c.plan = ${filters.plan}` : sql`TRUE`}
      )
      GROUP BY c.id, c.name, c.registration_number, c.status, c.plan, u.email, c.created_at
      ORDER BY c.created_at DESC
      LIMIT ${limit} OFFSET ${offset}
    `;

    const [countRow] = await sql`
      SELECT COUNT(DISTINCT c.id)::int AS total
      FROM companies c
      LEFT JOIN users u ON u.id = c.owner_id
      WHERE (
        ${filters.search ? sql`(
          c.name ILIKE ${'%' + filters.search + '%'}
          OR c.registration_number ILIKE ${'%' + filters.search + '%'}
          OR u.email ILIKE ${'%' + filters.search + '%'}
        )` : sql`TRUE`}
      )
      AND (
        ${filters.status ? sql`COALESCE(c.status, 'active') = ${filters.status}` : sql`TRUE`}
      )
      AND (
        ${filters.plan ? sql`c.plan = ${filters.plan}` : sql`TRUE`}
      )
    `;

    return {
      data: rows.map((r) => ({
        id: r.id as string,
        name: r.name as string,
        registration_number: r.registration_number as string | null,
        status: r.status as string,
        plan: r.plan as string | null,
        owner_email: r.owner_email as string | null,
        user_count: r.user_count as number,
        created_at:
          r.created_at instanceof Date
            ? r.created_at.toISOString()
            : (r.created_at as string),
      })),
      total: countRow?.total ?? 0,
      page,
      limit,
    };
  } catch (err) {
    log.error('listCompanies failed', { error: err }, 'adminCompanyService');
    throw err;
  }
}

export async function getCompanyDetail(id: string): Promise<CompanyDetail | null> {
  try {
    const [row] = await sql`
      SELECT
        c.id,
        c.name,
        c.registration_number,
        COALESCE(c.status, 'active') AS status,
        c.plan,
        c.vat_number,
        c.industry,
        c.address,
        c.phone,
        c.website,
        c.suspension_reason,
        c.suspended_at,
        u.email AS owner_email,
        COUNT(cu.user_id)::int AS user_count,
        c.created_at
      FROM companies c
      LEFT JOIN company_users cu ON cu.company_id = c.id
      LEFT JOIN users u ON u.id = c.owner_id
      WHERE c.id = ${id}
      GROUP BY c.id, c.name, c.registration_number, c.status, c.plan,
               c.vat_number, c.industry, c.address, c.phone, c.website,
               c.suspension_reason, c.suspended_at, u.email, c.created_at
    `;

    if (!row) return null;

    const toIso = (v: unknown) =>
      v instanceof Date ? v.toISOString() : (v as string | null);

    return {
      id: row.id as string,
      name: row.name as string,
      registration_number: row.registration_number as string | null,
      status: row.status as string,
      plan: row.plan as string | null,
      vat_number: row.vat_number as string | null,
      industry: row.industry as string | null,
      address: row.address as string | null,
      phone: row.phone as string | null,
      website: row.website as string | null,
      suspension_reason: row.suspension_reason as string | null,
      suspended_at: toIso(row.suspended_at),
      owner_email: row.owner_email as string | null,
      user_count: row.user_count as number,
      created_at: toIso(row.created_at) ?? '',
    };
  } catch (err) {
    log.error('getCompanyDetail failed', { id, error: err }, 'adminCompanyService');
    throw err;
  }
}

export async function updateCompany(
  id: string,
  data: Partial<{
    name: string;
    plan: string;
    status: string;
    industry: string;
    phone: string;
    website: string;
    address: string;
  }>
): Promise<CompanyDetail | null> {
  const fields = Object.entries(data).filter(([, v]) => v !== undefined);
  if (fields.length === 0) return getCompanyDetail(id);

  try {
    await sql`
      UPDATE companies
      SET ${sql(data, ...fields.map(([k]) => k))}, updated_at = NOW()
      WHERE id = ${id}
    `;
    return getCompanyDetail(id);
  } catch (err) {
    log.error('updateCompany failed', { id, error: err }, 'adminCompanyService');
    throw err;
  }
}

export async function suspendCompany(id: string, reason: string): Promise<void> {
  try {
    await sql`
      UPDATE companies
      SET status = 'suspended',
          suspension_reason = ${reason},
          suspended_at = NOW(),
          updated_at = NOW()
      WHERE id = ${id}
    `;
  } catch (err) {
    log.error('suspendCompany failed', { id, error: err }, 'adminCompanyService');
    throw err;
  }
}

export async function activateCompany(id: string): Promise<void> {
  try {
    await sql`
      UPDATE companies
      SET status = 'active',
          suspension_reason = NULL,
          suspended_at = NULL,
          updated_at = NOW()
      WHERE id = ${id}
    `;
  } catch (err) {
    log.error('activateCompany failed', { id, error: err }, 'adminCompanyService');
    throw err;
  }
}

export async function deleteCompany(id: string): Promise<void> {
  try {
    await sql`DELETE FROM companies WHERE id = ${id}`;
  } catch (err) {
    log.error('deleteCompany failed', { id, error: err }, 'adminCompanyService');
    throw err;
  }
}

export async function getCompanyUsers(companyId: string): Promise<CompanyUser[]> {
  try {
    const rows = await sql`
      SELECT
        u.id,
        u.email,
        u.first_name,
        u.last_name,
        cu.role,
        u.is_active,
        cu.created_at AS joined_at
      FROM company_users cu
      JOIN users u ON u.id = cu.user_id
      WHERE cu.company_id = ${companyId}
      ORDER BY cu.created_at DESC
    `;

    return rows.map((r) => ({
      id: r.id as string,
      email: r.email as string,
