export async function listCompanies(
  filters: CompanyListFilters = {}
): Promise<CompanyListResult> {
  const page = Math.max(1, filters.page ?? 1);
  const limit = Math.min(100, Math.max(1, filters.limit ?? 25));
  const offset = (page - 1) * limit;

  try {
    const rows = await sql`
      SELECT
        c.id,
        c.name,
        c.registration_number,
        COALESCE(c.status, 'active') AS status,
        c.plan,
        u.email AS owner_email,
        COUNT(cu.user_id)::int AS user_count,
        c.created_at
      FROM companies c
      LEFT JOIN company_users cu ON cu.company_id = c.id
      LEFT JOIN users u ON u.id = c.owner_id
      WHERE (
        ${filters.search ? sql`(
          c.name ILIKE ${'%' + filters.search + '%'}
          OR c.registration_number ILIKE ${'%' + filters.search + '%'}
          OR u.email ILIKE ${'%' + filters.search + '%'}
        )` : sql`TRUE`}
      )
      AND (
        ${filters.status ? sql`COALESCE(c.status, 'active') = ${filters.status}` : sql`TRUE`}
      )
      AND (
        ${filters.plan ? sql`c.plan = ${filters.plan}` : sql`TRUE`}
      )
      GROUP BY c.id, c.name, c.registration_number, c.status, c.plan, u.email, c.created_at
      ORDER BY c.created_at DESC
      LIMIT ${limit} OFFSET ${offset}
    `;

    const [countRow] = await sql`
      SELECT COUNT(DISTINCT c.id)::int AS total
      FROM companies c
      LEFT JOIN users u ON u.id = c.owner_id
      WHERE (
        ${filters.search ? sql`(
          c.name ILIKE ${'%' + filters.search + '%'}
          OR c.registration_number ILIKE ${'%' + filters.search + '%'}
          OR u.email ILIKE ${'%' + filters.search + '%'}
        )` : sql`TRUE`}
      )
