 * Cross-company user management for ISAFlow Admin Platform
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { generateRandomPassword, hashPassword } from '@/lib/auth';

export interface UserListFilters {
  search?: string;
  role?: string;
  company_id?: string;
  status?: string;
  page?: number;
  limit?: number;
}

export interface UserSummary {
  id: string;
  email: string;
  first_name: string;
  last_name: string;
  role: string;
  is_active: boolean;
  company_count: number;
  created_at: string;
}

export interface UserDetail extends UserSummary {
  phone: string | null;
  department: string | null;
  profile_picture: string | null;
  last_login: string | null;
  companies: Array<{ id: string; name: string; role: string }>;
}

export interface UserListResult {
  data: UserSummary[];
  total: number;
  page: number;
  limit: number;
}

export async function listUsers(
  filters: UserListFilters = {}
): Promise<UserListResult> {
  const page = Math.max(1, filters.page ?? 1);
  const limit = Math.min(100, Math.max(1, filters.limit ?? 25));
  const offset = (page - 1) * limit;

  try {
    const rows = await sql`
      SELECT
        u.id,
        u.email,
        u.first_name,
        u.last_name,
        u.role,
        u.is_active,
        COUNT(DISTINCT cu.company_id)::int AS company_count,
        u.created_at
      FROM users u
      LEFT JOIN company_users cu ON cu.user_id = u.id
      WHERE (
        ${filters.search ? sql`(
          u.email ILIKE ${'%' + filters.search + '%'}
          OR u.first_name ILIKE ${'%' + filters.search + '%'}
          OR u.last_name ILIKE ${'%' + filters.search + '%'}
        )` : sql`TRUE`}
      )
      AND (${filters.role ? sql`u.role = ${filters.role}` : sql`TRUE`})
      AND (${filters.company_id ? sql`cu.company_id = ${filters.company_id}` : sql`TRUE`})
      AND (${filters.status === 'active' ? sql`u.is_active = TRUE`
        : filters.status === 'suspended' ? sql`u.is_active = FALSE`
        : sql`TRUE`})
      GROUP BY u.id, u.email, u.first_name, u.last_name, u.role, u.is_active, u.created_at
      ORDER BY u.created_at DESC
      LIMIT ${limit} OFFSET ${offset}
    `;

    const [countRow] = await sql`
      SELECT COUNT(DISTINCT u.id)::int AS total
      FROM users u
      LEFT JOIN company_users cu ON cu.user_id = u.id
      WHERE (
        ${filters.search ? sql`(
          u.email ILIKE ${'%' + filters.search + '%'}
          OR u.first_name ILIKE ${'%' + filters.search + '%'}
          OR u.last_name ILIKE ${'%' + filters.search + '%'}
        )` : sql`TRUE`}
      )
      AND (${filters.role ? sql`u.role = ${filters.role}` : sql`TRUE`})
      AND (${filters.company_id ? sql`cu.company_id = ${filters.company_id}` : sql`TRUE`})
      AND (${filters.status === 'active' ? sql`u.is_active = TRUE`
        : filters.status === 'suspended' ? sql`u.is_active = FALSE`
        : sql`TRUE`})
    `;

    return {
      data: rows.map((r) => ({
        id: r.id as string,
        email: r.email as string,
        first_name: r.first_name as string,
        last_name: r.last_name as string,
        role: r.role as string,
        is_active: r.is_active as boolean,
        company_count: r.company_count as number,
        created_at:
          r.created_at instanceof Date
            ? r.created_at.toISOString()
            : (r.created_at as string),
      })),
      total: countRow?.total ?? 0,
      page,
      limit,
    };
  } catch (err) {
    log.error('listUsers failed', { error: err }, 'adminUserService');
    throw err;
  }
}

export async function getUserDetail(id: string): Promise<UserDetail | null> {
  try {
    const [row] = await sql`
      SELECT
        u.id,
        u.email,
        u.first_name,
        u.last_name,
        u.role,
        u.is_active,
        u.phone,
        u.department,
        u.profile_picture,
        u.created_at,
        MAX(s.created_at) AS last_login
      FROM users u
      LEFT JOIN user_sessions s ON s.user_id = u.id
      WHERE u.id = ${id}
      GROUP BY u.id, u.email, u.first_name, u.last_name, u.role,
               u.is_active, u.phone, u.department, u.profile_picture, u.created_at
    `;

    if (!row) return null;

    const companies = await sql`
      SELECT c.id, c.name, cu.role
      FROM company_users cu
      JOIN companies c ON c.id = cu.company_id
      WHERE cu.user_id = ${id}
      ORDER BY c.name
    `;

    const toIso = (v: unknown) =>
      v instanceof Date ? v.toISOString() : (v as string | null);

    return {
      id: row.id as string,
      email: row.email as string,
      first_name: row.first_name as string,
      last_name: row.last_name as string,
      role: row.role as string,
      is_active: row.is_active as boolean,
      phone: row.phone as string | null,
      department: row.department as string | null,
      profile_picture: row.profile_picture as string | null,
      company_count: companies.length,
      created_at: toIso(row.created_at) ?? '',
      last_login: toIso(row.last_login),
      companies: companies.map((c) => ({
        id: c.id as string,
        name: c.name as string,
        role: c.role as string,
      })),
    };
  } catch (err) {
    log.error('getUserDetail failed', { id, error: err }, 'adminUserService');
    throw err;
  }
}

export async function updateUser(
  id: string,
  data: Partial<{
    first_name: string;
    last_name: string;
    role: string;
    department: string;
    phone: string;
  }>
): Promise<UserDetail | null> {
  const fields = Object.entries(data).filter(([, v]) => v !== undefined);
  if (fields.length === 0) return getUserDetail(id);

  try {
    await sql`
      UPDATE users
      SET ${sql(data, ...fields.map(([k]) => k))}, updated_at = NOW()
      WHERE id = ${id}
    `;
    return getUserDetail(id);
  } catch (err) {
    log.error('updateUser failed', { id, error: err }, 'adminUserService');
    throw err;
  }
}

export async function suspendUser(id: string, reason: string): Promise<void> {
  try {
    await sql`
      UPDATE users
      SET is_active = FALSE, suspension_reason = ${reason}, updated_at = NOW()
      WHERE id = ${id}
    `;
    // Invalidate all active sessions
    await sql`DELETE FROM user_sessions WHERE user_id = ${id}`;
  } catch (err) {
    log.error('suspendUser failed', { id, error: err }, 'adminUserService');
    throw err;
  }
}

export async function activateUser(id: string): Promise<void> {
  try {
    await sql`
      UPDATE users
      SET is_active = TRUE, suspension_reason = NULL, updated_at = NOW()
      WHERE id = ${id}
    `;
  } catch (err) {
    log.error('activateUser failed', { id, error: err }, 'adminUserService');
    throw err;
  }
}

export async function resetPassword(id: string): Promise<{ temporary_password: string }> {
  try {
    const temporaryPassword = generateRandomPassword();
    const hashed = await hashPassword(temporaryPassword);

    await sql`
      UPDATE users
      SET password_hash = ${hashed},
          must_change_password = TRUE,
          updated_at = NOW()
      WHERE id = ${id}
    `;

    return { temporary_password: temporaryPassword };
  } catch (err) {
    log.error('resetPassword failed', { id, error: err }, 'adminUserService');
    throw err;
  }
}

export async function forceLogout(id: string): Promise<void> {
  try {
    await sql`DELETE FROM user_sessions WHERE user_id = ${id}`;
  } catch (err) {
    log.error('forceLogout failed', { id, error: err }, 'adminUserService');
    throw err;
  }
}

export async function addUserToCompany(
  userId: string,
  companyId: string,
  role: string
): Promise<void> {
  try {
    await sql`
      INSERT INTO company_users (user_id, company_id, role, created_at)
      VALUES (${userId}, ${companyId}, ${role}, NOW())
      ON CONFLICT (user_id, company_id) DO UPDATE SET role = ${role}, updated_at = NOW()
    `;
  } catch (err) {
    log.error('addUserToCompany failed', { userId, companyId, error: err }, 'adminUserService');
    throw err;
  }
}

export async function removeUserFromCompany(
  userId: string,
  companyId: string
): Promise<void> {
  try {
    await sql`
      DELETE FROM company_users
      WHERE user_id = ${userId} AND company_id = ${companyId}
    `;
  } catch (err) {
    log.error('removeUserFromCompany failed', { userId, companyId, error: err }, 'adminUserService');
    throw err;
  }
}

