}

export async function updateUser(
  userId: string,
  data: { first_name?: string; last_name?: string; role?: string; phone?: string }
): Promise<void> {
  await sql`
    UPDATE users SET
      first_name = COALESCE(${data.first_name ?? null}, first_name),
      last_name  = COALESCE(${data.last_name ?? null}, last_name),
      role       = COALESCE(${data.role ?? null}, role),
      phone      = COALESCE(${data.phone ?? null}, phone),
      updated_at = NOW()
    WHERE id = ${userId}
  `;
  log.info('updateUser', { userId }, 'AdminUserService');
}

export async function suspendUser(
  userId: string,
  reason: string
): Promise<void> {
  await sql`
    UPDATE users
    SET is_active        = false,
        suspended_reason = ${reason},
        suspended_at     = NOW(),
        updated_at       = NOW()
    WHERE id = ${userId}
  `;
  // Invalidate all active sessions immediately
  await sql`DELETE FROM user_sessions WHERE user_id = ${userId}`;
  log.info('suspendUser', { userId, reason }, 'AdminUserService');
}

export async function activateUser(userId: string): Promise<void> {
  await sql`
    UPDATE users
    SET is_active        = true,
        suspended_reason = NULL,
        suspended_at     = NULL,
        updated_at       = NOW()
    WHERE id = ${userId}
  `;
  log.info('activateUser', { userId }, 'AdminUserService');
}

/**
 * Generate a temporary password, hash and store it, return plain text.
 * Caller is responsible for emailing the reset token/password.
 */
export async function resetPassword(userId: string): Promise<string> {
  const temporaryPassword = generateRandomPassword();
  const hashed = await hashPassword(temporaryPassword);

  await sql`
    UPDATE users
    SET password_hash        = ${hashed},
        must_change_password = true,
        updated_at           = NOW()
    WHERE id = ${userId}
  `;

  log.info('resetPassword — temporary password issued', { userId }, 'AdminUserService');
  return temporaryPassword;
}

/**
 * Force logout by deleting all active sessions for a user.
 * A no-op placeholder message is logged if no sessions exist.
 */
export async function forceLogout(userId: string): Promise<void> {
  await sql`DELETE FROM user_sessions WHERE user_id = ${userId}`;
  log.info('forceLogout — sessions cleared', { userId }, 'AdminUserService');
}

export async function addUserToCompany(
  userId: string,
  companyId: string,
  role: string
): Promise<void> {
  await sql`
    INSERT INTO company_users (user_id, company_id, role, created_at)
    VALUES (${userId}, ${companyId}, ${role}, NOW())
    ON CONFLICT (user_id, company_id) DO UPDATE
      SET role       = EXCLUDED.role,
          updated_at = NOW()
  `;
  log.info('addUserToCompany', { userId, companyId, role }, 'AdminUserService');
}

export async function removeUserFromCompany(
  userId: string,
  companyId: string
): Promise<void> {
  await sql`
    DELETE FROM company_users
    WHERE user_id = ${userId} AND company_id = ${companyId}
  `;
  log.info('removeUserFromCompany', { userId, companyId }, 'AdminUserService');
}

/**
 * Admin Company Detail API
 * GET    /api/admin/companies/[id] — Get company details
 * PATCH  /api/admin/companies/[id] — Update company fields
 * DELETE /api/admin/companies/[id] — Delete company
 */

import type { NextApiResponse } from 'next';
import { withAuth, withRole, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { log } from '@/lib/logger';
import {
  getCompanyDetail,
  updateCompany,
  deleteCompany,
} from '@/modules/admin/services/adminCompanyService';
import { logAdminAction } from '@/modules/admin/services/auditService';

function getIp(req: AuthenticatedNextApiRequest): string | null {
  return (
    (req.headers['x-forwarded-for'] as string)?.split(',')[0]?.trim() ||
    req.socket?.remoteAddress ||
    null
  );
}

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  const companyId = req.query.id as string;

  if (req.method === 'GET') {
    try {
      const company = await getCompanyDetail(companyId);
      if (!company) {
        return apiResponse.notFound(res, 'Company', companyId);
      }
      return apiResponse.success(res, company);
    } catch (err) {
      log.error('Failed to get company detail', { companyId, error: err }, 'admin-api');
      return apiResponse.badRequest(res, 'Failed to get company detail');
    }
  }

  if (req.method === 'PATCH') {
    try {
      const {
        name,
        plan,
        status,
        industry,
        phone,
        website,
        address,
      } = req.body as Record<string, string | undefined>;

      const updated = await updateCompany(companyId, {
        name,
        plan,
        status,
        industry,
        phone,
        website,
        address,
      });

      if (!updated) {
        return apiResponse.notFound(res, 'Company', companyId);
      }

      await logAdminAction(
        req.user.id,
        'company.update',
        'company',
        companyId,
        { fields: Object.keys(req.body as object) },
        getIp(req)
      );

      return apiResponse.success(res, updated);
    } catch (err) {
      log.error('Failed to update company', { companyId, error: err }, 'admin-api');
      return apiResponse.badRequest(res, 'Failed to update company');
    }
  }

  if (req.method === 'DELETE') {
    try {
      await deleteCompany(companyId);

      await logAdminAction(
        req.user.id,
        'company.delete',
        'company',
        companyId,
        null,
        getIp(req)
      );

      return apiResponse.success(res, { deleted: true });
    } catch (err) {
      log.error('Failed to delete company', { companyId, error: err }, 'admin-api');
      return apiResponse.badRequest(res, 'Failed to delete company');
    }
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'PATCH', 'DELETE']);
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withAuth(withRole('super_admin')(withErrorHandler(handler as any) as any) as any);

