/**
 * Plan Service
 * CRUD operations for billing plans in the ISAFlow Admin Platform.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import type { Plan } from '../types/admin.types';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

function toIso(value: unknown): string {
  if (value instanceof Date) return value.toISOString();
  return value as string;
}

function rowToPlan(r: Row): Plan {
  return {
    id: r.id as string,
    code: r.code as string,
    name: r.name as string,
    description: r.description as string | null,
    monthly_price_cents: r.monthly_price_cents as number,
    annual_price_cents: r.annual_price_cents as number,
    currency: r.currency as string,
    features: (r.features ?? {}) as Record<string, unknown>,
    limits: (r.limits ?? {}) as Record<string, unknown>,
    is_active: r.is_active as boolean,
    display_order: r.display_order as number,
    created_at: toIso(r.created_at),
    updated_at: toIso(r.updated_at),
  };
}

export async function listPlans(includeArchived = false): Promise<Plan[]> {
  const rows = includeArchived
    ? await sql`
        SELECT * FROM plans
        ORDER BY display_order ASC, name ASC
      `
    : await sql`
        SELECT * FROM plans
        WHERE is_active = true
        ORDER BY display_order ASC, name ASC
      `;

  log.info(`listPlans: ${rows.length} plans (includeArchived=${includeArchived})`, {}, 'PlanService');
  return (rows as Row[]).map(rowToPlan);
}

export async function getPlan(planId: string): Promise<Plan | null> {
  const rows = await sql`
    SELECT * FROM plans
    WHERE id = ${planId}
    LIMIT 1
  `;
  if (rows.length === 0) return null;
  return rowToPlan(rows[0] as Row);
}

export interface CreatePlanData {
  code: string;
  name: string;
  description?: string;
  monthly_price_cents: number;
  annual_price_cents: number;
  currency?: string;
  features?: Record<string, unknown>;
  limits?: Record<string, unknown>;
  display_order?: number;
}

export async function createPlan(data: CreatePlanData): Promise<Plan> {
  const {
    code,
    name,
    description = null,
    monthly_price_cents,
    annual_price_cents,
    currency = 'ZAR',
    features = {},
    limits = {},
    display_order = 0,
  } = data;

  const rows = await sql`
    INSERT INTO plans (
      code, name, description,
      monthly_price_cents, annual_price_cents, currency,
      features, limits, is_active, display_order,
      created_at, updated_at
    ) VALUES (
      ${code}, ${name}, ${description},
      ${monthly_price_cents}, ${annual_price_cents}, ${currency},
      ${JSON.stringify(features)}::jsonb, ${JSON.stringify(limits)}::jsonb,
      true, ${display_order},
      NOW(), NOW()
    )
    RETURNING *
  `;

  const plan = rowToPlan(rows[0] as Row);
  log.info('createPlan', { planId: plan.id, code }, 'PlanService');
  return plan;
}

const UPDATABLE_PLAN_FIELDS = new Set<string>([
  'name', 'description', 'monthly_price_cents', 'annual_price_cents',
  'currency', 'features', 'limits', 'is_active', 'display_order',
]);

export async function updatePlan(
  planId: string,
  data: Partial<Plan>
): Promise<void> {
  const setClauses: string[] = [];
  const values: unknown[] = [];

  for (const [key, value] of Object.entries(data)) {
    if (!UPDATABLE_PLAN_FIELDS.has(key)) continue;
    setClauses.push(`${key} = $${values.length + 1}`);
    if (key === 'features' || key === 'limits') {
      values.push(JSON.stringify(value));
    } else {
      values.push(value);
    }
  }

  if (setClauses.length === 0) {
    log.info('updatePlan: no updatable fields provided', { planId }, 'PlanService');
    return;
  }

  setClauses.push(`updated_at = NOW()`);

  const setClause = setClauses.join(', ');
  const whereClause = `id = $${values.length + 1}`;
  values.push(planId);

  await sql.unsafe(
    `UPDATE plans SET ${setClause} WHERE ${whereClause}`,
    values as string[]
  );

  log.info('updatePlan', { planId, fields: Object.keys(data) }, 'PlanService');
}

export async function archivePlan(planId: string): Promise<void> {
  await sql`
    UPDATE plans
    SET is_active  = false,
        updated_at = NOW()
    WHERE id = ${planId}
  `;
  log.info('archivePlan', { planId }, 'PlanService');
}

/**
 * Billing Service
 * Subscription and invoice management for the ISAFlow Admin Platform.
 * Covers: overview metrics, subscriptions CRUD, invoice lifecycle.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import type {
  BillingOverview,
  SubscriptionListItem,
  InvoiceListItem,
  PaginatedResult,
} from '../types/admin.types';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

function toIso(value: unknown): string | null {
  if (value == null) return null;
  if (value instanceof Date) return value.toISOString();
  return value as string;
}

// ---------------------------------------------------------------------------
// Overview
// ---------------------------------------------------------------------------

export async function getBillingOverview(): Promise<BillingOverview> {
  const [subStats, churnRow, revenueRow] = await Promise.all([
    getSubscriptionStats(),
    getChurnRate(),
    getRevenueStats(),
  ]);

  const mrr = subStats.mrr_cents;
  const active = subStats.active_subscriptions;
  const arpu = active > 0 ? Math.round(mrr / active) : 0;

  const overview: BillingOverview = {
    mrr_cents: mrr,
    arr_cents: mrr * 12,
    total_subscriptions: subStats.total_subscriptions,
    active_subscriptions: active,
    past_due_count: subStats.past_due_count,
    trial_count: subStats.trial_count,
    churn_rate_percent: churnRow,
    arpu_cents: arpu,
    total_revenue_cents: revenueRow.total_revenue_cents,
    outstanding_cents: revenueRow.outstanding_cents,
  };

  log.info('getBillingOverview', { mrr_cents: mrr, active }, 'BillingService');
  return overview;
}

async function getSubscriptionStats(): Promise<{
  mrr_cents: number;
  total_subscriptions: number;
  active_subscriptions: number;
  past_due_count: number;
  trial_count: number;
}> {
  const rows = await sql`
    SELECT
      COUNT(*)                                                              AS total,
      COUNT(*) FILTER (WHERE s.status = 'active')                          AS active,
      COUNT(*) FILTER (WHERE s.status = 'past_due')                        AS past_due,
      COUNT(*) FILTER (WHERE s.status = 'trial')                           AS trial,
      COALESCE(SUM(
        CASE
          WHEN s.status NOT IN ('active','trial') THEN 0
          WHEN s.billing_cycle = 'monthly' THEN p.monthly_price_cents
          WHEN s.billing_cycle = 'annual'  THEN ROUND(p.annual_price_cents / 12.0)
          ELSE 0
        END
      ), 0)                                                                 AS mrr_cents
    FROM subscriptions s
    INNER JOIN plans p ON p.id = s.plan_id
  `;
  const r = rows[0] as Row;
  return {
    total_subscriptions: parseInt(r.total as string, 10),
    active_subscriptions: parseInt(r.active as string, 10),
    past_due_count: parseInt(r.past_due as string, 10),
    trial_count: parseInt(r.trial as string, 10),
    mrr_cents: parseInt(r.mrr_cents as string, 10),
  };
}

async function getChurnRate(): Promise<number> {
  const rows = await sql`
    SELECT
      COUNT(*) FILTER (
        WHERE status = 'cancelled'
          AND cancelled_at >= NOW() - INTERVAL '30 days'
      )::float AS cancelled_30d,
      GREATEST(
        COUNT(*) FILTER (
          WHERE status IN ('active','trial','past_due')
             OR (status = 'cancelled' AND cancelled_at >= NOW() - INTERVAL '30 days')
        ), 1
      )::float AS base
    FROM subscriptions
  `;
  const r = rows[0] as Row;
  const rate = ((r.cancelled_30d as number) / (r.base as number)) * 100;
  return Math.round(rate * 100) / 100;
}

async function getRevenueStats(): Promise<{
  total_revenue_cents: number;
  outstanding_cents: number;
}> {
  const rows = await sql`
    SELECT
      COALESCE(SUM(total_cents) FILTER (WHERE status = 'paid'), 0)               AS total_revenue_cents,
      COALESCE(SUM(total_cents) FILTER (WHERE status IN ('sent','overdue')), 0)   AS outstanding_cents
    FROM admin_invoices
  `;
  const r = rows[0] as Row;
  return {
    total_revenue_cents: parseInt(r.total_revenue_cents as string, 10),
    outstanding_cents: parseInt(r.outstanding_cents as string, 10),
  };
}

// ---------------------------------------------------------------------------
// Subscriptions
// ---------------------------------------------------------------------------

const ALLOWED_SUB_SORT: Record<string, string> = {
  created_at: 's.created_at',
  status: 's.status',
  company_name: 'c.name',
  plan_name: 'p.name',
};

export async function listSubscriptions(filters: {
  status?: string;
  plan_id?: string;
  search?: string;
  page?: number;
  limit?: number;
  sort_by?: string;
  sort_dir?: 'asc' | 'desc';
}): Promise<PaginatedResult<SubscriptionListItem>> {
  const page = Math.max(1, filters.page ?? 1);
  const limit = Math.min(100, Math.max(1, filters.limit ?? 25));
  const offset = (page - 1) * limit;
  const sortCol = ALLOWED_SUB_SORT[filters.sort_by ?? ''] ?? 's.created_at';
  const sortDir = filters.sort_dir === 'asc' ? sql`ASC` : sql`DESC`;
  const search = filters.search ? `%${filters.search}%` : null;

  const [countRow] = await sql`
    SELECT COUNT(*) AS total
    FROM subscriptions s
    INNER JOIN companies c ON c.id = s.company_id
    INNER JOIN plans p ON p.id = s.plan_id
    WHERE (${filters.status ?? null}::text IS NULL OR s.status = ${filters.status ?? null})
      AND (${filters.plan_id ?? null}::uuid IS NULL OR s.plan_id = ${filters.plan_id ?? null}::uuid)
      AND (${search}::text IS NULL OR c.name ILIKE ${search})
  `;

  const rows = await sql`
    SELECT
      s.id, s.company_id, c.name AS company_name,
      s.plan_id, p.name AS plan_name, p.code AS plan_code,
      s.status, s.billing_cycle,
      s.current_period_start, s.current_period_end,
      COALESCE(s.cancel_at_period_end, false) AS cancel_at_period_end,
      COALESCE(s.discount_percent, 0)          AS discount_percent,
      CASE
        WHEN s.billing_cycle = 'monthly' THEN p.monthly_price_cents
        WHEN s.billing_cycle = 'annual'  THEN ROUND(p.annual_price_cents / 12.0)
        ELSE 0
      END AS monthly_amount_cents,
      s.created_at
    FROM subscriptions s
    INNER JOIN companies c ON c.id = s.company_id
    INNER JOIN plans p ON p.id = s.plan_id
    WHERE (${filters.status ?? null}::text IS NULL OR s.status = ${filters.status ?? null})
      AND (${filters.plan_id ?? null}::uuid IS NULL OR s.plan_id = ${filters.plan_id ?? null}::uuid)
      AND (${search}::text IS NULL OR c.name ILIKE ${search})
    ORDER BY ${sql.unsafe(sortCol)} ${sortDir}
    LIMIT ${limit} OFFSET ${offset}
  `;

  const total = parseInt((countRow as Row).total as string, 10);
  log.info(`listSubscriptions: ${rows.length} rows (page ${page})`, {}, 'BillingService');

  return {
    items: (rows as Row[]).map(rowToSubscription),
    total,
    page,
    limit,
    total_pages: Math.ceil(total / limit),
  };
}

function rowToSubscription(r: Row): SubscriptionListItem {
  return {
    id: r.id as string,
    company_id: r.company_id as string,
    company_name: r.company_name as string,
    plan_id: r.plan_id as string,
    plan_name: r.plan_name as string,
    plan_code: r.plan_code as string,
    status: r.status as string,
    billing_cycle: r.billing_cycle as string,
    current_period_start: toIso(r.current_period_start),
    current_period_end: toIso(r.current_period_end),
    cancel_at_period_end: r.cancel_at_period_end as boolean,
    discount_percent: r.discount_percent as number,
    monthly_amount_cents: parseInt(r.monthly_amount_cents as string, 10),
    created_at: toIso(r.created_at) ?? '',
  };
}

export async function getSubscription(
  subscriptionId: string
): Promise<SubscriptionListItem | null> {
  const rows = await sql`
    SELECT
      s.id, s.company_id, c.name AS company_name,
      s.plan_id, p.name AS plan_name, p.code AS plan_code,
      s.status, s.billing_cycle,
      s.current_period_start, s.current_period_end,
      COALESCE(s.cancel_at_period_end, false) AS cancel_at_period_end,
      COALESCE(s.discount_percent, 0)          AS discount_percent,
      CASE
        WHEN s.billing_cycle = 'monthly' THEN p.monthly_price_cents
        WHEN s.billing_cycle = 'annual'  THEN ROUND(p.annual_price_cents / 12.0)
        ELSE 0
      END AS monthly_amount_cents,
      s.created_at
    FROM subscriptions s
    INNER JOIN companies c ON c.id = s.company_id
    INNER JOIN plans p ON p.id = s.plan_id
    WHERE s.id = ${subscriptionId}
    LIMIT 1
  `;
  if (rows.length === 0) return null;
  return rowToSubscription(rows[0] as Row);
}

export async function createSubscription(data: {
  company_id: string;
  plan_id: string;
  billing_cycle: string;
  discount_percent?: number;
  notes?: string;
}): Promise<string> {
  const { company_id, plan_id, billing_cycle, discount_percent = 0, notes = null } = data;
  const periodDays = billing_cycle === 'annual' ? 365 : 30;

  const rows = await sql`
    INSERT INTO subscriptions (
      company_id, plan_id, status, billing_cycle,
      current_period_start, current_period_end,
      cancel_at_period_end, discount_percent, notes,
      created_at, updated_at
    ) VALUES (
      ${company_id}::uuid, ${plan_id}::uuid,
      'active', ${billing_cycle},
      NOW(), NOW() + INTERVAL '1 day' * ${periodDays},
      false, ${discount_percent}, ${notes},
      NOW(), NOW()
    )
    RETURNING id
  `;

  const id = (rows[0] as Row).id as string;
  log.info('createSubscription', { id, company_id, plan_id, billing_cycle }, 'BillingService');
  return id;
}

export async function updateSubscription(
  subscriptionId: string,
  data: {
    plan_id?: string;
    billing_cycle?: string;
    discount_percent?: number;
    status?: string;
    notes?: string;
  }
): Promise<void> {
  const { plan_id, billing_cycle, discount_percent, status, notes } = data;

  await sql`
    UPDATE subscriptions SET
      plan_id          = COALESCE(${plan_id ?? null}::uuid, plan_id),
      billing_cycle    = COALESCE(${billing_cycle ?? null}, billing_cycle),
      discount_percent = COALESCE(${discount_percent ?? null}, discount_percent),
      status           = COALESCE(${status ?? null}, status),
      notes            = COALESCE(${notes ?? null}, notes),
      updated_at       = NOW()
    WHERE id = ${subscriptionId}
  `;

  log.info('updateSubscription', { subscriptionId }, 'BillingService');
}

export async function cancelSubscription(
  subscriptionId: string,
  atPeriodEnd: boolean
): Promise<void> {
  if (atPeriodEnd) {
    await sql`
      UPDATE subscriptions
      SET cancel_at_period_end = true,
          updated_at           = NOW()
      WHERE id = ${subscriptionId}
    `;
  } else {
    await sql`
      UPDATE subscriptions
      SET status       = 'cancelled',
          cancelled_at = NOW(),
          updated_at   = NOW()
      WHERE id = ${subscriptionId}
    `;
  }
  log.info('cancelSubscription', { subscriptionId, atPeriodEnd }, 'BillingService');
}

// ---------------------------------------------------------------------------
// Invoices
// ---------------------------------------------------------------------------

const ALLOWED_INV_SORT: Record<string, string> = {
  created_at: 'i.created_at',
  due_date: 'i.due_date',
  status: 'i.status',
  total_cents: 'i.total_cents',
  company_name: 'c.name',
  invoice_number: 'i.invoice_number',
};

export async function listInvoices(filters: {
  company_id?: string;
  status?: string;
  from_date?: string;
  to_date?: string;
  search?: string;
  page?: number;
  limit?: number;
  sort_by?: string;
  sort_dir?: 'asc' | 'desc';
}): Promise<PaginatedResult<InvoiceListItem>> {
  const page = Math.max(1, filters.page ?? 1);
  const limit = Math.min(100, Math.max(1, filters.limit ?? 25));
  const offset = (page - 1) * limit;
  const sortCol = ALLOWED_INV_SORT[filters.sort_by ?? ''] ?? 'i.created_at';
  const sortDir = filters.sort_dir === 'asc' ? sql`ASC` : sql`DESC`;
  const search = filters.search ? `%${filters.search}%` : null;

  const [countRow] = await sql`
    SELECT COUNT(*) AS total
    FROM admin_invoices i
    INNER JOIN companies c ON c.id = i.company_id
    WHERE (${filters.company_id ?? null}::uuid IS NULL OR i.company_id = ${filters.company_id ?? null}::uuid)
      AND (${filters.status ?? null}::text IS NULL OR i.status = ${filters.status ?? null})
      AND (${filters.from_date ?? null}::date IS NULL OR i.created_at::date >= ${filters.from_date ?? null}::date)
      AND (${filters.to_date ?? null}::date IS NULL OR i.created_at::date <= ${filters.to_date ?? null}::date)
      AND (${search}::text IS NULL OR c.name ILIKE ${search} OR i.invoice_number ILIKE ${search})
  `;

  const rows = await sql`
    SELECT
      i.id, i.company_id, c.name AS company_name,
      i.invoice_number, i.status,
      i.subtotal_cents, i.tax_cents, i.total_cents, i.currency,
      i.due_date, i.paid_at, i.payment_method,
      i.created_at
    FROM admin_invoices i
    INNER JOIN companies c ON c.id = i.company_id
    WHERE (${filters.company_id ?? null}::uuid IS NULL OR i.company_id = ${filters.company_id ?? null}::uuid)
      AND (${filters.status ?? null}::text IS NULL OR i.status = ${filters.status ?? null})
      AND (${filters.from_date ?? null}::date IS NULL OR i.created_at::date >= ${filters.from_date ?? null}::date)
      AND (${filters.to_date ?? null}::date IS NULL OR i.created_at::date <= ${filters.to_date ?? null}::date)
      AND (${search}::text IS NULL OR c.name ILIKE ${search} OR i.invoice_number ILIKE ${search})
    ORDER BY ${sql.unsafe(sortCol)} ${sortDir}
    LIMIT ${limit} OFFSET ${offset}
  `;

  const total = parseInt((countRow as Row).total as string, 10);
  log.info(`listInvoices: ${rows.length} rows (page ${page})`, {}, 'BillingService');

  return {
    items: (rows as Row[]).map((r: Row) => ({
      id: r.id as string,
      company_id: r.company_id as string,
      company_name: r.company_name as string,
      invoice_number: r.invoice_number as string,
      status: r.status as string,
      subtotal_cents: r.subtotal_cents as number,
      tax_cents: r.tax_cents as number,
      total_cents: r.total_cents as number,
      currency: r.currency as string,
      due_date: toIso(r.due_date),
      paid_at: toIso(r.paid_at),
      payment_method: r.payment_method as string | null,
      created_at: toIso(r.created_at) ?? '',
    })),
    total,
    page,
    limit,
    total_pages: Math.ceil(total / limit),
  };
}

export async function createInvoice(data: {
  company_id: string;
  subscription_id?: string;
  subtotal_cents: number;
  tax_cents: number;
  total_cents: number;
  due_date?: string;
  line_items?: unknown[];
  notes?: string;
}): Promise<string> {
  const {
    company_id, subscription_id = null,
    subtotal_cents, tax_cents, total_cents,
    due_date = null, line_items = [], notes = null,
  } = data;

  // Generate sequential invoice number: INV-YYYYMM-XXXX
  const seqRows = await sql`
    SELECT COUNT(*) AS count FROM admin_invoices
    WHERE invoice_number LIKE 'INV-' || TO_CHAR(NOW(), 'YYYYMM') || '-%'
  `;
  const seq = parseInt((seqRows[0] as Row).count as string, 10) + 1;
  const yyyymm = new Date().toISOString().slice(0, 7).replace('-', '');
  const invoice_number = `INV-${yyyymm}-${String(seq).padStart(4, '0')}`;

  const rows = await sql`
    INSERT INTO admin_invoices (
      company_id, subscription_id, invoice_number, status,
      subtotal_cents, tax_cents, total_cents, currency,
      due_date, line_items, notes, created_at
    ) VALUES (
      ${company_id}::uuid,
      ${subscription_id}::uuid,
      ${invoice_number}, 'draft',
      ${subtotal_cents}, ${tax_cents}, ${total_cents}, 'ZAR',
      ${due_date}::date,
      ${JSON.stringify(line_items)}::jsonb,
      ${notes},
      NOW()
    )
    RETURNING id
  `;

  const id = (rows[0] as Row).id as string;
  log.info('createInvoice', { id, invoice_number, company_id }, 'BillingService');
  return id;
}

export async function markInvoicePaid(
  invoiceId: string,
  paymentMethod: string
): Promise<void> {
  await sql`
    UPDATE admin_invoices
    SET status         = 'paid',
        paid_at        = NOW(),
        payment_method = ${paymentMethod}
    WHERE id = ${invoiceId}
  `;
  log.info('markInvoicePaid', { invoiceId, paymentMethod }, 'BillingService');
}

export async function sendInvoice(invoiceId: string): Promise<void> {
  await sql`
    UPDATE admin_invoices
    SET status = 'sent'
    WHERE id = ${invoiceId}
      AND status = 'draft'
  `;
  log.info('sendInvoice', { invoiceId }, 'BillingService');
}

