        notes?: string;
      };

      if (!company_id || !plan_id) {
        return apiResponse.badRequest(res, 'company_id and plan_id are required');
      }

      const subscription = await createSubscription({
        company_id,
        plan_id,
        billing_cycle,
        discount_percent,
        notes,
      });

      await logAdminAction(
        req.user.id,
        'subscription.create',
