async function getSubscriptionStats(): Promise<{
  mrr_cents: number;
  total_subscriptions: number;
  active_subscriptions: number;
  past_due_count: number;
  trial_count: number;
}> {
  const rows = await sql`
    SELECT
      COUNT(*)                                                          AS total,
      COUNT(*) FILTER (WHERE s.status = 'active')                      AS active,
      COUNT(*) FILTER (WHERE s.status = 'past_due')                    AS past_due,
      COUNT(*) FILTER (WHERE s.status = 'trial')                       AS trial,
      COALESCE(SUM(
        CASE
          WHEN s.status NOT IN ('active','trial') THEN 0
          WHEN s.billing_cycle = 'monthly' THEN p.monthly_price_cents
          WHEN s.billing_cycle = 'annual'  THEN ROUND(p.annual_price_cents / 12.0)
          ELSE 0
        END
      ), 0)                                                             AS mrr_cents
    FROM subscriptions s
    INNER JOIN plans p ON p.id = s.plan_id
  `;
  const r = rows[0] as Row;
  return {
    total_subscriptions: parseInt(r.total as string, 10),
    active_subscriptions: parseInt(r.active as string, 10),
    past_due_count: parseInt(r.past_due as string, 10),
    trial_count: parseInt(r.trial as string, 10),
    mrr_cents: parseInt(r.mrr_cents as string, 10),
  };
}

async function getChurnRate(): Promise<number> {
  const rows = await sql`
    SELECT
      COUNT(*) FILTER (
        WHERE status = 'cancelled'
          AND cancelled_at >= NOW() - INTERVAL '30 days'
      )::float AS cancelled_30d,
      GREATEST(
        COUNT(*) FILTER (
          WHERE status IN ('active','trial','past_due')
             OR (status = 'cancelled' AND cancelled_at >= NOW() - INTERVAL '30 days')
        ), 1
      )::float AS base
    FROM subscriptions
  `;
  const r = rows[0] as Row;
  const rate = ((r.cancelled_30d as number) / (r.base as number)) * 100;
  return Math.round(rate * 100) / 100;
}

async function getRevenueStats(): Promise<{
  total_revenue_cents: number;
  outstanding_cents: number;
}> {
  const rows = await sql`
    SELECT
      COALESCE(SUM(total_cents) FILTER (WHERE status = 'paid'), 0)             AS total_revenue_cents,
      COALESCE(SUM(total_cents) FILTER (WHERE status IN ('sent','overdue')), 0) AS outstanding_cents
    FROM admin_invoices
  `;
  const r = rows[0] as Row;
  return {
    total_revenue_cents: parseInt(r.total_revenue_cents as string, 10),
    outstanding_cents: parseInt(r.outstanding_cents as string, 10),
  };
}

