/**
 * Invoice & Credit Note PDF Generator
 * Server-side PDF generation using jsPDF + jspdf-autotable
 * Returns Buffer for API responses and email attachments
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

// ─── Currency Formatting ────────────────────────────────────────────────────

const fmtZAR = (amount: number): string =>
  'R ' + Number(amount).toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g, ',');

const fmtDate = (d: string | Date | null | undefined): string => {
  if (!d) return '—';
  const str = d instanceof Date ? d.toISOString() : String(d);
  const parts = str.split('T')[0]?.split('-') ?? [];
  if (parts.length === 3) return `${parts[2]}/${parts[1]}/${parts[0]}`;
  return str;
};

// ─── Company Details (loaded from DB settings) ─────────────────────────────

interface CompanyDetails {
  name: string;
  address: string;
  phone: string;
  email: string;
  vatNumber: string;
  bankName: string;
  bankAccountName: string;
  bankAccountNumber: string;
  bankBranchCode: string;
  bankReference: string;
}

const COMPANY_SETTINGS_KEYS = [
  'company_name', 'company_address', 'company_phone', 'company_email',
  'company_vat_number', 'bank_name', 'bank_account_name',
  'bank_account_number', 'bank_branch_code',
] as const;

async function getCompanyDetails(): Promise<CompanyDetails> {
  try {
    const rows = await sql`
      SELECT key, value FROM app_settings
      WHERE key = ANY(${COMPANY_SETTINGS_KEYS as unknown as string[]})
    `;
    const settings: Record<string, string> = {};
    for (const row of rows) {
      settings[row.key as string] = String(row.value ?? '');
    }
    return {
      name: settings.company_name || 'Company Name Not Set',
      address: settings.company_address || '',
      phone: settings.company_phone || '',
      email: settings.company_email || '',
      vatNumber: settings.company_vat_number || '',
      bankName: settings.bank_name || '',
      bankAccountName: settings.bank_account_name || '',
      bankAccountNumber: settings.bank_account_number || '',
      bankBranchCode: settings.bank_branch_code || '',
      bankReference: '',
    };
  } catch {
    log.warn('Failed to load company settings for PDF, using fallbacks', {}, 'invoicePdf');
    return {
      name: 'Company Name Not Set',
      address: '', phone: '', email: '', vatNumber: '',
      bankName: '', bankAccountName: '', bankAccountNumber: '',
      bankBranchCode: '', bankReference: '',
    };
  }
}

async function getCompanyDetailsFromCompany(companyId: string): Promise<CompanyDetails> {
  try {
    const rows = await sql`
      SELECT name, address_line1, address_line2, city, province, postal_code,
             phone, email, vat_number,
             bank_name, bank_account_number, bank_branch_code
      FROM companies WHERE id = ${companyId}::UUID
    `;
    if (rows.length > 0) {
      const c = rows[0] as Row;
      const addressParts = [c.address_line1, c.address_line2, c.city, c.province, c.postal_code].filter(Boolean);
      return {
        name: c.name || 'Company Name Not Set',
        address: addressParts.join(', '),
        phone: c.phone || '',
        email: c.email || '',
        vatNumber: c.vat_number || '',
        bankName: c.bank_name || '',
        bankAccountName: c.name || '',
        bankAccountNumber: c.bank_account_number || '',
        bankBranchCode: c.bank_branch_code || '',

/**
 * PRD-060: FibreFlow Accounting Module
 * Bank PDF Statement Parser
 *
 * Extracts transactions from bank PDF statements using pdf-parse.
 * Primary target: ABSA PDF statements.
 *
 * ABSA PDF transaction line format:
 *   15 Jan 2026  POS Purchase Woolworths  -1,234.56  45,678.90
 */

import { log } from '@/lib/logger';
import type { BankCsvParseResult, ParsedBankTransaction } from '../types/bank.types';
import { isVlmAvailable, extractBankStatementWithVlm } from '../services/vlmService';

// pdf-parse uses export= (CommonJS), so we use require() at runtime.
// Type definition for the parsed result.
interface PdfParseResult {
  text: string;
  numpages: number;
}
type PdfParseFunction = (buffer: Buffer) => Promise<PdfParseResult>;

// Month name lookup for ABSA PDF date parsing ("15 Jan 2026")
const MONTH_MAP: Record<string, string> = {
  jan: '01', feb: '02', mar: '03', apr: '04', may: '05', jun: '06',
  jul: '07', aug: '08', sep: '09', oct: '10', nov: '11', dec: '12',
};

/**
 * Parse a currency string that may contain commas, spaces, and a leading minus.
 * Examples: "-1,234.56", "45 678.90", "1234.56"
 */
function parsePdfAmount(raw: string): number | null {
  const cleaned = raw.replace(/\s/g, '').replace(/,/g, '');
  const num = parseFloat(cleaned);
  return isNaN(num) ? null : num;
}

/**
 * Parse ABSA-style date string "15 Jan 2026" → "2026-01-15".
 */
function parseAbsaDate(day: string, mon: string, year: string): string | null {
  const monthNum = MONTH_MAP[mon.toLowerCase()];
  if (!monthNum) return null;
  const d = parseInt(day, 10);
  const y = parseInt(year, 10);
  if (isNaN(d) || isNaN(y) || d < 1 || d > 31 || y < 2000 || y > 2099) return null;
  return `${y}-${monthNum}-${String(d).padStart(2, '0')}`;
}

/**
 * Parse ABSA PDF transaction lines from extracted text.
 *
 * ABSA PDF lines follow this pattern:
 *   <day> <Mon> <year>  <description text>  <signed-amount>  <balance>
 *
 * The regex captures:
 *   - date: "15 Jan 2026"
 *   - description: arbitrary text (greedy, trimmed)
 *   - amount: "-1,234.56" or "1,234.56"
 *   - balance (optional): second numeric at end of line
 */
function parseAbsaTextLines(text: string): BankCsvParseResult {
  const result: BankCsvParseResult = {
    transactions: [],
    errors: [],
    bankFormat: 'absa',
  };

  // Match lines that start with a date pattern: "15 Jan 2026"
  // Then description, then one or two signed/unsigned numeric amounts
  const linePattern =
    /^(\d{1,2})\s+(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)\s+(\d{4})\s+(.+?)\s+([-]?\d[\d,\s]*\.\d{2})\s+([-]?\d[\d,\s]*\.\d{2})?$/im;

  const lines = text.split('\n');
  let lineNum = 0;

  for (const rawLine of lines) {
    lineNum++;
    const line = rawLine.trim();
    if (!line) continue;

    const match = line.match(linePattern);
    if (!match) continue;

    const [, day, mon, year, desc, amountRaw, balanceRaw] = match;

    const transactionDate = parseAbsaDate(day!, mon!, year!);
    if (!transactionDate) {
      result.errors.push({ row: lineNum, error: `Invalid date: ${day} ${mon} ${year}` });
      continue;
    }

    const amount = parsePdfAmount(amountRaw!);
    if (amount === null) {
      result.errors.push({ row: lineNum, error: `Invalid amount: ${amountRaw}` });
      continue;
    }

/**
 * Customer Statement PDF Generator
 * Produces a portrait A4 PDF statement for a single customer
 * using jsPDF + jspdf-autotable (same pattern as reconReportPdf.ts)
 *
 * jsPDF and jspdf-autotable are loaded dynamically to keep them out of the
 * initial page bundle — they are only needed when the user clicks "Download PDF".
 */

// ─── Types ────────────────────────────────────────────────────────────────────

export interface StatementTransaction {
  date: string;
  type: 'invoice' | 'payment' | 'credit_note';
  reference: string;
  description: string;
  debit: number;
  credit: number;
  balance: number;
}

export interface StatementData {
  clientName: string;
  clientEmail?: string;
  clientPhone?: string;
  asAtDate: string;
  totalInvoiced: number;
  totalPaid: number;
  totalCredits: number;
  balanceOutstanding: number;
  transactions: StatementTransaction[];
  companyName?: string;
  companyVatNumber?: string;
}

// ─── Private helpers (no jsPDF type reference — avoids static import) ─────────

const fmtZAR = (amount: number): string =>
  new Intl.NumberFormat('en-ZA', {
    style: 'currency',
    currency: 'ZAR',
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  }).format(amount);

const fmtDate = (d: string): string => {
  if (!d) return '—';
  const parts = d.split('T')[0]?.split('-') ?? [];
  if (parts.length === 3) return `${parts[2]}/${parts[1]}/${parts[0]}`;
  return d;
};

// ─── Main Export Function ─────────────────────────────────────────────────────

/**
 * Generate a portrait A4 PDF customer statement and return it as a Blob.
 * Call `URL.createObjectURL(blob)` to download in the browser.
 *
 * This function is async because it dynamically imports jsPDF and
 * jspdf-autotable to avoid including them in the initial page bundle.
 */
