  if (!v) return '—';
  return new Date(v).toLocaleString('en-ZA', { dateStyle: 'medium', timeStyle: 'short' });
}

const EMPTY_FORM = {
  title: '', message: '', type: 'info', target: 'all',
  target_ids: '', starts_at: '', ends_at: '', is_dismissible: true,
};

type FormState = typeof EMPTY_FORM;

interface ModalProps {
  initial: FormState;
  onClose: () => void;
  onSave: (data: FormState) => Promise<void>;
  saving: boolean;
}

function AnnouncementModal({ initial, onClose, onSave, saving }: ModalProps) {
