/**
 * Admin Announcements Manager
 * List, create, edit, and delete system announcements.
 */

import { useState, useEffect, useCallback } from 'react';
import { AdminLayout } from '@/components/admin/AdminLayout';
import { ConfirmModal } from '@/components/admin/ConfirmModal';
import { apiFetch } from '@/lib/apiFetch';
import { Plus, Pencil, Trash2, AlertCircle, Loader2, X } from 'lucide-react';
import type { Announcement } from '@/modules/admin/types/admin.types';

const TYPE_BADGE: Record<string, string> = {
  info:        'bg-blue-500/10 text-blue-600 dark:text-blue-400',
  warning:     'bg-yellow-500/10 text-yellow-600 dark:text-yellow-400',
  maintenance: 'bg-orange-500/10 text-orange-600 dark:text-orange-400',
  feature:     'bg-teal-500/10 text-teal-600 dark:text-teal-400',
};

function fmtDate(v: string | null) {
  if (!v) return '—';
  return new Date(v).toLocaleString('en-ZA', { dateStyle: 'medium', timeStyle: 'short' });
}

const EMPTY_FORM = {
  title: '', message: '', type: 'info', target: 'all',
  target_ids: '', starts_at: '', ends_at: '', is_dismissible: true,
};

type FormState = typeof EMPTY_FORM;

interface ModalProps {
  initial: FormState;
  onClose: () => void;
  onSave: (data: FormState) => Promise<void>;
  saving: boolean;
}

function AnnouncementModal({ initial, onClose, onSave, saving }: ModalProps) {
  const [form, setForm] = useState<FormState>(initial);
  const set = (k: keyof FormState, v: string | boolean) =>
    setForm((f) => ({ ...f, [k]: v }));

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50">
      <div className="bg-white dark:bg-gray-800 rounded-xl shadow-xl w-full max-w-lg mx-4 p-6 space-y-4">
        <div className="flex items-center justify-between">
          <h2 className="text-lg font-semibold text-gray-900 dark:text-white">
            {initial.title ? 'Edit Announcement' : 'New Announcement'}
          </h2>
          <button onClick={onClose} className="text-gray-400 hover:text-gray-600"><X className="w-5 h-5" /></button>
        </div>

        <div className="space-y-3">
          <div>
            <label className="block text-xs font-medium text-gray-600 dark:text-gray-400 mb-1">Title</label>
            <input value={form.title} onChange={e => set('title', e.target.value)}
              className="w-full rounded-lg border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700 text-sm px-3 py-2 text-gray-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-teal-500" />
          </div>
          <div>
            <label className="block text-xs font-medium text-gray-600 dark:text-gray-400 mb-1">Message</label>
            <textarea rows={3} value={form.message} onChange={e => set('message', e.target.value)}
              className="w-full rounded-lg border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700 text-sm px-3 py-2 text-gray-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-teal-500 resize-none" />
          </div>
          <div className="grid grid-cols-2 gap-3">
