/**
 * Admin Announcements Manager
 * List, create, edit, and delete system announcements.
 */

import { useState, useEffect, useCallback } from 'react';
import { AdminLayout } from '@/components/admin/AdminLayout';
import { ConfirmModal } from '@/components/admin/ConfirmModal';
import { apiFetch } from '@/lib/apiFetch';
import { Plus, Pencil, Trash2, AlertCircle, Loader2, X } from 'lucide-react';
import type { Announcement } from '@/modules/admin/types/admin.types';

const TYPE_BADGE: Record<string, string> = {
  info:        'bg-blue-500/10 text-blue-600 dark:text-blue-400',
  warning:     'bg-yellow-500/10 text-yellow-600 dark:text-yellow-400',
  maintenance: 'bg-orange-500/10 text-orange-600 dark:text-orange-400',
  feature:     'bg-teal-500/10 text-teal-600 dark:text-teal-400',
};

function fmtDate(v: string | null) {
  if (!v) return '—';
  return new Date(v).toLocaleString('en-ZA', { dateStyle: 'medium', timeStyle: 'short' });
}

const EMPTY_FORM = {
  title: '', message: '', type: 'info', target: 'all',
  target_ids: '', starts_at: '', ends_at: '', is_dismissible: true,
};

type FormState = typeof EMPTY_FORM;

interface ModalProps {
  initial: FormState;
  onClose: () => void;
  onSave: (data: FormState) => Promise<void>;
  saving: boolean;
}

function AnnouncementModal({ initial, onClose, onSave, saving }: ModalProps) {
  const [form, setForm] = useState<FormState>(initial);
  const set = (k: keyof FormState, v: string | boolean) =>
    setForm((f) => ({ ...f, [k]: v }));

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50">
      <div className="bg-white dark:bg-gray-800 rounded-xl shadow-xl w-full max-w-lg mx-4 p-6 space-y-4">
        <div className="flex items-center justify-between">
          <h2 className="text-lg font-semibold text-gray-900 dark:text-white">
            {initial.title ? 'Edit Announcement' : 'New Announcement'}
          </h2>
          <button onClick={onClose} className="text-gray-400 hover:text-gray-600"><X className="w-5 h-5" /></button>
        </div>

        <div className="space-y-3">
          <div>
            <label className="block text-xs font-medium text-gray-600 dark:text-gray-400 mb-1">Title</label>
            <input value={form.title} onChange={e => set('title', e.target.value)}
              className="w-full rounded-lg border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700 text-sm px-3 py-2 text-gray-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-teal-500" />
          </div>
          <div>
            <label className="block text-xs font-medium text-gray-600 dark:text-gray-400 mb-1">Message</label>
            <textarea rows={3} value={form.message} onChange={e => set('message', e.target.value)}
              className="w-full rounded-lg border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700 text-sm px-3 py-2 text-gray-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-teal-500 resize-none" />
          </div>
          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="block text-xs font-medium text-gray-600 dark:text-gray-400 mb-1">Type</label>
              <select value={form.type} onChange={e => set('type', e.target.value)}
                className="w-full rounded-lg border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700 text-sm px-3 py-2 text-gray-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-teal-500">
                <option value="info">Info</option>
                <option value="warning">Warning</option>
                <option value="maintenance">Maintenance</option>
                <option value="feature">Feature</option>
              </select>
            </div>
            <div>
              <label className="block text-xs font-medium text-gray-600 dark:text-gray-400 mb-1">Target</label>
              <select value={form.target} onChange={e => set('target', e.target.value)}
                className="w-full rounded-lg border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700 text-sm px-3 py-2 text-gray-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-teal-500">
                <option value="all">All</option>
                <option value="plan">Plan</option>
                <option value="company">Company</option>
              </select>
            </div>
          </div>
          {form.target !== 'all' && (
            <div>
              <label className="block text-xs font-medium text-gray-600 dark:text-gray-400 mb-1">
                Target IDs (comma-separated UUIDs)
              </label>
              <input value={form.target_ids} onChange={e => set('target_ids', e.target.value)}
                placeholder="uuid1, uuid2, ..."
                className="w-full rounded-lg border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700 text-sm px-3 py-2 text-gray-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-teal-500" />
            </div>
          )}
          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="block text-xs font-medium text-gray-600 dark:text-gray-400 mb-1">Starts At</label>
              <input type="datetime-local" value={form.starts_at} onChange={e => set('starts_at', e.target.value)}
                className="w-full rounded-lg border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700 text-sm px-3 py-2 text-gray-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-teal-500" />
            </div>
            <div>
              <label className="block text-xs font-medium text-gray-600 dark:text-gray-400 mb-1">Ends At (optional)</label>
              <input type="datetime-local" value={form.ends_at} onChange={e => set('ends_at', e.target.value)}
                className="w-full rounded-lg border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700 text-sm px-3 py-2 text-gray-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-teal-500" />
            </div>
          </div>
          <label className="flex items-center gap-2 text-sm text-gray-700 dark:text-gray-300 cursor-pointer">
            <input type="checkbox" checked={form.is_dismissible} onChange={e => set('is_dismissible', e.target.checked)}
              className="rounded border-gray-300 text-teal-600 focus:ring-teal-500" />
            Dismissible by users
          </label>
        </div>

        <div className="flex justify-end gap-2 pt-2">
          <button onClick={onClose} className="px-4 py-2 text-sm text-gray-600 dark:text-gray-300 hover:text-gray-900 dark:hover:text-white">
            Cancel
          </button>
          <button
            onClick={() => onSave(form)}
            disabled={saving || !form.title || !form.message || !form.starts_at}
            className="px-4 py-2 text-sm font-medium bg-teal-600 text-white rounded-lg hover:bg-teal-700 disabled:opacity-50 flex items-center gap-2"
          >
            {saving && <Loader2 className="w-3.5 h-3.5 animate-spin" />}
            Save
          </button>
        </div>
      </div>
    </div>
  );
}

export default function AdminAnnouncementsPage() {
  const [rows, setRows]           = useState<Announcement[]>([]);
  const [loading, setLoading]     = useState(true);
  const [error, setError]         = useState('');
  const [modal, setModal]         = useState<{ open: boolean; item: Announcement | null }>({ open: false, item: null });
  const [saving, setSaving]       = useState(false);
  const [deleteId, setDeleteId]   = useState<string | null>(null);

  const load = useCallback(async () => {
    setLoading(true);
    setError('');
    try {
      const res = await apiFetch('/api/admin/announcements?limit=100');
      const data = await res.json();
      setRows(data.data?.items ?? []);
    } catch {
      setError('Failed to load announcements.');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => { load(); }, [load]);

  const openCreate = () => setModal({ open: true, item: null });
  const openEdit   = (item: Announcement) => setModal({ open: true, item });
  const closeModal = () => setModal({ open: false, item: null });

  const handleSave = async (form: FormState) => {
    setSaving(true);
    try {
      const targetIds = form.target_ids
        ? form.target_ids.split(',').map(s => s.trim()).filter(Boolean)
        : [];
      const body = {
        title:          form.title,
        message:        form.message,
        type:           form.type,
        target:         form.target,
        target_ids:     targetIds,
        starts_at:      form.starts_at ? new Date(form.starts_at).toISOString() : undefined,
        ends_at:        form.ends_at   ? new Date(form.ends_at).toISOString()   : undefined,
        is_dismissible: form.is_dismissible,
      };

      if (modal.item) {
        await apiFetch(`/api/admin/announcements/${modal.item.id}`, { method: 'PATCH', body: JSON.stringify(body) });
      } else {
        await apiFetch('/api/admin/announcements', { method: 'POST', body: JSON.stringify(body) });
      }

      closeModal();
      await load();
    } catch {
      // error surfaced by apiFetch
    } finally {
      setSaving(false);
    }
  };

  const handleDelete = async () => {
    if (!deleteId) return;
    try {
      await apiFetch(`/api/admin/announcements/${deleteId}`, { method: 'DELETE' });
      setDeleteId(null);
      await load();
    } catch {
      setDeleteId(null);
    }
  };

  const modalInitial: FormState = modal.item
    ? {
        title:          modal.item.title,
        message:        modal.item.message,
        type:           modal.item.type,
        target:         modal.item.target,
        target_ids:     (modal.item.target_ids ?? []).join(', '),
        starts_at:      modal.item.starts_at ? modal.item.starts_at.slice(0, 16) : '',
        ends_at:        modal.item.ends_at   ? modal.item.ends_at.slice(0, 16)   : '',
        is_dismissible: modal.item.is_dismissible,
      }
    : EMPTY_FORM;

  return (
    <AdminLayout title="Announcements">
      {modal.open && (
        <AnnouncementModal
          initial={modalInitial}
          onClose={closeModal}
          onSave={handleSave}
          saving={saving}
        />
      )}

      <ConfirmModal
        open={!!deleteId}
        title="Delete Announcement"
        message="This will permanently remove the announcement. Users will no longer see it."
        confirmLabel="Delete"
        onConfirm={handleDelete}
        onCancel={() => setDeleteId(null)}
      />

      <div className="space-y-4">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-2xl font-bold text-gray-900 dark:text-white">Announcements</h1>
            <p className="text-sm text-gray-500 dark:text-gray-400 mt-0.5">
              Platform messages shown to users in the app.
            </p>
          </div>
          <button
            onClick={openCreate}
            className="flex items-center gap-1.5 px-4 py-2 bg-teal-600 hover:bg-teal-700 text-white text-sm font-medium rounded-lg"
          >
            <Plus className="w-4 h-4" />
            New Announcement
          </button>
        </div>

        {error && (
          <div className="flex items-center gap-2 text-sm text-red-600 dark:text-red-400 bg-red-50 dark:bg-red-900/20 rounded-lg p-3">
            <AlertCircle className="w-4 h-4 flex-shrink-0" />
            {error}
          </div>
        )}

        {loading ? (
          <div className="flex justify-center py-12">
            <Loader2 className="w-6 h-6 animate-spin text-teal-500" />
          </div>
        ) : rows.length === 0 ? (
          <div className="text-center py-12 text-sm text-gray-500 dark:text-gray-400">
            No announcements yet. Create one to get started.
          </div>
        ) : (
          <div className="overflow-x-auto rounded-xl border border-gray-200 dark:border-gray-700">
            <table className="w-full text-sm">
              <thead className="bg-gray-50 dark:bg-gray-700/50 text-xs text-gray-500 dark:text-gray-400 uppercase tracking-wider">
                <tr>
                  <th className="px-4 py-3 text-left">Title</th>
                  <th className="px-4 py-3 text-left">Type</th>
                  <th className="px-4 py-3 text-left">Target</th>
                  <th className="px-4 py-3 text-left">Starts</th>
                  <th className="px-4 py-3 text-left">Ends</th>
                  <th className="px-4 py-3 text-left">Dismiss.</th>
                  <th className="px-4 py-3 text-right">Actions</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-100 dark:divide-gray-700">
                {rows.map((row) => (
                  <tr key={row.id} className="bg-white dark:bg-gray-800 hover:bg-gray-50 dark:hover:bg-gray-700/40">
                    <td className="px-4 py-3 font-medium text-gray-900 dark:text-white max-w-xs truncate">
                      {row.title}
                    </td>
                    <td className="px-4 py-3">
                      <span className={`px-2 py-0.5 rounded-full text-xs font-medium capitalize ${TYPE_BADGE[row.type] ?? 'bg-gray-100 text-gray-600'}`}>
                        {row.type}
                      </span>
                    </td>
                    <td className="px-4 py-3 text-gray-600 dark:text-gray-400 capitalize">{row.target}</td>
                    <td className="px-4 py-3 text-gray-600 dark:text-gray-400">{fmtDate(row.starts_at)}</td>
                    <td className="px-4 py-3 text-gray-600 dark:text-gray-400">{fmtDate(row.ends_at)}</td>
                    <td className="px-4 py-3 text-gray-600 dark:text-gray-400">{row.is_dismissible ? 'Yes' : 'No'}</td>
                    <td className="px-4 py-3">
                      <div className="flex items-center justify-end gap-2">
                        <button onClick={() => openEdit(row)} className="text-gray-400 hover:text-teal-500" title="Edit">
                          <Pencil className="w-4 h-4" />
                        </button>
                        <button onClick={() => setDeleteId(row.id)} className="text-gray-400 hover:text-red-500" title="Delete">
                          <Trash2 className="w-4 h-4" />
                        </button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>
    </AdminLayout>
  );
}

