  y = checkPageBreak(doc, y, 50);
  y += 4;

  // Navy box with closing statement
  doc.setFillColor(...BRAND.navy);
  doc.roundedRect(MARGIN_LEFT, y, CONTENT_WIDTH, 38, 3, 3, 'F');

  doc.setFont('helvetica', 'bold');
  doc.setFontSize(11);
  doc.setTextColor(...BRAND.teal);
  doc.text('Conclusion', MARGIN_LEFT + 8, y + 10);

  doc.setFont('helvetica', 'normal');
  doc.setFontSize(8.5);
  doc.setTextColor(200, 215, 230);
  const closing = 'ISAFlow is already a comprehensive, production-grade accounting platform that addresses the majority of challenges facing accounting professionals. By implementing the identified enhancements — guided by the practical wisdom of a 45-year veteran accountant — ISAFlow will deliver a Rolls-Royce-class accounting experience that sets a new standard in the South African market and beyond.';
  const closingLines = doc.splitTextToSize(closing, CONTENT_WIDTH - 16);
  let cy = y + 17;
  for (const cl of closingLines) {
    doc.text(cl, MARGIN_LEFT + 8, cy);
    cy += 4.5;
  }

  // ═══ ADD FOOTERS TO ALL PAGES ═════════════════════════════════════════════

  const totalPages = doc.getNumberOfPages();
  for (let i = 2; i <= totalPages; i++) {
    doc.setPage(i);
    addFooter(doc, i - 1, String(totalPages - 1));
  }

  // ═══ SAVE ═════════════════════════════════════════════════════════════════

  const outputPath = path.resolve(__dirname, '../tmp/ISAFlow-Gap-Analysis-Report.pdf');

  // Ensure tmp directory exists
  const tmpDir = path.dirname(outputPath);
  if (!fs.existsSync(tmpDir)) {
    fs.mkdirSync(tmpDir, { recursive: true });
  }

  const pdfBuffer = Buffer.from(doc.output('arraybuffer'));
  fs.writeFileSync(outputPath, pdfBuffer);

  console.log(`\n✅ Report generated: ${outputPath}`);
  console.log(`   Pages: ${totalPages - 1} (excluding cover)`);
  console.log(`   Size: ${(pdfBuffer.length / 1024).toFixed(0)} KB\n`);
}

// Run
generateReport();

