```typescript
// Import pattern:
import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import { getEntity, createEntity } from '@/modules/accounting/services/entityService';

// Handler function (wrapped):
async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  const { companyId } = req as CompanyApiRequest;

  if (req.method === 'GET') {
    try {
      const { filter_param } = req.query;
      const result = await getEntity(companyId, {
        filterParam: filter_param as string | undefined,
      });
      return apiResponse.success(res, result);
    } catch (err) {
      log.error('Failed to get entity', { error: err }, 'accounting-api');
      return apiResponse.badRequest(res, 'Failed to get entity');
    }
  }

  if (req.method === 'POST') {
    try {
      // ⚠️ CRITICAL: Never trust client request body for identity
      const userId = req.user.id; // From JWT, not body

      const { fieldA, fieldB } = req.body;
      if (!fieldA) {
        return apiResponse.badRequest(res, 'fieldA is required');
      }

      const result = await createEntity(companyId, { fieldA, fieldB }, userId);
      return apiResponse.success(res, result);
    } catch (err) {
      log.error('Failed to create entity', { error: err }, 'accounting-api');
      return apiResponse.badRequest(res, err instanceof Error ? err.message : 'Failed to create');
    }
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'POST']);
}

// Export with middleware stack:
export default withCompany(withErrorHandler(handler as any));

// CORS + error handling via withErrorHandler wrapper
// Error codes: BAD_REQUEST, UNAUTHORIZED, FORBIDDEN, NOT_FOUND, VALIDATION_ERROR, etc.
```

