```typescript
import { useEffect, useRef, useCallback } from 'react';
import type { ShortcutConfig } from '@/lib/keyboard-shortcuts';
import { parseShortcut, matchesShortcut } from '@/lib/keyboard-shortcuts';

export function useKeyboardShortcuts(shortcuts: ShortcutConfig[]) {
  // Register keydown listener
  // Track sequence state (for 'g d' style shortcuts — first key must be pressed within 1s of second)
  // Skip shortcuts when focus is in input/textarea/select UNLESS the shortcut uses Ctrl/Cmd/Alt modifier
  // Clean up on unmount
}
```

Key behaviors:
- Sequences: 'g d' means press 'g', then 'd' within 1 second
- Modifier shortcuts (ctrl+k, ctrl+n) work even when in text inputs
- Non-modifier shortcuts (?, j, k) are disabled when focus is in text input/textarea/contenteditable
- Multiple shortcuts can be registered; they don't conflict if keys are different

