  { key: 'g s', label: 'G then S', description: 'Go to Suppliers', category: 'navigation', action: () => router.push('/accounting?tab=suppliers') },
  { key: 'g b', label: 'G then B', description: 'Go to Banking', category: 'navigation', action: () => router.push('/accounting?tab=banking') },
  { key: 'g a', label: 'G then A', description: 'Go to Accounts', category: 'navigation', action: () => router.push('/accounting?tab=accounts') },
  { key: 'g r', label: 'G then R', description: 'Go to Reports', category: 'navigation', action: () => router.push('/accounting?tab=reports') },
  { key: 'g v', label: 'G then V', description: 'Go to VAT', category: 'navigation', action: () => router.push('/accounting?tab=vat') },
];

useKeyboardShortcuts(globalShortcuts);
```

Add state and render:
```tsx
const [shortcutHelpOpen, setShortcutHelpOpen] = useState(false);

// In render, add:
<ShortcutHelpOverlay 
  isOpen={shortcutHelpOpen} 
  onClose={() => setShortcutHelpOpen(false)}
  shortcuts={globalShortcuts}
/>
```

