/**
 * Audit Trail Page
 * Comprehensive field-level change history for all accounting entities.
 */

import { useState, useEffect, useCallback } from 'react';
import { useRouter } from 'next/router';
import Link from 'next/link';
import { AppLayout } from '@/components/layout/AppLayout';
import { useCompany } from '@/contexts/CompanyContext';
import { apiFetch } from '@/lib/apiFetch';
import { log } from '@/lib/logger';
import {
  Shield,
  Download,
  ChevronDown,
  ChevronRight,
  Loader2,
  AlertCircle,
  Search,
  Filter,
} from 'lucide-react';
import type { AuditLogItem, AuditAction } from '@/modules/accounting/services/auditTrailService';

const ACTION_LABELS: Record<AuditAction, string> = {
  create: 'Created',
  update: 'Updated',
  delete: 'Deleted',
  post: 'Posted',
  reverse: 'Reversed',
  approve: 'Approved',
  reject: 'Rejected',
  login: 'Login',
  export: 'Exported',
};

const ACTION_COLORS: Record<AuditAction, string> = {
  create: 'bg-green-500/10 text-green-400 border-green-500/20',
  update: 'bg-blue-500/10 text-blue-400 border-blue-500/20',
  delete: 'bg-red-500/10 text-red-400 border-red-500/20',
  post: 'bg-teal-500/10 text-teal-400 border-teal-500/20',
  reverse: 'bg-orange-500/10 text-orange-400 border-orange-500/20',
  approve: 'bg-emerald-500/10 text-emerald-400 border-emerald-500/20',
  reject: 'bg-rose-500/10 text-rose-400 border-rose-500/20',
  login: 'bg-gray-500/10 text-gray-400 border-gray-500/20',
  export: 'bg-purple-500/10 text-purple-400 border-purple-500/20',
};

const ENTITY_ROUTE_MAP: Record<string, string> = {
  invoice: '/accounting/customer-invoices',
  customer_invoice: '/accounting/customer-invoices',
  supplier_invoice: '/accounting/supplier-invoices',
  customer: '/accounting/customers',
  supplier: '/accounting/suppliers',
  journal_entry: '/accounting/journal-entries',
  payment: '/accounting/customer-payments',
  supplier_payment: '/accounting/supplier-payments',
  purchase_order: '/accounting/purchase-orders',
  bank_account: '/accounting/bank-accounts',
  asset: '/accounting/assets',
  budget: '/accounting/budgets',
};

function entityRoute(entityType: string, entityId: string): string | null {
  const base = ENTITY_ROUTE_MAP[entityType.toLowerCase()];
  if (!base) return null;
  return `${base}/${entityId}`;
}

function formatDateTime(iso: string): string {
  try {
    return new Date(iso).toLocaleString('en-ZA', {
      day: '2-digit', month: 'short', year: 'numeric',
      hour: '2-digit', minute: '2-digit', second: '2-digit',
    });
  } catch {
    return iso;
  }
}

interface Filters {
  entityType: string;
  action: string;
  dateFrom: string;
  dateTo: string;
  search: string;
}

const PAGE_SIZE = 50;

export default function AuditLogPage() {
  const router = useRouter();
  const { activeCompany } = useCompany();
  const [isMounted, setIsMounted] = useState(false);

  const [items, setItems] = useState<AuditLogItem[]>([]);
  const [total, setTotal] = useState(0);
  const [page, setPage] = useState(0);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [expandedRows, setExpandedRows] = useState<Set<string>>(new Set());

  const [filters, setFilters] = useState<Filters>({
    entityType: '',
    action: '',
    dateFrom: '',
    dateTo: '',
    search: '',
  });

  useEffect(() => { setIsMounted(true); }, []);

  const fetchAuditLog = useCallback(async (currentFilters: Filters, currentPage: number) => {
    if (!activeCompany) return;
    setLoading(true);
    setError(null);
    try {
      const params = new URLSearchParams();
      if (currentFilters.entityType) params.set('entity_type', currentFilters.entityType);
      if (currentFilters.action) params.set('action', currentFilters.action);
      if (currentFilters.dateFrom) params.set('date_from', currentFilters.dateFrom);
      if (currentFilters.dateTo) params.set('date_to', currentFilters.dateTo);
      if (currentFilters.search) params.set('search', currentFilters.search);
      params.set('limit', String(PAGE_SIZE));
      params.set('offset', String(currentPage * PAGE_SIZE));

      const data = await apiFetch<{ items: AuditLogItem[]; total: number }>(
        `/api/accounting/audit-log?${params.toString()}`,
      );
      setItems(data.items);
      setTotal(data.total);
    } catch (err) {
      log.error('Failed to fetch audit log', { error: err }, 'audit-log-page');
      setError('Failed to load audit trail');
    } finally {
      setLoading(false);
    }
  }, [activeCompany]);

  useEffect(() => {
    if (isMounted) {
      void fetchAuditLog(filters, page);
    }
  }, [isMounted, filters, page, fetchAuditLog]);

  const handleFilterChange = useCallback((key: keyof Filters, value: string) => {
    setFilters(prev => ({ ...prev, [key]: value }));
    setPage(0);
  }, []);

  const toggleRow = useCallback((id: string) => {
    setExpandedRows(prev => {
      const next = new Set(prev);
      if (next.has(id)) { next.delete(id); } else { next.add(id); }
      return next;
    });
  }, []);

  const handleExport = useCallback(() => {
    const params = new URLSearchParams();
    if (filters.entityType) params.set('entity_type', filters.entityType);
    if (filters.action) params.set('action', filters.action);
    if (filters.dateFrom) params.set('date_from', filters.dateFrom);
    if (filters.dateTo) params.set('date_to', filters.dateTo);
    if (filters.search) params.set('search', filters.search);
    const url = `/api/accounting/audit-log-export?${params.toString()}`;
    void router.push(url);
  }, [filters, router]);

  const totalPages = Math.ceil(total / PAGE_SIZE);

  if (!isMounted) {
    return (
      <AppLayout>
        <div className="min-h-screen bg-[var(--ff-bg-primary)] flex items-center justify-center">
          <Loader2 className="h-8 w-8 animate-spin text-teal-500" />
        </div>
      </AppLayout>
    );
  }

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">

        {/* Header */}
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)]">
          <div className="px-6 py-4 flex items-center justify-between">
            <div className="flex items-center gap-3">
              <div className="p-2 rounded-lg bg-teal-500/10">
                <Shield className="h-6 w-6 text-teal-500" />
              </div>
              <div>
                <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">Audit Trail</h1>
                <p className="text-sm text-[var(--ff-text-secondary)]">
                  Complete field-level change history — {total.toLocaleString()} records
                </p>
              </div>
            </div>
            <button
              onClick={handleExport}
              className="inline-flex items-center gap-2 px-4 py-2 bg-teal-600 text-white rounded-lg hover:bg-teal-700 transition-colors text-sm font-medium"
            >
              <Download className="h-4 w-4" />
              Export CSV
            </button>
          </div>
        </div>

        <div className="px-6 py-6 space-y-4">

          {/* Filter Bar */}
          <div className="bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)] rounded-lg p-4">
            <div className="flex items-center gap-2 mb-3">
              <Filter className="h-4 w-4 text-[var(--ff-text-secondary)]" />
              <span className="text-sm font-medium text-[var(--ff-text-secondary)]">Filters</span>
            </div>
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-5 gap-3">
              <div className="relative">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-[var(--ff-text-secondary)]" />
                <input
                  type="text"
                  placeholder="Search user, reference..."
                  value={filters.search}
                  onChange={e => handleFilterChange('search', e.target.value)}
                  className="w-full pl-9 pr-3 py-2 text-sm bg-[var(--ff-bg-primary)] border border-[var(--ff-border-light)] rounded-lg text-[var(--ff-text-primary)] placeholder-[var(--ff-text-secondary)] focus:outline-none focus:ring-2 focus:ring-teal-500/30"
                />
              </div>

              <select
                value={filters.entityType}
                onChange={e => handleFilterChange('entityType', e.target.value)}
                className="px-3 py-2 text-sm bg-[var(--ff-bg-primary)] border border-[var(--ff-border-light)] rounded-lg text-[var(--ff-text-primary)] focus:outline-none focus:ring-2 focus:ring-teal-500/30"
              >
                <option value="">All Entity Types</option>
                <option value="invoice">Invoice</option>
                <option value="customer_invoice">Customer Invoice</option>
                <option value="supplier_invoice">Supplier Invoice</option>
                <option value="customer">Customer</option>
                <option value="supplier">Supplier</option>
                <option value="journal_entry">Journal Entry</option>
                <option value="payment">Payment</option>
                <option value="purchase_order">Purchase Order</option>
                <option value="bank_account">Bank Account</option>
                <option value="asset">Asset</option>
                <option value="budget">Budget</option>
                <option value="user">User</option>
              </select>

              <select
                value={filters.action}
                onChange={e => handleFilterChange('action', e.target.value)}
                className="px-3 py-2 text-sm bg-[var(--ff-bg-primary)] border border-[var(--ff-border-light)] rounded-lg text-[var(--ff-text-primary)] focus:outline-none focus:ring-2 focus:ring-teal-500/30"
              >
                <option value="">All Actions</option>
                {(Object.keys(ACTION_LABELS) as AuditAction[]).map(a => (
                  <option key={a} value={a}>{ACTION_LABELS[a]}</option>
                ))}
              </select>

              <input
                type="date"
                value={filters.dateFrom}
                onChange={e => handleFilterChange('dateFrom', e.target.value)}
                className="px-3 py-2 text-sm bg-[var(--ff-bg-primary)] border border-[var(--ff-border-light)] rounded-lg text-[var(--ff-text-primary)] focus:outline-none focus:ring-2 focus:ring-teal-500/30"
                title="From date"
              />

              <input
                type="date"
                value={filters.dateTo}
                onChange={e => handleFilterChange('dateTo', e.target.value)}
                className="px-3 py-2 text-sm bg-[var(--ff-bg-primary)] border border-[var(--ff-border-light)] rounded-lg text-[var(--ff-text-primary)] focus:outline-none focus:ring-2 focus:ring-teal-500/30"
                title="To date"
              />
            </div>
          </div>

          {/* Error */}
          {error && (
            <div className="flex items-center gap-3 p-4 bg-red-500/10 border border-red-500/20 rounded-lg text-red-400">
              <AlertCircle className="h-5 w-5 shrink-0" />
              <span className="text-sm">{error}</span>
            </div>
          )}

          {/* Table */}
          <div className="bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)] rounded-lg overflow-hidden">
            {loading ? (
              <div className="flex items-center justify-center py-16">
                <Loader2 className="h-6 w-6 animate-spin text-teal-500" />
              </div>
            ) : items.length === 0 ? (
              <div className="text-center py-16">
                <Shield className="h-10 w-10 text-[var(--ff-text-secondary)] mx-auto mb-3 opacity-40" />
                <p className="text-[var(--ff-text-secondary)] text-sm">No audit records found</p>
              </div>
            ) : (
              <div className="overflow-x-auto">
                <table className="w-full text-sm">
                  <thead>
                    <tr className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-primary)]/50">
                      <th className="w-8 px-4 py-3" />
                      <th className="px-4 py-3 text-left text-xs font-semibold text-[var(--ff-text-secondary)] uppercase tracking-wider">
                        Date / Time
                      </th>
                      <th className="px-4 py-3 text-left text-xs font-semibold text-[var(--ff-text-secondary)] uppercase tracking-wider">
                        User
                      </th>
                      <th className="px-4 py-3 text-left text-xs font-semibold text-[var(--ff-text-secondary)] uppercase tracking-wider">
                        Action
                      </th>
                      <th className="px-4 py-3 text-left text-xs font-semibold text-[var(--ff-text-secondary)] uppercase tracking-wider">
                        Entity Type
                      </th>
                      <th className="px-4 py-3 text-left text-xs font-semibold text-[var(--ff-text-secondary)] uppercase tracking-wider">
                        Reference
                      </th>
                      <th className="px-4 py-3 text-left text-xs font-semibold text-[var(--ff-text-secondary)] uppercase tracking-wider">
                        Changes
                      </th>
                      <th className="px-4 py-3 text-left text-xs font-semibold text-[var(--ff-text-secondary)] uppercase tracking-wider">
                        IP Address
                      </th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-[var(--ff-border-light)]">
                    {items.map(item => {
                      const isExpanded = expandedRows.has(item.id);
                      const hasChanges = (item.changes?.fields?.length ?? 0) > 0;
                      const route = entityRoute(item.entityType, item.entityId);

                      return (
                        <>
                          <tr
                            key={item.id}
                            className="hover:bg-[var(--ff-bg-primary)]/40 transition-colors"
                          >
                            <td className="px-4 py-3">
                              {hasChanges && (
                                <button
                                  onClick={() => toggleRow(item.id)}
                                  className="text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] transition-colors"
                                  aria-label={isExpanded ? 'Collapse' : 'Expand'}
                                >
                                  {isExpanded
                                    ? <ChevronDown className="h-4 w-4" />
                                    : <ChevronRight className="h-4 w-4" />
                                  }
                                </button>
                              )}
                            </td>
                            <td className="px-4 py-3 text-[var(--ff-text-secondary)] whitespace-nowrap font-mono text-xs">
                              {formatDateTime(item.createdAt)}
                            </td>
                            <td className="px-4 py-3 text-[var(--ff-text-primary)]">
                              {item.userEmail ?? item.userId}
                            </td>
                            <td className="px-4 py-3">
                              <span className={`inline-flex items-center px-2 py-0.5 rounded border text-xs font-medium ${ACTION_COLORS[item.action] ?? 'bg-gray-500/10 text-gray-400 border-gray-500/20'}`}>
                                {ACTION_LABELS[item.action] ?? item.action}
                              </span>
                            </td>
                            <td className="px-4 py-3 text-[var(--ff-text-secondary)]">
                              {item.entityType.replace(/_/g, ' ')}
                            </td>
                            <td className="px-4 py-3">
                              {item.entityRef && route ? (
                                <Link
                                  href={route}
                                  className="text-teal-400 hover:text-teal-300 hover:underline font-mono text-xs"
                                >
                                  {item.entityRef}
                                </Link>
                              ) : (
                                <span className="text-[var(--ff-text-secondary)] font-mono text-xs">
                                  {item.entityRef ?? item.entityId.slice(0, 8) + '...'}
                                </span>
                              )}
                            </td>
                            <td className="px-4 py-3 text-[var(--ff-text-secondary)] text-xs">
                              {hasChanges
                                ? `${item.changes!.fields.length} field${item.changes!.fields.length !== 1 ? 's' : ''} changed`
                                : '—'}
                            </td>
                            <td className="px-4 py-3 text-[var(--ff-text-secondary)] font-mono text-xs">
                              {item.ipAddress ?? '—'}
                            </td>
                          </tr>

                          {isExpanded && hasChanges && (
                            <tr key={`${item.id}-detail`} className="bg-[var(--ff-bg-primary)]/20">
                              <td colSpan={8} className="px-8 py-4">
                                <div className="rounded-lg border border-[var(--ff-border-light)] overflow-hidden">
                                  <table className="w-full text-xs">
                                    <thead>
                                      <tr className="bg-[var(--ff-bg-primary)]/60">
                                        <th className="px-4 py-2 text-left text-[var(--ff-text-secondary)] font-semibold uppercase tracking-wider w-1/4">
                                          Field
                                        </th>
                                        <th className="px-4 py-2 text-left text-[var(--ff-text-secondary)] font-semibold uppercase tracking-wider w-1/3">
                                          Before
                                        </th>
                                        <th className="px-4 py-2 text-left text-[var(--ff-text-secondary)] font-semibold uppercase tracking-wider w-1/3">
                                          After
                                        </th>
                                      </tr>
                                    </thead>
                                    <tbody className="divide-y divide-[var(--ff-border-light)]">
                                      {item.changes!.fields.map((f, idx) => (
                                        <tr key={idx} className="hover:bg-[var(--ff-bg-secondary)]/40">
                                          <td className="px-4 py-2 font-medium text-[var(--ff-text-primary)]">
                                            {f.label}
                                          </td>
                                          <td className="px-4 py-2 text-red-400/80">
                                            {f.old ?? <span className="italic opacity-50">empty</span>}
                                          </td>
                                          <td className="px-4 py-2 text-green-400/80">
                                            {f.new ?? <span className="italic opacity-50">empty</span>}
                                          </td>
                                        </tr>
                                      ))}
                                    </tbody>
                                  </table>
                                  {item.changes!.metadata && Object.keys(item.changes!.metadata).length > 0 && (
                                    <div className="px-4 py-2 bg-[var(--ff-bg-primary)]/30 border-t border-[var(--ff-border-light)] flex flex-wrap gap-3">
                                      {Object.entries(item.changes!.metadata).map(([k, v]) => (
                                        <span key={k} className="text-[var(--ff-text-secondary)] text-xs">
                                          <span className="font-medium">{k}:</span> {v}
                                        </span>
                                      ))}
                                    </div>
                                  )}
                                </div>
                              </td>
                            </tr>
                          )}
                        </>
                      );
                    })}
                  </tbody>
                </table>
              </div>
            )}
          </div>

          {/* Pagination */}
          {totalPages > 1 && (
            <div className="flex items-center justify-between">
              <p className="text-sm text-[var(--ff-text-secondary)]">
                Showing {page * PAGE_SIZE + 1}–{Math.min((page + 1) * PAGE_SIZE, total)} of {total.toLocaleString()} records
              </p>
              <div className="flex items-center gap-2">
                <button
                  onClick={() => setPage(p => Math.max(0, p - 1))}
                  disabled={page === 0}
                  className="px-3 py-1.5 text-sm border border-[var(--ff-border-light)] rounded-lg text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] hover:border-teal-500/40 disabled:opacity-40 disabled:cursor-not-allowed transition-colors"
                >
                  Previous
                </button>
                <span className="text-sm text-[var(--ff-text-secondary)]">
                  Page {page + 1} of {totalPages}
                </span>
                <button
                  onClick={() => setPage(p => Math.min(totalPages - 1, p + 1))}
                  disabled={page >= totalPages - 1}
                  className="px-3 py-1.5 text-sm border border-[var(--ff-border-light)] rounded-lg text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] hover:border-teal-500/40 disabled:opacity-40 disabled:cursor-not-allowed transition-colors"
                >
                  Next
                </button>
              </div>
            </div>
          )}

        </div>
      </div>
    </AppLayout>
  );
}

