            AND i.item_type = ${String(type)}
            AND i.category_id = ${String(category_id)}::UUID
          ORDER BY i.code ASC LIMIT 500
        ` as Row[];
      }
    } else if (hasSearch && hasType) {
      const term = `%${String(q)}%`;
