        {/* Results area */}
        <div ref={listRef} className="overflow-y-auto flex-1">

          {/* Search results */}
          {showSearch && results.length > 0 && (
            <div className="py-2">
              <p className="px-4 py-1.5 text-xs font-semibold uppercase tracking-wider text-[var(--ff-text-tertiary)]">
                Results
              </p>
              {results.map((result, i) => (
                <ResultRow
                  key={`${result.type}-${result.id}`}
                  dataIdx={i}
                  icon={result.icon}
                  title={result.title}
                  subtitle={result.subtitle}
                  badge={TYPE_LABELS[result.type] ?? result.type}
                  isSelected={selectedIndex === i}
                  onClick={() => navigate(result.url, result)}
                />
              ))}
            </div>
          )}

          {/* No results */}
          {showSearch && !loading && results.length === 0 && (
            <div className="px-4 py-8 text-center text-sm text-[var(--ff-text-tertiary)]">
              No results for &ldquo;{query}&rdquo;
            </div>
          )}

          {/* Empty state: recent + quick actions */}
          {!showSearch && (
            <>
              {recentItems.length > 0 && (
                <div className="py-2">
                  <p className="px-4 py-1.5 text-xs font-semibold uppercase tracking-wider text-[var(--ff-text-tertiary)] flex items-center gap-1.5">
                    <Clock className="w-3 h-3" />
                    Recent
                  </p>
                  {recentItems.slice(0, 5).map((item, i) => (
                    <ResultRow
                      key={`recent-${item.url}`}
                      dataIdx={i}
                      icon={item.icon}
                      title={item.title}
                      subtitle={item.subtitle}
                      badge={TYPE_LABELS[item.type] ?? item.type}
                      isSelected={selectedIndex === i}
                      onClick={() => navigate(item.url, item)}
                    />
                  ))}
                </div>
              )}

              {actions.length > 0 && (
                <div className="py-2 border-t border-[var(--ff-border-primary)]">
                  <p className="px-4 py-1.5 text-xs font-semibold uppercase tracking-wider text-[var(--ff-text-tertiary)] flex items-center gap-1.5">
                    <Zap className="w-3 h-3" />
                    Quick Actions
                  </p>
                  {actions.map((action, i) => {
                    const idx = recentItems.slice(0, 5).length + i;
                    return (
                      <ActionRow
                        key={action.url}
                        dataIdx={idx}
                        icon={action.icon}
                        label={action.label}
                        shortcut={action.shortcut}
                        isSelected={selectedIndex === idx}
                        onClick={() => navigate(action.url)}
                      />
                    );
                  })}
                </div>
              )}

              {recentItems.length === 0 && actions.length === 0 && (
                <div className="px-4 py-8 text-center text-sm text-[var(--ff-text-tertiary)]">
                  Start typing to search...
                </div>
              )}
            </>
          )}
        </div>

        {/* Footer hint */}
        <div className="border-t border-[var(--ff-border-primary)] px-4 py-2 flex items-center gap-4 text-xs text-[var(--ff-text-tertiary)]">
          <span className="flex items-center gap-1">
            <kbd className="px-1.5 py-0.5 bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-primary)] rounded text-[10px]">↑↓</kbd>
            navigate
          </span>
          <span className="flex items-center gap-1">
            <kbd className="px-1.5 py-0.5 bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-primary)] rounded text-[10px]">↵</kbd>
            open
          </span>
          <span className="flex items-center gap-1">
            <kbd className="px-1.5 py-0.5 bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-primary)] rounded text-[10px]">Esc</kbd>
            close
          </span>
        </div>
      </div>
    </div>
  );
}

// ─── Sub-components ───────────────────────────────────────────────────────────

interface ResultRowProps {
  dataIdx: number;
  icon: string;
  title: string;
  subtitle: string;
  badge: string;
  isSelected: boolean;
  onClick: () => void;
}

function ResultRow({ dataIdx, icon, title, subtitle, badge, isSelected, onClick }: ResultRowProps) {
  return (
    <button
      data-idx={dataIdx}
      onClick={onClick}
      className={`
        w-full flex items-center gap-3 px-4 py-2.5 text-left transition-colors
        ${isSelected
          ? 'bg-teal-50 dark:bg-teal-900/20 text-teal-700 dark:text-teal-300'
          : 'hover:bg-[var(--ff-bg-hover)] text-[var(--ff-text-primary)]'
        }
      `}
    >
      <div className={`
        w-8 h-8 rounded-lg flex items-center justify-center flex-shrink-0
        ${isSelected ? 'bg-teal-100 dark:bg-teal-800/40 text-teal-600 dark:text-teal-400' : 'bg-[var(--ff-bg-secondary)] text-[var(--ff-text-secondary)]'}
      `}>
        <ResultIcon name={icon} />
      </div>
      <div className="flex-1 min-w-0">
        <p className="text-sm font-medium truncate">{title}</p>
        {subtitle && (
          <p className="text-xs text-[var(--ff-text-tertiary)] truncate">{subtitle}</p>
        )}
      </div>
      <span className="
        flex-shrink-0 px-2 py-0.5 text-[10px] font-medium rounded-full
        bg-[var(--ff-bg-tertiary)] text-[var(--ff-text-tertiary)]
      ">
        {badge}
      </span>
      {isSelected && <ArrowRight className="w-3.5 h-3.5 flex-shrink-0 text-teal-500" />}
    </button>
  );
}

interface ActionRowProps {
  dataIdx: number;
  icon: string;
  label: string;
  shortcut?: string;
  isSelected: boolean;
  onClick: () => void;
}

function ActionRow({ dataIdx, icon, label, shortcut, isSelected, onClick }: ActionRowProps) {
  return (
    <button
      data-idx={dataIdx}
      onClick={onClick}
      className={`
        w-full flex items-center gap-3 px-4 py-2.5 text-left transition-colors
        ${isSelected
          ? 'bg-teal-50 dark:bg-teal-900/20 text-teal-700 dark:text-teal-300'
          : 'hover:bg-[var(--ff-bg-hover)] text-[var(--ff-text-primary)]'
        }
      `}
    >
      <div className={`
        w-8 h-8 rounded-lg flex items-center justify-center flex-shrink-0
        ${isSelected ? 'bg-teal-100 dark:bg-teal-800/40 text-teal-600 dark:text-teal-400' : 'bg-[var(--ff-bg-secondary)] text-[var(--ff-text-secondary)]'}
      `}>
        <ResultIcon name={icon} />
      </div>
      <span className="flex-1 text-sm font-medium">{label}</span>
      {shortcut && (
        <kbd className="hidden sm:inline-flex px-1.5 py-0.5 text-[10px] text-[var(--ff-text-tertiary)] bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-primary)] rounded">
          {shortcut}
        </kbd>
      )}
      {isSelected && <ArrowRight className="w-3.5 h-3.5 flex-shrink-0 text-teal-500" />}
    </button>
  );
}

