/**
 * Company Settings API — Document Numbers & Messages
 * GET  ?type=document-numbers  — get document number config
 * GET  ?type=messages          — get statement/document messages
 * PUT  ?type=document-numbers  — update document number prefixes
 * PUT  ?type=messages          — update messages
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import {
  getDocumentNumbers, ensureDocumentNumbers, updateDocumentNumber,
  getCompanyMessages, upsertCompanyMessages,
} from '@/modules/accounting/services/companyService';
import type { CompanyMessage } from '@/modules/accounting/services/companyService';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  const { companyId } = req as CompanyApiRequest;
  const type = req.query.type as string;

  if (req.method === 'GET') {
    if (type === 'document-numbers') {
      const numbers = await ensureDocumentNumbers(companyId);
      return apiResponse.success(res, numbers);
    }
    if (type === 'messages') {
      const messages = await getCompanyMessages(companyId);
      return apiResponse.success(res, messages);
    }
    return apiResponse.badRequest(res, 'type query param required: document-numbers or messages');
  }

  if (req.method === 'PUT') {
    if (type === 'document-numbers') {
      const { updates } = req.body as { updates: { documentType: string; prefix: string; nextNumber?: number }[] };
      if (!updates || !Array.isArray(updates)) {
        return apiResponse.badRequest(res, 'updates array required');
      }
      for (const u of updates) {
        await updateDocumentNumber(companyId, u.documentType, u.prefix, u.nextNumber);
      }
      const numbers = await getDocumentNumbers(companyId);
      return apiResponse.success(res, numbers);
    }
    if (type === 'messages') {
      const { messages } = req.body as { messages: CompanyMessage[] };
      if (!messages || !Array.isArray(messages)) {
        return apiResponse.badRequest(res, 'messages array required');
      }
      await upsertCompanyMessages(companyId, messages);
      const updated = await getCompanyMessages(companyId);
      return apiResponse.success(res, updated);
    }
    return apiResponse.badRequest(res, 'type query param required: document-numbers or messages');
  }

  return apiResponse.methodNotAllowed(res, req.method!, ['GET', 'PUT']);
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withCompany(withErrorHandler(handler as any));

/**
 * Return SA tax periods for the current tax year.
 * VAT: Bi-monthly periods (Cat A) — Jan/Feb, Mar/Apr, May/Jun, Jul/Aug, Sep/Oct, Nov/Dec
 * PAYE: Monthly periods
 */
export function getTaxPeriods(year?: number): TaxPeriod[] {
  const y = year || new Date().getFullYear();
  const periods: TaxPeriod[] = [];

  // VAT bi-monthly periods (Category A — most common)
  const vatPeriods: Array<{ start: string; end: string; label: string }> = [
    { start: `${y}-01-01`, end: `${y}-02-28`, label: `Jan–Feb ${y}` },
    { start: `${y}-03-01`, end: `${y}-04-30`, label: `Mar–Apr ${y}` },
    { start: `${y}-05-01`, end: `${y}-06-30`, label: `May–Jun ${y}` },
    { start: `${y}-07-01`, end: `${y}-08-31`, label: `Jul–Aug ${y}` },
    { start: `${y}-09-01`, end: `${y}-10-31`, label: `Sep–Oct ${y}` },
    { start: `${y}-11-01`, end: `${y}-12-31`, label: `Nov–Dec ${y}` },
  ];

  // Handle leap year for Feb
  if (isLeapYear(y) && vatPeriods[0]) {
    vatPeriods[0].end = `${y}-02-29`;
  }

  for (const vp of vatPeriods) {
    const endDate = new Date(vp.end);
    // VAT201 due by 25th of month following end of period
    const dueMonth = endDate.getMonth() + 2; // +1 for next month, +1 because getMonth is 0-indexed
    const dueYear = dueMonth > 12 ? y + 1 : y;
    const dueM = dueMonth > 12 ? dueMonth - 12 : dueMonth;
    const dueDate = `${dueYear}-${pad(dueM)}-25`;

    periods.push({
      type: 'VAT',
      periodStart: vp.start,
      periodEnd: vp.end,
      dueDate,
      label: `VAT201 — ${vp.label}`,
    });
  }

  // PAYE monthly periods
  const monthNames = [
    'January', 'February', 'March', 'April', 'May', 'June',
    'July', 'August', 'September', 'October', 'November', 'December',
  ];

  for (let m = 1; m <= 12; m++) {
    const lastDay = new Date(y, m, 0).getDate();
    const periodStart = `${y}-${pad(m)}-01`;
    const periodEnd = `${y}-${pad(m)}-${pad(lastDay)}`;

    // EMP201 due by 7th of following month
    const dueMonth = m + 1;
    const dueYear = dueMonth > 12 ? y + 1 : y;
    const dueM = dueMonth > 12 ? 1 : dueMonth;
    const dueDate = `${dueYear}-${pad(dueM)}-07`;

    periods.push({
      type: 'PAYE',
      periodStart,
      periodEnd,
      dueDate,
      label: `EMP201 — ${monthNames[m - 1]} ${y}`,
    });
  }

  return periods;
}

// ---------------------------------------------------------------------------
// Compliance Calendar
// ---------------------------------------------------------------------------

/**
 * Build a compliance calendar with upcoming SARS deadlines.
 * Includes VAT201, EMP201, EMP501, IRP5/IT3(a), and Provisional Tax (IRP6).
 */
export function getComplianceCalendar(year?: number): ComplianceEvent[] {
  const y = year || new Date().getFullYear();
  const events: ComplianceEvent[] = [];

  // VAT201 deadlines — due 25th of month following bi-monthly period end
  const vatEndMonths = [2, 4, 6, 8, 10, 12];
  const vatLabels = ['Jan–Feb', 'Mar–Apr', 'May–Jun', 'Jul–Aug', 'Sep–Oct', 'Nov–Dec'];

  for (let i = 0; i < vatEndMonths.length; i++) {
    const endMonth = vatEndMonths[i] as number;
    const dueMonth = endMonth + 1;
    const dueYear = dueMonth > 12 ? y + 1 : y;
    const dueM = dueMonth > 12 ? 1 : dueMonth;

    events.push({
      eventType: 'VAT201_DUE',
      dueDate: `${dueYear}-${pad(dueM)}-25`,
      description: `VAT201 return for ${vatLabels[i]} ${y}`,
      status: getDeadlineStatus(`${dueYear}-${pad(dueM)}-25`),
    });
  }

