            {activeTab === 'documents' && renderDocumentsTab()}
            {activeTab === 'branding' && renderBrandingTab()}
          </div>
        </>
      ) : (
        <div className="text-center py-12 text-[var(--ff-text-secondary)]">No company configured</div>
      )}
    </div>
  </AppLayout>
);

