  const [expandedRows, setExpandedRows] = useState<Set<string>>(new Set());

  const [filters, setFilters] = useState<Filters>({
    entityType: '',
    action: '',
    dateFrom: '',
    dateTo: '',
    search: '',
  });

  useEffect(() => { setIsMounted(true); }, []);

  const fetchAuditLog = useCallback(async (currentFilters: Filters, currentPage: number) => {
    if (!activeCompany) return;
    setLoading(true);
    setError(null);
    try {
      const params = new URLSearchParams();
      if (currentFilters.entityType) params.set('entity_type', currentFilters.entityType);
      if (currentFilters.action) params.set('action', currentFilters.action);
      if (currentFilters.dateFrom) params.set('date_from', currentFilters.dateFrom);
      if (currentFilters.dateTo) params.set('date_to', currentFilters.dateTo);
      if (currentFilters.search) params.set('search', currentFilters.search);
      params.set('limit', String(PAGE_SIZE));
      params.set('offset', String(currentPage * PAGE_SIZE));

      const res = await apiFetch(
        `/api/accounting/audit-log?${params.toString()}`,
      );
      const json = await res.json() as { data: { items: AuditLogItem[]; total: number } };
      setItems(json.data.items);
      setTotal(json.data.total);
    } catch (err) {
      log.error('Failed to fetch audit log', { error: err }, 'audit-log-page');
      setError('Failed to load audit trail');
    } finally {
      setLoading(false);
    }
  }, [activeCompany]);

  useEffect(() => {
    if (isMounted) {
      void fetchAuditLog(filters, page);
    }
