                    {items.map(item => {
                      const isExpanded = expandedRows.has(item.id);
                      const hasChanges = (item.changes?.fields?.length ?? 0) > 0;
                      const route = entityRoute(item.entityType, item.entityId);

                      return (
                        <>
                          <tr
                            key={item.id}
                            className="hover:bg-[var(--ff-bg-primary)]/40 transition-colors"
                          >
                            <td className="px-4 py-3">
                              {hasChanges && (
                                <button
                                  onClick={() => toggleRow(item.id)}
                                  className="text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] transition-colors"
                                  aria-label={isExpanded ? 'Collapse' : 'Expand'}
                                >
                                  {isExpanded
                                    ? <ChevronDown className="h-4 w-4" />
                                    : <ChevronRight className="h-4 w-4" />
                                  }
                                </button>
                              )}
                            </td>
                            <td className="px-4 py-3 text-[var(--ff-text-secondary)] whitespace-nowrap font-mono text-xs">
                              {formatDateTime(item.createdAt)}
                            </td>
                            <td className="px-4 py-3 text-[var(--ff-text-primary)]">
                              {item.userEmail ?? item.userId}
                            </td>
                            <td className="px-4 py-3">
                              <span className={`inline-flex items-center px-2 py-0.5 rounded border text-xs font-medium ${ACTION_COLORS[item.action] ?? 'bg-gray-500/10 text-gray-400 border-gray-500/20'}`}>
                                {ACTION_LABELS[item.action] ?? item.action}
                              </span>
                            </td>
                            <td className="px-4 py-3 text-[var(--ff-text-secondary)]">
                              {item.entityType.replace(/_/g, ' ')}
                            </td>
                            <td className="px-4 py-3">
                              {item.entityRef && route ? (
                                <Link
                                  href={route}
                                  className="text-teal-400 hover:text-teal-300 hover:underline font-mono text-xs"
                                >
                                  {item.entityRef}
                                </Link>
                              ) : (
                                <span className="text-[var(--ff-text-secondary)] font-mono text-xs">
                                  {item.entityRef ?? item.entityId.slice(0, 8) + '...'}
                                </span>
                              )}
                            </td>
                            <td className="px-4 py-3 text-[var(--ff-text-secondary)] text-xs">
                              {hasChanges
                                ? `${item.changes!.fields.length} field${item.changes!.fields.length !== 1 ? 's' : ''} changed`
                                : '—'}
                            </td>
                            <td className="px-4 py-3 text-[var(--ff-text-secondary)] font-mono text-xs">
                              {item.ipAddress ?? '—'}
                            </td>
                          </tr>

                          {isExpanded && hasChanges && (
                            <tr key={`${item.id}-detail`} className="bg-[var(--ff-bg-primary)]/20">
                              <td colSpan={8} className="px-8 py-4">
                                <div className="rounded-lg border border-[var(--ff-border-light)] overflow-hidden">
                                  <table className="w-full text-xs">
                                    <thead>
                                      <tr className="bg-[var(--ff-bg-primary)]/60">
                                        <th className="px-4 py-2 text-left text-[var(--ff-text-secondary)] font-semibold uppercase tracking-wider w-1/4">
                                          Field
                                        </th>
                                        <th className="px-4 py-2 text-left text-[var(--ff-text-secondary)] font-semibold uppercase tracking-wider w-1/3">
                                          Before
                                        </th>
                                        <th className="px-4 py-2 text-left text-[var(--ff-text-secondary)] font-semibold uppercase tracking-wider w-1/3">
                                          After
                                        </th>
                                      </tr>
                                    </thead>
                                    <tbody className="divide-y divide-[var(--ff-border-light)]">
                                      {item.changes!.fields.map((f, idx) => (
                                        <tr key={idx} className="hover:bg-[var(--ff-bg-secondary)]/40">
                                          <td className="px-4 py-2 font-medium text-[var(--ff-text-primary)]">
                                            {f.label}
                                          </td>
                                          <td className="px-4 py-2 text-red-400/80">
                                            {f.old ?? <span className="italic opacity-50">empty</span>}
                                          </td>
                                          <td className="px-4 py-2 text-green-400/80">
                                            {f.new ?? <span className="italic opacity-50">empty</span>}
                                          </td>
                                        </tr>
                                      ))}
                                    </tbody>
                                  </table>
                                  {item.changes!.metadata && Object.keys(item.changes!.metadata).length > 0 && (
                                    <div className="px-4 py-2 bg-[var(--ff-bg-primary)]/30 border-t border-[var(--ff-border-light)] flex flex-wrap gap-3">
                                      {Object.entries(item.changes!.metadata).map(([k, v]) => (
                                        <span key={k} className="text-[var(--ff-text-secondary)] text-xs">
                                          <span className="font-medium">{k}:</span> {v}
                                        </span>
                                      ))}
                                    </div>
                                  )}
                                </div>
                              </td>
                            </tr>
                          )}
                        </>
                      );
                    })}
                  </tbody>
                </table>
              </div>
            )}
          </div>

          {/* Pagination */}
          {totalPages > 1 && (
            <div className="flex items-center justify-between">
              <p className="text-sm text-[var(--ff-text-secondary)]">
                Showing {page * PAGE_SIZE + 1}–{Math.min((page + 1) * PAGE_SIZE, total)} of {total.toLocaleString()} records
              </p>
              <div className="flex items-center gap-2">
                <button
                  onClick={() => setPage(p => Math.max(0, p - 1))}
                  disabled={page === 0}
                  className="px-3 py-1.5 text-sm border border-[var(--ff-border-light)] rounded-lg text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] hover:border-teal-500/40 disabled:opacity-40 disabled:cursor-not-allowed transition-colors"
                >
                  Previous
                </button>
                <span className="text-sm text-[var(--ff-text-secondary)]">
                  Page {page + 1} of {totalPages}
                </span>
                <button
                  onClick={() => setPage(p => Math.min(totalPages - 1, p + 1))}
                  disabled={page >= totalPages - 1}
                  className="px-3 py-1.5 text-sm border border-[var(--ff-border-light)] rounded-lg text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] hover:border-teal-500/40 disabled:opacity-40 disabled:cursor-not-allowed transition-colors"
                >
                  Next
                </button>
              </div>
            </div>
          )}

        </div>
      </div>
    </AppLayout>
  );
}

