      display_inactive_customers_reports = COALESCE(${v('displayInactiveCustomersReports') ?? null}, display_inactive_customers_reports),
      display_inactive_suppliers_reports = COALESCE(${v('displayInactiveSuppliersReports') ?? null}, display_inactive_suppliers_reports),
      use_inclusive_processing = COALESCE(${v('useInclusiveProcessing') ?? null}, use_inclusive_processing),
      use_account_default_line_type = COALESCE(${v('useAccountDefaultLineType') ?? null}, use_account_default_line_type),
      warn_item_qty_below_zero = COALESCE(${v('warnItemQtyBelowZero') ?? null}, warn_item_qty_below_zero),
      block_item_qty_below_zero = COALESCE(${v('blockItemQtyBelowZero') ?? null}, block_item_qty_below_zero),
      warn_item_cost_zero = COALESCE(${v('warnItemCostZero') ?? null}, warn_item_cost_zero),
      warn_item_selling_below_cost = COALESCE(${v('warnItemSellingBelowCost') ?? null}, warn_item_selling_below_cost),
      display_inactive_items_processing = COALESCE(${v('displayInactiveItemsProcessing') ?? null}, display_inactive_items_processing),
      display_inactive_items_reports = COALESCE(${v('displayInactiveItemsReports') ?? null}, display_inactive_items_reports),
      sales_orders_reserve_qty = COALESCE(${v('salesOrdersReserveQty') ?? null}, sales_orders_reserve_qty),
      display_inactive_bundles = COALESCE(${v('displayInactiveBundles') ?? null}, display_inactive_bundles),
      ageing_monthly = COALESCE(${v('ageingMonthly') ?? null}, ageing_monthly),
      ageing_based_on = COALESCE(${v('ageingBasedOn') ?? null}, ageing_based_on),
      updated_at = NOW()
    WHERE id = ${id}::UUID RETURNING *
  `) as Row[];
  if (!rows[0]) throw new Error(`Company ${id} not found`);
  return mapCompany(rows[0]);
}

// ── User-Company ─────────────────────────────────────────────────────────────

export async function getUserCompanies(userId: string): Promise<CompanyUser[]> {
  const rows = (await sql`
    SELECT cu.company_id, c.name AS company_name, cu.role, cu.is_default
    FROM company_users cu
    JOIN companies c ON c.id = cu.company_id
    WHERE cu.user_id = ${userId} AND c.is_active = true
    ORDER BY cu.is_default DESC, c.name ASC
  `) as Row[];
  return rows.map((r: Row) => ({
    companyId: r.company_id,
    companyName: r.company_name,
    role: r.role,
    isDefault: r.is_default,
  }));
}

export async function setDefaultCompany(userId: string, companyId: string): Promise<void> {
  await sql`UPDATE company_users SET is_default = false WHERE user_id = ${userId}`;
  await sql`UPDATE company_users SET is_default = true WHERE user_id = ${userId} AND company_id = ${companyId}::UUID`;
}

export async function addUserToCompany(companyId: string, userId: string, role = 'user'): Promise<void> {
  await sql`
    INSERT INTO company_users (company_id, user_id, role)
    VALUES (${companyId}::UUID, ${userId}, ${role})
    ON CONFLICT (company_id, user_id) DO UPDATE SET role = ${role}
  `;
}

export async function removeUserFromCompany(companyId: string, userId: string): Promise<void> {
  await sql`DELETE FROM company_users WHERE company_id = ${companyId}::UUID AND user_id = ${userId}`;
}

// ── Mapper ───────────────────────────────────────────────────────────────────

function mapCompany(r: Row): Company {
  return {
    id: r.id,
    name: r.name,
    tradingName: r.trading_name,
    registrationNumber: r.registration_number,
    vatNumber: r.vat_number,
    taxNumber: r.tax_number,
    addressLine1: r.address_line1,
    addressLine2: r.address_line2,
    city: r.city,
    province: r.province,
    postalCode: r.postal_code,
    country: r.country,
    phone: r.phone,
    email: r.email,
    website: r.website,
    logoUrl: r.logo_url,
    logoData: r.logo_data || null,
    bankName: r.bank_name,
    bankAccountNumber: r.bank_account_number,
    bankBranchCode: r.bank_branch_code,
    bankAccountType: r.bank_account_type,
    financialYearStart: r.financial_year_start,
    vatPeriod: r.vat_period,
    defaultCurrency: r.default_currency,
    isActive: r.is_active,
    createdAt: r.created_at,
    // Lockdown
    lockdownEnabled: r.lockdown_enabled ?? false,
    lockdownDate: r.lockdown_date ? new Date(r.lockdown_date).toISOString().split('T')[0]! : null,
    // VAT system
    vatSystemType: r.vat_system_type ?? 'invoice',
    // Entity & statutory
    entityType: r.entity_type ?? 'company',
    registeredName: r.registered_name,
    taxOffice: r.tax_office,
    contactName: r.contact_name,
    fax: r.fax,
    mobile: r.mobile,
    // Physical address
    physicalAddressLine1: r.physical_address_line1,
    physicalAddressLine2: r.physical_address_line2,
    physicalCity: r.physical_city,
    physicalProvince: r.physical_province,
    physicalPostalCode: r.physical_postal_code,
    // Tax practitioner
    taxPractitionerRegNumber: r.tax_practitioner_reg_number,
    taxPractitionerName: r.tax_practitioner_name,
    // SARS contact
    sarsContactFirstName: r.sars_contact_first_name,
    sarsContactLastName: r.sars_contact_last_name,
    sarsContactCapacity: r.sars_contact_capacity,
    sarsContactNumber: r.sars_contact_number,
    sarsContactTelephone: r.sars_contact_telephone,
    // Branding
    logoPosition: r.logo_position ?? 'top-left',
    logoOnEmails: r.logo_on_emails ?? true,
    logoOnPortal: r.logo_on_portal ?? true,
    // Regional
    roundingType: r.rounding_type ?? 'none',
    roundToNearest: parseFloat(r.round_to_nearest ?? '0'),
    qtyDecimalPlaces: r.qty_decimal_places ?? 2,
    valueDecimalPlaces: r.value_decimal_places ?? 2,
    hoursDecimalPlaces: r.hours_decimal_places ?? 2,
    costPriceDecimalPlaces: r.cost_price_decimal_places ?? 2,
    sellingPriceDecimalPlaces: r.selling_price_decimal_places ?? 2,
    currencySymbol: r.currency_symbol ?? 'R',
    dateFormat: r.date_format ?? 'dd/mm/yyyy',
    // Email toggles
    emailUseForCommunication: r.email_use_for_communication ?? true,
    emailAlwaysCc: r.email_always_cc ?? false,
    emailUseServiceFrom: r.email_use_service_from ?? false,
    // Customer & Supplier
    warnDuplicateCustomerRef: r.warn_duplicate_customer_ref ?? true,
    warnDuplicateSupplierInv: r.warn_duplicate_supplier_inv ?? true,
    displayInactiveCustomersProcessing: r.display_inactive_customers_processing ?? false,
    displayInactiveSuppliersProcessing: r.display_inactive_suppliers_processing ?? false,
    displayInactiveCustomersReports: r.display_inactive_customers_reports ?? false,
    displayInactiveSuppliersReports: r.display_inactive_suppliers_reports ?? false,
    useInclusiveProcessing: r.use_inclusive_processing ?? true,
    useAccountDefaultLineType: r.use_account_default_line_type ?? false,
    // Items
    warnItemQtyBelowZero: r.warn_item_qty_below_zero ?? true,
    blockItemQtyBelowZero: r.block_item_qty_below_zero ?? false,
    warnItemCostZero: r.warn_item_cost_zero ?? false,
    warnItemSellingBelowCost: r.warn_item_selling_below_cost ?? false,
    displayInactiveItemsProcessing: r.display_inactive_items_processing ?? false,
    displayInactiveItemsReports: r.display_inactive_items_reports ?? false,
    salesOrdersReserveQty: r.sales_orders_reserve_qty ?? false,
    displayInactiveBundles: r.display_inactive_bundles ?? false,
    // Ageing
    ageingMonthly: r.ageing_monthly ?? true,
    ageingBasedOn: r.ageing_based_on ?? 'invoice_date',
  };
}

// ── Document Numbers ──────────────────────────────────────────────────────────

export interface DocumentNumber {
  id: string;
  companyId: string;
  documentType: string;
  prefix: string;
  nextNumber: number;
  padding: number;
}

const DEFAULT_DOC_NUMBERS: { type: string; prefix: string }[] = [
  { type: 'quotation', prefix: 'QUO' },
  { type: 'sales_order', prefix: 'SO' },
  { type: 'customer_invoice', prefix: 'INV' },
  { type: 'credit_note', prefix: 'CRN' },
  { type: 'customer_receipt', prefix: 'RCP' },
  { type: 'customer_write_off', prefix: 'WRI' },
  { type: 'recurring_invoice', prefix: 'RINV' },
  { type: 'customer_adjustment', prefix: 'CADJ' },
  { type: 'purchase_order', prefix: 'PO' },
  { type: 'supplier_invoice', prefix: 'SIV' },
  { type: 'supplier_return', prefix: 'RTN' },
  { type: 'supplier_payment', prefix: 'PAY' },
  { type: 'supplier_adjustment', prefix: 'SADJ' },
  { type: 'delivery_note', prefix: 'DN' },
];

export async function getDocumentNumbers(companyId: string): Promise<DocumentNumber[]> {
  const rows = (await sql`
    SELECT * FROM company_document_numbers WHERE company_id = ${companyId}::UUID ORDER BY document_type
  `) as Row[];
  return rows.map((r: Row) => ({
    id: r.id, companyId: r.company_id, documentType: r.document_type,
    prefix: r.prefix, nextNumber: r.next_number, padding: r.padding,
  }));
}

export async function ensureDocumentNumbers(companyId: string): Promise<DocumentNumber[]> {
  for (const d of DEFAULT_DOC_NUMBERS) {
    await sql`
      INSERT INTO company_document_numbers (company_id, document_type, prefix, next_number, padding)
      VALUES (${companyId}::UUID, ${d.type}, ${d.prefix}, 1, 7)
      ON CONFLICT (company_id, document_type) DO NOTHING
    `;
  }
  return getDocumentNumbers(companyId);
}

export async function updateDocumentNumber(companyId: string, documentType: string, prefix: string, nextNumber?: number): Promise<void> {
  if (nextNumber !== undefined) {
    await sql`
      UPDATE company_document_numbers SET prefix = ${prefix}, next_number = ${nextNumber}
      WHERE company_id = ${companyId}::UUID AND document_type = ${documentType}
    `;
  } else {
    await sql`
      UPDATE company_document_numbers SET prefix = ${prefix}
      WHERE company_id = ${companyId}::UUID AND document_type = ${documentType}
    `;
  }
}

// ── Company Messages ──────────────────────────────────────────────────────────

export interface CompanyMessage {
  messageType: string;
  message: string;
}

export async function getCompanyMessages(companyId: string): Promise<CompanyMessage[]> {
  const rows = (await sql`
    SELECT message_type, message FROM company_messages WHERE company_id = ${companyId}::UUID ORDER BY message_type
  `) as Row[];
  return rows.map((r: Row) => ({ messageType: r.message_type, message: r.message ?? '' }));
}

export async function upsertCompanyMessage(companyId: string, messageType: string, message: string): Promise<void> {
  await sql`
    INSERT INTO company_messages (company_id, message_type, message)
    VALUES (${companyId}::UUID, ${messageType}, ${message})
    ON CONFLICT (company_id, message_type) DO UPDATE SET message = ${message}, updated_at = NOW()
  `;
}

export async function upsertCompanyMessages(companyId: string, messages: CompanyMessage[]): Promise<void> {
  for (const m of messages) {
    await upsertCompanyMessage(companyId, m.messageType, m.message);
  }
}

tool_input.content:
/**
 * Two-Factor Authentication section for My Account > Security tab.
 * Handles: status display, setup flow (QR + verify), backup codes, trusted devices.
 */

import { useState, useEffect } from 'react';
import { ShieldCheck, ShieldOff, Smartphone, Trash2, Loader2, RefreshCw, Copy, Check } from 'lucide-react';
import { apiFetch } from '@/lib/apiFetch';
import toast from 'react-hot-toast';
import { SECTION_CLS, LABEL_CLS, INPUT_CLS } from './AccountTabs';

// ── Types ─────────────────────────────────────────────────────────────────────

interface TwoFAStatus {
  enabled: boolean;
  method: string | null;
  verifiedAt: string | null;
}

interface TrustedDevice {
  id: string;
  deviceName: string | null;
  deviceFingerprint: string;
  trustedUntil: string;
  lastUsedAt: string;
}

// ── Helpers ───────────────────────────────────────────────────────────────────

type SetupStep = 'idle' | 'qr' | 'verify' | 'backup' | 'disable';

function formatDate(iso: string | null): string {
  if (!iso) return 'Unknown';
  return new Date(iso).toLocaleDateString('en-ZA', {
    day: '2-digit', month: 'short', year: 'numeric',
  });
}

// ── Backup Codes Display ──────────────────────────────────────────────────────

function BackupCodesDisplay({ codes, onDone }: { codes: string[]; onDone: () => void }) {
  const [copied, setCopied] = useState(false);

  const handleCopy = () => {
    void navigator.clipboard.writeText(codes.join('\n'));
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className="space-y-4">
      <div className="p-4 bg-amber-500/10 border border-amber-500/30 rounded-lg">
        <p className="text-sm font-medium text-amber-400">Save these backup codes now</p>
        <p className="text-xs text-amber-300 mt-1">
          Each code can only be used once. Store them somewhere safe — they will not be shown again.
        </p>
      </div>

      <div className="grid grid-cols-2 gap-2">
        {codes.map((code) => (
          <div key={code} className="font-mono text-sm text-center py-2 px-3 bg-[var(--ff-bg-primary)] border border-[var(--ff-border-primary)] rounded-lg text-[var(--ff-text-primary)] tracking-wider">
            {code}
          </div>
        ))}
      </div>

      <div className="flex gap-2">
        <button
          onClick={handleCopy}
          className="flex items-center gap-2 px-3 py-2 text-sm border border-[var(--ff-border-primary)] rounded-lg text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] transition-colors"
        >
          {copied ? <Check className="h-4 w-4 text-teal-500" /> : <Copy className="h-4 w-4" />}
          {copied ? 'Copied' : 'Copy All'}
        </button>
        <button
          onClick={onDone}
          className="flex-1 px-4 py-2 bg-teal-600 hover:bg-teal-700 text-white rounded-lg text-sm font-medium transition-colors"
        >
          I have saved my backup codes
        </button>
      </div>
    </div>
  );
}

// ── Main Component ────────────────────────────────────────────────────────────

export function TwoFactorSection() {
  const [status, setStatus] = useState<TwoFAStatus | null>(null);
  const [devices, setDevices] = useState<TrustedDevice[]>([]);
  const [step, setStep] = useState<SetupStep>('idle');
  const [qrData, setQrData] = useState<{ qrCodeDataUrl: string; uri: string } | null>(null);
  const [backupCodes, setBackupCodes] = useState<string[]>([]);
  const [verifyCode, setVerifyCode] = useState('');
  const [disableCode, setDisableCode] = useState('');
  const [loading, setLoading] = useState(false);
  const [statusLoading, setStatusLoading] = useState(true);

  useEffect(() => {
    void loadStatus();
    void loadDevices();
  }, []);

  async function loadStatus() {
    setStatusLoading(true);
    try {
      const res = await apiFetch('/api/auth/2fa-status');
      const json = await res.json();
      if (json.success) setStatus(json.data as TwoFAStatus);
    } catch {
      toast.error('Failed to load 2FA status');
    } finally {
      setStatusLoading(false);
    }
  }

  async function loadDevices() {
    try {
      const res = await apiFetch('/api/auth/2fa-trusted-devices');
      const json = await res.json();
      if (json.success) setDevices((json.data?.devices ?? []) as TrustedDevice[]);
    } catch {
      // Non-critical — silently ignore
    }
  }

  // ── Setup Flow ─────────────────────────────────────────────────────────────

  async function handleStartSetup() {
    setLoading(true);
    try {
      const res = await apiFetch('/api/auth/2fa-setup', { method: 'POST' });
      const json = await res.json();
      if (!res.ok) {
        toast.error(json.error?.message ?? 'Failed to start setup');
        return;
      }
      setQrData({ qrCodeDataUrl: json.data.qrCodeDataUrl as string, uri: json.data.uri as string });
      setVerifyCode('');
      setStep('qr');
    } catch {
      toast.error('Failed to start 2FA setup');
    } finally {
      setLoading(false);
    }
  }

  async function handleVerifySetup() {
    if (!verifyCode.trim()) return;
    setLoading(true);
    try {
      const res = await apiFetch('/api/auth/2fa-verify-setup', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ code: verifyCode.trim() }),
      });
      const json = await res.json();
      if (!res.ok) {
        toast.error(json.error?.message ?? 'Invalid code');
        return;
      }
      setBackupCodes((json.data?.backupCodes as string[]) ?? []);
      setStep('backup');
      await loadStatus();
    } catch {
      toast.error('Verification failed');
    } finally {
      setLoading(false);
    }
  }

  // ── Disable Flow ───────────────────────────────────────────────────────────

  async function handleDisable() {
    if (!disableCode.trim()) return;
    setLoading(true);
    try {
      const res = await apiFetch('/api/auth/2fa-disable', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ code: disableCode.trim() }),
      });
      const json = await res.json();
      if (!res.ok) {
        toast.error(json.error?.message ?? 'Invalid code');
        return;
      }
      toast.success('2FA disabled');
      setDisableCode('');
      setStep('idle');
      await loadStatus();
    } catch {
      toast.error('Failed to disable 2FA');
    } finally {
      setLoading(false);
    }
  }

  // ── Remove Device ──────────────────────────────────────────────────────────

  async function handleRemoveDevice(deviceId: string) {
    try {
      const res = await apiFetch(`/api/auth/2fa-trusted-devices?id=${deviceId}`, { method: 'DELETE' });
      if (!res.ok) {
        toast.error('Failed to remove device');
        return;
      }
      toast.success('Device removed');
      void loadDevices();
    } catch {
      toast.error('Failed to remove device');
    }
  }

  // ── Render ─────────────────────────────────────────────────────────────────

  if (statusLoading) {
    return (
      <section className={SECTION_CLS}>
        <div className="flex justify-center py-8">
          <Loader2 className="h-6 w-6 animate-spin text-teal-500" />
        </div>
      </section>
    );
  }

  const enabled = status?.enabled ?? false;

  return (
    <div className="space-y-6">

      {/* Status Card */}
      <section className={SECTION_CLS}>
        <div className="flex items-start justify-between gap-4">
          <div className="flex items-start gap-3">
            <div className={`p-2 rounded-lg ${enabled ? 'bg-teal-500/10' : 'bg-gray-500/10'}`}>
              {enabled
                ? <ShieldCheck className="h-6 w-6 text-teal-500" />
                : <ShieldOff className="h-6 w-6 text-gray-400" />
              }
            </div>
            <div>
              <h2 className="text-lg font-semibold text-[var(--ff-text-primary)]">
                Two-Factor Authentication
              </h2>
              <p className="text-sm text-[var(--ff-text-secondary)] mt-0.5">
                {enabled
                  ? `Enabled via authenticator app${status?.verifiedAt ? ` since ${formatDate(status.verifiedAt)}` : ''}`
                  : 'Add an extra layer of security to your account'
                }
              </p>
            </div>
          </div>

          <div className="flex gap-2 flex-shrink-0">
            {enabled && step === 'idle' && (
              <button
                onClick={() => setStep('disable')}
                className="px-3 py-1.5 text-sm text-red-400 border border-red-400/30 rounded-lg hover:bg-red-400/10 transition-colors"
              >
                Disable
              </button>
            )}
            {!enabled && step === 'idle' && (
              <button
                onClick={() => void handleStartSetup()}
                disabled={loading}
                className="flex items-center gap-2 px-3 py-1.5 text-sm bg-teal-600 hover:bg-teal-700 text-white rounded-lg transition-colors disabled:opacity-50"
              >
                {loading ? <Loader2 className="h-4 w-4 animate-spin" /> : null}
                Enable 2FA
              </button>
            )}
            {(step === 'qr' || step === 'verify') && (
              <button
                onClick={() => { setStep('idle'); setQrData(null); }}
                className="px-3 py-1.5 text-sm text-[var(--ff-text-secondary)] border border-[var(--ff-border-primary)] rounded-lg hover:text-[var(--ff-text-primary)] transition-colors"
              >
                Cancel
              </button>
            )}
          </div>
        </div>

        {/* QR Code Step */}
        {step === 'qr' && qrData && (
          <div className="mt-6 space-y-4">
            <div className="p-4 bg-[var(--ff-bg-primary)] border border-[var(--ff-border-primary)] rounded-lg">
              <p className="text-sm font-medium text-[var(--ff-text-primary)] mb-3">
                1. Scan this QR code with your authenticator app
              </p>
              <div className="flex justify-center">
                {/* eslint-disable-next-line @next/next/no-img-element */}
                <img src={qrData.qrCodeDataUrl} alt="2FA QR Code" className="rounded-lg" width={200} height={200} />
              </div>
              <p className="text-xs text-[var(--ff-text-secondary)] mt-3 text-center">
                Supported apps: Google Authenticator, Microsoft Authenticator, Authy
              </p>
            </div>

            <div>
              <p className="text-sm font-medium text-[var(--ff-text-primary)] mb-2">
                2. Enter the 6-digit code shown in your app
              </p>
              <div className="flex gap-2">
                <input
                  type="text"
                  inputMode="numeric"
                  maxLength={6}
                  value={verifyCode}
                  onChange={e => setVerifyCode(e.target.value.replace(/\D/g, ''))}
                  placeholder="000000"
                  className={INPUT_CLS + ' font-mono tracking-widest text-center'}
                />
                <button
                  onClick={() => void handleVerifySetup()}
                  disabled={loading || verifyCode.length < 6}
                  className="flex items-center gap-2 px-4 py-2 bg-teal-600 hover:bg-teal-700 text-white rounded-lg text-sm font-medium transition-colors disabled:opacity-50 whitespace-nowrap"
                >
                  {loading ? <Loader2 className="h-4 w-4 animate-spin" /> : null}
                  Verify & Enable
                </button>
              </div>
            </div>
          </div>
        )}

        {/* Backup Codes Step */}
        {step === 'backup' && (
          <div className="mt-6">
            <BackupCodesDisplay codes={backupCodes} onDone={() => { setStep('idle'); setBackupCodes([]); }} />
          </div>
        )}

        {/* Disable Step */}
        {step === 'disable' && (
          <div className="mt-6 space-y-4">
            <div className="p-4 bg-red-500/10 border border-red-500/30 rounded-lg">
              <p className="text-sm text-red-400">
                Enter your current authenticator code to disable 2FA.
                This will remove the extra security layer from your account.
              </p>
            </div>
            <div>
              <label className={LABEL_CLS}>Authentication Code</label>
              <div className="flex gap-2">
                <input
                  type="text"
                  inputMode="numeric"
                  maxLength={6}
                  value={disableCode}
                  onChange={e => setDisableCode(e.target.value.replace(/\D/g, ''))}
                  placeholder="000000"
                  className={INPUT_CLS + ' font-mono tracking-widest text-center'}
                />
                <button
                  onClick={() => void handleDisable()}
                  disabled={loading || disableCode.length < 6}
                  className="flex items-center gap-2 px-4 py-2 bg-red-600 hover:bg-red-700 text-white rounded-lg text-sm font-medium transition-colors disabled:opacity-50 whitespace-nowrap"
                >
                  {loading ? <Loader2 className="h-4 w-4 animate-spin" /> : null}
                  Disable 2FA
                </button>
              </div>
            </div>
            <button
              onClick={() => { setStep('idle'); setDisableCode(''); }}
              className="text-sm text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] transition-colors"
            >
              Cancel
            </button>
          </div>
        )}
      </section>

      {/* Trusted Devices */}
      {enabled && devices.length > 0 && (
        <section className={SECTION_CLS}>
          <div className="flex items-center justify-between mb-4">
            <h2 className="text-base font-semibold text-[var(--ff-text-primary)]">
              Trusted Devices
            </h2>
            <button
              onClick={() => void loadDevices()}
              className="text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] transition-colors"
              title="Refresh"
            >
              <RefreshCw className="h-4 w-4" />
            </button>
          </div>

          <div className="space-y-2">
            {devices.map(device => (
              <div
                key={device.id}
                className="flex items-center justify-between gap-4 p-3 bg-[var(--ff-bg-primary)] border border-[var(--ff-border-primary)] rounded-lg"
              >
                <div className="flex items-center gap-3 min-w-0">
                  <Smartphone className="h-4 w-4 text-[var(--ff-text-secondary)] flex-shrink-0" />
                  <div className="min-w-0">
                    <p className="text-sm font-medium text-[var(--ff-text-primary)] truncate">
                      {device.deviceName ?? 'Unknown Device'}
                    </p>
                    <p className="text-xs text-[var(--ff-text-secondary)]">
                      Trusted until {formatDate(device.trustedUntil)}
                      {' · '}Last used {formatDate(device.lastUsedAt)}
                    </p>
                  </div>
                </div>
                <button
                  onClick={() => void handleRemoveDevice(device.id)}
                  className="text-red-400 hover:text-red-300 transition-colors flex-shrink-0"
                  title="Remove device"
                >
                  <Trash2 className="h-4 w-4" />
                </button>
              </div>
            ))}
          </div>
        </section>
      )}

    </div>
  );
}

/**
 * Two-Factor Authentication section for My Account > Security tab.
 * Handles: status display, setup flow (QR + verify), backup codes, trusted devices.
 */

import { useState, useEffect } from 'react';
import { ShieldCheck, ShieldOff, Smartphone, Trash2, Loader2, RefreshCw, Copy, Check } from 'lucide-react';
import { apiFetch } from '@/lib/apiFetch';
import toast from 'react-hot-toast';
import { SECTION_CLS, LABEL_CLS, INPUT_CLS } from './AccountTabs';

// ── Types ─────────────────────────────────────────────────────────────────────

interface TwoFAStatus {
  enabled: boolean;
  method: string | null;
  verifiedAt: string | null;
}

interface TrustedDevice {
  id: string;
  deviceName: string | null;
  deviceFingerprint: string;
  trustedUntil: string;
  lastUsedAt: string;
}

// ── Helpers ───────────────────────────────────────────────────────────────────

type SetupStep = 'idle' | 'qr' | 'verify' | 'backup' | 'disable';

function formatDate(iso: string | null): string {
  if (!iso) return 'Unknown';
  return new Date(iso).toLocaleDateString('en-ZA', {
    day: '2-digit', month: 'short', year: 'numeric',
  });
}

// ── Backup Codes Display ──────────────────────────────────────────────────────

function BackupCodesDisplay({ codes, onDone }: { codes: string[]; onDone: () => void }) {
  const [copied, setCopied] = useState(false);

  const handleCopy = () => {
    void navigator.clipboard.writeText(codes.join('\n'));
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className="space-y-4">
      <div className="p-4 bg-amber-500/10 border border-amber-500/30 rounded-lg">
        <p className="text-sm font-medium text-amber-400">Save these backup codes now</p>
        <p className="text-xs text-amber-300 mt-1">
          Each code can only be used once. Store them somewhere safe — they will not be shown again.
        </p>
      </div>

      <div className="grid grid-cols-2 gap-2">
        {codes.map((code) => (
          <div key={code} className="font-mono text-sm text-center py-2 px-3 bg-[var(--ff-bg-primary)] border border-[var(--ff-border-primary)] rounded-lg text-[var(--ff-text-primary)] tracking-wider">
            {code}
          </div>
        ))}
      </div>

      <div className="flex gap-2">
        <button
          onClick={handleCopy}
          className="flex items-center gap-2 px-3 py-2 text-sm border border-[var(--ff-border-primary)] rounded-lg text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] transition-colors"
        >
          {copied ? <Check className="h-4 w-4 text-teal-500" /> : <Copy className="h-4 w-4" />}
          {copied ? 'Copied' : 'Copy All'}
        </button>
        <button
          onClick={onDone}
          className="flex-1 px-4 py-2 bg-teal-600 hover:bg-teal-700 text-white rounded-lg text-sm font-medium transition-colors"
        >
          I have saved my backup codes
        </button>
      </div>
    </div>
  );
}

// ── Main Component ────────────────────────────────────────────────────────────

export function TwoFactorSection() {
  const [status, setStatus] = useState<TwoFAStatus | null>(null);
  const [devices, setDevices] = useState<TrustedDevice[]>([]);
  const [step, setStep] = useState<SetupStep>('idle');
  const [qrData, setQrData] = useState<{ qrCodeDataUrl: string; uri: string } | null>(null);
  const [backupCodes, setBackupCodes] = useState<string[]>([]);
  const [verifyCode, setVerifyCode] = useState('');
  const [disableCode, setDisableCode] = useState('');
  const [loading, setLoading] = useState(false);
  const [statusLoading, setStatusLoading] = useState(true);

  useEffect(() => {
    void loadStatus();
    void loadDevices();
  }, []);

  async function loadStatus() {
    setStatusLoading(true);
    try {
      const res = await apiFetch('/api/auth/2fa-status');
      const json = await res.json();
      if (json.success) setStatus(json.data as TwoFAStatus);
    } catch {
      toast.error('Failed to load 2FA status');
    } finally {
      setStatusLoading(false);
    }
  }

  async function loadDevices() {
    try {
      const res = await apiFetch('/api/auth/2fa-trusted-devices');
      const json = await res.json();
      if (json.success) setDevices((json.data?.devices ?? []) as TrustedDevice[]);
    } catch {
      // Non-critical — silently ignore
    }
  }

  // ── Setup Flow ─────────────────────────────────────────────────────────────

  async function handleStartSetup() {
    setLoading(true);
    try {
      const res = await apiFetch('/api/auth/2fa-setup', { method: 'POST' });
      const json = await res.json();
      if (!res.ok) {
        toast.error(json.error?.message ?? 'Failed to start setup');
        return;
      }
      setQrData({ qrCodeDataUrl: json.data.qrCodeDataUrl as string, uri: json.data.uri as string });
      setVerifyCode('');
      setStep('qr');
    } catch {
      toast.error('Failed to start 2FA setup');
    } finally {
      setLoading(false);
    }
  }

  async function handleVerifySetup() {
    if (!verifyCode.trim()) return;
    setLoading(true);
    try {
      const res = await apiFetch('/api/auth/2fa-verify-setup', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ code: verifyCode.trim() }),
      });
      const json = await res.json();
      if (!res.ok) {
        toast.error(json.error?.message ?? 'Invalid code');
        return;
      }
      setBackupCodes((json.data?.backupCodes as string[]) ?? []);
      setStep('backup');
      await loadStatus();
    } catch {
      toast.error('Verification failed');
    } finally {
      setLoading(false);
    }
  }

  // ── Disable Flow ───────────────────────────────────────────────────────────

  async function handleDisable() {
    if (!disableCode.trim()) return;
    setLoading(true);
    try {
      const res = await apiFetch('/api/auth/2fa-disable', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ code: disableCode.trim() }),
      });
      const json = await res.json();
      if (!res.ok) {
        toast.error(json.error?.message ?? 'Invalid code');
        return;
      }
      toast.success('2FA disabled');
      setDisableCode('');
      setStep('idle');
      await loadStatus();
    } catch {
      toast.error('Failed to disable 2FA');
    } finally {
      setLoading(false);
    }
  }

  // ── Remove Device ──────────────────────────────────────────────────────────

  async function handleRemoveDevice(deviceId: string) {
    try {
      const res = await apiFetch(`/api/auth/2fa-trusted-devices?id=${deviceId}`, { method: 'DELETE' });
      if (!res.ok) {
        toast.error('Failed to remove device');
        return;
      }
      toast.success('Device removed');
      void loadDevices();
    } catch {
      toast.error('Failed to remove device');
    }
  }

  // ── Render ─────────────────────────────────────────────────────────────────

  if (statusLoading) {
    return (
      <section className={SECTION_CLS}>
        <div className="flex justify-center py-8">
          <Loader2 className="h-6 w-6 animate-spin text-teal-500" />
        </div>
      </section>
    );
  }

  const enabled = status?.enabled ?? false;

  return (
    <div className="space-y-6">

      {/* Status Card */}
      <section className={SECTION_CLS}>
        <div className="flex items-start justify-between gap-4">
          <div className="flex items-start gap-3">
            <div className={`p-2 rounded-lg ${enabled ? 'bg-teal-500/10' : 'bg-gray-500/10'}`}>
              {enabled
                ? <ShieldCheck className="h-6 w-6 text-teal-500" />
                : <ShieldOff className="h-6 w-6 text-gray-400" />
              }
            </div>
            <div>
              <h2 className="text-lg font-semibold text-[var(--ff-text-primary)]">
                Two-Factor Authentication
              </h2>
              <p className="text-sm text-[var(--ff-text-secondary)] mt-0.5">
                {enabled
                  ? `Enabled via authenticator app${status?.verifiedAt ? ` since ${formatDate(status.verifiedAt)}` : ''}`
                  : 'Add an extra layer of security to your account'
                }
              </p>
            </div>
          </div>

          <div className="flex gap-2 flex-shrink-0">
            {enabled && step === 'idle' && (
              <button
                onClick={() => setStep('disable')}
                className="px-3 py-1.5 text-sm text-red-400 border border-red-400/30 rounded-lg hover:bg-red-400/10 transition-colors"
              >
                Disable
              </button>
            )}
            {!enabled && step === 'idle' && (
              <button
                onClick={() => void handleStartSetup()}
                disabled={loading}
                className="flex items-center gap-2 px-3 py-1.5 text-sm bg-teal-600 hover:bg-teal-700 text-white rounded-lg transition-colors disabled:opacity-50"
              >
                {loading ? <Loader2 className="h-4 w-4 animate-spin" /> : null}
                Enable 2FA
              </button>
            )}
            {(step === 'qr' || step === 'verify') && (
              <button
                onClick={() => { setStep('idle'); setQrData(null); }}
                className="px-3 py-1.5 text-sm text-[var(--ff-text-secondary)] border border-[var(--ff-border-primary)] rounded-lg hover:text-[var(--ff-text-primary)] transition-colors"
              >
                Cancel
              </button>
            )}
          </div>
        </div>

        {/* QR Code Step */}
        {step === 'qr' && qrData && (
          <div className="mt-6 space-y-4">
            <div className="p-4 bg-[var(--ff-bg-primary)] border border-[var(--ff-border-primary)] rounded-lg">
              <p className="text-sm font-medium text-[var(--ff-text-primary)] mb-3">
                1. Scan this QR code with your authenticator app
              </p>
              <div className="flex justify-center">
                {/* eslint-disable-next-line @next/next/no-img-element */}
                <img src={qrData.qrCodeDataUrl} alt="2FA QR Code" className="rounded-lg" width={200} height={200} />
              </div>
              <p className="text-xs text-[var(--ff-text-secondary)] mt-3 text-center">
                Supported apps: Google Authenticator, Microsoft Authenticator, Authy
              </p>
            </div>

            <div>
              <p className="text-sm font-medium text-[var(--ff-text-primary)] mb-2">
                2. Enter the 6-digit code shown in your app
              </p>
              <div className="flex gap-2">
                <input
                  type="text"
                  inputMode="numeric"
                  maxLength={6}
                  value={verifyCode}
                  onChange={e => setVerifyCode(e.target.value.replace(/\D/g, ''))}
                  placeholder="000000"
                  className={INPUT_CLS + ' font-mono tracking-widest text-center'}
                />
                <button
                  onClick={() => void handleVerifySetup()}
                  disabled={loading || verifyCode.length < 6}
                  className="flex items-center gap-2 px-4 py-2 bg-teal-600 hover:bg-teal-700 text-white rounded-lg text-sm font-medium transition-colors disabled:opacity-50 whitespace-nowrap"
                >
                  {loading ? <Loader2 className="h-4 w-4 animate-spin" /> : null}
                  Verify & Enable
                </button>
              </div>
            </div>
          </div>
        )}

        {/* Backup Codes Step */}
        {step === 'backup' && (
          <div className="mt-6">
            <BackupCodesDisplay codes={backupCodes} onDone={() => { setStep('idle'); setBackupCodes([]); }} />
          </div>
        )}

        {/* Disable Step */}
        {step === 'disable' && (
          <div className="mt-6 space-y-4">
            <div className="p-4 bg-red-500/10 border border-red-500/30 rounded-lg">
              <p className="text-sm text-red-400">
                Enter your current authenticator code to disable 2FA.
                This will remove the extra security layer from your account.
              </p>
            </div>
            <div>
              <label className={LABEL_CLS}>Authentication Code</label>
              <div className="flex gap-2">
                <input
                  type="text"
                  inputMode="numeric"
                  maxLength={6}
                  value={disableCode}
                  onChange={e => setDisableCode(e.target.value.replace(/\D/g, ''))}
                  placeholder="000000"
                  className={INPUT_CLS + ' font-mono tracking-widest text-center'}
                />
                <button
                  onClick={() => void handleDisable()}
                  disabled={loading || disableCode.length < 6}
                  className="flex items-center gap-2 px-4 py-2 bg-red-600 hover:bg-red-700 text-white rounded-lg text-sm font-medium transition-colors disabled:opacity-50 whitespace-nowrap"
                >
                  {loading ? <Loader2 className="h-4 w-4 animate-spin" /> : null}
                  Disable 2FA
                </button>
              </div>
            </div>
            <button
              onClick={() => { setStep('idle'); setDisableCode(''); }}
              className="text-sm text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] transition-colors"
            >
              Cancel
            </button>
          </div>
        )}
      </section>

      {/* Trusted Devices */}
      {enabled && devices.length > 0 && (
        <section className={SECTION_CLS}>
          <div className="flex items-center justify-between mb-4">
            <h2 className="text-base font-semibold text-[var(--ff-text-primary)]">
              Trusted Devices
            </h2>
            <button
              onClick={() => void loadDevices()}
              className="text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] transition-colors"
              title="Refresh"
            >
              <RefreshCw className="h-4 w-4" />
            </button>
          </div>

          <div className="space-y-2">
            {devices.map(device => (
              <div
                key={device.id}
                className="flex items-center justify-between gap-4 p-3 bg-[var(--ff-bg-primary)] border border-[var(--ff-border-primary)] rounded-lg"
              >
                <div className="flex items-center gap-3 min-w-0">
                  <Smartphone className="h-4 w-4 text-[var(--ff-text-secondary)] flex-shrink-0" />
                  <div className="min-w-0">
                    <p className="text-sm font-medium text-[var(--ff-text-primary)] truncate">
                      {device.deviceName ?? 'Unknown Device'}
                    </p>
                    <p className="text-xs text-[var(--ff-text-secondary)]">
                      Trusted until {formatDate(device.trustedUntil)}
                      {' · '}Last used {formatDate(device.lastUsedAt)}
                    </p>
                  </div>
                </div>
                <button
                  onClick={() => void handleRemoveDevice(device.id)}
                  className="text-red-400 hover:text-red-300 transition-colors flex-shrink-0"
                  title="Remove device"
                >
                  <Trash2 className="h-4 w-4" />
                </button>
              </div>
            ))}
          </div>
        </section>
      )}

    </div>
  );
}

