      <div
        className="w-full max-w-xl mx-4 bg-[var(--ff-bg-primary)] border border-[var(--ff-border-primary)] rounded-xl shadow-2xl flex flex-col overflow-hidden max-h-[70vh]"
        onClick={e => e.stopPropagation()}
