} from 'react';
import { useRouter } from 'next/router';
import {
  Search,
  X,
  ArrowRight,
  BookOpen,
  Users,
  Truck,
  FileText,
  Scroll,
  Landmark,
  Package,
  FilePlus,
  PlusCircle,
  UserPlus,
  CheckSquare,
  BarChart2,
  Clock,
  Zap,
} from 'lucide-react';
import { apiFetch } from '@/lib/apiFetch';

// ─── Types ────────────────────────────────────────────────────────────────────

interface SearchResult {
  type: string;
  id: string;
  title: string;
  subtitle: string;
  url: string;
  icon: string;
