const TYPE_LABELS: Record<string, string> = {
  gl_account: 'Account',
  customer: 'Customer',
  supplier: 'Supplier',
  invoice: 'Invoice',
  journal_entry: 'Journal',
  bank_transaction: 'Bank',
  item: 'Item',
};

// ─── Icon map ─────────────────────────────────────────────────────────────────

function ResultIcon({ name, className }: { name: string; className?: string }) {
  const cls = className ?? 'w-4 h-4 flex-shrink-0';
  switch (name) {
    case 'book-open':     return <BookOpen className={cls} />;
    case 'users':         return <Users className={cls} />;
    case 'truck':         return <Truck className={cls} />;
    case 'file-text':     return <FileText className={cls} />;
    case 'scroll':        return <Scroll className={cls} />;
    case 'landmark':      return <Landmark className={cls} />;
    case 'package':       return <Package className={cls} />;
    case 'file-plus':     return <FilePlus className={cls} />;
    case 'plus-circle':   return <PlusCircle className={cls} />;
    case 'user-plus':     return <UserPlus className={cls} />;
    case 'check-square':  return <CheckSquare className={cls} />;
    case 'bar-chart-2':   return <BarChart2 className={cls} />;
    default:              return <ArrowRight className={cls} />;
  }
}

// ─── Recent items helpers ─────────────────────────────────────────────────────

function loadRecentItems(): SearchResult[] {
  if (typeof window === 'undefined') return [];
  try {
    const raw = localStorage.getItem(RECENT_KEY);
    return raw ? (JSON.parse(raw) as SearchResult[]) : [];
  } catch {
    return [];
  }
}

function saveRecentItem(item: SearchResult): void {
  if (typeof window === 'undefined') return;
  try {
    const existing = loadRecentItems().filter(r => r.url !== item.url);
    const updated = [item, ...existing].slice(0, MAX_RECENT);
    localStorage.setItem(RECENT_KEY, JSON.stringify(updated));
  } catch {
    // Storage errors are non-fatal
  }
}

// ─── Component ────────────────────────────────────────────────────────────────

export function CommandPalette({ isOpen, onClose }: CommandPaletteProps) {
  const router = useRouter();
  const inputRef = useRef<HTMLInputElement>(null);
  const listRef = useRef<HTMLDivElement>(null);

  const [query, setQuery] = useState('');
  const [results, setResults] = useState<SearchResult[]>([]);
  const [actions, setActions] = useState<QuickAction[]>([]);
  const [recentItems, setRecentItems] = useState<SearchResult[]>([]);
  const [loading, setLoading] = useState(false);
  const [selectedIndex, setSelectedIndex] = useState(0);
  const debounceRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  // Load recent items and reset state when opened
  useEffect(() => {
    if (isOpen) {
      setQuery('');
      setResults([]);
      setSelectedIndex(0);
      setRecentItems(loadRecentItems());
      // Fetch actions on open (no auth needed, they're static, but we do it via API for consistency)
      void fetchActions();
      setTimeout(() => inputRef.current?.focus(), 50);
    }
  }, [isOpen]);

  // Debounced search
  useEffect(() => {
    if (debounceRef.current) clearTimeout(debounceRef.current);

    if (query.length < 2) {
      setResults([]);
      setLoading(false);
      return;
    }

    setLoading(true);
    debounceRef.current = setTimeout(() => {
      void runSearch(query);
    }, 300);

    return () => {
      if (debounceRef.current) clearTimeout(debounceRef.current);
    };
  }, [query]);

  const fetchActions = useCallback(async () => {
    try {
      const res = await apiFetch('/api/accounting/global-search?q=');
      if (res.ok) {
        const data = await res.json() as { success: boolean; data: { actions: QuickAction[] } };
        if (data.success) setActions(data.data.actions);
      }
    } catch {
      // Non-fatal — actions are cosmetic
    }
  }, []);

  const runSearch = useCallback(async (q: string) => {
    try {
      const res = await apiFetch(`/api/accounting/global-search?q=${encodeURIComponent(q)}&limit=12`);
      if (res.ok) {
        const data = await res.json() as { success: boolean; data: { results: SearchResult[]; actions: QuickAction[] } };
        if (data.success) {
          setResults(data.data.results);
          setActions(data.data.actions);
        }
      }
    } catch {
      setResults([]);
    } finally {
      setLoading(false);
      setSelectedIndex(0);
    }
  }, []);

  // Flatten all navigable items for keyboard index
  const showSearch = query.length >= 2;
  const flatItems: Array<{ url: string; asResult?: SearchResult; asAction?: QuickAction }> =
    showSearch
      ? results.map(r => ({ url: r.url, asResult: r }))
      : [
          ...recentItems.map(r => ({ url: r.url, asResult: r })),
          ...actions.map(a => ({ url: a.url, asAction: a })),
        ];

  const navigate = useCallback((url: string, result?: SearchResult) => {
    if (result) saveRecentItem(result);
    onClose();
    void router.push(url);
  }, [onClose, router]);

  // Keyboard navigation
  useEffect(() => {
    if (!isOpen) return;

    const handler = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        onClose();
        return;
      }
      if (e.key === 'ArrowDown') {
        e.preventDefault();
        setSelectedIndex(i => Math.min(i + 1, flatItems.length - 1));
      }
      if (e.key === 'ArrowUp') {
        e.preventDefault();
        setSelectedIndex(i => Math.max(i - 1, 0));
      }
      if (e.key === 'Enter') {
        e.preventDefault();
        const item = flatItems[selectedIndex];
        if (item) navigate(item.url, item.asResult);
      }
    };

    window.addEventListener('keydown', handler);
    return () => window.removeEventListener('keydown', handler);
  }, [isOpen, flatItems, selectedIndex, navigate, onClose]);

  // Scroll selected item into view
  useEffect(() => {
    const el = listRef.current?.querySelector(`[data-idx="${selectedIndex}"]`);
    el?.scrollIntoView({ block: 'nearest' });
  }, [selectedIndex]);

  if (!isOpen) return null;

  return (
    <div
      className="fixed inset-0 bg-black/50 z-50 flex items-start justify-center pt-[10vh]"
      onClick={onClose}
    >
      <div
        className="
          w-full max-w-xl mx-4
          bg-[var(--ff-bg-primary)]
          border border-[var(--ff-border-primary)]
          rounded-xl shadow-2xl
          flex flex-col overflow-hidden
          max-h-[70vh]
        "
        onClick={e => e.stopPropagation()}
      >
        {/* Search input */}
        <div className="flex items-center gap-3 px-4 border-b border-[var(--ff-border-primary)]">
          <Search className="w-5 h-5 text-[var(--ff-text-tertiary)] flex-shrink-0" />
          <input
            ref={inputRef}
            type="text"
            value={query}
            onChange={e => setQuery(e.target.value)}
            placeholder="Search or jump to..."
            className="
              flex-1 py-4 text-base bg-transparent outline-none
              text-[var(--ff-text-primary)]
              placeholder:text-[var(--ff-text-tertiary)]
            "
          />
          {loading && (
            <div className="w-4 h-4 border-2 border-[var(--ff-border-primary)] border-t-teal-500 rounded-full animate-spin flex-shrink-0" />
          )}
          {query && !loading && (
            <button
              onClick={() => setQuery('')}
              className="p-1 rounded text-[var(--ff-text-tertiary)] hover:text-[var(--ff-text-primary)] transition-colors"
              aria-label="Clear search"
            >
              <X className="w-4 h-4" />
            </button>
          )}
          <kbd className="hidden sm:flex items-center gap-0.5 px-2 py-0.5 text-xs text-[var(--ff-text-tertiary)] bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-primary)] rounded">
            Esc
          </kbd>
        </div>

        {/* Results area */}
        <div ref={listRef} className="overflow-y-auto flex-1">

          {/* Search results */}
          {showSearch && results.length > 0 && (
            <div className="py-2">
              <p className="px-4 py-1.5 text-xs font-semibold uppercase tracking-wider text-[var(--ff-text-tertiary)]">
                Results
              </p>
              {results.map((result, i) => (
                <ResultRow
                  key={`${result.type}-${result.id}`}
                  dataIdx={i}
                  icon={result.icon}
                  title={result.title}
                  subtitle={result.subtitle}
                  badge={TYPE_LABELS[result.type] ?? result.type}
                  isSelected={selectedIndex === i}
                  onClick={() => navigate(result.url, result)}
                />
              ))}
            </div>
          )}

          {/* No results */}
          {showSearch && !loading && results.length === 0 && (
            <div className="px-4 py-8 text-center text-sm text-[var(--ff-text-tertiary)]">
              No results for &ldquo;{query}&rdquo;
            </div>
          )}

          {/* Empty state: recent + quick actions */}
          {!showSearch && (
            <>
              {recentItems.length > 0 && (
                <div className="py-2">
                  <p className="px-4 py-1.5 text-xs font-semibold uppercase tracking-wider text-[var(--ff-text-tertiary)] flex items-center gap-1.5">
                    <Clock className="w-3 h-3" />
                    Recent
                  </p>
                  {recentItems.slice(0, 5).map((item, i) => (
                    <ResultRow
                      key={`recent-${item.url}`}
                      dataIdx={i}
                      icon={item.icon}
                      title={item.title}
                      subtitle={item.subtitle}
                      badge={TYPE_LABELS[item.type] ?? item.type}
                      isSelected={selectedIndex === i}
                      onClick={() => navigate(item.url, item)}
                    />
                  ))}
                </div>
              )}

              {actions.length > 0 && (
                <div className="py-2 border-t border-[var(--ff-border-primary)]">
                  <p className="px-4 py-1.5 text-xs font-semibold uppercase tracking-wider text-[var(--ff-text-tertiary)] flex items-center gap-1.5">
                    <Zap className="w-3 h-3" />
                    Quick Actions
                  </p>
                  {actions.map((action, i) => {
                    const idx = recentItems.slice(0, 5).length + i;
                    return (
                      <ActionRow
                        key={action.url}
                        dataIdx={idx}
                        icon={action.icon}
                        label={action.label}
                        shortcut={action.shortcut}
                        isSelected={selectedIndex === idx}
                        onClick={() => navigate(action.url)}
                      />
                    );
                  })}
                </div>
              )}

              {recentItems.length === 0 && actions.length === 0 && (
                <div className="px-4 py-8 text-center text-sm text-[var(--ff-text-tertiary)]">
                  Start typing to search...
                </div>
              )}
            </>
          )}
        </div>

        {/* Footer hint */}
        <div className="border-t border-[var(--ff-border-primary)] px-4 py-2 flex items-center gap-4 text-xs text-[var(--ff-text-tertiary)]">
          <span className="flex items-center gap-1">
            <kbd className="px-1.5 py-0.5 bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-primary)] rounded text-[10px]">↑↓</kbd>
            navigate
          </span>
          <span className="flex items-center gap-1">
            <kbd className="px-1.5 py-0.5 bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-primary)] rounded text-[10px]">↵</kbd>
            open
          </span>
          <span className="flex items-center gap-1">
            <kbd className="px-1.5 py-0.5 bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-primary)] rounded text-[10px]">Esc</kbd>
            close
          </span>
        </div>
      </div>
    </div>
  );
}

// ─── Sub-components ───────────────────────────────────────────────────────────

interface ResultRowProps {
  dataIdx: number;
  icon: string;
  title: string;
  subtitle: string;
  badge: string;
  isSelected: boolean;
  onClick: () => void;
}

function ResultRow({ dataIdx, icon, title, subtitle, badge, isSelected, onClick }: ResultRowProps) {
  return (
    <button
      data-idx={dataIdx}
      onClick={onClick}
      className={`
        w-full flex items-center gap-3 px-4 py-2.5 text-left transition-colors
        ${isSelected
          ? 'bg-teal-50 dark:bg-teal-900/20 text-teal-700 dark:text-teal-300'
          : 'hover:bg-[var(--ff-bg-hover)] text-[var(--ff-text-primary)]'
        }
      `}
    >
      <div className={`
        w-8 h-8 rounded-lg flex items-center justify-center flex-shrink-0
        ${isSelected ? 'bg-teal-100 dark:bg-teal-800/40 text-teal-600 dark:text-teal-400' : 'bg-[var(--ff-bg-secondary)] text-[var(--ff-text-secondary)]'}
      `}>
        <ResultIcon name={icon} />
      </div>
      <div className="flex-1 min-w-0">
        <p className="text-sm font-medium truncate">{title}</p>
        {subtitle && (
          <p className="text-xs text-[var(--ff-text-tertiary)] truncate">{subtitle}</p>
        )}
      </div>
      <span className="
        flex-shrink-0 px-2 py-0.5 text-[10px] font-medium rounded-full
        bg-[var(--ff-bg-tertiary)] text-[var(--ff-text-tertiary)]
      ">
        {badge}
      </span>
      {isSelected && <ArrowRight className="w-3.5 h-3.5 flex-shrink-0 text-teal-500" />}
    </button>
  );
}

interface ActionRowProps {
  dataIdx: number;
  icon: string;
  label: string;
  shortcut?: string;
  isSelected: boolean;
  onClick: () => void;
}

function ActionRow({ dataIdx, icon, label, shortcut, isSelected, onClick }: ActionRowProps) {
  return (
    <button
      data-idx={dataIdx}
      onClick={onClick}
      className={`
        w-full flex items-center gap-3 px-4 py-2.5 text-left transition-colors
        ${isSelected
          ? 'bg-teal-50 dark:bg-teal-900/20 text-teal-700 dark:text-teal-300'
          : 'hover:bg-[var(--ff-bg-hover)] text-[var(--ff-text-primary)]'
        }
      `}
    >
      <div className={`
        w-8 h-8 rounded-lg flex items-center justify-center flex-shrink-0
        ${isSelected ? 'bg-teal-100 dark:bg-teal-800/40 text-teal-600 dark:text-teal-400' : 'bg-[var(--ff-bg-secondary)] text-[var(--ff-text-secondary)]'}
      `}>
        <ResultIcon name={icon} />
      </div>
      <span className="flex-1 text-sm font-medium">{label}</span>
      {shortcut && (
        <kbd className="hidden sm:inline-flex px-1.5 py-0.5 text-[10px] text-[var(--ff-text-tertiary)] bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-primary)] rounded">
          {shortcut}
        </kbd>
      )}
      {isSelected && <ArrowRight className="w-3.5 h-3.5 flex-shrink-0 text-teal-500" />}
    </button>
  );
}

