                  <td className="px-4 py-2 text-right text-[var(--ff-text-primary)]">{fmt(inv.totalExclVat)}</td>
                  <td className="px-4 py-2 text-right text-teal-400 font-medium">{fmt(inv.vatAmount)}</td>
