## 2. Cache Library — `src/lib/cache.ts`

Create an LRU cache wrapper:

```typescript
import { LRUCache } from 'lru-cache';
import { log } from '@/lib/logger';

interface CacheOptions {
  maxSize?: number;      // Max entries (default 10000)
  defaultTTL?: number;   // Default TTL in ms (default 5 min)
}

class AppCache {
  private cache: LRUCache<string, unknown>;
  private hitCount = 0;
  private missCount = 0;

  constructor(options?: CacheOptions) {
    this.cache = new LRUCache({
      max: options?.maxSize ?? 10000,
      ttl: options?.defaultTTL ?? 5 * 60 * 1000, // 5 min default
      allowStale: false,
    });
  }

  get<T>(key: string): T | undefined {
    const val = this.cache.get(key) as T | undefined;
    if (val !== undefined) {
      this.hitCount++;
    } else {
      this.missCount++;
    }
    return val;
  }

  set<T>(key: string, value: T, ttl?: number): void {
    this.cache.set(key, value, { ttl });
  }

  // Invalidate a specific key
  invalidate(key: string): void {
    this.cache.delete(key);
  }

  // Invalidate all keys matching a prefix
  invalidatePrefix(prefix: string): void {
    for (const key of this.cache.keys()) {
      if (key.startsWith(prefix)) {
        this.cache.delete(key);
      }
    }
  }

  // Clear all entries for a company
  invalidateCompany(companyId: string): void {
    this.invalidatePrefix(`${companyId}:`);
  }

  // Get cache statistics
  stats(): { size: number; hitCount: number; missCount: number; hitRate: string } {
    const total = this.hitCount + this.missCount;
    return {
      size: this.cache.size,
      hitCount: this.hitCount,
      missCount: this.missCount,
      hitRate: total > 0 ? `${Math.round((this.hitCount / total) * 100)}%` : '0%',
    };
  }

  // Clear everything
  clear(): void {
    this.cache.clear();
    this.hitCount = 0;
    this.missCount = 0;
  }
}

// Singleton instance
export const cache = new AppCache();

// Helper: cache-through pattern
export async function cacheThrough<T>(
  key: string,
  fetcher: () => Promise<T>,
  ttl?: number,
): Promise<T> {
  const cached = cache.get<T>(key);
  if (cached !== undefined) return cached;

  const result = await fetcher();
  cache.set(key, result, ttl);
  return result;
}
```

