-- Consolidated trial balance materialized view for group reporting
CREATE MATERIALIZED VIEW IF NOT EXISTS mv_consolidated_trial_balance AS
SELECT
  gc.group_id,
  gc.company_id,
  ga.account_code,
  ga.account_name,
  ga.account_type,
  COALESCE(SUM(jl.debit), 0) AS total_debit,
  COALESCE(SUM(jl.credit), 0) AS total_credit,
  COALESCE(SUM(jl.debit), 0) - COALESCE(SUM(jl.credit), 0) AS net_balance
FROM group_companies gc
JOIN gl_accounts ga ON ga.company_id = gc.company_id
LEFT JOIN gl_journal_lines jl ON jl.gl_account_id = ga.id
LEFT JOIN gl_journal_entries je ON je.id = jl.journal_entry_id AND je.status = 'posted'
GROUP BY gc.group_id, gc.company_id, ga.account_code, ga.account_name, ga.account_type;

-- Note: CONCURRENTLY requires a unique index
CREATE UNIQUE INDEX IF NOT EXISTS idx_mv_ctb_pk 
  ON mv_consolidated_trial_balance(group_id, company_id, account_code);
```

