/**
 * New Journal Entry Page
 * Create a manual journal entry with balanced debit/credit lines
 */

import { useState, useEffect, useCallback } from 'react';
import { useRouter } from 'next/router';
import Link from 'next/link';
import { AppLayout } from '@/components/layout/AppLayout';
import { log } from '@/lib/logger';
import {
  ArrowLeft,
  Plus,
  Trash2,
  Loader2,
  AlertCircle,
  CheckCircle2,
  Save,
} from 'lucide-react';
import type { GLAccount } from '@/modules/accounting/types/gl.types';
import { apiFetch } from '@/lib/apiFetch';

interface LineInput {
  key: string;
  accountId: string;
  description: string;
  debitAmount: string;
  creditAmount: string;
}

const emptyLine = (): LineInput => ({
  key: crypto.randomUUID(),
  accountId: '',
  description: '',
  debitAmount: '',
  creditAmount: '',
});

export default function NewJournalEntryPage() {
  const router = useRouter();
  const [accounts, setAccounts] = useState<GLAccount[]>([]);
  const [entryDate, setEntryDate] = useState(new Date().toISOString().split('T')[0]!);
  const [description, setDescription] = useState('');
  const [lines, setLines] = useState<LineInput[]>([emptyLine(), emptyLine()]);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState(false);

  useEffect(() => {
    loadAccounts();
  }, []);

  const loadAccounts = async () => {
    try {
      const res = await apiFetch('/api/accounting/chart-of-accounts');
      const data = await res.json();
      const list = data.data || data || [];
      // Only show leaf accounts (no children / subtype level) for journal lines
      setAccounts(list.filter((a: GLAccount) => a.isActive));
    } catch (err) {
      log.error('Failed to load accounts', { error: err }, 'accounting-ui');
    }
  };

  const addLine = useCallback(() => {
    setLines(prev => [...prev, emptyLine()]);
  }, []);

  const removeLine = useCallback((key: string) => {
    setLines(prev => prev.length > 2 ? prev.filter(l => l.key !== key) : prev);
  }, []);

  const updateLine = useCallback((key: string, field: keyof LineInput, value: string) => {
    setLines(prev => prev.map(l => {
      if (l.key !== key) return l;
      const updated = { ...l, [field]: value };
      // If user enters debit, clear credit and vice versa
      if (field === 'debitAmount' && value) updated.creditAmount = '';
      if (field === 'creditAmount' && value) updated.debitAmount = '';
      return updated;

  }

  get<T>(key: string): T | undefined {
    const val = this.cache.get(key) as T | undefined;
    if (val !== undefined) {
      this.hitCount++;
    } else {
      this.missCount++;
    }
    return val;
  }

  set<T>(key: string, value: T, ttl?: number): void {
    this.cache.set(key, value, ttl !== undefined ? { ttl } : undefined);
  }

  invalidate(key: string): void {
    this.cache.delete(key);
    log.info('Cache invalidated', { key }, 'cache');
  }

  invalidatePrefix(prefix: string): void {
    let count = 0;
    for (const key of this.cache.keys()) {
      if (key.startsWith(prefix)) {
        this.cache.delete(key);
        count++;
      }
    }
    log.info('Cache prefix invalidated', { prefix, count }, 'cache');
  }

  invalidateCompany(companyId: string): void {
    this.invalidatePrefix(`${companyId}:`);
  }

  stats(): { size: number; hitCount: number; missCount: number; hitRate: string } {
    const total = this.hitCount + this.missCount;
    return {
      size: this.cache.size,
      hitCount: this.hitCount,
      missCount: this.missCount,
      hitRate: total > 0 ? `${Math.round((this.hitCount / total) * 100)}%` : '0%',
    };
  }

  clear(): void {
    this.cache.clear();
    this.hitCount = 0;
    this.missCount = 0;
    log.info('Cache cleared', {}, 'cache');
  }
}

// Singleton — lives in the Next.js server process
export const cache = new AppCache();

/**
 * Cache-through helper: returns cached value if present,
 * otherwise calls fetcher, stores the result, and returns it.
 */
export async function cacheThrough<T>(
  key: string,
  fetcher: () => Promise<T>,
  ttl?: number,
): Promise<T> {
  const cached = cache.get<T>(key);
  if (cached !== undefined) return cached;

  const result = await fetcher();
  cache.set(key, result, ttl);
  return result;
}

