/**
 * User Access Control — mirrors Sage Accounting "Control User Access".
 */

import { useState, useEffect, useCallback } from 'react';
import { AppLayout } from '@/components/layout/AppLayout';
import { Users, UserPlus, Trash2, Shield, Mail, Clock, Copy, Check } from 'lucide-react';
import { apiFetch } from '@/lib/apiFetch';
import { useAuth } from '@/contexts/AuthContext';

interface CompanyUser { userId: string; name: string; email: string; role: string; joinedAt: string; }
interface PendingInvitation {
  id: string; email: string; role: string; token: string; expiresAt: string; createdAt: string;
  emailSentAt: string | null; emailError: string | null;
}

const ROLES = ['owner', 'admin', 'manager', 'viewer'] as const;
const ADMIN_ROLES = ['owner', 'admin'];
const ROLE_BADGE: Record<string, string> = {
  owner: 'bg-teal-900 text-teal-300', admin: 'bg-blue-900 text-blue-300',
  manager: 'bg-purple-900 text-purple-300', viewer: 'bg-gray-700 text-gray-300',
};

export default function UserAccessPage() {
  const { user } = useAuth();
  const [users, setUsers] = useState<CompanyUser[]>([]);
  const [invitations, setInvitations] = useState<PendingInvitation[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [inviteEmail, setInviteEmail] = useState('');
  const [inviteRole, setInviteRole] = useState<string>('viewer');
  const [inviting, setInviting] = useState(false);
  const [feedback, setFeedback] = useState<string | null>(null);
  const [confirmRemove, setConfirmRemove] = useState<string | null>(null);
  const [copiedId, setCopiedId] = useState<string | null>(null);

  const myEntry = users.find((u) => u.userId === user?.id);
  const myRole = myEntry?.role ?? '';
  const isAdmin = ADMIN_ROLES.includes(myRole);
  const ownerCount = users.filter((u) => u.role === 'owner').length;

  const loadData = useCallback(async () => {
    setLoading(true); setError(null);
    try {
      const ur = await (await apiFetch('/api/accounting/company-users')).json();
      setUsers(ur.data ?? []);
      // Always try fetching invitations — the API returns 403 for non-admins which is fine
      try {
        const ir = await (await apiFetch('/api/accounting/company-invitations')).json();
        setInvitations(ir.data ?? []);
      } catch { /* non-admin — no access to invitations */ }
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Failed to load data.');
    } finally { setLoading(false); }
  }, []);

  useEffect(() => { loadData(); }, [loadData]);

  const showFeedback = (msg: string) => {
    setFeedback(msg);
    setTimeout(() => setFeedback(null), 4000);
  };

  async function handleRoleChange(userId: string, role: string) {
    try {
      const j = await (await apiFetch('/api/accounting/company-users', { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ userId, role }) })).json();
      setUsers(j.data ?? []); showFeedback('Role updated.');
    } catch (e) { showFeedback(e instanceof Error ? e.message : 'Update failed.'); }
  }

  async function handleRemove(userId: string) {
    try {
      const j = await (await apiFetch('/api/accounting/company-users', { method: 'DELETE', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ userId }) })).json();
      setUsers(j.data ?? []); showFeedback('User removed.');
    } catch (e) { showFeedback(e instanceof Error ? e.message : 'Remove failed.'); }
    finally { setConfirmRemove(null); }
  }

  async function handleInvite(e: React.FormEvent) {
    e.preventDefault();
    if (!inviteEmail.trim()) return;
    setInviting(true);
    try {
      const j = await (await apiFetch('/api/accounting/company-invitations', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email: inviteEmail.trim(), role: inviteRole }),
      })).json();
      if (j.data?.autoAdded) {
        showFeedback(`${inviteEmail} was found and added directly to this company.`);
        loadData();
      } else {
        showFeedback(`Invitation sent to ${inviteEmail}.`);
        const ir = await (await apiFetch('/api/accounting/company-invitations')).json();
        setInvitations(ir.data ?? []);
      }
      setInviteEmail('');
    } catch (e) { showFeedback(e instanceof Error ? e.message : 'Invite failed.'); }
    finally { setInviting(false); }
  }

  async function handleCancelInvite(invitationId: string) {
    try {
      await apiFetch('/api/accounting/company-invitations', { method: 'DELETE', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ invitationId }) });
      setInvitations((prev) => prev.filter((i) => i.id !== invitationId));
      showFeedback('Invitation cancelled.');
    } catch (e) { showFeedback(e instanceof Error ? e.message : 'Cancel failed.'); }
  }

  function handleCopyLink(inv: PendingInvitation) {
    const link = `${window.location.origin}/invite/${inv.token}`;
    void navigator.clipboard.writeText(link).then(() => {
      setCopiedId(inv.id);
      setTimeout(() => setCopiedId(null), 2000);
    });
  }

  const fmt = (iso: string) => new Date(iso).toLocaleDateString('en-ZA', { day: '2-digit', month: 'short', year: 'numeric' });

  return (
    <AppLayout>
      <div className="min-h-screen bg-gray-950 px-4 py-8 sm:px-8">
        <div className="mx-auto max-w-4xl space-y-8">

          <div className="flex items-center gap-3">
            <Shield className="h-7 w-7 text-teal-400" />
            <div>
              <h1 className="text-2xl font-bold text-white">User Access Control</h1>
              <p className="text-sm text-gray-400">Manage who can access this company and what they can do.</p>
            </div>
          </div>

          {feedback && <div className="rounded-lg border border-teal-700 bg-teal-900/40 px-4 py-3 text-sm text-teal-300">{feedback}</div>}
          {error && <div className="rounded-lg border border-red-700 bg-red-900/30 px-4 py-3 text-sm text-red-300">{error}</div>}

          {/* Current Users */}
          <div className="rounded-xl border border-gray-800 bg-gray-900">
            <div className="flex items-center gap-2 border-b border-gray-800 px-6 py-4">
              <Users className="h-5 w-5 text-teal-400" />
              <h2 className="font-semibold text-white">Company Users</h2>
            </div>
            {loading ? (
              <div className="px-6 py-10 text-center text-gray-500">Loading...</div>
            ) : (
              <div className="overflow-x-auto">
                <table className="w-full text-sm">
                  <thead>
                    <tr className="border-b border-gray-800 text-left text-gray-500">
                      <th className="px-6 py-3 font-medium">Name</th>
                      <th className="px-6 py-3 font-medium">Email</th>
                      <th className="px-6 py-3 font-medium">Role</th>
                      <th className="px-6 py-3 font-medium">Joined</th>
                      {isAdmin && <th className="px-6 py-3 font-medium">Actions</th>}
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-gray-800">
                    {users.map((u) => {
                      const isSelf = u.userId === user?.id;
                      const isLastOwner = u.role === 'owner' && ownerCount <= 1;
                      return (
                        <tr key={u.userId} className="hover:bg-gray-800/40">
                          <td className="px-6 py-3 text-white">
                            {u.name}{isSelf && <span className="ml-2 text-xs text-gray-500">(you)</span>}
                          </td>
                          <td className="px-6 py-3 text-gray-400">{u.email}</td>
                          <td className="px-6 py-3">
                            {isAdmin && !isSelf ? (
                              <select value={u.role} onChange={(e) => handleRoleChange(u.userId, e.target.value)}
                                className="rounded border border-gray-700 bg-gray-800 px-2 py-1 text-xs text-white focus:border-teal-500 focus:outline-none">
                                {ROLES.map((r) => <option key={r} value={r}>{r}</option>)}
                              </select>
                            ) : (
                              <span className={`inline-flex rounded-full px-2 py-0.5 text-xs font-medium ${ROLE_BADGE[u.role] ?? 'bg-gray-700 text-gray-300'}`}>{u.role}</span>
                            )}
                          </td>
                          <td className="px-6 py-3 text-gray-400">{fmt(u.joinedAt)}</td>
                          {isAdmin && (
                            <td className="px-6 py-3">
                              {!isSelf && !isLastOwner && (
                                confirmRemove === u.userId ? (
                                  <span className="flex items-center gap-2">
                                    <button onClick={() => handleRemove(u.userId)} className="text-xs text-red-400 hover:text-red-300">Confirm</button>
                                    <button onClick={() => setConfirmRemove(null)} className="text-xs text-gray-500 hover:text-gray-300">Cancel</button>
                                  </span>
                                ) : (
                                  <button onClick={() => setConfirmRemove(u.userId)} className="text-gray-500 hover:text-red-400">
                                    <Trash2 className="h-4 w-4" />
                                  </button>
                                )
                              )}
                            </td>
                          )}
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              </div>
            )}
          </div>

          {/* Invite User (admin/owner only) */}
          {isAdmin && (
            <div className="rounded-xl border border-gray-800 bg-gray-900">
              <div className="flex items-center gap-2 border-b border-gray-800 px-6 py-4">
                <UserPlus className="h-5 w-5 text-teal-400" />
                <h2 className="font-semibold text-white">Invite a User</h2>
              </div>
              <div className="px-6 py-5">
                <form onSubmit={handleInvite} className="flex flex-wrap items-end gap-3">
                  <div className="flex-1 min-w-[220px]">
                    <label className="mb-1 block text-xs font-medium text-gray-400">Email Address</label>
                    <input type="email" value={inviteEmail} onChange={(e) => setInviteEmail(e.target.value)}
                      placeholder="colleague@example.com" required
                      className="w-full rounded-lg border border-gray-700 bg-gray-800 px-3 py-2 text-sm text-white placeholder-gray-500 focus:border-teal-500 focus:outline-none" />
                  </div>
                  <div>
                    <label className="mb-1 block text-xs font-medium text-gray-400">Role</label>
                    <select value={inviteRole} onChange={(e) => setInviteRole(e.target.value)}
                      className="rounded-lg border border-gray-700 bg-gray-800 px-3 py-2 text-sm text-white focus:border-teal-500 focus:outline-none">
                      {ROLES.map((r) => <option key={r} value={r}>{r}</option>)}
                    </select>
                  </div>
                  <button type="submit" disabled={inviting}
                    className="rounded-lg bg-teal-600 px-4 py-2 text-sm font-medium text-white hover:bg-teal-500 disabled:opacity-50">
                    {inviting ? 'Sending...' : 'Invite'}
                  </button>
                </form>
              </div>
              {invitations.length > 0 && (
                <div className="border-t border-gray-800 px-6 py-4">
                  <p className="mb-3 text-xs font-medium uppercase tracking-wide text-gray-500">Pending Invitations</p>
                  <ul className="space-y-2">
                    {invitations.map((inv) => (
                      <li key={inv.id} className="flex items-center justify-between rounded-lg border border-gray-700/50 bg-gray-800/40 px-4 py-3">
                        <div className="flex items-center gap-3">
                          <Mail className="h-4 w-4 text-gray-500" />
                          <div>
                            <p className="text-sm text-white">{inv.email}</p>
                            <div className="flex items-center gap-2 text-xs text-gray-500">
                              <span className={`inline-flex rounded-full px-2 py-0.5 font-medium ${ROLE_BADGE[inv.role] ?? 'bg-gray-700 text-gray-300'}`}>{inv.role}</span>
                              <Clock className="h-3 w-3" />
                              <span>Expires {fmt(inv.expiresAt)}</span>
                              {inv.emailSentAt ? (
                                <span className="inline-flex items-center gap-1 rounded-full bg-green-900/50 px-2 py-0.5 text-green-400">
                                  <Mail className="h-3 w-3" />
                                  Email sent
                                </span>
                              ) : inv.emailError ? (
                                <span className="inline-flex items-center gap-1 rounded-full bg-red-900/50 px-2 py-0.5 text-red-400" title={inv.emailError}>
                                  <Mail className="h-3 w-3" />
                                  Email failed
                                </span>
                              ) : (
                                <span className="inline-flex items-center gap-1 rounded-full bg-orange-900/50 px-2 py-0.5 text-orange-400">
                                  <Mail className="h-3 w-3" />
                                  Email pending
                                </span>
                              )}
                            </div>
                          </div>
                        </div>
                        <div className="flex items-center gap-3">
                          <button
                            onClick={() => handleCopyLink(inv)}
                            title="Copy invite link"
                            className="flex items-center gap-1 text-xs text-gray-500 hover:text-teal-400 transition-colors"
                          >
                            {copiedId === inv.id
                              ? <><Check className="h-3.5 w-3.5 text-teal-400" /><span className="text-teal-400">Copied</span></>
                              : <><Copy className="h-3.5 w-3.5" /><span>Copy link</span></>
                            }
                          </button>
                          <button onClick={() => handleCancelInvite(inv.id)} className="text-xs text-gray-500 hover:text-red-400">Cancel</button>
                        </div>
                      </li>
                    ))}
                  </ul>
                </div>
              )}
            </div>
          )}

        </div>
      </div>
    </AppLayout>
  );
}

/**
 * Standalone AppLayout for the Accounting app.
 * Supports two nav modes: top-bar (Sage-style, default) or sidebar.
 * User preference persisted in localStorage.
 */

import { useState, useEffect, useRef, ReactNode, useMemo } from 'react';
import { useRouter } from 'next/router';
import {
  BookOpen,
  ChevronLeft,
  ChevronRight,
  Menu,
  LogOut,
  User,
  Moon,
  Sun,
  PanelLeft,
  PanelTop,
  Download,
  X as XIcon,
  Search,
} from 'lucide-react';
import dynamic from 'next/dynamic';
import { useAuth } from '@/contexts/AuthContext';
import { useTheme } from '@/contexts/ThemeContext';
import { useCompany } from '@/contexts/CompanyContext';
import { LoadingSpinner } from '@/components/ui/LoadingSpinner';
import { CompanySwitcher } from '@/components/layout/CompanySwitcher';
import { SidebarNav } from '@/components/layout/SidebarNav';
import { CommandPalette } from '@/components/layout/CommandPalette';
import { ShortcutHelpOverlay } from '@/components/layout/ShortcutHelpOverlay';
import { useKeyboardShortcuts } from '@/hooks/useKeyboardShortcuts';
import type { ShortcutConfig } from '@/lib/keyboard-shortcuts';

const AccountingNav = dynamic(
  () => import('@/components/accounting/AccountingNav').then(mod => ({ default: mod.AccountingNav })),
);

const SIDEBAR_COLLAPSED_KEY = 'accounting-sidebar-collapsed';
const NAV_MODE_KEY = 'accounting-nav-mode';
const PWA_INSTALL_DISMISSED_KEY = 'isaflow-pwa-install-dismissed';

type NavMode = 'top' | 'side';

// ─── Props ──────────────────────────────────────────────────────────────────

interface AppLayoutProps {
  children: ReactNode;
}

// ─── Component ──────────────────────────────────────────────────────────────

export function AppLayout({ children }: AppLayoutProps) {
  const router = useRouter();
  const { user, loading, logout } = useAuth();
  const { theme, toggleTheme } = useTheme();
  const { companyRole } = useCompany();

  // Command palette
  const [commandPaletteOpen, setCommandPaletteOpen] = useState(false);

  // Shortcut help overlay
  const [shortcutHelpOpen, setShortcutHelpOpen] = useState(false);

  // Nav mode preference
  const [navMode, setNavMode] = useState<NavMode>('top');

  // Mobile sidebar open state (used in both modes for mobile)
  const [mobileOpen, setMobileOpen] = useState(false);

  // Desktop collapsed state (sidebar mode only)
  const [collapsed, setCollapsed] = useState(false);
  const [hydrated, setHydrated] = useState(false);

  // PWA install prompt
  const deferredPromptRef = useRef<Event | null>(null);
  const [showInstallBanner, setShowInstallBanner] = useState(false);

  useEffect(() => {
    const savedMode = localStorage.getItem(NAV_MODE_KEY) as NavMode | null;
    if (savedMode === 'top' || savedMode === 'side') setNavMode(savedMode);
    const savedCollapsed = localStorage.getItem(SIDEBAR_COLLAPSED_KEY);
    if (savedCollapsed !== null) setCollapsed(JSON.parse(savedCollapsed) as boolean);
    setHydrated(true);
  }, []);

  // Listen for PWA install prompt
  useEffect(() => {
    const dismissed = localStorage.getItem(PWA_INSTALL_DISMISSED_KEY);
    if (dismissed) return;

    const handler = (e: Event) => {
      e.preventDefault();
      deferredPromptRef.current = e;
      setShowInstallBanner(true);
    };
    window.addEventListener('beforeinstallprompt', handler);
    return () => window.removeEventListener('beforeinstallprompt', handler);
  }, []);

  useEffect(() => {
    if (hydrated) {
      localStorage.setItem(NAV_MODE_KEY, navMode);
      localStorage.setItem(SIDEBAR_COLLAPSED_KEY, JSON.stringify(collapsed));
    }
  }, [collapsed, navMode, hydrated]);

  // ─── Global keyboard shortcuts ────────────────────────────────────────────
  const globalShortcuts = useMemo<ShortcutConfig[]>(() => [
    {
      key: 'ctrl+k',
      label: 'Ctrl+K',
      description: 'Open command palette',
      category: 'global',
      action: () => setCommandPaletteOpen(true),
    },
    {
      key: '?',
      label: '?',
      description: 'Show keyboard shortcuts',
      category: 'global',
      action: () => setShortcutHelpOpen(true),
    },
    // Navigation sequences — press G then the second key within 1 second
    {
      key: 'g d',
      label: 'G then D',
      description: 'Go to Dashboard',
      category: 'navigation',
      action: () => { void router.push('/accounting'); },
    },
    {
      key: 'g c',
      label: 'G then C',
      description: 'Go to Customers',
      category: 'navigation',
      action: () => { void router.push('/accounting?tab=customers'); },
    },
    {
      key: 'g s',
      label: 'G then S',
      description: 'Go to Suppliers',
      category: 'navigation',
      action: () => { void router.push('/accounting?tab=suppliers'); },
    },
    {
      key: 'g b',
      label: 'G then B',
      description: 'Go to Banking',
      category: 'navigation',
      action: () => { void router.push('/accounting?tab=banking'); },
    },
    {
      key: 'g a',
      label: 'G then A',
      description: 'Go to Accounts',
      category: 'navigation',
      action: () => { void router.push('/accounting?tab=accounts'); },
    },
    {
      key: 'g r',
      label: 'G then R',
      description: 'Go to Reports',
      category: 'navigation',
      action: () => { void router.push('/accounting?tab=reports'); },
    },
    {
      key: 'g v',
      label: 'G then V',
      description: 'Go to VAT',
      category: 'navigation',
      action: () => { void router.push('/accounting?tab=vat'); },
    },
  ], [router]);

  useKeyboardShortcuts(globalShortcuts);

  // Close mobile nav on route change
  useEffect(() => {
    setMobileOpen(false);
  }, [router.pathname]);

  const toggleNavMode = () => setNavMode(m => m === 'top' ? 'side' : 'top');

  const handleInstall = async () => {
    const prompt = deferredPromptRef.current as (Event & { prompt: () => Promise<void> }) | null;
    if (!prompt) return;
    await prompt.prompt();
    deferredPromptRef.current = null;
    setShowInstallBanner(false);
  };

  const dismissInstall = () => {
    setShowInstallBanner(false);
    localStorage.setItem(PWA_INSTALL_DISMISSED_KEY, '1');
  };

  const userInitials = user
    ? (`${user.firstName?.[0] ?? ''}${user.lastName?.[0] ?? ''}`.toUpperCase() || user.email?.[0]?.toUpperCase() || 'U')
    : 'U';

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-950">
        <div className="text-center">
          <LoadingSpinner size="lg" className="mx-auto mb-4" />
          <p className="text-gray-400 text-sm">Loading...</p>
        </div>
      </div>
    );
  }

  // ─── Sidebar content (shared between mobile + desktop sidebar) ────────────

  const SidebarContent = (
    <>
      {/* Logo */}
      <div className={`flex items-center px-4 py-4 border-b border-gray-200 dark:border-gray-700 ${collapsed ? 'justify-center' : ''}`}>
        {collapsed ? (
          <div className="w-8 h-8 bg-teal-600 rounded-lg flex items-center justify-center flex-shrink-0">
            <BookOpen className="w-4 h-4 text-white" />
          </div>
        ) : (
          <img src="/logo.png" alt="ISAFlow" className="h-9 w-auto dark:brightness-0 dark:invert" />
        )}
      </div>

      {/* Nav — uses same TABS config as top nav */}
      <SidebarNav collapsed={collapsed} />

      {/* User area */}
      <div className={`border-t border-gray-200 dark:border-gray-700 p-3 ${collapsed ? 'flex flex-col items-center gap-2' : ''}`}>
        {user && !collapsed && (
          <div className="flex items-center gap-2 px-2 py-2 mb-1">
            <div className="w-7 h-7 bg-teal-700 rounded-full flex items-center justify-center flex-shrink-0">
              <span className="text-xs text-white font-semibold">{userInitials}</span>
            </div>
            <div className="flex-1 min-w-0">
              <p className="text-xs font-medium text-gray-900 dark:text-white truncate">
                {user.firstName} {user.lastName}
              </p>
              <p className="text-xs text-gray-500 truncate capitalize">{companyRole || user.role}</p>
            </div>
          </div>
        )}
        <button
          onClick={() => void logout()}
          title={collapsed ? 'Log out' : undefined}
          className={`
            flex items-center gap-2 w-full px-3 py-2 rounded-lg text-sm text-gray-500 dark:text-gray-400
            hover:text-gray-900 dark:hover:text-white hover:bg-gray-100 dark:hover:bg-gray-700/50 transition-colors
            ${collapsed ? 'justify-center' : ''}
          `}
        >
          <LogOut className="w-4 h-4 flex-shrink-0" />
          {!collapsed && <span>Log out</span>}
        </button>
      </div>
    </>
  );

  const showSidebar = navMode === 'side';

  return (
    <div className="flex h-screen bg-white dark:bg-gray-950 overflow-hidden">

      {/* ── Desktop sidebar (only in side mode) ──────────────────────────── */}
      {showSidebar && (
        <aside
          className={`
            hidden lg:flex flex-col bg-gray-50 dark:bg-gray-900 border-r border-gray-200 dark:border-gray-700
            transition-all duration-300 flex-shrink-0
            ${collapsed ? 'w-16' : 'w-64'}
          `}
        >
          {SidebarContent}

          {/* Collapse toggle */}
          <button
            onClick={() => setCollapsed(c => !c)}
            className="flex items-center justify-center h-10 border-t border-gray-200 dark:border-gray-700 text-gray-400 hover:text-gray-900 dark:hover:text-white hover:bg-gray-100 dark:hover:bg-gray-700/50 transition-colors"
            title={collapsed ? 'Expand sidebar' : 'Collapse sidebar'}
          >
            {collapsed
              ? <ChevronRight className="w-4 h-4" />
              : <ChevronLeft className="w-4 h-4" />
            }
          </button>
        </aside>
      )}

      {/* ── Mobile sidebar overlay (always available for mobile) ──────── */}
      {mobileOpen && (
        <div
          className="fixed inset-0 z-30 bg-black/60 lg:hidden"
          onClick={() => setMobileOpen(false)}
        />
      )}
      <aside
        className={`
          fixed inset-y-0 left-0 z-40 w-64 bg-gray-50 dark:bg-gray-900 border-r border-gray-200 dark:border-gray-700
          flex flex-col lg:hidden transition-transform duration-300
          ${mobileOpen ? 'translate-x-0' : '-translate-x-full'}
        `}
      >
        {SidebarContent}
      </aside>

      {/* ── Main area ────────────────────────────────────────────────────── */}
      <div className="flex-1 flex flex-col min-w-0">

        {/* PWA install banner */}
        {showInstallBanner && (
          <div className="bg-teal-600 text-white px-4 py-2 flex items-center justify-between text-sm flex-shrink-0">
            <div className="flex items-center gap-2">
              <Download className="w-4 h-4" />
              <span>Install IsaFlow for a faster, app-like experience</span>
            </div>
            <div className="flex items-center gap-2">
              <button onClick={handleInstall} className="px-3 py-1 bg-white/20 hover:bg-white/30 rounded text-xs font-medium transition-colors">
                Install
              </button>
              <button onClick={dismissInstall} className="p-1 hover:bg-white/20 rounded transition-colors" aria-label="Dismiss">
                <XIcon className="w-3.5 h-3.5" />
              </button>
            </div>
          </div>
        )}

        {/* Header bar */}
        <header className="bg-gray-50 dark:bg-gray-900 border-b border-gray-200 dark:border-gray-700 h-14 flex items-center px-4 gap-3 flex-shrink-0">
          {/* Mobile hamburger */}
          <button
            className="lg:hidden text-gray-400 hover:text-gray-900 dark:hover:text-white transition-colors"
            onClick={() => setMobileOpen(o => !o)}
            aria-label="Open menu"
          >
            <Menu className="w-5 h-5" />
          </button>

          {/* Logo (in top-nav mode, show logo here; in side mode it's in the sidebar) */}
          <img src="/logo.png" alt="ISAFlow" className="h-8 w-auto hidden sm:block dark:brightness-0 dark:invert" />

          {/* Company switcher */}
          <div data-tour="company-switcher">
            <CompanySwitcher />
          </div>

          <div className="flex-1" />

          {/* Command palette trigger */}
          <button
            onClick={() => setCommandPaletteOpen(true)}
            className="
              hidden sm:flex items-center gap-2 px-3 py-1.5 rounded-lg text-sm
              text-[var(--ff-text-tertiary)] bg-[var(--ff-bg-secondary)]
              border border-[var(--ff-border-primary)]
              hover:border-teal-400 hover:text-[var(--ff-text-primary)]
              transition-colors
            "
            title="Search (Ctrl+K)"
          >
            <Search className="w-3.5 h-3.5" />
            <span className="text-xs">Search</span>
            <kbd className="ml-1 px-1 py-0.5 text-[10px] bg-[var(--ff-bg-primary)] border border-[var(--ff-border-primary)] rounded">
              Ctrl+K
            </kbd>
          </button>

          {/* Mobile search icon */}
          <button
            onClick={() => setCommandPaletteOpen(true)}
            className="sm:hidden p-2 rounded-lg text-gray-400 hover:text-gray-900 dark:hover:text-white hover:bg-gray-100 dark:hover:bg-gray-700/50 transition-colors"
            title="Search"
            aria-label="Open search"
          >
            <Search className="w-4 h-4" />
          </button>

          {/* Nav mode toggle */}
          <button
            onClick={toggleNavMode}
            className="p-2 rounded-lg text-gray-400 hover:text-gray-900 dark:hover:text-white hover:bg-gray-100 dark:hover:bg-gray-700/50 transition-colors"
            title={navMode === 'top' ? 'Switch to sidebar navigation' : 'Switch to top navigation'}
          >
            {navMode === 'top' ? <PanelLeft className="w-4 h-4" /> : <PanelTop className="w-4 h-4" />}
          </button>

          {/* Theme toggle */}
          <button
            onClick={toggleTheme}
            className="p-2 rounded-lg text-gray-400 hover:text-gray-900 dark:hover:text-white hover:bg-gray-100 dark:hover:bg-gray-700/50 transition-colors"
            title={theme === 'dark' ? 'Switch to light mode' : 'Switch to dark mode'}
          >
            {theme === 'dark' ? <Sun className="w-4 h-4" /> : <Moon className="w-4 h-4" />}
          </button>

          {/* User info */}
          {user && (
            <div className="flex items-center gap-2 text-sm text-gray-500 dark:text-gray-400">
              <User className="w-4 h-4" />
              <span className="hidden sm:inline truncate max-w-[160px]">
                {user.firstName} {user.lastName}
              </span>
            </div>
          )}

          {/* Logout (visible in top-nav mode where sidebar user area is hidden) */}
          {!showSidebar && (
            <button
              onClick={() => void logout()}
              className="p-2 rounded-lg text-gray-400 hover:text-red-500 transition-colors"
              title="Log out"
            >
              <LogOut className="w-4 h-4" />
            </button>
          )}
        </header>

        {/* Horizontal nav bar (only in top mode) */}
        {!showSidebar && (
          <div className="relative z-40">
            <AccountingNav />
          </div>
        )}

        {/* Page content */}
        <main className="flex-1 overflow-y-auto bg-white dark:bg-gray-950 p-4 lg:p-6 relative z-0">
          {children}
        </main>
      </div>

      {/* Command Palette */}
      <CommandPalette
        isOpen={commandPaletteOpen}
        onClose={() => setCommandPaletteOpen(false)}
      />

      {/* Shortcut Help Overlay — triggered by '?' */}
      <ShortcutHelpOverlay
        isOpen={shortcutHelpOpen}
        onClose={() => setShortcutHelpOpen(false)}
        shortcuts={globalShortcuts}
      />
    </div>
  );
}

