/**
 * Duplicate Detection Service
 * PRD: WS-6.6 — Duplicate Detection and Merge Wizard
 *
 * Detects potential duplicate customers, suppliers, and items using
 * fuzzy name matching, exact email matching, and VAT number matching.
 * Supports merging (reassigning transactions) and soft-deleting duplicates.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { fuzzyMatch } from '@/modules/accounting/utils/fuzzyMatcher';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

// ── Types ─────────────────────────────────────────────────────────────────────

export interface DuplicateEntity {
  id: string;
  name: string;
  email?: string;
  vatNumber?: string;
  phone?: string;
  [key: string]: unknown;
}

export interface DuplicatePair {
  entityType: 'customer' | 'supplier' | 'item';
  primary: DuplicateEntity;
  duplicate: DuplicateEntity;
  confidence: number;   // 0–100
  matchReasons: string[];
}

export interface MergeResult {
  reassignedTransactions: number;
}

// ── Detection ─────────────────────────────────────────────────────────────────

export async function detectDuplicates(
  companyId: string,
  entityType: 'customer' | 'supplier' | 'item',
): Promise<DuplicatePair[]> {
  log.info('Detecting duplicates', { companyId, entityType }, 'duplicate-detection');

  if (entityType === 'customer') return detectCustomerDuplicates(companyId);
  if (entityType === 'supplier') return detectSupplierDuplicates(companyId);
  return detectItemDuplicates(companyId);
}

// ── Customer duplicate detection ──────────────────────────────────────────────

async function detectCustomerDuplicates(companyId: string): Promise<DuplicatePair[]> {
  const rows = (await sql`
    SELECT id, name, email, vat_number, phone, registration_number, contact_person, billing_address
    FROM customers
    WHERE company_id = ${companyId}::UUID
      AND deleted_at IS NULL
      AND is_active = true
    ORDER BY name
  `) as Row[];

  const entities: DuplicateEntity[] = rows.map((r: Row) => ({
    id: r.id,
    name: r.name,
    email: r.email,
    vatNumber: r.vat_number,
    phone: r.phone,
    registrationNumber: r.registration_number,
    contactPerson: r.contact_person,
    billingAddress: r.billing_address,
  }));

  return findDuplicatePairs(entities, 'customer', 0.85);
}

// ── Supplier duplicate detection ──────────────────────────────────────────────

async function detectSupplierDuplicates(companyId: string): Promise<DuplicatePair[]> {
  const rows = (await sql`
    SELECT id, name, email, vat_number, phone, registration_number, contact_person, address
    FROM suppliers
    WHERE company_id = ${companyId}::UUID
      AND deleted_at IS NULL
      AND is_active = true
    ORDER BY name
  `) as Row[];

  const entities: DuplicateEntity[] = rows.map((r: Row) => ({
    id: r.id,
    name: r.name,
    email: r.email,
    vatNumber: r.vat_number,
    phone: r.phone,
    registrationNumber: r.registration_number,
    contactPerson: r.contact_person,
    address: r.address,
  }));

  return findDuplicatePairs(entities, 'supplier', 0.85);
}

// ── Item duplicate detection ──────────────────────────────────────────────────

async function detectItemDuplicates(companyId: string): Promise<DuplicatePair[]> {
  const rows = (await sql`
    SELECT id, code, description, item_type, unit, cost_price, selling_price_excl
    FROM items
    WHERE company_id = ${companyId}::UUID
      AND deleted_at IS NULL
      AND is_active = true
    ORDER BY code
  `) as Row[];

  const pairs: DuplicatePair[] = [];
  const seen = new Set<string>();

  for (let i = 0; i < rows.length; i++) {
    for (let j = i + 1; j < rows.length; j++) {
      const a = rows[i]!;
      const b = rows[j]!;
      const pairKey = [a.id, b.id].sort().join(':');
      if (seen.has(pairKey)) continue;

      const reasons: string[] = [];
      let confidence = 0;

      // Exact code match = 100% confident
      if (a.code && b.code && a.code.toLowerCase() === b.code.toLowerCase()) {
        reasons.push(`Same item code: ${a.code}`);
        confidence = 100;
      } else {
        // Name fuzzy match >90%
        const nameResult = fuzzyMatch(a.description, [b.description], 0.90);
        if (nameResult) {
          const pct = Math.round(nameResult.score * 100);
          reasons.push(`Name ${pct}% match`);
          confidence = Math.max(confidence, pct);
        }
      }

      if (reasons.length > 0) {
        seen.add(pairKey);
        pairs.push({
          entityType: 'item',
          primary: { id: a.id, name: a.description, itemCode: a.code, itemType: a.item_type, unit: a.unit, costPrice: a.cost_price, sellingPrice: a.selling_price_excl },
          duplicate: { id: b.id, name: b.description, itemCode: b.code, itemType: b.item_type, unit: b.unit, costPrice: b.cost_price, sellingPrice: b.selling_price_excl },
          confidence,
          matchReasons: reasons,
        });
      }
    }
  }

  log.info('Item duplicate scan complete', { count: pairs.length, companyId }, 'duplicate-detection');
  return pairs;
}

// ── Generic pair-finding for customers and suppliers ──────────────────────────

function findDuplicatePairs(
  entities: DuplicateEntity[],
  entityType: 'customer' | 'supplier',
  nameThreshold: number,
): DuplicatePair[] {
  const pairs: DuplicatePair[] = [];
  const seen = new Set<string>();

  // For >500 entities, group by first 3 chars of name to reduce O(n²) comparisons
  const useBucketing = entities.length > 500;
  const buckets = new Map<string, DuplicateEntity[]>();

  if (useBucketing) {
    for (const e of entities) {
      const key = e.name.toLowerCase().slice(0, 3);
      if (!buckets.has(key)) buckets.set(key, []);
      buckets.get(key)!.push(e);
    }
  }

  const compareGroups = useBucketing
    ? Array.from(buckets.values())
    : [entities];

  for (const group of compareGroups) {
    for (let i = 0; i < group.length; i++) {
      for (let j = i + 1; j < group.length; j++) {
        const a = group[i]!;
        const b = group[j]!;
        const pairKey = [a.id, b.id].sort().join(':');
        if (seen.has(pairKey)) continue;

        const reasons: string[] = [];
        let confidence = 0;

        // Same VAT number (exact)
        if (a.vatNumber && b.vatNumber && a.vatNumber === b.vatNumber) {
          reasons.push(`Same VAT number: ${a.vatNumber}`);
          confidence = Math.max(confidence, 95);
        }

        // Same email (case-insensitive)
        if (a.email && b.email && a.email.toLowerCase() === b.email.toLowerCase()) {
          reasons.push(`Same email: ${a.email}`);
          confidence = Math.max(confidence, 90);
        }

        // Fuzzy name match
        const nameResult = fuzzyMatch(a.name, [b.name], nameThreshold);
        if (nameResult) {
          const pct = Math.round(nameResult.score * 100);
          reasons.push(`Name ${pct}% match`);
          confidence = Math.max(confidence, pct);
        }

        if (reasons.length > 0) {
          seen.add(pairKey);
          pairs.push({
            entityType,
            primary: a,
            duplicate: b,
            confidence: Math.min(confidence, 100),
            matchReasons: reasons,
          });
        }
      }
    }
  }

  pairs.sort((a, b) => b.confidence - a.confidence);
  log.info(`${entityType} duplicate scan complete`, { count: pairs.length }, 'duplicate-detection');
  return pairs;
}

// ── Merge ─────────────────────────────────────────────────────────────────────

export async function mergeEntities(
  companyId: string,
  entityType: 'customer' | 'supplier' | 'item',
  primaryId: string,
  duplicateId: string,
  userId: string,
): Promise<MergeResult> {
  log.info('Merging entities', { companyId, entityType, primaryId, duplicateId, userId }, 'duplicate-detection');

  if (primaryId === duplicateId) {
    throw new Error('Primary and duplicate cannot be the same entity');
  }

  if (entityType === 'customer') return mergeCustomers(companyId, primaryId, duplicateId);
  if (entityType === 'supplier') return mergeSuppliers(companyId, primaryId, duplicateId);
  return mergeItems(companyId, primaryId, duplicateId);
}

// ── Customer merge ────────────────────────────────────────────────────────────

async function mergeCustomers(
  companyId: string,
  primaryId: string,
  duplicateId: string,
): Promise<MergeResult> {
  // Verify both belong to this company
  const check = (await sql`
    SELECT id FROM customers
    WHERE id IN (${primaryId}::UUID, ${duplicateId}::UUID)
      AND company_id = ${companyId}::UUID
      AND deleted_at IS NULL
  `) as Row[];
  if (check.length !== 2) throw new Error('One or both customers not found for this company');

  let count = 0;

  // Reassign customer_invoices (both customer_id and client_id columns)
  const ciRes = (await sql`
    UPDATE customer_invoices
    SET customer_id = ${primaryId}::UUID,
        client_id   = ${primaryId}::UUID
    WHERE company_id = ${companyId}::UUID
      AND (customer_id = ${duplicateId}::UUID OR client_id = ${duplicateId}::UUID)
  `) as { count?: number };
  count += Number((ciRes as unknown as { rowCount?: number }).rowCount ?? 0);

  // Reassign customer_payments (client_id column)
  const cpRes = (await sql`
    UPDATE customer_payments
    SET client_id = ${primaryId}::UUID
    WHERE company_id = ${companyId}::UUID
      AND client_id = ${duplicateId}::UUID
  `) as unknown as { rowCount?: number };
  count += Number(cpRes.rowCount ?? 0);

  // Reassign credit_notes (client_id column)
  const cnRes = (await sql`
    UPDATE credit_notes
    SET client_id = ${primaryId}::UUID
    WHERE company_id = ${companyId}::UUID
      AND client_id = ${duplicateId}::UUID
  `) as unknown as { rowCount?: number };
  count += Number(cnRes.rowCount ?? 0);

  // Reassign customer_sales_orders
  const soRes = (await sql`
    UPDATE customer_sales_orders
    SET customer_id = ${primaryId}::UUID
    WHERE company_id = ${companyId}::UUID
      AND customer_id = ${duplicateId}::UUID
  `) as unknown as { rowCount?: number };
  count += Number(soRes.rowCount ?? 0);

  // Reassign customer_quotes
  const cqRes = (await sql`
    UPDATE customer_quotes
    SET client_id = ${primaryId}::UUID
    WHERE company_id = ${companyId}::UUID
      AND client_id = ${duplicateId}::UUID
  `) as unknown as { rowCount?: number };
  count += Number(cqRes.rowCount ?? 0);

  // Soft-delete the duplicate
  await sql`
    UPDATE customers
    SET deleted_at = NOW()
    WHERE id = ${duplicateId}::UUID
      AND company_id = ${companyId}::UUID
  `;

  log.info('Customer merge complete', { primaryId, duplicateId, count }, 'duplicate-detection');
  return { reassignedTransactions: count };
}

// ── Supplier merge ────────────────────────────────────────────────────────────

async function mergeSuppliers(
  companyId: string,
  primaryId: string,
  duplicateId: string,
): Promise<MergeResult> {
  const check = (await sql`
    SELECT id FROM suppliers
    WHERE id IN (${primaryId}::UUID, ${duplicateId}::UUID)
      AND company_id = ${companyId}::UUID
      AND deleted_at IS NULL
  `) as Row[];
  if (check.length !== 2) throw new Error('One or both suppliers not found for this company');

  let count = 0;

  // Reassign supplier_invoices
  const siRes = (await sql`
    UPDATE supplier_invoices
    SET supplier_id = ${primaryId}::UUID
    WHERE company_id = ${companyId}::UUID
      AND supplier_id = ${duplicateId}::UUID
  `) as unknown as { rowCount?: number };
  count += Number(siRes.rowCount ?? 0);

  // Reassign supplier_payments
  const spRes = (await sql`
    UPDATE supplier_payments
    SET supplier_id = ${primaryId}::UUID
    WHERE company_id = ${companyId}::UUID
      AND supplier_id = ${duplicateId}::UUID
  `) as unknown as { rowCount?: number };
  count += Number(spRes.rowCount ?? 0);

  // Reassign supplier_purchase_orders
  const poRes = (await sql`
    UPDATE supplier_purchase_orders
    SET supplier_id = ${primaryId}::UUID
    WHERE company_id = ${companyId}::UUID
      AND supplier_id = ${duplicateId}::UUID
  `) as unknown as { rowCount?: number };
  count += Number(poRes.rowCount ?? 0);

  // Soft-delete the duplicate
  await sql`
    UPDATE suppliers
    SET deleted_at = NOW()
    WHERE id = ${duplicateId}::UUID
      AND company_id = ${companyId}::UUID
  `;

  log.info('Supplier merge complete', { primaryId, duplicateId, count }, 'duplicate-detection');
  return { reassignedTransactions: count };
}

// ── Item merge ────────────────────────────────────────────────────────────────

async function mergeItems(
  companyId: string,
  primaryId: string,
  duplicateId: string,
): Promise<MergeResult> {
  const check = (await sql`
    SELECT id FROM items
    WHERE id IN (${primaryId}::UUID, ${duplicateId}::UUID)
      AND company_id = ${companyId}::UUID
      AND deleted_at IS NULL
  `) as Row[];
  if (check.length !== 2) throw new Error('One or both items not found for this company');

  let count = 0;

  // Reassign customer_invoice_items
  const ciiRes = (await sql`
    UPDATE customer_invoice_items cii
    SET item_id = ${primaryId}::UUID
    FROM customer_invoices ci
    WHERE cii.invoice_id = ci.id
      AND ci.company_id = ${companyId}::UUID
      AND cii.item_id = ${duplicateId}::UUID
  `) as unknown as { rowCount?: number };
  count += Number(ciiRes.rowCount ?? 0);

  // Reassign supplier_purchase_order_items
  const spoiRes = (await sql`
    UPDATE supplier_purchase_order_items spoi
    SET item_id = ${primaryId}::UUID
    FROM supplier_purchase_orders spo
    WHERE spoi.purchase_order_id = spo.id
      AND spo.company_id = ${companyId}::UUID
      AND spoi.item_id = ${duplicateId}::UUID
  `) as unknown as { rowCount?: number };
  count += Number(spoiRes.rowCount ?? 0);

  // Reassign customer_sales_order_items
  const csoiRes = (await sql`
    UPDATE customer_sales_order_items csoi
    SET item_id = ${primaryId}::UUID
    FROM customer_sales_orders cso
    WHERE csoi.sales_order_id = cso.id
      AND cso.company_id = ${companyId}::UUID
      AND csoi.item_id = ${duplicateId}::UUID
  `) as unknown as { rowCount?: number };
  count += Number(csoiRes.rowCount ?? 0);

  // Soft-delete the duplicate
  await sql`
    UPDATE items
    SET deleted_at = NOW()
    WHERE id = ${duplicateId}::UUID
      AND company_id = ${companyId}::UUID
  `;

  log.info('Item merge complete', { primaryId, duplicateId, count }, 'duplicate-detection');
  return { reassignedTransactions: count };
}

