/**
 * GL Import Wizard — WS-6.3
 * 4-step wizard: Upload → Map Columns → Validate → Import
 */

import { useState, useEffect, useCallback, useRef } from 'react';
import { useRouter } from 'next/router';
import * as XLSX from 'xlsx';
import { AppLayout } from '@/components/layout/AppLayout';
import { apiFetch } from '@/lib/apiFetch';
import { log } from '@/lib/logger';
import {
  Upload, ArrowRight, ArrowLeft, CheckCircle2, XCircle,
  AlertTriangle, FileSpreadsheet, Download, Loader2, BookOpen,
} from 'lucide-react';
import type { ImportRow, ValidationSummary } from '@/modules/accounting/services/glImportService';

// ---- Types -------------------------------------------------------------------

type Step = 1 | 2 | 3 | 4;

const REQUIRED_FIELDS = ['date', 'accountCode', 'description', 'debit', 'credit'] as const;
const ALL_FIELDS = [
  { value: '__skip__', label: '— Skip —' },
  { value: 'date', label: 'Date' },
  { value: 'accountCode', label: 'Account Code' },
  { value: 'description', label: 'Description' },
  { value: 'reference', label: 'Reference' },
  { value: 'debit', label: 'Debit' },
  { value: 'credit', label: 'Credit' },
  { value: 'vatCode', label: 'VAT Code' },
  { value: 'costCentre', label: 'Cost Centre' },
];

const AUTO_MAP: Record<string, string> = {
  date: 'date', 'entry date': 'date', 'trans date': 'date',
  'account code': 'accountCode', account: 'accountCode', 'acc code': 'accountCode', code: 'accountCode',
  description: 'description', desc: 'description', narration: 'description', details: 'description',
  reference: 'reference', ref: 'reference',
  debit: 'debit', dr: 'debit',
  credit: 'credit', cr: 'credit',
  'vat code': 'vatCode', vatcode: 'vatCode', 'tax code': 'vatCode',
  'cost centre': 'costCentre', 'cost center': 'costCentre', cc: 'costCentre',
};

// ---- Step Indicator ----------------------------------------------------------

function StepIndicator({ current }: { current: Step }) {
  const steps = ['Upload', 'Map Columns', 'Validate', 'Import'];
  return (
    <div className="flex items-center gap-0">
      {steps.map((label, idx) => {
        const num = (idx + 1) as Step;
        const done = current > num;
        const active = current === num;
        return (
          <div key={label} className="flex items-center">
            <div className={`flex items-center gap-2 px-4 py-2 rounded-lg text-sm font-medium transition-colors ${
              active ? 'bg-teal-500/20 text-teal-400' :
              done ? 'text-teal-500' : 'text-[var(--ff-text-secondary)]'
            }`}>
              <span className={`w-6 h-6 rounded-full flex items-center justify-center text-xs font-bold ${
                done ? 'bg-teal-600 text-white' :
                active ? 'bg-teal-500 text-white' : 'bg-[var(--ff-border-light)] text-[var(--ff-text-secondary)]'
              }`}>
                {done ? <CheckCircle2 className="h-4 w-4" /> : num}
              </span>
              {label}
            </div>
            {idx < steps.length - 1 && (
              <ArrowRight className="h-4 w-4 text-[var(--ff-border-light)]" />
            )}
          </div>
        );
      })}
    </div>
  );
}

// ---- Main Page ---------------------------------------------------------------

export default function GlImportPage() {
  const router = useRouter();
  const [isMounted, setIsMounted] = useState(false);
  const [step, setStep] = useState<Step>(1);

  // Step 1
  const [rawHeaders, setRawHeaders] = useState<string[]>([]);
  const [rawRows, setRawRows] = useState<string[][]>([]);
  const [fileName, setFileName] = useState('');
  const [fileError, setFileError] = useState('');
  const fileRef = useRef<HTMLInputElement>(null);
  const [dragging, setDragging] = useState(false);

  // Step 2
  const [mapping, setMapping] = useState<Record<number, string>>({});

  // Step 3
  const [validating, setValidating] = useState(false);
  const [summary, setSummary] = useState<ValidationSummary | null>(null);
  const [validRows, setValidRows] = useState<ImportRow[]>([]);
  const [validateError, setValidateError] = useState('');

  // Step 4
  const [postImmediately, setPostImmediately] = useState(false);
  const [importing, setImporting] = useState(false);
  const [importResult, setImportResult] = useState<{ entriesCreated: number; linesCreated: number; totalValue: number } | null>(null);
  const [importError, setImportError] = useState('');

  useEffect(() => { setIsMounted(true); }, []);

  // ---- File parsing ----------------------------------------------------------

  const parseFile = useCallback((file: File) => {
    setFileError('');
    const name = file.name.toLowerCase();
    if (!name.endsWith('.xlsx') && !name.endsWith('.xls') && !name.endsWith('.csv')) {
      setFileError('Only .xlsx, .xls and .csv files are supported');
      return;
    }
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const data = e.target?.result;
        const wb = XLSX.read(data, { type: 'binary' });
        const ws = wb.Sheets[wb.SheetNames[0]!]!;
        const aoa = XLSX.utils.sheet_to_json<string[]>(ws, { header: 1, raw: false }) as string[][];
        if (aoa.length < 2) {
          setFileError('File must have a header row and at least one data row');
          return;
        }
        const headers = (aoa[0] ?? []).map(h => String(h ?? '').trim());
        const dataRows = aoa.slice(1).filter(r => r.some(c => c !== '' && c != null));
        setRawHeaders(headers);
        setRawRows(dataRows.map(r => headers.map((_, i) => String(r[i] ?? '').trim())));
        setFileName(file.name);

        // Auto-detect mapping
        const autoMapping: Record<number, string> = {};
        headers.forEach((h, i) => {
          const key = h.toLowerCase().trim();
          if (AUTO_MAP[key]) autoMapping[i] = AUTO_MAP[key]!;
          else autoMapping[i] = '__skip__';
        });
        setMapping(autoMapping);
        setStep(2);
      } catch (err) {
        log.error('Failed to parse spreadsheet', { error: err }, 'gl-import-page');
        setFileError('Failed to read file — make sure it is a valid Excel or CSV file');
      }
    };
    reader.readAsBinaryString(file);
  }, []);

  const handleFileDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setDragging(false);
    const file = e.dataTransfer.files[0];
    if (file) parseFile(file);
  }, [parseFile]);

  const handleFileSelect = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) parseFile(file);
  }, [parseFile]);

  // ---- Map Columns → build ImportRows ----------------------------------------

  const buildImportRows = useCallback((): ImportRow[] => {
    return rawRows.map(row => {
      const get = (field: string) => {
        const idx = Object.entries(mapping).find(([, v]) => v === field)?.[0];
        return idx != null ? (row[Number(idx)] ?? '') : '';
      };
      return {
        date: get('date'),
        accountCode: get('accountCode'),
        description: get('description'),
        reference: get('reference') || undefined,
        debit: parseFloat(get('debit').replace(/,/g, '')) || 0,
        credit: parseFloat(get('credit').replace(/,/g, '')) || 0,
        vatCode: get('vatCode') || undefined,
        costCentre: get('costCentre') || undefined,
      };
    });
  }, [rawRows, mapping]);

  const isMappingComplete = REQUIRED_FIELDS.every(
    f => Object.values(mapping).includes(f),
  );

  // ---- Step 3: Validate ------------------------------------------------------

  const handleValidate = useCallback(async () => {
    setValidating(true);
    setValidateError('');
    setSummary(null);
    try {
      const rows = buildImportRows();
      const res = await apiFetch('/api/accounting/gl-import-validate', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ rows }),
      });
      const json = await res.json() as { data: ValidationSummary };
      setSummary(json.data);
      // Keep only valid rows for import
      const valid = rows.filter((_, i) => json.data.validations[i]?.valid);
      setValidRows(valid);
      setStep(3);
    } catch (err) {
      log.error('Validation API error', { error: err }, 'gl-import-page');
      setValidateError('Validation failed — please try again');
    } finally {
      setValidating(false);
    }
  }, [buildImportRows]);

  // ---- Step 4: Import --------------------------------------------------------

  const handleImport = useCallback(async () => {
    setImporting(true);
    setImportError('');
    try {
      const res = await apiFetch('/api/accounting/gl-import', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ rows: validRows, postImmediately }),
      });
      const json = await res.json() as { data: { entriesCreated: number; linesCreated: number; totalValue: number } };
      setImportResult(json.data);
    } catch (err) {
      log.error('Import API error', { error: err }, 'gl-import-page');
      setImportError('Import failed — please try again');
    } finally {
      setImporting(false);
    }
  }, [validRows, postImmediately]);

  // ---- Render ----------------------------------------------------------------

  if (!isMounted) {
    return (
      <AppLayout>
        <div className="min-h-screen bg-[var(--ff-bg-primary)] flex items-center justify-center">
          <Loader2 className="h-8 w-8 animate-spin text-teal-500" />
        </div>
      </AppLayout>
    );
  }

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">

        {/* Header */}
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)]">
          <div className="px-6 py-4 flex items-center justify-between">
            <div className="flex items-center gap-3">
              <div className="p-2 rounded-lg bg-teal-500/10">
                <FileSpreadsheet className="h-6 w-6 text-teal-500" />
              </div>
              <div>
                <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">Import Transactions</h1>
                <p className="text-sm text-[var(--ff-text-secondary)]">Import GL journal entries from Excel or CSV</p>
              </div>
            </div>
            <a
              href="/api/accounting/gl-import-template"
              className="inline-flex items-center gap-2 px-4 py-2 border border-[var(--ff-border-light)] text-[var(--ff-text-secondary)] rounded-lg hover:bg-[var(--ff-bg-primary)] transition-colors text-sm"
            >
              <Download className="h-4 w-4" />
              Download Template
            </a>
          </div>
          <div className="px-6 pb-4">
            <StepIndicator current={step} />
          </div>
        </div>

        <div className="px-6 py-6 max-w-5xl mx-auto">

          {/* ── Step 1: Upload ─────────────────────────────────────────── */}
          {step === 1 && (
            <div className="space-y-4">
              <div
                onDragOver={e => { e.preventDefault(); setDragging(true); }}
                onDragLeave={() => setDragging(false)}
                onDrop={handleFileDrop}
                onClick={() => fileRef.current?.click()}
                className={`border-2 border-dashed rounded-xl p-12 text-center cursor-pointer transition-colors ${
                  dragging
                    ? 'border-teal-500 bg-teal-500/5'
                    : 'border-[var(--ff-border-light)] hover:border-teal-500/50 hover:bg-[var(--ff-bg-secondary)]'
                }`}
              >
                <Upload className="h-12 w-12 text-[var(--ff-text-secondary)] mx-auto mb-4" />
                <p className="text-lg font-medium text-[var(--ff-text-primary)] mb-1">
                  Drag and drop your file here
                </p>
                <p className="text-sm text-[var(--ff-text-secondary)]">
                  or click to browse — supports .xlsx, .xls, .csv
                </p>
                <input
                  ref={fileRef}
                  type="file"
                  accept=".xlsx,.xls,.csv"
                  className="hidden"
                  onChange={handleFileSelect}
                />
              </div>
              {fileError && (
                <div className="flex items-center gap-2 text-red-400 text-sm bg-red-500/10 border border-red-500/20 rounded-lg px-4 py-3">
                  <XCircle className="h-4 w-4 flex-shrink-0" />
                  {fileError}
                </div>
              )}
              <div className="bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)] rounded-lg p-4">
                <div className="flex items-center gap-2 mb-2">
                  <BookOpen className="h-4 w-4 text-teal-500" />
                  <span className="text-sm font-medium text-[var(--ff-text-primary)]">Required columns</span>
                </div>
                <p className="text-sm text-[var(--ff-text-secondary)]">
                  Date, Account Code, Description, Debit, Credit.
                  Optional: Reference, VAT Code, Cost Centre.
                  Download the template above for the correct format.
                </p>
              </div>
            </div>
          )}

          {/* ── Step 2: Map Columns ────────────────────────────────────── */}
          {step === 2 && (
            <div className="space-y-6">
              <div className="bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)] rounded-lg p-4">
                <p className="text-sm text-[var(--ff-text-secondary)] mb-4">
                  File: <span className="font-medium text-[var(--ff-text-primary)]">{fileName}</span> — {rawRows.length} data rows detected.
                  Map each column below. Required fields are marked with *.
                </p>
                <div className="overflow-x-auto">
                  <table className="w-full text-sm">
                    <thead>
                      <tr className="border-b border-[var(--ff-border-light)]">
                        <th className="text-left pb-2 pr-4 text-[var(--ff-text-secondary)] font-medium">Source Column</th>
                        <th className="text-left pb-2 pr-4 text-[var(--ff-text-secondary)] font-medium">Maps To</th>
                        {rawRows.slice(0, 3).map((_, i) => (
                          <th key={i} className="text-left pb-2 pr-2 text-[var(--ff-text-secondary)] font-medium">
                            Row {i + 1}
                          </th>
                        ))}
                      </tr>
                    </thead>
                    <tbody>
                      {rawHeaders.map((header, colIdx) => (
                        <tr key={colIdx} className="border-b border-[var(--ff-border-light)]/50">
                          <td className="py-2 pr-4 font-medium text-[var(--ff-text-primary)]">{header}</td>
                          <td className="py-2 pr-4">
                            <select
                              value={mapping[colIdx] ?? '__skip__'}
                              onChange={e => setMapping(prev => ({ ...prev, [colIdx]: e.target.value }))}
                              className="px-2 py-1 text-sm bg-[var(--ff-bg-primary)] border border-[var(--ff-border-light)] rounded text-[var(--ff-text-primary)] focus:outline-none focus:ring-2 focus:ring-teal-500/30"
                            >
                              {ALL_FIELDS.map(f => (
                                <option key={f.value} value={f.value}>{f.label}</option>
                              ))}
                            </select>
                          </td>
                          {rawRows.slice(0, 3).map((row, ri) => (
                            <td key={ri} className="py-2 pr-2 text-[var(--ff-text-secondary)] truncate max-w-[120px]">
                              {row[colIdx] ?? ''}
                            </td>
                          ))}
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
                {!isMappingComplete && (
                  <p className="mt-3 text-sm text-amber-400">
                    Required fields not yet mapped: {REQUIRED_FIELDS.filter(f => !Object.values(mapping).includes(f)).join(', ')}
                  </p>
                )}
              </div>
              {validateError && (
                <div className="flex items-center gap-2 text-red-400 text-sm bg-red-500/10 border border-red-500/20 rounded-lg px-4 py-3">
                  <XCircle className="h-4 w-4 flex-shrink-0" />
                  {validateError}
                </div>
              )}
              <div className="flex items-center justify-between">
                <button
                  onClick={() => setStep(1)}
                  className="inline-flex items-center gap-2 px-4 py-2 border border-[var(--ff-border-light)] text-[var(--ff-text-secondary)] rounded-lg hover:bg-[var(--ff-bg-secondary)] transition-colors text-sm"
                >
                  <ArrowLeft className="h-4 w-4" />
                  Back
                </button>
                <button
                  onClick={handleValidate}
                  disabled={!isMappingComplete || validating}
                  className="inline-flex items-center gap-2 px-5 py-2 bg-teal-600 text-white rounded-lg hover:bg-teal-700 disabled:opacity-50 disabled:cursor-not-allowed transition-colors text-sm font-medium"
                >
                  {validating ? <Loader2 className="h-4 w-4 animate-spin" /> : <ArrowRight className="h-4 w-4" />}
                  {validating ? 'Validating...' : 'Validate'}
                </button>
              </div>
            </div>
          )}

          {/* ── Step 3: Validation Results ─────────────────────────────── */}
          {step === 3 && summary && (
            <div className="space-y-6">
              {/* Summary cards */}
              <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
                {[
                  { label: 'Total Rows', value: summary.validations.length, color: 'text-[var(--ff-text-primary)]' },
                  { label: 'Valid', value: summary.validCount, color: 'text-green-400' },
                  { label: 'Warnings', value: summary.warningCount, color: 'text-amber-400' },
                  { label: 'Errors', value: summary.errorCount, color: 'text-red-400' },
                ].map(c => (
                  <div key={c.label} className="bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)] rounded-lg p-4 text-center">
                    <div className={`text-2xl font-bold ${c.color}`}>{c.value}</div>
                    <div className="text-xs text-[var(--ff-text-secondary)] mt-1">{c.label}</div>
                  </div>
                ))}
              </div>

              {/* Balance check */}
              <div className={`flex items-center gap-3 px-4 py-3 rounded-lg border ${
                summary.isBalanced
                  ? 'bg-green-500/10 border-green-500/20 text-green-400'
                  : 'bg-red-500/10 border-red-500/20 text-red-400'
              }`}>
                {summary.isBalanced
                  ? <CheckCircle2 className="h-5 w-5 flex-shrink-0" />
                  : <XCircle className="h-5 w-5 flex-shrink-0" />}
                <span className="text-sm font-medium">
                  {summary.isBalanced
                    ? `Balanced — Debit: R${summary.totalDebit.toLocaleString('en-ZA', { minimumFractionDigits: 2 })} / Credit: R${summary.totalCredit.toLocaleString('en-ZA', { minimumFractionDigits: 2 })}`
                    : `Out of balance — Debit: R${summary.totalDebit.toLocaleString('en-ZA', { minimumFractionDigits: 2 })} / Credit: R${summary.totalCredit.toLocaleString('en-ZA', { minimumFractionDigits: 2 })} (difference: R${Math.abs(summary.totalDebit - summary.totalCredit).toLocaleString('en-ZA', { minimumFractionDigits: 2 })})`}
                </span>
              </div>

              {/* Error / warning table */}
              {summary.validations.some(v => !v.valid || v.warnings.length > 0) && (
                <div className="bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)] rounded-lg overflow-hidden">
                  <div className="px-4 py-3 border-b border-[var(--ff-border-light)]">
                    <span className="text-sm font-medium text-[var(--ff-text-primary)]">Row-level issues</span>
                  </div>
                  <div className="overflow-x-auto max-h-72 overflow-y-auto">
                    <table className="w-full text-sm">
                      <thead className="sticky top-0 bg-[var(--ff-bg-secondary)]">
                        <tr className="border-b border-[var(--ff-border-light)]">
                          <th className="text-left px-4 py-2 text-[var(--ff-text-secondary)] font-medium">Row</th>
                          <th className="text-left px-4 py-2 text-[var(--ff-text-secondary)] font-medium">Type</th>
                          <th className="text-left px-4 py-2 text-[var(--ff-text-secondary)] font-medium">Message</th>
                        </tr>
                      </thead>
                      <tbody>
                        {summary.validations.flatMap(v => [
                          ...v.errors.map((e, i) => ({ row: v.row, type: 'error', msg: e, key: `e-${v.row}-${i}` })),
                          ...v.warnings.map((w, i) => ({ row: v.row, type: 'warning', msg: w, key: `w-${v.row}-${i}` })),
                        ]).map(item => (
                          <tr key={item.key} className="border-b border-[var(--ff-border-light)]/50">
                            <td className="px-4 py-2 text-[var(--ff-text-secondary)]">{item.row}</td>
                            <td className="px-4 py-2">
                              {item.type === 'error'
                                ? <span className="inline-flex items-center gap-1 text-red-400"><XCircle className="h-3 w-3" />Error</span>
                                : <span className="inline-flex items-center gap-1 text-amber-400"><AlertTriangle className="h-3 w-3" />Warning</span>}
                            </td>
                            <td className="px-4 py-2 text-[var(--ff-text-secondary)]">{item.msg}</td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                </div>
              )}

              <div className="flex items-center justify-between">
                <button
                  onClick={() => setStep(2)}
                  className="inline-flex items-center gap-2 px-4 py-2 border border-[var(--ff-border-light)] text-[var(--ff-text-secondary)] rounded-lg hover:bg-[var(--ff-bg-secondary)] transition-colors text-sm"
                >
                  <ArrowLeft className="h-4 w-4" />
                  Back
                </button>
                <button
                  disabled={summary.validCount === 0}
                  onClick={() => setStep(4)}
                  className="inline-flex items-center gap-2 px-5 py-2 bg-teal-600 text-white rounded-lg hover:bg-teal-700 disabled:opacity-50 disabled:cursor-not-allowed transition-colors text-sm font-medium"
                >
                  <ArrowRight className="h-4 w-4" />
                  Continue ({summary.validCount} valid rows)
                </button>
              </div>
            </div>
          )}

          {/* ── Step 4: Import ─────────────────────────────────────────── */}
          {step === 4 && (
            <div className="space-y-6">
              {!importResult ? (
                <>
                  <div className="bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)] rounded-lg p-6 space-y-4">
                    <h2 className="text-base font-semibold text-[var(--ff-text-primary)]">Import Summary</h2>
                    <div className="grid grid-cols-3 gap-4 text-center">
                      <div>
                        <div className="text-2xl font-bold text-[var(--ff-text-primary)]">{validRows.length}</div>
                        <div className="text-xs text-[var(--ff-text-secondary)]">Lines to import</div>
                      </div>
                      <div>
                        <div className="text-2xl font-bold text-teal-400">
                          R{summary!.totalDebit.toLocaleString('en-ZA', { minimumFractionDigits: 2 })}
                        </div>
                        <div className="text-xs text-[var(--ff-text-secondary)]">Total debit value</div>
                      </div>
                      <div>
                        <div className="text-2xl font-bold text-[var(--ff-text-primary)]">
                          {summary!.isBalanced ? 'Balanced' : 'Unbalanced'}
                        </div>
                        <div className="text-xs text-[var(--ff-text-secondary)]">Balance status</div>
                      </div>
                    </div>

                    <div className="border-t border-[var(--ff-border-light)] pt-4">
                      <p className="text-sm font-medium text-[var(--ff-text-primary)] mb-3">Posting option</p>
                      <div className="space-y-2">
                        {[
                          { value: false, label: 'Import as Draft', desc: 'Entries created as drafts — review and post manually' },
                          { value: true, label: 'Import and Post', desc: 'Entries immediately posted to the general ledger' },
                        ].map(opt => (
                          <label key={String(opt.value)} className="flex items-start gap-3 cursor-pointer">
                            <input
                              type="radio"
                              name="postMode"
                              checked={postImmediately === opt.value}
                              onChange={() => setPostImmediately(opt.value)}
                              className="mt-0.5 accent-teal-500"
                            />
                            <div>
                              <span className="text-sm font-medium text-[var(--ff-text-primary)]">{opt.label}</span>
                              <p className="text-xs text-[var(--ff-text-secondary)]">{opt.desc}</p>
                            </div>
                          </label>
                        ))}
                      </div>
                    </div>
                  </div>

                  {importError && (
                    <div className="flex items-center gap-2 text-red-400 text-sm bg-red-500/10 border border-red-500/20 rounded-lg px-4 py-3">
                      <XCircle className="h-4 w-4 flex-shrink-0" />
                      {importError}
                    </div>
                  )}

                  <div className="flex items-center justify-between">
                    <button
                      onClick={() => setStep(3)}
                      className="inline-flex items-center gap-2 px-4 py-2 border border-[var(--ff-border-light)] text-[var(--ff-text-secondary)] rounded-lg hover:bg-[var(--ff-bg-secondary)] transition-colors text-sm"
                    >
                      <ArrowLeft className="h-4 w-4" />
                      Back
                    </button>
                    <button
                      onClick={handleImport}
                      disabled={importing}
                      className="inline-flex items-center gap-2 px-6 py-2 bg-teal-600 text-white rounded-lg hover:bg-teal-700 disabled:opacity-50 disabled:cursor-not-allowed transition-colors text-sm font-medium"
                    >
                      {importing ? <Loader2 className="h-4 w-4 animate-spin" /> : <Upload className="h-4 w-4" />}
                      {importing ? 'Importing...' : `Import ${validRows.length} rows`}
                    </button>
                  </div>
                </>
              ) : (
                /* Success state */
                <div className="text-center py-12 space-y-6">
                  <div className="flex items-center justify-center">
                    <div className="p-4 rounded-full bg-green-500/10">
                      <CheckCircle2 className="h-12 w-12 text-green-400" />
                    </div>
                  </div>
                  <div>
                    <h2 className="text-xl font-bold text-[var(--ff-text-primary)] mb-2">Import Successful</h2>
                    <p className="text-[var(--ff-text-secondary)]">
                      {importResult.entriesCreated} journal {importResult.entriesCreated === 1 ? 'entry' : 'entries'} created
                      with {importResult.linesCreated} lines
                      totalling R{importResult.totalValue.toLocaleString('en-ZA', { minimumFractionDigits: 2 })}.
                    </p>
                  </div>
                  <div className="flex items-center justify-center gap-4">
                    <button
                      onClick={() => void router.push('/accounting/journal-entries')}
                      className="inline-flex items-center gap-2 px-5 py-2 bg-teal-600 text-white rounded-lg hover:bg-teal-700 transition-colors text-sm font-medium"
                    >
                      View Journal Entries
                    </button>
                    <button
                      onClick={() => {
                        setStep(1);
                        setRawHeaders([]); setRawRows([]); setFileName('');
                        setSummary(null); setValidRows([]); setImportResult(null);
                      }}
                      className="inline-flex items-center gap-2 px-5 py-2 border border-[var(--ff-border-light)] text-[var(--ff-text-secondary)] rounded-lg hover:bg-[var(--ff-bg-secondary)] transition-colors text-sm"
                    >
                      Import Another File
                    </button>
                  </div>
                </div>
              )}
            </div>
          )}

        </div>
      </div>
    </AppLayout>
  );
}

