```typescript
import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';

interface StorageStats {
  tableName: string;
  rowCount: number;
  oldestDate: string | null;
  newestDate: string | null;
}

interface ArchivePreview {
  journalEntries: number;
  journalLines: number;
  bankTransactions: number;
  customerInvoices: number;
  supplierInvoices: number;
  totalRecords: number;
}

// Get storage statistics per table
export async function getStorageStats(companyId: string): Promise<StorageStats[]>
// Query each table for COUNT(*), MIN(date), MAX(date) WHERE company_id

// Preview what would be archived
export async function previewArchive(companyId: string, cutoffDate: string): Promise<ArchivePreview>
// Count records per table WHERE date < cutoffDate AND company_id

// Validate archive is safe (all periods locked)
export async function validateArchive(companyId: string, cutoffDate: string): Promise<{
  valid: boolean;
  errors: string[];
}>
// Check: cutoff date must be at least 5 years ago
// Check: all fiscal periods before cutoff must be 'locked'
// Check: no pending/draft entries before cutoff

// Execute archive
export async function executeArchive(companyId: string, cutoffDate: string, userId: string): Promise<{
  runId: string;
  entriesArchived: number;
  linesArchived: number;
  transactionsArchived: number;
  invoicesArchived: number;
}>
// 1. Create archive_runs record with status='running'
// 2. INSERT INTO archive_gl_journal_entries SELECT * FROM gl_journal_entries WHERE company_id AND entry_date < cutoff AND status = 'posted'
// 3. INSERT INTO archive_gl_journal_lines SELECT jl.* FROM gl_journal_lines jl JOIN gl_journal_entries je ON ... WHERE je.company_id AND je.entry_date < cutoff
// 4. Same for bank_transactions, customer_invoices, supplier_invoices
// 5. DELETE from active tables (same WHERE clauses, in reverse order: lines first, then entries)
// 6. Update archive_runs with counts and status='completed'
// 7. On any error: update status='failed', set error_message

// Get archive run history
export async function getArchiveRuns(companyId: string): Promise<Array<{
  id: string; cutoffDate: string; status: string; entriesArchived: number; linesArchived: number;
  transactionsArchived: number; startedAt: string; completedAt: string | null;
}>>

// Query archived data (read-only)
export async function getArchivedEntries(companyId: string, filters: {
  dateFrom?: string; dateTo?: string; limit?: number; offset?: number;
}): Promise<{ items: unknown[]; total: number }>
```

