import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import crypto from 'crypto';

// Supported events
export const WEBHOOK_EVENTS = [
  'customer.created', 'customer.updated',
  'supplier.created', 'supplier.updated',
  'invoice.created', 'invoice.posted', 'invoice.paid',
  'payment.received', 'payment.made',
  'journal_entry.posted', 'journal_entry.reversed',
] as const;

// Fire webhook for an event (fire-and-forget, non-blocking)
export async function fireWebhook(companyId: string, event: string, payload: Record<string, unknown>): Promise<void>
// 1. Query webhook_endpoints WHERE company_id AND is_active AND event = ANY(events)
// 2. For each matching endpoint:
//    a. Generate HMAC-SHA256 signature: crypto.createHmac('sha256', secret).update(JSON.stringify(payload)).digest('hex')
//    b. POST to url with headers: X-Webhook-Signature, X-Webhook-Event, Content-Type: application/json
//    c. Record delivery in webhook_deliveries (success/failure, response status)
//    d. On failure: increment failure_count. If failure_count >= 10, set is_active = false
// 3. Use try/catch — never throw, never block caller
// 4. Use fetch() with timeout (5 seconds)

// CRUD for endpoints
