  };
}

// ── Note 3: Trade & Other Receivables ─────────────────────────────────────────

async function noteReceivables(companyId: string, fiscalYear: number): Promise<DisclosureNote> {
  const { end } = fiscalRange(fiscalYear);

  const rows = await sql`
    SELECT
      SUM(ci.total_amount) FILTER (WHERE ci.status NOT IN ('paid','cancelled','void')) AS gross_receivables,
      SUM(ci.total_amount) FILTER (
        WHERE ci.status NOT IN ('paid','cancelled','void')
          AND ci.due_date <= ${end}::date - INTERVAL '0 days'
          AND ci.due_date > ${end}::date - INTERVAL '30 days'
      ) AS current_amount,
      SUM(ci.total_amount) FILTER (
        WHERE ci.status NOT IN ('paid','cancelled','void')
          AND ci.due_date <= ${end}::date - INTERVAL '30 days'
          AND ci.due_date > ${end}::date - INTERVAL '60 days'
      ) AS days_30,
      SUM(ci.total_amount) FILTER (
        WHERE ci.status NOT IN ('paid','cancelled','void')
          AND ci.due_date <= ${end}::date - INTERVAL '60 days'
          AND ci.due_date > ${end}::date - INTERVAL '90 days'
      ) AS days_60,
      SUM(ci.total_amount) FILTER (
        WHERE ci.status NOT IN ('paid','cancelled','void')
          AND ci.due_date <= ${end}::date - INTERVAL '90 days'
      ) AS days_90_plus
    FROM customer_invoices ci
    WHERE ci.company_id = ${companyId}
      AND ci.invoice_date <= ${end}
  ` as Row[];

  const r = rows[0] ?? {};
  const gross = Number(r.gross_receivables) || 0;

  const tableHeaders = ['', 'Amount (R)'];
  const tableRows = [
    ['Gross trade receivables', fmt(gross)],
    ['Less: Provision for doubtful debts', fmt(0)],
    ['Net trade receivables', fmt(gross)],
  ];

  const agingHeaders = ['Current', '30 days', '60 days', '90+ days', 'Total'];
  const agingRows = [[
    fmt(r.current_amount),
    fmt(r.days_30),
    fmt(r.days_60),
    fmt(r.days_90_plus),
    fmt(gross),
  ]];

  const content = `Trade receivables are carried at original invoice amount less any provision for doubtful debts. The provision for doubtful debts is assessed at the reporting date based on objective evidence of impairment. All amounts are stated in Rands.`;

  return {
    noteNumber: 3,
    title: 'Trade and Other Receivables',
    content,
    tables: [
      { headers: tableHeaders, rows: tableRows },
      { headers: agingHeaders, rows: agingRows },
    ],
    source: 'auto',
  };
}

// ── Note 4: Trade & Other Payables ────────────────────────────────────────────

async function notePayables(companyId: string, fiscalYear: number): Promise<DisclosureNote> {
  const { end } = fiscalRange(fiscalYear);

  const rows = await sql`
    SELECT
      SUM(si.total_amount) FILTER (WHERE si.status NOT IN ('paid','cancelled','void')) AS gross_payables,
      SUM(si.total_amount) FILTER (
        WHERE si.status NOT IN ('paid','cancelled','void')
          AND si.due_date <= ${end}::date
          AND si.due_date > ${end}::date - INTERVAL '30 days'
      ) AS current_amount,
      SUM(si.total_amount) FILTER (
        WHERE si.status NOT IN ('paid','cancelled','void')
          AND si.due_date <= ${end}::date - INTERVAL '30 days'
          AND si.due_date > ${end}::date - INTERVAL '60 days'
