/**
 * Custom Report Builder Service — WS-7.1
 * All SQL is parameterized. Column/field names come only from the whitelist in customReportFieldDefs.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import {
  getAvailableFields,
  getFieldDef,
  getBaseQuery,
  getCompanyAlias,
  type FieldDef,
} from './customReportFieldDefs';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = Record<string, any>;

export interface ReportColumn {
  field: string;
  label?: string;
  width?: number;
}

export interface ReportFilter {
  field: string;
  operator: 'equals' | 'not_equals' | 'contains' | 'starts_with' |
    'greater_than' | 'less_than' | 'between' | 'in' | 'is_null' | 'is_not_null';
  value?: string | number;
  value2?: string | number; // for 'between'
}

export interface ReportSort {
  field: string;
  direction: 'asc' | 'desc';
}

export interface ReportConfig {
  dataSource: string;
  columns: ReportColumn[];
  filters?: ReportFilter[];
  sortBy?: ReportSort[];
  groupBy?: string[];
  limit?: number;
  offset?: number;
}

export interface ReportTemplate {
  id: string;
  companyId: string;
  createdBy: string;
  name: string;
  description: string | null;
  dataSource: string;
  columns: ReportColumn[];
  filters: ReportFilter[];
  sortBy: ReportSort[];
  groupBy: string[];
  totals: Record<string, boolean>;
  layoutOptions: Record<string, unknown>;
  isShared: boolean;
  schedule: unknown | null;
  createdAt: Date | string;
  updatedAt: Date | string;
}

export interface TemplateInput {
  id?: string;
  name: string;
  description?: string;
  dataSource: string;
  columns: ReportColumn[];
  filters?: ReportFilter[];
  sortBy?: ReportSort[];
  groupBy?: string[];
  totals?: Record<string, boolean>;
  layoutOptions?: Record<string, unknown>;
  isShared?: boolean;
  schedule?: unknown;
}

export interface RunResult {
  columns: Array<{ field: string; label: string; type: string }>;
  rows: Row[];
  totals: Record<string, number>;
  rowCount: number;
}

// Re-export for API layer
export { getAvailableFields };

// ─── CRUD ────────────────────────────────────────────────────────────────────

export async function getTemplates(companyId: string, userId: string): Promise<ReportTemplate[]> {
  const rows = await sql`
    SELECT id, company_id, created_by, name, description, data_source,
      columns, filters, sort_by, group_by, totals, layout_options,
      is_shared, schedule, created_at, updated_at
    FROM custom_report_templates
    WHERE company_id = ${companyId}
      AND (created_by = ${userId} OR is_shared = true)
    ORDER BY updated_at DESC
  `;
  return rows.map(mapTemplate);
}

export async function getTemplateById(companyId: string, id: string): Promise<ReportTemplate | null> {
  const rows = await sql`
    SELECT id, company_id, created_by, name, description, data_source,
      columns, filters, sort_by, group_by, totals, layout_options,
      is_shared, schedule, created_at, updated_at
    FROM custom_report_templates
    WHERE company_id = ${companyId} AND id = ${id}
  `;
  if (!rows[0]) return null;
  return mapTemplate(rows[0]);
}

export async function saveTemplate(
  companyId: string,
  userId: string,
  input: TemplateInput,
): Promise<ReportTemplate> {
  const cols = JSON.stringify(input.columns ?? []);
  const filters = JSON.stringify(input.filters ?? []);
  const sortBy = JSON.stringify(input.sortBy ?? []);
  const groupBy = JSON.stringify(input.groupBy ?? []);
  const totals = JSON.stringify(input.totals ?? {});
  const layout = JSON.stringify(input.layoutOptions ?? {});
  const schedule = input.schedule ? JSON.stringify(input.schedule) : null;
  const isShared = input.isShared ?? false;

  if (input.id) {
    // Update — verify ownership
    const existing = await getTemplateById(companyId, input.id);
    if (!existing) throw new Error('Template not found');
    if (existing.createdBy !== userId) throw new Error('You do not own this template');

    const rows = await sql`
      UPDATE custom_report_templates SET
        name = ${input.name},
        description = ${input.description ?? null},
        data_source = ${input.dataSource},
        columns = ${cols}::jsonb,
        filters = ${filters}::jsonb,
        sort_by = ${sortBy}::jsonb,
        group_by = ${groupBy}::jsonb,
        totals = ${totals}::jsonb,
        layout_options = ${layout}::jsonb,
        is_shared = ${isShared},
        schedule = ${schedule ? schedule + '::jsonb' : null},
        updated_at = NOW()
      WHERE company_id = ${companyId} AND id = ${input.id}
      RETURNING *
    `;
    log.info('Custom report template updated', { id: input.id, companyId }, 'CustomReportService');
    return mapTemplate(rows[0]);
  }

  const rows = await sql`
    INSERT INTO custom_report_templates
      (company_id, created_by, name, description, data_source, columns, filters,
       sort_by, group_by, totals, layout_options, is_shared, schedule)
    VALUES (
      ${companyId}, ${userId}, ${input.name}, ${input.description ?? null},
      ${input.dataSource}, ${cols}::jsonb, ${filters}::jsonb,
      ${sortBy}::jsonb, ${groupBy}::jsonb, ${totals}::jsonb, ${layout}::jsonb,
      ${isShared}, ${schedule ? schedule + '::jsonb' : null}
    )
    RETURNING *
  `;
  log.info('Custom report template created', { id: rows[0].id, companyId }, 'CustomReportService');
  return mapTemplate(rows[0]);
}

export async function deleteTemplate(companyId: string, userId: string, id: string): Promise<void> {
  const existing = await getTemplateById(companyId, id);
  if (!existing) throw new Error('Template not found');
  if (existing.createdBy !== userId) throw new Error('You do not own this template');

  await sql`
    DELETE FROM custom_report_templates
    WHERE company_id = ${companyId} AND id = ${id}
  `;
  log.info('Custom report template deleted', { id, companyId }, 'CustomReportService');
}

// ─── QUERY RUNNER ────────────────────────────────────────────────────────────

export async function runReport(companyId: string, config: ReportConfig): Promise<RunResult> {
  const { dataSource, columns, filters = [], sortBy = [], limit = 500, offset = 0 } = config;

  const fields = getAvailableFields(dataSource);
  if (!fields.length) throw new Error(`Unknown data source: ${dataSource}`);

  // Validate & resolve selected columns against whitelist
  const selectedFields = columns
    .map(c => getFieldDef(dataSource, c.field))
    .filter((f): f is FieldDef => f !== undefined);

  if (!selectedFields.length) throw new Error('No valid columns selected');

  const alias = getCompanyAlias(dataSource);
  const baseQuery = getBaseQuery(dataSource);

  // Build SELECT clause from whitelisted sql expressions only
  const selectParts = selectedFields.map(f => `${f.sqlExpr} AS "${f.field}"`).join(', ');

  // Build parameterized WHERE clause
  const params: (string | number | null)[] = [companyId];
  let paramIdx = 2;
  const whereParts: string[] = [`${alias}.company_id = $1`];

  for (const filter of filters) {
    const fd = getFieldDef(dataSource, filter.field);
    if (!fd || !fd.filterable) continue;

    const expr = fd.sqlExpr;
    switch (filter.operator) {
      case 'equals':
        whereParts.push(`${expr} = $${paramIdx++}`);
        params.push(filter.value ?? null);
        break;
      case 'not_equals':
        whereParts.push(`${expr} != $${paramIdx++}`);
        params.push(filter.value ?? null);
        break;
      case 'contains':
        whereParts.push(`${expr}::text ILIKE $${paramIdx++}`);
        params.push(`%${filter.value ?? ''}%`);
        break;
      case 'starts_with':
        whereParts.push(`${expr}::text ILIKE $${paramIdx++}`);
        params.push(`${filter.value ?? ''}%`);
        break;
      case 'greater_than':
        whereParts.push(`${expr} > $${paramIdx++}`);
        params.push(filter.value ?? null);
        break;
      case 'less_than':
        whereParts.push(`${expr} < $${paramIdx++}`);
        params.push(filter.value ?? null);
        break;
      case 'between':
        whereParts.push(`${expr} BETWEEN $${paramIdx++} AND $${paramIdx++}`);
        params.push(filter.value ?? null, filter.value2 ?? null);
        break;
      case 'in': {
        const vals = String(filter.value ?? '').split(',').map(v => v.trim()).filter(Boolean);
        if (vals.length) {
          const placeholders = vals.map(() => `$${paramIdx++}`).join(', ');
          whereParts.push(`${expr} IN (${placeholders})`);
          params.push(...vals);
        }
        break;
      }
      case 'is_null':
        whereParts.push(`${expr} IS NULL`);
        break;
      case 'is_not_null':
        whereParts.push(`${expr} IS NOT NULL`);
        break;
    }
  }

  const whereClause = whereParts.join(' AND ');

  // Build ORDER BY from whitelisted fields only
  const orderParts = sortBy
    .map(s => {
      const fd = getFieldDef(dataSource, s.field);
      if (!fd || !fd.sortable) return null;
      const dir = s.direction === 'desc' ? 'DESC' : 'ASC';
      return `${fd.sqlExpr} ${dir}`;
    })
    .filter(Boolean);
  const orderClause = orderParts.length ? `ORDER BY ${orderParts.join(', ')}` : '';

  const limitVal = Math.min(Math.max(1, Number(limit) || 500), 5000);
  const offsetVal = Math.max(0, Number(offset) || 0);

  // Build final SQL string — only whitelisted sqlExpr values are interpolated
  const querySql = `
    SELECT ${selectParts}
    ${baseQuery}
    WHERE ${whereClause}
    ${orderClause}
    LIMIT ${limitVal} OFFSET ${offsetVal}
  `;

  // Count query for rowCount
  const countSql = `
    SELECT COUNT(*) AS total
    ${baseQuery}
    WHERE ${whereClause}
  `;

  // Execute using parameterized query via Neon's query() method
  // We must use raw query here because we're building dynamic SQL from whitelisted expressions
  const neonClient = (await import('@neondatabase/serverless')).neon(process.env.DATABASE_URL!);

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const [dataRows, countRows] = await Promise.all([
    neonClient.query(querySql, params as string[]),
    neonClient.query(countSql, params as string[]),
  ]);

  const rows = (dataRows.rows ?? dataRows) as Row[];
  const rowCount = Number((countRows.rows ?? countRows)[0]?.total ?? rows.length);

  // Compute totals for totalable fields
  const totals: Record<string, number> = {};
  for (const f of selectedFields) {
    if (f.totalable) {
      totals[f.field] = rows.reduce((sum, r) => sum + (Number(r[f.field]) || 0), 0);
    }
  }

  const resultColumns = selectedFields.map(f => ({
    field: f.field,
    label: columns.find(c => c.field === f.field)?.label ?? f.label,
    type: f.type,
  }));

  log.info('Custom report executed', { dataSource, rowCount, companyId }, 'CustomReportService');

  return { columns: resultColumns, rows, totals, rowCount };
}

// ─── Helpers ─────────────────────────────────────────────────────────────────

function mapTemplate(r: Row): ReportTemplate {
  return {
    id: String(r.id),
    companyId: String(r.company_id),
    createdBy: String(r.created_by),
    name: String(r.name),
    description: r.description ? String(r.description) : null,
    dataSource: String(r.data_source),
    columns: (r.columns ?? []) as ReportColumn[],
    filters: (r.filters ?? []) as ReportFilter[],
    sortBy: (r.sort_by ?? []) as ReportSort[],
    groupBy: (r.group_by ?? []) as string[],
    totals: (r.totals ?? {}) as Record<string, boolean>,
    layoutOptions: (r.layout_options ?? {}) as Record<string, unknown>,
    isShared: Boolean(r.is_shared),
    schedule: r.schedule ?? null,
    createdAt: r.created_at,
    updatedAt: r.updated_at,
  };
}

