          <div className="px-6 py-4 flex items-center justify-between">
            <div className="flex items-center gap-3">
              <div className="p-2 rounded-lg bg-teal-500/10">
                <Webhook className="h-6 w-6 text-teal-500" />
              </div>
              <div>
                <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">Webhooks</h1>
                <p className="text-sm text-[var(--ff-text-secondary)]">
                  Send real-time events to external systems
                </p>
              </div>
            </div>
            <button onClick={() => { setShowForm(true); setEditId(null); setForm(DEFAULT_FORM); }} className={BTN_PRIMARY}>
              <Plus className="h-4 w-4" /> Add Webhook
            </button>
          </div>
        </div>

        <div className="px-6 py-6 space-y-4">
          {error && (
            <div className="flex items-center gap-2 p-3 bg-red-500/10 border border-red-500/30 rounded-lg text-red-400 text-sm">
              <AlertCircle className="h-4 w-4 flex-shrink-0" /> {error}
            </div>
          )}

          {/* Add/Edit Form */}
          {showForm && (
            <div className="bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)] rounded-lg p-5">
              <h2 className="text-base font-semibold text-[var(--ff-text-primary)] mb-4">
                {editId ? 'Edit Webhook' : 'New Webhook'}
              </h2>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 mb-4">
                <div>
                  <label className="block text-xs font-medium text-[var(--ff-text-secondary)] mb-1">Name</label>
                  <input className={INPUT_CLS} placeholder="e.g. Slack Notifications" value={form.name} onChange={e => setForm(p => ({ ...p, name: e.target.value }))} />
                </div>
                <div>
                  <label className="block text-xs font-medium text-[var(--ff-text-secondary)] mb-1">Endpoint URL</label>
                  <input className={INPUT_CLS} placeholder="https://example.com/webhook" value={form.url} onChange={e => setForm(p => ({ ...p, url: e.target.value }))} />
                </div>
                <div>
                  <label className="block text-xs font-medium text-[var(--ff-text-secondary)] mb-1">
                    Secret (HMAC-SHA256)
                  </label>
                  <div className="flex gap-2">
                    <input className={INPUT_CLS} placeholder="Leave blank for none" value={form.secret} onChange={e => setForm(p => ({ ...p, secret: e.target.value }))} />
                    <button type="button" onClick={() => setForm(p => ({ ...p, secret: generateSecret() }))} className={BTN_GHOST} title="Generate secret">
                      <RefreshCw className="h-3.5 w-3.5" />
                    </button>
                    {form.secret && (
                      <button type="button" onClick={() => void navigator.clipboard.writeText(form.secret)} className={BTN_GHOST} title="Copy secret">
                        <Copy className="h-3.5 w-3.5" />
                      </button>
                    )}
                  </div>
                </div>
                <div className="flex items-center gap-3 pt-5">
                  <input type="checkbox" id="isActive" checked={form.isActive} onChange={e => setForm(p => ({ ...p, isActive: e.target.checked }))} className="w-4 h-4 accent-teal-500" />
                  <label htmlFor="isActive" className="text-sm text-[var(--ff-text-primary)]">Active</label>
                </div>
              </div>
              <div className="mb-4">
                <label className="block text-xs font-medium text-[var(--ff-text-secondary)] mb-2">Events to subscribe</label>
                <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-4 gap-2">
                  {WEBHOOK_EVENTS.map(ev => (
                    <label key={ev} className="flex items-center gap-2 text-sm text-[var(--ff-text-primary)] cursor-pointer">
                      <input type="checkbox" checked={form.events.includes(ev)} onChange={() => handleToggleEvent(ev)} className="accent-teal-500" />
                      <span className="font-mono text-xs">{ev}</span>
                    </label>
                  ))}
                </div>
              </div>
              <div className="flex gap-2">
                <button onClick={() => void handleSave()} disabled={saving} className={BTN_PRIMARY}>
                  {saving ? <Loader2 className="h-4 w-4 animate-spin" /> : null}
                  {saving ? 'Saving...' : 'Save'}
                </button>
                <button onClick={() => { setShowForm(false); setEditId(null); setForm(DEFAULT_FORM); }} className={BTN_GHOST}>
                  Cancel
                </button>
              </div>
            </div>
          )}

          {/* Webhook List */}
          {loading ? (
            <div className="flex justify-center py-12"><Loader2 className="h-6 w-6 animate-spin text-teal-500" /></div>
          ) : webhooks.length === 0 ? (
            <div className="text-center py-16 text-[var(--ff-text-secondary)]">
              <Webhook className="h-12 w-12 mx-auto mb-3 opacity-30" />
              <p className="font-medium">No webhooks configured</p>
              <p className="text-sm mt-1">Add a webhook to receive real-time event notifications.</p>
            </div>
          ) : (
            <div className="space-y-3">
              {webhooks.map(wh => (
                <div key={wh.id} className="bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)] rounded-lg overflow-hidden">
                  {/* Card Header */}
                  <div className="px-5 py-4 flex items-center gap-4">
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-2">
                        <span className="font-semibold text-[var(--ff-text-primary)]">{wh.name}</span>
                        <span className={`text-xs px-2 py-0.5 rounded-full font-medium ${wh.isActive ? 'bg-green-500/15 text-green-400' : 'bg-red-500/15 text-red-400'}`}>
                          {wh.isActive ? 'Active' : 'Disabled'}
                        </span>
                        {wh.failureCount > 0 && (
                          <span className="text-xs px-2 py-0.5 rounded-full bg-yellow-500/15 text-yellow-400 font-medium">
                            {wh.failureCount} failure{wh.failureCount !== 1 ? 's' : ''}
                          </span>
                        )}
                      </div>
                      <p className="text-sm text-[var(--ff-text-secondary)] truncate mt-0.5">
                        {wh.url.replace(/^(https?:\/\/[^/]+).*$/, '$1/***')}
                      </p>
                      <div className="flex flex-wrap gap-1 mt-1.5">
                        {wh.events.map(ev => (
                          <span key={ev} className="text-xs font-mono px-1.5 py-0.5 bg-teal-500/10 text-teal-400 rounded">
                            {ev}
                          </span>
                        ))}
                      </div>
                    </div>
                    <div className="flex items-center gap-2 flex-shrink-0">
                      {testResults[wh.id] && (
                        <span className={`text-xs font-medium ${testResults[wh.id]!.success ? 'text-green-400' : 'text-red-400'}`}>
                          {testResults[wh.id]!.success ? `OK ${testResults[wh.id]!.status}` : `Fail ${testResults[wh.id]!.status}`}
                        </span>
                      )}
                      <button onClick={() => void handleTest(wh.id)} disabled={testing === wh.id} className={BTN_GHOST} title="Test">
                        {testing === wh.id ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <Play className="h-3.5 w-3.5" />}
                        Test
                      </button>
                      <button onClick={() => handleEdit(wh)} className={BTN_GHOST}>Edit</button>
                      <button onClick={() => void handleDelete(wh.id)} className="p-1.5 text-red-400 hover:bg-red-500/10 rounded-lg transition-colors">
                        <Trash2 className="h-4 w-4" />
                      </button>
                      <button onClick={() => toggleExpand(wh.id)} className="p-1.5 text-[var(--ff-text-secondary)] hover:bg-[var(--ff-bg-primary)] rounded-lg transition-colors">
                        {expandedId === wh.id ? <ChevronUp className="h-4 w-4" /> : <ChevronDown className="h-4 w-4" />}
                      </button>
                    </div>
                  </div>

                  {/* Delivery Log */}
                  {expandedId === wh.id && (
                    <div className="border-t border-[var(--ff-border-light)] px-5 py-4">
                      <h3 className="text-sm font-semibold text-[var(--ff-text-secondary)] mb-3">Delivery Log</h3>
                      {!deliveries[wh.id] ? (
                        <div className="flex justify-center py-4"><Loader2 className="h-4 w-4 animate-spin text-teal-500" /></div>
                      ) : deliveries[wh.id]!.length === 0 ? (
                        <p className="text-sm text-[var(--ff-text-secondary)] py-2">No deliveries yet.</p>
                      ) : (
                        <div className="overflow-x-auto">
                          <table className="w-full text-sm">
                            <thead>
                              <tr className="text-xs text-[var(--ff-text-secondary)] border-b border-[var(--ff-border-light)]">
                                <th className="text-left py-2 pr-4">Date</th>
                                <th className="text-left py-2 pr-4">Event</th>
                                <th className="text-left py-2 pr-4">Status</th>
                                <th className="text-left py-2">Result</th>
                              </tr>
                            </thead>
                            <tbody>
                              {deliveries[wh.id]!.map(d => (
                                <tr key={d.id} className="border-b border-[var(--ff-border-light)] last:border-0">
                                  <td className="py-2 pr-4 text-[var(--ff-text-secondary)] whitespace-nowrap">
                                    {new Date(d.deliveredAt).toLocaleString('en-ZA')}
                                  </td>
                                  <td className="py-2 pr-4 font-mono text-xs text-[var(--ff-text-primary)]">{d.event}</td>
                                  <td className="py-2 pr-4 text-[var(--ff-text-secondary)]">{d.responseStatus ?? '—'}</td>
                                  <td className="py-2">
                                    {d.success
                                      ? <span className="flex items-center gap-1 text-green-400 text-xs"><CheckCircle className="h-3.5 w-3.5" /> OK</span>
                                      : <span className="flex items-center gap-1 text-red-400 text-xs"><XCircle className="h-3.5 w-3.5" /> Failed</span>
                                    }
                                  </td>
                                </tr>
                              ))}
                            </tbody>
                          </table>
                        </div>
                      )}
                    </div>
                  )}
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    </AppLayout>
  );
}

