        ...(editId ? { id: editId } : {}),
      };
      await apiFetch('/api/accounting/recurring-transactions', {
        method: editId ? 'PUT' : 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(input),
      });
      setShowModal(false);
      await fetchTemplates();
    } catch (err) {
      log.error('Failed to save recurring template', { error: err }, 'recurring-page');
      setFormError('Failed to save template');
    } finally {
      setSaving(false);
    }
  };

  const handleDelete = async (id: string) => {
    if (!confirm('Delete this recurring template?')) return;
    try {
      await apiFetch(`/api/accounting/recurring-transactions?id=${id}`, { method: 'DELETE' });
      await fetchTemplates();
    } catch (err) {
      log.error('Failed to delete template', { error: err }, 'recurring-page');
    }
  };

  const handleRunNow = async (id: string) => {
    setExecuting(id);
    try {
      const res = await apiFetch('/api/accounting/recurring-transactions-execute', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ templateId: id }),
      });
      const json = await res.json() as { data: ExecuteResult };
      setExecResults(prev => ({ ...prev, [id]: json.data }));
      await fetchTemplates();
    } catch (err) {
      log.error('Failed to execute recurring template', { error: err }, 'recurring-page');
      setExecResults(prev => ({ ...prev, [id]: 'error' }));
    } finally {
      setExecuting(null);
    }
  };

  if (!isMounted) {
    return (
      <AppLayout>
        <div className="min-h-screen bg-[var(--ff-bg-primary)] flex items-center justify-center">
          <Loader2 className="h-8 w-8 animate-spin text-teal-500" />
        </div>
      </AppLayout>
    );
  }

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        {/* Header */}
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)]">
          <div className="px-6 py-4 flex items-center justify-between">
            <div className="flex items-center gap-3">
              <div className="p-2 rounded-lg bg-teal-500/10">
                <RefreshCw className="h-6 w-6 text-teal-500" />
              </div>
              <div>
                <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">Recurring Transactions</h1>
                <p className="text-sm text-[var(--ff-text-secondary)]">
                  Automate repeating journals, invoices, and more
                </p>
              </div>
            </div>
            <button onClick={openCreate} className={BTN_PRIMARY}>
              <Plus className="h-4 w-4" /> New Template
            </button>
          </div>
        </div>

        <div className="px-6 py-6">
          {error && (
            <div className="flex items-center gap-2 p-3 mb-4 bg-red-500/10 border border-red-500/30 rounded-lg text-red-400 text-sm">
              <AlertCircle className="h-4 w-4 flex-shrink-0" /> {error}
            </div>
          )}

          {/* Template Table */}
          {loading ? (
            <div className="flex justify-center py-12"><Loader2 className="h-6 w-6 animate-spin text-teal-500" /></div>
          ) : templates.length === 0 ? (
            <div className="text-center py-16 text-[var(--ff-text-secondary)]">
              <Calendar className="h-12 w-12 mx-auto mb-3 opacity-30" />
              <p className="font-medium">No recurring templates</p>
              <p className="text-sm mt-1">Create a template to automate repeating transactions.</p>
            </div>
          ) : (
            <div className="bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)] rounded-lg overflow-hidden">
              <div className="overflow-x-auto">
                <table className="w-full text-sm">
                  <thead className="border-b border-[var(--ff-border-light)]">
                    <tr className="text-xs text-[var(--ff-text-secondary)]">
                      <th className="text-left px-5 py-3">Name</th>
                      <th className="text-left px-4 py-3">Type</th>
                      <th className="text-left px-4 py-3">Frequency</th>
                      <th className="text-left px-4 py-3">Next Run</th>
                      <th className="text-left px-4 py-3">Last Run</th>
                      <th className="text-left px-4 py-3">Status</th>
                      <th className="text-right px-5 py-3">Actions</th>
                    </tr>
                  </thead>
                  <tbody>
                    {templates.map(t => {
                      const execResult = execResults[t.id];
                      return (
                        <tr key={t.id} className="border-b border-[var(--ff-border-light)] last:border-0 hover:bg-[var(--ff-bg-primary)] transition-colors">
                          <td className="px-5 py-3 font-medium text-[var(--ff-text-primary)]">{t.name}</td>
                          <td className="px-4 py-3 text-[var(--ff-text-secondary)]">
                            {ENTITY_LABELS[t.entityType]}
                          </td>
                          <td className="px-4 py-3 text-[var(--ff-text-secondary)]">
                            {FREQ_LABELS[t.frequency]}
                          </td>
                          <td className="px-4 py-3 text-[var(--ff-text-secondary)]">
                            {t.nextRunDate ? new Date(t.nextRunDate).toLocaleDateString('en-ZA') : '—'}
                          </td>
                          <td className="px-4 py-3 text-[var(--ff-text-secondary)]">
                            {t.lastRunDate ? new Date(t.lastRunDate).toLocaleDateString('en-ZA') : '—'}
                          </td>
                          <td className="px-4 py-3">
                            <span className={`text-xs px-2 py-0.5 rounded-full font-medium ${t.isActive ? 'bg-green-500/15 text-green-400' : 'bg-gray-500/15 text-gray-400'}`}>
                              {t.isActive ? 'Active' : 'Paused'}
                            </span>
                            {t.autoPost && (
                              <span className="ml-1.5 text-xs px-2 py-0.5 rounded-full bg-blue-500/15 text-blue-400 font-medium">
                                Auto-post
                              </span>
                            )}
                          </td>
                          <td className="px-5 py-3">
                            <div className="flex items-center justify-end gap-2">
                              {execResult && execResult !== 'error' && (
                                <span className="flex items-center gap-1 text-xs text-green-400">
                                  <CheckCircle className="h-3.5 w-3.5" /> Created
                                </span>
                              )}
                              {execResult === 'error' && (
                                <span className="flex items-center gap-1 text-xs text-red-400">
                                  <XCircle className="h-3.5 w-3.5" /> Failed
                                </span>
                              )}
                              <button onClick={() => void handleRunNow(t.id)} disabled={executing === t.id || !t.isActive} className={BTN_GHOST} title="Run now">
                                {executing === t.id ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <Play className="h-3.5 w-3.5" />}
                                Run Now
                              </button>
                              <button onClick={() => openEdit(t)} className={BTN_GHOST}>
                                <Edit2 className="h-3.5 w-3.5" />
                              </button>
                              <button onClick={() => void handleDelete(t.id)} className="p-1.5 text-red-400 hover:bg-red-500/10 rounded-lg transition-colors">
                                <Trash2 className="h-4 w-4" />
                              </button>
                            </div>
                          </td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              </div>
            </div>
          )}
        </div>
      </div>

      {/* Modal */}
      {showModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4">
          <div className="bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)] rounded-xl w-full max-w-2xl max-h-[90vh] overflow-y-auto">
            <div className="px-6 py-4 border-b border-[var(--ff-border-light)] flex items-center justify-between">
              <h2 className="text-base font-semibold text-[var(--ff-text-primary)]">
                {editId ? 'Edit Template' : 'New Recurring Template'}
              </h2>
              <button onClick={() => setShowModal(false)} className="text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] transition-colors text-xl leading-none">&times;</button>
            </div>
            <div className="px-6 py-5 space-y-4">
              {formError && (
                <div className="flex items-center gap-2 p-3 bg-red-500/10 border border-red-500/30 rounded-lg text-red-400 text-sm">
                  <AlertCircle className="h-4 w-4 flex-shrink-0" /> {formError}
                </div>
              )}
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div className="sm:col-span-2">
                  <label className="block text-xs font-medium text-[var(--ff-text-secondary)] mb-1">Name</label>
                  <input className={INPUT_CLS} placeholder="e.g. Monthly Rent Expense" value={form.name} onChange={e => setForm(p => ({ ...p, name: e.target.value }))} />
                </div>
                <div>
                  <label className="block text-xs font-medium text-[var(--ff-text-secondary)] mb-1">Entity Type</label>
                  <select className={INPUT_CLS} value={form.entityType} onChange={e => setForm(p => ({ ...p, entityType: e.target.value as EntityType }))}>
                    {(Object.keys(ENTITY_LABELS) as EntityType[]).map(k => (
                      <option key={k} value={k}>{ENTITY_LABELS[k]}</option>
                    ))}
                  </select>
                </div>
                <div>
                  <label className="block text-xs font-medium text-[var(--ff-text-secondary)] mb-1">Frequency</label>
                  <select className={INPUT_CLS} value={form.frequency} onChange={e => setForm(p => ({ ...p, frequency: e.target.value as Frequency }))}>
                    {(Object.keys(FREQ_LABELS) as Frequency[]).map(k => (
                      <option key={k} value={k}>{FREQ_LABELS[k]}</option>
                    ))}
                  </select>
                </div>
                <div>
                  <label className="block text-xs font-medium text-[var(--ff-text-secondary)] mb-1">Next Run Date</label>
                  <input type="date" className={INPUT_CLS} value={form.nextRunDate} onChange={e => setForm(p => ({ ...p, nextRunDate: e.target.value }))} />
                </div>
                <div className="flex items-center gap-6 pt-5">
                  <label className="flex items-center gap-2 text-sm text-[var(--ff-text-primary)] cursor-pointer">
                    <input type="checkbox" checked={form.isActive} onChange={e => setForm(p => ({ ...p, isActive: e.target.checked }))} className="accent-teal-500" />
                    Active
                  </label>
                  <label className="flex items-center gap-2 text-sm text-[var(--ff-text-primary)] cursor-pointer">
                    <input type="checkbox" checked={form.autoPost} onChange={e => setForm(p => ({ ...p, autoPost: e.target.checked }))} className="accent-teal-500" />
                    Auto-post
                  </label>
                </div>
                <div className="sm:col-span-2">
                  <label className="block text-xs font-medium text-[var(--ff-text-secondary)] mb-1">
                    Template Data (JSON)
                  </label>
                  <textarea
                    className={`${INPUT_CLS} font-mono min-h-[120px] resize-y`}
                    placeholder='{"lines": [], "description": "..."}'
                    value={form.templateData}
                    onChange={e => setForm(p => ({ ...p, templateData: e.target.value }))}
                  />
                  <p className="text-xs text-[var(--ff-text-secondary)] mt-1">
                    For journal entries: include <code className="font-mono">lines</code> array. For invoices: include <code className="font-mono">clientId</code>/<code className="font-mono">supplierId</code>, <code className="font-mono">lines</code>, amounts.
                  </p>
                </div>
              </div>
            </div>
            <div className="px-6 py-4 border-t border-[var(--ff-border-light)] flex gap-2">
              <button onClick={() => void handleSave()} disabled={saving} className={BTN_PRIMARY}>
                {saving ? <Loader2 className="h-4 w-4 animate-spin" /> : null}
                {saving ? 'Saving...' : 'Save Template'}
              </button>
              <button onClick={() => setShowModal(false)} className={BTN_GHOST}>Cancel</button>
            </div>
          </div>
        </div>
      )}
    </AppLayout>
  );
}

