                <th className="px-4 py-2">Date</th>
                <th className="px-4 py-2">VAT Type</th>
                <th className="px-4 py-2 text-right">Excl. VAT</th>
                <th className="px-4 py-2 text-right">VAT</th>
              </tr>
            </thead>
            <tbody>
              {invoices.length === 0 && (
                <tr>
                  <td colSpan={6} className="px-4 py-4 text-center text-[var(--ff-text-tertiary)]">
                    No invoices for this period.
                  </td>
                </tr>
              )}
              {invoices.map((inv) => (
                <tr key={inv.id} className="border-b border-[var(--ff-border-light)] hover:bg-[var(--ff-bg-primary)]/50">
                  <td className="px-4 py-2 text-[var(--ff-text-primary)] font-medium">{inv.invoiceNumber}</td>
                  <td className="px-4 py-2 text-[var(--ff-text-secondary)]">{inv.counterpartyName}</td>
                  <td className="px-4 py-2 text-[var(--ff-text-secondary)]">{formatDate(inv.invoiceDate)}</td>
                  <td className="px-4 py-2">
                    <span className="inline-flex px-2 py-0.5 rounded text-xs font-medium bg-teal-500/10 text-teal-400">
                      {inv.vatType}
                    </span>
                  </td>
                  <td className="px-4 py-2 text-right text-[var(--ff-text-primary)]">{fmt(inv.totalExclVat)}</td>
                  <td className="px-4 py-2 text-right text-teal-400 font-medium">{fmt(inv.vatAmount)}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

file.content:
/**
 * SARS VAT201 API
 * GET  ?from=YYYY-MM-DD&to=YYYY-MM-DD — generate VAT201 data for period
 * POST { periodStart, periodEnd }     — save as draft submission
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import {
  generateVAT201,
  saveDraftSubmission,
} from '@/modules/accounting/services/sarsService';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  const { companyId } = req as CompanyApiRequest;
  const userId = (req as AuthenticatedNextApiRequest).user.id;

  if (req.method === 'GET') {
    const from = req.query.from as string;
    const to = req.query.to as string;

    if (!from || !to) {
      return apiResponse.badRequest(res, 'from and to query parameters are required (YYYY-MM-DD)');
    }

    try {
      const vat201 = await generateVAT201(companyId, from, to);
      return apiResponse.success(res, vat201);
    } catch (err) {
      log.error('Failed to generate VAT201', { error: err }, 'sars-api');
      return apiResponse.badRequest(res, err instanceof Error ? err.message : 'Failed to generate VAT201');
    }
  }

  if (req.method === 'POST') {
    const { periodStart, periodEnd } = req.body;

    if (!periodStart || !periodEnd) {
      return apiResponse.badRequest(res, 'periodStart and periodEnd are required');
    }

    try {
      const vat201 = await generateVAT201(companyId, periodStart, periodEnd);
      const submission = await saveDraftSubmission(
        companyId,
        'VAT201',
        periodStart,
        periodEnd,
        vat201 as unknown as Record<string, unknown>,
        userId
      );
      return apiResponse.created(res, submission, 'VAT201 draft saved');
    } catch (err) {
      log.error('Failed to save VAT201 draft', { error: err }, 'sars-api');
      return apiResponse.badRequest(res, err instanceof Error ? err.message : 'Failed to save draft');
    }
  }

  return apiResponse.methodNotAllowed(res, req.method!, ['GET', 'POST']);
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withCompany(withErrorHandler(handler as any));

export async function generateVAT201(companyId: string, 
  periodStart: string,
  periodEnd: string
): Promise<VAT201Data> {
  log.info('Generating VAT201', { periodStart, periodEnd }, 'sarsService');

  // -- Output VAT: customer invoices in period --
  let customerInvoices: Row[] = [];
  try {
    customerInvoices = (await sql`
      SELECT
        ci.id,
        ci.invoice_number,
        ci.invoice_date,
        ci.subtotal,
        ci.vat_amount,
        ci.total,
        ci.vat_type,
        c.name AS customer_name
      FROM customer_invoices ci
      LEFT JOIN customers c ON c.id = ci.customer_id
      WHERE ci.invoice_date >= ${periodStart}
        AND ci.invoice_date <= ${periodEnd}
        AND ci.status != 'cancelled'
      ORDER BY ci.invoice_date
    `) as Row[];
  } catch (err) {
    log.warn('Could not query customer_invoices for VAT201', { error: err }, 'sarsService');
  }

  // -- Input VAT: supplier invoices in period --
  let supplierInvoices: Row[] = [];
  try {
    supplierInvoices = (await sql`
      SELECT
        si.id,
        si.invoice_number,
        si.invoice_date,
        si.subtotal,
        si.vat_amount,
        si.total,
        si.vat_type,
        s.name AS supplier_name
      FROM supplier_invoices si
      LEFT JOIN suppliers s ON s.id = si.supplier_id
      WHERE si.invoice_date >= ${periodStart}
        AND si.invoice_date <= ${periodEnd}
        AND si.status != 'cancelled'
      ORDER BY si.invoice_date
    `) as Row[];
  } catch (err) {
    log.warn('Could not query supplier_invoices for VAT201', { error: err }, 'sarsService');
  }

  // Categorise customer invoices (output side)
  let field1_standardRated = 0;
  let field2_zeroRated = 0;
  let field3_exempt = 0;

  const outputInvoices: VAT201Invoice[] = customerInvoices.map((inv: Row) => {
    const subtotal = Number(inv.subtotal) || 0;
    const vatAmt = Number(inv.vat_amount) || 0;
    const vatType = String(inv.vat_type || 'standard').toLowerCase();

    if (vatType === 'zero_rated' || vatType === 'zero-rated' || vatType === 'zero') {
      field2_zeroRated += subtotal;
    } else if (vatType === 'exempt') {
      field3_exempt += subtotal;
    } else {
      field1_standardRated += subtotal;
    }

    return {
      id: String(inv.id),
      invoiceNumber: String(inv.invoice_number || ''),
      counterpartyName: String(inv.customer_name || 'Unknown'),
      invoiceDate: String(inv.invoice_date || ''),
      totalExclVat: subtotal,
      vatAmount: vatAmt,
      vatType,
    };
  });

  // Field 5: Output VAT = standard-rated supplies x 15%
  const field5_outputVAT = roundCents(field1_standardRated * SA_VAT_RATE);

  // Categorise supplier invoices (input side)
  let field6_capitalGoods = 0;
  let field7_otherGoods = 0;
  let field8_services = 0;
  let field9_imports = 0;

  const inputInvoices: VAT201Invoice[] = supplierInvoices.map((inv: Row) => {
    const vatAmt = Number(inv.vat_amount) || 0;
    const subtotal = Number(inv.subtotal) || 0;
    const vatType = String(inv.vat_type || 'standard').toLowerCase();

    // Categorise into input VAT fields based on vat_type metadata
    if (vatType === 'capital' || vatType === 'capital_goods') {
      field6_capitalGoods += vatAmt;
    } else if (vatType === 'import' || vatType === 'imports') {
      field9_imports += vatAmt;
    } else if (vatType === 'services' || vatType === 'service') {
      field8_services += vatAmt;
    } else {
      // Default: other goods and services
      field7_otherGoods += vatAmt;
    }

    return {
      id: String(inv.id),
      invoiceNumber: String(inv.invoice_number || ''),
      counterpartyName: String(inv.supplier_name || 'Unknown'),
      invoiceDate: String(inv.invoice_date || ''),
      totalExclVat: subtotal,
      vatAmount: vatAmt,
      vatType,
    };
  });

