A generic migration service that handles importing data from external accounting systems.

```typescript
import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';

export type MigrationSource = 'xero' | 'quickbooks' | 'pastel';

interface MigrationAccount {
  sourceCode: string;
  sourceName: string;
  sourceType: string;
  mappedCode?: string;    // ISAFlow account code
  mappedName?: string;    // ISAFlow account name
  openingBalance?: number;
}

interface MigrationEntity {
  name: string;
  email?: string;
  phone?: string;
  vatNumber?: string;
  address?: string;
  accountNumber?: string;
  balance?: number;
}

interface MigrationResult {
  accountsImported: number;
  customersImported: number;
  suppliersImported: number;
  openingBalancesSet: number;
  errors: string[];
}

// Parse uploaded CSV/file for accounts
export async function parseAccountsFile(source: MigrationSource, fileContent: string): Promise<MigrationAccount[]>
// Each source has different CSV column formats:
// Xero: "Account Code","Account Name","Account Type","YTD Balance"
// QuickBooks: "Account","Type","Balance","Detail Type"  
// Pastel: "AccNumber","Description","AccType","CurrentBalance"

// Parse uploaded CSV for customers
export async function parseCustomersFile(source: MigrationSource, fileContent: string): Promise<MigrationEntity[]>
// Xero: "Contact Name","Email","Phone","Tax Number"
// QuickBooks: "Customer","Email","Phone","Balance"
// Pastel: "Account","Description","Email","Telephone"

// Parse uploaded CSV for suppliers  
export async function parseSuppliersFile(source: MigrationSource, fileContent: string): Promise<MigrationEntity[]>
// Similar format variations per source

// Auto-map source accounts to ISAFlow account types
export function autoMapAccounts(source: MigrationSource, accounts: MigrationAccount[]): MigrationAccount[]
// Map source account types to ISAFlow types:
// Xero: "BANK" → asset/bank, "CURRENT" → asset/current_asset, "REVENUE" → revenue, etc.
// QuickBooks: "Bank" → asset/bank, "Accounts Receivable" → asset/current_asset, "Income" → revenue, etc.
// Pastel: numeric ranges (1xxx = asset, 2xxx = liability, etc.)

// Import mapped data into ISAFlow
export async function executeMigration(
  companyId: string, 
  userId: string,
  source: MigrationSource,
  accounts: MigrationAccount[],
  customers: MigrationEntity[],
  suppliers: MigrationEntity[]
): Promise<MigrationResult>
// 1. Create GL accounts from mapped accounts
// 2. Set opening balances via journal entry
// 3. Create customers
// 4. Create suppliers
// 5. Return counts and any errors

// Rollback a migration (delete imported data)
export async function rollbackMigration(companyId: string, migrationRunId: string): Promise<{ deleted: number }>
// Delete accounts, customers, suppliers created in this migration run
// Uses a tracking field or tag to identify imported records

// Balance verification
export async function verifyBalances(companyId: string, sourceAccounts: MigrationAccount[]): Promise<Array<{
  accountCode: string;
  sourceName: string;
  sourceBalance: number;
  isaflowBalance: number;
  difference: number;
  matched: boolean;
}>>
```

