  const drMatch = s.match(/^(.*?)\s*(Dr|DR|debit)$/i);
  const crMatch = s.match(/^(.*?)\s*(Cr|CR|credit)$/i);
  if (drMatch) { suffix = -1; cleaned = drMatch[1]!; }
  else if (crMatch) { suffix = 1; cleaned = crMatch[1]!; }

