  cleaned = cleaned.replace(/^R\s*/i, '').replace(/^ZAR\s*/i, '');

  // Parentheses denote negative: (1,234.56)
  const parenMatch = cleaned.match(/^\(([^)]+)\)$/);
  if (parenMatch) {
