/**
 * ExternalMigrationWizard — steps 2-5 of the Xero/QuickBooks/Pastel wizard.
 * Extracted to keep pages/accounting/migration/external.tsx under 300 lines.
 */

'use client';

import { useState, useRef } from 'react';
import {
  Upload, CheckCircle2, AlertCircle, Loader2, RotateCcw, ArrowRight,
} from 'lucide-react';
import { apiFetch } from '@/lib/apiFetch';
import { AccountMappingTable } from './AccountMappingTable';
import type { ParsedAccount, ParsedEntity, MigrationSource } from '@/modules/accounting/services/migrationParserService';

interface Props {
  source: MigrationSource;
  onDone: () => void;
  onBack: () => void;
}

type Step = 'upload' | 'mapping' | 'review' | 'verify';

interface VerifyEntry {
  accountCode: string;
  sourceName: string;
  sourceBalance: number;
  isaflowBalance: number;
  difference: number;
  matched: boolean;
}

interface ImportResult {
  accountsImported: number;
  customersImported: number;
  suppliersImported: number;
  openingBalancesSet: number;
  errors: string[];
}

const SOURCE_LABELS: Record<MigrationSource, string> = {
  xero: 'Xero',
  quickbooks: 'QuickBooks',
  pastel: 'Pastel / Sage 50',
};

const SOURCE_HINTS: Record<MigrationSource, { accounts: string; customers: string; suppliers: string }> = {
  xero: {
    accounts: 'Export from Xero: Reports → Chart of Accounts → Export to CSV',
    customers: 'Export from Xero: Contacts → Customers → Export',
    suppliers: 'Export from Xero: Contacts → Suppliers → Export',
  },
  quickbooks: {
    accounts: 'Export from QuickBooks: Accounting → Chart of Accounts → Export',
    customers: 'Export from QuickBooks: Sales → Customers → Export',
    suppliers: 'Export from QuickBooks: Expenses → Vendors → Export',
  },
  pastel: {
    accounts: 'Export from Pastel: General Ledger → Chart of Accounts → Export to Excel/CSV',
    customers: 'Export from Pastel: Customers → Customer List → Export',
    suppliers: 'Export from Pastel: Suppliers → Supplier List → Export',
  },
};

export function ExternalMigrationWizard({ source, onDone, onBack }: Props) {
  const [step, setStep] = useState<Step>('upload');
  const [accounts, setAccounts] = useState<ParsedAccount[]>([]);
  const [customers, setCustomers] = useState<ParsedEntity[]>([]);
  const [suppliers, setSuppliers] = useState<ParsedEntity[]>([]);
  const [parsing, setParsing] = useState<string>('');
  const [autoMapping, setAutoMapping] = useState(false);
  const [importing, setImporting] = useState(false);
  const [importResult, setImportResult] = useState<ImportResult | null>(null);
  const [verifyResults, setVerifyResults] = useState<VerifyEntry[]>([]);
  const [verifying, setVerifying] = useState(false);
  const [error, setError] = useState('');

  const acctRef = useRef<HTMLInputElement>(null);
  const custRef = useRef<HTMLInputElement>(null);
  const suppRef = useRef<HTMLInputElement>(null);

  const hints = SOURCE_HINTS[source];

  const parseFile = async (file: File, fileType: 'accounts' | 'customers' | 'suppliers') => {
    setParsing(fileType);
    setError('');
    try {
      const form = new FormData();
      form.append('file', file);
      form.append('source', source);
      form.append('fileType', fileType);

      const res = await apiFetch('/api/accounting/migration-parse', { method: 'POST', body: form });
      const json = await res.json();
      if (!res.ok) throw new Error(json.message || 'Parse failed');

      if (fileType === 'accounts') setAccounts(json.data.parsed);
      if (fileType === 'customers') setCustomers(json.data.parsed);
      if (fileType === 'suppliers') setSuppliers(json.data.parsed);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to parse file');
    } finally {
      setParsing('');
    }
  };

  const runAutoMap = async () => {
    if (accounts.length === 0) return;
    setAutoMapping(true);
    try {
      const form = new FormData();
      // Re-parse with auto-mapping by passing current data as JSON
      const res = await apiFetch('/api/accounting/migration-parse', {
        method: 'POST',
        body: (() => {
          const f = new FormData();
          const blob = new Blob([JSON.stringify(accounts)], { type: 'text/plain' });
          f.append('file', blob, 'accounts.json');
          f.append('source', source);
          f.append('fileType', 'accounts');
          return f;
        })(),
      });
      const json = await res.json();
      if (res.ok) setAccounts(json.data.parsed);
    } catch {
      // silent — mapping already applied locally
    } finally {
      setAutoMapping(false);
    }
  };

  const executeImport = async () => {
    setImporting(true);
    setError('');
    try {
      const res = await apiFetch('/api/accounting/migration-execute', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ source, accounts, customers, suppliers }),
      });
      const json = await res.json();
      if (!res.ok) throw new Error(json.message || 'Import failed');
      setImportResult(json.data);
      setStep('verify');
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Import failed');
    } finally {
      setImporting(false);
    }
  };

  const runVerify = async () => {
    setVerifying(true);
    setError('');
    try {
      const res = await apiFetch('/api/accounting/migration-verify', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ sourceAccounts: accounts.filter(a => a.openingBalance !== 0) }),
      });
      const json = await res.json();
      if (!res.ok) throw new Error(json.message || 'Verify failed');
      setVerifyResults(json.data.results);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Verification failed');
    } finally {
      setVerifying(false);
    }
  };

  return (
    <div className="space-y-6">
      <StepIndicator step={step} />

      {error && (
        <div className="flex items-center gap-2 p-3 rounded-lg bg-red-500/10 text-red-400 text-sm">
          <AlertCircle className="h-4 w-4 shrink-0" /> {error}
        </div>
      )}

      {/* Step 2 — Upload */}
      {step === 'upload' && (
        <div className="space-y-4">
          <FileUploadZone
            label="Chart of Accounts"
            hint={hints.accounts}
            required
            count={accounts.length}
            loading={parsing === 'accounts'}
            inputRef={acctRef}
            onFile={f => parseFile(f, 'accounts')}
          />
          <FileUploadZone
            label="Customers"
            hint={hints.customers}
            count={customers.length}
            loading={parsing === 'customers'}
            inputRef={custRef}
            onFile={f => parseFile(f, 'customers')}
          />
          <FileUploadZone
            label="Suppliers"
            hint={hints.suppliers}
            count={suppliers.length}
            loading={parsing === 'suppliers'}
            inputRef={suppRef}
            onFile={f => parseFile(f, 'suppliers')}
          />
          <div className="flex items-center justify-between pt-2">
            <button onClick={onBack} className="text-sm text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] underline">
              Back
            </button>
            <button
              onClick={() => setStep('mapping')}
              disabled={accounts.length === 0}
              className="flex items-center gap-2 px-4 py-2 rounded-lg bg-blue-600 hover:bg-blue-500 text-white text-sm font-medium disabled:opacity-50"
            >
              Next: Map Accounts <ArrowRight className="h-4 w-4" />
            </button>
          </div>
        </div>
      )}

      {/* Step 3 — Mapping */}
      {step === 'mapping' && (
        <div className="space-y-4">
          <AccountMappingTable
            accounts={accounts}
            onChange={setAccounts}
            onAutoMap={runAutoMap}
            autoMapping={autoMapping}
          />
          <div className="flex items-center justify-between pt-2">
            <button onClick={() => setStep('upload')} className="text-sm text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] underline">
              Back
            </button>
            <button
              onClick={() => setStep('review')}
              className="flex items-center gap-2 px-4 py-2 rounded-lg bg-blue-600 hover:bg-blue-500 text-white text-sm font-medium"
            >
              Next: Review <ArrowRight className="h-4 w-4" />
            </button>
          </div>
        </div>
      )}

      {/* Step 4 — Review & Import */}
      {step === 'review' && (
        <div className="space-y-4">
          <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] p-5 space-y-4">
            <h3 className="font-semibold text-[var(--ff-text-primary)]">Ready to import from {SOURCE_LABELS[source]}</h3>
            <div className="grid grid-cols-3 gap-3">
              <SummaryCard label="Accounts" value={accounts.filter(a => a.mappedType).length} />
              <SummaryCard label="Customers" value={customers.length} />
              <SummaryCard label="Suppliers" value={suppliers.length} />
            </div>
            {accounts.some(a => !a.mappedType) && (
              <p className="text-xs text-amber-400">
                {accounts.filter(a => !a.mappedType).length} unmapped account(s) will be skipped.
              </p>
            )}
          </div>
          <div className="flex items-center justify-between pt-2">
            <button onClick={() => setStep('mapping')} className="text-sm text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] underline">
              Back
            </button>
            <button
              onClick={executeImport}
              disabled={importing}
              className="flex items-center gap-2 px-5 py-2 rounded-lg bg-teal-600 hover:bg-teal-500 text-white text-sm font-medium disabled:opacity-50"
            >
              {importing ? <Loader2 className="h-4 w-4 animate-spin" /> : <CheckCircle2 className="h-4 w-4" />}
              {importing ? 'Importing...' : 'Import Now'}
            </button>
          </div>
        </div>
      )}

      {/* Step 5 — Verify */}
      {step === 'verify' && importResult && (
        <div className="space-y-4">
          <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] p-5 space-y-4">
            <div className="flex items-center gap-2 text-teal-400">
              <CheckCircle2 className="h-5 w-5" />
              <h3 className="font-semibold">Import Complete</h3>
            </div>
            <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
              <SummaryCard label="Accounts" value={importResult.accountsImported} />
              <SummaryCard label="Customers" value={importResult.customersImported} />
              <SummaryCard label="Suppliers" value={importResult.suppliersImported} />
              <SummaryCard label="Opening Balances" value={importResult.openingBalancesSet} />
            </div>
            {importResult.errors.length > 0 && (
              <div className="p-3 rounded-lg bg-red-500/10 text-red-400 text-xs space-y-1">
                <p className="font-medium">{importResult.errors.length} error(s):</p>
                {importResult.errors.slice(0, 5).map((e, i) => <p key={i}>{e}</p>)}
                {importResult.errors.length > 5 && <p>…and {importResult.errors.length - 5} more</p>}
              </div>
            )}
          </div>

          {verifyResults.length === 0 ? (
            <button
              onClick={runVerify}
              disabled={verifying}
              className="flex items-center gap-2 px-4 py-2 rounded-lg bg-blue-600 hover:bg-blue-500 text-white text-sm font-medium disabled:opacity-50"
            >
              {verifying ? <Loader2 className="h-4 w-4 animate-spin" /> : null}
              Verify Balances
            </button>
          ) : (
            <VerifyTable results={verifyResults} />
          )}

          <div className="flex items-center justify-between pt-2">
            <RollbackButton source={source} />
            <button
              onClick={onDone}
              className="px-5 py-2 rounded-lg bg-teal-600 hover:bg-teal-500 text-white text-sm font-medium"
            >
              Done
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

// ── Sub-components ────────────────────────────────────────────────────────────

function StepIndicator({ step }: { step: Step }) {
  const steps: { id: Step; label: string }[] = [
    { id: 'upload', label: 'Upload' },
    { id: 'mapping', label: 'Mapping' },
    { id: 'review', label: 'Review' },
    { id: 'verify', label: 'Verify' },
  ];
  const idx = steps.findIndex(s => s.id === step);
  return (
    <div className="flex items-center gap-2">
      {steps.map((s, i) => (
        <div key={s.id} className="flex items-center gap-2">
          <div className={`flex items-center justify-center w-6 h-6 rounded-full text-xs font-bold ${i <= idx ? 'bg-blue-500 text-white' : 'bg-[var(--ff-bg-primary)] text-[var(--ff-text-tertiary)]'}`}>
            {i < idx ? <CheckCircle2 className="h-3.5 w-3.5" /> : i + 1}
          </div>
          <span className={`text-xs ${i === idx ? 'text-[var(--ff-text-primary)] font-medium' : 'text-[var(--ff-text-tertiary)]'}`}>{s.label}</span>
          {i < steps.length - 1 && <div className="w-6 h-px bg-[var(--ff-border-light)]" />}
        </div>
      ))}
    </div>
  );
}

function FileUploadZone({ label, hint, required, count, loading, inputRef, onFile }: {
  label: string; hint: string; required?: boolean; count: number;
  loading: boolean; inputRef: React.RefObject<HTMLInputElement>; onFile: (f: File) => void;
}) {
  return (
    <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] p-4">
      <div className="flex items-start justify-between gap-3">
        <div className="flex-1 min-w-0">
          <p className="text-sm font-medium text-[var(--ff-text-primary)]">
            {label} {required && <span className="text-red-400 text-xs">*required</span>}
          </p>
          <p className="text-xs text-[var(--ff-text-tertiary)] mt-0.5">{hint}</p>
          {count > 0 && <p className="text-xs text-teal-400 mt-1">{count} records parsed</p>}
        </div>
        <div className="shrink-0">
          {loading
            ? <Loader2 className="h-5 w-5 animate-spin text-blue-400" />
            : (
              <>
                <input
                  ref={inputRef}
                  type="file"
                  accept=".csv,.txt,.xlsx"
                  className="hidden"
                  onChange={e => { const f = e.target.files?.[0]; if (f) onFile(f); }}
                />
                <button
                  onClick={() => inputRef.current?.click()}
                  className={`flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-medium transition-colors ${count > 0 ? 'bg-teal-500/10 text-teal-400 hover:bg-teal-500/20' : 'bg-blue-500/10 text-blue-400 hover:bg-blue-500/20'}`}
                >
                  <Upload className="h-3.5 w-3.5" />
                  {count > 0 ? 'Re-upload' : 'Upload'}
                </button>
              </>
            )
          }
        </div>
      </div>
    </div>
  );
}

function SummaryCard({ label, value }: { label: string; value: number }) {
  return (
    <div className="p-3 rounded-lg bg-[var(--ff-bg-primary)]">
      <p className="text-xs text-[var(--ff-text-tertiary)]">{label}</p>
      <p className="text-xl font-bold text-[var(--ff-text-primary)]">{value}</p>
    </div>
  );
}

function VerifyTable({ results }: { results: VerifyEntry[] }) {
  const allMatched = results.every(r => r.matched);
  return (
    <div className="rounded-lg border border-[var(--ff-border-light)] overflow-hidden">
      <div className={`px-4 py-2 text-sm font-medium ${allMatched ? 'bg-teal-500/10 text-teal-400' : 'bg-amber-500/10 text-amber-400'}`}>
        {allMatched ? 'All balances matched' : `${results.filter(r => !r.matched).length} balance(s) differ`}
      </div>
      <table className="w-full text-sm">
        <thead>
          <tr className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-primary)]">
            <th className="text-left px-3 py-2 text-[var(--ff-text-secondary)]">Account</th>
            <th className="text-right px-3 py-2 text-[var(--ff-text-secondary)]">Source</th>
            <th className="text-right px-3 py-2 text-[var(--ff-text-secondary)]">ISAFlow</th>
            <th className="text-right px-3 py-2 text-[var(--ff-text-secondary)]">Diff</th>
          </tr>
        </thead>
        <tbody className="divide-y divide-[var(--ff-border-light)]">
          {results.map(r => (
            <tr key={r.accountCode} className={r.matched ? '' : 'bg-red-500/5'}>
              <td className="px-3 py-2 text-[var(--ff-text-primary)]">
                <span className="font-mono text-xs mr-2">{r.accountCode}</span>{r.sourceName}
              </td>
              <td className="px-3 py-2 text-right font-mono text-xs">{r.sourceBalance.toFixed(2)}</td>
              <td className="px-3 py-2 text-right font-mono text-xs">{r.isaflowBalance.toFixed(2)}</td>
              <td className={`px-3 py-2 text-right font-mono text-xs ${r.matched ? 'text-teal-400' : 'text-red-400'}`}>
                {r.difference.toFixed(2)}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

function RollbackButton({ source }: { source: MigrationSource }) {
  const [loading, setLoading] = useState(false);
  const [done, setDone] = useState(false);

  const handleRollback = async () => {
    if (!confirm(`This will delete all GL accounts imported from ${source}. Continue?`)) return;
    setLoading(true);
    try {
      await apiFetch('/api/accounting/migration-rollback', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ source }),
      });
      setDone(true);
    } finally {
      setLoading(false);
    }
  };

  if (done) return <span className="text-xs text-teal-400">Rollback complete</span>;

  return (
    <button
      onClick={handleRollback}
      disabled={loading}
      className="flex items-center gap-1.5 text-xs text-[var(--ff-text-tertiary)] hover:text-red-400 disabled:opacity-50"
    >
      <RotateCcw className="h-3.5 w-3.5" />
      {loading ? 'Rolling back...' : 'Rollback import'}
    </button>
  );
}

