        subtotal: s, tax_rate: 15.00, tax_amount: t, total_amount: tot,
        status: 'applied',
        created_by: ADMIN_ID,
      });
    }

    // 1 supplier credit note per month
    const supInv = pick(supInvoices.filter(i => i.status === 'paid'));
    if (supInv) {
