// ── CLEAN ─────────────────────────────────────────────────────────────────────

async function cleanExisting(): Promise<void> {
  console.log('[clean] Removing existing transaction data...');
  const tables = [
    'customer_payment_allocations','customer_payments',
    'supplier_payment_allocations','supplier_payments',
    'customer_quote_lines','customer_quotes',
    'customer_invoice_items','customer_invoices',
    'supplier_invoice_items','supplier_invoices',
    'credit_notes',
    'gl_journal_lines','gl_journal_entries',
    'bank_transactions',
    'gl_account_balances',
    'customer_sales_order_items','customer_sales_orders',
    'supplier_purchase_order_items','supplier_purchase_orders',
  ];
  // Tables without company_id must be deleted via FK-scoped joins
  const noCompanyId = new Set(['customer_payment_allocations','supplier_payment_allocations',
    'customer_invoice_items','supplier_invoice_items','customer_quote_lines',
    'customer_sales_order_items','supplier_purchase_order_items','gl_journal_lines']);

  for (const t of tables) {
    if (noCompanyId.has(t)) continue; // handled below
    await sql.query(`DELETE FROM ${t} WHERE company_id = $1`, [COMPANY_ID]);
  }
  // Delete child rows of company-scoped parents
  await sql.query(`DELETE FROM customer_payment_allocations WHERE payment_id IN (SELECT id FROM customer_payments WHERE company_id = $1)`, [COMPANY_ID]);
  await sql.query(`DELETE FROM supplier_payment_allocations WHERE payment_id IN (SELECT id FROM supplier_payments WHERE company_id = $1)`, [COMPANY_ID]);
  await sql.query(`DELETE FROM customer_invoice_items WHERE invoice_id IN (SELECT id FROM customer_invoices WHERE company_id = $1)`, [COMPANY_ID]);
  await sql.query(`DELETE FROM supplier_invoice_items WHERE supplier_invoice_id IN (SELECT id FROM supplier_invoices WHERE company_id = $1)`, [COMPANY_ID]);
  await sql.query(`DELETE FROM customer_quote_lines WHERE quote_id IN (SELECT id FROM customer_quotes WHERE company_id = $1)`, [COMPANY_ID]);
  await sql.query(`DELETE FROM customer_sales_order_items WHERE sales_order_id IN (SELECT id FROM customer_sales_orders WHERE company_id = $1)`, [COMPANY_ID]);
  await sql.query(`DELETE FROM supplier_purchase_order_items WHERE purchase_order_id IN (SELECT id FROM supplier_purchase_orders WHERE company_id = $1)`, [COMPANY_ID]);

