async function main(): Promise<void> {
  console.log('=== ISAFlow Demo Data Seeder ===');
  console.log(`Company: ${COMPANY_ID}`);
  console.log('Range:   March 2024 → March 2027\n');

  const gl = await resolveGlAccounts();
