/**
 * Password Utilities
 * Secure password hashing and verification using bcryptjs
 */

import * as bcrypt from 'bcryptjs';
import { randomBytes, randomInt, createHash } from 'crypto';

// Cost factor for bcrypt (10-12 is recommended for production)
const SALT_ROUNDS = 12;

/**
 * Hash a password
 */
export async function hashPassword(password: string): Promise<string> {
  return bcrypt.hash(password, SALT_ROUNDS);
}

/**
 * Verify a password against a hash
 */
export async function verifyPassword(
  password: string,
  hash: string
): Promise<boolean> {
  return bcrypt.compare(password, hash);
}

/**
 * Check password strength
 * Returns an object with strength score and issues
 */
export function checkPasswordStrength(password: string): {
  score: number; // 0-4 (0 = very weak, 4 = very strong)
  issues: string[];
  isValid: boolean;
} {
  const issues: string[] = [];
  let score = 0;

  // Minimum length check
  if (password.length < 8) {
    issues.push('Password must be at least 8 characters');
  } else {
    score++;
    if (password.length >= 12) score++;
  }

  // Uppercase check
  if (!/[A-Z]/.test(password)) {
    issues.push('Password should contain at least one uppercase letter');
  } else {
    score++;
  }

  // Lowercase check
  if (!/[a-z]/.test(password)) {
    issues.push('Password should contain at least one lowercase letter');
  }

  // Number check
  if (!/[0-9]/.test(password)) {
    issues.push('Password should contain at least one number');
  } else {
    score++;
  }

  // Special character check
  if (!/[!@#$%^&*(),.?":{}|<>]/.test(password)) {
    issues.push('Password should contain at least one special character');
  }

  return {
    score: Math.min(score, 4),
    issues,
    isValid: password.length >= 8 && issues.length <= 2,
  };
}

/**
 * Generate a cryptographically secure random password
 */
export function generateRandomPassword(length: number = 16): string {
  const uppercase = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
  const lowercase = 'abcdefghijklmnopqrstuvwxyz';
  const numbers = '0123456789';
  const special = '!@#$%^&*';
  const all = uppercase + lowercase + numbers + special;

  const chars: string[] = [];

  // Ensure at least one of each type using crypto.randomInt
  chars.push(uppercase[randomInt(uppercase.length)]!);
  chars.push(lowercase[randomInt(lowercase.length)]!);
  chars.push(numbers[randomInt(numbers.length)]!);
  chars.push(special[randomInt(special.length)]!);

  // Fill the rest
  for (let i = 4; i < length; i++) {
    chars.push(all[randomInt(all.length)]!);
  }

  // Fisher-Yates shuffle using crypto.randomInt
  for (let i = chars.length - 1; i > 0; i--) {
    const j = randomInt(i + 1);
    [chars[i], chars[j]] = [chars[j]!, chars[i]!];
  }

  return chars.join('');
}

/**
 * Generate a secure password reset token
 * Returns both the plain token (to send to user) and hashed token (to store in DB)
 */
export function generateResetToken(): {
  token: string;
  hashedToken: string;
  expiresAt: Date;
} {
  // Generate 32 random bytes = 64 hex characters
  const token = randomBytes(32).toString('hex');

  // Hash the token for storage (so even if DB is compromised, tokens can't be used)
  const hashedToken = createHash('sha256').update(token).digest('hex');

  // Token expires in 1 hour
  const expiresAt = new Date(Date.now() + 60 * 60 * 1000);

  return { token, hashedToken, expiresAt };
}

/**
 * Hash a reset token for comparison
 */
export function hashResetToken(token: string): string {
  return createHash('sha256').update(token).digest('hex');
}

/**
 * Check if a reset token has expired
 */
export function isResetTokenExpired(expiresAt: Date | string): boolean {
  const expiry = typeof expiresAt === 'string' ? new Date(expiresAt) : expiresAt;
  return expiry < new Date();
}

/**
 * Next.js Edge Middleware
 * - app.isaflow.co.za: redirect / to /accounting (app domain — no landing page)
 * - isaflow.co.za: show landing page at /
 * - Redirects unauthenticated /accounting/* requests to /login
 */

import { NextResponse } from 'next/server';
import type { NextRequest } from 'next/server';

const AUTH_COOKIE_NAME = 'ff_auth_token';

const PUBLIC_PATHS = ['/login', '/register', '/api/auth/login', '/api/auth/logout', '/api/auth/register', '/onboarding', '/api/onboarding', '/invite', '/api/invite'];

/** Hostnames that should skip the landing page and go straight to the app */
const APP_HOSTS = ['app.isaflow.co.za'];

export function middleware(request: NextRequest) {
  const { pathname } = request.nextUrl;
  const host = request.headers.get('host')?.split(':')[0] ?? '';

  // Allow public paths, static files, and API routes
  if (
    PUBLIC_PATHS.some(p => pathname.startsWith(p)) ||
    pathname.startsWith('/_next') ||
    pathname.startsWith('/api/') ||
    pathname.startsWith('/icons') ||
    pathname.startsWith('/landing') ||
    pathname === '/manifest.json' ||
    pathname === '/sw.js' ||
    pathname === '/favicon.ico'
  ) {
    return NextResponse.next();
  }

  // app.isaflow.co.za: redirect root to /accounting
  if (pathname === '/' && APP_HOSTS.includes(host)) {
    return NextResponse.redirect(new URL('/accounting', request.url));
  }

  // Check for auth cookie on protected routes
  const token = request.cookies.get(AUTH_COOKIE_NAME)?.value;

  if (!token && (pathname.startsWith('/accounting') || pathname.startsWith('/payroll'))) {
    const loginUrl = new URL('/login', request.url);
    loginUrl.searchParams.set('returnTo', pathname);
    return NextResponse.redirect(loginUrl);
  }

  // Redirect to onboarding if user hasn't completed it
  if (token && !request.cookies.get('ff_onboarding_done')?.value) {
    if (pathname.startsWith('/accounting') || pathname.startsWith('/payroll')) {
      return NextResponse.redirect(new URL('/onboarding', request.url));
    }
  }

  return NextResponse.next();
}

export const config = {
  matcher: ['/', '/accounting/:path*', '/onboarding/:path*', '/payroll/:path*', '/invite/:path*'],
};

/**
 * Payslip Verification API
 * POST /api/accounting/verify-payslip — Upload payslip PDF, verify against payroll record
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { Writable } from 'stream';
import formidable from 'formidable';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany } from '@/lib/auth';
import { log } from '@/lib/logger';
import {
  parsePayslipExtractionResponse,
  verifyPayslipAgainstPayroll,
  validatePayslipExtraction,
  matchEmployeeFromExtraction,
  type PayrollRecord,
} from '@/modules/accounting/services/payslipVerificationService';

export const config = {
  api: { bodyParser: false },
};

const MAX_FILE_SIZE = 10 * 1024 * 1024; // 10MB

const ALLOWED_MIME_TYPES: Record<string, boolean> = {
  'application/pdf': true,
  'image/jpeg': true,
  'image/jpg': true,
  'image/png': true,
};

const fileBuffers = new WeakMap<formidable.File, Buffer>();

function parseForm(req: NextApiRequest): Promise<{ fields: formidable.Fields; files: formidable.Files }> {
  return new Promise((resolve, reject) => {
    const form = formidable({
      maxFileSize: MAX_FILE_SIZE,
      keepExtensions: true,
      filter: (part) => {
        const mime = part.mimetype || '';
        return mime in ALLOWED_MIME_TYPES || !mime;
      },
      fileWriteStreamHandler: (file) => {
        const chunks: Buffer[] = [];
        const writable = new Writable({
          write(chunk, _encoding, callback) {
            chunks.push(Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk));
            callback();
          },
          final(callback) {
            fileBuffers.set(file as unknown as formidable.File, Buffer.concat(chunks));
            callback();
          },
        });
        return writable;
      },
    });
    form.parse(req, (err, fields, files) => {
      if (err) reject(err);
      else resolve({ fields, files });
    });
  });
}

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['POST']);
  }

  const { fields, files } = await parseForm(req);

  const fileField = files.file;
  const file = Array.isArray(fileField) ? fileField[0] : fileField;

  if (!file) {
    return apiResponse.badRequest(res, 'No file uploaded. Please select a PDF or image.');
  }

  const mimeType = file.mimetype || '';
  if (!ALLOWED_MIME_TYPES[mimeType]) {
    return apiResponse.badRequest(res, `Unsupported file type: ${mimeType}. Supported: PDF, JPEG, PNG`);
  }

  const buffer = fileBuffers.get(file);
  if (!buffer || buffer.length === 0) {
    return apiResponse.badRequest(res, 'Failed to read uploaded file');
  }

  // Parse payroll record from form fields
  const payrollRaw = Array.isArray(fields.payroll) ? fields.payroll[0] : fields.payroll;
  const employeesRaw = Array.isArray(fields.employees) ? fields.employees[0] : fields.employees;
  const extractedRaw = Array.isArray(fields.extracted) ? fields.extracted[0] : fields.extracted;

  if (!payrollRaw && !extractedRaw) {
    return apiResponse.badRequest(res, 'Either payroll record or extracted payslip data is required');
  }

  let payroll: PayrollRecord | undefined;
  if (payrollRaw) {
    try {
      payroll = JSON.parse(payrollRaw) as PayrollRecord;
    } catch {
      return apiResponse.badRequest(res, 'Invalid payroll JSON');
    }
  }

  // Use pre-extracted data or attempt to parse from a VLM response string
  const extracted = extractedRaw ? parsePayslipExtractionResponse(extractedRaw) : null;

  if (!extracted) {
    log.warn('No extracted payslip data provided — returning raw buffer analysis not available without VLM', {}, 'verify-payslip');
    return apiResponse.badRequest(res, 'extracted field with payslip JSON is required');
  }

  const validation = validatePayslipExtraction(extracted);
  if (!validation.valid) {
    return apiResponse.badRequest(res, `Extracted payslip incomplete: ${validation.errors.join(', ')}`);
  }

  // Optional employee matching
  let employeeMatch = null;
  if (employeesRaw) {
    try {
      const employees = JSON.parse(employeesRaw) as Array<{ id: string; name: string; idNumber: string }>;
      employeeMatch = matchEmployeeFromExtraction(extracted, employees);
    } catch {
      log.warn('Could not parse employees field — skipping employee match', {}, 'verify-payslip');
    }
  }

  if (!payroll) {
    log.info('No payroll record supplied — returning extracted data only', {}, 'verify-payslip');
    return apiResponse.success(res, { extracted, employeeMatch });
  }

  const result = verifyPayslipAgainstPayroll(extracted, payroll);

  log.info('Payslip verification complete', {
    valid: result.valid,
    score: result.score,
    discrepancies: result.discrepancies.length,
  }, 'verify-payslip');

  return apiResponse.success(res, { result, extracted, employeeMatch });
}

