/**
 * POST /api/auth/register
 * Creates a new user account with email + password.
 * Does NOT set an auth cookie — user must log in after registering.
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { hashPassword, checkPasswordStrength } from '@/lib/auth';
import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method ?? 'unknown', ['POST']);
  }

  const { firstName, lastName, email, password, confirmPassword } = req.body as {
    firstName?: string;
    lastName?: string;
    email?: string;
    password?: string;
    confirmPassword?: string;
  };

  // Validate all fields present
  if (!firstName || !lastName || !email || !password || !confirmPassword) {
    return apiResponse.badRequest(res, 'All fields are required');
  }

  // Validate email format
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (!emailRegex.test(email)) {
    return apiResponse.badRequest(res, 'Please enter a valid email address');
  }

  // Validate passwords match
  if (password !== confirmPassword) {
    return apiResponse.badRequest(res, 'Passwords do not match');
  }

  // Check password strength
  const strength = checkPasswordStrength(password);
  if (strength.score < 2) {
    return apiResponse.badRequest(res, `Password too weak: ${strength.issues[0] || 'Please choose a stronger password'}`);
  }

  try {
    // Check email uniqueness
    const existing = (await sql`
      SELECT id FROM users WHERE LOWER(email) = LOWER(${email.trim()}) LIMIT 1
    `) as Row[];

    if (existing.length > 0) {
      return apiResponse.badRequest(res, 'An account with this email already exists');
    }

    // Hash password
    const hash = await hashPassword(password);

    // Insert user
    const rows = (await sql`
      INSERT INTO users (email, password_hash, first_name, last_name, role, permissions, is_active, onboarding_completed)
      VALUES (${email.toLowerCase().trim()}, ${hash}, ${firstName.trim()}, ${lastName.trim()}, 'viewer', '[]', true, false)
      RETURNING id, email
    `) as Row[];

    const user = rows[0];
    const userId = String(user.id);
    const normalizedEmail = (email as string).toLowerCase().trim();

    // Auto-accept any pending company invitations for this email
    const pendingInvitations = (await sql`
      SELECT id, company_id, role
      FROM company_invitations
      WHERE LOWER(email) = LOWER(${normalizedEmail})
        AND accepted_at IS NULL
        AND expires_at > NOW()
    `) as Row[];

    let invitationsAccepted = 0;
    for (const inv of pendingInvitations) {
      await sql`
        INSERT INTO company_users (company_id, user_id, role, is_default)
        VALUES (${inv.company_id as string}::UUID, ${userId}::UUID, ${inv.role as string}, false)
        ON CONFLICT (company_id, user_id) DO NOTHING
      `;
      await sql`
        UPDATE company_invitations SET accepted_at = NOW() WHERE id = ${inv.id as string}::UUID
      `;
      invitationsAccepted++;
    }

    if (invitationsAccepted > 0) {
      await sql`UPDATE users SET onboarding_completed = true WHERE id = ${userId}`;
      log.info('Onboarding skipped via invitation acceptance at registration', { userId, invitationsAccepted }, 'auth/register');
    }

    log.info('User registered', { userId, email: user.email as string, invitationsAccepted }, 'auth/register');

    return apiResponse.created(res, { userId, email: user.email as string, invitationsAccepted });
  } catch (err) {
    log.error('Registration error', err instanceof Error ? { message: err.message } : { err }, 'auth/register');
    return apiResponse.internalError(res, err);
  }
}

export default withErrorHandler(handler as any);

/**
 * PayFast ITN (Instant Transaction Notification) Webhook
 * POST — called by PayFast servers to confirm payment status
 *
 * NO auth wrapper — this is a public webhook endpoint.
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { handleITN } from '@/modules/accounting/services/paymentGatewayService';
import { log } from '@/lib/logger';

export default async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    res.setHeader('Allow', 'POST');
    return res.status(405).json({ error: 'Method not allowed' });
  }

  try {
    // Get source IP from request (may be behind proxy)
    const sourceIp = (req.headers['x-forwarded-for'] as string)?.split(',')[0]?.trim()
      || req.socket.remoteAddress
      || '';

    log.info('ITN received', { sourceIp, body: req.body }, 'PaymentGateway');

    const result = await handleITN(req.body || {}, sourceIp);

    if (!result.valid) {
      log.error('ITN validation failed', { transactionId: result.transactionId }, 'PaymentGateway');
      // PayFast expects 200 OK even on validation failure to stop retries
      return res.status(200).json({ status: 'invalid' });
    }

    log.info('ITN processed successfully', { transactionId: result.transactionId }, 'PaymentGateway');
    return res.status(200).json({ status: 'ok' });
  } catch (error) {
    log.error('ITN processing error', error instanceof Error ? { message: error.message, stack: error.stack } : { error }, 'PaymentGateway');
    // Return 200 to prevent PayFast from retrying indefinitely
    return res.status(200).json({ status: 'error' });
  }
}

/**
 * GL Import Template API
 * GET /api/accounting/gl-import-template
 * Returns an Excel (.xlsx) template file with headers and 2 sample rows.
 * NOTE: This endpoint does NOT require company auth — just auth.
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import * as XLSX from 'xlsx';

export default function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') {
    res.setHeader('Allow', ['GET']);
    res.status(405).json({ error: 'Method not allowed' });
    return;
  }

  const headers = [
    'Date',
    'Account Code',
    'Description',
    'Reference',
    'Debit',
    'Credit',
    'VAT Code',
    'Cost Centre',
  ];

  const sampleRows = [
    [
      '2026-04-01',
      '1000',
      'Opening bank balance',
      'OB-2026-001',
      50000,
      0,
      'no_vat',
      '',
    ],
    [
      '2026-04-01',
      '3100',
      'Opening bank balance',
      'OB-2026-001',
      0,
      50000,
      'no_vat',
      '',
    ],
  ];

  const wsData = [headers, ...sampleRows];
  const ws = XLSX.utils.aoa_to_sheet(wsData);

  // Set column widths
  ws['!cols'] = [
    { wch: 12 }, // Date
    { wch: 14 }, // Account Code
    { wch: 35 }, // Description
    { wch: 18 }, // Reference
    { wch: 12 }, // Debit
    { wch: 12 }, // Credit
    { wch: 14 }, // VAT Code
    { wch: 14 }, // Cost Centre
  ];

  const wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, ws, 'GL Import');

  // Add a Notes sheet with VAT code reference
  const notesData = [
    ['VAT Code Reference'],
    ['standard', '15% standard rate'],
    ['zero_rated', '0% zero-rated supplies'],
    ['exempt', 'Exempt from VAT'],
    ['capital_goods', 'Standard-rated capital goods'],
    ['export', 'Zero-rated exports'],
    ['imported', 'Imported goods/services'],
    ['reverse_charge', 'Domestic reverse charge (DRC)'],
    ['bad_debt', 'Bad debt recovery'],
    ['no_vat', 'No VAT applicable'],
  ];
  const notesWs = XLSX.utils.aoa_to_sheet(notesData);
  notesWs['!cols'] = [{ wch: 18 }, { wch: 35 }];
  XLSX.utils.book_append_sheet(wb, notesWs, 'VAT Codes');

  const buf = XLSX.write(wb, { type: 'buffer', bookType: 'xlsx' });

  res.setHeader('Content-Type', 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');
  res.setHeader('Content-Disposition', 'attachment; filename="isaflow-gl-import-template.xlsx"');
  res.setHeader('Content-Length', buf.length);
  res.status(200).send(buf);
}

/**
