/**
 * Bank Statement Import API
 * POST /api/accounting/bank-transactions-import
 *   Import CSV or PDF bank statement
 *
 * Body (CSV):
 *   { csvContent, bankAccountId, statementDate, bankFormat?, fileType?: 'csv' }
 *
 * Body (PDF):
 *   { pdfBase64, bankAccountId, statementDate, bankFormat?, fileType: 'pdf' }
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import { importBankStatement, importParsedTransactions } from '@/modules/accounting/services/bankReconciliationService';
import { parseBankPdf } from '@/modules/accounting/utils/bankPdfParser';
import type { BankFormat } from '@/modules/accounting/types/bank.types';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['POST']);
  }

  const { companyId } = req as CompanyApiRequest;

  try {
    const {
      csvContent,
      pdfBase64,
      fileType,
      bankAccountId,
      statementDate,
      bankFormat,
    } = req.body as {
      csvContent?: string;
      pdfBase64?: string;
      fileType?: 'csv' | 'pdf';
      bankAccountId: string;
      statementDate: string;
      bankFormat?: string;
    };

    if (!bankAccountId || !statementDate) {
      return apiResponse.badRequest(res, 'bankAccountId and statementDate are required');
    }

    const resolvedFileType: 'csv' | 'pdf' = fileType || (pdfBase64 ? 'pdf' : 'csv');

    if (resolvedFileType === 'pdf') {
      if (!pdfBase64) {
        return apiResponse.badRequest(res, 'pdfBase64 is required for PDF imports');
      }

      // Strip data-URL prefix if present: "data:application/pdf;base64,<data>"
      const base64Data = pdfBase64.includes(',') ? pdfBase64.split(',')[1]! : pdfBase64;
      const pdfBuffer = Buffer.from(base64Data, 'base64');

      log.info('Starting PDF bank statement import', {
        bankAccountId, statementDate, bankFormat, bufferSize: pdfBuffer.length,
      }, 'accounting-api');

      const parseResult = await parseBankPdf(pdfBuffer, bankFormat);

      if (parseResult.errors.length > 0 && parseResult.transactions.length === 0) {
        return apiResponse.badRequest(res, parseResult.errors[0]!.error);
      }

      const result = await importParsedTransactions(
        companyId,
        parseResult,
        String(bankAccountId),
        String(statementDate),
      );

      return apiResponse.created(res, result);
    }

    // Default: CSV import
    if (!csvContent) {
      return apiResponse.badRequest(res, 'csvContent is required for CSV imports');
    }

    const result = await importBankStatement(
      companyId,
      csvContent,
      String(bankAccountId),
      String(statementDate),
      (bankFormat || undefined) as BankFormat | undefined,
    );

    return apiResponse.created(res, result);
  } catch (err) {
    const message = err instanceof Error ? err.message : 'Failed to import bank statement';
    log.error('Failed to import bank statement', { error: err }, 'accounting-api');
    return apiResponse.badRequest(res, message);
  }
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withCompany(withErrorHandler(handler as any));

/**
 * Client Portal — Statement API
 * GET — get client statement
 * Requires signed portal session cookie (JWT)
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { getClientStatement } from '@/modules/accounting/services/portalService';
import { jwtVerify } from 'jose';
import cookie from 'cookie';

const PORTAL_SECRET = new TextEncoder().encode(
  (() => { if (!process.env.JWT_SECRET) throw new Error('JWT_SECRET is required'); return process.env.JWT_SECRET + '-portal'; })()
);

async function getPortalSession(req: NextApiRequest): Promise<{ clientId: string } | null> {
  const cookies = cookie.parse(req.headers.cookie || '');
  const token = cookies.portal_session;
  if (!token) return null;
  try {
    const { payload } = await jwtVerify(token, PORTAL_SECRET);
    return { clientId: payload.clientId as string };
  } catch {
    return null;
  }
}

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method!, ['GET']);
  }

  const session = await getPortalSession(req);
  if (!session) {
    return apiResponse.unauthorized(res, 'Portal authentication required');
  }

  const clientId = req.query.clientId as string;
  if (!clientId) {
    return apiResponse.badRequest(res, 'clientId is required');
  }

  // Enforce tenant isolation
  if (session.clientId !== clientId) {
    return apiResponse.forbidden(res, 'Access denied — clientId mismatch');
  }

  const asOfDate = (req.query.asOf as string) || new Date().toISOString().slice(0, 10);
  const statement = await getClientStatement(clientId, asOfDate);
  return apiResponse.success(res, statement);
}

export default withErrorHandler(handler);

/**
 * Purchase Orders API — CRUD
 */
import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { validatePurchaseOrder, calculatePOTotals, generatePONumber } from '@/modules/accounting/services/procurementService';

type Row = Record<string, unknown>;

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  const companyId = (req as any).companyId as string | undefined;

  if (req.method === 'GET') {
    const { status, supplierId } = req.query;
    let rows: Row[];
    if (status) {
      rows = await sql`SELECT po.*, s.name as supplier_name FROM purchase_orders po LEFT JOIN suppliers s ON po.supplier_id = s.id WHERE po.status = ${String(status)} ORDER BY po.created_at DESC LIMIT 200` as Row[];
    } else if (supplierId) {
      rows = await sql`SELECT po.*, s.name as supplier_name FROM purchase_orders po LEFT JOIN suppliers s ON po.supplier_id = s.id WHERE po.supplier_id = ${String(supplierId)} ORDER BY po.created_at DESC LIMIT 200` as Row[];
    } else {
      rows = await sql`SELECT po.*, s.name as supplier_name FROM purchase_orders po LEFT JOIN suppliers s ON po.supplier_id = s.id ORDER BY po.created_at DESC LIMIT 200` as Row[];
    }
    return apiResponse.success(res, rows);
  }

  if (req.method === 'POST') {
    const body = req.body;
    const validation = validatePurchaseOrder(body);
    if (!validation.success) return apiResponse.validationError(res, Object.fromEntries((validation.errors || []).map(e => [e.field, e.message])));

    const totals = calculatePOTotals(body.items);
    const countRes = await sql`SELECT COUNT(*) as cnt FROM purchase_orders` as Row[];
    const poNumber = generatePONumber(Number((countRes[0] as any)?.cnt || 0));

    const inserted = await sql`
      INSERT INTO purchase_orders (company_id, po_number, supplier_id, order_date, expected_delivery_date, subtotal, tax_amount, total, notes, reference, created_by)
      VALUES (${companyId || null}, ${poNumber}, ${body.supplierId}, ${body.orderDate || new Date().toISOString().split('T')[0]}, ${body.expectedDeliveryDate || null}, ${totals.subtotal}, ${totals.taxAmount}, ${totals.total}, ${body.notes || null}, ${body.reference || null}, ${String(req.user.id)})
      RETURNING *
    ` as Row[];

    const poId = String(inserted[0]?.id);
    for (let i = 0; i < body.items.length; i++) {
      const item = body.items[i];
      const lineTotal = Math.round(item.quantity * item.unitPrice * 100) / 100;
      const lineTax = Math.round(lineTotal * (item.taxRate || 15) / 100 * 100) / 100;
      await sql`INSERT INTO po_items (purchase_order_id, product_id, description, quantity, unit_price, tax_rate, line_total, tax_amount, sort_order) VALUES (${poId}, ${item.productId || null}, ${item.description}, ${item.quantity}, ${item.unitPrice}, ${item.taxRate || 15}, ${lineTotal}, ${lineTax}, ${i})`;
    }

    log.info('Purchase order created', { poNumber, supplier: body.supplierId, total: totals.total }, 'accounting');
    return apiResponse.created(res, { ...inserted[0], items: body.items });
  }

  return apiResponse.methodNotAllowed(res, req.method!, ['GET', 'POST']);
}

export default withCompany(withErrorHandler(handler as any));

/**
 * GET /api/auth/me
 * Returns the currently authenticated user from the JWT cookie.
 * Uses a single JOIN query for performance (session + user in one round-trip).
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { log } from '@/lib/logger';
import { apiResponse } from '@/lib/apiResponse';
import { verifyToken } from '@/lib/auth/jwt';
import { getUserAndValidateSession, AUTH_COOKIE_NAME } from '@/lib/auth/middleware';
import { createHash } from 'crypto';

export default async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method ?? 'unknown', ['GET']);
  }

  // Extract token from cookie or Authorization header
  const cookieToken = req.cookies[AUTH_COOKIE_NAME];
  const authHeader = req.headers.authorization;
  const bearerToken = authHeader?.startsWith('Bearer ') ? authHeader.substring(7) : null;
  const token = cookieToken ?? bearerToken;

  if (!token) {
    return res.status(401).json({
      success: false,
      error: { code: 'UNAUTHORIZED', message: 'Not authenticated' },
    });
  }

  try {
    const payload = await verifyToken(token);
    if (!payload) {
      return res.status(401).json({
        success: false,
        error: { code: 'INVALID_TOKEN', message: 'Invalid or expired token' },
      });
    }

    const tokenHash = createHash('sha256').update(token).digest('hex');
    const user = await getUserAndValidateSession(payload.sub, payload.sessionId, tokenHash);

    if (!user) {
      return res.status(401).json({
        success: false,
        error: { code: 'SESSION_INVALID', message: 'Session expired or invalid' },
      });
    }

    return apiResponse.success(res, { user });
  } catch (err) {
    log.error('Failed to get current user', err instanceof Error ? { message: err.message } : { err }, 'auth/me');
    return apiResponse.internalError(res, err);
  }
}

/**
 * POST /api/auth/2fa-verify
 * Verify TOTP code during login using a short-lived temp token.
 * Returns full auth token on success (mirrors login response).
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { serialize } from 'cookie';
import { sql } from '@/lib/neon';
import { apiResponse } from '@/lib/apiResponse';
import { verifyToken, signToken } from '@/lib/auth/jwt';
import { createSession } from '@/lib/auth/session';
import { AUTH_COOKIE_NAME } from '@/lib/auth/middleware';
import { verifyTOTPCode, addTrustedDevice } from '@/modules/auth/services/twoFactorService';
import { log } from '@/lib/logger';
import type { AuthRole } from '@/lib/auth/types';
import { createHash } from 'crypto';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

export default async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method ?? 'unknown', ['POST']);
  }

  const {
    tempToken,
    code,
    trustDevice,
    deviceFingerprint,
    deviceName,
  } = req.body as {
    tempToken?: string;
    code?: string;
    trustDevice?: boolean;
    deviceFingerprint?: string;
    deviceName?: string;
  };

  if (!tempToken || !code) {
    return apiResponse.badRequest(res, 'tempToken and code are required');
  }

  try {
    // Verify the temp token
    const payload = await verifyToken(tempToken);
    if (!payload) {
      return res.status(401).json({
        success: false,
        error: { code: 'INVALID_TOKEN', message: 'Invalid or expired temp token' },
      });
    }

    // Temp tokens use sessionId = '2fa-pending'
    if (payload.sessionId !== '2fa-pending') {
      return res.status(401).json({
        success: false,
        error: { code: 'INVALID_TOKEN', message: 'Token is not a 2FA temp token' },
      });
    }

    const userId = payload.sub;

    // Look up the user
    const rows = (await sql`
      SELECT id, email, first_name, last_name, role,
             is_active, permissions, profile_picture, department, onboarding_completed
      FROM users
      WHERE id = ${userId} AND is_active = true
      LIMIT 1
    `) as Row[];

    const user = rows[0];
    if (!user) {
      return res.status(401).json({
        success: false,
        error: { code: 'USER_NOT_FOUND', message: 'User not found' },
      });
    }

    // Verify TOTP code
    const codeValid = await verifyTOTPCode(userId, code.trim());
    if (!codeValid) {
      return res.status(401).json({
        success: false,
        error: { code: 'INVALID_2FA_CODE', message: 'Invalid authentication code' },
      });
    }

    const firstName = (user.first_name as string) || '';
    const lastName = (user.last_name as string) || '';

    const authUser = {
      id: String(user.id),
      userId: String(user.id),
      email: user.email as string,
      firstName,
      lastName,
      name: `${firstName} ${lastName}`.trim() || (user.email as string),
      role: user.role as AuthRole,
      permissions: (user.permissions as string[]) || [],
      isActive: true,
      profilePicture: user.profile_picture as string | undefined,
      department: user.department as string | undefined,
    };

    // Create full session
    const ipAddress = Array.isArray(req.headers['x-forwarded-for'])
      ? req.headers['x-forwarded-for'][0]
      : req.headers['x-forwarded-for'] ?? req.socket.remoteAddress;
    const userAgent = req.headers['user-agent'];

    const pendingToken = await signToken(authUser, 'pending');
    const session = await createSession(authUser.id, pendingToken, ipAddress, userAgent);

    const finalToken = await signToken(authUser, session.id);
    const finalHash = createHash('sha256').update(finalToken).digest('hex');

    await sql`
      UPDATE user_sessions SET token_hash = ${finalHash} WHERE id = ${Number(session.id)}
    `;

    // Optionally trust device
    if (trustDevice && deviceFingerprint) {
      await addTrustedDevice(userId, deviceFingerprint, deviceName ?? 'Unknown Device');
    }

    const onboardingCompleted = !!user.onboarding_completed;

    const authCookieString = serialize(AUTH_COOKIE_NAME, finalToken, {
      httpOnly: true,
      secure: process.env.NODE_ENV === 'production',
      sameSite: 'strict',
      path: '/',
      maxAge: 30 * 24 * 60 * 60,
    });

    const cookies = [authCookieString];
    if (onboardingCompleted) {
      cookies.push(`ff_onboarding_done=1; Path=/; Max-Age=${30 * 24 * 60 * 60}; SameSite=Lax${process.env.NODE_ENV === 'production' ? '; Secure' : ''}`);
    }
    res.setHeader('Set-Cookie', cookies);

    log.info('2FA verified — full session created', { userId }, 'api/auth/2fa-verify');

    return apiResponse.success(res, {
      user: { ...authUser, onboardingCompleted },
    }, 'Two-factor authentication verified');
  } catch (err) {
    log.error('2fa-verify error', err instanceof Error ? { message: err.message } : { err }, 'api/auth/2fa-verify');
    return apiResponse.internalError(res, err);
  }
}

