/**
 * Exchange Rates API
 * GET  — list rates (optional from/to currency filters)
 * POST — set/update rate for a date
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest, type AuthenticatedNextApiRequest } from '@/lib/auth';
import {
  getExchangeRates,
  setExchangeRate,
  getLatestRate,
  convertAmount,
} from '@/modules/accounting/services/currencyService';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  const { companyId } = req as CompanyApiRequest;
  const userId = (req as AuthenticatedNextApiRequest).user.id;

  if (req.method === 'GET') {
    const { from, to, convert, amount, date } = req.query;

    // Convert endpoint: ?convert=true&from=USD&to=ZAR&amount=100&date=2026-02-26
    if (convert === 'true' && from && to && amount) {
      const result = await convertAmount(companyId,
        Number(amount), String(from), String(to), date ? String(date) : undefined
      );
      if (!result) return apiResponse.notFound(res, 'Exchange rate', `${from}/${to}`);
      return apiResponse.success(res, result);
    }

    // Latest rate: ?from=USD&to=ZAR&latest=true
    if (req.query.latest === 'true' && from && to) {
      const rate = await getLatestRate(companyId, String(from), String(to), date ? String(date) : undefined);
      if (rate === null) return apiResponse.notFound(res, 'Exchange rate', `${from}/${to}`);
      return apiResponse.success(res, { from, to, rate });
    }

    // List rates
    const rates = await getExchangeRates(companyId, {
      fromCurrency: from ? String(from) : undefined,
      toCurrency: to ? String(to) : undefined,
      limit: req.query.limit ? Number(req.query.limit) : undefined,
    });
    return apiResponse.success(res, rates);
  }

  if (req.method === 'POST') {
    const { fromCurrency, toCurrency, rate, effectiveDate, source } = req.body;
    if (!fromCurrency || !toCurrency || !rate || !effectiveDate) {
      return apiResponse.badRequest(res, 'fromCurrency, toCurrency, rate, effectiveDate required');
    }
    const result = await setExchangeRate(companyId,
      { fromCurrency, toCurrency, rate: Number(rate), effectiveDate, source },
      userId
    );
    return apiResponse.success(res, result);
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'POST']);
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withCompany(withErrorHandler(handler as any));

/**
 * EFT File Generation API
 * POST: generate EFT file for a batch payment
 */
import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import {
  generateStandardBankACB, generateFNBEFT, generateABSAEFT,
  generateNedbankEFT, generateCapitecEFT, validateEFTBatch,
  type EFTBatchHeader, type EFTPayment,
} from '@/modules/accounting/services/eftService';

type Row = Record<string, unknown>;

const GENERATORS: Record<string, typeof generateStandardBankACB> = {
  standard_bank: generateStandardBankACB,
  fnb: generateFNBEFT,
  absa: generateABSAEFT,
  nedbank: generateNedbankEFT,
  capitec: generateCapitecEFT,
};

async function handler(req: CompanyApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') return apiResponse.methodNotAllowed(res, req.method!, ['POST']);

  const { batchId, bank } = req.body;
  if (!batchId) return apiResponse.badRequest(res, 'batchId is required');
  if (!bank || !GENERATORS[bank]) return apiResponse.badRequest(res, `Invalid bank. Supported: ${Object.keys(GENERATORS).join(', ')}`);

  // Get batch details
  const batches = await sql`SELECT * FROM supplier_payment_batches WHERE id = ${batchId}` as Row[];
  if (!batches[0]) return apiResponse.notFound(res, 'Batch', batchId);

  // Get payments in batch
  const payments = await sql`
    SELECT sp.*, s.name as supplier_name, s.bank_account_number, s.bank_branch_code, s.bank_account_type, s.bank_name
    FROM supplier_payments sp
    JOIN suppliers s ON sp.supplier_id = s.id
    WHERE sp.batch_id = ${batchId}
    ORDER BY sp.created_at
  ` as Row[];

  if (payments.length === 0) return apiResponse.badRequest(res, 'No payments in batch');

  // Build EFT header and payments
  const header: EFTBatchHeader = {
    companyName: String(batches[0].company_name || (await sql`SELECT name FROM companies WHERE id = ${req.companyId} LIMIT 1` as Row[])[0]?.name || 'Unknown Company'),
    bankAccountNumber: String(batches[0].bank_account_number || ''),
    branchCode: String(batches[0].bank_branch_code || ''),
    accountType: 'current',
    batchReference: String(batches[0].batch_number || batchId),
    actionDate: String(batches[0].payment_date || new Date().toISOString().split('T')[0]),
  };

  const eftPayments: EFTPayment[] = payments.map((p: any) => ({
    beneficiaryName: String(p.supplier_name || ''),
    beneficiaryAccountNumber: String(p.bank_account_number || ''),
    beneficiaryBranchCode: String(p.bank_branch_code || ''),
    beneficiaryAccountType: (p.bank_account_type || 'current') as any,
    amount: Number(p.amount || 0),
    reference: String(p.reference || p.id || ''),
    beneficiaryBank: String(p.bank_name || bank),
  }));

  // Validate
  const validation = validateEFTBatch(header, eftPayments);

/**
 * Active Announcements API — Customer-facing
 * GET /api/announcements/active
 * Returns currently active announcements for the authenticated user's company.
 * Filters by target: 'all', or 'company' (matching company_id), or 'plan' (matching plan_id).
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import type { Announcement } from '@/modules/admin/types/admin.types';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

function toIso(v: unknown): string | null {
  if (v == null) return null;
  if (v instanceof Date) return v.toISOString();
  return v as string;
}

function rowToAnnouncement(r: Row): Announcement {
  return {
    id:            r.id as string,
    title:         r.title as string,
    message:       r.message as string,
    type:          r.type as string,
    target:        r.target as string,
    target_ids:    (r.target_ids ?? []) as string[],
    starts_at:     toIso(r.starts_at) as string,
    ends_at:       toIso(r.ends_at),
    is_dismissible: r.is_dismissible as boolean,
    created_by:    r.created_by as string,
    created_at:    toIso(r.created_at) as string,
  };
}

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method ?? 'UNKNOWN', ['GET']);
  }

  const { companyId } = req as CompanyApiRequest;

  try {
    // Fetch the company's plan_id for plan-targeted announcements
    const [companyRow] = await sql`
      SELECT s.plan_id
      FROM companies c
      LEFT JOIN subscriptions s ON s.company_id = c.id
        AND s.status IN ('active', 'trial')
      WHERE c.id = ${companyId}
      LIMIT 1
    `;
    const planId: string | null = (companyRow?.plan_id as string | null) ?? null;

    const rows = await sql`
      SELECT *
      FROM system_announcements
      WHERE starts_at <= NOW()
        AND (ends_at IS NULL OR ends_at >= NOW())
        AND (
          target = 'all'
          OR (target = 'company' AND ${companyId} = ANY(target_ids))
          OR (
            target = 'plan'
            AND ${planId}::uuid IS NOT NULL
            AND ${planId}::uuid = ANY(target_ids)
          )
        )
      ORDER BY starts_at DESC
    `;

    return apiResponse.success(res, rows.map(rowToAnnouncement));
  } catch (err) {
    log.error('Failed to fetch active announcements', { companyId, error: err }, 'announcements-api');
    return apiResponse.badRequest(res, 'Failed to fetch active announcements');
  }
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withCompany(withErrorHandler(handler as any) as any);

/**
 * Feature Check API
 * GET /api/features/check?code=payroll
 * Customer-facing endpoint — not admin-only. Returns whether the current company
 * has access to a given feature flag. Used by the FeatureGate component.
 */

import type { NextApiResponse } from 'next';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { hasFeature } from '@/modules/admin/services/featureFlagService';

async function handler(req: CompanyApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET']);
  }

  const code = req.query.code as string | undefined;
  if (!code) return apiResponse.badRequest(res, 'code query param required');

  const enabled = await hasFeature(req.companyId, code);
  return apiResponse.success(res, { code, enabled });
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withCompany(withErrorHandler(handler as any));

