/**
 * Client Portal — Payment Link API
 * GET  — get payment link details by token
 * POST — create a new payment link for an invoice
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { createPaymentLink, getPaymentLink } from '@/modules/accounting/services/portalService';
import { generatePayFastForm } from '@/modules/accounting/services/paymentGatewayService';
import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method === 'GET') {
    const token = req.query.token as string;
    if (!token) return apiResponse.badRequest(res, 'token is required');
    const link = await getPaymentLink(token);
    if (!link) return apiResponse.notFound(res, 'Payment link');

    // Enrich with invoice details and PayFast form data
    const enriched: Record<string, unknown> = { ...link };
    try {
      const invoiceRows = (await sql`
        SELECT ci.invoice_number, ci.due_date, ci.online_payment_enabled, ci.company_id,
               co.name AS company_name
        FROM customer_invoices ci
        LEFT JOIN companies co ON co.id = ci.company_id
        WHERE ci.id = ${link.invoiceId}::UUID
      `) as Row[];

      if (invoiceRows[0]) {
        enriched.invoiceNumber = invoiceRows[0].invoice_number;
        enriched.dueDate = invoiceRows[0].due_date;
        enriched.companyName = invoiceRows[0].company_name;

        // Generate PayFast form data if online payment is enabled
        if (invoiceRows[0].online_payment_enabled) {
          const appUrl = process.env.NEXT_PUBLIC_APP_URL || 'http://localhost:3101';
          const companyId = invoiceRows[0].company_id as string;
          try {
            const formData = await generatePayFastForm(
              companyId,
              link.invoiceId,
              `${appUrl}/portal/pay/${token}?payment_status=success`,
              `${appUrl}/portal/pay/${token}?payment_status=cancelled`,
              `${appUrl}/api/accounting/payment-gateway-itn`,
            );
            enriched.payfastFormData = formData;
          } catch (e) {
            log.error('Failed to generate PayFast form for portal', e instanceof Error ? { message: e.message } : { error: e }, 'PaymentLink');
          }
        }
      }
    } catch (e) {
      log.error('Failed to enrich payment link', e instanceof Error ? { message: e.message } : { error: e }, 'PaymentLink');
    }

    return apiResponse.success(res, enriched);
  }

  if (req.method === 'POST') {
    const { invoiceId, clientId, amount } = req.body;
    if (!invoiceId || !clientId || !amount) {
      return apiResponse.badRequest(res, 'invoiceId, clientId, and amount are required');
    }
    const token = await createPaymentLink(invoiceId, clientId, Number(amount));
    return apiResponse.success(res, { token, url: `/portal/pay/${token}` });
  }

  return apiResponse.methodNotAllowed(res, req.method!, ['GET', 'POST']);
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withAuth(withErrorHandler(handler as any));

}

export async function listPortalUsers(clientId?: string): Promise<PortalUser[]> {
  const rows = clientId
    ? (await sql`SELECT * FROM portal_access WHERE client_id = ${clientId}::UUID ORDER BY name`) as Row[]
    : (await sql`SELECT * FROM portal_access ORDER BY name`) as Row[];
  return rows.map(mapPortalUser);
}

// ── Portal Data ──────────────────────────────────────────────────────────────

export async function getClientInvoices(clientId: string): Promise<PortalInvoice[]> {
  const rows = (await sql`
    SELECT id, invoice_number, invoice_date, due_date, total,
           COALESCE(amount_paid, 0) AS amount_paid,
           (total - COALESCE(amount_paid, 0)) AS balance,
           status
    FROM customer_invoices
    WHERE client_id = ${clientId}::UUID
      AND status NOT IN ('draft', 'cancelled')
    ORDER BY invoice_date DESC
  `) as Row[];

  return rows.map((r: Row) => ({
    id: r.id,
    invoiceNumber: r.invoice_number,
    invoiceDate: r.invoice_date,
    dueDate: r.due_date,
    total: Number(r.total),
    amountPaid: Number(r.amount_paid),
    balance: Number(r.balance),
    status: r.status,
  }));
}

export async function getClientStatement(clientId: string, asOfDate: string): Promise<PortalStatement> {
  // Get client info
  const clients = (await sql`SELECT name, email FROM customers WHERE id = ${clientId}::UUID`) as Row[];
  const client = clients[0] || { name: 'Unknown', email: '' };

  // Get all transactions for this client
  const rows = (await sql`
    SELECT invoice_date AS date, invoice_number AS reference,
           'Invoice' AS description, total AS debit, 0 AS credit
    FROM customer_invoices
    WHERE client_id = ${clientId}::UUID AND status NOT IN ('draft', 'cancelled')
      AND invoice_date <= ${asOfDate}::DATE
    UNION ALL
    SELECT payment_date AS date, reference AS reference,
           'Payment' AS description, 0 AS debit, amount AS credit
    FROM customer_payments
    WHERE client_id = ${clientId}::UUID AND status = 'posted'
      AND payment_date <= ${asOfDate}::DATE
    ORDER BY date ASC
  `) as Row[];

  let runningBalance = 0;
  const transactions = rows.map((r: Row) => {
    const debit = Number(r.debit);
    const credit = Number(r.credit);
    runningBalance += debit - credit;
    return {
      date: r.date,
      reference: r.reference || '',
      description: r.description,
      debit,
      credit,
      balance: runningBalance,
    };
  });

  return {
    clientName: client.name,
    clientEmail: client.email || '',
    asOfDate,
    openingBalance: 0,
    transactions,
    closingBalance: runningBalance,
  };
}

// ── Payment Links ────────────────────────────────────────────────────────────

export async function createPaymentLink(invoiceId: string, clientId: string, amount: number): Promise<string> {
  const rows = (await sql`
    INSERT INTO portal_payment_links (invoice_id, client_id, amount)
    VALUES (${invoiceId}::UUID, ${clientId}::UUID, ${amount})
    RETURNING token
  `) as Row[];
  return rows[0].token;
}

export async function getPaymentLink(token: string): Promise<{
  invoiceId: string;
  clientId: string;
  amount: number;
  status: string;
  expiresAt: string;
} | null> {
  const rows = (await sql`
    SELECT * FROM portal_payment_links WHERE token = ${token} AND status = 'active' AND expires_at > NOW()
  `) as Row[];
  if (!rows[0]) return null;
  return {
    invoiceId: rows[0].invoice_id,
    clientId: rows[0].client_id,
    amount: Number(rows[0].amount),
    status: rows[0].status,
    expiresAt: rows[0].expires_at,
  };
}

export async function markPaymentLinkPaid(token: string, reference: string): Promise<void> {
  await sql`
    UPDATE portal_payment_links SET status = 'paid', paid_at = NOW(), payment_reference = ${reference}
    WHERE token = ${token}
  `;
}

// ── Mappers ──────────────────────────────────────────────────────────────────

