// ═══════════════════════════════════════════════════════════════════
//  5. LOW FINDINGS
// ═══════════════════════════════════════════════════════════════════
spacer(20);
heading('5. Low Findings', 20, C.green);
spacer(5);

tableHeader([
  { label: '#', width: 25 },
  { label: 'SEV', width: 71 },
