/**
 * EFT File Generation API
 * POST: generate EFT file for a batch payment
 */
import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import {
  generateStandardBankACB, generateFNBEFT, generateABSAEFT,
  generateNedbankEFT, generateCapitecEFT, validateEFTBatch,
  type EFTBatchHeader, type EFTPayment,
} from '@/modules/accounting/services/eftService';

type Row = Record<string, unknown>;

const GENERATORS: Record<string, typeof generateStandardBankACB> = {
  standard_bank: generateStandardBankACB,
  fnb: generateFNBEFT,
  absa: generateABSAEFT,
  nedbank: generateNedbankEFT,
  capitec: generateCapitecEFT,
};

async function handler(req: CompanyApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') return apiResponse.methodNotAllowed(res, req.method!, ['POST']);

  const { batchId, bank } = req.body;
  if (!batchId) return apiResponse.badRequest(res, 'batchId is required');
  if (!bank || !GENERATORS[bank]) return apiResponse.badRequest(res, `Invalid bank. Supported: ${Object.keys(GENERATORS).join(', ')}`);

  // Get batch details
  const batches = await sql`SELECT * FROM supplier_payment_batches WHERE id = ${batchId}` as Row[];
  if (!batches[0]) return apiResponse.notFound(res, 'Batch', batchId);

  // Get payments in batch
  const payments = await sql`
    SELECT sp.*, s.name as supplier_name, s.bank_account_number, s.bank_branch_code, s.bank_account_type, s.bank_name
    FROM supplier_payments sp
    JOIN suppliers s ON sp.supplier_id = s.id
    WHERE sp.batch_id = ${batchId}
    ORDER BY sp.created_at
  ` as Row[];

  if (payments.length === 0) return apiResponse.badRequest(res, 'No payments in batch');

  // Build EFT header and payments
  const header: EFTBatchHeader = {
    companyName: String(batches[0].company_name || (await sql`SELECT name FROM companies WHERE id = ${req.companyId} LIMIT 1` as Row[])[0]?.name || 'Unknown Company'),
    bankAccountNumber: String(batches[0].bank_account_number || ''),
    branchCode: String(batches[0].bank_branch_code || ''),
    accountType: 'current',
    batchReference: String(batches[0].batch_number || batchId),
    actionDate: String(batches[0].payment_date || new Date().toISOString().split('T')[0]),
  };

  const eftPayments: EFTPayment[] = payments.map((p: any) => ({
    beneficiaryName: String(p.supplier_name || ''),
    beneficiaryAccountNumber: String(p.bank_account_number || ''),
    beneficiaryBranchCode: String(p.bank_branch_code || ''),
    beneficiaryAccountType: (p.bank_account_type || 'current') as any,
    amount: Number(p.amount || 0),
    reference: String(p.reference || p.id || ''),
    beneficiaryBank: String(p.bank_name || bank),
  }));

  // Validate
  const validation = validateEFTBatch(header, eftPayments);
  if (!validation.valid) return apiResponse.badRequest(res, 'EFT validation failed', validation.errors);

  // Generate
  const generator = GENERATORS[bank]!;
  const fileContent = generator(header, eftPayments);
  const filename = `EFT-${bank}-${header.batchReference}-${header.actionDate}.txt`;

  log.info('EFT file generated', { bank, batchId, payments: payments.length, total: validation.totalAmount }, 'accounting');

  return apiResponse.success(res, {
    filename,
    content: fileContent,
    bank,
    paymentCount: validation.paymentCount,
    totalAmount: validation.totalAmount,
  });
}

export default withCompany(withErrorHandler(handler as any));

/**
 * Document Validation API
 * POST /api/accounting/document-validation
 * Body: { entityType, entityId, documentId }
 * Validates VLM-extracted data against the entity record.
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import { sql } from '@/lib/neon';
import {
  validateInvoiceDocument,
  validatePaymentReceipt,
} from '@/modules/accounting/services/documentValidationService';
import type { ExtractedDocument } from '@/modules/accounting/types/documentCapture.types';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = Record<string, any>;

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['POST']);
  }

  const { companyId } = req as CompanyApiRequest;
  const { entityType, entityId, documentId } = req.body as {
    entityType?: string;
    entityId?: string;
    documentId?: string;
  };

  if (!entityType || !entityId || !documentId) {
    return apiResponse.badRequest(res, 'entityType, entityId, and documentId are required');
  }

  // Fetch extracted data from document
  const [doc] = (await sql`
    SELECT extracted_data FROM procurement_documents
    WHERE id = ${documentId}::uuid
  `) as Row[];

  if (!doc?.extracted_data) {
    return apiResponse.badRequest(res, 'Document has no extracted data. VLM extraction may not have completed.');
  }

  const extracted = doc.extracted_data as ExtractedDocument;
  let result;

  if (entityType === 'supplier_invoice') {
    const [invoice] = (await sql`
      SELECT invoice_number, total_amount, tax_amount as vat_amount, tax_rate
      FROM supplier_invoices WHERE id = ${entityId}::uuid
    `) as Row[];
    if (!invoice) return apiResponse.notFound(res, 'Supplier invoice', entityId);

    // Get supplier name
    const [supplier] = (await sql`
      SELECT name FROM suppliers WHERE id = (
        SELECT supplier_id FROM supplier_invoices WHERE id = ${entityId}::uuid
      )
    `) as Row[];

    result = validateInvoiceDocument(extracted, {
      invoiceNumber: invoice.invoice_number,
      totalAmount: parseFloat(invoice.total_amount),
      vatAmount: invoice.vat_amount ? parseFloat(invoice.vat_amount) : undefined,
      taxRate: invoice.tax_rate ? parseFloat(invoice.tax_rate) : undefined,
      vendorName: supplier?.name,
    });
  } else if (entityType === 'customer_invoice') {
    const [invoice] = (await sql`
      SELECT invoice_number, total_amount, tax_amount, invoice_date
      FROM customer_invoices WHERE id = ${entityId}::uuid
    `) as Row[];
    if (!invoice) return apiResponse.notFound(res, 'Customer invoice', entityId);

    result = validateInvoiceDocument(extracted, {
      invoiceNumber: invoice.invoice_number,
      totalAmount: parseFloat(invoice.total_amount),
      vatAmount: invoice.tax_amount ? parseFloat(invoice.tax_amount) : undefined,
      invoiceDate: invoice.invoice_date ? new Date(invoice.invoice_date).toISOString().split('T')[0] : undefined,
    });
  } else if (entityType === 'supplier_payment' || entityType === 'customer_payment') {
    const [payment] = entityType === 'supplier_payment'
      ? (await sql`SELECT total_amount, payment_date, reference FROM supplier_payments WHERE id = ${entityId}::uuid`) as Row[]
      : (await sql`SELECT total_amount, payment_date, reference FROM customer_payments WHERE id = ${entityId}::uuid`) as Row[];
    if (!payment) return apiResponse.notFound(res, entityType, entityId);

    result = validatePaymentReceipt(extracted, {
      totalAmount: parseFloat(payment.total_amount),
      paymentDate: payment.payment_date ? new Date(payment.payment_date).toISOString().split('T')[0] : undefined,
      reference: payment.reference,
    });
  } else {
    return apiResponse.badRequest(res, `Unsupported entity type: ${entityType}`);
  }

  // Store validation result
  // @ts-expect-error — auth middleware attaches user
  const userId: string | null = req.user?.id ?? null;

  await sql`
    INSERT INTO document_validation_results (
      company_id, document_id, entity_type, entity_id,
      validation_type, result_data, discrepancy_count, validated_by
    ) VALUES (
      ${companyId}::uuid, ${documentId}::uuid, ${entityType}, ${entityId}::uuid,
      'vlm_document_match', ${JSON.stringify(result)}::jsonb,
      ${result.discrepancies.length}, ${userId}
    )
  `;

  log.info('Document validation completed', {
    entityType,
    entityId,
    documentId,
    valid: result.valid,
    discrepancies: result.discrepancies.length,
  }, 'document-validation');

  return apiResponse.success(res, result);
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withCompany(withErrorHandler(handler as any));

/**
 * Purchase Orders API — CRUD
 */
import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { validatePurchaseOrder, calculatePOTotals, generatePONumber } from '@/modules/accounting/services/procurementService';

type Row = Record<string, unknown>;

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  const companyId = (req as any).companyId as string | undefined;

  if (req.method === 'GET') {
    const { status, supplierId } = req.query;
    let rows: Row[];
    if (status) {
      rows = await sql`SELECT po.*, s.name as supplier_name FROM purchase_orders po LEFT JOIN suppliers s ON po.supplier_id = s.id WHERE po.status = ${String(status)} ORDER BY po.created_at DESC LIMIT 200` as Row[];
    } else if (supplierId) {
      rows = await sql`SELECT po.*, s.name as supplier_name FROM purchase_orders po LEFT JOIN suppliers s ON po.supplier_id = s.id WHERE po.supplier_id = ${String(supplierId)} ORDER BY po.created_at DESC LIMIT 200` as Row[];
    } else {
      rows = await sql`SELECT po.*, s.name as supplier_name FROM purchase_orders po LEFT JOIN suppliers s ON po.supplier_id = s.id ORDER BY po.created_at DESC LIMIT 200` as Row[];
    }
    return apiResponse.success(res, rows);
  }

  if (req.method === 'POST') {
    const body = req.body;
    const validation = validatePurchaseOrder(body);
    if (!validation.success) return apiResponse.validationError(res, Object.fromEntries((validation.errors || []).map(e => [e.field, e.message])));

    const totals = calculatePOTotals(body.items);
    const countRes = await sql`SELECT COUNT(*) as cnt FROM purchase_orders` as Row[];
    const poNumber = generatePONumber(Number((countRes[0] as any)?.cnt || 0));

    const inserted = await sql`
      INSERT INTO purchase_orders (company_id, po_number, supplier_id, order_date, expected_delivery_date, subtotal, tax_amount, total, notes, reference, created_by)
      VALUES (${companyId || null}, ${poNumber}, ${body.supplierId}, ${body.orderDate || new Date().toISOString().split('T')[0]}, ${body.expectedDeliveryDate || null}, ${totals.subtotal}, ${totals.taxAmount}, ${totals.total}, ${body.notes || null}, ${body.reference || null}, ${String(req.user.id)})
      RETURNING *
    ` as Row[];

    const poId = String(inserted[0]?.id);
    for (let i = 0; i < body.items.length; i++) {
      const item = body.items[i];
      const lineTotal = Math.round(item.quantity * item.unitPrice * 100) / 100;
      const lineTax = Math.round(lineTotal * (item.taxRate || 15) / 100 * 100) / 100;
      await sql`INSERT INTO po_items (purchase_order_id, product_id, description, quantity, unit_price, tax_rate, line_total, tax_amount, sort_order) VALUES (${poId}, ${item.productId || null}, ${item.description}, ${item.quantity}, ${item.unitPrice}, ${item.taxRate || 15}, ${lineTotal}, ${lineTax}, ${i})`;
    }

    log.info('Purchase order created', { poNumber, supplier: body.supplierId, total: totals.total }, 'accounting');
    return apiResponse.created(res, { ...inserted[0], items: body.items });
  }

  return apiResponse.methodNotAllowed(res, req.method!, ['GET', 'POST']);
}

export default withCompany(withErrorHandler(handler as any));

/**
 * Project Time Entries API
 */
import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { validateTimeEntry, calculateBillableAmount } from '@/modules/accounting/services/projectAccountingService';

type Row = Record<string, unknown>;

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  if (req.method === 'GET') {
    const { projectId, employeeId } = req.query;
    let rows: Row[];
    if (projectId) {
      rows = await sql`SELECT t.*, e.first_name, e.last_name, p.name as project_name FROM project_time_entries t LEFT JOIN employees e ON t.employee_id = e.id LEFT JOIN projects p ON t.project_id = p.id WHERE t.project_id = ${String(projectId)} ORDER BY t.entry_date DESC` as Row[];
    } else if (employeeId) {
      rows = await sql`SELECT t.*, p.name as project_name FROM project_time_entries t LEFT JOIN projects p ON t.project_id = p.id WHERE t.employee_id = ${String(employeeId)} ORDER BY t.entry_date DESC LIMIT 200` as Row[];
    } else {
      rows = await sql`SELECT t.*, e.first_name, e.last_name, p.name as project_name FROM project_time_entries t LEFT JOIN employees e ON t.employee_id = e.id LEFT JOIN projects p ON t.project_id = p.id ORDER BY t.entry_date DESC LIMIT 200` as Row[];
    }
    return apiResponse.success(res, rows);
  }

  if (req.method === 'POST') {
    const body = req.body;
    const validation = validateTimeEntry(body);
    if (!validation.success) return apiResponse.validationError(res, Object.fromEntries((validation.errors || []).map(e => [e.field, e.message])));

    const billableAmount = body.billable ? calculateBillableAmount(body.hours, body.hourlyRate || 0) : 0;

    const inserted = await sql`
      INSERT INTO project_time_entries (project_id, task_id, employee_id, entry_date, hours, hourly_rate, billable_amount, description, is_billable, created_by)
      VALUES (${body.projectId}, ${body.taskId || null}, ${body.employeeId}, ${body.date}, ${body.hours}, ${body.hourlyRate || 0}, ${billableAmount}, ${body.description}, ${body.billable ?? true}, ${String(req.user.id)})
      RETURNING *
    ` as Row[];

    log.info('Time entry created', { projectId: body.projectId, hours: body.hours }, 'accounting');
    return apiResponse.created(res, inserted[0]);
  }

  return apiResponse.methodNotAllowed(res, req.method!, ['GET', 'POST']);
}
export default withCompany(withErrorHandler(handler as any));

/**
 * Stock Levels API — current stock per product
 */
import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { sql } from '@/lib/neon';
type Row = Record<string, unknown>;

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') return apiResponse.methodNotAllowed(res, req.method!, ['GET']);
  const { belowReorder } = req.query;
  let rows: Row[];
  if (belowReorder === 'true') {
    rows = await sql`SELECT p.id, p.code, p.name, p.current_stock, p.reorder_level, p.reorder_quantity, p.avg_cost, p.selling_price, p.unit, p.category FROM products p WHERE p.is_active = true AND p.product_type = 'inventory' AND p.current_stock <= p.reorder_level ORDER BY p.current_stock ASC` as Row[];
  } else {
    rows = await sql`SELECT p.id, p.code, p.name, p.current_stock, p.reorder_level, p.reorder_quantity, p.avg_cost, p.selling_price, p.unit, p.category, (p.current_stock * p.avg_cost) as stock_value FROM products p WHERE p.is_active = true AND p.product_type = 'inventory' ORDER BY p.name` as Row[];
  }
  const summary = {
    totalProducts: rows.length,
    totalStockValue: rows.reduce((s, r) => s + Number(r.stock_value || 0), 0),
    belowReorder: rows.filter(r => Number(r.current_stock) <= Number(r.reorder_level)).length,
  };
  return apiResponse.success(res, { items: rows, summary });
}
export default withCompany(withErrorHandler(handler as any));

/**
 * IRP5 Certificate Generation API
 * POST: generate IRP5 for an employee or batch
 */
import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { buildIRP5Certificate, validateIRP5Data, type IRP5EmployeeData } from '@/modules/accounting/services/irp5Service';

type Row = Record<string, unknown>;

async function handler(req: CompanyApiRequest, res: NextApiResponse) {
  if (req.method === 'GET') {
    // List generated IRP5 certificates
    const { taxYear } = req.query;
    const yr = taxYear ? Number(taxYear) : new Date().getFullYear();
    const rows = await sql`
      SELECT e.id, e.first_name, e.last_name, e.id_number, e.tax_number,
        COALESCE(SUM(ps.gross_pay), 0) as total_gross,
        COALESCE(SUM(ps.paye), 0) as total_paye,
        COALESCE(SUM(ps.uif_employee), 0) as total_uif
      FROM employees e
      LEFT JOIN payslips ps ON ps.employee_id = e.id
      LEFT JOIN payroll_runs pr ON ps.payroll_run_id = pr.id AND EXTRACT(YEAR FROM pr.period_end) = ${yr}
      GROUP BY e.id, e.first_name, e.last_name, e.id_number, e.tax_number
      ORDER BY e.last_name
    ` as Row[];
    return apiResponse.success(res, rows);
  }

  if (req.method === 'POST') {
    const { employeeId, taxYear } = req.body;
    if (!employeeId) return apiResponse.badRequest(res, 'employeeId is required');
    const yr = taxYear || new Date().getFullYear();

    // Get employee
    const employees = await sql`SELECT * FROM employees WHERE id = ${employeeId}` as Row[];
    if (!employees[0]) return apiResponse.notFound(res, 'Employee', employeeId);
    const emp = employees[0] as any;

    // Validate
    const validation = validateIRP5Data({
      employeeName: `${emp.first_name} ${emp.last_name}`,
      idNumber: emp.id_number || '',
      taxNumber: emp.tax_number || '',
      grossSalary: 1,
      paye: 1,
    });
    if (!validation.valid) return apiResponse.badRequest(res, 'IRP5 validation failed', validation.errors);

    // Aggregate payslip data for the tax year
    const payslips = await sql`
      SELECT
        COALESCE(SUM(ps.gross_pay), 0) as gross_salary,
        COALESCE(SUM(ps.paye), 0) as paye,
        COALESCE(SUM(ps.uif_employee), 0) as uif_employee,
        COALESCE(SUM(ps.uif_employer), 0) as uif_employer,
        COALESCE(SUM(ps.sdl), 0) as sdl
      FROM payslips ps
      JOIN payroll_runs pr ON ps.payroll_run_id = pr.id
      WHERE ps.employee_id = ${employeeId}
        AND pr.period_end >= ${`${yr - 1}-03-01`}
        AND pr.period_end <= ${`${yr}-02-28`}
    ` as Row[];

    const data = payslips[0] as any || {};
    const employeeData: IRP5EmployeeData = {
      grossSalary: Number(data.gross_salary || 0),
      commission: 0,
      overtime: 0,
      bonus: 0,
      travelAllowance: 0,
      pensionContribEmployee: 0,
      medicalAidEmployee: 0,
      retirementAnnuity: 0,
      paye: Number(data.paye || 0),
      uifEmployee: Number(data.uif_employee || 0),
      uifEmployer: Number(data.uif_employer || 0),
      sdl: Number(data.sdl || 0),
    };

    // Fetch company details for employer info
    const companyRows = await sql`SELECT name, vat_number FROM companies WHERE id = ${req.companyId}` as Row[];
    const company = companyRows[0] as Record<string, string> | undefined;

    const cert = buildIRP5Certificate({
      employeeData,
      employeeName: `${emp.first_name} ${emp.last_name}`,
      idNumber: emp.id_number || '',
      taxNumber: emp.tax_number || '',
      employerName: String(company?.name || 'Unknown Company'),
      employerPayeRef: String(company?.vat_number || ''),
      taxYear: yr,
      periodStart: `${yr - 1}-03-01`,
      periodEnd: `${yr}-02-28`,
    });

    log.info('IRP5 generated', { employeeId, taxYear: yr }, 'payroll');
    return apiResponse.success(res, cert);
  }

  return apiResponse.methodNotAllowed(res, req.method!, ['GET', 'POST']);
}

export default withCompany(withErrorHandler(handler as any));

/**
 * Leave Balances API
 */
import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { sql } from '@/lib/neon';
type Row = Record<string, unknown>;

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') return apiResponse.methodNotAllowed(res, req.method!, ['GET']);
  const { employeeId, year } = req.query;
  const yr = year ? Number(year) : new Date().getFullYear();
  if (employeeId) {
    const rows = await sql`SELECT lb.*, lt.name as leave_type_name FROM leave_balances lb JOIN leave_types lt ON lb.leave_type_id = lt.id WHERE lb.employee_id = ${String(employeeId)} AND lb.year = ${yr} ORDER BY lt.name` as Row[];
    return apiResponse.success(res, rows);
  }
  const rows = await sql`SELECT lb.*, lt.name as leave_type_name, e.first_name, e.last_name FROM leave_balances lb JOIN leave_types lt ON lb.leave_type_id = lt.id JOIN employees e ON lb.employee_id = e.id WHERE lb.year = ${yr} ORDER BY e.last_name, lt.name` as Row[];
  return apiResponse.success(res, rows);
}
export default withCompany(withErrorHandler(handler as any));

/**
 * Asset Register Report API
 * GET: full asset register with depreciation details
 */

import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { sql } from '@/lib/neon';

type Row = Record<string, unknown>;

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method!, ['GET']);
  }

  const { asOf } = req.query;
  const asOfDate = asOf ? String(asOf) : new Date().toISOString().split('T')[0];

  const rows = await sql`
    SELECT a.*, ac.name as category_name, ac.sars_rate, ac.sars_years,
      COALESCE(a.accumulated_depreciation, 0) as total_depreciation,
      COALESCE(a.current_book_value, a.purchase_price) as net_book_value
    FROM assets a
    LEFT JOIN asset_categories ac ON a.category_id = ac.id
    WHERE a.purchase_date <= ${asOfDate}
    ORDER BY a.category, a.asset_number
  ` as Row[];

  const summary = {
    totalAssets: rows.length,
    totalCost: rows.reduce((s, r) => s + Number(r.purchase_price || 0), 0),
    totalAccumulatedDepreciation: rows.reduce((s, r) => s + Number(r.total_depreciation || 0), 0),
    totalBookValue: rows.reduce((s, r) => s + Number(r.net_book_value || 0), 0),
    asOfDate,
  };

  return apiResponse.success(res, { assets: rows, summary });
}

export default withCompany(withErrorHandler(handler as any));

/**
 * Company Groups API
 * GET    — list groups / get single group
 * POST   — create group / add member / manage COA
 * PUT    — update group / update member
 * DELETE — remove member / delete group
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth, type AuthenticatedNextApiRequest } from '@/lib/auth';
import {
  listGroups,
  getGroup,
  createGroup,
  updateGroup,
  deleteGroup,
  addMember,
  updateMember,
  removeMember,
  getGroupMembers,
  getGroupAccounts,
  createGroupAccount,
  updateGroupAccount,
  deleteGroupAccount,
  autoGenerateGroupCOA,
  getCoaMappings,
  setCoaMapping,
  removeCoaMapping,
  autoMapAccounts,
  getUnmappedAccounts,
} from '@/modules/accounting/services/groupCompanyService';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  const userId = (req as AuthenticatedNextApiRequest).user.id;
  const action = (req.query.action || req.body?.action) as string | undefined;

  // ── GET ────────────────────────────────────────────────────────────────────
  if (req.method === 'GET') {
    const groupId = req.query.group_id as string | undefined;

    if (action === 'members' && groupId) {
      const members = await getGroupMembers(groupId);
      return apiResponse.success(res, { items: members });
    }

    if (action === 'accounts' && groupId) {
      const accounts = await getGroupAccounts(groupId);
      return apiResponse.success(res, { items: accounts });
    }

    if (action === 'mappings' && groupId) {
      const companyId = req.query.company_id as string | undefined;
      const mappings = await getCoaMappings(groupId, companyId);
      return apiResponse.success(res, { items: mappings });
    }

    if (action === 'unmapped' && groupId) {
      const companyId = req.query.company_id as string;
      if (!companyId) return apiResponse.badRequest(res, 'company_id required');
      const unmapped = await getUnmappedAccounts(groupId, companyId);
      return apiResponse.success(res, { items: unmapped });
    }

    if (groupId) {
      const group = await getGroup(groupId);
      if (!group) return apiResponse.notFound(res, 'Group');
      return apiResponse.success(res, group);
    }

    const groups = await listGroups();
    return apiResponse.success(res, { items: groups });
  }

  // ── POST ───────────────────────────────────────────────────────────────────
  if (req.method === 'POST') {
    if (action === 'add-member') {
      const { groupId, companyId, ownershipPct, consolidationMethod } = req.body;
      if (!groupId || !companyId) return apiResponse.badRequest(res, 'groupId and companyId required');
      const member = await addMember(groupId, companyId, {
        ownershipPct: ownershipPct ?? 100,
        consolidationMethod: consolidationMethod ?? 'full',
      });
      return apiResponse.success(res, member);
    }

    if (action === 'create-group-account') {
      const { groupId, accountCode, accountName, accountType, accountSubtype, parentAccountId, normalBalance, level, displayOrder } = req.body;
      if (!groupId || !accountCode || !accountName || !accountType) {
        return apiResponse.badRequest(res, 'groupId, accountCode, accountName, accountType required');
      }
      const account = await createGroupAccount(groupId, {
        accountCode, accountName, accountType, accountSubtype, parentAccountId, normalBalance, level, displayOrder,
      });
      return apiResponse.success(res, account);
    }

    if (action === 'auto-generate-coa') {
      const { groupId, sourceCompanyId } = req.body;
      if (!groupId || !sourceCompanyId) return apiResponse.badRequest(res, 'groupId and sourceCompanyId required');
      const count = await autoGenerateGroupCOA(groupId, sourceCompanyId);
      return apiResponse.success(res, { accountsCreated: count });
    }

    if (action === 'set-mapping') {
      const { groupId, companyId, companyAccountId, groupAccountId } = req.body;
      if (!groupId || !companyId || !companyAccountId || !groupAccountId) {
        return apiResponse.badRequest(res, 'groupId, companyId, companyAccountId, groupAccountId required');
      }
      const mapping = await setCoaMapping(groupId, companyId, companyAccountId, groupAccountId);
      return apiResponse.success(res, mapping);
    }

    if (action === 'auto-map') {
      const { groupId, companyId } = req.body;
      if (!groupId || !companyId) return apiResponse.badRequest(res, 'groupId and companyId required');
      const count = await autoMapAccounts(groupId, companyId);
      return apiResponse.success(res, { mappedCount: count });
    }

    // Default POST: create group
    const { name, holdingCompanyId, defaultCurrency, financialYearStart } = req.body;
    if (!name) return apiResponse.badRequest(res, 'name is required');
    const group = await createGroup({ name, holdingCompanyId, defaultCurrency, financialYearStart }, userId);
    return apiResponse.success(res, group);
  }

  // ── PUT ────────────────────────────────────────────────────────────────────
  if (req.method === 'PUT') {
    if (action === 'update-member') {
      const { memberId, ownershipPct, consolidationMethod } = req.body;
      if (!memberId) return apiResponse.badRequest(res, 'memberId required');
      await updateMember(memberId, { ownershipPct, consolidationMethod });
      return apiResponse.success(res, { updated: true });
    }

    if (action === 'update-group-account') {
      const { accountId, ...updates } = req.body;
      if (!accountId) return apiResponse.badRequest(res, 'accountId required');
      const account = await updateGroupAccount(accountId, updates);
      return apiResponse.success(res, account);
    }

    const { groupId, ...updates } = req.body;
    if (!groupId) return apiResponse.badRequest(res, 'groupId required');
    const group = await updateGroup(groupId, updates);
    return apiResponse.success(res, group);
  }

  // ── DELETE ─────────────────────────────────────────────────────────────────
  if (req.method === 'DELETE') {
    if (action === 'remove-member') {
      const memberId = req.query.member_id as string;
      if (!memberId) return apiResponse.badRequest(res, 'member_id required');
      await removeMember(memberId);
      return apiResponse.success(res, { removed: true });
    }

    if (action === 'remove-mapping') {
      const mappingId = req.query.mapping_id as string;
      if (!mappingId) return apiResponse.badRequest(res, 'mapping_id required');
      await removeCoaMapping(mappingId);
      return apiResponse.success(res, { removed: true });
    }

    if (action === 'delete-group-account') {
      const accountId = req.query.account_id as string;
      if (!accountId) return apiResponse.badRequest(res, 'account_id required');
      await deleteGroupAccount(accountId);
      return apiResponse.success(res, { deleted: true });
    }

    const groupId = req.query.group_id as string;
    if (!groupId) return apiResponse.badRequest(res, 'group_id required');
    await deleteGroup(groupId);
    return apiResponse.success(res, { deleted: true });
  }

  return apiResponse.methodNotAllowed(res, req.method!, ['GET', 'POST', 'PUT', 'DELETE']);
}

