}

// ═══════════════════════════════════════════════════════════════════
//  5. MEDIUM FINDINGS
// ═══════════════════════════════════════════════════════════════════
doc.addPage();
y = 50;

heading('5. Medium Findings — Before & After', 20, '#d97706');
spacer(5);

const mediums = [
  { id: 'M1', title: 'Company Groups — User-Controlled company_id', status: 'FIXED',
