}

// ═══════════════════════════════════════════════════════════════════
//  6. LOW FINDINGS
// ═══════════════════════════════════════════════════════════════════
spacer(10);
heading('6. Low Findings — Before & After', 20, C.green);
spacer(5);

const lows = [
