#!/usr/bin/env node
/**
 * Generate ISAFlow Penetration Test Report PDF
 * Uses ISAFlow CI: dark theme, teal accent, Inter font
 */

import PDFDocument from 'pdfkit';
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const OUTPUT = path.join(__dirname, '..', 'tmp', 'ISAFlow_Penetration_Test_Report_2026-03-30.pdf');
const LOGO = path.join(__dirname, '..', 'public', 'logo.png');

// ISAFlow CI Colors
const C = {
  dark: '#0f172a',
  darkAlt: '#1e293b',
  surface: '#334155',
  teal: '#14b8a6',
  tealDark: '#0d9488',
  white: '#ffffff',
  gray: '#94a3b8',
  lightGray: '#cbd5e1',
  red: '#ef4444',
  orange: '#f59e0b',
  yellow: '#fbbf24',
  green: '#22c55e',
  blue: '#3b82f6',
};

const doc = new PDFDocument({
  size: 'A4',
  bufferPages: true,
  margins: { top: 50, bottom: 50, left: 50, right: 50 },
  info: {
    Title: 'ISAFlow Security Penetration Test Report',
    Author: 'ISAFlow Security Audit Team',
    Subject: 'Full Codebase Security Assessment',
    CreationDate: new Date(),
  },
});

const stream = fs.createWriteStream(OUTPUT);
doc.pipe(stream);

const W = 495; // usable width
let y = 50;

// ─── Helper Functions ───
function hexToRGB(hex) {
  const r = parseInt(hex.slice(1, 3), 16);
  const g = parseInt(hex.slice(3, 5), 16);
  const b = parseInt(hex.slice(5, 7), 16);
  return [r, g, b];
}

function drawRect(x, yPos, w, h, color) {
  doc.save().rect(x, yPos, w, h).fill(color).restore();
}

function heading(text, size = 18, color = C.dark) {
  checkPage(size + 20);
  doc.fontSize(size).fillColor(color).text(text, 50, y, { width: W });
  y += size + 10;
}

function subheading(text, size = 13) {
  checkPage(size + 16);
  doc.fontSize(size).fillColor(C.tealDark).text(text, 50, y, { width: W });
  y += size + 8;
}

function para(text, size = 9.5, color = '#374151') {
  checkPage(size + 10);
  doc.fontSize(size).fillColor(color).text(text, 50, y, { width: W, lineGap: 3 });
  y = doc.y + 6;
}

function bullet(text, size = 9.5, indent = 15) {
  checkPage(size + 10);
  doc.fontSize(size).fillColor('#374151');
  doc.text('\u2022', 50 + indent, y);
  doc.text(text, 50 + indent + 12, y, { width: W - indent - 12, lineGap: 2 });
  y = doc.y + 4;
}

function spacer(h = 10) {
  y += h;
}

function line() {
  checkPage(10);
  doc.save().moveTo(50, y).lineTo(545, y).strokeColor(C.lightGray).lineWidth(0.5).stroke().restore();
  y += 8;
}

function checkPage(needed = 50) {
  if (y + needed > 780) {
    doc.addPage();
    y = 50;
  }
}

function severityColor(sev) {
  if (sev === 'CRITICAL') return C.red;
  if (sev === 'HIGH') return C.orange;
  if (sev === 'MEDIUM') return C.yellow;
  return C.green;
}

function severityBadge(sev, xPos, yPos) {
  const color = severityColor(sev);
  const w = doc.fontSize(7).widthOfString(sev) + 10;
  drawRect(xPos, yPos, w, 14, color);
  doc.fontSize(7).fillColor(C.white).text(sev, xPos + 5, yPos + 3);
  return w;
}

function findingRow(id, severity, issue, file) {
  checkPage(40);
  const rowY = y;
  // alternating bg
  if (parseInt(id) % 2 === 0) drawRect(48, rowY - 2, W + 4, 32, '#f8fafc');

  doc.fontSize(8).fillColor(C.dark).text(id, 52, rowY + 2, { width: 25 });
  severityBadge(severity, 77, rowY + 1);
  doc.fontSize(8).fillColor('#1e293b').text(issue, 148, rowY + 2, { width: 250, lineGap: 1 });
  doc.fontSize(7).fillColor(C.gray).text(file, 400, rowY + 2, { width: 145, lineGap: 1 });
  y = Math.max(doc.y + 6, rowY + 30);
}

function tableHeader(cols) {
  checkPage(25);
  drawRect(48, y - 2, W + 4, 20, C.darkAlt);
  let x = 52;
  for (const col of cols) {
    doc.fontSize(7.5).fillColor(C.teal).text(col.label, x, y + 2, { width: col.width });
    x += col.width;
  }
  y += 22;
}

// ═══════════════════════════════════════════════════════════════════
//  COVER PAGE
// ═══════════════════════════════════════════════════════════════════

// Dark header band
drawRect(0, 0, 595, 280, C.dark);

// Logo
if (fs.existsSync(LOGO)) {
  doc.image(LOGO, 50, 50, { width: 200 });
}

y = 140;
doc.fontSize(28).fillColor(C.white).text('Security Penetration Test', 50, y, { width: W });
y += 38;
doc.fontSize(28).fillColor(C.teal).text('Report', 50, y, { width: W });
y += 50;

// Accent line
drawRect(50, y, 80, 3, C.teal);
y += 20;

doc.fontSize(11).fillColor(C.gray).text('Full Codebase Security Assessment', 50, y);
y += 18;
doc.fontSize(11).fillColor(C.gray).text('ISAFlow Cloud Accounting Platform', 50, y);

// Meta block below dark band
y = 310;
const metaFields = [
  ['Date', '2026-03-30'],
  ['Classification', 'CONFIDENTIAL'],
  ['Prepared By', 'ISAFlow Security Audit Team (4 parallel agents)'],
  ['Target', 'ISAFlow v14.2.35 — https://app.isaflow.co.za'],
  ['Scope', '327 API routes, 159 services, all dependencies & config'],
  ['Method', 'Automated static analysis + architecture review'],
];

for (const [label, value] of metaFields) {
  doc.fontSize(9).fillColor(C.gray).text(label, 50, y, { width: 120 });
  doc.fontSize(9).fillColor(C.dark).text(value, 170, y, { width: 370 });
  y += 18;
}

// Severity summary boxes
y += 20;
const summaryBoxes = [
  { label: 'CRITICAL', count: 7, color: C.red },
  { label: 'HIGH', count: 9, color: C.orange },
  { label: 'MEDIUM', count: 11, color: C.yellow },
  { label: 'LOW', count: 7, color: C.green },
  { label: 'PASS', count: 8, color: C.blue },
];

let bx = 50;
for (const box of summaryBoxes) {
  drawRect(bx, y, 90, 55, '#f1f5f9');
  drawRect(bx, y, 90, 4, box.color);
  doc.fontSize(22).fillColor(C.dark).text(String(box.count), bx, y + 12, { width: 90, align: 'center' });
  doc.fontSize(8).fillColor(C.gray).text(box.label, bx, y + 38, { width: 90, align: 'center' });
  bx += 98;
}

// ═══════════════════════════════════════════════════════════════════
//  TABLE OF CONTENTS
// ═══════════════════════════════════════════════════════════════════
doc.addPage();
y = 50;

heading('Table of Contents', 20);
spacer(5);

const tocItems = [
  '1. Executive Summary',
  '2. Critical Findings (7)',
  '3. High Findings (9)',
  '4. Medium Findings (11)',
  '5. Low Findings (7)',
  '6. Passed Checks (8)',
  '7. Priority Action Plan',
];

for (const item of tocItems) {
  doc.fontSize(11).fillColor(C.tealDark).text(item, 60, y, { width: W });
  y += 22;
}

// ═══════════════════════════════════════════════════════════════════
//  1. EXECUTIVE SUMMARY
// ═══════════════════════════════════════════════════════════════════
doc.addPage();
y = 50;

heading('1. Executive Summary', 20);
spacer(5);

para(
  'A comprehensive security assessment was conducted on the ISAFlow Cloud Accounting platform on 2026-03-30. ' +
  'Four parallel audit agents examined the full codebase covering SQL injection, authentication & access control, ' +
  'XSS & input validation, and dependencies & configuration. The assessment covered 327 API routes, 159 service ' +
  'files, all database migrations, and infrastructure configuration.'
);
spacer(5);

para(
  'The most critical finding is a pattern of IDOR (Insecure Direct Object Reference) vulnerabilities where ' +
  'multiple API endpoints query the database without filtering by company_id. In a multi-tenant accounting ' +
  'application, this allows any authenticated user to access financial data belonging to other companies. ' +
  'Additionally, the AI-powered natural language query endpoint executes AI-generated SQL without enforcing ' +
  'tenant isolation, and the JWT secret used in production is predictable.'
);
spacer(5);

para(
  'Positively, the application uses parameterized SQL throughout (no SQL injection), React default escaping ' +
  '(no XSS), safe file upload patterns with magic byte validation, and proper admin route protection. ' +
  'All 327 admin endpoints are correctly gated with role-based access control.'
);

// ═══════════════════════════════════════════════════════════════════
//  2. CRITICAL FINDINGS
// ═══════════════════════════════════════════════════════════════════
doc.addPage();
y = 50;

heading('2. Critical Findings', 20, C.red);
spacer(5);

const criticals = [
  {
    id: 'C1',
    title: 'AI-Generated SQL Executes Without Company Scope',
    file: 'pages/api/accounting/nl-query.ts:91',
    desc: 'The natural language query endpoint sends user questions to Claude AI, which generates SQL. This SQL is validated for forbidden keywords but never scoped to the authenticated company. Any user can ask "show all invoices for all companies" and the AI may comply, leaking cross-tenant financial data. The keyword blocklist can be bypassed via SQL comment tricks.',
    fix: 'Execute NL queries on a read-only database role. Wrap generated SQL in a mandatory outer query with company_id filter. Add statement timeout. Consider removing this feature until properly sandboxed.',
  },
  {
    id: 'C2',
    title: 'Weak JWT Secret in Production',
    file: '.env.local:3',
    desc: 'The JWT_SECRET is set to "accounting-app-jwt-secret-change-in-production" — a predictable, low-entropy string. An attacker who discovers this can forge authentication tokens for any user, including super_admin, gaining full access to all companies\' financial data.',
    fix: 'Immediately rotate: openssl rand -base64 32. Store in a secrets manager. Invalidate all active sessions after rotation.',
  },
  {
    id: 'C3',
    title: 'No Rate Limiting on Authentication Endpoints',
    file: 'pages/api/auth/login.ts',
    desc: 'The login, register, and 2FA verification endpoints have zero rate limiting. No per-IP throttling, no account lockout after failed attempts, no CAPTCHA. Combined with the weak admin password (admin123), this makes brute-force attacks trivial.',
    fix: 'Add rate limiting (5 attempts per IP per 15 minutes). Implement exponential backoff. Add failed_attempts column to users table with lockout after 10 failures.',
  },
  {
    id: 'C4',
    title: 'EFT Batch Access Without Company Scope (IDOR)',
    file: 'pages/api/accounting/eft-generate.ts:35',
    desc: 'The EFT payment file generation endpoint fetches batch data using only the user-supplied batchId with no company_id filter. An authenticated user from Company A can supply Company B\'s batchId and download their EFT payment file containing full banking details (account numbers, branch codes, payment amounts).',
    fix: 'Add AND company_id = ${companyId}::UUID to both batch and payment queries.',
  },
  {
    id: 'C5',
    title: 'Document Validation — Cross-Company Entity Access (IDOR)',
    file: 'pages/api/accounting/document-validation.ts:53-89',
    desc: 'Four entity lookup queries (supplier_invoices, customer_invoices, supplier_payments, customer_payments) use only the entityId with no company_id filter. Any authenticated user can validate documents against any other company\'s invoices and payments.',
    fix: 'Add AND company_id = ${companyId}::UUID to all entity fetch queries.',
  },
  {
    id: 'C6',
    title: 'Live Credentials in Environment File',
    file: '.env.local',
    desc: 'The .env.local file contains live production credentials: Neon database connection string with password, SMTP password (appears to follow a personal password pattern). While gitignored, these are accessible to anyone with filesystem access on the server.',
    fix: 'Rotate all credentials immediately. Use a secrets manager (Vault, Doppler, AWS Secrets Manager). Restrict file permissions to chmod 600.',
  },
  {
    id: 'C7',
    title: 'No Account Lockout Mechanism',
    file: 'users table / login handler',
    desc: 'There is no failed_attempts tracking, no locked_until field, and no lockout logic anywhere in the codebase. Combined with no rate limiting (C3), this allows unlimited password guessing.',
    fix: 'Add failed_attempts and locked_until columns to users table. Lock account after 10 failed attempts for 30 minutes. Reset on successful login.',
  },
];

for (const f of criticals) {
  checkPage(100);
  drawRect(48, y - 2, W + 4, 18, C.red);
  doc.fontSize(10).fillColor(C.white).text(`${f.id} — ${f.title}`, 54, y + 1, { width: W - 10 });
  y += 22;

  doc.fontSize(7.5).fillColor(C.gray).text(`File: ${f.file}`, 54, y);
  y += 12;

  doc.fontSize(9).fillColor('#374151').text(f.desc, 54, y, { width: W - 10, lineGap: 2 });
  y = doc.y + 6;

  drawRect(54, y, 3, 30, C.teal);
  doc.fontSize(8).fillColor(C.tealDark).text('Recommended Fix:', 62, y + 2, { width: W - 20 });
  y += 12;
  doc.fontSize(8.5).fillColor('#374151').text(f.fix, 62, y, { width: W - 20, lineGap: 2 });
  y = doc.y + 15;
}

// ═══════════════════════════════════════════════════════════════════
//  3. HIGH FINDINGS
// ═══════════════════════════════════════════════════════════════════
doc.addPage();
y = 50;

heading('3. High Findings', 20, C.orange);
spacer(5);

tableHeader([
  { label: '#', width: 25 },
  { label: 'SEV', width: 71 },
  { label: 'ISSUE', width: 252 },
  { label: 'FILE', width: 145 },
]);

const highs = [
  ['H1', 'HIGH', 'Purchase orders GET — no company_id filter (IDOR)', 'purchase-orders.ts:21-25'],
  ['H2', 'HIGH', 'Time entries — no company_id scope (IDOR)', 'project-time-entries.ts:19-23'],
  ['H3', 'HIGH', 'Stock levels — no company_id filter (IDOR)', 'stock-levels.ts:16-18'],
  ['H4', 'HIGH', 'IRP5/payroll — employee fetched without company scope', 'irp5-generate.ts:40'],
  ['H5', 'HIGH', 'Leave balances — no company_id scope (IDOR)', 'leave-balances.ts:16-19'],
  ['H6', 'HIGH', 'Assets register — no company_id filter (IDOR)', 'assets-register.ts:22-33'],
  ['H7', 'HIGH', 'Bank OAuth tokens stored unencrypted in DB', 'bankFeedService.ts:378'],
  ['H8', 'HIGH', 'Vulnerable deps: xlsx (prototype pollution), next.js (DoS)', 'package.json'],
  ['H9', 'HIGH', 'Default admin password admin123 in migration fallback', 'run-migrations.mjs:71'],
];

for (const [id, sev, issue, file] of highs) {
  findingRow(id, sev, issue, file);
}

spacer(10);
para(
  'The IDOR pattern (H1-H6) is systemic: these endpoints use withCompany() middleware (which resolves companyId), ' +
  'but the SQL queries never include the company_id in their WHERE clauses. The fix is consistent across all: ' +
  'add AND table.company_id = ${companyId}::UUID to each query.',
  9.5
);

// ═══════════════════════════════════════════════════════════════════
//  4. MEDIUM FINDINGS
// ═══════════════════════════════════════════════════════════════════
doc.addPage();
y = 50;

heading('4. Medium Findings', 20, '#d97706');
spacer(5);

tableHeader([
  { label: '#', width: 25 },
  { label: 'SEV', width: 71 },
  { label: 'ISSUE', width: 252 },
  { label: 'FILE', width: 145 },
]);

const mediums = [
  ['M1', 'MEDIUM', 'Company groups — company_id from query string (IDOR)', 'company-groups.ts:54'],
  ['M2', 'MEDIUM', 'Leave applications — no company_id scope', 'leave-applications.ts:19'],
  ['M3', 'MEDIUM', 'sql.unsafe() in 4 admin files (allowlisted but fragile)', 'admin services'],
  ['M4', 'MEDIUM', 'Path traversal — unsanitized originalFilename in storage', 'documents.ts:196'],
  ['M5', 'MEDIUM', 'Raw error messages leaked to clients (6+ files)', 'Multiple API files'],
  ['M6', 'MEDIUM', 'Date params accepted without format validation (~15 endpoints)', 'Report endpoints'],
  ['M7', 'MEDIUM', 'CSP allows unsafe-eval + unsafe-inline', 'next.config.js:24'],
  ['M8', 'MEDIUM', '30-day session cookie, no Secure flag in dev', 'login.ts:143-149'],
  ['M9', 'MEDIUM', 'No POPIA/GDPR data subject rights implementation', 'N/A'],
  ['M10', 'MEDIUM', '50MB upload endpoints + no rate limiting = DoS vector', '3 upload endpoints'],
  ['M11', 'MEDIUM', 'Password strength bar is low (score 2/4 passes)', 'password.ts:77'],
];

for (const [id, sev, issue, file] of mediums) {
  findingRow(id, sev, issue, file);
}

// ═══════════════════════════════════════════════════════════════════
//  5. LOW FINDINGS
// ═══════════════════════════════════════════════════════════════════
spacer(20);
heading('5. Low Findings', 20, C.green);
spacer(5);

tableHeader([
  { label: '#', width: 25 },
  { label: 'SEV', width: 71 },
  { label: 'ISSUE', width: 252 },
  { label: 'FILE', width: 145 },
]);

const lows = [
  ['L1', 'LOW', 'Unbounded queries — missing LIMIT on 3 endpoints', 'Multiple'],
  ['L2', 'LOW', 'Numeric params can produce NaN passed to SQL', 'Multiple'],
  ['L3', 'LOW', 'No UUID format pre-validation on ID params', 'Multiple'],
  ['L4', 'LOW', 'No max-length on NL query question (LLM cost abuse)', 'nl-query.ts:38'],
  ['L5', 'LOW', '.gitignore does not cover plain .env file', '.gitignore'],
  ['L6', 'LOW', 'Source maps present in production build', '.next/server/'],
  ['L7', 'LOW', 'Invite GET leaks email/company data (UUID token)', 'invite/[token].ts'],
];

for (const [id, sev, issue, file] of lows) {
  findingRow(id, sev, issue, file);
}

// ═══════════════════════════════════════════════════════════════════
//  6. PASSED CHECKS
// ═══════════════════════════════════════════════════════════════════
doc.addPage();
y = 50;

heading('6. Passed Security Checks', 20, C.blue);
spacer(5);

const passes = [
  ['SQL Injection', 'All queries use parameterized sql tagged templates from @neondatabase/serverless'],
  ['Cross-Site Scripting', 'No dangerouslySetInnerHTML usage. React default JSX escaping used throughout'],
  ['Command Injection', 'execFile used safely with array args, no exec()/eval()/Function() found'],
  ['File Upload Security', 'MIME allowlists + magic byte validation + 10MB size limits on all upload endpoints'],
  ['CORS', 'Same-origin only. No Access-Control-Allow-Origin: * found anywhere'],
  ['Admin Route Protection', 'All 327 admin endpoints use withAuth(withRole(\'super_admin\'))'],
  ['Client-Side Secrets', 'No NEXT_PUBLIC_ exposure of sensitive env vars. All secrets server-only'],
  ['Logging Hygiene', 'No console.log in source. Structured logger with sensitive field sanitization'],
];

for (const [check, detail] of passes) {
  checkPage(40);
  drawRect(48, y - 2, W + 4, 28, '#f0fdf4');
  drawRect(48, y - 2, 4, 28, C.green);
  doc.fontSize(9.5).fillColor(C.dark).text(`PASS — ${check}`, 58, y + 1, { width: W - 15 });
  doc.fontSize(8).fillColor(C.gray).text(detail, 58, y + 14, { width: W - 15 });
  y += 34;
}

// ═══════════════════════════════════════════════════════════════════
//  7. PRIORITY ACTION PLAN
// ═══════════════════════════════════════════════════════════════════
doc.addPage();
y = 50;

heading('7. Priority Action Plan', 20);
spacer(5);

subheading('Immediate (today)');
bullet('Rotate JWT secret (openssl rand -base64 32), database password, and SMTP password');
bullet('Add rate limiting to /api/auth/login, /register, /2fa-verify (max 5 attempts per IP per 15 min)');
bullet('Fix 8 IDOR endpoints — add AND company_id = ${companyId} to all queries missing it');
spacer(10);

subheading('This Week');
bullet('Disable or sandbox the NL query endpoint (read-only DB role + mandatory company_id injection)');
bullet('Remove admin123 fallback from run-migrations.mjs');
bullet('Encrypt bank OAuth tokens at rest (AES-256 via Node.js crypto)');
bullet('Upgrade xlsx to exceljs, upgrade next.js to >= 15.5.10');
bullet('Add account lockout mechanism (failed_attempts + locked_until columns)');
spacer(10);

subheading('This Month');
bullet('Tighten CSP for production (nonces, remove unsafe-eval/unsafe-inline)');
bullet('Add input validation across all endpoints (date format, UUID format, string lengths)');
bullet('Sanitize error messages in production (gate on NODE_ENV)');
bullet('Implement POPIA data subject rights (access, erasure, portability)');
bullet('Sanitize originalFilename in document upload storage path');
bullet('Reduce session cookie lifetime to 8 hours with refresh mechanism');

// ═══════════════════════════════════════════════════════════════════
//  FOOTER / DISCLAIMER
// ═══════════════════════════════════════════════════════════════════
spacer(30);
line();
spacer(5);

doc.fontSize(7.5).fillColor(C.gray).text(
  'DISCLAIMER: This report is based on automated static analysis and architecture review of the ISAFlow codebase ' +
  'as of 2026-03-30. It does not constitute a full manual penetration test with active exploitation. Findings should ' +
  'be verified and remediated by qualified security professionals. This document is classified CONFIDENTIAL and should ' +
  'not be shared outside the ISAFlow development team without authorization.',
  50, y, { width: W, lineGap: 2 }
);

// Page numbers
const pageCount = doc.bufferedPageRange().count;
for (let i = 0; i < pageCount; i++) {
  doc.switchToPage(i);
  doc.fontSize(7).fillColor(C.gray)
    .text(`ISAFlow Security Penetration Test Report — CONFIDENTIAL`, 50, 805, { width: W - 60 })
    .text(`Page ${i + 1} of ${pageCount}`, 50, 805, { width: W, align: 'right' });
}

doc.end();

stream.on('finish', () => {
  console.log(`PDF generated: ${OUTPUT}`);
  console.log(`Size: ${(fs.statSync(OUTPUT).size / 1024).toFixed(1)} KB`);
});

