/**
 * GET  /api/invite/[token] — Validate an invitation token (public)
 * POST /api/invite/[token] — Accept an invitation (requires auth)
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth, type AuthenticatedNextApiRequest } from '@/lib/auth/middleware';
import { serialize } from 'cookie';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

// ── GET: public token validation ──────────────────────────────────────────────

async function handleGet(req: NextApiRequest, res: NextApiResponse) {
  const { token } = req.query as { token: string };

  if (!token || typeof token !== 'string') {
    return apiResponse.badRequest(res, 'Token is required');
  }

  const rows = (await sql`
    SELECT
      ci.email,
      ci.role,
      c.name  AS company_name,
      u.first_name AS inviter_first,
      u.last_name  AS inviter_last,
      u.email      AS inviter_email
    FROM company_invitations ci
    JOIN companies c ON c.id = ci.company_id
    LEFT JOIN users u ON u.id::VARCHAR = ci.invited_by
    WHERE ci.token = ${token}
      AND ci.accepted_at IS NULL
      AND ci.expires_at > NOW()
    LIMIT 1
  `) as Row[];

  if (rows.length === 0) {
    return apiResponse.notFound(res, 'Invitation');
  }

  const row = rows[0];
  const inviterName =
    row.inviter_first
      ? `${row.inviter_first} ${row.inviter_last ?? ''}`.trim()
      : (row.inviter_email ?? 'Someone');

  return apiResponse.success(res, {
    email: row.email as string,
    companyName: row.company_name as string,
    role: row.role as string,
    invitedBy: inviterName,
  });
}

// ── POST: accept invitation (auth required) ───────────────────────────────────

async function handlePost(req: NextApiRequest, res: NextApiResponse) {
  const authReq = req as AuthenticatedNextApiRequest;
  const { token } = req.query as { token: string };

  if (!token || typeof token !== 'string') {
    return apiResponse.badRequest(res, 'Token is required');
  }

  // Look up the invitation
  const rows = (await sql`
    SELECT id, company_id, email, role
    FROM company_invitations
    WHERE token = ${token}
      AND accepted_at IS NULL
      AND expires_at > NOW()
    LIMIT 1
  `) as Row[];

  if (rows.length === 0) {
    return apiResponse.notFound(res, 'Invitation');
  }

  const inv = rows[0];
  const userId = authReq.user.id;

  // Verify invited email matches the logged-in user's email
  if ((inv.email as string).toLowerCase() !== authReq.user.email.toLowerCase()) {
    return apiResponse.forbidden(res, 'This invitation was sent to a different email address');
  }

  // Insert into company_users
  await sql`
    INSERT INTO company_users (company_id, user_id, role)
    VALUES (${inv.company_id}::UUID, ${userId}::UUID, ${inv.role})
    ON CONFLICT (company_id, user_id) DO NOTHING
  `;

  // Mark invitation accepted
  await sql`
    UPDATE company_invitations SET accepted_at = NOW() WHERE id = ${inv.id}::UUID
  `;

  // Mark onboarding completed for this user (they're joining an existing company)
  await sql`
    UPDATE users SET onboarding_completed = true WHERE id = ${userId}
  `;

  log.info('Invitation accepted via token page', { token, userId, companyId: inv.company_id }, 'invite');

  // Set the onboarding-done cookie so middleware stops redirecting
  const cookieStr = serialize('ff_onboarding_done', '1', {
    httpOnly: false,
    secure: process.env.NODE_ENV === 'production',
    sameSite: 'lax',
    path: '/',
    maxAge: 30 * 24 * 60 * 60,
  });
  res.setHeader('Set-Cookie', cookieStr);

  return apiResponse.success(res, { companyId: inv.company_id as string }, 'Invitation accepted');
}

// ── Router ────────────────────────────────────────────────────────────────────

const postHandler = withAuth(handlePost);

export default async function handler(req: NextApiRequest, res: NextApiResponse) {
  try {
    if (req.method === 'GET') {
      return await handleGet(req, res);
    }
    if (req.method === 'POST') {
      return await postHandler(req, res);
    }
    return apiResponse.methodNotAllowed(res, req.method ?? 'unknown', ['GET', 'POST']);
  } catch (err) {
    log.error('Invite token handler error', err instanceof Error ? { message: err.message } : { err }, 'invite');
    return apiResponse.internalError(res, err);
  }
}

/**
 * Bank Feed Service — Stitch.money Integration
 * OAuth flow, transaction sync, connection management.
 *
 * Environment variables required:
 *   STITCH_CLIENT_ID     — Stitch application client ID
 *   STITCH_CLIENT_SECRET — Stitch application secret
 *   STITCH_REDIRECT_URI  — OAuth callback URL (e.g. https://app.isaflow.co.za/api/bank-feeds/callback)
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import crypto from 'crypto';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

// ── Config ───────────────────────────────────────────────────────────────────

const STITCH_AUTH_URL = 'https://secure.stitch.money/connect/authorize';
const STITCH_TOKEN_URL = 'https://secure.stitch.money/connect/token';
const STITCH_GRAPHQL_URL = 'https://api.stitch.money/graphql';

function getConfig() {
  const clientId = process.env.STITCH_CLIENT_ID;
  const clientSecret = process.env.STITCH_CLIENT_SECRET;
  const redirectUri = process.env.STITCH_REDIRECT_URI;
  return { clientId, clientSecret, redirectUri };
}

function isConfigured(): boolean {
  const { clientId, clientSecret, redirectUri } = getConfig();
  return !!(clientId && clientSecret && redirectUri);
}

// ── Types ────────────────────────────────────────────────────────────────────

export interface BankFeedConnection {
  id: string;
  bankAccountId: string;
  bankAccountName?: string;
  provider: string;
  externalAccountId: string | null;
  bankName: string | null;
  accountNumberMasked: string | null;
  branchCode: string | null;
  accountType: string | null;
  lastSyncAt: string | null;
  syncStatus: string;
  syncError: string | null;
  isActive: boolean;
  createdAt: string;
}

export interface StitchTransaction {
  id: string;
  amount: number;
  runningBalance: number | null;
  description: string;
  reference: string | null;
  date: string;
}

export interface StitchAccount {
  id: string;
  name: string;
  bankId: string;
  accountType: string;
  accountNumber: string;
  branchCode: string;
  currency: string;
  currentBalance: number | null;
  availableBalance: number | null;
}

export interface SyncResult {
  fetched: number;
  imported: number;
  skipped: number;
}

// ── PKCE Helpers ─────────────────────────────────────────────────────────────

function generateCodeVerifier(): string {
  return crypto.randomBytes(32).toString('base64url');
}

function generateCodeChallenge(verifier: string): string {
  return crypto.createHash('sha256').update(verifier).digest('base64url');
}

// ── OAuth Flow ───────────────────────────────────────────────────────────────

/**
 * Generate the Stitch authorization URL for linking a bank account.
 * Returns { url, state, codeVerifier } — store state + codeVerifier in session.
 */
export function getAuthorizationUrl(): {
  url: string;
  state: string;
  nonce: string;
  codeVerifier: string;
} {
  const { clientId, redirectUri } = getConfig();
  if (!clientId || !redirectUri) {
    throw new Error('Stitch integration not configured. Set STITCH_CLIENT_ID and STITCH_REDIRECT_URI.');
  }

  const state = crypto.randomBytes(16).toString('hex');
  const nonce = crypto.randomBytes(16).toString('hex');
  const codeVerifier = generateCodeVerifier();
  const codeChallenge = generateCodeChallenge(codeVerifier);

  const params = new URLSearchParams({
    client_id: clientId,
    response_type: 'code',
    scope: 'openid accounts transactions balances offline_access',
    redirect_uri: redirectUri,
    state,
    nonce,
    code_challenge: codeChallenge,
    code_challenge_method: 'S256',
  });

  return {
    url: `${STITCH_AUTH_URL}?${params.toString()}`,
    state,
    nonce,
    codeVerifier,
  };
}

/**
 * Exchange authorization code for access + refresh tokens.
 */
export async function exchangeCode(
  code: string,
  codeVerifier: string
): Promise<{
  accessToken: string;
  refreshToken: string;
  expiresIn: number;
}> {
  const { clientId, clientSecret, redirectUri } = getConfig();
  if (!clientId || !clientSecret || !redirectUri) {
    throw new Error('Stitch integration not configured');
  }

  const res = await fetch(STITCH_TOKEN_URL, {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams({
      grant_type: 'authorization_code',
      client_id: clientId,
      client_secret: clientSecret,
      code,
      redirect_uri: redirectUri,
      code_verifier: codeVerifier,
    }),
  });

  if (!res.ok) {
    const error = await res.text();
    log.error('Stitch token exchange failed', { status: res.status, error }, 'bank-feeds');
    throw new Error(`Token exchange failed: ${res.status}`);
  }

  const data = await res.json();
  return {
    accessToken: data.access_token,
    refreshToken: data.refresh_token,
    expiresIn: data.expires_in,
  };
}

/**
 * Refresh an expired access token.
 */
export async function refreshAccessToken(refreshToken: string): Promise<{
  accessToken: string;
  refreshToken: string;
  expiresIn: number;
}> {
  const { clientId, clientSecret } = getConfig();
  if (!clientId || !clientSecret) {
    throw new Error('Stitch integration not configured');
  }

  const res = await fetch(STITCH_TOKEN_URL, {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams({
      grant_type: 'refresh_token',
      client_id: clientId,
      client_secret: clientSecret,
      refresh_token: refreshToken,
    }),
  });

  if (!res.ok) {
    const error = await res.text();
    log.error('Stitch token refresh failed', { status: res.status, error }, 'bank-feeds');
    throw new Error(`Token refresh failed: ${res.status}`);
  }

  const data = await res.json();
  return {
    accessToken: data.access_token,
    refreshToken: data.refresh_token || refreshToken,
    expiresIn: data.expires_in,
  };
}

// ── GraphQL Queries ──────────────────────────────────────────────────────────

async function graphqlQuery(accessToken: string, query: string, variables?: Record<string, unknown>) {
  const res = await fetch(STITCH_GRAPHQL_URL, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      Authorization: `Bearer ${accessToken}`,
    },
    body: JSON.stringify({ query, variables }),
  });

  if (!res.ok) {
    const error = await res.text();
    throw new Error(`GraphQL request failed: ${res.status} — ${error}`);
  }

  const json = await res.json();
  if (json.errors?.length) {
    throw new Error(`GraphQL errors: ${JSON.stringify(json.errors)}`);
  }

  return json.data;
}

/**
 * Fetch linked bank accounts from Stitch.
 */
export async function fetchStitchAccounts(accessToken: string): Promise<StitchAccount[]> {
  const query = `
    query {
      user {
        bankAccounts {
          id
          name
          bankId
          accountType
          accountNumber
          branchCode
          currency
          currentBalance
          availableBalance
        }
      }
    }
  `;

  const data = await graphqlQuery(accessToken, query);
  const accounts = data?.user?.bankAccounts ?? [];

  return accounts.map((a: Record<string, unknown>) => ({
    id: a.id as string,
    name: a.name as string,
    bankId: a.bankId as string,
    accountType: a.accountType as string,
    accountNumber: a.accountNumber as string,
    branchCode: a.branchCode as string,
    currency: (a.currency as string) || 'ZAR',
    currentBalance: a.currentBalance != null ? Number(a.currentBalance) : null,
    availableBalance: a.availableBalance != null ? Number(a.availableBalance) : null,
  }));
}

/**
 * Fetch transactions for a specific account from Stitch.
 * Supports cursor-based pagination for incremental sync.
 */
export async function fetchStitchTransactions(
  accessToken: string,
  accountId: string,
  afterCursor?: string,
  limit = 100
): Promise<{
  transactions: StitchTransaction[];
  endCursor: string | null;
  hasNextPage: boolean;
}> {
  const query = `
    query GetTransactions($accountId: ID!, $first: Int!, $after: String) {
      node(id: $accountId) {
        ... on BankAccount {
          transactions(first: $first, after: $after) {
            pageInfo {
              hasNextPage
              endCursor
            }
            nodes {
              id
              amount
              runningBalance
              description
              reference
              date
            }
          }
        }
      }
    }
  `;

  const data = await graphqlQuery(accessToken, query, {
    accountId,
    first: limit,
    after: afterCursor || null,
  });

  const txConnection = data?.node?.transactions;
  const nodes = txConnection?.nodes ?? [];
  const pageInfo = txConnection?.pageInfo ?? {};

  return {
    transactions: nodes.map((t: Record<string, unknown>) => ({
      id: t.id as string,
      amount: Number(t.amount),
      runningBalance: t.runningBalance != null ? Number(t.runningBalance) : null,
      description: (t.description as string) || '',
      reference: (t.reference as string) || null,
      date: t.date as string,
    })),
    endCursor: (pageInfo.endCursor as string) || null,
    hasNextPage: !!pageInfo.hasNextPage,
  };
}

// ── Connection Management ────────────────────────────────────────────────────

export async function listConnections(): Promise<BankFeedConnection[]> {
  const rows = (await sql`
    SELECT bfc.*, ba.account_name AS bank_account_name
    FROM bank_feed_connections bfc
    LEFT JOIN bank_accounts ba ON ba.id = bfc.bank_account_id
    ORDER BY bfc.created_at DESC
  `) as Row[];
  return rows.map(mapConnection);
}

export async function getConnection(id: string): Promise<BankFeedConnection | null> {
  const rows = (await sql`
    SELECT bfc.*, ba.account_name AS bank_account_name
    FROM bank_feed_connections bfc
    LEFT JOIN bank_accounts ba ON ba.id = bfc.bank_account_id
    WHERE bfc.id = ${id}::UUID
  `) as Row[];
  return rows[0] ? mapConnection(rows[0]) : null;
}

export async function createConnection(input: {
  bankAccountId: string;
  externalAccountId: string;
  bankName?: string;
  accountNumberMasked?: string;
  branchCode?: string;
  accountType?: string;
  accessToken: string;
  refreshToken: string;
  expiresIn: number;
  createdBy: string;
}): Promise<BankFeedConnection> {
  const expiresAt = new Date(Date.now() + input.expiresIn * 1000).toISOString();

  const rows = (await sql`
    INSERT INTO bank_feed_connections (
      bank_account_id, provider, external_account_id, bank_name,
      account_number_masked, branch_code, account_type,
      access_token, refresh_token, token_expires_at, sync_status, created_by
    ) VALUES (
      ${input.bankAccountId}::UUID, 'stitch', ${input.externalAccountId},
      ${input.bankName || null}, ${input.accountNumberMasked || null},
      ${input.branchCode || null}, ${input.accountType || null},
      ${input.accessToken}, ${input.refreshToken}, ${expiresAt}::TIMESTAMPTZ,
      'pending', ${input.createdBy}::UUID
    ) RETURNING *
  `) as Row[];

  log.info('Bank feed connection created', { id: rows[0].id, bankName: input.bankName }, 'bank-feeds');
  return mapConnection(rows[0]);
}

export async function disconnectConnection(id: string): Promise<void> {
  await sql`
    UPDATE bank_feed_connections SET is_active = false, updated_at = NOW()
    WHERE id = ${id}::UUID
  `;
  log.info('Bank feed disconnected', { id }, 'bank-feeds');
}

// ── Transaction Sync ─────────────────────────────────────────────────────────

/**
 * Sync transactions for a connection.
 * Handles token refresh, pagination, and deduplication.
 */
export async function syncTransactions(connectionId: string): Promise<SyncResult> {
  const conn = (await sql`SELECT * FROM bank_feed_connections WHERE id = ${connectionId}::UUID AND is_active = true`) as Row[];
  if (!conn[0]) throw new Error('Connection not found or inactive');

  const connection = conn[0];
  let accessToken = connection.access_token;
  const refreshToken = connection.refresh_token;
  const externalAccountId = connection.external_account_id;

  // Refresh token if expired
  const tokenExpiry = new Date(connection.token_expires_at);
  if (tokenExpiry <= new Date()) {
    log.info('Refreshing expired token', { connectionId }, 'bank-feeds');
    const refreshed = await refreshAccessToken(refreshToken);
    accessToken = refreshed.accessToken;
    const newExpiry = new Date(Date.now() + refreshed.expiresIn * 1000).toISOString();
    await sql`
      UPDATE bank_feed_connections SET
        access_token = ${refreshed.accessToken},
        refresh_token = ${refreshed.refreshToken},
        token_expires_at = ${newExpiry}::TIMESTAMPTZ,
        updated_at = NOW()
      WHERE id = ${connectionId}::UUID
    `;
  }

  // Create sync log entry
  const logRows = (await sql`
    INSERT INTO bank_feed_sync_log (connection_id, sync_type)
    VALUES (${connectionId}::UUID, ${connection.last_sync_cursor ? 'incremental' : 'full'})
    RETURNING id
  `) as Row[];
  const syncLogId = logRows[0].id;

  // Update status
  await sql`UPDATE bank_feed_connections SET sync_status = 'syncing', updated_at = NOW() WHERE id = ${connectionId}::UUID`;

  let totalFetched = 0;
  let totalImported = 0;
  let totalSkipped = 0;
  let cursor = connection.last_sync_cursor || undefined;

  try {
    let hasMore = true;
    while (hasMore) {
      const result = await fetchStitchTransactions(accessToken, externalAccountId, cursor, 100);
      totalFetched += result.transactions.length;

      for (const tx of result.transactions) {
        // Check for duplicates by external reference
        const existing = (await sql`
          SELECT id FROM bank_transactions
          WHERE bank_account_id = ${connection.bank_account_id}::UUID
            AND bank_reference = ${tx.id}
          LIMIT 1
        `) as Row[];

        if (existing.length > 0) {
          totalSkipped++;
          continue;
        }

        // Import transaction
        await sql`
          INSERT INTO bank_transactions (
            bank_account_id, transaction_date, amount, description,
            reference, bank_reference, status, import_batch_id
          ) VALUES (
            ${connection.bank_account_id}::UUID, ${tx.date}::DATE, ${tx.amount},
            ${tx.description}, ${tx.reference || null}, ${tx.id},
            'imported', NULL
          )
        `;
        totalImported++;
      }

      cursor = result.endCursor || undefined;
      hasMore = result.hasNextPage;
    }

    // Update connection
    await sql`
      UPDATE bank_feed_connections SET
        last_sync_at = NOW(),
        last_sync_cursor = ${cursor || null},
        sync_status = 'synced',
        sync_error = NULL,
        updated_at = NOW()
      WHERE id = ${connectionId}::UUID
    `;

    // Complete sync log
    await sql`
      UPDATE bank_feed_sync_log SET
        transactions_fetched = ${totalFetched},
        transactions_imported = ${totalImported},
        transactions_skipped = ${totalSkipped},
        completed_at = NOW(),
        status = 'completed'
      WHERE id = ${syncLogId}::UUID
    `;

    log.info('Bank feed sync completed', {
      connectionId, fetched: totalFetched, imported: totalImported, skipped: totalSkipped,
    }, 'bank-feeds');

  } catch (error) {
    const errorMessage = error instanceof Error ? error.message : 'Sync failed';

    await sql`
      UPDATE bank_feed_connections SET sync_status = 'error', sync_error = ${errorMessage}, updated_at = NOW()
      WHERE id = ${connectionId}::UUID
    `;
    await sql`
      UPDATE bank_feed_sync_log SET status = 'failed', error = ${errorMessage}, completed_at = NOW()
      WHERE id = ${syncLogId}::UUID
    `;

    log.error('Bank feed sync failed', { connectionId, error: errorMessage }, 'bank-feeds');
    throw error;
  }

  return { fetched: totalFetched, imported: totalImported, skipped: totalSkipped };
}

/**
 * Get sync history for a connection.
 */
export async function getSyncHistory(connectionId: string, limit = 20): Promise<Array<{
  id: string;
  syncType: string;
  fetched: number;
  imported: number;
  skipped: number;
  startedAt: string;
  completedAt: string | null;
  status: string;
  error: string | null;
}>> {
  const rows = (await sql`
    SELECT * FROM bank_feed_sync_log
    WHERE connection_id = ${connectionId}::UUID
    ORDER BY started_at DESC
    LIMIT ${limit}
  `) as Row[];

  return rows.map((r: Row) => ({
    id: r.id,
    syncType: r.sync_type,
    fetched: r.transactions_fetched,
    imported: r.transactions_imported,
    skipped: r.transactions_skipped,
    startedAt: r.started_at,
    completedAt: r.completed_at,
    status: r.status,
    error: r.error,
  }));
}

/** Check if Stitch integration is configured */
export { isConfigured };

// ── Mapper ───────────────────────────────────────────────────────────────────

function mapConnection(r: Row): BankFeedConnection {
  return {
    id: r.id,
    bankAccountId: r.bank_account_id,
    bankAccountName: r.bank_account_name || undefined,
    provider: r.provider,
    externalAccountId: r.external_account_id,
    bankName: r.bank_name,
    accountNumberMasked: r.account_number_masked,
    branchCode: r.branch_code,
    accountType: r.account_type,
    lastSyncAt: r.last_sync_at,
    syncStatus: r.sync_status,
    syncError: r.sync_error,
    isActive: r.is_active,
    createdAt: r.created_at,
  };
}

/**
 * GL Import Template API
 * GET /api/accounting/gl-import-template
 * Returns an Excel (.xlsx) template file with headers and 2 sample rows.
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { withCompany } from '@/lib/auth';
import * as XLSX from 'xlsx';

function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') {
    res.setHeader('Allow', ['GET']);
    res.status(405).json({ error: 'Method not allowed' });
    return;
  }

  const headers = [
    'Date',
    'Account Code',
    'Description',
    'Reference',
    'Debit',
    'Credit',
    'VAT Code',
    'Cost Centre',
  ];

  const sampleRows = [
    [
      '2026-04-01',
      '1000',
      'Opening bank balance',
      'OB-2026-001',
      50000,
      0,
      'no_vat',
      '',
    ],
    [
      '2026-04-01',
      '3100',
      'Opening bank balance',
      'OB-2026-001',
      0,
      50000,
      'no_vat',
      '',
    ],
  ];

  const wsData = [headers, ...sampleRows];
  const ws = XLSX.utils.aoa_to_sheet(wsData);

  // Set column widths
  ws['!cols'] = [
    { wch: 12 }, // Date
    { wch: 14 }, // Account Code
    { wch: 35 }, // Description
    { wch: 18 }, // Reference
    { wch: 12 }, // Debit
    { wch: 12 }, // Credit
    { wch: 14 }, // VAT Code
    { wch: 14 }, // Cost Centre
  ];

  const wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, ws, 'GL Import');

  // Add a Notes sheet with VAT code reference
  const notesData = [
    ['VAT Code Reference'],
    ['standard', '15% standard rate'],
    ['zero_rated', '0% zero-rated supplies'],
    ['exempt', 'Exempt from VAT'],
    ['capital_goods', 'Standard-rated capital goods'],
    ['export', 'Zero-rated exports'],
    ['imported', 'Imported goods/services'],
    ['reverse_charge', 'Domestic reverse charge (DRC)'],
    ['bad_debt', 'Bad debt recovery'],
    ['no_vat', 'No VAT applicable'],
  ];
  const notesWs = XLSX.utils.aoa_to_sheet(notesData);
  notesWs['!cols'] = [{ wch: 18 }, { wch: 35 }];
  XLSX.utils.book_append_sheet(wb, notesWs, 'VAT Codes');

  const buf = XLSX.write(wb, { type: 'buffer', bookType: 'xlsx' });

  res.setHeader('Content-Type', 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');
  res.setHeader('Content-Disposition', 'attachment; filename="isaflow-gl-import-template.xlsx"');
  res.setHeader('Content-Length', buf.length);
  res.status(200).send(buf);
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withCompany(withErrorHandler(handler as any));

/**
 * GL Import Wizard — WS-6.3
 * 4-step wizard: Upload → Map Columns → Validate → Import
 */

import { useState, useEffect, useCallback, useRef } from 'react';
import { useRouter } from 'next/router';
import * as XLSX from 'xlsx';
import { AppLayout } from '@/components/layout/AppLayout';
import { apiFetch } from '@/lib/apiFetch';
import { log } from '@/lib/logger';
import {
  Upload, ArrowRight, ArrowLeft, CheckCircle2, XCircle,
  FileSpreadsheet, Download, Loader2, BookOpen,
} from 'lucide-react';
import { ValidationStep, ImportStep } from '@/components/accounting/gl-import/GlImportWizardSteps';
import type { ImportRow, ValidationSummary } from '@/modules/accounting/services/glImportService';

type Step = 1 | 2 | 3 | 4;

const REQUIRED_FIELDS = ['date', 'accountCode', 'description', 'debit', 'credit'] as const;
const ALL_FIELDS = [
  { value: '__skip__', label: '— Skip —' },
  { value: 'date', label: 'Date' },
  { value: 'accountCode', label: 'Account Code' },
  { value: 'description', label: 'Description' },
  { value: 'reference', label: 'Reference' },
  { value: 'debit', label: 'Debit' },
  { value: 'credit', label: 'Credit' },
  { value: 'vatCode', label: 'VAT Code' },
  { value: 'costCentre', label: 'Cost Centre' },
];

const AUTO_MAP: Record<string, string> = {
  date: 'date', 'entry date': 'date', 'trans date': 'date',
  'account code': 'accountCode', account: 'accountCode', 'acc code': 'accountCode', code: 'accountCode',
  description: 'description', desc: 'description', narration: 'description', details: 'description',
  reference: 'reference', ref: 'reference',
  debit: 'debit', dr: 'debit',
  credit: 'credit', cr: 'credit',
  'vat code': 'vatCode', vatcode: 'vatCode', 'tax code': 'vatCode',
  'cost centre': 'costCentre', 'cost center': 'costCentre', cc: 'costCentre',
};

function StepIndicator({ current }: { current: Step }) {
  const steps = ['Upload', 'Map Columns', 'Validate', 'Import'];
  return (
    <div className="flex items-center gap-0">
      {steps.map((label, idx) => {
        const num = (idx + 1) as Step;
        const done = current > num;
        const active = current === num;
        return (
          <div key={label} className="flex items-center">
            <div className={`flex items-center gap-2 px-4 py-2 rounded-lg text-sm font-medium transition-colors ${
              active ? 'bg-teal-500/20 text-teal-400' :
              done ? 'text-teal-500' : 'text-[var(--ff-text-secondary)]'
            }`}>
              <span className={`w-6 h-6 rounded-full flex items-center justify-center text-xs font-bold ${
                done ? 'bg-teal-600 text-white' :
                active ? 'bg-teal-500 text-white' : 'bg-[var(--ff-border-light)] text-[var(--ff-text-secondary)]'
              }`}>
                {done ? <CheckCircle2 className="h-4 w-4" /> : num}
              </span>
              {label}
            </div>
            {idx < steps.length - 1 && (
              <ArrowRight className="h-4 w-4 text-[var(--ff-border-light)]" />
            )}
          </div>
        );
      })}
    </div>
  );
}

export default function GlImportPage() {
  const router = useRouter();
  const [isMounted, setIsMounted] = useState(false);
  const [step, setStep] = useState<Step>(1);

  // Step 1 — file
  const [rawHeaders, setRawHeaders] = useState<string[]>([]);
  const [rawRows, setRawRows] = useState<string[][]>([]);
  const [fileName, setFileName] = useState('');
  const [fileError, setFileError] = useState('');
  const fileRef = useRef<HTMLInputElement>(null);
  const [dragging, setDragging] = useState(false);

  // Step 2 — mapping
  const [mapping, setMapping] = useState<Record<number, string>>({});

  // Step 3 — validation
  const [validating, setValidating] = useState(false);
  const [summary, setSummary] = useState<ValidationSummary | null>(null);
  const [validRows, setValidRows] = useState<ImportRow[]>([]);
  const [validateError, setValidateError] = useState('');

  // Step 4 — import
  const [postImmediately, setPostImmediately] = useState(false);
  const [importing, setImporting] = useState(false);
  const [importResult, setImportResult] = useState<{ entriesCreated: number; linesCreated: number; totalValue: number } | null>(null);
  const [importError, setImportError] = useState('');

  useEffect(() => { setIsMounted(true); }, []);

  const parseFile = useCallback((file: File) => {
    setFileError('');
    const name = file.name.toLowerCase();
    if (!name.endsWith('.xlsx') && !name.endsWith('.xls') && !name.endsWith('.csv')) {
      setFileError('Only .xlsx, .xls and .csv files are supported');
      return;
    }
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const data = e.target?.result;
        const wb = XLSX.read(data, { type: 'binary' });
        const ws = wb.Sheets[wb.SheetNames[0]!]!;
        const aoa = XLSX.utils.sheet_to_json<string[]>(ws, { header: 1, raw: false }) as string[][];
        if (aoa.length < 2) {
          setFileError('File must have a header row and at least one data row');
          return;
        }
        const headers = (aoa[0] ?? []).map(h => String(h ?? '').trim());
        const dataRows = aoa.slice(1).filter(r => r.some(c => c !== '' && c != null));
        setRawHeaders(headers);
        setRawRows(dataRows.map(r => headers.map((_, i) => String(r[i] ?? '').trim())));
        setFileName(file.name);
        const autoMapping: Record<number, string> = {};
        headers.forEach((h, i) => {
          const key = h.toLowerCase().trim();
          autoMapping[i] = AUTO_MAP[key] ?? '__skip__';
        });
        setMapping(autoMapping);
        setStep(2);
      } catch (err) {
        log.error('Failed to parse spreadsheet', { error: err }, 'gl-import-page');
        setFileError('Failed to read file — make sure it is a valid Excel or CSV file');
      }
    };
    reader.readAsBinaryString(file);
  }, []);

  const buildImportRows = useCallback((): ImportRow[] => {
    return rawRows.map(row => {
      const get = (field: string) => {
        const entry = Object.entries(mapping).find(([, v]) => v === field);
        return entry ? (row[Number(entry[0])] ?? '') : '';
      };
      return {
        date: get('date'),
        accountCode: get('accountCode'),
        description: get('description'),
        reference: get('reference') || undefined,
        debit: parseFloat(get('debit').replace(/,/g, '')) || 0,
        credit: parseFloat(get('credit').replace(/,/g, '')) || 0,
        vatCode: get('vatCode') || undefined,
        costCentre: get('costCentre') || undefined,
      };
    });
  }, [rawRows, mapping]);

  const isMappingComplete = REQUIRED_FIELDS.every(f => Object.values(mapping).includes(f));

  const handleValidate = useCallback(async () => {
    setValidating(true);
    setValidateError('');
    setSummary(null);
    try {
      const rows = buildImportRows();
      const res = await apiFetch('/api/accounting/gl-import-validate', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ rows }),
      });
      const json = await res.json() as { data: ValidationSummary };
      setSummary(json.data);
      setValidRows(rows.filter((_, i) => json.data.validations[i]?.valid));
      setStep(3);
    } catch (err) {
      log.error('Validation API error', { error: err }, 'gl-import-page');
      setValidateError('Validation failed — please try again');
    } finally {
      setValidating(false);
    }
  }, [buildImportRows]);

  const handleImport = useCallback(async () => {
    setImporting(true);
    setImportError('');
    try {
      const res = await apiFetch('/api/accounting/gl-import', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ rows: validRows, postImmediately }),
      });
      const json = await res.json() as { data: { entriesCreated: number; linesCreated: number; totalValue: number } };
      setImportResult(json.data);
    } catch (err) {
      log.error('Import API error', { error: err }, 'gl-import-page');
      setImportError('Import failed — please try again');
    } finally {
      setImporting(false);
    }
  }, [validRows, postImmediately]);

  const handleReset = useCallback(() => {
    setStep(1);
    setRawHeaders([]); setRawRows([]); setFileName('');
    setSummary(null); setValidRows([]); setImportResult(null);
    setImportError(''); setValidateError(''); setFileError('');
  }, []);

  if (!isMounted) {
    return (
      <AppLayout>
        <div className="min-h-screen bg-[var(--ff-bg-primary)] flex items-center justify-center">
          <Loader2 className="h-8 w-8 animate-spin text-teal-500" />
        </div>
      </AppLayout>
    );
  }

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">

        {/* Page header */}
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)]">
          <div className="px-6 py-4 flex items-center justify-between">
            <div className="flex items-center gap-3">
              <div className="p-2 rounded-lg bg-teal-500/10">
                <FileSpreadsheet className="h-6 w-6 text-teal-500" />
              </div>
              <div>
                <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">Import Transactions</h1>
                <p className="text-sm text-[var(--ff-text-secondary)]">Import GL journal entries from Excel or CSV</p>
              </div>
            </div>
            <a
              href="/api/accounting/gl-import-template"
              className="inline-flex items-center gap-2 px-4 py-2 border border-[var(--ff-border-light)] text-[var(--ff-text-secondary)] rounded-lg hover:bg-[var(--ff-bg-primary)] transition-colors text-sm"
            >
              <Download className="h-4 w-4" />
              Download Template
            </a>
          </div>
          <div className="px-6 pb-4">
            <StepIndicator current={step} />
          </div>
        </div>

        <div className="px-6 py-6 max-w-5xl mx-auto">

          {/* Step 1: Upload */}
          {step === 1 && (
            <div className="space-y-4">
              <div
                onDragOver={e => { e.preventDefault(); setDragging(true); }}
                onDragLeave={() => setDragging(false)}
                onDrop={e => { e.preventDefault(); setDragging(false); const f = e.dataTransfer.files[0]; if (f) parseFile(f); }}
                onClick={() => fileRef.current?.click()}
                className={`border-2 border-dashed rounded-xl p-12 text-center cursor-pointer transition-colors ${
                  dragging ? 'border-teal-500 bg-teal-500/5' :
                  'border-[var(--ff-border-light)] hover:border-teal-500/50 hover:bg-[var(--ff-bg-secondary)]'
                }`}
              >
                <Upload className="h-12 w-12 text-[var(--ff-text-secondary)] mx-auto mb-4" />
                <p className="text-lg font-medium text-[var(--ff-text-primary)] mb-1">Drag and drop your file here</p>
                <p className="text-sm text-[var(--ff-text-secondary)]">or click to browse — supports .xlsx, .xls, .csv</p>
                <input ref={fileRef} type="file" accept=".xlsx,.xls,.csv" className="hidden" onChange={e => { const f = e.target.files?.[0]; if (f) parseFile(f); }} />
              </div>
              {fileError && (
                <div className="flex items-center gap-2 text-red-400 text-sm bg-red-500/10 border border-red-500/20 rounded-lg px-4 py-3">
                  <XCircle className="h-4 w-4 flex-shrink-0" />{fileError}
                </div>
              )}
              <div className="bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)] rounded-lg p-4">
                <div className="flex items-center gap-2 mb-2">
                  <BookOpen className="h-4 w-4 text-teal-500" />
                  <span className="text-sm font-medium text-[var(--ff-text-primary)]">Required columns</span>
                </div>
                <p className="text-sm text-[var(--ff-text-secondary)]">
                  Date, Account Code, Description, Debit, Credit. Optional: Reference, VAT Code, Cost Centre.
                  Download the template above for the correct format.
                </p>
              </div>
            </div>
          )}

          {/* Step 2: Map Columns */}
          {step === 2 && (
            <div className="space-y-6">
              <div className="bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)] rounded-lg p-4">
                <p className="text-sm text-[var(--ff-text-secondary)] mb-4">
                  File: <span className="font-medium text-[var(--ff-text-primary)]">{fileName}</span> — {rawRows.length} data rows detected.
                  Map each column to an ISAFlow field. Required fields are marked below.
                </p>
                <div className="overflow-x-auto">
                  <table className="w-full text-sm">
                    <thead>
                      <tr className="border-b border-[var(--ff-border-light)]">
                        <th className="text-left pb-2 pr-4 text-[var(--ff-text-secondary)] font-medium">Source Column</th>
                        <th className="text-left pb-2 pr-4 text-[var(--ff-text-secondary)] font-medium">Maps To</th>
                        {rawRows.slice(0, 3).map((_, i) => (
                          <th key={i} className="text-left pb-2 pr-2 text-[var(--ff-text-secondary)] font-medium">Row {i + 1}</th>
                        ))}
                      </tr>
                    </thead>
                    <tbody>
                      {rawHeaders.map((header, colIdx) => (
                        <tr key={colIdx} className="border-b border-[var(--ff-border-light)]/50">
                          <td className="py-2 pr-4 font-medium text-[var(--ff-text-primary)]">{header}</td>
                          <td className="py-2 pr-4">
                            <select
                              value={mapping[colIdx] ?? '__skip__'}
                              onChange={e => setMapping(prev => ({ ...prev, [colIdx]: e.target.value }))}
                              className="px-2 py-1 text-sm bg-[var(--ff-bg-primary)] border border-[var(--ff-border-light)] rounded text-[var(--ff-text-primary)] focus:outline-none focus:ring-2 focus:ring-teal-500/30"
                            >
                              {ALL_FIELDS.map(f => (
                                <option key={f.value} value={f.value}>{f.label}</option>
                              ))}
                            </select>
                          </td>
                          {rawRows.slice(0, 3).map((row, ri) => (
                            <td key={ri} className="py-2 pr-2 text-[var(--ff-text-secondary)] truncate max-w-[120px]">
                              {row[colIdx] ?? ''}
                            </td>
                          ))}
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
                {!isMappingComplete && (
                  <p className="mt-3 text-sm text-amber-400">
                    Required fields not yet mapped: {REQUIRED_FIELDS.filter(f => !Object.values(mapping).includes(f)).join(', ')}
                  </p>
                )}
              </div>
              {validateError && (
                <div className="flex items-center gap-2 text-red-400 text-sm bg-red-500/10 border border-red-500/20 rounded-lg px-4 py-3">
                  <XCircle className="h-4 w-4 flex-shrink-0" />{validateError}
                </div>
              )}
              <div className="flex items-center justify-between">
                <button onClick={() => setStep(1)} className="inline-flex items-center gap-2 px-4 py-2 border border-[var(--ff-border-light)] text-[var(--ff-text-secondary)] rounded-lg hover:bg-[var(--ff-bg-secondary)] transition-colors text-sm">
                  <ArrowLeft className="h-4 w-4" />Back
                </button>
                <button
                  onClick={() => void handleValidate()}
                  disabled={!isMappingComplete || validating}
                  className="inline-flex items-center gap-2 px-5 py-2 bg-teal-600 text-white rounded-lg hover:bg-teal-700 disabled:opacity-50 disabled:cursor-not-allowed transition-colors text-sm font-medium"
                >
                  {validating ? <Loader2 className="h-4 w-4 animate-spin" /> : <ArrowRight className="h-4 w-4" />}
                  {validating ? 'Validating...' : 'Validate'}
                </button>
              </div>
            </div>
          )}

          {/* Step 3: Validation */}
          {step === 3 && summary && (
            <ValidationStep
              summary={summary}
              onBack={() => setStep(2)}
              onNext={() => setStep(4)}
            />
          )}

          {/* Step 4: Import */}
          {step === 4 && summary && (
            <ImportStep
              validRows={validRows}
              summary={summary}
              postImmediately={postImmediately}
              onPostModeChange={setPostImmediately}
              onBack={() => setStep(3)}
              onImport={() => void handleImport()}
              importing={importing}
              importError={importError}
              importResult={importResult}
              onViewEntries={() => void router.push('/accounting/journal-entries')}
              onReset={handleReset}
            />
          )}

        </div>
      </div>
    </AppLayout>
  );
}

