  drawRect(394, y + 2, barW, 10, '#e2e8f0');
  drawRect(394, y + 2, fillW, 10, pctNum === 100 ? C.green : pctNum >= 70 ? C.teal : C.orange);
  doc.fontSize(8).fillColor(C.dark).text(row.pct, 450, y + 2, { width: 40 });

