# IsaFlow App (app.isaflow.co.za)
# Cloudflare SSL: Flexible (CF terminates SSL, connects to origin on HTTP)
server {
    listen 80;
    server_name app.isaflow.co.za;

    client_max_body_size 50M;

    location / {
        proxy_pass http://localhost:3101;
        proxy_http_version 1.1;
