/**
 * Natural Language Financial Query Service
 * Text-to-SQL with Claude, validation, formatting.
 * Pure business logic — no database dependencies.
 */

export interface SchemaTable {
  name: string;
  columns: string[];
  description: string;
}

export interface ParsedSQL {
  sql: string;
  explanation: string;
}

export interface SQLValidation {
  valid: boolean;
  error?: string;
  sanitizedSQL: string;
}

export type QueryIntent = 'revenue' | 'expense' | 'customer' | 'supplier' | 'cash' | 'tax' | 'payroll' | 'inventory' | 'general';

export interface QueryResult {
  rows: Record<string, unknown>[];
  columns: string[];
  numericColumns: string[];
  summary: string;
  rowCount: number;
}

// ═══════════════════════════════════════════════════════════════════════════
// SCHEMA DESCRIPTION
// ═══════════════════════════════════════════════════════════════════════════

export function buildSchemaDescription(tables: SchemaTable[]): string {
  return tables.map(t =>
    `TABLE: ${t.name} (${t.columns.join(', ')}) — ${t.description}`
  ).join('\n');
}

// ═══════════════════════════════════════════════════════════════════════════
// TEXT-TO-SQL PROMPT
// ═══════════════════════════════════════════════════════════════════════════

export function buildTextToSQLPrompt(question: string, schemaDesc: string, companyId?: string): string {
  const companyFilter = companyId
    ? `CRITICAL: Every query MUST include WHERE company_id = '${companyId}' on ALL tables that have a company_id column. Never omit this filter — omitting it is a security violation.`
    : '';

  return `You are a South African accounting database assistant. Generate a read-only PostgreSQL SELECT query to answer the user's question.

Database Schema:
${schemaDesc}

User Question: ${question}

Rules:
- Generate ONLY read-only SELECT queries (no INSERT, UPDATE, DELETE, DROP, ALTER, TRUNCATE)
- Use proper SQL aggregation (SUM, COUNT, AVG, etc.) where appropriate
- Use ZAR currency context (South African Rand)
- Format dates as YYYY-MM-DD
- Limit results to 100 rows max unless the user asks for a specific count
- Use table aliases for readability
${companyFilter}

Respond in JSON format:
{"sql": "SELECT ...", "explanation": "Brief explanation of what this query returns"}`;
}

// ═══════════════════════════════════════════════════════════════════════════
// SQL RESPONSE PARSING
// ═══════════════════════════════════════════════════════════════════════════

export function parseSQLResponse(response: string): ParsedSQL | null {
  if (!response || response.trim() === '') return null;

  // Try JSON parse first
  try {
    const jsonMatch = response.match(/\{[\s\S]*"sql"[\s\S]*\}/);
    if (jsonMatch) {
      const parsed = JSON.parse(jsonMatch[0]);
      if (parsed.sql && typeof parsed.sql === 'string' && parsed.sql.trim().toUpperCase().startsWith('SELECT') || parsed.sql.trim().toUpperCase().startsWith('WITH')) {
        return { sql: parsed.sql.trim(), explanation: String(parsed.explanation || '') };
      }
    }
  } catch { /* not JSON */ }

  // Try SQL code block
  const sqlBlock = response.match(/```(?:sql)?\s*\n?([\s\S]*?)\n?```/);
  if (sqlBlock) {
    const sql = sqlBlock[1]!.trim();
    if (sql.toUpperCase().startsWith('SELECT') || sql.toUpperCase().startsWith('WITH')) {
      const explanationMatch = response.replace(sqlBlock[0], '').trim();
      return { sql, explanation: explanationMatch.slice(0, 200) };
    }
  }

  // Try plain SQL
  const trimmed = response.trim();
  if (trimmed.toUpperCase().startsWith('SELECT') || trimmed.toUpperCase().startsWith('WITH')) {
    return { sql: trimmed, explanation: '' };
  }

  return null;
}

// ═══════════════════════════════════════════════════════════════════════════
// SQL VALIDATION
// ═══════════════════════════════════════════════════════════════════════════

const FORBIDDEN_KEYWORDS = ['INSERT', 'UPDATE', 'DELETE', 'DROP', 'ALTER', 'TRUNCATE', 'CREATE', 'GRANT', 'REVOKE', 'EXEC', 'EXECUTE'];
const MAX_LIMIT = 100;

export function validateGeneratedSQL(sql: string): SQLValidation {
  if (!sql || sql.trim() === '') {
    return { valid: false, error: 'Empty SQL', sanitizedSQL: '' };
  }

  const upper = sql.toUpperCase().trim();

  // Must start with SELECT or WITH
  if (!upper.startsWith('SELECT') && !upper.startsWith('WITH')) {
    return { valid: false, error: 'Query must be a SELECT statement', sanitizedSQL: '' };
  }

  // Check for forbidden keywords
  for (const kw of FORBIDDEN_KEYWORDS) {
    // Match keyword as whole word (not inside column names)
    const regex = new RegExp(`\\b${kw}\\b`, 'i');
    if (regex.test(sql)) {
      return { valid: false, error: `Forbidden keyword: ${kw}`, sanitizedSQL: '' };
    }
  }

  // Reject multiple statements
  const statements = sql.split(';').filter(s => s.trim().length > 0);
  if (statements.length > 1) {
    return { valid: false, error: 'Multiple statements not allowed', sanitizedSQL: '' };
  }

  // Add LIMIT if not present
  let sanitizedSQL = sql.trim().replace(/;$/, '');
  if (!/\bLIMIT\b/i.test(sanitizedSQL)) {
    sanitizedSQL += ` LIMIT ${MAX_LIMIT}`;
  }

  return { valid: true, sanitizedSQL };
}

// ═══════════════════════════════════════════════════════════════════════════
// QUERY INTENT CLASSIFICATION
// ═══════════════════════════════════════════════════════════════════════════

const INTENT_PATTERNS: Array<{ intent: QueryIntent; patterns: RegExp[] }> = [
  { intent: 'revenue', patterns: [/\brevenue\b/i, /\bsales\b/i, /\bincome\b/i, /\bturnover\b/i, /\bbilling\b/i] },
  { intent: 'expense', patterns: [/\bexpens/i, /\bcost\b/i, /\bspend/i, /\bpurchas/i] },
  { intent: 'customer', patterns: [/\bcustomer/i, /\bclient/i, /\bdebtor/i, /\breceivable/i] },
  { intent: 'supplier', patterns: [/\bsupplier/i, /\bvendor/i, /\bcreditor/i, /\bpayable/i] },
  { intent: 'cash', patterns: [/\bcash\b/i, /\bbank\b/i, /\bbalance\b/i, /\bliquidity/i] },
  { intent: 'tax', patterns: [/\bvat\b/i, /\btax\b/i, /\bsars\b/i, /\bpaye\b/i] },
  { intent: 'payroll', patterns: [/\bpayroll\b/i, /\bsalary\b/i, /\bwage/i, /\bemploee/i] },
  { intent: 'inventory', patterns: [/\binventory\b/i, /\bstock\b/i, /\bproduct/i] },
];

export function classifyQueryIntent(question: string): QueryIntent {
  for (const { intent, patterns } of INTENT_PATTERNS) {
    if (patterns.some(p => p.test(question))) return intent;
  }
  return 'general';
}

// ═══════════════════════════════════════════════════════════════════════════
// RESULT FORMATTING
// ═══════════════════════════════════════════════════════════════════════════

export function formatQueryResult(rows: Record<string, unknown>[], question: string): QueryResult {
  if (!rows || rows.length === 0) {
    return { rows: [], columns: [], numericColumns: [], summary: 'No results found for your query.', rowCount: 0 };
  }

  const columns = Object.keys(rows[0]!);
  const numericColumns = columns.filter(col =>
    rows.some(r => typeof r[col] === 'number' || (typeof r[col] === 'string' && !isNaN(Number(r[col])) && r[col] !== ''))
  );

  let summary: string;
  if (rows.length === 1 && columns.length === 1) {
    const value = rows[0]![columns[0]!];
    summary = `Result: ${value}`;
  } else if (rows.length === 1) {
    summary = columns.map(c => `${c}: ${rows[0]![c]}`).join(', ');
  } else {
    summary = `${rows.length} result${rows.length === 1 ? '' : 's'} returned.`;
  }

  return { rows, columns, numericColumns, summary, rowCount: rows.length };
}

/**
 * JWT Utilities
 * Token signing and verification using jose library
 */

import { SignJWT, jwtVerify, JWTPayload as JosePayload } from 'jose';
import type { JWTPayload, AuthUser, AuthRole } from './types';

// Secret key for JWT signing - must be set in environment
const getJWTSecret = (): Uint8Array => {
  const secret = process.env.JWT_SECRET;
  if (!secret || secret.length < 32) {
    throw new Error('JWT_SECRET must be set and at least 32 characters');
  }
  return new TextEncoder().encode(secret);
};

// Token expiration times
const ACCESS_TOKEN_EXPIRY = '24h'; // 24 hours
const _REFRESH_TOKEN_EXPIRY = '30d'; // 30 days – reserved for future refresh-token flow

/**
 * Sign a JWT token for a user
 */
export async function signToken(
  user: AuthUser,
  sessionId: string,
  expiresIn: string = ACCESS_TOKEN_EXPIRY
): Promise<string> {
  const secret = getJWTSecret();

  const token = await new SignJWT({
    email: user.email,
    role: user.role,
    sessionId,
  })
    .setProtectedHeader({ alg: 'HS256' })
    .setSubject(user.id)
    .setIssuedAt()
    .setExpirationTime(expiresIn)
    .sign(secret);

  return token;
}

/**
 * Verify and decode a JWT token
 */
export async function verifyToken(token: string): Promise<JWTPayload | null> {
  try {
    const secret = getJWTSecret();
    const { payload } = await jwtVerify(token, secret);

    // Type assertion with validation
    if (!payload.sub || !payload.email || !payload.role || !payload.sessionId) {
      return null;
    }

    return {
      sub: payload.sub as string,
      email: payload.email as string,
      role: payload.role as AuthRole,
      permissions: [], // Permissions fetched from DB via getUserAndValidateSession()
      sessionId: payload.sessionId as string,
      iat: payload.iat || 0,
      exp: payload.exp || 0,
    };
  } catch (error) {
    // Token invalid or expired
    return null;
  }
}

/**
 * Decode token without verification (for debugging)
 */
export function decodeToken(token: string): JosePayload | null {
  try {
    const parts = token.split('.');
    if (parts.length !== 3) return null;

    const part = parts[1];
    if (!part) return null;
    const payload = JSON.parse(
      Buffer.from(part, 'base64url' as BufferEncoding).toString('utf-8')
    );
    return payload;
  } catch {
    return null;
  }
}

/**
 * Check if token is expired
 */
export function isTokenExpired(token: string): boolean {
  const decoded = decodeToken(token);
  if (!decoded || !decoded.exp) return true;

  return Date.now() >= decoded.exp * 1000;
}

/**
 * Get time until token expires (in seconds)
 */
export function getTokenExpiryTime(token: string): number {
  const decoded = decodeToken(token);
  if (!decoded || !decoded.exp) return 0;

  const expiresAt = decoded.exp * 1000;
  const now = Date.now();

  return Math.max(0, Math.floor((expiresAt - now) / 1000));
}

/**
 * Client Portal — Authentication API
 * POST — login with email/password, sets signed httpOnly session cookie
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { authenticatePortalUser } from '@/modules/accounting/services/portalService';
import { SignJWT } from 'jose';
import cookie from 'cookie';

const PORTAL_SECRET = new TextEncoder().encode(
  (() => { if (!process.env.JWT_SECRET) throw new Error('JWT_SECRET is required'); return process.env.JWT_SECRET + '-portal'; })()
);

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method!, ['POST']);
  }

  const { email, password } = req.body;
  if (!email || !password) {
    return apiResponse.badRequest(res, 'email and password are required');
  }

  const user = await authenticatePortalUser(email, password);
  if (!user) {
    return apiResponse.unauthorized(res, 'Invalid email or password');
  }

  // Sign a JWT for the portal session
  const token = await new SignJWT({ clientId: user.clientId, email: user.email })
    .setProtectedHeader({ alg: 'HS256' })
    .setExpirationTime('24h')
    .setIssuedAt()
    .sign(PORTAL_SECRET);

  // Set httpOnly signed cookie
  res.setHeader('Set-Cookie', cookie.serialize('portal_session', token, {
    httpOnly: true,
    secure: process.env.NODE_ENV === 'production',
    sameSite: 'strict',
    path: '/',
    maxAge: 60 * 60 * 24, // 24 hours
  }));

  return apiResponse.success(res, { user });
}

export default withErrorHandler(handler);

/**
 * Next.js Edge Middleware
 * - app.isaflow.co.za: redirect / to /accounting (app domain — no landing page)
 * - isaflow.co.za: show landing page at /
 * - Redirects unauthenticated /accounting/* requests to /login
 */

import { NextResponse } from 'next/server';
import type { NextRequest } from 'next/server';

const AUTH_COOKIE_NAME = 'ff_auth_token';

const PUBLIC_PATHS = ['/login', '/register', '/api/auth/login', '/api/auth/logout', '/api/auth/register', '/onboarding', '/api/onboarding', '/invite', '/api/invite'];

/** Hostnames that should skip the landing page and go straight to the app */
const APP_HOSTS = ['app.isaflow.co.za'];

export function middleware(request: NextRequest) {
  const { pathname } = request.nextUrl;
  const host = request.headers.get('host')?.split(':')[0] ?? '';

  // Allow public paths, static files, and API routes
  if (
    PUBLIC_PATHS.some(p => pathname.startsWith(p)) ||
    pathname.startsWith('/_next') ||
    pathname.startsWith('/api/') ||
    pathname.startsWith('/icons') ||
    pathname.startsWith('/landing') ||
    pathname === '/manifest.json' ||
    pathname === '/sw.js' ||
    pathname === '/favicon.ico'
  ) {
    return NextResponse.next();
  }

  // app.isaflow.co.za: redirect root to /accounting
  if (pathname === '/' && APP_HOSTS.includes(host)) {
    return NextResponse.redirect(new URL('/accounting', request.url));
  }

  // Check for auth cookie on protected routes
  const token = request.cookies.get(AUTH_COOKIE_NAME)?.value;

  if (!token && (pathname.startsWith('/accounting') || pathname.startsWith('/payroll'))) {
    const loginUrl = new URL('/login', request.url);
    loginUrl.searchParams.set('returnTo', pathname);
    return NextResponse.redirect(loginUrl);
  }

  // Redirect to onboarding if user hasn't completed it
  if (token && !request.cookies.get('ff_onboarding_done')?.value) {
    if (pathname.startsWith('/accounting') || pathname.startsWith('/payroll')) {
      return NextResponse.redirect(new URL('/onboarding', request.url));
    }
  }

  return NextResponse.next();
}

export const config = {
  matcher: ['/', '/accounting/:path*', '/onboarding/:path*', '/payroll/:path*', '/invite/:path*'],
};

import {
  createContext,
  useContext,
  useEffect,
  useState,
  useCallback,
  ReactNode,
} from 'react';
import { useAuth } from './AuthContext';
import { apiFetch } from '@/lib/apiFetch';

const STORAGE_KEY = 'isaflow_active_company';

export interface Company {
  id: string;
  name: string;
  tradingName?: string;
  registrationNumber?: string;
  vatNumber?: string;
  taxNumber?: string;
  addressLine1?: string;
  addressLine2?: string;
  city?: string;
  province?: string;
  postalCode?: string;
  country?: string;
  phone?: string;
  email?: string;
  website?: string;
  logoUrl?: string;
  logoData?: string;
  bankName?: string;
  bankAccountNumber?: string;
  bankBranchCode?: string;
  bankAccountType?: string;
  financialYearStart?: number;
  vatPeriod?: string;
  defaultCurrency?: string;
  isActive?: boolean;
}

export interface CompanyUser {
  companyId: string;
  companyName: string;
  role: string;
  isDefault: boolean;
}

interface CompanyContextType {
  activeCompany: Company | null;
  companies: CompanyUser[];
  loading: boolean;
  companyRole: string | null;
  switchCompany: (companyId: string) => Promise<void>;
}

const CompanyContext = createContext<CompanyContextType | undefined>(undefined);

export function CompanyProvider({ children }: { children: ReactNode }) {
  const { user, isAuthenticated } = useAuth();
  const [activeCompany, setActiveCompany] = useState<Company | null>(null);
  const [companies, setCompanies] = useState<CompanyUser[]>([]);
  const [loading, setLoading] = useState(true);
  const [companyRole, setCompanyRole] = useState<string | null>(null);

  const loadCompanyDetails = useCallback(async (companyId: string) => {
    try {
      const res = await apiFetch(`/api/accounting/companies?id=${companyId}`);
      if (res.ok) {
        const data = await res.json();
        const c = data.data;
        if (c) {
          const company: Company = {
            id: c.id,
            name: c.name,
            tradingName: c.trading_name || c.tradingName,
            registrationNumber: c.registration_number || c.registrationNumber,
            vatNumber: c.vat_number || c.vatNumber,
            taxNumber: c.tax_number || c.taxNumber,
            addressLine1: c.address_line1 || c.addressLine1,
            addressLine2: c.address_line2 || c.addressLine2,
            city: c.city,
            province: c.province,
            postalCode: c.postal_code || c.postalCode,
            country: c.country,
            phone: c.phone,
            email: c.email,
            website: c.website,
            logoUrl: c.logo_url || c.logoUrl,
            logoData: c.logo_data || c.logoData,
            bankName: c.bank_name || c.bankName,
            bankAccountNumber: c.bank_account_number || c.bankAccountNumber,
            bankBranchCode: c.bank_branch_code || c.bankBranchCode,
            bankAccountType: c.bank_account_type || c.bankAccountType,
            financialYearStart: c.financial_year_start || c.financialYearStart,
            vatPeriod: c.vat_period || c.vatPeriod,
            defaultCurrency: c.default_currency || c.defaultCurrency,
            isActive: c.is_active ?? c.isActive ?? true,
          };
          setActiveCompany(company);
          localStorage.setItem(STORAGE_KEY, JSON.stringify({ id: company.id, name: company.name }));
          return company;
        }
      }
    } catch {
      // Failed to load company details
    }
    return null;
  }, []);

  const loadUserCompanies = useCallback(async () => {
    if (!isAuthenticated) {
      setLoading(false);
      return;
    }

    try {
      const res = await apiFetch('/api/accounting/companies?action=user-companies');

      if (!res.ok) {
        setLoading(false);
        return;
      }

      const data = await res.json();
      const raw = data.data?.items ?? data.data ?? [];
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const list: CompanyUser[] = (Array.isArray(raw) ? raw : []).map((c: any) => ({
        companyId: (c.companyId || c.company_id) as string,
        companyName: (c.companyName || c.company_name) as string,
        role: c.role as string,
        isDefault: Boolean(c.isDefault ?? c.is_default ?? false),
      }));

      setCompanies(list);

      if (list.length === 0) {
        // User has no companies — clear any stale localStorage
        localStorage.removeItem(STORAGE_KEY);
        setActiveCompany(null);
        setLoading(false);
        return;
      }

      // Determine which company to activate
      let targetId: string | null = null;

      // 1. Check localStorage
      try {
        const stored = localStorage.getItem(STORAGE_KEY);
        if (stored) {
          const { id } = JSON.parse(stored);
          if (id && list.some((c: CompanyUser) => c.companyId === id)) {
            targetId = id;
          }
        }
      } catch {
        // Invalid stored data
      }

      // 2. Fall back to default company
      if (!targetId) {
        const defaultCompany = list.find((c: CompanyUser) => c.isDefault) ?? list[0];
        targetId = defaultCompany?.companyId ?? null;
      }

      if (!targetId) {
        setLoading(false);
        return;
      }

      // Set the role
      const match = list.find((c: CompanyUser) => c.companyId === targetId);
      if (match) setCompanyRole(match.role);

      await loadCompanyDetails(targetId);
    } catch {
      // Network error
    } finally {
      setLoading(false);
    }
  }, [isAuthenticated, loadCompanyDetails]);

  useEffect(() => {
    loadUserCompanies();
  }, [loadUserCompanies]);

  const switchCompany = useCallback(async (companyId: string) => {
    setLoading(true);
    const match = companies.find(c => c.companyId === companyId);
    if (match) setCompanyRole(match.role);
    await loadCompanyDetails(companyId);
    setLoading(false);

    // Set as default on the server
    try {
      await apiFetch('/api/accounting/companies', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'set-default', companyId }),
      });
    } catch {
      // Non-critical
    }
  }, [companies, loadCompanyDetails]);

  const value: CompanyContextType = {
    activeCompany,
    companies,
    loading,
    companyRole,
    switchCompany,
  };

  return <CompanyContext.Provider value={value}>{children}</CompanyContext.Provider>;
}

export function useCompany() {
  const context = useContext(CompanyContext);
  if (context === undefined) {
    throw new Error('useCompany must be used within a CompanyProvider');
  }
  return context;
}

