      return apiResponse.success(res, overview);
    } catch (err) {
      log.error('Failed to get billing overview', { error: err }, 'admin-api');
      return apiResponse.badRequest(res, 'Failed to get billing overview');
    }
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET']);
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withAuth(withRole('super_admin')(withErrorHandler(handler as any) as any) as any);

/**
 * Admin Billing Plan Detail API
 * GET    /api/admin/billing/plans/[id] — Get a single plan
 * PATCH  /api/admin/billing/plans/[id] — Update a plan
 * DELETE /api/admin/billing/plans/[id] — Archive a plan
 */

import type { NextApiResponse } from 'next';
import { withAuth, withRole, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { log } from '@/lib/logger';
import { getPlan, updatePlan, archivePlan } from '@/modules/admin/services/planService';
import { logAdminAction } from '@/modules/admin/services/auditService';

function getIp(req: AuthenticatedNextApiRequest): string | null {
  return (
    (req.headers['x-forwarded-for'] as string)?.split(',')[0]?.trim() ||
    req.socket?.remoteAddress ||
    null
  );
}

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  const id = req.query.id as string;

  if (req.method === 'GET') {
    try {
      const plan = await getPlan(id);
      if (!plan) return apiResponse.notFound(res, 'Plan not found');
      return apiResponse.success(res, plan);
    } catch (err) {
      log.error('Failed to get plan', { id, error: err }, 'admin-api');
      return apiResponse.badRequest(res, 'Failed to get plan');
    }
  }

  if (req.method === 'PATCH') {
    try {
      const body = req.body as Record<string, unknown>;
      await updatePlan(id, body);

      await logAdminAction(
        req.user.id,
        'plan.update',
        'plan',
        id,
        body,
        getIp(req)
      );

      return apiResponse.success(res, { updated: true });
    } catch (err) {
      log.error('Failed to update plan', { id, error: err }, 'admin-api');
      return apiResponse.badRequest(res, 'Failed to update plan');
    }
  }

  if (req.method === 'DELETE') {
    try {
      await archivePlan(id);

      await logAdminAction(
        req.user.id,
        'plan.archive',
        'plan',
        id,
        null,
        getIp(req)
      );

      return apiResponse.success(res, { archived: true });
    } catch (err) {
      log.error('Failed to archive plan', { id, error: err }, 'admin-api');
      return apiResponse.badRequest(res, 'Failed to archive plan');
    }
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'PATCH', 'DELETE']);
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withAuth(withRole('super_admin')(withErrorHandler(handler as any) as any) as any);

/**
 * Admin Billing Plans API
 * GET  /api/admin/billing/plans — List all plans
 * POST /api/admin/billing/plans — Create a new plan
 */

import type { NextApiResponse } from 'next';
import { withAuth, withRole, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { log } from '@/lib/logger';
import { listPlans, createPlan } from '@/modules/admin/services/planService';
import { logAdminAction } from '@/modules/admin/services/auditService';

function getIp(req: AuthenticatedNextApiRequest): string | null {
  return (
    (req.headers['x-forwarded-for'] as string)?.split(',')[0]?.trim() ||
    req.socket?.remoteAddress ||
    null
  );
}

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  if (req.method === 'GET') {
    try {
      const includeArchived = req.query.include_archived === 'true';
      const plans = await listPlans(includeArchived);
      return apiResponse.success(res, plans);
    } catch (err) {
      log.error('Failed to list plans', { error: err }, 'admin-api');
      return apiResponse.badRequest(res, 'Failed to list plans');
    }
  }

  if (req.method === 'POST') {
    try {
      const {
        code,
        name,
        description,
        monthly_price_cents,
        annual_price_cents,
        currency,
        features,
        limits,
        display_order,
      } = req.body as {
        code: string;
        name: string;
        description?: string;
        monthly_price_cents: number;
        annual_price_cents: number | undefined;
        currency?: string;
        features?: Record<string, unknown>;
        limits?: Record<string, unknown>;
        display_order?: number;
      };

      if (!code || !name || monthly_price_cents == null) {
        return apiResponse.badRequest(res, 'code, name, and monthly_price_cents are required');
      }

      const plan = await createPlan({
        code,
        name,
        description,
        monthly_price_cents,
        annual_price_cents: annual_price_cents ?? monthly_price_cents,
        currency,
        features,
        limits,
        display_order,
      });

      await logAdminAction(
        req.user.id,
        'plan.create',
        'plan',
        plan.id,
        { code, name, monthly_price_cents },
        getIp(req)
      );

      return apiResponse.success(res, plan);
    } catch (err) {
      log.error('Failed to create plan', { error: err }, 'admin-api');
      return apiResponse.badRequest(res, 'Failed to create plan');
    }
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'POST']);
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withAuth(withRole('super_admin')(withErrorHandler(handler as any) as any) as any);

/**
 * Admin Billing Subscription Cancel API
 * POST /api/admin/billing/subscriptions/[id]/cancel — Cancel a subscription
 */

import type { NextApiResponse } from 'next';
import { withAuth, withRole, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { log } from '@/lib/logger';
import { cancelSubscription } from '@/modules/admin/services/billingService';
import { logAdminAction } from '@/modules/admin/services/auditService';

function getIp(req: AuthenticatedNextApiRequest): string | null {
  return (
    (req.headers['x-forwarded-for'] as string)?.split(',')[0]?.trim() ||
    req.socket?.remoteAddress ||
    null
  );
}

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  const id = req.query.id as string;

  if (req.method === 'POST') {
    try {
      const { at_period_end } = req.body as { at_period_end?: boolean };

      const atPeriodEnd = at_period_end === true;
      await cancelSubscription(id, atPeriodEnd);

      await logAdminAction(
        req.user.id,
        'subscription.cancel',
        'subscription',
        id,
        { at_period_end: atPeriodEnd },
        getIp(req)
      );

      return apiResponse.success(res, { cancelled: true, at_period_end: atPeriodEnd });
    } catch (err) {
      log.error('Failed to cancel subscription', { id, error: err }, 'admin-api');
      return apiResponse.badRequest(res, 'Failed to cancel subscription');
    }
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['POST']);
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withAuth(withRole('super_admin')(withErrorHandler(handler as any) as any) as any);

