/**
 * Admin Billing Subscription Detail API
 * GET   /api/admin/billing/subscriptions/[id] — Get a single subscription
 * PATCH /api/admin/billing/subscriptions/[id] — Update a subscription
 */

import type { NextApiResponse } from 'next';
import { withAuth, withRole, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { log } from '@/lib/logger';
import { getSubscription, updateSubscription } from '@/modules/admin/services/billingService';
import { logAdminAction } from '@/modules/admin/services/auditService';

function getIp(req: AuthenticatedNextApiRequest): string | null {
  return (
    (req.headers['x-forwarded-for'] as string)?.split(',')[0]?.trim() ||
    req.socket?.remoteAddress ||
    null
  );
}

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  const id = req.query.id as string;

  if (req.method === 'GET') {
    try {
      const subscription = await getSubscription(id);
      if (!subscription) return apiResponse.notFound(res, 'Subscription not found');
      return apiResponse.success(res, subscription);
    } catch (err) {
      log.error('Failed to get subscription', { id, error: err }, 'admin-api');
      return apiResponse.badRequest(res, 'Failed to get subscription');
    }
  }

  if (req.method === 'PATCH') {
    try {
      const body = req.body as {
        plan_id?: string;
        billing_cycle?: string;
        discount_percent?: number;
        status?: string;
        notes?: string;
      };
      await updateSubscription(id, body);

      await logAdminAction(
        req.user.id,
        'subscription.update',
        'subscription',
        id,
        body as Record<string, unknown>,
        getIp(req)
      );

      return apiResponse.success(res, { updated: true });
    } catch (err) {
      log.error('Failed to update subscription', { id, error: err }, 'admin-api');
      return apiResponse.badRequest(res, 'Failed to update subscription');
    }
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'PATCH']);
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withAuth(withRole('super_admin')(withErrorHandler(handler as any) as any) as any);

/**
 * Admin Billing Subscriptions API
 * GET  /api/admin/billing/subscriptions — List subscriptions with filters
 * POST /api/admin/billing/subscriptions — Create a subscription
 */

import type { NextApiResponse } from 'next';
import { withAuth, withRole, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { log } from '@/lib/logger';
import { listSubscriptions, createSubscription } from '@/modules/admin/services/billingService';
import { logAdminAction } from '@/modules/admin/services/auditService';

function getIp(req: AuthenticatedNextApiRequest): string | null {
  return (
    (req.headers['x-forwarded-for'] as string)?.split(',')[0]?.trim() ||
    req.socket?.remoteAddress ||
    null
  );
}

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  if (req.method === 'GET') {
    try {
      const { status, plan_id, search, page, limit } = req.query;

      const result = await listSubscriptions({
        status: status as string | undefined,
        plan_id: plan_id as string | undefined,
        search: search as string | undefined,
        page: page ? Number(page) : undefined,
        limit: limit ? Number(limit) : undefined,
      });

      return apiResponse.success(res, result);
    } catch (err) {
      log.error('Failed to list subscriptions', { error: err }, 'admin-api');
      return apiResponse.badRequest(res, 'Failed to list subscriptions');
    }
  }

  if (req.method === 'POST') {
    try {
      const { company_id, plan_id, billing_cycle, discount_percent, notes } = req.body as {
        company_id: string;
        plan_id: string;
        billing_cycle: string;
        discount_percent?: number;
        notes?: string;
      };

      if (!company_id || !plan_id || !billing_cycle) {
        return apiResponse.badRequest(res, 'company_id, plan_id, and billing_cycle are required');
      }

      const subscriptionId = await createSubscription({
        company_id,
        plan_id,
        billing_cycle,
        discount_percent,
        notes,
      });

      await logAdminAction(
        req.user.id,
        'subscription.create',
        'subscription',
        subscriptionId,
        { company_id, plan_id, billing_cycle },
        getIp(req)
      );

      return apiResponse.success(res, { id: subscriptionId });
    } catch (err) {
      log.error('Failed to create subscription', { error: err }, 'admin-api');
      return apiResponse.badRequest(res, 'Failed to create subscription');
    }
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'POST']);
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withAuth(withRole('super_admin')(withErrorHandler(handler as any) as any) as any);

/**
 * Admin Company Activate API
 * POST /api/admin/companies/[id]/activate — Reinstate a suspended company
 */

import type { NextApiResponse } from 'next';
import { withAuth, withRole, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { log } from '@/lib/logger';
import { activateCompany } from '@/modules/admin/services/adminCompanyService';
import { logAdminAction } from '@/modules/admin/services/auditService';

function getIp(req: AuthenticatedNextApiRequest): string | null {
  return (
    (req.headers['x-forwarded-for'] as string)?.split(',')[0]?.trim() ||
    req.socket?.remoteAddress ||
    null
  );
}

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  const companyId = req.query.id as string;

  if (req.method === 'POST') {
    try {
      await activateCompany(companyId);

      await logAdminAction(
        req.user.id,
        'company.activate',
        'company',
        companyId,
        null,
        getIp(req)
      );

      return apiResponse.success(res, { activated: true });
    } catch (err) {
      log.error('Failed to activate company', { companyId, error: err }, 'admin-api');
      return apiResponse.badRequest(res, 'Failed to activate company');
    }
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['POST']);
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withAuth(withRole('super_admin')(withErrorHandler(handler as any) as any) as any);

/**
 * Admin Company Data Export API
 * GET /api/admin/companies/[id]/export-data
 * Returns all company accounting data as a downloadable JSON file.
 */

import type { NextApiResponse } from 'next';
import { withAuth, withRole, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { log } from '@/lib/logger';
import { exportCompanyData } from '@/modules/admin/services/dataExportService';
import { logAdminAction } from '@/modules/admin/services/auditService';

function getIp(req: AuthenticatedNextApiRequest): string | null {
  return (
    (req.headers['x-forwarded-for'] as string)?.split(',')[0]?.trim() ||
    req.socket?.remoteAddress ||
    null
  );
}

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method ?? 'UNKNOWN', ['GET']);
  }

  const companyId = req.query.id as string;

  try {
    const { filename, data } = await exportCompanyData(companyId);

    await logAdminAction(
      req.user.id,
      'company.export_data',
      'company',
      companyId,
      { filename },
      getIp(req)
    );

    res.setHeader('Content-Type', 'application/json');
    res.setHeader('Content-Disposition', `attachment; filename="${filename}"`);
    res.status(200).json({ filename, data });
  } catch (err) {
    log.error('Failed to export company data', { companyId, error: err }, 'admin-api');
    return apiResponse.badRequest(res, 'Failed to export company data');
  }
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withAuth(withRole('super_admin')(withErrorHandler(handler as any) as any) as any);

/**
 * Admin Company Features API
 * GET    /api/admin/companies/[id]/features — Effective features for a company
 * POST   /api/admin/companies/[id]/features — Set a feature override
 * DELETE /api/admin/companies/[id]/features — Remove a feature override
 */

import type { NextApiResponse } from 'next';
import { withAuth, withRole, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { log } from '@/lib/logger';
import {
  getCompanyEffectiveFeatures,
  setCompanyFeatureOverride,
  removeCompanyFeatureOverride,
} from '@/modules/admin/services/featureFlagService';
import { logAdminAction } from '@/modules/admin/services/auditService';

function getIp(req: AuthenticatedNextApiRequest): string | null {
  return (
    (req.headers['x-forwarded-for'] as string)?.split(',')[0]?.trim() ||
    req.socket?.remoteAddress ||
    null
  );
}

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  const companyId = req.query.id as string;

  if (req.method === 'GET') {
    try {
      const features = await getCompanyEffectiveFeatures(companyId);
      return apiResponse.success(res, features);
    } catch (err) {
      log.error('Failed to get company features', { companyId, error: err }, 'admin-api');
      return apiResponse.badRequest(res, 'Failed to get company features');
    }
  }

  if (req.method === 'POST') {
    try {
      const { feature_id, enabled, reason } = req.body as {
        feature_id?: string;
        enabled?: boolean;
        reason?: string;
      };

      if (!feature_id) return apiResponse.badRequest(res, 'feature_id is required');
      if (enabled === undefined || enabled === null) {
        return apiResponse.badRequest(res, 'enabled is required');
      }
      if (!reason) return apiResponse.badRequest(res, 'reason is required');

      await setCompanyFeatureOverride(
        companyId,
        feature_id,
        enabled,
        reason,
        req.user.id
      );

      await logAdminAction(
        req.user.id,
        'company_feature.override_set',
        'company',
        companyId,
        { feature_id, enabled, reason },
        getIp(req)
      );

      const updated = await getCompanyEffectiveFeatures(companyId);
      return apiResponse.success(res, updated);
    } catch (err) {
      log.error('Failed to set company feature override', { companyId, error: err }, 'admin-api');
      return apiResponse.badRequest(res, 'Failed to set feature override');
    }
  }

  if (req.method === 'DELETE') {
    try {
      const { feature_id } = req.body as { feature_id?: string };

      if (!feature_id) return apiResponse.badRequest(res, 'feature_id is required');

      await removeCompanyFeatureOverride(companyId, feature_id);

      await logAdminAction(
        req.user.id,
        'company_feature.override_removed',
        'company',
        companyId,
        { feature_id },
        getIp(req)
      );

      const updated = await getCompanyEffectiveFeatures(companyId);
      return apiResponse.success(res, updated);
    } catch (err) {
      log.error('Failed to remove company feature override', { companyId, error: err }, 'admin-api');
      return apiResponse.badRequest(res, 'Failed to remove feature override');
    }
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'POST', 'DELETE']);
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withAuth(withRole('super_admin')(withErrorHandler(handler as any) as any) as any);

