    '/accounting/sage-migration',
    '/accounting/group',
    '/payroll/employees',
    '/payroll/runs',
    '/payroll/leave',
  ];

  const results = [];
  const base = 'http://localhost:3101';

  for (const route of pagesWithContent) {
    // navigate in current page context
    try {
      const res = await fetch(`${base}${route}`, { credentials: 'include' });
      const html = await res.text();

      // Check for error indicators
      const is404 = html.includes('404') && html.includes('could not be found');
      const is500 = html.includes('500') || html.includes('Internal Server Error');
      const hasMain = html.includes('<main') || html.includes('id="__next"');

      // Extract approximate title
      const titleMatch = html.match(/<title[^>]*>([^<]+)<\/title>/);
      const title = titleMatch ? titleMatch[1] : 'no title';

      // Detect blank/empty main
      const mainMatch = html.match(/<main[^>]*>([\s\S]*?)<\/main>/);
      const mainText = mainMatch ? mainMatch[1].replace(/<[^>]+>/g, '').trim().substring(0, 100) : '';

      results.push({
        route,
        status: res.status,
        is404,
        is500,
        title: title.substring(0, 50),
        mainPreview: mainText.substring(0, 80),
        renderOk: !is404 && !is500 && hasMain
      });
    } catch (e) {
      results.push({ route, status: 'ERROR', error: String(e) });
    }
  }
  return results;
}

