  days60: number;
  days90: number;
  days90Plus: number;
  totalOutstanding: number;
  invoiceCount: number;
}

export interface DebtorInvoice {
  id: string;
  invoiceNumber: string;
  invoiceDate: string;
  dueDate: string | null;
  totalAmount: number;
  amountPaid: number;
  outstanding: number;
  daysOverdue: number;
  status: string;
  agingBucket: 'current' | 'days30' | 'days60' | 'days90' | 'days90Plus';
}

export interface OverdueInvoice {
  id: string;
  invoiceNumber: string;
  clientId: string;
  clientName: string;
  invoiceDate: string;
  dueDate: string;
  totalAmount: number;
  amountPaid: number;
  outstanding: number;
  daysOverdue: number;
  status: string;
}

export interface CollectionStats {
  totalOutstanding: number;
  totalOverdue: number;
  avgDaysOutstanding: number;
  collectionRate: number;
  clientCount: number;
  overdueCount: number;
}

// ── Helpers ───────────────────────────────────────────────────────────────────

function classifyBucket(daysOverdue: number): DebtorInvoice['agingBucket'] {
  if (daysOverdue <= 0) return 'current';
  if (daysOverdue <= 30) return 'days30';
  if (daysOverdue <= 60) return 'days60';
  if (daysOverdue <= 90) return 'days90';
  return 'days90Plus';
}

// ── Debtors Summary ───────────────────────────────────────────────────────────

/**
 * Aggregate outstanding invoices by customer with aging buckets.
 * Buckets: current (not yet due), 1-30, 31-60, 61-90, 90+ days overdue.
 */
export async function getDebtorsSummary(companyId: string): Promise<DebtorSummary[]> {
  try {
    const rows = (await sql`
      SELECT
        ci.client_id,
        c.name AS client_name,
        COUNT(ci.id)::int AS invoice_count,
        SUM(
          CASE WHEN ci.due_date IS NULL OR ci.due_date >= CURRENT_DATE
               THEN (ci.total_amount - ci.amount_paid) ELSE 0 END
        ) AS current,
        SUM(
          CASE WHEN ci.due_date IS NOT NULL
                AND ci.due_date < CURRENT_DATE
                AND (CURRENT_DATE - ci.due_date) <= 30
               THEN (ci.total_amount - ci.amount_paid) ELSE 0 END
        ) AS days30,
        SUM(
          CASE WHEN ci.due_date IS NOT NULL
                AND (CURRENT_DATE - ci.due_date) BETWEEN 31 AND 60
               THEN (ci.total_amount - ci.amount_paid) ELSE 0 END
        ) AS days60,
        SUM(
          CASE WHEN ci.due_date IS NOT NULL
                AND (CURRENT_DATE - ci.due_date) BETWEEN 61 AND 90
               THEN (ci.total_amount - ci.amount_paid) ELSE 0 END
        ) AS days90,
        SUM(
          CASE WHEN ci.due_date IS NOT NULL
                AND (CURRENT_DATE - ci.due_date) > 90
               THEN (ci.total_amount - ci.amount_paid) ELSE 0 END
        ) AS days90_plus,
        SUM(ci.total_amount - ci.amount_paid) AS total_outstanding
      FROM customer_invoices ci
      JOIN customers c ON c.id = ci.client_id
      WHERE ci.status IN ('approved', 'sent', 'partially_paid', 'overdue')
        AND (ci.total_amount - ci.amount_paid) > 0
      GROUP BY ci.client_id, c.name
      ORDER BY total_outstanding DESC
    `) as Row[];

    return rows.map((r: Row) => ({
      clientId: String(r.client_id),
      clientName: String(r.client_name),
      current: Number(r.current),
      days30: Number(r.days30),
      days60: Number(r.days60),
      days90: Number(r.days90),
      days90Plus: Number(r.days90_plus),
      totalOutstanding: Number(r.total_outstanding),
      invoiceCount: Number(r.invoice_count),
    }));
  } catch (err) {
    log.error('getDebtorsSummary failed', { error: err }, 'accounting');
    throw err;
  }
}

// ── Debtor Detail ─────────────────────────────────────────────────────────────

/**
 * List outstanding invoices for a specific customer with age and amounts.
 */
export async function getDebtorDetail(companyId: string, clientId: string): Promise<DebtorInvoice[]> {
  try {
    const rows = (await sql`
      SELECT
        ci.id,
        ci.invoice_number,
        ci.invoice_date,
        ci.due_date,
        ci.total_amount,
        ci.amount_paid,
        (ci.total_amount - ci.amount_paid) AS outstanding,
        ci.status,
        CASE
          WHEN ci.due_date IS NULL THEN 0
          ELSE GREATEST(0, (CURRENT_DATE - ci.due_date)::int)
        END AS days_overdue
      FROM customer_invoices ci
      WHERE ci.client_id = ${clientId}::UUID
        AND ci.status IN ('approved', 'sent', 'partially_paid', 'overdue')
        AND (ci.total_amount - ci.amount_paid) > 0
      ORDER BY ci.due_date ASC NULLS LAST, ci.invoice_date ASC
    `) as Row[];

    return rows.map((r: Row) => {
      const daysOverdue = Number(r.days_overdue);
      return {
        id: String(r.id),
        invoiceNumber: String(r.invoice_number),
        invoiceDate: String(r.invoice_date),
        dueDate: r.due_date ? String(r.due_date) : null,
        totalAmount: Number(r.total_amount),
        amountPaid: Number(r.amount_paid),
        outstanding: Number(r.outstanding),
        daysOverdue,
        status: String(r.status),
        agingBucket: classifyBucket(daysOverdue),
      };
    });
  } catch (err) {
    log.error('getDebtorDetail failed', { clientId, error: err }, 'accounting');
    throw err;
  }
}

// ── Overdue Invoices ──────────────────────────────────────────────────────────

/**
 * List all overdue invoices sorted by age descending.
 * Optionally filter to invoices overdue by at least daysOverdue days.
 */
export async function getOverdueInvoices(companyId: string, daysOverdue?: number): Promise<OverdueInvoice[]> {
  const minDays = daysOverdue ?? 1;

  try {
    const rows = (await sql`
      SELECT
        ci.id,
        ci.invoice_number,
        ci.client_id,
        c.name AS client_name,
        ci.invoice_date,
        ci.due_date,
        ci.total_amount,
        ci.amount_paid,
        (ci.total_amount - ci.amount_paid) AS outstanding,
        (CURRENT_DATE - ci.due_date)::int AS days_overdue,
        ci.status
      FROM customer_invoices ci
      JOIN customers c ON c.id = ci.client_id
      WHERE ci.due_date IS NOT NULL
        AND ci.due_date < CURRENT_DATE
        AND (CURRENT_DATE - ci.due_date) >= ${minDays}
        AND ci.status IN ('approved', 'sent', 'partially_paid', 'overdue')
        AND (ci.total_amount - ci.amount_paid) > 0
      ORDER BY days_overdue DESC, ci.total_amount DESC
    `) as Row[];

    return rows.map((r: Row) => ({
      id: String(r.id),
      invoiceNumber: String(r.invoice_number),
      clientId: String(r.client_id),
      clientName: String(r.client_name),
      invoiceDate: String(r.invoice_date),
      dueDate: String(r.due_date),
      totalAmount: Number(r.total_amount),
      amountPaid: Number(r.amount_paid),
      outstanding: Number(r.outstanding),
      daysOverdue: Number(r.days_overdue),
      status: String(r.status),
    }));
  } catch (err) {
    log.error('getOverdueInvoices failed', { daysOverdue, error: err }, 'accounting');
    throw err;
  }
}

// ── Collection Stats ──────────────────────────────────────────────────────────

/**
 * Aggregate collection metrics: total outstanding, total overdue,
 * average days outstanding, and collection rate.
 */
export async function getCollectionStats(companyId: string): Promise<CollectionStats> {
  try {
    const rows = (await sql`
      SELECT
        SUM(ci.total_amount - ci.amount_paid)                            AS total_outstanding,
        SUM(CASE WHEN ci.due_date < CURRENT_DATE
                 THEN (ci.total_amount - ci.amount_paid) ELSE 0 END)     AS total_overdue,
        COALESCE(AVG(
          CASE WHEN ci.due_date IS NOT NULL AND ci.due_date < CURRENT_DATE
               THEN (CURRENT_DATE - ci.due_date)::numeric END
        ), 0)                                                             AS avg_days_outstanding,
        COUNT(DISTINCT ci.client_id)::int                                AS client_count,
        COUNT(CASE WHEN ci.due_date < CURRENT_DATE THEN 1 END)::int      AS overdue_count
      FROM customer_invoices ci
      WHERE ci.status IN ('approved', 'sent', 'partially_paid', 'overdue')
        AND (ci.total_amount - ci.amount_paid) > 0
    `) as Row[];

    const rateRows = (await sql`
      SELECT
        SUM(ci.total_amount)  AS invoiced,
        SUM(ci.amount_paid)   AS collected
      FROM customer_invoices ci
      WHERE ci.status NOT IN ('draft', 'cancelled')
    `) as Row[];

    const r = rows[0] ?? {};
    const rate = rateRows[0] ?? {};
    const invoiced = Number(rate.invoiced ?? 0);
    const collected = Number(rate.collected ?? 0);

    return {
      totalOutstanding: Number(r.total_outstanding ?? 0),
      totalOverdue: Number(r.total_overdue ?? 0),
      avgDaysOutstanding: Math.round(Number(r.avg_days_outstanding ?? 0)),
      collectionRate: invoiced > 0 ? Math.round((collected / invoiced) * 100 * 10) / 10 : 0,
      clientCount: Number(r.client_count ?? 0),
      overdueCount: Number(r.overdue_count ?? 0),
    };
  } catch (err) {
    log.error('getCollectionStats failed', { error: err }, 'accounting');
    throw err;
  }
}

/**
 * DRC (Domestic Reverse Charge) VAT Service
 * Phase 5: Handle DRC VAT for supplier invoices
 *
 * DRC applies when a supplier provides certain services and the recipient
 * (FibreFlow) is responsible for accounting for VAT on those supplies.
 * Instead of the supplier charging VAT, the buyer self-accounts:
 *   DR Input VAT (1140)   — claimable
 *   CR Output VAT (2120)  — payable (net effect = zero)
 *
 * The invoice amount stays the same but both sides of VAT are recorded.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { createJournalEntry, postJournalEntry } from './journalEntryService';
import { getSystemAccountId } from './systemAccountResolver';
import type { JournalLineInput } from '../types/gl.types';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

const DEFAULT_VAT_RATE = 0.15; // SA VAT rate

/** Load VAT rate from app_settings, falling back to 15% */
async function getVatRate(): Promise<number> {
  try {
    const rows = (await sql`SELECT value FROM app_settings WHERE key = 'vat_rate'`) as Row[];
    if (rows[0]?.value) {
      const rate = Number(rows[0].value);
      if (rate > 0 && rate < 1) return rate;
    }
  } catch (error) { log.warn('Failed to fetch VAT rate from DB, using default', { error }, 'drcVatService'); }
  return DEFAULT_VAT_RATE;
}

export interface DRCResult {
  supplierInvoiceId: string;
  vatAmount: number;
  journalEntryId: string;
}

/**
 * Apply DRC VAT to a supplier invoice.
 * Creates a journal entry: DR Input VAT, CR Output VAT.
 */
export async function applyDRCVat(companyId: string, 
  supplierInvoiceId: string,
  userId: string
): Promise<DRCResult> {
  // Get invoice details
  const invoices = (await sql`
    SELECT si.id, si.invoice_number, si.total_amount, si.is_drc
    FROM supplier_invoices si
    WHERE si.id = ${supplierInvoiceId}::UUID
  `) as Row[];

  if (!invoices[0]) throw new Error('Supplier invoice not found');
  const inv = invoices[0];

  if (inv.is_drc) throw new Error('DRC VAT already applied to this invoice');

  const totalExclVat = Number(inv.total_amount);
  const vatRate = await getVatRate();
  const vatAmount = Math.round(totalExclVat * vatRate * 100) / 100;

  // Get VAT account IDs by subtype (code-independent)
  const inputVatId = await getSystemAccountId('vat_input');
  const outputVatId = await getSystemAccountId('vat_output');

  const description = `DRC VAT: ${inv.invoice_number} (R${vatAmount.toFixed(2)})`;

  const lines: JournalLineInput[] = [
    { glAccountId: String(inputVatId), debit: vatAmount, credit: 0, description },
    { glAccountId: String(outputVatId), debit: 0, credit: vatAmount, description },
  ];

  const je = await createJournalEntry('', {
    entryDate: new Date().toISOString().split('T')[0] ?? '',
    description,
    source: 'auto_vat_adjustment',
    sourceDocumentId: supplierInvoiceId,
    lines,
  }, userId);

  await postJournalEntry('', je.id, userId);

  // Mark invoice as DRC processed
  await sql`
    UPDATE supplier_invoices SET is_drc = true WHERE id = ${supplierInvoiceId}::UUID
  `;

  log.info('Applied DRC VAT', {
    supplierInvoiceId, vatAmount, journalEntryId: je.id,
  }, 'accounting');

  return { supplierInvoiceId, vatAmount, journalEntryId: je.id };
}

/**
 * Get all DRC-eligible supplier invoices (not yet processed).
 */
export async function getDRCEligibleInvoices(companyId: string): Promise<Array<{
  id: string; invoiceNumber: string; supplierName: string;
  totalAmount: number; vatAmount: number; invoiceDate: string;
}>> {
  const rows = (await sql`
    SELECT si.id, si.invoice_number, si.total_amount, si.invoice_date,
           s.company_name as supplier_name
    FROM supplier_invoices si
    LEFT JOIN suppliers s ON s.id = si.supplier_id
    WHERE si.status IN ('approved', 'partially_paid', 'paid')
      AND (si.is_drc IS NULL OR si.is_drc = false)
    ORDER BY si.invoice_date DESC
  `) as Row[];

  const vatRate = await getVatRate();
  return rows.map((r: Row) => ({
    id: String(r.id),
    invoiceNumber: String(r.invoice_number),
    supplierName: String(r.supplier_name || 'Unknown'),
    totalAmount: Number(r.total_amount),
    vatAmount: Math.round(Number(r.total_amount) * vatRate * 100) / 100,
    invoiceDate: String(r.invoice_date).split('T')[0] ?? '',
  }));
}

/**
 * Get DRC VAT history (already processed).
 */
export async function getDRCHistory(companyId: string): Promise<Array<{
  id: string; invoiceNumber: string; supplierName: string;
  totalAmount: number; invoiceDate: string;
}>> {
  const rows = (await sql`
    SELECT si.id, si.invoice_number, si.total_amount, si.invoice_date,
           s.company_name as supplier_name
    FROM supplier_invoices si
    LEFT JOIN suppliers s ON s.id = si.supplier_id
    WHERE si.is_drc = true
    ORDER BY si.invoice_date DESC
  `) as Row[];

  return rows.map((r: Row) => ({
    id: String(r.id),
    invoiceNumber: String(r.invoice_number),
    supplierName: String(r.supplier_name || 'Unknown'),
    totalAmount: Number(r.total_amount),
    invoiceDate: String(r.invoice_date).split('T')[0] ?? '',
  }));
}

/**
 * Cash Flow Forecasting Service
 * Projects future cash position based on historical patterns,
 * recurring invoices, known payables, and seasonal trends.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

// ── Types ────────────────────────────────────────────────────────────────────

export interface CashFlowForecastPoint {
  date: string;          // YYYY-MM-DD
  label: string;         // "Apr 2026", "Week 14", etc.
  projectedInflow: number;
  projectedOutflow: number;
  projectedNet: number;
  projectedBalance: number;
  confidence: number;    // 0-1
}

export interface CashFlowAlert {
  type: 'warning' | 'danger';
  message: string;
  date: string;
  projectedBalance: number;
}

export interface CashFlowForecastResult {
  currentBalance: number;
  forecastPoints: CashFlowForecastPoint[];
  alerts: CashFlowAlert[];
  assumptions: string[];
  generatedAt: string;
}

export interface HistoricalCashFlow {
  month: string;
  inflow: number;
  outflow: number;
  net: number;
}

// ── Historical Analysis ──────────────────────────────────────────────────────

/** Get current total cash balance across all bank accounts */
async function getCurrentCashBalance(): Promise<number> {
  const rows = (await sql`
    SELECT COALESCE(SUM(
      CASE WHEN ga.account_subtype IN ('bank', 'cash')
        THEN COALESCE(
          (SELECT SUM(jl.debit) - SUM(jl.credit)
           FROM gl_journal_lines jl
           JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
           WHERE jl.gl_account_id = ga.id
             AND je.status = 'posted'),
          0)
        ELSE 0
      END
    ), 0) AS total_cash
    FROM gl_accounts ga
    WHERE ga.account_type = 'asset'
      AND ga.account_subtype IN ('bank', 'cash')
      AND ga.is_active = true
  `) as Row[];
  return Number(rows[0]?.total_cash ?? 0);
}

/** Get monthly cash inflows and outflows for the last N months */
async function getHistoricalCashFlows(months: number): Promise<HistoricalCashFlow[]> {
  // Compute the start date in JS to avoid interval arithmetic in tagged templates
  const startDate = new Date();
  startDate.setMonth(startDate.getMonth() - months);
  const startStr = startDate.toISOString().split('T')[0]!;

  const rows = (await sql`
    WITH monthly AS (
      SELECT
        date_trunc('month', je.entry_date) AS month,
        COALESCE(SUM(CASE WHEN jl.debit > 0 AND ga.account_subtype IN ('bank', 'cash') THEN jl.debit ELSE 0 END), 0) AS inflow,
        COALESCE(SUM(CASE WHEN jl.credit > 0 AND ga.account_subtype IN ('bank', 'cash') THEN jl.credit ELSE 0 END), 0) AS outflow
      FROM gl_journal_lines jl
      JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
      JOIN gl_accounts ga ON ga.id = jl.gl_account_id
      WHERE je.status = 'posted'
        AND ga.account_type = 'asset'
        AND ga.account_subtype IN ('bank', 'cash')
        AND je.entry_date >= ${startStr}::DATE
      GROUP BY date_trunc('month', je.entry_date)
    )
    SELECT
      to_char(month, 'YYYY-MM') AS month,
      inflow,
      outflow,
      (inflow - outflow) AS net
    FROM monthly
    ORDER BY month ASC
  `) as Row[];

  return rows.map((r: Row) => ({
    month: r.month,
    inflow: Number(r.inflow),
    outflow: Number(r.outflow),
    net: Number(r.net),
  }));
}

/** Get known future receivables (unpaid customer invoices) */
async function getExpectedReceivables(): Promise<Array<{ dueDate: string; amount: number }>> {
  const rows = (await sql`
    SELECT due_date, SUM(total_amount - COALESCE(amount_paid, 0)) AS amount_due
    FROM customer_invoices
    WHERE status IN ('sent', 'overdue', 'approved')
      AND due_date >= CURRENT_DATE
      AND (total_amount - COALESCE(amount_paid, 0)) > 0
    GROUP BY due_date
    ORDER BY due_date ASC
  `) as Row[];

  return rows.map((r: Row) => ({
    dueDate: r.due_date,
    amount: Number(r.amount_due),
  }));
}

/** Get known future payables (unpaid supplier invoices) */
async function getExpectedPayables(): Promise<Array<{ dueDate: string; amount: number }>> {
  const rows = (await sql`
    SELECT due_date, SUM(total_amount - COALESCE(amount_paid, 0)) AS amount_due
    FROM supplier_invoices
    WHERE status IN ('approved', 'received', 'overdue')
      AND due_date >= CURRENT_DATE
      AND (total_amount - COALESCE(amount_paid, 0)) > 0
    GROUP BY due_date
    ORDER BY due_date ASC
  `) as Row[];

  return rows.map((r: Row) => ({
    dueDate: r.due_date,
    amount: Number(r.amount_due),
  }));
}

/** Get recurring invoice amounts for projection */
async function getRecurringRevenue(): Promise<number> {
  const rows = (await sql`
    SELECT COALESCE(SUM(total_amount), 0) AS monthly_recurring
    FROM recurring_invoices
    WHERE status = 'active'
      AND frequency = 'monthly'
  `) as Row[];
  return Number(rows[0]?.monthly_recurring ?? 0);
}

// ── Forecasting Engine ───────────────────────────────────────────────────────

/**
 * Generate a cash flow forecast for the next N months.
 * Uses a blend of:
 * 1. Known receivables and payables (high confidence)
 * 2. Recurring invoices (medium-high confidence)
 * 3. Historical average patterns (medium confidence)
 * 4. Seasonal adjustment from same month prior year (lower confidence)
 */
export async function generateForecast(companyId: string, 
  forecastMonths = 6,
  alertThreshold = 0
): Promise<CashFlowForecastResult> {
  const [currentBalance, historical, receivables, payables, recurringRevenue] = await Promise.all([
    getCurrentCashBalance(),
    getHistoricalCashFlows(12),
    getExpectedReceivables(),
    getExpectedPayables(),
    getRecurringRevenue(),
  ]);

  // Calculate historical averages
  const avgInflow = historical.length > 0
    ? historical.reduce((sum, h) => sum + h.inflow, 0) / historical.length
    : 0;
  const avgOutflow = historical.length > 0
    ? historical.reduce((sum, h) => sum + h.outflow, 0) / historical.length
    : 0;

  // Build month-by-month forecast
  const forecastPoints: CashFlowForecastPoint[] = [];
  const alerts: CashFlowAlert[] = [];
  let runningBalance = currentBalance;
  const now = new Date();

  for (let i = 1; i <= forecastMonths; i++) {
    const forecastDate = new Date(now.getFullYear(), now.getMonth() + i, 1);
    const monthStr = forecastDate.toISOString().slice(0, 7); // YYYY-MM
    const monthLabel = forecastDate.toLocaleDateString('en-ZA', { month: 'short', year: 'numeric' });

    // Known receivables due this month
    const knownInflows = receivables
      .filter(r => String(r.dueDate).startsWith(monthStr))
      .reduce((sum, r) => sum + r.amount, 0);

    // Known payables due this month
    const knownOutflows = payables
      .filter(p => String(p.dueDate).startsWith(monthStr))
      .reduce((sum, p) => sum + p.amount, 0);

    // Projected inflow: known receivables + recurring revenue + historical average for unknowns
    const knownInflowWeight = knownInflows > 0 ? 0.7 : 0;
    const historicalInflowWeight = 1 - knownInflowWeight;
    const projectedInflow = knownInflows + recurringRevenue + (avgInflow * historicalInflowWeight * 0.5);

    // Projected outflow: known payables + historical average for unknowns
    const knownOutflowWeight = knownOutflows > 0 ? 0.7 : 0;
    const historicalOutflowWeight = 1 - knownOutflowWeight;
    const projectedOutflow = knownOutflows + (avgOutflow * historicalOutflowWeight * 0.5);

    const projectedNet = projectedInflow - projectedOutflow;
    runningBalance += projectedNet;

    // Confidence decreases as we project further out
    const baseConfidence = 0.9;
    const decayFactor = 0.1;
    const knownDataBoost = (knownInflows + knownOutflows > 0) ? 0.1 : 0;
    const confidence = Math.max(0.3, baseConfidence - (i * decayFactor) + knownDataBoost);

    forecastPoints.push({
      date: forecastDate.toISOString().slice(0, 10),
      label: monthLabel,
      projectedInflow: Math.round(projectedInflow * 100) / 100,
      projectedOutflow: Math.round(projectedOutflow * 100) / 100,
      projectedNet: Math.round(projectedNet * 100) / 100,
      projectedBalance: Math.round(runningBalance * 100) / 100,
      confidence: Math.round(confidence * 100) / 100,
    });

    // Generate alerts
    if (runningBalance < alertThreshold) {
      alerts.push({
        type: runningBalance < 0 ? 'danger' : 'warning',
        message: runningBalance < 0
          ? `Projected negative cash balance of R ${Math.abs(runningBalance).toLocaleString('en-ZA', { minimumFractionDigits: 2 })} in ${monthLabel}`
          : `Cash balance projected to drop below threshold in ${monthLabel}`,
        date: forecastDate.toISOString().slice(0, 10),
        projectedBalance: Math.round(runningBalance * 100) / 100,
      });
    }
  }

  // Build assumptions list
  const assumptions: string[] = [];
  if (historical.length > 0) {
    assumptions.push(`Based on ${historical.length} months of historical data`);
  } else {
    assumptions.push('Limited historical data — forecast accuracy may be low');
  }
  if (recurringRevenue > 0) {
    assumptions.push(`Includes R ${recurringRevenue.toLocaleString('en-ZA', { minimumFractionDigits: 2 })} monthly recurring revenue`);
  }
  if (receivables.length > 0) {
    const totalAR = receivables.reduce((s, r) => s + r.amount, 0);
    assumptions.push(`${receivables.length} outstanding invoices totalling R ${totalAR.toLocaleString('en-ZA', { minimumFractionDigits: 2 })}`);
  }
  if (payables.length > 0) {
    const totalAP = payables.reduce((s, p) => s + p.amount, 0);
    assumptions.push(`${payables.length} outstanding payables totalling R ${totalAP.toLocaleString('en-ZA', { minimumFractionDigits: 2 })}`);
  }
  assumptions.push('Confidence decreases for months further in the future');

  log.info('Cash flow forecast generated', {
    months: forecastMonths,
    currentBalance,
    pointCount: forecastPoints.length,
    alertCount: alerts.length,
  }, 'accounting');

  return {
    currentBalance: Math.round(currentBalance * 100) / 100,
    forecastPoints,
    alerts,
    assumptions,
    generatedAt: new Date().toISOString(),
  };
}

