/**
 * Customer Categories Management
 * Sage Parity: Lists > Customer Categories
 */

import { useState, useEffect, useCallback } from 'react';
import { AppLayout } from '@/components/layout/AppLayout';
import { Tag, Plus, Pencil, Trash2, Loader2, X, Check } from 'lucide-react';
import { apiFetch } from '@/lib/apiFetch';

interface Category { id: string; name: string; description: string; clientCount: number; }

export default function CustomerCategoriesPage() {
  const [items, setItems] = useState<Category[]>([]);
  const [loading, setLoading] = useState(true);
  const [editing, setEditing] = useState<string | null>(null);
  const [adding, setAdding] = useState(false);
  const [form, setForm] = useState({ name: '', description: '' });
  const [busy, setBusy] = useState(false);

  const load = useCallback(async () => {
    const res = await apiFetch('/api/accounting/customer-categories', { credentials: 'include' });
    const json = await res.json();
    setItems(json.data || []);
    setLoading(false);
  }, []);

  useEffect(() => { load(); }, [load]);

  const save = async () => {
    if (!form.name.trim()) return;
    setBusy(true);
    const method = editing ? 'PUT' : 'POST';
    const body = editing ? { id: editing, ...form } : form;
    await apiFetch('/api/accounting/customer-categories', {
      method, headers: { 'Content-Type': 'application/json' },
      credentials: 'include', body: JSON.stringify(body),
    });
    setForm({ name: '', description: '' });
    setEditing(null); setAdding(false); setBusy(false);
    await load();
  };

  const remove = async (id: string) => {
    if (!confirm('Delete this category?')) return;
    await apiFetch('/api/accounting/customer-categories', {
      method: 'DELETE', headers: { 'Content-Type': 'application/json' },
      credentials: 'include', body: JSON.stringify({ id }),
    });
    await load();
  };

  const startEdit = (cat: Category) => {
    setEditing(cat.id);
    setForm({ name: cat.name, description: cat.description });
    setAdding(false);
  };

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)] px-6 py-4">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <div className="p-2 rounded-lg bg-blue-500/10"><Tag className="h-6 w-6 text-blue-500" /></div>
              <div>
                <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">Customer Categories</h1>
                <p className="text-sm text-[var(--ff-text-secondary)]">Organize and classify customers</p>
              </div>
            </div>
            {!adding && !editing && (
              <button onClick={() => { setAdding(true); setForm({ name: '', description: '' }); }}
                className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 text-sm font-medium">
                <Plus className="h-4 w-4" /> Add Category
              </button>
            )}
          </div>
        </div>

        <div className="p-6">
          <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] overflow-hidden">
            <table className="w-full text-sm">
              <thead><tr className="border-b border-[var(--ff-border-light)] text-left text-[var(--ff-text-secondary)]">
                <th className="px-4 py-3">Name</th><th className="px-4 py-3">Description</th>
                <th className="px-4 py-3 text-right">Customers</th><th className="px-4 py-3 w-24">Actions</th>
              </tr></thead>
              <tbody>
                {(adding || editing) && (
                  <tr className="border-b border-[var(--ff-border-light)] bg-blue-500/5">
                    <td className="px-4 py-2">
                      <input value={form.name} onChange={e => setForm({ ...form, name: e.target.value })}
                        placeholder="Category name" className="w-full px-2 py-1 bg-[var(--ff-bg-tertiary)] border border-[var(--ff-border-light)] rounded text-[var(--ff-text-primary)] text-sm" />
                    </td>
                    <td className="px-4 py-2">
                      <input value={form.description} onChange={e => setForm({ ...form, description: e.target.value })}
                        placeholder="Description" className="w-full px-2 py-1 bg-[var(--ff-bg-tertiary)] border border-[var(--ff-border-light)] rounded text-[var(--ff-text-primary)] text-sm" />
                    </td>
                    <td />
                    <td className="px-4 py-2">
                      <div className="flex items-center gap-1">
                        <button onClick={save} disabled={busy} className="p-1 text-teal-400 hover:text-teal-300">
                          {busy ? <Loader2 className="h-4 w-4 animate-spin" /> : <Check className="h-4 w-4" />}
                        </button>
                        <button onClick={() => { setAdding(false); setEditing(null); }} className="p-1 text-red-400 hover:text-red-300">
                          <X className="h-4 w-4" />
                        </button>
                      </div>
                    </td>
                  </tr>
                )}
                {loading && <tr><td colSpan={4} className="px-4 py-8 text-center text-[var(--ff-text-tertiary)]">Loading...</td></tr>}
                {!loading && items.length === 0 && !adding && (
                  <tr><td colSpan={4} className="px-4 py-8 text-center text-[var(--ff-text-tertiary)]">No categories yet</td></tr>
                )}
                {items.map(cat => editing === cat.id ? null : (
                  <tr key={cat.id} className="border-b border-[var(--ff-border-light)] hover:bg-[var(--ff-bg-primary)]/50">
                    <td className="px-4 py-3 text-[var(--ff-text-primary)] font-medium">{cat.name}</td>
                    <td className="px-4 py-3 text-[var(--ff-text-secondary)]">{cat.description || '-'}</td>
                    <td className="px-4 py-3 text-right text-[var(--ff-text-secondary)]">{cat.clientCount}</td>
                    <td className="px-4 py-3">
                      <div className="flex items-center gap-1">
                        <button onClick={() => startEdit(cat)} className="p-1 text-blue-400 hover:text-blue-300"><Pencil className="h-4 w-4" /></button>
                        <button onClick={() => remove(cat.id)} className="p-1 text-red-400 hover:text-red-300"><Trash2 className="h-4 w-4" /></button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    </AppLayout>
  );
}

/**
 * WebhookForm — add/edit webhook endpoint form
 */

import { RefreshCw, Copy, Loader2 } from 'lucide-react';
import { WEBHOOK_EVENTS } from '@/modules/accounting/services/webhookService';

const INPUT_CLS = 'w-full px-3 py-2 text-sm bg-[var(--ff-bg-primary)] border border-[var(--ff-border-light)] rounded-lg text-[var(--ff-text-primary)] placeholder-[var(--ff-text-secondary)] focus:outline-none focus:ring-2 focus:ring-teal-500/30';
const BTN_PRIMARY = 'inline-flex items-center gap-2 px-4 py-2 bg-teal-600 text-white rounded-lg hover:bg-teal-700 transition-colors text-sm font-medium';
const BTN_GHOST = 'inline-flex items-center gap-2 px-3 py-1.5 text-sm text-[var(--ff-text-secondary)] border border-[var(--ff-border-light)] rounded-lg hover:bg-[var(--ff-bg-primary)] transition-colors';

export interface WebhookFormState {
  name: string; url: string; secret: string; events: string[]; isActive: boolean;
}

interface Props {
  form: WebhookFormState;
  isEdit: boolean;
  saving: boolean;
  onChange: (updates: Partial<WebhookFormState>) => void;
  onSave: () => void;
  onCancel: () => void;
}

export function generateSecret(): string {
  return Array.from(crypto.getRandomValues(new Uint8Array(24)))
    .map(b => b.toString(16).padStart(2, '0')).join('');
}

export function WebhookForm({ form, isEdit, saving, onChange, onSave, onCancel }: Props) {
  const toggleEvent = (ev: string) => {
    onChange({
      events: form.events.includes(ev)
        ? form.events.filter(e => e !== ev)
        : [...form.events, ev],
    });
  };

  return (
    <div className="bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)] rounded-lg p-5">
      <h2 className="text-base font-semibold text-[var(--ff-text-primary)] mb-4">
        {isEdit ? 'Edit Webhook' : 'New Webhook'}
      </h2>
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 mb-4">
        <div>
          <label className="block text-xs font-medium text-[var(--ff-text-secondary)] mb-1">Name</label>
          <input className={INPUT_CLS} placeholder="e.g. Slack Notifications" value={form.name}
            onChange={e => onChange({ name: e.target.value })} />
        </div>
        <div>
          <label className="block text-xs font-medium text-[var(--ff-text-secondary)] mb-1">Endpoint URL</label>
          <input className={INPUT_CLS} placeholder="https://example.com/webhook" value={form.url}
            onChange={e => onChange({ url: e.target.value })} />
        </div>
        <div>
          <label className="block text-xs font-medium text-[var(--ff-text-secondary)] mb-1">
            Secret (HMAC-SHA256)
          </label>
          <div className="flex gap-2">
            <input className={INPUT_CLS} placeholder="Leave blank for none" value={form.secret}
              onChange={e => onChange({ secret: e.target.value })} />
            <button type="button" onClick={() => onChange({ secret: generateSecret() })} className={BTN_GHOST} title="Generate">
              <RefreshCw className="h-3.5 w-3.5" />
            </button>
            {form.secret && (
              <button type="button" onClick={() => void navigator.clipboard.writeText(form.secret)} className={BTN_GHOST} title="Copy">
                <Copy className="h-3.5 w-3.5" />
              </button>
            )}
          </div>
        </div>
        <div className="flex items-center gap-3 pt-5">
          <input type="checkbox" id="wh-isActive" checked={form.isActive}
            onChange={e => onChange({ isActive: e.target.checked })} className="w-4 h-4 accent-teal-500" />
          <label htmlFor="wh-isActive" className="text-sm text-[var(--ff-text-primary)]">Active</label>
        </div>
      </div>
      <div className="mb-4">
        <label className="block text-xs font-medium text-[var(--ff-text-secondary)] mb-2">Events to subscribe</label>
        <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-4 gap-2">
          {WEBHOOK_EVENTS.map(ev => (
            <label key={ev} className="flex items-center gap-2 text-sm text-[var(--ff-text-primary)] cursor-pointer">
              <input type="checkbox" checked={form.events.includes(ev)} onChange={() => toggleEvent(ev)} className="accent-teal-500" />
              <span className="font-mono text-xs">{ev}</span>
            </label>
          ))}
        </div>
      </div>
      <div className="flex gap-2">
        <button onClick={onSave} disabled={saving} className={BTN_PRIMARY}>
          {saving ? <Loader2 className="h-4 w-4 animate-spin" /> : null}
          {saving ? 'Saving...' : 'Save'}
        </button>
        <button onClick={onCancel} className={BTN_GHOST}>Cancel</button>
      </div>
    </div>
  );
}

// DML/DDL keywords that must never appear in a read-only query
const FORBIDDEN_KEYWORDS = [
  'INSERT', 'UPDATE', 'DELETE', 'DROP', 'ALTER', 'TRUNCATE', 'CREATE',
  'GRANT', 'REVOKE', 'EXEC', 'EXECUTE', 'UNION', 'INFORMATION_SCHEMA',
  'PG_CATALOG', 'INTO OUTFILE', 'LOAD_FILE',
  // PostgreSQL administrative / file-access / control keywords
  'COPY', 'DO', 'CALL', 'PREPARE', 'LISTEN', 'NOTIFY', 'LOAD', 'IMPORT',
  // PostgreSQL file-access and server-control functions
  'PG_READ_FILE', 'PG_READ_BINARY_FILE', 'PG_LS_DIR',
  'LO_IMPORT', 'LO_EXPORT', 'PG_SLEEP',
  // Runtime configuration manipulation
  'CURRENT_SETTING', 'SET_CONFIG', 'PG_TERMINATE_BACKEND', 'PG_CANCEL_BACKEND',
];

// Dangerous function-call patterns that warrant a separate regex sweep
const FORBIDDEN_PATTERNS: Array<{ label: string; regex: RegExp }> = [
  // Any pg_ function invocation (covers pg_read_file, pg_ls_dir, etc.)
  { label: 'pg_ function call', regex: /\bpg_\w+\s*\(/i },
  // dblink — cross-database tunnelling
  { label: 'dblink call', regex: /\bdblink\s*\(/i },
  // COPY with TO or FROM (data exfiltration / injection)
  { label: 'COPY TO/FROM', regex: /\bCOPY\b[\s\S]*?\b(TO|FROM)\b/i },
];

const MAX_LIMIT = 100;

export function validateGeneratedSQL(sql: string): SQLValidation {
  if (!sql || sql.trim() === '') {
    return { valid: false, error: 'Empty SQL', sanitizedSQL: '' };
  }

  const upper = sql.toUpperCase().trim();

  // Must start with SELECT or WITH
  if (!upper.startsWith('SELECT') && !upper.startsWith('WITH')) {
    return { valid: false, error: 'Query must be a SELECT statement', sanitizedSQL: '' };
  }

  // Check for forbidden keywords using word-boundary, case-insensitive match
  for (const kw of FORBIDDEN_KEYWORDS) {
    const regex = new RegExp(`\\b${kw}\\b`, 'i');
    if (regex.test(sql)) {
      return { valid: false, error: `Forbidden keyword: ${kw}`, sanitizedSQL: '' };
    }
  }

  // Check for dangerous function-call patterns
  for (const { label, regex } of FORBIDDEN_PATTERNS) {
    if (regex.test(sql)) {
      return { valid: false, error: `Forbidden pattern detected: ${label}`, sanitizedSQL: '' };
    }
  }

  // Reject multiple statements
  const statements = sql.split(';').filter(s => s.trim().length > 0);
  if (statements.length > 1) {
    return { valid: false, error: 'Multiple statements not allowed', sanitizedSQL: '' };
  }

  // Add LIMIT if not present
  let sanitizedSQL = sql.trim().replace(/;$/, '');
  if (!/\bLIMIT\b/i.test(sanitizedSQL)) {
    sanitizedSQL += ` LIMIT ${MAX_LIMIT}`;
  }

  return { valid: true, sanitizedSQL };
}

// ═══════════════════════════════════════════════════════════════════════════
// QUERY INTENT CLASSIFICATION
// ═══════════════════════════════════════════════════════════════════════════

const INTENT_PATTERNS: Array<{ intent: QueryIntent; patterns: RegExp[] }> = [
  { intent: 'revenue', patterns: [/\brevenue\b/i, /\bsales\b/i, /\bincome\b/i, /\bturnover\b/i, /\bbilling\b/i] },
  { intent: 'expense', patterns: [/\bexpens/i, /\bcost\b/i, /\bspend/i, /\bpurchas/i] },
  { intent: 'customer', patterns: [/\bcustomer/i, /\bclient/i, /\bdebtor/i, /\breceivable/i] },
  { intent: 'supplier', patterns: [/\bsupplier/i, /\bvendor/i, /\bcreditor/i, /\bpayable/i] },
  { intent: 'cash', patterns: [/\bcash\b/i, /\bbank\b/i, /\bbalance\b/i, /\bliquidity/i] },
  { intent: 'tax', patterns: [/\bvat\b/i, /\btax\b/i, /\bsars\b/i, /\bpaye\b/i] },
  { intent: 'payroll', patterns: [/\bpayroll\b/i, /\bsalary\b/i, /\bwage/i, /\bemploee/i] },
  { intent: 'inventory', patterns: [/\binventory\b/i, /\bstock\b/i, /\bproduct/i] },
];

export function classifyQueryIntent(question: string): QueryIntent {
  for (const { intent, patterns } of INTENT_PATTERNS) {
    if (patterns.some(p => p.test(question))) return intent;
  }
  return 'general';
}

