/**
 * Neon Database Client
 * Standalone serverless PostgreSQL connection for the Accounting app
 * Uses @neondatabase/serverless with retry logic and proper config
 */

import { neon, neonConfig, Pool } from '@neondatabase/serverless';
import { log } from '@/lib/logger';

// Enable connection caching for better performance
neonConfig.fetchConnectionCache = true;

// Configure transport for Node.js environments (not in browser/edge)
declare const EdgeRuntime: unknown;

const isNodeEnv =
  typeof window === 'undefined' &&
  typeof EdgeRuntime === 'undefined';

if (isNodeEnv) {
  const useHttpTransport = process.env.NEON_USE_HTTP === 'true';

  if (!useHttpTransport) {
    // WebSocket transport - faster for Node.js
    try {
      // eslint-disable-next-line @typescript-eslint/no-var-requires
      const ws = require('ws');
      neonConfig.webSocketConstructor = ws;
      log.info('Using WebSocket transport', {}, 'Neon');
    } catch {
      log.info('WebSocket not available, falling back to HTTP', {}, 'Neon');
    }
  } else {
    log.info('Using HTTP transport (NEON_USE_HTTP=true)', {}, 'Neon');
  }

  // Configure WebSocket proxy (Neon v2 protocol)
  neonConfig.wsProxy = (host: string, port: number | string) => `${host}:${port}/v2`;

  // Use secure WebSocket connections
  neonConfig.useSecureWebSocket = true;

  // Pipeline authentication for faster connections
  neonConfig.pipelineConnect = 'password';

  // Enable automatic retries on transient errors
  neonConfig.fetchFunction = async (...args: Parameters<typeof fetch>) => {
    const maxRetries = 3;
    let lastError: unknown;

    for (let i = 0; i < maxRetries; i++) {
      try {
        const response = await fetch(...args);
        if (!response.ok && response.status >= 500 && i < maxRetries - 1) {
          // Retry on server errors with exponential backoff
          await new Promise(resolve => setTimeout(resolve, Math.pow(2, i) * 100));
          continue;
        }
        return response;
      } catch (error) {
        lastError = error;
        if (i < maxRetries - 1) {
          // Exponential backoff: 100ms, 200ms, 400ms
          await new Promise(resolve => setTimeout(resolve, Math.pow(2, i) * 100));
          continue;
        }
      }
    }
    throw lastError || new Error('Request failed after retries');
  };
}

/**
 * Get the DATABASE_URL, throwing a clear error if not set
 */
function getDatabaseUrl(): string {
  const url = process.env.DATABASE_URL;
  if (!url) {
    throw new Error('DATABASE_URL is not set. Please configure it in your environment.');
  }
  return url;
}

/**
 * Serverless SQL client for use in API routes and edge functions.
 * Use tagged template literals: sql`SELECT * FROM table WHERE id = ${id}`
 */
export const sql = neon(getDatabaseUrl());

/**
 * Execute multiple queries in a transaction using the Neon serverless driver.
 *
 * IMPORTANT: The Neon HTTP driver is stateless — each tagged template call is an
 * independent HTTP request. Issuing BEGIN/COMMIT as separate calls does NOT
 * guarantee they run on the same connection. We use the official `transaction()`
 * API from @neondatabase/serverless which batches queries into a single HTTP request.
 *
 * @param queries - Array of query-producing functions that receive the sql client
 * @returns Array of query results
 *
 * @example
 * const results = await transaction([
 *   (sql) => sql`INSERT INTO accounts (name) VALUES (${'Cash'}) RETURNING id`,
 *   (sql) => sql`UPDATE balances SET amount = 0 WHERE account_id = ${id}`,
 * ]);
 */
export async function transaction(
  queriesFn: (txSql: typeof sql) => Array<ReturnType<typeof sql>>
): Promise<unknown[]> {
  try {
    const txClient = neon(getDatabaseUrl());
    const results = await txClient.transaction(
      (tx) => queriesFn(tx as unknown as typeof sql) as any,
      { isolationLevel: 'ReadCommitted' }
    );
    return results as unknown[];
  } catch (error) {
    log.error(
      'Transaction failed',
      error instanceof Error ? { message: error.message } : { error },
      'Neon'
    );
    throw error;
  }
}

export default sql;

/**
 * DRC (Domestic Reverse Charge) VAT Page
 * Phase 5: Self-account VAT on eligible supplier invoices
 */

import { useState, useEffect, useCallback } from 'react';
import { AppLayout } from '@/components/layout/AppLayout';
import { ArrowRightLeft, Loader2, Check } from 'lucide-react';
import { ExportCSVButton } from '@/components/shared/ExportCSVButton';
import { apiFetch } from '@/lib/apiFetch';

interface Invoice {
  id: string; invoiceNumber: string; supplierName: string;
  totalAmount: number; vatAmount: number; invoiceDate: string;
}

const fmt = (n: number) => new Intl.NumberFormat('en-ZA', { style: 'currency', currency: 'ZAR' }).format(n);

export default function DRCVatPage() {
  const [eligible, setEligible] = useState<Invoice[]>([]);
  const [history, setHistory] = useState<Invoice[]>([]);
  const [tab, setTab] = useState<'eligible' | 'history'>('eligible');
  const [loading, setLoading] = useState(true);
  const [busy, setBusy] = useState('');
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');

  const load = useCallback(async () => {
    setLoading(true);
    const [eligRes, histRes] = await Promise.all([
      apiFetch('/api/accounting/drc-vat', { credentials: 'include' }),
      apiFetch('/api/accounting/drc-vat?tab=history', { credentials: 'include' }),
    ]);
    const eligJson = await eligRes.json();
    const histJson = await histRes.json();
    setEligible(eligJson.data?.items || []);
    setHistory(histJson.data?.items || []);
    setLoading(false);
  }, []);

  useEffect(() => { load(); }, [load]);

  const applyDRC = async (invoiceId: string) => {
    setBusy(invoiceId); setError(''); setSuccess('');
    try {
      const res = await apiFetch('/api/accounting/drc-vat', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        credentials: 'include', body: JSON.stringify({ supplierInvoiceId: invoiceId }),
      });
      const json = await res.json();
      if (!res.ok) throw new Error(json.message || 'Failed');
      setSuccess(`DRC VAT applied: ${fmt(json.data?.vatAmount || 0)}`);
      await load();
    } catch (err) { setError(err instanceof Error ? err.message : 'Failed'); }
    finally { setBusy(''); }
  };

  const items = tab === 'eligible' ? eligible : history;

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)] px-6 py-4">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <div className="p-2 rounded-lg bg-rose-500/10"><ArrowRightLeft className="h-6 w-6 text-rose-500" /></div>
              <div>
                <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">DRC VAT</h1>
                <p className="text-sm text-[var(--ff-text-secondary)]">Domestic Reverse Charge — self-account VAT on supplier invoices</p>
              </div>
            </div>
            <ExportCSVButton endpoint="/api/accounting/drc-vat-export" filenamePrefix="drc-vat" label="Export CSV" />
          </div>
        </div>

        <div className="p-6 space-y-4">
          {error && <div className="p-3 rounded-lg bg-red-500/10 text-red-400 text-sm">{error}</div>}
          {success && <div className="p-3 rounded-lg bg-teal-500/10 text-teal-400 text-sm">{success}</div>}

          {/* Info box */}
          <div className="bg-rose-500/5 border border-rose-500/20 rounded-lg p-4 text-sm text-[var(--ff-text-secondary)]">
            <strong className="text-rose-400">How DRC works:</strong> When a supplier doesn&apos;t charge VAT on their invoice,
            FibreFlow self-accounts both Input VAT (claimable) and Output VAT (payable). The net effect is zero,
            but both sides are recorded for SARS compliance. Select invoices below to apply DRC VAT at 15%.
          </div>

          {/* Tabs */}
          <div className="flex gap-1 bg-[var(--ff-bg-secondary)] rounded-lg p-1 w-fit border border-[var(--ff-border-light)]">
            <button onClick={() => setTab('eligible')}
              className={`px-4 py-2 rounded-md text-sm font-medium transition-colors ${tab === 'eligible' ? 'bg-rose-600 text-white' : 'text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)]'}`}>
              Eligible ({eligible.length})
            </button>
            <button onClick={() => setTab('history')}
              className={`px-4 py-2 rounded-md text-sm font-medium transition-colors ${tab === 'history' ? 'bg-rose-600 text-white' : 'text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)]'}`}>
              Processed ({history.length})
            </button>
          </div>

          <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] overflow-hidden">
            <table className="w-full text-sm">
              <thead><tr className="border-b border-[var(--ff-border-light)] text-left text-[var(--ff-text-secondary)]">
                <th className="px-4 py-3">Invoice</th><th className="px-4 py-3">Supplier</th>
                <th className="px-4 py-3">Date</th>
                <th className="px-4 py-3 text-right">Amount (excl)</th>
                <th className="px-4 py-3 text-right">VAT (15%)</th>
                {tab === 'eligible' && <th className="px-4 py-3">Action</th>}
              </tr></thead>
              <tbody>
                {loading && <tr><td colSpan={6} className="px-4 py-8 text-center text-[var(--ff-text-tertiary)]">Loading...</td></tr>}
                {!loading && items.length === 0 && (
                  <tr><td colSpan={6} className="px-4 py-8 text-center text-[var(--ff-text-tertiary)]">
                    {tab === 'eligible' ? 'No eligible invoices for DRC VAT.' : 'No DRC VAT history.'}
                  </td></tr>
                )}
                {items.map(inv => (
                  <tr key={inv.id} className="border-b border-[var(--ff-border-light)] hover:bg-[var(--ff-bg-primary)]/50">
                    <td className="px-4 py-3 text-[var(--ff-text-primary)] font-medium">{inv.invoiceNumber}</td>
                    <td className="px-4 py-3 text-[var(--ff-text-secondary)]">{inv.supplierName}</td>
                    <td className="px-4 py-3 text-[var(--ff-text-secondary)]">{inv.invoiceDate}</td>
                    <td className="px-4 py-3 text-right text-[var(--ff-text-primary)]">{fmt(inv.totalAmount)}</td>
                    <td className="px-4 py-3 text-right text-rose-400 font-medium">{fmt(inv.vatAmount || inv.totalAmount * 0.15)}</td>
                    {tab === 'eligible' && (
                      <td className="px-4 py-3">
                        <button onClick={() => applyDRC(inv.id)} disabled={busy === inv.id}
                          className="inline-flex items-center gap-1 px-3 py-1.5 bg-rose-600 text-white rounded-md text-xs font-medium hover:bg-rose-700 disabled:opacity-50">
                          {busy === inv.id ? <Loader2 className="h-3 w-3 animate-spin" /> : <Check className="h-3 w-3" />}
                          Apply DRC
                        </button>
                      </td>
                    )}
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    </AppLayout>
  );
}

/**
 * New Item Page
 * Route: /accounting/items/new
 */
import { useState, useEffect, useCallback } from 'react';
import { AppLayout } from '@/components/layout/AppLayout';
import { Package, Save, ArrowLeft, Loader2 } from 'lucide-react';
import Link from 'next/link';
import { useRouter } from 'next/router';
import { apiFetch } from '@/lib/apiFetch';
import { useCompany } from '@/contexts/CompanyContext';

interface Category {
  id: string;
  name: string;
}

interface Account {
  id: string;
  account_number: string;
  name: string;
}

const VAT_OPTIONS = [
  { value: 'standard', label: 'Standard (15%)' },
  { value: 'zero', label: 'Zero Rated (0%)' },
  { value: 'exempt', label: 'Exempt' },
];

export default function NewItemPage() {
  const router = useRouter();
  const { activeCompany: company } = useCompany();
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');
  const [categories, setCategories] = useState<Category[]>([]);
  const [accounts, setAccounts] = useState<Account[]>([]);

  const [form, setForm] = useState({
    code: '',
    description: '',
    category_id: '',
    item_type: 'physical' as 'physical' | 'service',
    is_active: true,
    unit: 'each',
    cost_price: '',
    selling_price_excl: '',
    selling_price_incl: '',
    gp_percent: '',
    vat_on_sales: 'standard',
    vat_on_purchases: 'standard',
    sales_account_id: '',
    purchases_account_id: '',
    opening_qty: '',
    opening_cost: '',
    opening_date: '',
    notes: '',
  });

  const loadCategories = useCallback(async () => {
    try {
      const res = await apiFetch('/api/accounting/item-categories', { credentials: 'include' });
      const json = await res.json();
      setCategories(json.data || []);
    } catch {
      setCategories([]);
    }
  }, []);

  const loadAccounts = useCallback(async () => {
    try {
      const res = await apiFetch('/api/accounting/chart-of-accounts', { credentials: 'include' });
      const json = await res.json();
      setAccounts(json.data || []);
    } catch {
      setAccounts([]);
    }
  }, []);

  useEffect(() => {
    loadCategories();
    loadAccounts();
  }, [loadCategories, loadAccounts]);

  const update = (field: string, value: string | boolean) => {
    setForm(prev => {
      const next = { ...prev, [field]: value };

      // Auto-calculate GP% when cost and excl selling price change
      if (field === 'cost_price' || field === 'selling_price_excl') {
        const cost = Number(field === 'cost_price' ? value : next.cost_price) || 0;
        const excl = Number(field === 'selling_price_excl' ? value : next.selling_price_excl) || 0;
        if (excl > 0 && cost >= 0) {
          next.gp_percent = (((excl - cost) / excl) * 100).toFixed(2);
        }
      }

      // Auto-calculate inclusive price from exclusive (VAT 15%)
      if (field === 'selling_price_excl') {
        const excl = Number(value) || 0;
        const vatRate = next.vat_on_sales === 'standard' ? 0.15 : 0;
        next.selling_price_incl = (excl * (1 + vatRate)).toFixed(2);
      }

      // Auto-calculate exclusive price from inclusive
      if (field === 'selling_price_incl') {
        const incl = Number(value) || 0;
        const vatRate = next.vat_on_sales === 'standard' ? 0.15 : 0;
        const excl = vatRate > 0 ? incl / (1 + vatRate) : incl;
        next.selling_price_excl = excl.toFixed(2);
        const cost = Number(next.cost_price) || 0;
        if (excl > 0 && cost >= 0) {
          next.gp_percent = (((excl - cost) / excl) * 100).toFixed(2);
        }
      }

      // Recalculate inclusive when VAT type changes
      if (field === 'vat_on_sales') {
        const excl = Number(next.selling_price_excl) || 0;
        const vatRate = value === 'standard' ? 0.15 : 0;
        next.selling_price_incl = (excl * (1 + vatRate)).toFixed(2);
      }

      return next;
    });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setSaving(true);
    try {
      const payload = {
        code: form.code || undefined,
        description: form.description,
        category_id: form.category_id || undefined,
        item_type: form.item_type,
        is_active: form.is_active,
        unit: form.unit,
        cost_price: Number(form.cost_price) || 0,
        selling_price_excl: Number(form.selling_price_excl) || 0,
        selling_price_incl: Number(form.selling_price_incl) || 0,
        gp_percent: Number(form.gp_percent) || 0,
        vat_on_sales: form.vat_on_sales,
        vat_on_purchases: form.vat_on_purchases,
        sales_account_id: form.sales_account_id || undefined,
        purchases_account_id: form.purchases_account_id || undefined,
        opening_qty: Number(form.opening_qty) || 0,
        opening_cost: Number(form.opening_cost) || 0,
        opening_date: form.opening_date || undefined,
        notes: form.notes || undefined,
      };

      const res = await apiFetch('/api/accounting/items', {
        method: 'POST',
        credentials: 'include',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      });
      const json = await res.json();
      if (!res.ok) {
        throw new Error(json.error?.message || 'Failed to create item');
      }
      router.push('/accounting/items');
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to create item');
    } finally {
      setSaving(false);
    }
  };

  const salesAccounts = accounts.filter(
    a => String(a.account_number).startsWith('4') || String(a.name).toLowerCase().includes('sales')
  );
  const purchaseAccounts = accounts.filter(
    a => String(a.account_number).startsWith('5') || String(a.name).toLowerCase().includes('purchase') || String(a.name).toLowerCase().includes('cost')
  );

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        {/* Header */}
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)] px-6 py-4">
          <div className="flex items-center gap-3">
            <Link
              href="/accounting/items"
              className="p-2 rounded-lg hover:bg-[var(--ff-bg-primary)]"
            >
              <ArrowLeft className="h-5 w-5 text-[var(--ff-text-secondary)]" />
            </Link>
            <div className="p-2 rounded-lg bg-blue-500/10">
              <Package className="h-6 w-6 text-blue-500" />
            </div>
            <div>
              <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">New Item</h1>
              <p className="text-sm text-[var(--ff-text-secondary)]">
                Add a new inventory or service item
                {company?.name ? ` for ${company.name}` : ''}
              </p>
            </div>
          </div>
        </div>

        <form onSubmit={handleSubmit} className="p-6 max-w-3xl space-y-6">
          {error && (
            <div className="p-3 rounded-lg bg-red-500/10 text-red-400 text-sm">{error}</div>
          )}

          {/* Item Details */}
          <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] p-5 space-y-4">
            <h2 className="text-sm font-semibold text-[var(--ff-text-primary)]">Item Details</h2>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <label className="block text-sm text-[var(--ff-text-secondary)] mb-1">
                  Code <span className="text-[var(--ff-text-tertiary)]">(auto-generated if blank)</span>
                </label>
                <input
                  type="text"
                  value={form.code}
                  onChange={e => update('code', e.target.value)}
                  className="ff-input w-full"
                  placeholder="ITEM-0001"
