/**
 * Execute a sequential, multi-step transaction using a dedicated pool client.
 *
 * Unlike `transaction()` above (which batches static queries in a single HTTP
 * round-trip), `withTransaction` allows you to `await` intermediate results
 * inside the callback — necessary when later queries depend on IDs returned by
 * earlier ones (e.g. INSERT … RETURNING id → INSERT … WHERE fk = id).
 *
 * The pool client issues genuine BEGIN / COMMIT / ROLLBACK over a WebSocket
 * connection, giving full ACID guarantees.  Any error thrown inside `fn` will
 * trigger an automatic ROLLBACK and the error is re-thrown.
 *
 * @example
 * const result = await withTransaction(async (client) => {
 *   const [row] = await client.query(
 *     'INSERT INTO orders (total) VALUES ($1) RETURNING id',
 *     [total]
 *   );
 *   await client.query(
 *     'INSERT INTO order_items (order_id, sku) VALUES ($1, $2)',
 *     [row.id, sku]
 *   );
 *   return row.id;
 * });
 */
let _pool: InstanceType<typeof Pool> | null = null;

function getPool(): InstanceType<typeof Pool> {
  if (!_pool) {
    _pool = new Pool({ connectionString: getDatabaseUrl() });
  }
  return _pool;
}

export async function withTransaction<T>(
  fn: (client: { query: (text: string, values?: unknown[]) => Promise<{ rows: unknown[] }> }) => Promise<T>
): Promise<T> {
  const pool = getPool();
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    const result = await fn(client as unknown as { query: (text: string, values?: unknown[]) => Promise<{ rows: unknown[] }> });
    await client.query('COMMIT');
    return result;
  } catch (error) {
    await client.query('ROLLBACK');
    log.error(
      'withTransaction rolled back',
      error instanceof Error ? { message: error.message } : { error },
      'Neon'
    );
    throw error;
  } finally {
    client.release();
  }
}

