/**
 * GET /api/auth/2fa-status
 * Return current 2FA status for the authenticated user.
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withAuth } from '@/lib/auth/middleware';
import type { AuthenticatedNextApiRequest } from '@/lib/auth/middleware';
import { apiResponse } from '@/lib/apiResponse';
import { get2FAStatus } from '@/modules/auth/services/twoFactorService';
import { log } from '@/lib/logger';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method ?? 'unknown', ['GET']);
  }

  const { user } = req as AuthenticatedNextApiRequest;

  try {
    const status = await get2FAStatus(user.id);
    return apiResponse.success(res, status);
  } catch (err) {
    log.error('2fa-status error', err instanceof Error ? { message: err.message } : { err }, 'api/auth/2fa-status');
    return apiResponse.internalError(res, err);
  }
}

export default withAuth(handler);

/**
 * GET  /api/auth/2fa-trusted-devices  — List trusted devices
 * DELETE /api/auth/2fa-trusted-devices?id=UUID — Remove a trusted device
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withAuth } from '@/lib/auth/middleware';
import type { AuthenticatedNextApiRequest } from '@/lib/auth/middleware';
import { apiResponse } from '@/lib/apiResponse';
import { getTrustedDevices, removeTrustedDevice } from '@/modules/auth/services/twoFactorService';
import { log } from '@/lib/logger';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  const { user } = req as AuthenticatedNextApiRequest;

  if (req.method === 'GET') {
    try {
      const devices = await getTrustedDevices(user.id);
      return apiResponse.success(res, { devices });
    } catch (err) {
      log.error('2fa-trusted-devices GET error', err instanceof Error ? { message: err.message } : { err }, 'api/auth/2fa-trusted-devices');
      return apiResponse.internalError(res, err);
    }
  }

  if (req.method === 'DELETE') {
    const { id } = req.query;
    if (!id || typeof id !== 'string') {
      return apiResponse.badRequest(res, 'Device ID is required');
    }

    try {
      await removeTrustedDevice(user.id, id);
      log.info('Trusted device removed via API', { userId: user.id, deviceId: id }, 'api/auth/2fa-trusted-devices');
      return apiResponse.success(res, null, 'Device removed');
    } catch (err) {
      log.error('2fa-trusted-devices DELETE error', err instanceof Error ? { message: err.message } : { err }, 'api/auth/2fa-trusted-devices');
      return apiResponse.internalError(res, err);
    }
  }

  return apiResponse.methodNotAllowed(res, req.method ?? 'unknown', ['GET', 'DELETE']);
}

export default withAuth(handler);

/**
 * POST /api/auth/2fa-verify-setup
 * Verify initial TOTP code and enable 2FA for the authenticated user.
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withAuth } from '@/lib/auth/middleware';
import type { AuthenticatedNextApiRequest } from '@/lib/auth/middleware';
import { apiResponse } from '@/lib/apiResponse';
import { verifyTOTPSetup } from '@/modules/auth/services/twoFactorService';
import { log } from '@/lib/logger';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method ?? 'unknown', ['POST']);
  }

  const { user } = req as AuthenticatedNextApiRequest;
  const { code } = req.body as { code?: string };

  if (!code || typeof code !== 'string' || code.trim().length === 0) {
    return apiResponse.badRequest(res, 'Verification code is required');
  }

  try {
    const result = await verifyTOTPSetup(user.id, code.trim());

    if (!result.success) {
      return res.status(400).json({
        success: false,
        error: { code: 'INVALID_CODE', message: 'Invalid or expired verification code' },
      });
    }

    log.info('2FA enabled via setup verification', { userId: user.id }, 'api/auth/2fa-verify-setup');

    return apiResponse.success(res, {
      backupCodes: result.backupCodes,
    }, '2FA enabled successfully. Save your backup codes — they will not be shown again.');
  } catch (err) {
    log.error('2fa-verify-setup error', err instanceof Error ? { message: err.message } : { err }, 'api/auth/2fa-verify-setup');
    return apiResponse.internalError(res, err);
  }
}

export default withAuth(handler);

