/**
 * Sales by Customer Report
 * Sage Parity: Customers > Reports > Sales by Customer
 */

import { useState, useEffect, useCallback } from 'react';
import { AppLayout } from '@/components/layout/AppLayout';
import { TrendingUp, Loader2, Download } from 'lucide-react';
import { apiFetch } from '@/lib/apiFetch';

const fmt = (n: number) => new Intl.NumberFormat('en-ZA', { style: 'currency', currency: 'ZAR' }).format(n);

interface Row { clientId: string; clientName: string; invoiceCount: number; totalSales: number; paymentsReceived: number; outstanding: number; }

export default function SalesByCustomerReport() {
  const [rows, setRows] = useState<Row[]>([]);
  const [loading, setLoading] = useState(true);
  const today = new Date();
  const [from, setFrom] = useState(new Date(today.getFullYear(), today.getMonth(), 1).toISOString().split('T')[0]);
  const [to, setTo] = useState(today.toISOString().split('T')[0]);

  const load = useCallback(async () => {
    setLoading(true);
    const res = await apiFetch(`/api/accounting/reports/sales-by-customer?from=${from}&to=${to}`, { credentials: 'include' });
    const json = await res.json();
    setRows(json.data || []);
    setLoading(false);
  }, [from, to]);

  useEffect(() => { load(); }, [load]);

  const totals = rows.reduce((a, r) => ({
    invoiceCount: a.invoiceCount + r.invoiceCount,
    totalSales: a.totalSales + r.totalSales,
    paymentsReceived: a.paymentsReceived + r.paymentsReceived,
    outstanding: a.outstanding + r.outstanding,
  }), { invoiceCount: 0, totalSales: 0, paymentsReceived: 0, outstanding: 0 });

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)] px-6 py-4">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <div className="p-2 rounded-lg bg-blue-500/10"><TrendingUp className="h-6 w-6 text-blue-500" /></div>
              <div>
                <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">Sales by Customer</h1>
                <p className="text-sm text-[var(--ff-text-secondary)]">Revenue breakdown per customer</p>
              </div>
            </div>
            <div className="flex items-center gap-3">
              <input type="date" value={from} onChange={e => setFrom(e.target.value)} className="ff-input text-sm" />
              <span className="text-[var(--ff-text-tertiary)]">to</span>
              <input type="date" value={to} onChange={e => setTo(e.target.value)} className="ff-input text-sm" />
              <button onClick={() => window.open(`/api/accounting/reports/sales-by-customer?from=${from}&to=${to}&format=csv`, '_blank')}
                className="flex items-center gap-1.5 px-3 py-1.5 text-sm bg-blue-600 hover:bg-blue-500 text-white rounded-lg">
                <Download className="h-4 w-4" /> CSV
              </button>
            </div>
          </div>
        </div>

        <div className="p-6">
          <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] overflow-hidden">
            {loading ? (
              <div className="p-8 text-center"><Loader2 className="h-6 w-6 animate-spin text-[var(--ff-text-tertiary)] mx-auto" /></div>
            ) : rows.length === 0 ? (
              <div className="p-8 text-center text-[var(--ff-text-tertiary)]">No sales data for this period</div>
            ) : (
              <table className="w-full text-sm">
                <thead><tr className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-tertiary)]">
                  <th className="px-4 py-3 text-left text-xs font-medium text-[var(--ff-text-secondary)] uppercase">Customer</th>
                  <th className="px-4 py-3 text-right text-xs font-medium text-[var(--ff-text-secondary)] uppercase">Invoices</th>
                  <th className="px-4 py-3 text-right text-xs font-medium text-[var(--ff-text-secondary)] uppercase">Total Sales</th>
                  <th className="px-4 py-3 text-right text-xs font-medium text-[var(--ff-text-secondary)] uppercase">Received</th>
                  <th className="px-4 py-3 text-right text-xs font-medium text-[var(--ff-text-secondary)] uppercase">Outstanding</th>
                </tr></thead>
                <tbody className="divide-y divide-[var(--ff-border-light)]">
                  {rows.map(r => (
                    <tr key={r.clientId} className="hover:bg-[var(--ff-bg-tertiary)]">
                      <td className="px-4 py-3 text-[var(--ff-text-primary)] font-medium">{r.clientName}</td>
                      <td className="px-4 py-3 text-right text-[var(--ff-text-secondary)]">{r.invoiceCount}</td>
                      <td className="px-4 py-3 text-right font-mono text-[var(--ff-text-primary)]">{fmt(r.totalSales)}</td>
                      <td className="px-4 py-3 text-right font-mono text-teal-400">{fmt(r.paymentsReceived)}</td>
                      <td className="px-4 py-3 text-right font-mono text-amber-400">{fmt(r.outstanding)}</td>
                    </tr>
                  ))}
                </tbody>
                <tfoot><tr className="border-t-2 border-[var(--ff-border-medium)] bg-[var(--ff-bg-tertiary)] font-bold">
                  <td className="px-4 py-3 text-[var(--ff-text-primary)]">TOTAL</td>
                  <td className="px-4 py-3 text-right text-[var(--ff-text-secondary)]">{totals.invoiceCount}</td>
                  <td className="px-4 py-3 text-right font-mono text-[var(--ff-text-primary)]">{fmt(totals.totalSales)}</td>
                  <td className="px-4 py-3 text-right font-mono text-teal-400">{fmt(totals.paymentsReceived)}</td>
                  <td className="px-4 py-3 text-right font-mono text-amber-400">{fmt(totals.outstanding)}</td>
                </tr></tfoot>
              </table>
            )}
          </div>
        </div>
      </div>
    </AppLayout>
  );
}

/**
 * VAT Adjustments Export API
 * GET — export VAT adjustments as CSV
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { sql } from '@/lib/neon';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';

function csvCell(v: string): string { return `"${String(v || '').replace(/"/g, '""')}"`; }

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET']);

  const { companyId } = req as CompanyApiRequest;

  try {
    const rows = await sql`
      SELECT adjustment_number, adjustment_date, vat_period,
        adjustment_type, amount, reason, status
      FROM vat_adjustments WHERE company_id = ${companyId} ORDER BY adjustment_date DESC
    `;

    const csvLines = [
      'Adjustment No,Date,VAT Period,Type,Amount,Reason,Status',
      ...rows.map((r: Record<string, unknown>) => [
        csvCell(String(r.adjustment_number)),
        csvCell(String(r.adjustment_date)),
        csvCell(String(r.vat_period || '')),
        csvCell(String(r.adjustment_type)),
        Number(r.amount || 0).toFixed(2),
        csvCell(String(r.reason || '')),
        csvCell(String(r.status)),
      ].join(',')),
    ];

    res.setHeader('Content-Type', 'text/csv');
    res.setHeader('Content-Disposition', `attachment; filename="vat-adjustments-${new Date().toISOString().split('T')[0]}.csv"`);
    return res.status(200).send(csvLines.join('\n'));
  } catch (err) {
    log.error('VAT adjustments export failed', { error: err });
    return apiResponse.badRequest(res, 'Failed to export VAT adjustments');
  }
}

export default withCompany(handler);

/**
 * Year-End Export API
 * GET — export fiscal year summaries as CSV
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { sql } from '@/lib/neon';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';

function csvCell(v: string): string { return `"${String(v || '').replace(/"/g, '""')}"`; }

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET']);

  const { companyId } = req as CompanyApiRequest;

  try {
    const rows = await sql`
      SELECT fiscal_year, MIN(start_date) AS start_date, MAX(end_date) AS end_date,
        CASE WHEN COUNT(*) FILTER (WHERE status = 'open') > 0 THEN 'open' ELSE 'closed' END AS status
      FROM fiscal_periods
      WHERE company_id = ${companyId}
      GROUP BY fiscal_year
      ORDER BY fiscal_year DESC
    `;

    const csvLines = [
      'Year,Start Date,End Date,Status',
      ...rows.map((r: Record<string, unknown>) => [
        csvCell(String(r.fiscal_year)),
        csvCell(String(r.start_date)),
        csvCell(String(r.end_date)),
        csvCell(String(r.status)),
      ].join(',')),
    ];

    res.setHeader('Content-Type', 'text/csv');
    res.setHeader('Content-Disposition', `attachment; filename="year-end-${new Date().toISOString().split('T')[0]}.csv"`);
    return res.status(200).send(csvLines.join('\n'));
  } catch (err) {
    log.error('Year-end export failed', { error: err });
    return apiResponse.badRequest(res, 'Failed to export year-end data');
  }
}

export default withCompany(handler);

/**
 * Customer Receipt Allocations API
 * GET  — List existing allocations (audit trail)
 * POST — Allocate receipts against outstanding invoices
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { sql } from '@/lib/neon';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';

interface AllocationItem {
  invoiceId: string;
  amount: number;
}

async function handler(req: NextApiRequest, res: NextApiResponse) {
  const { companyId } = req as CompanyApiRequest;

  if (req.method === 'GET') {
    try {
      const paymentId = req.query.payment_id as string | undefined;
      const clientId = req.query.client_id as string | undefined;

      let rows;
      if (paymentId) {
        rows = await sql`
          SELECT cpa.id, cpa.payment_id, cpa.invoice_id, cpa.amount_allocated AS amount,
            cpa.created_at AS allocated_at, cp.payment_number, ci.invoice_number,
            c.name AS client_name
          FROM customer_payment_allocations cpa
          JOIN customer_payments cp ON cp.id = cpa.payment_id
          JOIN customer_invoices ci ON ci.id = cpa.invoice_id
          JOIN customers c ON c.id = cp.client_id
          WHERE cpa.payment_id = ${paymentId}
            AND cp.company_id = ${companyId}
          ORDER BY cpa.created_at DESC
        `;
      } else if (clientId) {
        rows = await sql`
          SELECT cpa.id, cpa.payment_id, cpa.invoice_id, cpa.amount_allocated AS amount,
            cpa.created_at AS allocated_at, cp.payment_number, ci.invoice_number,
            c.name AS client_name
          FROM customer_payment_allocations cpa
          JOIN customer_payments cp ON cp.id = cpa.payment_id
          JOIN customer_invoices ci ON ci.id = cpa.invoice_id
          JOIN customers c ON c.id = cp.client_id
          WHERE cp.client_id = ${clientId}
            AND cp.company_id = ${companyId}
          ORDER BY cpa.created_at DESC
          LIMIT 200
        `;
      } else {
        rows = await sql`
          SELECT cpa.id, cpa.payment_id, cpa.invoice_id, cpa.amount_allocated AS amount,
            cpa.created_at AS allocated_at, cp.payment_number, ci.invoice_number,
            c.name AS client_name
          FROM customer_payment_allocations cpa
          JOIN customer_payments cp ON cp.id = cpa.payment_id
          JOIN customer_invoices ci ON ci.id = cpa.invoice_id
          JOIN customers c ON c.id = cp.client_id
          WHERE cp.company_id = ${companyId}
          ORDER BY cpa.created_at DESC
          LIMIT 200
        `;
      }

      return apiResponse.success(res, rows);
    } catch (err) {
      log.error('Failed to get customer allocations', { error: err });
      return apiResponse.badRequest(res, 'Failed to get allocations');
    }
  }

  if (req.method === 'POST') {
    try {
      const { paymentId, allocations } = req.body as {
        paymentId?: string;
        allocations?: AllocationItem[];
      };

      if (!paymentId) return apiResponse.badRequest(res, 'paymentId is required');
      if (!allocations || !Array.isArray(allocations) || allocations.length === 0) {
        return apiResponse.badRequest(res, 'allocations array is required');
      }

      // Validate allocation items
      for (const alloc of allocations) {
        if (!alloc.invoiceId || !alloc.amount || alloc.amount <= 0) {
          return apiResponse.badRequest(res, 'Each allocation needs invoiceId and positive amount');
        }
      }

      // Fetch payment
      const paymentRows = await sql`
        SELECT cp.id, cp.client_id, cp.total_amount, cp.status,
          COALESCE((SELECT SUM(amount_allocated) FROM customer_payment_allocations WHERE payment_id = cp.id), 0) AS allocated_amount
        FROM customer_payments cp WHERE cp.id = ${paymentId} AND cp.company_id = ${companyId}
      `;
      const payment = paymentRows[0];
      if (!payment) return apiResponse.notFound(res, 'Payment', paymentId);
      if (payment.status === 'cancelled') {
        return apiResponse.badRequest(res, 'Cannot allocate a cancelled payment');
      }

      const currentAllocated = Number(payment.allocated_amount || 0);
      const totalPayment = Number(payment.total_amount);
      const allocTotal = allocations.reduce((s, a) => s + a.amount, 0);

      if (currentAllocated + allocTotal > totalPayment + 0.01) {
        return apiResponse.badRequest(res, `Allocation total (${allocTotal}) exceeds available balance (${(totalPayment - currentAllocated).toFixed(2)})`);
      }

      // Process each allocation
      const results: { invoiceId: string; amount: number; newStatus: string }[] = [];

      for (const alloc of allocations) {
        // Validate invoice belongs to same client
        const invoiceRows = await sql`
          SELECT id, client_id, total_amount, amount_paid, status
          FROM customer_invoices WHERE id = ${alloc.invoiceId} AND company_id = ${companyId}
        `;
        const invoice = invoiceRows[0];
        if (!invoice) {
          return apiResponse.badRequest(res, `Invoice ${alloc.invoiceId} not found`);
        }
        if (invoice.client_id !== payment.client_id) {
          return apiResponse.badRequest(res, `Invoice ${alloc.invoiceId} belongs to a different client`);
        }

        const outstanding = Number(invoice.total_amount) - Number(invoice.amount_paid || 0);
        if (alloc.amount > outstanding + 0.01) {
          return apiResponse.badRequest(res, `Allocation ${alloc.amount} exceeds outstanding ${outstanding.toFixed(2)} for invoice ${alloc.invoiceId}`);
        }

        // Insert allocation record
        await sql`
          INSERT INTO customer_payment_allocations (payment_id, invoice_id, amount_allocated)
          VALUES (${paymentId}, ${alloc.invoiceId}, ${alloc.amount})
        `;

        // Update invoice amount_paid
        const newPaid = Number(invoice.amount_paid || 0) + alloc.amount;
        const invoiceTotal = Number(invoice.total_amount);
        const newStatus = newPaid >= invoiceTotal - 0.01 ? 'paid' : 'partially_paid';

        await sql`
          UPDATE customer_invoices
          SET amount_paid = ${newPaid}, status = ${newStatus}
          WHERE id = ${alloc.invoiceId}
        `;

        results.push({ invoiceId: alloc.invoiceId, amount: alloc.amount, newStatus });
      }

      // Update payment allocated_amount
      const newAllocated = currentAllocated + allocTotal;
      const paymentStatus = newAllocated >= totalPayment - 0.01 ? 'reconciled' : 'confirmed';

      await sql`
        UPDATE customer_payments
        SET status = ${paymentStatus}
        WHERE id = ${paymentId}
      `;

      log.info('Customer allocations created', {
        paymentId,
        count: results.length,
        total: allocTotal,
      });

      return apiResponse.success(res, {
        paymentId,
        allocations: results,
        newAllocatedAmount: newAllocated,
        paymentStatus,
      });
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Allocation failed';
      log.error('Customer allocation failed', { error: err });
      return apiResponse.badRequest(res, message);
    }
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'POST']);
}

export default withCompany(handler);

