/**
 * PRD-060: FibreFlow Accounting Module
 * Fiscal Period Service
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import type { FiscalPeriod, FiscalPeriodStatus } from '../types/gl.types';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

export async function getFiscalPeriods(companyId: string, fiscalYear?: number): Promise<FiscalPeriod[]> {
  try {
    let rows: Row[];
    if (fiscalYear) {
      rows = (await sql`
        SELECT * FROM fiscal_periods
        WHERE company_id = ${companyId} AND fiscal_year = ${fiscalYear}
        ORDER BY period_number
      `) as Row[];
    } else {
      rows = (await sql`
        SELECT * FROM fiscal_periods WHERE company_id = ${companyId}
        ORDER BY fiscal_year DESC, period_number
      `) as Row[];
    }
    return rows.map(mapRow);
  } catch (err) {
    log.error('Failed to get fiscal periods', { fiscalYear, error: err }, 'accounting');
    throw err;
  }
}

export async function getFiscalPeriodById(id: string): Promise<FiscalPeriod | null> {
  try {
    const rows = (await sql`SELECT * FROM fiscal_periods WHERE id = ${id}`) as Row[]; // NOTE: id-only lookup used internally — callers must ensure companyId scoping
    return rows.length > 0 ? mapRow(rows[0]) : null;
  } catch (err) {
    log.error('Failed to get fiscal period', { id, error: err }, 'accounting');
    throw err;
  }
}

export async function getCurrentFiscalPeriod(companyId: string): Promise<FiscalPeriod | null> {
  try {
    const rows = (await sql`
      SELECT * FROM fiscal_periods
      WHERE company_id = ${companyId}
        AND start_date <= CURRENT_DATE AND end_date >= CURRENT_DATE
      LIMIT 1
    `) as Row[];
    return rows.length > 0 ? mapRow(rows[0]) : null;
  } catch (err) {
    log.error('Failed to get current fiscal period', { error: err }, 'accounting');
    throw err;
  }
}

export async function createFiscalYear(companyId: string, year: number): Promise<FiscalPeriod[]> {
  try {
    const existing = (await sql`
      SELECT COUNT(*) AS cnt FROM fiscal_periods WHERE company_id = ${companyId} AND fiscal_year = ${year}
    `) as Row[];
    if (Number(existing[0].cnt) > 0) {
      throw new Error(`Fiscal year ${year} already exists`);
    }

    const months = [
      'January', 'February', 'March', 'April', 'May', 'June',
      'July', 'August', 'September', 'October', 'November', 'December',
    ];

    const periods: FiscalPeriod[] = [];
    for (let i = 0; i < 12; i++) {
      const periodNum = i + 1;
      const startDate = `${year}-${String(periodNum).padStart(2, '0')}-01`;
      const lastDay = new Date(year, periodNum, 0).getDate();
      const endDate = `${year}-${String(periodNum).padStart(2, '0')}-${String(lastDay).padStart(2, '0')}`;

      const rows = (await sql`
        INSERT INTO fiscal_periods (company_id, period_name, period_number, fiscal_year, start_date, end_date)
        VALUES (${companyId}, ${months[i]! + ' ' + year}, ${periodNum}, ${year}, ${startDate}, ${endDate})
        RETURNING *
      `) as Row[];
      periods.push(mapRow(rows[0]));
    }

    return periods;
  } catch (err) {
    log.error('Failed to create fiscal year', { year, error: err }, 'accounting');
    throw err;
  }
}

export async function closePeriod(companyId: string, id: string, userId: string): Promise<FiscalPeriod> {
  try {
    const period = await getFiscalPeriodById(id);
    if (!period) throw new Error(`Fiscal period ${id} not found`);
    if (period.status === 'locked') throw new Error('Cannot close a locked period');
    if (period.status === 'closed') throw new Error('Period is already closed');

    const openPrior = (await sql`
      SELECT COUNT(*) AS cnt FROM fiscal_periods
      WHERE company_id = ${companyId}
        AND fiscal_year = ${period.fiscalYear}
        AND period_number < ${period.periodNumber}
        AND status = 'open'
    `) as Row[];
    if (Number(openPrior[0].cnt) > 0) {
      throw new Error('Cannot close period while prior periods are still open');
    }

    const rows = (await sql`
      UPDATE fiscal_periods
      SET status = 'closed', closed_by = ${userId}::UUID, closed_at = NOW()
      WHERE id = ${id} AND company_id = ${companyId}
      RETURNING *
    `) as Row[];
    return mapRow(rows[0]);
  } catch (err) {
    log.error('Failed to close period', { id, error: err }, 'accounting');
    throw err;
  }
}

export async function lockPeriod(companyId: string, id: string): Promise<FiscalPeriod> {
  try {
    const period = await getFiscalPeriodById(id);
    if (!period) throw new Error(`Fiscal period ${id} not found`);
    if (period.status !== 'closed') throw new Error('Period must be closed before locking');

    const rows = (await sql`
      UPDATE fiscal_periods SET status = 'locked' WHERE id = ${id} AND company_id = ${companyId} RETURNING *
    `) as Row[];
    return mapRow(rows[0]);
  } catch (err) {
    log.error('Failed to lock period', { id, error: err }, 'accounting');
    throw err;
  }
}

export async function reopenPeriod(companyId: string, id: string): Promise<FiscalPeriod> {
  try {
    const period = await getFiscalPeriodById(id);
    if (!period) throw new Error(`Fiscal period ${id} not found`);
    if (period.status === 'locked') throw new Error('Cannot reopen a locked period');
    if (period.status === 'open') throw new Error('Period is already open');

    const rows = (await sql`
      UPDATE fiscal_periods
      SET status = 'open', closed_by = NULL, closed_at = NULL
      WHERE id = ${id}
      RETURNING *
    `) as Row[];
    return mapRow(rows[0]);
  } catch (err) {
    log.error('Failed to reopen period', { id, error: err }, 'accounting');
    throw err;
  }
}

function mapRow(row: Row): FiscalPeriod {
  return {
    id: String(row.id),
    periodName: String(row.period_name),
    periodNumber: Number(row.period_number),
    fiscalYear: Number(row.fiscal_year),
    startDate: String(row.start_date),
    endDate: String(row.end_date),
    status: String(row.status) as FiscalPeriodStatus,
    closedBy: row.closed_by ? String(row.closed_by) : undefined,
    closedAt: row.closed_at ? String(row.closed_at) : undefined,
    createdAt: String(row.created_at),
    updatedAt: String(row.updated_at),
  };
}

/**
 * Recurring Journal Service
 * Phase 1 Sage Alignment: Scheduled automated journal entries
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { createJournalEntry, postJournalEntry } from './journalEntryService';
import type { RecurringJournal, RecurringJournalCreateInput, JournalLineInput } from '../types/gl.types';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

export async function getRecurringJournals(companyId: string, filters?: {
  status?: string;
  limit?: number;
  offset?: number;
}): Promise<{ items: RecurringJournal[]; total: number }> {
  const limit = filters?.limit || 50;
  const offset = filters?.offset || 0;
  let rows: Row[];
  let countRows: Row[];

  if (filters?.status) {
    rows = (await sql`
      SELECT * FROM recurring_journals WHERE status = ${filters.status}
      ORDER BY created_at DESC LIMIT ${limit} OFFSET ${offset}
    `) as Row[];
    countRows = (await sql`
      SELECT COUNT(*) AS cnt FROM recurring_journals WHERE status = ${filters.status}
    `) as Row[];
  } else {
    rows = (await sql`
      SELECT * FROM recurring_journals
      ORDER BY created_at DESC LIMIT ${limit} OFFSET ${offset}
    `) as Row[];
    countRows = (await sql`SELECT COUNT(*) AS cnt FROM recurring_journals`) as Row[];
  }

  return { items: rows.map(mapRow), total: Number(countRows[0]?.cnt || 0) };
}

export async function createRecurringJournal(companyId: string, 
  input: RecurringJournalCreateInput,
  userId: string
): Promise<RecurringJournal> {
  // Validate lines balance
  const totalDebit = input.lines.reduce((s, l) => s + l.debit, 0);
  const totalCredit = input.lines.reduce((s, l) => s + l.credit, 0);
  if (Math.abs(totalDebit - totalCredit) > 0.01) {
    throw new Error(`Journal lines do not balance: DR ${totalDebit.toFixed(2)} vs CR ${totalCredit.toFixed(2)}`);
  }

  const rows = (await sql`
    INSERT INTO recurring_journals (
      template_name, description, frequency, next_run_date,
      end_date, lines, total_amount, created_by
    ) VALUES (
      ${input.templateName}, ${input.description || null}, ${input.frequency},
      ${input.nextRunDate}, ${input.endDate || null},
      ${JSON.stringify(input.lines)}::JSONB, ${totalDebit}, ${userId}::UUID
    ) RETURNING *
  `) as Row[];

  log.info('Created recurring journal', { id: rows[0]?.id }, 'accounting');
  return mapRow(rows[0]!);
}

export async function updateRecurringJournalStatus(companyId: string, 
  id: string,
  status: 'paused' | 'active' | 'cancelled'
): Promise<void> {
  await sql`UPDATE recurring_journals SET status = ${status} WHERE id = ${id}`;
  log.info('Updated recurring journal status', { id, status }, 'accounting');
}

export async function generateJournalFromRecurring(companyId: string, 
  id: string,
  userId: string
): Promise<string> {
  const rows = (await sql`SELECT * FROM recurring_journals WHERE id = ${id}`) as Row[];
  if (!rows[0]) throw new Error('Recurring journal not found');
  const rj = rows[0];
  if (rj.status !== 'active') throw new Error('Recurring journal is not active');

  const lines: JournalLineInput[] = Array.isArray(rj.lines) ? rj.lines : JSON.parse(rj.lines || '[]');

  const je = await createJournalEntry('', {
    entryDate: new Date().toISOString().split('T')[0]!,
    description: rj.description || rj.template_name,
    source: 'auto_recurring',
    lines,
  }, userId);
  await postJournalEntry('', je.id, userId);

  // Advance next run date
  const nextDate = advanceDate(String(rj.next_run_date), String(rj.frequency));
  const endDate = rj.end_date ? String(rj.end_date) : null;
  const newStatus = endDate && nextDate > endDate ? 'completed' : 'active';

  await sql`
    UPDATE recurring_journals
    SET last_run_date = CURRENT_DATE, next_run_date = ${nextDate}::DATE,
        run_count = run_count + 1, status = ${newStatus}
    WHERE id = ${id}
  `;

  log.info('Generated journal from recurring', { recurringId: id, journalId: je.id }, 'accounting');
  return je.id;
}

function advanceDate(dateStr: string, frequency: string): string {
  const d = new Date(dateStr);
  switch (frequency) {
    case 'weekly': d.setDate(d.getDate() + 7); break;
    case 'monthly': d.setMonth(d.getMonth() + 1); break;
    case 'quarterly': d.setMonth(d.getMonth() + 3); break;
    case 'annually': d.setFullYear(d.getFullYear() + 1); break;
  }
  return d.toISOString().split('T')[0]!;
}

function mapRow(row: Row): RecurringJournal {
  return {
    id: String(row.id),
    templateName: String(row.template_name),
    description: row.description ? String(row.description) : undefined,
    frequency: String(row.frequency) as RecurringJournal['frequency'],
    nextRunDate: String(row.next_run_date),
    endDate: row.end_date ? String(row.end_date) : undefined,
    lastRunDate: row.last_run_date ? String(row.last_run_date) : undefined,
    runCount: Number(row.run_count),
    status: String(row.status) as RecurringJournal['status'],
    lines: Array.isArray(row.lines) ? row.lines : JSON.parse(row.lines || '[]'),
    totalAmount: Number(row.total_amount),
    createdBy: String(row.created_by),
    createdAt: String(row.created_at),
    updatedAt: String(row.updated_at),
  };
}

/**
 * Opening Balances Export API
 * GET — export GL opening balances as CSV
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { sql } from '@/lib/neon';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import { withErrorHandler } from '@/lib/api-error-handler';

function csvCell(v: string): string { return `"${String(v || '').replace(/"/g, '""')}"`; }

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET']);

  const { companyId } = req as CompanyApiRequest;

  try {
    const rows = await sql`
      SELECT a.account_code, a.account_name, a.account_type, a.normal_balance,
        COALESCE(ob.debit, 0) AS opening_debit, COALESCE(ob.credit, 0) AS opening_credit
      FROM gl_accounts a
      LEFT JOIN (
        SELECT gl_account_id,
          SUM(CASE WHEN debit > 0 THEN debit ELSE 0 END) AS debit,
          SUM(CASE WHEN credit > 0 THEN credit ELSE 0 END) AS credit
        FROM gl_journal_lines jl
        JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
        WHERE je.source = 'opening_balance' AND je.company_id = ${companyId}
        GROUP BY gl_account_id
      ) ob ON ob.gl_account_id = a.id
      WHERE a.company_id = ${companyId}
      ORDER BY a.account_code
    `;

    const csvLines = [
      'Account Code,Account Name,Type,Normal Balance,Opening Debit,Opening Credit',
      ...rows.map((r: Record<string, unknown>) => [
        csvCell(String(r.account_code)),
        csvCell(String(r.account_name)),
        csvCell(String(r.account_type)),
        csvCell(String(r.normal_balance)),
        Number(r.opening_debit || 0).toFixed(2),
        Number(r.opening_credit || 0).toFixed(2),
      ].join(',')),
    ];

    res.setHeader('Content-Type', 'text/csv');
    res.setHeader('Content-Disposition', `attachment; filename="opening-balances-${new Date().toISOString().split('T')[0]}.csv"`);
    return res.status(200).send(csvLines.join('\n'));
  } catch (err) {
    log.error('Opening balances export failed', { error: err });
    return apiResponse.badRequest(res, 'Failed to export opening balances');
  }
}

export default withCompany(handler);

