/**
 * Debtors Manager Service
 * Sage-parity collections/aging dashboard for AR
 *
 * Queries customer_invoices and customer_payments (existing tables).
 * No new migration required.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

// ── Types ─────────────────────────────────────────────────────────────────────

export interface DebtorSummary {
  clientId: string;
  clientName: string;
  current: number;
  days30: number;
  days60: number;
  days90: number;
  days90Plus: number;
  totalOutstanding: number;
  invoiceCount: number;
}

export interface DebtorInvoice {
  id: string;
  invoiceNumber: string;
  invoiceDate: string;
  dueDate: string | null;
  totalAmount: number;
  amountPaid: number;
  outstanding: number;
  daysOverdue: number;
  status: string;
  agingBucket: 'current' | 'days30' | 'days60' | 'days90' | 'days90Plus';
}

export interface OverdueInvoice {
  id: string;
  invoiceNumber: string;
  clientId: string;
  clientName: string;
  invoiceDate: string;
  dueDate: string;
  totalAmount: number;
  amountPaid: number;
  outstanding: number;
  daysOverdue: number;
  status: string;
}

export interface CollectionStats {
  totalOutstanding: number;
  totalOverdue: number;
  avgDaysOutstanding: number;
  collectionRate: number;
  clientCount: number;
  overdueCount: number;
}

// ── Helpers ───────────────────────────────────────────────────────────────────

function classifyBucket(daysOverdue: number): DebtorInvoice['agingBucket'] {
  if (daysOverdue <= 0) return 'current';
  if (daysOverdue <= 30) return 'days30';
  if (daysOverdue <= 60) return 'days60';
  if (daysOverdue <= 90) return 'days90';
  return 'days90Plus';
}

// ── Debtors Summary ───────────────────────────────────────────────────────────

/**
 * Aggregate outstanding invoices by customer with aging buckets.
 * Buckets: current (not yet due), 1-30, 31-60, 61-90, 90+ days overdue.
 */
export async function getDebtorsSummary(companyId: string): Promise<DebtorSummary[]> {
  try {
    const rows = (await sql`
      SELECT
        ci.client_id,
        c.name AS client_name,
        COUNT(ci.id)::int AS invoice_count,
        SUM(
          CASE WHEN ci.due_date IS NULL OR ci.due_date >= CURRENT_DATE
               THEN (ci.total_amount - ci.amount_paid) ELSE 0 END
        ) AS current,
        SUM(
          CASE WHEN ci.due_date IS NOT NULL
                AND ci.due_date < CURRENT_DATE
                AND (CURRENT_DATE - ci.due_date) <= 30
               THEN (ci.total_amount - ci.amount_paid) ELSE 0 END
        ) AS days30,
        SUM(
          CASE WHEN ci.due_date IS NOT NULL
                AND (CURRENT_DATE - ci.due_date) BETWEEN 31 AND 60
               THEN (ci.total_amount - ci.amount_paid) ELSE 0 END
        ) AS days60,
        SUM(
          CASE WHEN ci.due_date IS NOT NULL
                AND (CURRENT_DATE - ci.due_date) BETWEEN 61 AND 90
               THEN (ci.total_amount - ci.amount_paid) ELSE 0 END
        ) AS days90,
        SUM(
          CASE WHEN ci.due_date IS NOT NULL
                AND (CURRENT_DATE - ci.due_date) > 90
               THEN (ci.total_amount - ci.amount_paid) ELSE 0 END
        ) AS days90_plus,
        SUM(ci.total_amount - ci.amount_paid) AS total_outstanding
      FROM customer_invoices ci
      JOIN customers c ON c.id = ci.client_id
      WHERE ci.status IN ('approved', 'sent', 'partially_paid', 'overdue')
        AND (ci.total_amount - ci.amount_paid) > 0
      GROUP BY ci.client_id, c.name
      ORDER BY total_outstanding DESC
    `) as Row[];

    return rows.map((r: Row) => ({
      clientId: String(r.client_id),
      clientName: String(r.client_name),
      current: Number(r.current),
      days30: Number(r.days30),
      days60: Number(r.days60),
      days90: Number(r.days90),
      days90Plus: Number(r.days90_plus),
      totalOutstanding: Number(r.total_outstanding),
      invoiceCount: Number(r.invoice_count),
    }));
  } catch (err) {
    log.error('getDebtorsSummary failed', { error: err }, 'accounting');
    throw err;
  }
}

// ── Debtor Detail ─────────────────────────────────────────────────────────────

/**
 * List outstanding invoices for a specific customer with age and amounts.
 */
export async function getDebtorDetail(companyId: string, clientId: string): Promise<DebtorInvoice[]> {
  try {
    const rows = (await sql`
      SELECT
        ci.id,
        ci.invoice_number,
        ci.invoice_date,
        ci.due_date,
        ci.total_amount,
        ci.amount_paid,
        (ci.total_amount - ci.amount_paid) AS outstanding,
        ci.status,
        CASE
          WHEN ci.due_date IS NULL THEN 0
          ELSE GREATEST(0, (CURRENT_DATE - ci.due_date)::int)
        END AS days_overdue
      FROM customer_invoices ci
      WHERE ci.client_id = ${clientId}::UUID
        AND ci.status IN ('approved', 'sent', 'partially_paid', 'overdue')
        AND (ci.total_amount - ci.amount_paid) > 0
      ORDER BY ci.due_date ASC NULLS LAST, ci.invoice_date ASC
    `) as Row[];

    return rows.map((r: Row) => {
      const daysOverdue = Number(r.days_overdue);
      return {
        id: String(r.id),
        invoiceNumber: String(r.invoice_number),
        invoiceDate: String(r.invoice_date),
        dueDate: r.due_date ? String(r.due_date) : null,
        totalAmount: Number(r.total_amount),
        amountPaid: Number(r.amount_paid),
        outstanding: Number(r.outstanding),
        daysOverdue,
        status: String(r.status),
        agingBucket: classifyBucket(daysOverdue),
      };
    });
  } catch (err) {
    log.error('getDebtorDetail failed', { clientId, error: err }, 'accounting');
    throw err;
  }
}

// ── Overdue Invoices ──────────────────────────────────────────────────────────

/**
 * List all overdue invoices sorted by age descending.
 * Optionally filter to invoices overdue by at least daysOverdue days.
 */
export async function getOverdueInvoices(companyId: string, daysOverdue?: number): Promise<OverdueInvoice[]> {
  const minDays = daysOverdue ?? 1;

  try {
    const rows = (await sql`
      SELECT
        ci.id,
        ci.invoice_number,
        ci.client_id,
        c.name AS client_name,
        ci.invoice_date,
        ci.due_date,
        ci.total_amount,
        ci.amount_paid,
        (ci.total_amount - ci.amount_paid) AS outstanding,
        (CURRENT_DATE - ci.due_date)::int AS days_overdue,
        ci.status
      FROM customer_invoices ci
      JOIN customers c ON c.id = ci.client_id
      WHERE ci.due_date IS NOT NULL
        AND ci.due_date < CURRENT_DATE
        AND (CURRENT_DATE - ci.due_date) >= ${minDays}
        AND ci.status IN ('approved', 'sent', 'partially_paid', 'overdue')
        AND (ci.total_amount - ci.amount_paid) > 0
      ORDER BY days_overdue DESC, ci.total_amount DESC
    `) as Row[];

    return rows.map((r: Row) => ({
      id: String(r.id),
      invoiceNumber: String(r.invoice_number),
      clientId: String(r.client_id),
      clientName: String(r.client_name),
      invoiceDate: String(r.invoice_date),
      dueDate: String(r.due_date),
      totalAmount: Number(r.total_amount),
      amountPaid: Number(r.amount_paid),
      outstanding: Number(r.outstanding),
      daysOverdue: Number(r.days_overdue),
      status: String(r.status),
    }));
  } catch (err) {
    log.error('getOverdueInvoices failed', { daysOverdue, error: err }, 'accounting');
    throw err;
  }
}

// ── Collection Stats ──────────────────────────────────────────────────────────

/**
 * Aggregate collection metrics: total outstanding, total overdue,
 * average days outstanding, and collection rate.
 */
export async function getCollectionStats(companyId: string): Promise<CollectionStats> {
  try {
    const rows = (await sql`
      SELECT
        SUM(ci.total_amount - ci.amount_paid)                            AS total_outstanding,
        SUM(CASE WHEN ci.due_date < CURRENT_DATE
                 THEN (ci.total_amount - ci.amount_paid) ELSE 0 END)     AS total_overdue,
        COALESCE(AVG(
          CASE WHEN ci.due_date IS NOT NULL AND ci.due_date < CURRENT_DATE
               THEN (CURRENT_DATE - ci.due_date)::numeric END
        ), 0)                                                             AS avg_days_outstanding,
        COUNT(DISTINCT ci.client_id)::int                                AS client_count,
        COUNT(CASE WHEN ci.due_date < CURRENT_DATE THEN 1 END)::int      AS overdue_count
      FROM customer_invoices ci
      WHERE ci.status IN ('approved', 'sent', 'partially_paid', 'overdue')
        AND (ci.total_amount - ci.amount_paid) > 0
    `) as Row[];

    const rateRows = (await sql`
      SELECT
        SUM(ci.total_amount)  AS invoiced,
        SUM(ci.amount_paid)   AS collected
      FROM customer_invoices ci
      WHERE ci.status NOT IN ('draft', 'cancelled')
    `) as Row[];

    const r = rows[0] ?? {};
    const rate = rateRows[0] ?? {};
    const invoiced = Number(rate.invoiced ?? 0);
    const collected = Number(rate.collected ?? 0);

    return {
      totalOutstanding: Number(r.total_outstanding ?? 0),
      totalOverdue: Number(r.total_overdue ?? 0),
      avgDaysOutstanding: Math.round(Number(r.avg_days_outstanding ?? 0)),
      collectionRate: invoiced > 0 ? Math.round((collected / invoiced) * 100 * 10) / 10 : 0,
      clientCount: Number(r.client_count ?? 0),
      overdueCount: Number(r.overdue_count ?? 0),
    };
  } catch (err) {
    log.error('getCollectionStats failed', { error: err }, 'accounting');
    throw err;
  }
}

/**
 * Customers API
 * GET  /api/accounting/customers         - List customers (optional ?q= search)
 * POST /api/accounting/customers         - Create a new customer
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { sql } from '@/lib/neon';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import { cacheThrough, cache } from '@/lib/cache';
import { CACHE_KEYS, CACHE_TTL } from '@/lib/cache-keys';
import { withErrorHandler } from '@/lib/api-error-handler';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = Record<string, any>;

export default withCompany(async function handler(req: NextApiRequest, res: NextApiResponse) {
  const { companyId } = req as CompanyApiRequest;
  // ─── GET: List customers ────────────────────────────────────────────────────
  if (req.method === 'GET') {
    try {
      const { q } = req.query;
      const searchTerm = typeof q === 'string' && q.trim() ? `%${q.trim()}%` : null;

      let rows: Row[];

      if (searchTerm) {
        // Search queries are not cached — results change with every keystroke
        rows = (await sql`
          SELECT
            id, name, email, phone, contact_person,
            payment_terms, credit_limit, is_active,
            vat_number, registration_number,
            created_at
          FROM customers
          WHERE company_id = ${companyId}
            AND deleted_at IS NULL
            AND (name ILIKE ${searchTerm}
            OR email ILIKE ${searchTerm}
            OR vat_number ILIKE ${searchTerm}
            OR contact_person ILIKE ${searchTerm})
          ORDER BY name ASC
          LIMIT 200
        `) as Row[];
      } else {
        rows = await cacheThrough(
          CACHE_KEYS.customers(companyId),
          async () => (await sql`
            SELECT
              id, name, email, phone, contact_person,
              payment_terms, credit_limit, is_active,
              vat_number, registration_number,
              created_at
            FROM customers
            WHERE company_id = ${companyId}
              AND deleted_at IS NULL
            ORDER BY name ASC
            LIMIT 200
          `) as Row[],
          CACHE_TTL.REFERENCE_DATA,
        );
      }

      return apiResponse.success(res, rows);
    } catch (err: unknown) {
      const message = err instanceof Error ? err.message : String(err);
      // Return empty list if table does not yet exist
      if (message.includes('does not exist')) {
        return apiResponse.success(res, []);
      }
      log.error('customers GET failed', { error: message, module: 'accounting' });
      return apiResponse.internalError(res, err, 'Failed to fetch customers');
    }
  }

  // ─── POST: Create customer ──────────────────────────────────────────────────
  if (req.method === 'POST') {
    try {
      const b = req.body as Record<string, unknown>;
      const name = b.name as string | undefined;

      if (!name?.trim()) {
        return apiResponse.badRequest(res, 'Customer name is required');
      }

      const s = (k: string) => { const v = b[k]; return typeof v === 'string' && v.trim() ? v.trim() : null; };
      const n = (k: string) => { const v = b[k]; return v !== undefined && v !== null && v !== '' ? Number(v) : null; };
      const bool = (k: string, def = false) => { const v = b[k]; return typeof v === 'boolean' ? v : def; };

      const rows = (await sql`
        INSERT INTO customers (
          company_id, name, email, phone, mobile, fax, web_address,
          vat_number, registration_number,
          billing_address, shipping_address, contact_person,
          payment_terms, payment_terms_type, credit_limit, is_active, notes,
          category_id, cash_sale, opening_balance, opening_balance_date,
          accepts_electronic_invoices, auto_allocate_receipts,
          statement_distribution, default_discount, default_vat_type,
          subject_to_drc_vat, invoices_viewable_online
        ) VALUES (
          ${companyId},
          ${name.trim()},
          ${s('email')},
          ${s('phone')},
          ${s('mobile')},
          ${s('fax')},
          ${s('web_address')},
          ${s('vat_number')},
          ${s('registration_number')},
          ${s('billing_address')},
          ${s('shipping_address')},
          ${s('contact_person')},
          ${n('payment_terms') ?? 30},
          ${s('payment_terms_type') ?? 'days'},
          ${n('credit_limit')},
          ${bool('is_active', true)},
          ${s('notes')},
          ${s('category_id') ? s('category_id') : null}::uuid,
          ${bool('cash_sale')},
          ${n('opening_balance') ?? 0},
          ${s('opening_balance_date')}::date,
          ${bool('accepts_electronic_invoices')},
          ${bool('auto_allocate_receipts')},
          ${s('statement_distribution') ?? 'email'},
          ${n('default_discount') ?? 0},
          ${s('default_vat_type')},
          ${bool('subject_to_drc_vat')},
          ${bool('invoices_viewable_online', true)}
        )
        RETURNING *
      `) as Row[];

      cache.invalidate(CACHE_KEYS.customers(companyId));
      log.info('Customer created', { id: rows[0]?.id, name: rows[0]?.name, module: 'accounting' });
      return apiResponse.success(res, rows[0]);
    } catch (err: unknown) {
      const message = err instanceof Error ? err.message : String(err);
      log.error('customers POST failed', { error: message, module: 'accounting' });
      return apiResponse.internalError(res, err, 'Failed to create customer');
    }
  }

  return apiResponse.methodNotAllowed(res, req.method ?? 'UNKNOWN', ['GET', 'POST']);
});

/**
 * Invoice Service
 * Admin invoice lifecycle for the ISAFlow Admin Platform.
 * Subscription operations are in billingService.ts.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import type { InvoiceListItem, PaginatedResult } from '../types/admin.types';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

function toIso(value: unknown): string | null {
  if (value == null) return null;
  if (value instanceof Date) return value.toISOString();
  return value as string;
}

const ALLOWED_SORT: Record<string, string> = {
  created_at: 'i.created_at',
  due_date: 'i.due_date',
  status: 'i.status',
  total_cents: 'i.total_cents',
  company_name: 'c.name',
  invoice_number: 'i.invoice_number',
};

export async function listInvoices(filters: {
  company_id?: string;
  status?: string;
  from_date?: string;
  to_date?: string;
  search?: string;
  page?: number;
  limit?: number;
  sort_by?: string;
  sort_dir?: 'asc' | 'desc';
}): Promise<PaginatedResult<InvoiceListItem>> {
  const page = Math.max(1, filters.page ?? 1);
  const limit = Math.min(100, Math.max(1, filters.limit ?? 25));
  const offset = (page - 1) * limit;
  const sortCol = ALLOWED_SORT[filters.sort_by ?? ''] ?? 'i.created_at';
  const sortDir = filters.sort_dir === 'asc' ? sql`ASC` : sql`DESC`;
  const search = filters.search ? `%${filters.search}%` : null;

  const [countRow] = await sql`
    SELECT COUNT(*) AS total
    FROM admin_invoices i
    INNER JOIN companies c ON c.id = i.company_id
    WHERE (${filters.company_id ?? null}::uuid IS NULL
           OR i.company_id = ${filters.company_id ?? null}::uuid)
      AND (${filters.status ?? null}::text IS NULL
           OR i.status = ${filters.status ?? null})
      AND (${filters.from_date ?? null}::date IS NULL
           OR i.created_at::date >= ${filters.from_date ?? null}::date)
      AND (${filters.to_date ?? null}::date IS NULL
           OR i.created_at::date <= ${filters.to_date ?? null}::date)
      AND (${search}::text IS NULL
           OR c.name ILIKE ${search}
           OR i.invoice_number ILIKE ${search})
  `;

  const rows = await sql`
    SELECT
      i.id, i.company_id, c.name AS company_name,
      i.invoice_number, i.status,
      i.subtotal_cents, i.tax_cents, i.total_cents, i.currency,
      i.due_date, i.paid_at, i.payment_method,
      i.created_at
    FROM admin_invoices i
    INNER JOIN companies c ON c.id = i.company_id
    WHERE (${filters.company_id ?? null}::uuid IS NULL
           OR i.company_id = ${filters.company_id ?? null}::uuid)
      AND (${filters.status ?? null}::text IS NULL
           OR i.status = ${filters.status ?? null})
      AND (${filters.from_date ?? null}::date IS NULL
           OR i.created_at::date >= ${filters.from_date ?? null}::date)
      AND (${filters.to_date ?? null}::date IS NULL
           OR i.created_at::date <= ${filters.to_date ?? null}::date)
      AND (${search}::text IS NULL
           OR c.name ILIKE ${search}
           OR i.invoice_number ILIKE ${search})
    ORDER BY ${sql.unsafe(sortCol)} ${sortDir}
    LIMIT ${limit} OFFSET ${offset}
  `;

  const total = parseInt((countRow as Row).total as string, 10);
  log.info(`listInvoices: ${rows.length} rows (page ${page})`, {}, 'InvoiceService');

  return {
    items: (rows as Row[]).map((r: Row) => ({
      id: r.id as string,
      company_id: r.company_id as string,
      company_name: r.company_name as string,
      invoice_number: r.invoice_number as string,
      status: r.status as string,
      subtotal_cents: r.subtotal_cents as number,
      tax_cents: r.tax_cents as number,
      total_cents: r.total_cents as number,
      currency: r.currency as string,
      due_date: toIso(r.due_date),
      paid_at: toIso(r.paid_at),
      payment_method: r.payment_method as string | null,
      created_at: toIso(r.created_at) ?? '',
    })),
    total,
    page,
    limit,
    total_pages: Math.ceil(total / limit),
  };
}

export async function createInvoice(data: {
  company_id: string;
  subscription_id?: string;
  subtotal_cents: number;
  tax_cents: number;
  total_cents: number;
  due_date?: string;
  line_items?: unknown[];
  notes?: string;
}): Promise<string> {
  const {
    company_id,
    subscription_id = null,
    subtotal_cents,
    tax_cents,
    total_cents,
    due_date = null,
    line_items = [],
    notes = null,
  } = data;

  // Sequential invoice number: INV-YYYYMM-XXXX
  const yyyymm = new Date().toISOString().slice(0, 7).replace('-', '');
  const prefix = `INV-${yyyymm}-`;

  const seqRows = await sql`
    SELECT COUNT(*) AS count FROM admin_invoices
    WHERE invoice_number LIKE ${prefix + '%'}
  `;
  const seq = parseInt((seqRows[0] as Row).count as string, 10) + 1;
  const invoice_number = `${prefix}${String(seq).padStart(4, '0')}`;

  const rows = await sql`
    INSERT INTO admin_invoices (
      company_id, subscription_id, invoice_number, status,
      subtotal_cents, tax_cents, total_cents, currency,
      due_date, line_items, notes, created_at
    ) VALUES (
      ${company_id}::uuid,
      ${subscription_id}::uuid,
      ${invoice_number}, 'draft',
      ${subtotal_cents}, ${tax_cents}, ${total_cents}, 'ZAR',
      ${due_date}::date,
      ${JSON.stringify(line_items)}::jsonb,
      ${notes},
      NOW()
    )
    RETURNING id
  `;

  const id = (rows[0] as Row).id as string;
  log.info('createInvoice', { id, invoice_number, company_id }, 'InvoiceService');
  return id;
}

export async function markInvoicePaid(
  invoiceId: string,
  paymentMethod: string
): Promise<void> {
  await sql`
    UPDATE admin_invoices
    SET status         = 'paid',
        paid_at        = NOW(),
        payment_method = ${paymentMethod}
    WHERE id = ${invoiceId}
  `;
  log.info('markInvoicePaid', { invoiceId, paymentMethod }, 'InvoiceService');
}

export async function sendInvoice(invoiceId: string): Promise<void> {
  await sql`
    UPDATE admin_invoices
    SET status = 'sent'
    WHERE id   = ${invoiceId}
      AND status = 'draft'
  `;
  log.info('sendInvoice', { invoiceId }, 'InvoiceService');
}

/**
 * Debtors Manager Service
 * Sage-parity collections/aging dashboard for AR
 *
 * Queries customer_invoices and customer_payments (existing tables).
 * No new migration required.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

// ── Types ─────────────────────────────────────────────────────────────────────

export interface DebtorSummary {
  clientId: string;
  clientName: string;
  current: number;
  days30: number;
  days60: number;
  days90: number;
  days90Plus: number;
  totalOutstanding: number;
  invoiceCount: number;
}

export interface DebtorInvoice {
  id: string;
  invoiceNumber: string;
  invoiceDate: string;
  dueDate: string | null;
  totalAmount: number;
  amountPaid: number;
  outstanding: number;
  daysOverdue: number;
  status: string;
  agingBucket: 'current' | 'days30' | 'days60' | 'days90' | 'days90Plus';
}

export interface OverdueInvoice {
  id: string;
  invoiceNumber: string;
  clientId: string;
  clientName: string;
  invoiceDate: string;
  dueDate: string;
  totalAmount: number;
  amountPaid: number;
  outstanding: number;
  daysOverdue: number;
  status: string;
}

export interface CollectionStats {
  totalOutstanding: number;
  totalOverdue: number;
  avgDaysOutstanding: number;
  collectionRate: number;
  clientCount: number;
  overdueCount: number;
}

// ── Helpers ───────────────────────────────────────────────────────────────────

function classifyBucket(daysOverdue: number): DebtorInvoice['agingBucket'] {
  if (daysOverdue <= 0) return 'current';
  if (daysOverdue <= 30) return 'days30';
  if (daysOverdue <= 60) return 'days60';
  if (daysOverdue <= 90) return 'days90';
  return 'days90Plus';
}

// ── Debtors Summary ───────────────────────────────────────────────────────────

/**
 * Aggregate outstanding invoices by customer with aging buckets.
 * Buckets: current (not yet due), 1-30, 31-60, 61-90, 90+ days overdue.
 */
export async function getDebtorsSummary(companyId: string): Promise<DebtorSummary[]> {
  try {
    const rows = (await sql`
      SELECT
        ci.client_id,
        c.name AS client_name,
        COUNT(ci.id)::int AS invoice_count,
        SUM(
          CASE WHEN ci.due_date IS NULL OR ci.due_date >= CURRENT_DATE
               THEN (ci.total_amount - ci.amount_paid) ELSE 0 END
        ) AS current,
        SUM(
          CASE WHEN ci.due_date IS NOT NULL
                AND ci.due_date < CURRENT_DATE
                AND (CURRENT_DATE - ci.due_date) <= 30
               THEN (ci.total_amount - ci.amount_paid) ELSE 0 END
        ) AS days30,
        SUM(
          CASE WHEN ci.due_date IS NOT NULL
                AND (CURRENT_DATE - ci.due_date) BETWEEN 31 AND 60
               THEN (ci.total_amount - ci.amount_paid) ELSE 0 END
        ) AS days60,
        SUM(
          CASE WHEN ci.due_date IS NOT NULL
                AND (CURRENT_DATE - ci.due_date) BETWEEN 61 AND 90
               THEN (ci.total_amount - ci.amount_paid) ELSE 0 END
        ) AS days90,
        SUM(
          CASE WHEN ci.due_date IS NOT NULL
                AND (CURRENT_DATE - ci.due_date) > 90
               THEN (ci.total_amount - ci.amount_paid) ELSE 0 END
        ) AS days90_plus,
        SUM(ci.total_amount - ci.amount_paid) AS total_outstanding
      FROM customer_invoices ci
      JOIN customers c ON c.id = ci.client_id
      WHERE ci.company_id = ${companyId}
        AND ci.status IN ('approved', 'sent', 'partially_paid', 'overdue')
        AND (ci.total_amount - ci.amount_paid) > 0
      GROUP BY ci.client_id, c.name
      ORDER BY total_outstanding DESC
    `) as Row[];

    return rows.map((r: Row) => ({
      clientId: String(r.client_id),
      clientName: String(r.client_name),
      current: Number(r.current),
      days30: Number(r.days30),
      days60: Number(r.days60),
      days90: Number(r.days90),
      days90Plus: Number(r.days90_plus),
      totalOutstanding: Number(r.total_outstanding),
      invoiceCount: Number(r.invoice_count),
    }));
  } catch (err) {
    log.error('getDebtorsSummary failed', { error: err }, 'accounting');
    throw err;
  }
}

// ── Debtor Detail ─────────────────────────────────────────────────────────────

/**
 * List outstanding invoices for a specific customer with age and amounts.
 */
export async function getDebtorDetail(companyId: string, clientId: string): Promise<DebtorInvoice[]> {
  try {
    const rows = (await sql`
      SELECT
        ci.id,
        ci.invoice_number,
        ci.invoice_date,
        ci.due_date,
        ci.total_amount,
        ci.amount_paid,
        (ci.total_amount - ci.amount_paid) AS outstanding,
        ci.status,
        CASE
          WHEN ci.due_date IS NULL THEN 0
          ELSE GREATEST(0, (CURRENT_DATE - ci.due_date)::int)
        END AS days_overdue
      FROM customer_invoices ci
      WHERE ci.client_id = ${clientId}::UUID
        AND ci.status IN ('approved', 'sent', 'partially_paid', 'overdue')
        AND (ci.total_amount - ci.amount_paid) > 0
      ORDER BY ci.due_date ASC NULLS LAST, ci.invoice_date ASC
    `) as Row[];

    return rows.map((r: Row) => {
      const daysOverdue = Number(r.days_overdue);
      return {
        id: String(r.id),
        invoiceNumber: String(r.invoice_number),
        invoiceDate: String(r.invoice_date),
        dueDate: r.due_date ? String(r.due_date) : null,
        totalAmount: Number(r.total_amount),
        amountPaid: Number(r.amount_paid),
        outstanding: Number(r.outstanding),
        daysOverdue,
        status: String(r.status),
        agingBucket: classifyBucket(daysOverdue),
      };
    });
  } catch (err) {
    log.error('getDebtorDetail failed', { clientId, error: err }, 'accounting');
    throw err;
  }
}

// ── Overdue Invoices ──────────────────────────────────────────────────────────

/**
 * List all overdue invoices sorted by age descending.
 * Optionally filter to invoices overdue by at least daysOverdue days.
 */
export async function getOverdueInvoices(companyId: string, daysOverdue?: number): Promise<OverdueInvoice[]> {
  const minDays = daysOverdue ?? 1;

  try {
    const rows = (await sql`
      SELECT
        ci.id,
        ci.invoice_number,
        ci.client_id,
        c.name AS client_name,
        ci.invoice_date,
        ci.due_date,
        ci.total_amount,
        ci.amount_paid,
        (ci.total_amount - ci.amount_paid) AS outstanding,
        (CURRENT_DATE - ci.due_date)::int AS days_overdue,
        ci.status
      FROM customer_invoices ci
      JOIN customers c ON c.id = ci.client_id
      WHERE ci.due_date IS NOT NULL
        AND ci.due_date < CURRENT_DATE
        AND (CURRENT_DATE - ci.due_date) >= ${minDays}
        AND ci.status IN ('approved', 'sent', 'partially_paid', 'overdue')
        AND (ci.total_amount - ci.amount_paid) > 0
      ORDER BY days_overdue DESC, ci.total_amount DESC
    `) as Row[];

    return rows.map((r: Row) => ({
      id: String(r.id),
      invoiceNumber: String(r.invoice_number),
      clientId: String(r.client_id),
      clientName: String(r.client_name),
      invoiceDate: String(r.invoice_date),
      dueDate: String(r.due_date),
      totalAmount: Number(r.total_amount),
      amountPaid: Number(r.amount_paid),
      outstanding: Number(r.outstanding),
      daysOverdue: Number(r.days_overdue),
      status: String(r.status),
    }));
  } catch (err) {
    log.error('getOverdueInvoices failed', { daysOverdue, error: err }, 'accounting');
    throw err;
  }
}

// ── Collection Stats ──────────────────────────────────────────────────────────

/**
 * Aggregate collection metrics: total outstanding, total overdue,
 * average days outstanding, and collection rate.
 */
export async function getCollectionStats(companyId: string): Promise<CollectionStats> {
  try {
    const rows = (await sql`
      SELECT
        SUM(ci.total_amount - ci.amount_paid)                            AS total_outstanding,
        SUM(CASE WHEN ci.due_date < CURRENT_DATE
                 THEN (ci.total_amount - ci.amount_paid) ELSE 0 END)     AS total_overdue,
        COALESCE(AVG(
          CASE WHEN ci.due_date IS NOT NULL AND ci.due_date < CURRENT_DATE
               THEN (CURRENT_DATE - ci.due_date)::numeric END
        ), 0)                                                             AS avg_days_outstanding,
        COUNT(DISTINCT ci.client_id)::int                                AS client_count,
        COUNT(CASE WHEN ci.due_date < CURRENT_DATE THEN 1 END)::int      AS overdue_count
      FROM customer_invoices ci
      WHERE ci.status IN ('approved', 'sent', 'partially_paid', 'overdue')
        AND (ci.total_amount - ci.amount_paid) > 0
    `) as Row[];

    const rateRows = (await sql`
      SELECT
        SUM(ci.total_amount)  AS invoiced,
        SUM(ci.amount_paid)   AS collected
      FROM customer_invoices ci
      WHERE ci.status NOT IN ('draft', 'cancelled')
    `) as Row[];

    const r = rows[0] ?? {};
    const rate = rateRows[0] ?? {};
    const invoiced = Number(rate.invoiced ?? 0);
    const collected = Number(rate.collected ?? 0);

    return {
      totalOutstanding: Number(r.total_outstanding ?? 0),
      totalOverdue: Number(r.total_overdue ?? 0),
      avgDaysOutstanding: Math.round(Number(r.avg_days_outstanding ?? 0)),
      collectionRate: invoiced > 0 ? Math.round((collected / invoiced) * 100 * 10) / 10 : 0,
      clientCount: Number(r.client_count ?? 0),
      overdueCount: Number(r.overdue_count ?? 0),
    };
  } catch (err) {
    log.error('getCollectionStats failed', { error: err }, 'accounting');
    throw err;
  }
}

