/**
 * Suppliers List API
 * GET  /api/accounting/suppliers-list    - List suppliers (optional ?q= search)
 * POST /api/accounting/suppliers-list    - Create a new supplier
 *
 * Named suppliers-list.ts to avoid conflict with any existing suppliers route.
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { sql } from '@/lib/neon';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import { cacheThrough, cache } from '@/lib/cache';
import { CACHE_KEYS, CACHE_TTL } from '@/lib/cache-keys';
import { withErrorHandler } from '@/lib/api-error-handler';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = Record<string, any>;

async function handler(req: NextApiRequest, res: NextApiResponse) {
  const { companyId } = req as CompanyApiRequest;
  // ─── GET: List suppliers ────────────────────────────────────────────────────
  if (req.method === 'GET') {
    try {
      const { q } = req.query;
      const searchTerm = typeof q === 'string' && q.trim() ? `%${q.trim()}%` : null;

      let rows: Row[];

      if (searchTerm) {
        // Search queries are not cached — results change with every keystroke
        rows = (await sql`
          SELECT
            id, name, company_name, email, phone,
            contact_person, is_active,
            vat_number, payment_terms,
            created_at
          FROM suppliers
          WHERE company_id = ${companyId}
            AND deleted_at IS NULL
            AND (name ILIKE ${searchTerm}
            OR email ILIKE ${searchTerm}
            OR company_name ILIKE ${searchTerm}
            OR contact_person ILIKE ${searchTerm})
          ORDER BY name ASC
          LIMIT 200
        `) as Row[];
      } else {
        rows = await cacheThrough(
          CACHE_KEYS.suppliers(companyId),
          async () => (await sql`
            SELECT
              id, name, company_name, email, phone,
              contact_person, is_active,
              vat_number, payment_terms,
              created_at
            FROM suppliers
            WHERE company_id = ${companyId}
              AND deleted_at IS NULL
            ORDER BY name ASC
            LIMIT 200
          `) as Row[],
          CACHE_TTL.REFERENCE_DATA,
        );
      }

      return apiResponse.success(res, rows);
    } catch (err: unknown) {
      const message = err instanceof Error ? err.message : String(err);
      log.error('suppliers GET failed', { error: message, module: 'accounting' });
      return apiResponse.internalError(res, err, `Failed to fetch suppliers: ${message}`);
    }
  }

  // ─── POST: Create supplier ──────────────────────────────────────────────────
  if (req.method === 'POST') {
    try {
      const {
        name,
        company_name,
        email,
        phone,
        vat_number,
        registration_number,
        address,
        contact_person,
        payment_terms,
        bank_name,
        bank_account_number,
        bank_branch_code,
        bank_account_type,
        is_active,
        notes,
        category,
      } = req.body as {
        name?: string;
        company_name?: string;
        email?: string;
        phone?: string;
        vat_number?: string;
        registration_number?: string;
        address?: string;
        contact_person?: string;
        payment_terms?: number;
        bank_name?: string | null;
        bank_account_number?: string | null;
        bank_branch_code?: string | null;
        bank_account_type?: string | null;
        is_active?: boolean;
        notes?: string;
        category?: string;
      };

      if (!name?.trim()) {
        return apiResponse.badRequest(res, 'Supplier name is required');
      }

      const rows = (await sql`
        INSERT INTO suppliers (
          company_id, name, company_name, email, phone,
          vat_number, registration_number, address, contact_person,
          payment_terms,
          bank_name, bank_account_number, bank_branch_code, bank_account_type,
          is_active, notes, category
        ) VALUES (
          ${companyId},
          ${name.trim()},
          ${company_name?.trim() || null},
          ${email?.trim() || null},
          ${phone?.trim() || null},
          ${vat_number?.trim() || null},
          ${registration_number?.trim() || null},
          ${address?.trim() || null},
          ${contact_person?.trim() || null},
          ${payment_terms ?? 30},
          ${bank_name ?? null},
          ${bank_account_number ?? null},
          ${bank_branch_code ?? null},
          ${bank_account_type ?? null},
          ${is_active ?? true},
          ${notes?.trim() || null},
          ${category?.trim() || null}
        )
        RETURNING
          id, name, company_name, email, phone,
          vat_number, registration_number, address, contact_person,
          payment_terms,
          bank_name, bank_account_number, bank_branch_code, bank_account_type,
          is_active, notes, category,
          created_at
      `) as Row[];

      cache.invalidate(CACHE_KEYS.suppliers(companyId));
      log.info('Supplier created', { id: rows[0]?.id, name: rows[0]?.name, module: 'accounting' });
      return apiResponse.success(res, rows[0]);
    } catch (err: unknown) {
      const message = err instanceof Error ? err.message : String(err);
      log.error('suppliers POST failed', { error: message, module: 'accounting' });
      return apiResponse.internalError(res, err, 'Failed to create supplier');
    }
  }

  return apiResponse.methodNotAllowed(res, req.method ?? 'UNKNOWN', ['GET', 'POST']);
});

/**
 * Item Valuation Report
 * Sage Parity: Items > Reports > Item Valuation
 */

import { useState, useEffect, useCallback } from 'react';
import { AppLayout } from '@/components/layout/AppLayout';
import { DollarSign, Loader2, Download } from 'lucide-react';
import { apiFetch } from '@/lib/apiFetch';

const fmt = (n: number) => new Intl.NumberFormat('en-ZA', { style: 'currency', currency: 'ZAR' }).format(n);

interface Row { id: string; itemCode: string; name: string; category: string; uom: string; qtyOnHand: number; costPrice: number; stockValue: number; }

export default function ItemValuationReport() {
  const [rows, setRows] = useState<Row[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  const load = useCallback(async () => {
    setLoading(true);
    setError('');
    try {
      const res = await apiFetch('/api/accounting/reports/item-valuation', { credentials: 'include' });
      const json = await res.json();
      setRows(json.data || []);
    } catch (err: unknown) {
      setError(err instanceof Error ? err.message : 'Failed to load data');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => { load(); }, [load]);

  const totalValue = rows.reduce((s, r) => s + r.stockValue, 0);

  // Group by category for summary
  const byCategory = rows.reduce<Record<string, number>>((acc, r) => {
    acc[r.category] = (acc[r.category] || 0) + r.stockValue;
    return acc;
  }, {});

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)] px-6 py-4">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <div className="p-2 rounded-lg bg-amber-500/10"><DollarSign className="h-6 w-6 text-amber-500" /></div>
              <div>
                <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">Item Valuation</h1>
                <p className="text-sm text-[var(--ff-text-secondary)]">Current stock value by item</p>
              </div>
            </div>
            <div className="flex items-center gap-4">
              <div className="text-right">
                <p className="text-xs text-[var(--ff-text-tertiary)]">Total Stock Value</p>
                <p className="text-xl font-bold text-amber-400 font-mono">{fmt(totalValue)}</p>
              </div>
              <button onClick={() => window.open('/api/accounting/reports/item-valuation?format=csv', '_blank')}
                className="flex items-center gap-1.5 px-3 py-1.5 text-sm bg-blue-600 hover:bg-blue-500 text-white rounded-lg">
                <Download className="h-4 w-4" /> CSV
              </button>
            </div>
          </div>
        </div>
        <div className="p-6 space-y-4">
          {/* Category summary */}
          {!loading && Object.keys(byCategory).length > 1 && (
            <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
              {Object.entries(byCategory).sort((a, b) => b[1] - a[1]).map(([cat, val]) => (
                <div key={cat} className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] p-3">
                  <p className="text-xs text-[var(--ff-text-tertiary)] truncate">{cat}</p>
                  <p className="text-sm font-bold text-[var(--ff-text-primary)] font-mono">{fmt(val)}</p>
                </div>
              ))}
            </div>
          )}

          <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] overflow-hidden">
            {loading ? (
              <div className="p-8 text-center"><Loader2 className="h-6 w-6 animate-spin text-[var(--ff-text-tertiary)] mx-auto" /></div>
            ) : rows.length === 0 ? (
              <div className="p-8 text-center text-[var(--ff-text-tertiary)]">No items with stock value</div>
            ) : (
              <table className="w-full text-sm">
                <thead><tr className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-tertiary)]">
                  <th className="px-4 py-3 text-left text-xs font-medium text-[var(--ff-text-secondary)] uppercase">Code</th>
                  <th className="px-4 py-3 text-left text-xs font-medium text-[var(--ff-text-secondary)] uppercase">Item</th>
                  <th className="px-4 py-3 text-left text-xs font-medium text-[var(--ff-text-secondary)] uppercase">Category</th>
                  <th className="px-4 py-3 text-left text-xs font-medium text-[var(--ff-text-secondary)] uppercase">UOM</th>
                  <th className="px-4 py-3 text-right text-xs font-medium text-[var(--ff-text-secondary)] uppercase">Qty</th>
                  <th className="px-4 py-3 text-right text-xs font-medium text-[var(--ff-text-secondary)] uppercase">Unit Cost</th>
                  <th className="px-4 py-3 text-right text-xs font-medium text-[var(--ff-text-secondary)] uppercase">Value</th>
                </tr></thead>
                <tbody className="divide-y divide-[var(--ff-border-light)]">
                  {rows.map(r => (
                    <tr key={r.id} className="hover:bg-[var(--ff-bg-tertiary)]">
                      <td className="px-4 py-3 font-mono text-xs text-[var(--ff-text-tertiary)]">{r.itemCode}</td>
                      <td className="px-4 py-3 text-[var(--ff-text-primary)]">{r.name}</td>
                      <td className="px-4 py-3 text-[var(--ff-text-secondary)]">{r.category}</td>
                      <td className="px-4 py-3 text-[var(--ff-text-tertiary)]">{r.uom}</td>
                      <td className="px-4 py-3 text-right text-[var(--ff-text-primary)]">{r.qtyOnHand}</td>
                      <td className="px-4 py-3 text-right font-mono text-[var(--ff-text-secondary)]">{fmt(r.costPrice)}</td>
                      <td className="px-4 py-3 text-right font-mono text-amber-400 font-medium">{fmt(r.stockValue)}</td>
                    </tr>
                  ))}
                </tbody>
                <tfoot><tr className="border-t-2 border-[var(--ff-border-medium)] bg-[var(--ff-bg-tertiary)] font-bold">
                  <td className="px-4 py-3" colSpan={6}>TOTAL STOCK VALUE</td>
                  <td className="px-4 py-3 text-right font-mono text-amber-400">{fmt(totalValue)}</td>
                </tr></tfoot>
              </table>
            )}
          </div>
        </div>
      </div>
    </AppLayout>
  );
}

/**
 * Item Listing Report API
 * GET: Master list of all stock items with details
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { sql } from '@/lib/neon';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';

export default withCompany(async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') return apiResponse.methodNotAllowed(res, req.method!, ['GET']);

  try {
    const category = req.query.category as string | undefined;
    const search = req.query.search as string | undefined;
    const format = req.query.format as string;

    let rows;
    if (category && search) {
      const like = `%${search}%`;
      rows = await sql`
        SELECT id, item_code, name, description, category, uom,
          list_price, standard_cost, qty_available, is_active
        FROM stock_items
        WHERE category = ${category} AND (name ILIKE ${like} OR item_code ILIKE ${like})
        ORDER BY name
      `;
    } else if (category) {
      rows = await sql`
        SELECT id, item_code, name, description, category, uom,
          list_price, standard_cost, qty_available, is_active
        FROM stock_items WHERE category = ${category}
        ORDER BY name
      `;
    } else if (search) {
      const like = `%${search}%`;
      rows = await sql`
        SELECT id, item_code, name, description, category, uom,
          list_price, standard_cost, qty_available, is_active
        FROM stock_items WHERE name ILIKE ${like} OR item_code ILIKE ${like}
        ORDER BY name
      `;
    } else {
      rows = await sql`
        SELECT id, item_code, name, description, category, uom,
          list_price, standard_cost, qty_available, is_active
        FROM stock_items ORDER BY name
      `;
    }

    const data = rows.map(r => ({
      id: r.id,
      itemCode: r.item_code || '',
      name: r.name,
      description: r.description || '',
      category: r.category || 'uncategorized',
      uom: r.uom || '',
      sellingPrice: Number(r.list_price || 0),
      costPrice: Number(r.standard_cost || 0),
      qtyOnHand: Number(r.qty_available || 0),
      isActive: r.is_active,
    }));

    if (format === 'csv') {
      const header = 'Item Code,Name,Description,Category,UOM,Selling Price,Cost Price,Qty On Hand,Active';
      const csvRows = data.map(r =>
        `"${r.itemCode}","${r.name}","${r.description}","${r.category}","${r.uom}",${r.sellingPrice.toFixed(2)},${r.costPrice.toFixed(2)},${r.qtyOnHand},${r.isActive}`
      );
      res.setHeader('Content-Type', 'text/csv');
      res.setHeader('Content-Disposition', 'attachment; filename="item-listing.csv"');
      return res.send([header, ...csvRows].join('\n'));
    }

    return apiResponse.success(res, data);
  } catch (err: unknown) {
    const message = err instanceof Error ? err.message : String(err);
    log.error('Item listing report error', { error: message });
    return apiResponse.badRequest(res, 'Failed to generate item listing');
  }
});

/**
 * Item Listing Report API
 * GET: Master list of all stock items with details
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { sql } from '@/lib/neon';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import { withErrorHandler } from '@/lib/api-error-handler';

export default withCompany(async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') return apiResponse.methodNotAllowed(res, req.method!, ['GET']);

  try {
    const category = req.query.category as string | undefined;
    const search = req.query.search as string | undefined;
    const format = req.query.format as string;

    let rows;
    if (category && search) {
      const like = `%${search}%`;
      rows = await sql`
        SELECT id, item_code, name, description, category, uom,
          list_price, standard_cost, qty_available, is_active
        FROM stock_items
        WHERE category = ${category} AND (name ILIKE ${like} OR item_code ILIKE ${like})
        ORDER BY name
      `;
    } else if (category) {
      rows = await sql`
        SELECT id, item_code, name, description, category, uom,
          list_price, standard_cost, qty_available, is_active
        FROM stock_items WHERE category = ${category}
        ORDER BY name
      `;
    } else if (search) {
      const like = `%${search}%`;
      rows = await sql`
        SELECT id, item_code, name, description, category, uom,
          list_price, standard_cost, qty_available, is_active
        FROM stock_items WHERE name ILIKE ${like} OR item_code ILIKE ${like}
        ORDER BY name
      `;
    } else {
      rows = await sql`
        SELECT id, item_code, name, description, category, uom,
          list_price, standard_cost, qty_available, is_active
        FROM stock_items ORDER BY name
      `;
    }

    const data = rows.map(r => ({
      id: r.id,
      itemCode: r.item_code || '',
      name: r.name,
      description: r.description || '',
      category: r.category || 'uncategorized',
      uom: r.uom || '',
      sellingPrice: Number(r.list_price || 0),
      costPrice: Number(r.standard_cost || 0),
      qtyOnHand: Number(r.qty_available || 0),
      isActive: r.is_active,
    }));

    if (format === 'csv') {
      const header = 'Item Code,Name,Description,Category,UOM,Selling Price,Cost Price,Qty On Hand,Active';
      const csvRows = data.map(r =>
        `"${r.itemCode}","${r.name}","${r.description}","${r.category}","${r.uom}",${r.sellingPrice.toFixed(2)},${r.costPrice.toFixed(2)},${r.qtyOnHand},${r.isActive}`
      );
      res.setHeader('Content-Type', 'text/csv');
      res.setHeader('Content-Disposition', 'attachment; filename="item-listing.csv"');
      return res.send([header, ...csvRows].join('\n'));
    }

    return apiResponse.success(res, data);
  } catch (err: unknown) {
    const message = err instanceof Error ? err.message : String(err);
    log.error('Item listing report error', { error: message });
    return apiResponse.badRequest(res, 'Failed to generate item listing');
  }
});

