/**
 * Item Movement Report API
 * GET: Stock movement log (in/out/adjustments) per item with running balance
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { sql } from '@/lib/neon';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';

export default withCompany(async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') return apiResponse.methodNotAllowed(res, req.method!, ['GET']);

  try {
    const from = (req.query.from as string) || new Date(new Date().getFullYear(), new Date().getMonth(), 1).toISOString().split('T')[0];
    const to = (req.query.to as string) || new Date().toISOString().split('T')[0];
    const itemId = req.query.item_id as string | undefined;
    const format = req.query.format as string;

    // Get GRN (goods received) as stock IN
    let grnRows;
    if (itemId) {
      grnRows = await sql`
        SELECT g.delivery_date AS move_date, 'GRN' AS move_type,
          g.grn_number AS reference, si.name AS item_name, si.item_code,
          gi.quantity_received AS qty_in, 0 AS qty_out
        FROM grn_items gi
        JOIN goods_received_notes g ON g.id = gi.grn_id
        JOIN stock_items si ON si.id = gi.stock_item_id
        WHERE gi.stock_item_id = ${itemId}
          AND g.delivery_date >= ${from} AND g.delivery_date <= ${to}
      `;
    } else {
      grnRows = await sql`
        SELECT g.delivery_date AS move_date, 'GRN' AS move_type,
          g.grn_number AS reference, si.name AS item_name, si.item_code,
          gi.quantity_received AS qty_in, 0 AS qty_out
        FROM grn_items gi
        JOIN goods_received_notes g ON g.id = gi.grn_id
        JOIN stock_items si ON si.id = gi.stock_item_id
        WHERE g.delivery_date IS NOT NULL
          AND g.delivery_date >= ${from} AND g.delivery_date <= ${to}
      `;
    }

    // No sales rows — customer_invoice_items don't link to stock_items
    const salesRows: typeof grnRows = [];

    // Merge and sort by date
    const allMoves = [...grnRows, ...salesRows].sort((a, b) =>
      new Date(a.move_date).getTime() - new Date(b.move_date).getTime()
    );

    let runningBalance = 0;
    const data = allMoves.map(r => {
      const qtyIn = Number(r.qty_in || 0);
      const qtyOut = Number(r.qty_out || 0);
      runningBalance += qtyIn - qtyOut;
      return {
        date: r.move_date instanceof Date ? r.move_date.toISOString().split('T')[0] : String(r.move_date || '').split('T')[0],
        type: r.move_type,
        reference: r.reference || '',
        itemName: r.item_name,
        itemCode: r.item_code || '',
        qtyIn,
        qtyOut,
        balance: runningBalance,
      };
    });

    if (format === 'csv') {
      const header = 'Date,Type,Reference,Item Code,Item,Qty In,Qty Out,Balance';
      const csvRows = data.map(r =>
        `${r.date},"${r.type}","${r.reference}","${r.itemCode}","${r.itemName}",${r.qtyIn},${r.qtyOut},${r.balance}`
      );
      res.setHeader('Content-Type', 'text/csv');
      res.setHeader('Content-Disposition', `attachment; filename="item-movement-${from}-${to}.csv"`);
      return res.send([header, ...csvRows].join('\n'));
    }

    return apiResponse.success(res, data);
  } catch (err: unknown) {
    const message = err instanceof Error ? err.message : String(err);
    log.error('Item movement report error', { error: message });
    return apiResponse.badRequest(res, 'Failed to generate report');
  }
});

/**
 * Unallocated Supplier Payments Report
 * Sage Parity: Suppliers > Reports > Unallocated Payments
 */

import { useState, useEffect, useCallback } from 'react';
import { AppLayout } from '@/components/layout/AppLayout';
import Link from 'next/link';
import { AlertCircle, Loader2 } from 'lucide-react';
import { apiFetch } from '@/lib/apiFetch';

const fmt = (n: number) => new Intl.NumberFormat('en-ZA', { style: 'currency', currency: 'ZAR' }).format(n);

interface Payment { id: string; paymentNumber: string; supplierName: string; date: string; amount: number; allocatedAmount: number; }

export default function UnallocatedPaymentsReport() {
  const [items, setItems] = useState<Payment[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  const load = useCallback(async () => {
    setLoading(true);
    setError('');
    try {
      const res = await apiFetch('/api/accounting/supplier-payments?unallocated=true', { credentials: 'include' });
      const json = await res.json();
      const d = json.data;
      setItems(Array.isArray(d) ? d : d?.items || d?.payments || []);
    } catch (err: unknown) {
      setError(err instanceof Error ? err.message : 'Failed to load data');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => { load(); }, [load]);

  const totalUnalloc = items.reduce((s, p) => s + (p.amount - p.allocatedAmount), 0);

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)] px-6 py-4">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <div className="p-2 rounded-lg bg-amber-500/10"><AlertCircle className="h-6 w-6 text-amber-500" /></div>
              <div>
                <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">Unallocated Supplier Payments</h1>
                <p className="text-sm text-[var(--ff-text-secondary)]">Payments not fully matched to invoices</p>
              </div>
            </div>
            <Link href="/accounting/supplier-allocations"
              className="px-4 py-2 bg-orange-600 text-white rounded-lg hover:bg-orange-700 text-sm font-medium">
              Allocate Payments
            </Link>
          </div>
        </div>

        <div className="p-6 space-y-4">
          {!loading && items.length > 0 && (
            <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] p-4 inline-block">
              <p className="text-xs text-[var(--ff-text-tertiary)] uppercase">Total Unallocated</p>
              <p className="text-xl font-bold text-amber-400 font-mono">{fmt(totalUnalloc)}</p>
            </div>
          )}

          <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] overflow-hidden">
            {loading ? (
              <div className="p-8 text-center"><Loader2 className="h-6 w-6 animate-spin text-[var(--ff-text-tertiary)] mx-auto" /></div>
            ) : items.length === 0 ? (
              <div className="p-8 text-center text-[var(--ff-text-tertiary)]">All payments are fully allocated</div>
            ) : (
              <table className="w-full text-sm">
                <thead><tr className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-tertiary)]">
                  <th className="px-4 py-3 text-left text-xs font-medium text-[var(--ff-text-secondary)] uppercase">Payment No</th>
                  <th className="px-4 py-3 text-left text-xs font-medium text-[var(--ff-text-secondary)] uppercase">Supplier</th>
                  <th className="px-4 py-3 text-left text-xs font-medium text-[var(--ff-text-secondary)] uppercase">Date</th>
                  <th className="px-4 py-3 text-right text-xs font-medium text-[var(--ff-text-secondary)] uppercase">Total</th>
                  <th className="px-4 py-3 text-right text-xs font-medium text-[var(--ff-text-secondary)] uppercase">Allocated</th>
                  <th className="px-4 py-3 text-right text-xs font-medium text-[var(--ff-text-secondary)] uppercase">Unallocated</th>
                </tr></thead>
                <tbody className="divide-y divide-[var(--ff-border-light)]">
                  {items.map(p => (
                    <tr key={p.id} className="hover:bg-[var(--ff-bg-tertiary)]">
                      <td className="px-4 py-3 font-medium text-[var(--ff-text-primary)]">
                        <Link href={`/accounting/supplier-payments/${p.id}`} className="hover:text-orange-400">{p.paymentNumber}</Link>
                      </td>
                      <td className="px-4 py-3 text-[var(--ff-text-secondary)]">{p.supplierName}</td>
                      <td className="px-4 py-3 text-[var(--ff-text-secondary)]">{p.date?.split('T')[0]}</td>
                      <td className="px-4 py-3 text-right font-mono text-[var(--ff-text-primary)]">{fmt(p.amount)}</td>
                      <td className="px-4 py-3 text-right font-mono text-teal-400">{fmt(p.allocatedAmount)}</td>
                      <td className="px-4 py-3 text-right font-mono font-bold text-amber-400">{fmt(p.amount - p.allocatedAmount)}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            )}
          </div>
        </div>
      </div>
    </AppLayout>
  );
}

/**
 * DRC (Domestic Reverse Charge) VAT Service
 * Phase 5: Handle DRC VAT for supplier invoices
 *
 * DRC applies when a supplier provides certain services and the recipient
 * (FibreFlow) is responsible for accounting for VAT on those supplies.
 * Instead of the supplier charging VAT, the buyer self-accounts:
 *   DR Input VAT (1140)   — claimable
 *   CR Output VAT (2120)  — payable (net effect = zero)
 *
 * The invoice amount stays the same but both sides of VAT are recorded.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { createJournalEntry, postJournalEntry } from './journalEntryService';
import { getSystemAccountId } from './systemAccountResolver';
import type { JournalLineInput } from '../types/gl.types';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

const DEFAULT_VAT_RATE = 0.15; // SA VAT rate

/** Load VAT rate from app_settings, falling back to 15% */
async function getVatRate(): Promise<number> {
  try {
    const rows = (await sql`SELECT value FROM app_settings WHERE key = 'vat_rate'`) as Row[];
    if (rows[0]?.value) {
      const rate = Number(rows[0].value);
      if (rate > 0 && rate < 1) return rate;
    }
  } catch (error) { log.warn('Failed to fetch VAT rate from DB, using default', { error }, 'drcVatService'); }
  return DEFAULT_VAT_RATE;
}

export interface DRCResult {
  supplierInvoiceId: string;
  vatAmount: number;
  journalEntryId: string;
}

/**
 * Apply DRC VAT to a supplier invoice.
 * Creates a journal entry: DR Input VAT, CR Output VAT.
 */
export async function applyDRCVat(companyId: string, 
  supplierInvoiceId: string,
  userId: string
): Promise<DRCResult> {
  // Get invoice details
  const invoices = (await sql`
    SELECT si.id, si.invoice_number, si.total_amount, si.is_drc
    FROM supplier_invoices si
    WHERE si.id = ${supplierInvoiceId}::UUID AND si.company_id = ${companyId}
  `) as Row[];

  if (!invoices[0]) throw new Error('Supplier invoice not found');
  const inv = invoices[0];

  if (inv.is_drc) throw new Error('DRC VAT already applied to this invoice');

  const totalExclVat = Number(inv.total_amount);
  const vatRate = await getVatRate();
  const vatAmount = Math.round(totalExclVat * vatRate * 100) / 100;

  // Get VAT account IDs by subtype (code-independent)
  const inputVatId = await getSystemAccountId('vat_input');
  const outputVatId = await getSystemAccountId('vat_output');

  const description = `DRC VAT: ${inv.invoice_number} (R${vatAmount.toFixed(2)})`;

  const lines: JournalLineInput[] = [
    { glAccountId: String(inputVatId), debit: vatAmount, credit: 0, description },
    { glAccountId: String(outputVatId), debit: 0, credit: vatAmount, description },
  ];

  const je = await createJournalEntry('', {
    entryDate: new Date().toISOString().split('T')[0] ?? '',
    description,
    source: 'auto_vat_adjustment',
    sourceDocumentId: supplierInvoiceId,
    lines,
  }, userId);

  await postJournalEntry('', je.id, userId);

  // Mark invoice as DRC processed
  await sql`
    UPDATE supplier_invoices SET is_drc = true WHERE id = ${supplierInvoiceId}::UUID AND company_id = ${companyId}
  `;

  log.info('Applied DRC VAT', {
    supplierInvoiceId, vatAmount, journalEntryId: je.id,
  }, 'accounting');

  return { supplierInvoiceId, vatAmount, journalEntryId: je.id };
}

