  if (req.method !== 'GET') return apiResponse.methodNotAllowed(res, req.method!, ['GET']);

  try {
    const from = (req.query.from as string) || new Date(new Date().getFullYear(), new Date().getMonth(), 1).toISOString().split('T')[0];
    const to = (req.query.to as string) || new Date().toISOString().split('T')[0];
    const format = req.query.format as string;

    const rows = await sql`
      SELECT
        si.id, si.item_code, si.name, si.category,
        COUNT(DISTINCT poi.purchase_order_id)::int AS po_count,
        COALESCE(SUM(poi.quantity_ordered), 0)::numeric AS qty_ordered,
        COALESCE(SUM(poi.quantity_ordered * poi.unit_price), 0)::numeric AS total_cost
      FROM po_items poi
      JOIN purchase_orders po ON po.id = poi.purchase_order_id
      JOIN stock_items si ON si.id = poi.stock_item_id
      WHERE po.order_date >= ${from}
        AND po.order_date <= ${to}
      GROUP BY si.id, si.item_code, si.name, si.category
      ORDER BY total_cost DESC
    `;

    const data = rows.map(r => ({
      id: r.id,
      itemCode: r.item_code || '',
      name: r.name,
      category: r.category || '',
      poCount: Number(r.po_count),
      qtyOrdered: Number(r.qty_ordered),
      totalCost: Number(r.total_cost),
      avgCost: Number(r.qty_ordered) > 0 ? Number(r.total_cost) / Number(r.qty_ordered) : 0,
    }));

    if (format === 'csv') {
      const header = 'Item Code,Name,Category,PO Count,Qty Ordered,Total Cost,Avg Cost';
      const csvRows = data.map(r =>
        `"${r.itemCode}","${r.name}","${r.category}",${r.poCount},${r.qtyOrdered},${r.totalCost.toFixed(2)},${r.avgCost.toFixed(2)}`
      );
      res.setHeader('Content-Type', 'text/csv');
      res.setHeader('Content-Disposition', `attachment; filename="purchases-by-item-${from}-${to}.csv"`);
      return res.send([header, ...csvRows].join('\n'));
    }

    return apiResponse.success(res, data);
  } catch (err: unknown) {
    const message = err instanceof Error ? err.message : String(err);
    log.error('Purchases by item report error', { error: message });
    return apiResponse.badRequest(res, 'Failed to generate report');
  }
});

/**
 * Currency & Exchange Rate Service
 * Multi-currency foundation for accounting
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

export interface Currency {
  code: string;
  name: string;
  symbol: string;
  decimalPlaces: number;
  isActive: boolean;
}

export interface ExchangeRate {
  id: string;
  fromCurrency: string;
  toCurrency: string;
  rate: number;
  effectiveDate: string;
  source: string;
}

// ── Currencies ──────────────────────────────────────────────────────────────

export async function getCurrencies(companyId: string, activeOnly = true): Promise<Currency[]> {
  const rows = activeOnly
    ? ((await sql`SELECT * FROM currencies WHERE company_id = ${companyId} AND is_active = true ORDER BY code`) as Row[])
    : ((await sql`SELECT * FROM currencies WHERE company_id = ${companyId} ORDER BY code`) as Row[]);
  return rows.map(mapCurrency);
}

export async function createCurrency(companyId: string, input: {
  code: string; name: string; symbol: string; decimalPlaces?: number;
}): Promise<Currency> {
  const rows = (await sql`
    INSERT INTO currencies (company_id, code, name, symbol, decimal_places)
    VALUES (${companyId}, ${input.code.toUpperCase()}, ${input.name}, ${input.symbol}, ${input.decimalPlaces || 2})
    RETURNING *
  `) as Row[];
  log.info('Created currency', { code: input.code }, 'accounting');
  return mapCurrency(rows[0]!);
}

export async function toggleCurrency(companyId: string, code: string, isActive: boolean): Promise<void> {
  await sql`UPDATE currencies SET is_active = ${isActive} WHERE code = ${code} AND company_id = ${companyId}`;
}

// ── Exchange Rates ──────────────────────────────────────────────────────────

export async function getExchangeRates(companyId: string, filters?: {
  fromCurrency?: string; toCurrency?: string; limit?: number;
}): Promise<ExchangeRate[]> {
  const limit = filters?.limit || 100;

  if (filters?.fromCurrency && filters?.toCurrency) {
    const rows = (await sql`
      SELECT * FROM exchange_rates
      WHERE company_id = ${companyId}
        AND from_currency = ${filters.fromCurrency} AND to_currency = ${filters.toCurrency}
      ORDER BY effective_date DESC LIMIT ${limit}
    `) as Row[];
    return rows.map(mapRate);
  }
  if (filters?.fromCurrency) {
    const rows = (await sql`
      SELECT * FROM exchange_rates
      WHERE company_id = ${companyId} AND from_currency = ${filters.fromCurrency}
      ORDER BY effective_date DESC LIMIT ${limit}
    `) as Row[];
    return rows.map(mapRate);
  }
  const rows = (await sql`
    SELECT * FROM exchange_rates WHERE company_id = ${companyId} ORDER BY effective_date DESC LIMIT ${limit}
  `) as Row[];
  return rows.map(mapRate);
}

export async function getLatestRate(companyId: string, 
  fromCurrency: string, toCurrency: string, asOfDate?: string
): Promise<number | null> {
  const date = asOfDate || new Date().toISOString().split('T')[0]!;
  const rows = (await sql`
    SELECT rate FROM exchange_rates
    WHERE company_id = ${companyId}
      AND from_currency = ${fromCurrency} AND to_currency = ${toCurrency}
      AND effective_date <= ${date}::DATE
    ORDER BY effective_date DESC LIMIT 1
  `) as Row[];
  return rows[0] ? Number(rows[0].rate) : null;
}

export async function setExchangeRate(companyId: string, input: {
  fromCurrency: string; toCurrency: string; rate: number;
  effectiveDate: string; source?: string;
}, userId: string): Promise<ExchangeRate> {
  const rows = (await sql`
    INSERT INTO exchange_rates (from_currency, to_currency, rate, effective_date, source, created_by)
    VALUES (${input.fromCurrency}, ${input.toCurrency}, ${input.rate},
            ${input.effectiveDate}::DATE, ${input.source || 'manual'}, ${userId}::UUID)
    ON CONFLICT (from_currency, to_currency, effective_date)
    DO UPDATE SET rate = EXCLUDED.rate, source = EXCLUDED.source, created_by = EXCLUDED.created_by
    RETURNING *
  `) as Row[];
  log.info('Set exchange rate', {
    pair: `${input.fromCurrency}/${input.toCurrency}`,
    rate: input.rate, date: input.effectiveDate,
  }, 'accounting');
  return mapRate(rows[0]!);
}

export async function convertAmount(companyId: string, 
  amount: number, fromCurrency: string, toCurrency: string, asOfDate?: string
): Promise<{ converted: number; rate: number } | null> {
  if (fromCurrency === toCurrency) return { converted: amount, rate: 1 };
  const rate = await getLatestRate(companyId, fromCurrency, toCurrency, asOfDate);
  if (rate === null) return null;
  return { converted: Math.round(amount * rate * 100) / 100, rate };
}

// ── Settings ────────────────────────────────────────────────────────────────

export async function getSetting(key: string): Promise<string | null> {
  const rows = (await sql`
    SELECT setting_value FROM accounting_settings WHERE setting_key = ${key}
  `) as Row[];
  return rows[0] ? String(rows[0].setting_value) : null;
}

export async function setSetting(key: string, value: string, userId: string): Promise<void> {
  await sql`
    INSERT INTO accounting_settings (setting_key, setting_value, updated_by)
    VALUES (${key}, ${value}, ${userId}::UUID)
    ON CONFLICT (setting_key) DO UPDATE SET setting_value = EXCLUDED.setting_value,
      updated_by = EXCLUDED.updated_by, updated_at = NOW()
  `;
}

// ── Helpers ─────────────────────────────────────────────────────────────────

function mapCurrency(row: Row): Currency {
  return {
    code: String(row.code),
    name: String(row.name),
    symbol: String(row.symbol),
    decimalPlaces: Number(row.decimal_places),
    isActive: Boolean(row.is_active),
  };
}

function mapRate(row: Row): ExchangeRate {
  return {
    id: String(row.id),
    fromCurrency: String(row.from_currency),
    toCurrency: String(row.to_currency),
    rate: Number(row.rate),
    effectiveDate: row.effective_date instanceof Date
      ? row.effective_date.toISOString().split('T')[0]!
      : String(row.effective_date).split('T')[0]!,
    source: String(row.source || 'manual'),
  };
}

/**
 * Supplier Payment Allocation
 * Sage Parity: Transactions > Allocate Payments
 */

import { useState, useEffect, useCallback } from 'react';
import { AppLayout } from '@/components/layout/AppLayout';
import { ArrowLeftRight, Loader2, AlertCircle, Check } from 'lucide-react';
import { apiFetch } from '@/lib/apiFetch';

const fmt = (n: number) => new Intl.NumberFormat('en-ZA', { style: 'currency', currency: 'ZAR' }).format(n);

interface Payment { id: string; paymentNumber: string; supplierName: string; supplierId: string; date: string; amount: number; allocatedAmount: number; }
interface Invoice { id: string; invoiceNumber: string; date: string; total: number; outstanding: number; }

export default function SupplierAllocationsPage() {
  const [payments, setPayments] = useState<Payment[]>([]);
  const [invoices, setInvoices] = useState<Invoice[]>([]);
  const [selected, setSelected] = useState<Payment | null>(null);
  const [allocs, setAllocs] = useState<Record<string, number>>({});
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [loadingInv, setLoadingInv] = useState(false);
  const [saving, setSaving] = useState(false);
  const [msg, setMsg] = useState('');

  const loadPayments = useCallback(async () => {
    setLoading(true);
    setError('');
    try {
      const res = await apiFetch('/api/accounting/supplier-payments?unallocated=true', { credentials: 'include' });
      const json = await res.json();
      const d = json.data;
      const raw: Payment[] = Array.isArray(d) ? d : d?.items || d?.payments || d?.invoices || [];
      setPayments(raw.map(p => ({ ...p, amount: Number(p.amount), allocatedAmount: Number(p.allocatedAmount) })));
    } catch (err: unknown) {
      setError(err instanceof Error ? err.message : 'Failed to load data');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => { loadPayments(); }, [loadPayments]);

  const selectPayment = async (p: Payment) => {
    setSelected(p); setAllocs({}); setMsg(''); setLoadingInv(true);
    const res = await apiFetch(`/api/accounting/supplier-invoices?supplier_id=${p.supplierId}&status=approved`, { credentials: 'include' });
    const json = await res.json();
    const rawInv: Invoice[] = (() => { const d = json.data; return Array.isArray(d) ? d : d?.items || d?.payments || d?.invoices || []; })();
    setInvoices(rawInv.map(i => ({ ...i, total: Number(i.total), outstanding: Number(i.outstanding) })));
    setLoadingInv(false);
  };

  const toggleAlloc = (inv: Invoice) => {
    setAllocs(prev => {
      const next = { ...prev };
      if (next[inv.id] !== undefined) { delete next[inv.id]; } else { next[inv.id] = inv.outstanding; }
      return next;
    });
  };

  const totalAlloc = Object.values(allocs).reduce((s, a) => s + a, 0);
  const unallocTotal = payments.reduce((s, p) => s + (p.amount - p.allocatedAmount), 0);

  const doAllocate = async () => {
    if (!selected || totalAlloc <= 0) return;
    setSaving(true);
    const allocations = Object.entries(allocs).filter(([, a]) => a > 0).map(([invoiceId, amount]) => ({ invoiceId, amount }));
    const res = await apiFetch('/api/accounting/supplier-allocations', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      credentials: 'include', body: JSON.stringify({ paymentId: selected.id, allocations }),
    });
    if (res.ok) { setMsg('Allocated successfully'); setSelected(null); setAllocs({}); await loadPayments(); }
    else { setMsg('Allocation failed'); }
    setSaving(false);
  };

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)] px-6 py-4">
          <div className="flex items-center gap-3">
            <div className="p-2 rounded-lg bg-orange-500/10"><ArrowLeftRight className="h-6 w-6 text-orange-500" /></div>
            <div>
              <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">Allocate Payments</h1>
              <p className="text-sm text-[var(--ff-text-secondary)]">Match supplier payments to outstanding invoices</p>
            </div>
          </div>
        </div>

        <div className="p-6 space-y-4">
          {!loading && payments.length > 0 && (
            <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] p-4">
              <p className="text-xs text-[var(--ff-text-tertiary)] uppercase">Total Unallocated</p>
              <p className="text-xl font-bold text-amber-400 font-mono">{fmt(unallocTotal)}</p>
              <p className="text-xs text-[var(--ff-text-tertiary)]">{payments.length} payment(s)</p>
            </div>
          )}
          {msg && <div className="flex items-center gap-2 p-3 rounded-lg bg-teal-500/10 text-teal-400 text-sm"><Check className="h-4 w-4" />{msg}</div>}

          <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
            {/* Unallocated Payments */}
            <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] overflow-hidden">
              <div className="px-4 py-3 border-b border-[var(--ff-border-light)] text-sm font-medium text-[var(--ff-text-secondary)]">Unallocated Payments</div>
              {loading ? (
                <div className="p-8 text-center"><Loader2 className="h-6 w-6 animate-spin text-[var(--ff-text-tertiary)] mx-auto" /></div>
              ) : payments.length === 0 ? (
                <div className="p-8 text-center text-[var(--ff-text-tertiary)]">All payments allocated</div>
              ) : (
                <div className="divide-y divide-[var(--ff-border-light)] max-h-[60vh] overflow-y-auto">
                  {payments.map(p => (
                    <button key={p.id} onClick={() => selectPayment(p)}
                      className={`w-full text-left px-4 py-3 hover:bg-[var(--ff-bg-tertiary)] transition-colors ${selected?.id === p.id ? 'bg-orange-500/10 border-l-2 border-orange-500' : ''}`}>
                      <div className="flex justify-between">
                        <span className="text-sm font-medium text-[var(--ff-text-primary)]">{p.paymentNumber}</span>
                        <span className="text-sm font-mono text-amber-400">{fmt(p.amount - p.allocatedAmount)}</span>
                      </div>
                      <div className="text-xs text-[var(--ff-text-tertiary)]">{p.supplierName} &middot; {p.date?.split('T')[0]}</div>
                    </button>
                  ))}
                </div>
              )}
            </div>

            {/* Outstanding Invoices */}
            <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] overflow-hidden">
              <div className="px-4 py-3 border-b border-[var(--ff-border-light)] text-sm font-medium text-[var(--ff-text-secondary)]">
                {selected ? `Invoices for ${selected.supplierName}` : 'Select a payment'}
              </div>
              {!selected ? (
                <div className="p-8 text-center text-[var(--ff-text-tertiary)]"><AlertCircle className="h-6 w-6 mx-auto mb-2" />Select a payment to allocate</div>
              ) : loadingInv ? (
                <div className="p-8 text-center"><Loader2 className="h-6 w-6 animate-spin text-[var(--ff-text-tertiary)] mx-auto" /></div>
              ) : invoices.length === 0 ? (
                <div className="p-8 text-center text-[var(--ff-text-tertiary)]">No outstanding invoices</div>
              ) : (
                <>
                  <div className="divide-y divide-[var(--ff-border-light)] max-h-[50vh] overflow-y-auto">
                    {invoices.map(inv => (
                      <label key={inv.id} className="flex items-center gap-3 px-4 py-3 hover:bg-[var(--ff-bg-tertiary)] cursor-pointer">
                        <input type="checkbox" checked={allocs[inv.id] !== undefined} onChange={() => toggleAlloc(inv)}
                          className="rounded border-[var(--ff-border-light)]" />
                        <div className="flex-1">
                          <div className="flex justify-between">
                            <span className="text-sm text-[var(--ff-text-primary)]">{inv.invoiceNumber}</span>
                            <span className="text-sm font-mono text-[var(--ff-text-primary)]">{fmt(inv.outstanding)}</span>
                          </div>
                          <p className="text-xs text-[var(--ff-text-tertiary)]">{inv.date?.split('T')[0]} &middot; Total: {fmt(inv.total)}</p>
                        </div>
                        {allocs[inv.id] !== undefined && (
                          <input type="number" value={allocs[inv.id]} step="0.01" min="0" max={inv.outstanding}
                            onChange={e => setAllocs(prev => ({ ...prev, [inv.id]: Number(e.target.value) }))}
                            onClick={e => e.stopPropagation()}
                            className="w-28 px-2 py-1 text-right bg-[var(--ff-bg-tertiary)] border border-[var(--ff-border-light)] rounded text-sm font-mono text-[var(--ff-text-primary)]" />
                        )}
                      </label>
                    ))}
                  </div>
                  {totalAlloc > 0 && (
                    <div className="px-4 py-3 border-t border-[var(--ff-border-light)] flex items-center justify-between">
                      <span className="text-sm text-[var(--ff-text-secondary)]">Allocating: <strong className="text-[var(--ff-text-primary)]">{fmt(totalAlloc)}</strong></span>
                      <button onClick={doAllocate} disabled={saving}
                        className="flex items-center gap-2 px-4 py-2 bg-orange-600 text-white rounded-lg hover:bg-orange-700 text-sm font-medium">
                        {saving ? <Loader2 className="h-4 w-4 animate-spin" /> : <Check className="h-4 w-4" />} Allocate
                      </button>
                    </div>
                  )}
                </>
              )}
            </div>
          </div>
        </div>
      </div>
    </AppLayout>
  );
}

