      const bankList = Array.isArray(bankJson.data || bankJson) ? (bankJson.data || bankJson) : [];
      setBankAccounts(bankList);
      if (bankList.length > 0) setSelectedBank(prev => prev || bankList[0].id);

      const coaList = Array.isArray(coaJson.data || coaJson) ? (coaJson.data || coaJson) : [];
      setGlAccounts(coaList
        .filter((a: SelectOption & { accountSubtype?: string }) => a.accountSubtype !== 'bank')
        .map((a: SelectOption & { accountCode?: string; accountName?: string; defaultVatCode?: string }) => ({
          id: a.id, code: a.accountCode || a.code, name: a.accountName || a.name,
          defaultVatCode: a.defaultVatCode,
        }))
      );

      const suppList = Array.isArray(suppJson.data) ? suppJson.data : [];
      setSuppliers(suppList.map((s: { id: number | string; name: string; code?: string }) => ({
        id: String(s.id), name: s.name, code: s.code,
      })));

      const clientList = Array.isArray(clientJson.data) ? clientJson.data : [];
      setCustomers(clientList.map((c: { id: string; name: string }) => ({
        id: c.id, name: c.name || '',
      })));

      const cc1List = Array.isArray(cc1Json.data?.items) ? cc1Json.data.items : [];
      setCc1Options(cc1List.map((c: { id: string; code: string; name: string }) => ({ id: c.id, code: c.code, name: c.name })));

      const cc2List = Array.isArray(cc2Json.data?.items) ? cc2Json.data.items : [];
      setCc2Options(cc2List.map((c: { id: string; code: string; name: string }) => ({ id: c.id, code: c.code, name: c.name })));

      const deptList = Array.isArray(deptJson.data || deptJson) ? (deptJson.data || deptJson) : [];
      setBuOptions(deptList.filter((d: { is_active?: boolean; isActive?: boolean }) => d.is_active !== false && d.isActive !== false)
        .map((d: { id: string; name: string; code?: string }) => ({ id: d.id, name: d.name, code: d.code })));
    }).catch(() => { /* reference data load failure — non-critical, UI handles empty lists */ });
  }, []);

  // Debounce search input — 500ms delay before firing server request
  useEffect(() => {
    if (debounceTimer.current) clearTimeout(debounceTimer.current);
    debounceTimer.current = setTimeout(() => {
      setDebouncedSearch(searchTerm);
      setPage(1);
    }, 500);
    return () => { if (debounceTimer.current) clearTimeout(debounceTimer.current); };
  }, [searchTerm]);

  // Load transactions — server-side filtering for search, dates, amount range, status
  const loadTransactions = useCallback(async () => {
    if (!selectedBank) return;
    setIsLoading(true);
    setError('');
    try {
      const status = tabToStatus(tab);
      const offset = (page - 1) * PAGE_SIZE;
      const params = new URLSearchParams({
        bank_account_id: selectedBank, status, limit: String(PAGE_SIZE), offset: String(offset),
      });
      if (fromDate) params.set('from_date', fromDate);
      if (toDate) params.set('to_date', toDate);
      if (fromAmount) params.set('from_amount', fromAmount);
      if (toAmount) params.set('to_amount', toAmount);
      if (debouncedSearch) params.set('search', debouncedSearch);
      const res = await apiFetch(`/api/accounting/bank-transactions?${params}`);
      const json = await res.json();
      const data = json.data || json;
      setTransactions(data.transactions || []);
      setTotal(data.total || 0);
    } catch {
      setError('Failed to load transactions');
    } finally {
      setIsLoading(false);
    }
  }, [selectedBank, tab, page, fromDate, toDate, fromAmount, toAmount, debouncedSearch]);

  useEffect(() => { loadTransactions(); }, [loadTransactions]);

  // Seed rowSelections from suggestion fields on newly-loaded transactions
  useEffect(() => {
    if (transactions.length === 0) return;
    const initialSelections: Record<string, RowSelection> = {};
    for (const tx of transactions) {
      // Skip only if user has already picked a specific entity — an empty selection (type set, no entity)
      // should be overridden by fresh DB suggestions (e.g. after Apply Rules runs)
      if (rowSelections[tx.id]?.entityId) continue;
      // VAT only applies to GL account allocations; supplier/customer VAT is handled on their own invoices
      const dimFields = { cc1Id: tx.cc1Id, cc2Id: tx.cc2Id, buId: tx.buId };
      if (tx.suggestedSupplierId) {
        initialSelections[tx.id] = {
          type: 'supplier' as AllocType,
          entityId: tx.suggestedSupplierId,
          label: tx.suggestedSupplierName || tx.suggestedCategory || '',
          vatCode: 'none', ...dimFields,
        };
      } else if (tx.suggestedClientId) {
        initialSelections[tx.id] = {
          type: 'customer' as AllocType,
          entityId: tx.suggestedClientId,
          label: tx.suggestedClientName || tx.suggestedCategory || '',
          vatCode: 'none', ...dimFields,
        };
      } else if (tx.suggestedGlAccountId) {
        initialSelections[tx.id] = {
          type: 'account' as AllocType,
          entityId: tx.suggestedGlAccountId,
          label: tx.suggestedGlAccountCode
            ? `${tx.suggestedGlAccountCode} ${tx.suggestedGlAccountName || ''}`
            : tx.suggestedGlAccountName || tx.suggestedCategory || '',
          vatCode: (tx.suggestedVatCode || 'none') as VatCode, ...dimFields,
        };
      }
    }
    if (Object.keys(initialSelections).length > 0) {
      // Merge: DB suggestions fill in empty slots; existing selections with an entityId win
      setRowSelections(prev => {
        const merged = { ...prev };
        for (const [id, sel] of Object.entries(initialSelections)) {
          if (!merged[id]?.entityId) merged[id] = sel;
        }
        return merged;
      });
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [transactions]);

  useEffect(() => {
    setPage(1);
    setSelectedIds(new Set());
    setRowSelections({});
  }, [selectedBank, tab]);

  // API helpers
  const callAction = async (body: Record<string, string>) => {
    const res = await apiFetch('/api/accounting/bank-transactions-action', {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, credentials: 'include',
      body: JSON.stringify(body),
    });
    const json = await res.json();
    if (!res.ok || json.success === false) {
      const msg = json.error?.message || json.message || (typeof json.error === 'string' ? json.error : 'Action failed');
      throw new Error(msg);
    }
    return json;
  };

  // Fire-and-forget: persist dropdown selection to DB so it survives page refresh
  const saveSelection = (txId: string, type: AllocType, entityId: string) => {
    apiFetch('/api/accounting/bank-transactions-action', {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, credentials: 'include',
      body: JSON.stringify({ action: 'save_selection', bankTransactionId: txId, selectionType: type, selectionEntityId: entityId || null }),
    }).catch(() => { /* fire-and-forget: selection persist failure is non-critical, selection still shown in UI */ });
  };

  // Fire-and-forget: persist CC1/CC2/BU dimension changes
  const saveDimensions = (txId: string, cc1Id: string, cc2Id: string, buId: string) => {
    apiFetch('/api/accounting/bank-transactions-action', {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, credentials: 'include',
      body: JSON.stringify({ action: 'save_dimensions', bankTransactionId: txId, cc1Id: cc1Id || null, cc2Id: cc2Id || null, buId: buId || null }),
    }).catch(() => { /* fire-and-forget: dimension persist failure is non-critical, dimensions still shown in UI */ });
  };

  const handleAccept = async (txId: string) => {
    const sel = rowSelections[txId];
    if (!sel?.entityId) { notify.error('Select an account/supplier/customer first'); return; }
    const tx = transactions.find(t => t.id === txId);
    try {
      const body: Record<string, string> = {
        action: 'allocate', bankTransactionId: txId, allocationType: sel.type,
        vatCode: sel.vatCode || 'none',
      };
      if (sel.type === 'account') body.contraAccountId = sel.entityId;
      else body.entityId = sel.entityId;
      if (sel.cc1Id) body.cc1Id = sel.cc1Id;
      if (sel.cc2Id) body.cc2Id = sel.cc2Id;
      if (sel.buId) body.buId = sel.buId;
      await callAction(body);
      notify.success('Transaction allocated');
      loadTransactions();
      // Learn from this allocation for smart categorization (fire-and-forget)
      if (sel.type === 'account' && sel.entityId) {
        apiFetch('/api/accounting/smart-categorize', {
          method: 'POST', headers: { 'Content-Type': 'application/json' }, credentials: 'include',
          body: JSON.stringify({ action: 'learn', txId, glAccountId: sel.entityId, category: sel.label, vatCode: sel.vatCode }),
        }).catch(() => { /* fire-and-forget: smart-categorize learn failure is non-critical */ });
      }
      // After allocation, check if there are other similar unprocessed transactions
      // to suggest creating a categorisation rule
      if (tx?.description && selectedBank) {
        const pattern = extractPattern(tx.description);
        if (pattern.trim().length >= 3) {
          try {
            const params = new URLSearchParams({ pattern, matchType: 'contains', bankAccountId: selectedBank });
            const res = await apiFetch(`/api/accounting/bank-rules-preview?${params}`);
            const json = await res.json();
            const matchCount = json.data?.matchCount ?? 0;
            if (matchCount > 0) setRulePrompt({ tx, matchCount });
          } catch { /* non-critical — ignore preview errors */ }
        }

/**
 * Inline entity creation modal — create GL Accounts, Suppliers, or Customers
 * directly from the bank transaction allocation dropdown (Sage-style).
 */

import { useState } from 'react';
import { Plus, X, Loader2 } from 'lucide-react';
import { notify } from '@/utils/toast';
import { apiFetch } from '@/lib/apiFetch';
import type { AllocType } from './BankTxTable';

interface Props {
  type: AllocType;
  onClose: () => void;
  onCreated: (entity: { id: string; code?: string; name: string }) => void;
}

const ACCOUNT_TYPES = [
  { value: 'expense', label: 'Expense', nb: 'debit' },
  { value: 'asset', label: 'Asset', nb: 'debit' },
  { value: 'liability', label: 'Liability', nb: 'credit' },
  { value: 'revenue', label: 'Revenue', nb: 'credit' },
  { value: 'equity', label: 'Equity', nb: 'credit' },
];

const INPUT = 'w-full px-3 py-2 rounded bg-[var(--ff-bg-primary)] border border-[var(--ff-border-light)] text-sm text-[var(--ff-text-primary)] focus:outline-none focus:border-teal-500';
const LABEL = 'text-xs text-[var(--ff-text-tertiary)] mb-1 block';

export function CreateEntityModal({ type, onClose, onCreated }: Props) {
  const [saving, setSaving] = useState(false);

  // Account fields
  const [acctCode, setAcctCode] = useState('');
  const [acctName, setAcctName] = useState('');
  const [acctType, setAcctType] = useState('expense');

  // Supplier fields
  const [supName, setSupName] = useState('');
  const [supEmail, setSupEmail] = useState('');
  const [supPhone, setSupPhone] = useState('');

  // Customer fields
  const [custName, setCustName] = useState('');
  const [custEmail, setCustEmail] = useState('');
  const [custPhone, setCustPhone] = useState('');

  const title = type === 'account' ? 'New GL Account'
    : type === 'supplier' ? 'New Supplier' : 'New Customer';

  const canSave = type === 'account'
    ? !!(acctCode.trim() && acctName.trim())
    : type === 'supplier'
      ? !!(supName.trim() && supEmail.trim())
      : !!custName.trim();

  const handleSave = async () => {
    setSaving(true);
    try {
      let entity: { id: string; code?: string; name: string };

      if (type === 'account') {
        const nb = ACCOUNT_TYPES.find(t => t.value === acctType)?.nb || 'debit';
        const res = await apiFetch('/api/accounting/chart-of-accounts', {
          method: 'POST', headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            accountCode: acctCode.trim(), accountName: acctName.trim(),
            accountType: acctType, normalBalance: nb,
          }),
        });
        const json = await res.json();
        if (!res.ok) throw new Error(json.message || json.error?.message || 'Failed to create account');
        const d = json.data;
        entity = { id: d.id, code: d.accountCode, name: d.accountName };
      } else if (type === 'supplier') {
        const res = await apiFetch('/api/suppliers', {
          method: 'POST', headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ data: {
            name: supName.trim(),
            email: supEmail.trim(),
            phone: supPhone.trim() || undefined,
          }}),
        });
        const json = await res.json();
        if (!res.ok) throw new Error(json.message || 'Failed to create supplier');
        const d = json.data;
        entity = { id: String(d.id), code: d.code, name: supName.trim() };
      } else {
        const res = await apiFetch('/api/clients', {
          method: 'POST', headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            company_name: custName.trim(),
            email: custEmail.trim() || undefined,
            phone: custPhone.trim() || undefined,
          }),
        });
        const json = await res.json();
        if (!res.ok) throw new Error(json.message || 'Failed to create customer');
        const d = json.data;
        entity = { id: d.id, name: custName.trim() };
      }

      notify.success(`${title.replace('New ', '')} created`);
      onCreated(entity);
    } catch (e) {
      notify.error(e instanceof Error ? e.message : 'Failed to create');
    } finally {
      setSaving(false);
    }
  };

  const nb = ACCOUNT_TYPES.find(t => t.value === acctType)?.nb;

  return (
    <div className="fixed inset-0 z-[60] flex items-center justify-center bg-black/60">
      <div className="bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)] rounded-xl shadow-2xl w-full max-w-md mx-4">
        {/* Header */}
        <div className="flex items-center justify-between px-5 py-3 border-b border-[var(--ff-border-light)]">
          <div className="flex items-center gap-2">
            <Plus className="h-4 w-4 text-teal-400" />
            <h2 className="text-sm font-semibold text-[var(--ff-text-primary)]">{title}</h2>
          </div>
          <button onClick={onClose} className="p-1 rounded hover:bg-[var(--ff-bg-primary)] text-[var(--ff-text-tertiary)]">
            <X className="h-4 w-4" />
          </button>
        </div>

        {/* Body */}
        <div className="px-5 py-4 space-y-3">
          {type === 'account' && (
            <>
              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className={LABEL}>Account Code *</label>
                  <input type="text" value={acctCode} onChange={e => setAcctCode(e.target.value)}
                    placeholder="e.g. 5250" className={`${INPUT} font-mono`} autoFocus />
                </div>
                <div>
                  <label className={LABEL}>Type *</label>
                  <select value={acctType} onChange={e => setAcctType(e.target.value)} className={INPUT}>
                    {ACCOUNT_TYPES.map(t => <option key={t.value} value={t.value}>{t.label}</option>)}
                  </select>
                </div>
              </div>
              <div>
                <label className={LABEL}>Account Name *</label>
                <input type="text" value={acctName} onChange={e => setAcctName(e.target.value)}
                  placeholder="e.g. Cleaning & Maintenance" className={INPUT} />
              </div>
              <div className="flex items-center gap-2 text-xs text-[var(--ff-text-tertiary)]">
                Normal balance:&nbsp;
                <span className={nb === 'debit' ? 'text-red-400' : 'text-teal-400'}>
                  {nb === 'debit' ? 'Debit' : 'Credit'}
                </span>
              </div>
            </>
          )}

          {type === 'supplier' && (
            <>
              <div>
                <label className={LABEL}>Supplier Name *</label>
                <input type="text" value={supName} onChange={e => setSupName(e.target.value)}
                  placeholder="e.g. ACME Trading" className={INPUT} autoFocus />
              </div>
              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className={LABEL}>Email *</label>
                  <input type="email" value={supEmail} onChange={e => setSupEmail(e.target.value)}
                    placeholder="info@supplier.co.za" className={INPUT} />
                </div>
                <div>
                  <label className={LABEL}>Phone</label>
                  <input type="tel" value={supPhone} onChange={e => setSupPhone(e.target.value)}
                    placeholder="012 345 6789" className={INPUT} />
                </div>
              </div>
            </>
          )}

          {type === 'customer' && (
            <>
              <div>
                <label className={LABEL}>Company Name *</label>
                <input type="text" value={custName} onChange={e => setCustName(e.target.value)}
                  placeholder="e.g. Fibertime" className={INPUT} autoFocus />
              </div>
              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className={LABEL}>Email</label>
                  <input type="email" value={custEmail} onChange={e => setCustEmail(e.target.value)}
                    placeholder="client@example.com" className={INPUT} />
                </div>
                <div>
                  <label className={LABEL}>Phone</label>
                  <input type="tel" value={custPhone} onChange={e => setCustPhone(e.target.value)}
                    placeholder="012 345 6789" className={INPUT} />
                </div>
              </div>
            </>
          )}
        </div>

        {/* Footer */}
        <div className="flex items-center justify-end gap-2 px-5 py-3 border-t border-[var(--ff-border-light)]">
          <button onClick={onClose}
            className="px-4 py-1.5 rounded text-sm text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)]">
            Cancel
          </button>
          <button onClick={handleSave} disabled={saving || !canSave}
            className="px-4 py-1.5 rounded bg-teal-600 hover:bg-teal-700 disabled:opacity-50 text-white text-sm font-medium flex items-center gap-1.5">
            {saving && <Loader2 className="h-3.5 w-3.5 animate-spin" />}
            Create
          </button>
        </div>
      </div>
    </div>
  );
}

/**
 * Chart of Accounts API
 * GET  /api/accounting/chart-of-accounts - List all accounts (flat or tree)
 * POST /api/accounting/chart-of-accounts - Create new account
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import {
  getChartOfAccounts,
  getAccountTree,
  createAccount,
  updateAccount,
} from '@/modules/accounting/services/chartOfAccountsService';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  const { companyId } = req as CompanyApiRequest;

  if (req.method === 'GET') {
    try {
      const { view, subtype, includeInactive } = req.query;
      const withInactive = includeInactive === 'true';
      let data;
      if (view === 'tree') {
        data = await getAccountTree(companyId, withInactive);
      } else {
        const accounts = await getChartOfAccounts(companyId, withInactive);
        data = subtype
          ? accounts.filter(a => a.accountSubtype === String(subtype))
          : accounts;
      }
      return apiResponse.success(res, data);
    } catch (err) {
      log.error('Failed to get chart of accounts', { error: err }, 'accounting-api');
      return apiResponse.badRequest(res, 'Failed to get chart of accounts');
    }
  }

  if (req.method === 'POST') {
    try {
      const { accountCode, accountName, accountType, accountSubtype, parentAccountId, description, normalBalance } = req.body;

      if (!accountCode || !accountName || !accountType || !normalBalance) {
        return apiResponse.badRequest(res, 'accountCode, accountName, accountType, and normalBalance are required');
      }

      const account = await createAccount(companyId, {
        accountCode,
        accountName,
        accountType,
        accountSubtype,
        parentAccountId,
        description,
        normalBalance,
      });

      return apiResponse.success(res, account);
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to create account';
      log.error('Failed to create account', { error: err }, 'accounting-api');
      return apiResponse.badRequest(res, message);
    }
  }

  if (req.method === 'PUT') {
    try {
      const { id, accountName, description, isActive, displayOrder, defaultVatCode } = req.body;
      if (!id) return apiResponse.badRequest(res, 'id is required');
      const updated = await updateAccount(companyId, id, { accountName, description, isActive, displayOrder, defaultVatCode });
      return apiResponse.success(res, updated);
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to update account';
      log.error('Failed to update account', { error: err }, 'accounting-api');
      return apiResponse.badRequest(res, message);
    }
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'POST', 'PUT']);
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withCompany(withErrorHandler(handler as any));

