export async function allocateTransaction(
  companyId: string,
  bankTxId: string,
  contraAccountId: string,
  userId: string,
  description?: string,
  allocType: AllocationType = 'account',
  entityId?: string,
  vatCode?: string,
  cc1Id?: string,
  cc2Id?: string,
  buId?: string,
): Promise<{ journalEntryId: string; bankTransaction: BankTransaction }> {
  // Get the bank transaction
  const txRows = (await sql`
    SELECT * FROM bank_transactions WHERE id = ${bankTxId}::UUID
  `) as Row[];
  if (txRows.length === 0) throw new Error(`Bank transaction ${bankTxId} not found`);
  const tx = txRows[0]!;

  if (tx.status !== 'imported') {
    throw new Error(`Transaction already ${tx.status} — cannot allocate`);
  }

  const totalAmount = Math.abs(Number(tx.amount));
  const bankAccountId = String(tx.bank_account_id);
  const txDate = tx.transaction_date instanceof Date
    ? tx.transaction_date.toISOString().split('T')[0]
    : String(tx.transaction_date).split('T')[0];
  const isSpent = Number(tx.amount) < 0;

  // VAT splitting: Standard (15%) splits into net + VAT
  const hasVat = vatCode === 'standard';
  const vatRate = hasVat ? 15 : 0;
  const netAmount = hasVat ? Math.round((totalAmount * 100 / 115) * 100) / 100 : totalAmount;
  const vatAmount = hasVat ? Math.round((totalAmount - netAmount) * 100) / 100 : 0;
  // VAT accounts: Input (expenses/payments), Output (sales/receipts)
  const vatAccountKey = isSpent ? 'vat_input' as const : 'vat_output' as const;
  const mapVatType = vatCode === 'standard' ? 'standard' as const
    : vatCode === 'zero_rated' ? 'zero_rated' as const
    : vatCode === 'exempt' ? 'exempt' as const
    : undefined;

  let lines: JournalLineInput[];
  let source: import('../types/gl.types').GLEntrySource;
  let entryDesc: string;
  let allocEntityName: string | null = null;

  if (allocType === 'supplier' && entityId) {
    // Supplier payment: DR Accounts Payable, CR Bank (+ VAT Input if applicable)
    const apAccountId = await getSystemAccountId('payable');
    const supRows = (await sql`SELECT name FROM suppliers WHERE id = ${entityId}::UUID`) as Row[];
    const supName = supRows.length > 0 ? String(supRows[0]!.name) : `Supplier #${entityId}`;
    allocEntityName = supName;
    entryDesc = description || `Payment to ${supName}`;
    source = 'auto_supplier_payment';
    lines = [
      { glAccountId: apAccountId, debit: netAmount, credit: 0, description: entryDesc, vatType: mapVatType },
      { glAccountId: bankAccountId, debit: 0, credit: totalAmount, description: entryDesc },
    ];
    if (hasVat) {
      const vatAcctId = await getSystemAccountId(vatAccountKey);
      lines.splice(1, 0, { glAccountId: vatAcctId, debit: vatAmount, credit: 0, description: `VAT @ ${vatRate}%`, vatType: 'standard' });
    }
  } else if (allocType === 'customer' && entityId) {
    // Customer receipt: DR Bank, CR Accounts Receivable (+ VAT Output if applicable)
    const arAccountId = await getSystemAccountId('receivable');
    const custRows = (await sql`SELECT name FROM customers WHERE id = ${entityId}::UUID`) as Row[];
    const custName = custRows.length > 0 ? String(custRows[0]!.name) : `Customer #${entityId}`;
    allocEntityName = custName;
    entryDesc = description || `Receipt from ${custName}`;
    source = 'auto_payment';
    lines = [
      { glAccountId: bankAccountId, debit: totalAmount, credit: 0, description: entryDesc },
      { glAccountId: arAccountId, debit: 0, credit: netAmount, description: entryDesc, vatType: mapVatType },
    ];
    if (hasVat) {
      const vatAcctId = await getSystemAccountId(vatAccountKey);
      lines.push({ glAccountId: vatAcctId, debit: 0, credit: vatAmount, description: `VAT @ ${vatRate}%`, vatType: 'standard' });
    }
  } else {
    // Standard GL account allocation
    const acctRows = (await sql`SELECT account_code, account_name FROM gl_accounts WHERE id = ${contraAccountId}::UUID`) as Row[];
    allocEntityName = acctRows.length > 0 ? `${acctRows[0]!.account_code} ${acctRows[0]!.account_name}` : null;
    entryDesc = description || tx.description || 'Bank allocation';
    source = 'auto_bank_recon';
    if (!isSpent) {
      // Money in: DR Bank (total), CR Contra (net), CR VAT Output (vat)
      lines = [
        { glAccountId: bankAccountId, debit: totalAmount, credit: 0, description: entryDesc },
        { glAccountId: contraAccountId, debit: 0, credit: netAmount, description: entryDesc, vatType: mapVatType },
      ];
      if (hasVat) {
        const vatAcctId = await getSystemAccountId(vatAccountKey);
        lines.push({ glAccountId: vatAcctId, debit: 0, credit: vatAmount, description: `VAT @ ${vatRate}%`, vatType: 'standard' });
      }
    } else {
      // Money out: DR Contra (net), DR VAT Input (vat), CR Bank (total)
      lines = [
        { glAccountId: contraAccountId, debit: netAmount, credit: 0, description: entryDesc, vatType: mapVatType },
      ];
      if (hasVat) {
        const vatAcctId = await getSystemAccountId(vatAccountKey);
        lines.push({ glAccountId: vatAcctId, debit: vatAmount, credit: 0, description: `VAT @ ${vatRate}%`, vatType: 'standard' });
      }
      lines.push({ glAccountId: bankAccountId, debit: 0, credit: totalAmount, description: entryDesc });
    }
  }

  // Attach CC1 (cost centre) and BU to contra (non-bank) lines
  const linesWithDims = lines.map(l =>
    l.glAccountId === bankAccountId ? l : { ...l, costCenterId: cc1Id || l.costCenterId, buId: buId || l.buId }
  );

  const je = await createJournalEntry(companyId, {
    entryDate: txDate,
    description: entryDesc,
    source,
    sourceDocumentId: bankTxId,
    lines: linesWithDims,
  }, userId);
  await postJournalEntry('', je.id, userId);

  // Find the bank-side journal line to match against
  const jeLines = (await sql`
    SELECT id FROM gl_journal_lines
    WHERE journal_entry_id = ${je.id}::UUID
      AND gl_account_id = ${bankAccountId}::UUID
    LIMIT 1
  `) as Row[];

  const journalLineId = jeLines.length > 0 ? String(jeLines[0]!.id) : null;

  // Mark as allocated (stays on New tab until explicitly reviewed); persist dimensions
  if (journalLineId) {
    await sql`
      UPDATE bank_transactions
      SET status = 'allocated',
          matched_journal_line_id = ${journalLineId}::UUID,
          allocation_type = ${allocType},
          allocated_entity_name = ${allocEntityName},
          cc1_id = ${cc1Id || null}::UUID,
          cc2_id = ${cc2Id || null}::UUID,
          bu_id = ${buId || null}::UUID,
          updated_at = NOW()
      WHERE id = ${bankTxId}::UUID
    `;
  }

  // Create customer_payments record so payment appears in customer statements
  if (allocType === 'customer' && entityId) {
    await sql`
      INSERT INTO customer_payments (
        client_id, payment_date, total_amount, payment_method,
        bank_reference, bank_account_id, description, status,
        gl_journal_entry_id, created_by, confirmed_by, confirmed_at
      ) VALUES (
        ${entityId}::UUID, ${txDate}, ${totalAmount}, 'eft',
        ${tx.reference || tx.bank_reference || tx.description || null},
        ${bankAccountId}::UUID, ${entryDesc}, 'confirmed',
        ${je.id}::UUID, ${userId}::UUID, ${userId}::UUID, NOW()
      )
    `;
  }

  log.info('Allocated bank transaction', {
    bankTxId, journalEntryId: je.id, allocType, entityId, contraAccountId,
  }, 'accounting');

  const updated = (await sql`SELECT * FROM bank_transactions WHERE id = ${bankTxId}::UUID`) as Row[];
  return { journalEntryId: je.id, bankTransaction: mapTxRow(updated[0]!) };
}

// ── Split Allocate ───────────────────────────────────────────────────────────

export interface SplitLine {
  contraAccountId: string;
  amount: number; // absolute amount for this line
  description?: string;
  vatCode?: string; // 'none' | 'standard' | 'zero_rated' | 'exempt'
}

/**
 * Split-allocate a bank transaction across multiple GL accounts.
 * Each split line may carry its own VAT treatment.
 * The sum of all line amounts must equal Math.abs(tx.amount).
 */
export async function splitAllocateTransaction(companyId: string, 
  bankTxId: string,
  lines: SplitLine[],
  userId: string,
): Promise<{ journalEntryId: string; bankTransaction: BankTransaction }> {
  const txRows = (await sql`
    SELECT * FROM bank_transactions WHERE id = ${bankTxId}::UUID
  `) as Row[];
  if (txRows.length === 0) throw new Error(`Bank transaction ${bankTxId} not found`);
  const tx = txRows[0]!;

  if (tx.status !== 'imported') {
    throw new Error(`Transaction already ${tx.status} — cannot split allocate`);
  }

  if (!lines || lines.length === 0) throw new Error('At least one split line is required');

  const totalAmount = Math.abs(Number(tx.amount));
  const linesTotal = lines.reduce((sum, l) => sum + Number(l.amount), 0);
  // Allow 1-cent rounding tolerance
  if (Math.abs(linesTotal - totalAmount) > 0.01) {
    throw new Error(
      `Split lines total R${linesTotal.toFixed(2)} does not equal transaction amount R${totalAmount.toFixed(2)}`
    );
  }

  const bankAccountId = String(tx.bank_account_id);
  const txDate = tx.transaction_date instanceof Date
    ? tx.transaction_date.toISOString().split('T')[0]
    : String(tx.transaction_date).split('T')[0];
  const isSpent = Number(tx.amount) < 0;
  const entryDesc = tx.description || 'Split bank allocation';
  const journalLines: JournalLineInput[] = [];

  // Build contra lines for each split
  for (const line of lines) {
    const lineAmount = Number(line.amount);
    const hasVat = line.vatCode === 'standard';
    const netAmount = hasVat ? Math.round((lineAmount * 100 / 115) * 100) / 100 : lineAmount;
    const vatAmount = hasVat ? Math.round((lineAmount - netAmount) * 100) / 100 : 0;
    const vatAccountKey = isSpent ? 'vat_input' as const : 'vat_output' as const;
    const lineDesc = line.description || entryDesc;
    const mapVatType = line.vatCode === 'standard' ? 'standard' as const
      : line.vatCode === 'zero_rated' ? 'zero_rated' as const
      : line.vatCode === 'exempt' ? 'exempt' as const
      : undefined;

    if (isSpent) {
      // Money out: DR contra (net), DR VAT Input (vat if standard)
      journalLines.push({
        glAccountId: line.contraAccountId,
        debit: netAmount, credit: 0,
        description: lineDesc,
        vatType: mapVatType,
      });
      if (hasVat) {
        const vatAcctId = await getSystemAccountId(vatAccountKey);
        journalLines.push({
          glAccountId: vatAcctId,
          debit: vatAmount, credit: 0,
          description: `VAT @ 15%`,
          vatType: 'standard',
        });

/**
 * PRD-060: FibreFlow Accounting Module
 * Bank Transaction Auto-Match Algorithm
 *
 * Four-tier matching strategy:
 *   Tier 0: Rule-based match via bank_categorisation_rules (confidence 1.0)
 *   Tier 1: Exact reference match (confidence 1.0)
 *   Tier 2: Amount + date within 3 days (confidence 0.9)
 *   Tier 3: Amount only match (confidence 0.7)
 */

import type { AutoMatchCandidate } from '../types/bank.types';

interface BankTxForMatch {
  id: string;
  amount: number;
  transactionDate: string;
  reference?: string;
  description?: string;
}

interface JournalLineForMatch {
  id: string;
  debit: number;
  credit: number;
  description?: string;
  entryDate: string;
  entryNumber?: string;
  sourceDocumentId?: string;
}

/**
 * Find match candidates for a single bank transaction against unmatched GL journal lines.
 * Returns candidates sorted by confidence DESC.
 */
export function findMatchCandidates(
  bankTx: BankTxForMatch,
  glLines: JournalLineForMatch[],
  threshold: number = 0.7
): AutoMatchCandidate[] {
  const candidates: AutoMatchCandidate[] = [];
  const txAmount = Math.abs(bankTx.amount);
  const isDeposit = bankTx.amount > 0;

  for (const line of glLines) {
    // For deposits, match against credit lines; for withdrawals, match against debit lines
    const lineAmount = isDeposit ? line.credit : line.debit;
    if (lineAmount <= 0) continue;

    const amountMatch = Math.abs(txAmount - lineAmount) < 0.02;
    if (!amountMatch) continue;

    // Tier 1: Exact reference match
    if (bankTx.reference && bankTx.reference.trim().length > 2) {
      const ref = bankTx.reference.toLowerCase().trim();
      const lineDesc = (line.description || '').toLowerCase();
      const entryNum = (line.entryNumber || '').toLowerCase();
      const sourceDoc = (line.sourceDocumentId || '').toLowerCase();

      if (lineDesc.includes(ref) || entryNum.includes(ref) || ref.includes(entryNum) || sourceDoc.includes(ref)) {
        candidates.push({
          bankTransactionId: bankTx.id,
          journalLineId: line.id,
          confidence: 1.0,
          matchReason: 'exact_reference',
        });
        continue;
      }
    }

    // Check description-based reference match
    if (bankTx.description && bankTx.description.trim().length > 3) {
      const desc = bankTx.description.toLowerCase().trim();
      const lineDesc = (line.description || '').toLowerCase();
      if (lineDesc.length > 3 && (desc.includes(lineDesc) || lineDesc.includes(desc))) {
        candidates.push({
          bankTransactionId: bankTx.id,
          journalLineId: line.id,
          confidence: 0.95,
          matchReason: 'exact_reference',
        });
        continue;
      }
    }

    // Tier 2: Amount + date within 3 days
    const daysDiff = Math.abs(dateDiffDays(bankTx.transactionDate, line.entryDate));
    if (daysDiff <= 3) {
      candidates.push({
        bankTransactionId: bankTx.id,
        journalLineId: line.id,
        confidence: 0.9,
        matchReason: 'amount_date',
      });
      continue;
    }

    // Tier 3: Amount only
    candidates.push({
      bankTransactionId: bankTx.id,
      journalLineId: line.id,
      confidence: 0.7,
      matchReason: 'amount_only',
    });
  }

  return candidates
    .filter(c => c.confidence >= threshold)
    .sort((a, b) => b.confidence - a.confidence);
}

/**
 * Run auto-match across multiple bank transactions.
 * Returns best single match per bank transaction (highest confidence).
 * Prevents duplicate GL line matches.
 */
export function runAutoMatch(
  bankTxs: BankTxForMatch[],
  glLines: JournalLineForMatch[],
  threshold: number = 0.7
): { matches: AutoMatchCandidate[]; unmatched: string[] } {
  const matches: AutoMatchCandidate[] = [];
  const usedGlLines = new Set<string>();
  const unmatched: string[] = [];

  // Sort bank transactions by amount DESC for better matching priority
  const sorted = [...bankTxs].sort((a, b) => Math.abs(b.amount) - Math.abs(a.amount));

  for (const tx of sorted) {
    const availableLines = glLines.filter(l => !usedGlLines.has(l.id));
    const candidates = findMatchCandidates(tx, availableLines, threshold);

    if (candidates.length > 0) {
      const best = candidates[0]!;
      matches.push(best);
      usedGlLines.add(best.journalLineId);
    } else {
      unmatched.push(tx.id);
    }
  }

  return { matches, unmatched };
}

function dateDiffDays(dateA: string, dateB: string): number {
  const a = new Date(dateA);
  const b = new Date(dateB);
  return Math.round((a.getTime() - b.getTime()) / (1000 * 60 * 60 * 24));
}

import { NextApiRequest, NextApiResponse } from 'next';
import { apiLogger } from '@/lib/logger';

const SENSITIVE_KEYS = new Set(['password', 'confirmPassword', 'password_hash', 'token', 'secret', 'apiKey', 'api_key']);

function sanitizeBody(body: unknown): unknown {
  if (!body || typeof body !== 'object') return body;
  const sanitized: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(body as Record<string, unknown>)) {
    sanitized[key] = SENSITIVE_KEYS.has(key) ? '[REDACTED]' : value;
  }
  return sanitized;
}

/**
 * Standard API error response
 */
export interface ApiErrorResponse {
  success: false;
  data: null;
  message: string;
  code?: string;
  details?: Record<string, unknown>;
}

/**
 * Standard API success response
 */
export interface ApiSuccessResponse<T = unknown> {
  success: true;
  data: T;
  message?: string;
}

export type ApiResponse<T = unknown> = ApiSuccessResponse<T> | ApiErrorResponse;

/**
 * Wraps an API handler with error handling
 * Generic R extends NextApiRequest to support AuthenticatedNextApiRequest
 */
export function withErrorHandler<T = unknown, R extends NextApiRequest = NextApiRequest>(
  handler: (req: R, res: NextApiResponse<ApiResponse<T>>) => Promise<void>
) {
  return async (req: R, res: NextApiResponse<ApiResponse<T>>) => {
    const startTime = Date.now();

    try {
      // Set CORS headers - restrict to known origins
      const allowedOrigins = [
        'https://fin.fibreflow.app',
        ...(process.env.NODE_ENV === 'development'
          ? ['http://localhost:3101', 'http://localhost:3004']
          : []),
      ];
      const origin = req.headers.origin;
      if (origin && allowedOrigins.includes(origin)) {
        res.setHeader('Access-Control-Allow-Origin', origin);
        res.setHeader('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE, OPTIONS');
        res.setHeader('Access-Control-Allow-Headers', 'Content-Type, Authorization');
      }

      // Handle OPTIONS request for CORS
      if (req.method === 'OPTIONS') {
        return res.status(200).end();
      }

      // Log incoming request
      apiLogger.info({
        type: 'request',
        method: req.method,
        url: req.url,
        query: req.query,
        body: req.method !== 'GET' ? sanitizeBody(req.body) : undefined,
      }, `API Request: ${req.method} ${req.url}`);

      // Execute the actual handler
      await handler(req, res);

      // Log successful response
      const duration = Date.now() - startTime;
      apiLogger.info({
        type: 'response',
        method: req.method,
        url: req.url,
        statusCode: res.statusCode,
        duration: `${duration}ms`,
      }, `API Response: ${req.method} ${req.url} - ${res.statusCode} (${duration}ms)`);

    } catch (error) {
      const duration = Date.now() - startTime;

      // Log error with context
      apiLogger.error({
        type: 'error',
        method: req.method,
        url: req.url,
        error: error instanceof Error ? error.message : 'Unknown error',
        stack: error instanceof Error ? error.stack : undefined,
        duration: `${duration}ms`,
      });

      // Check if headers were already sent
      if (res.headersSent) {
        apiLogger.warn({ method: req.method, url: req.url }, 'Headers already sent, cannot send error response');
        return;
      }

      // Send error response — mask internal details in production
      const errorMessage =
        process.env.NODE_ENV === 'production'
          ? 'An unexpected error occurred'
          : error instanceof Error ? error.message : 'An unexpected error occurred';

      res.status(500).json({
        success: false,
        data: null,
        message: errorMessage,
        code: 'INTERNAL_SERVER_ERROR',
        ...(process.env.NODE_ENV === 'development' && {
          details: error instanceof Error ? {
            message: error.message,
            stack: error.stack,
          } as Record<string, unknown> : { error: String(error) },
        }),
      });
    }
  };
}

/**
 * Creates a standard success response
 */
export function successResponse<T>(data: T, message?: string): ApiSuccessResponse<T> {
  return {
    success: true,
    data,
    ...(message && { message }),
  };
}

/**
 * Creates a standard error response
 */
export function errorResponse(
  message: string,
  code?: string,
  details?: Record<string, unknown>
): ApiErrorResponse {
  return {
    success: false,
    data: null,
    message,
    ...(code && { code }),
    ...(details && process.env.NODE_ENV === 'development' && { details }),
  };
}

/**
 * Common HTTP error responses
 */
export const HttpErrors = {
  BadRequest: (message = 'Bad Request') =>
    errorResponse(message, 'BAD_REQUEST'),

  Unauthorized: (message = 'Unauthorized') =>
    errorResponse(message, 'UNAUTHORIZED'),

  Forbidden: (message = 'Forbidden') =>
    errorResponse(message, 'FORBIDDEN'),

  NotFound: (message = 'Not Found') =>
    errorResponse(message, 'NOT_FOUND'),

  MethodNotAllowed: (method: string) =>
    errorResponse(`Method ${method} not allowed`, 'METHOD_NOT_ALLOWED'),

  InternalServerError: (message = 'Internal Server Error') =>
    errorResponse(message, 'INTERNAL_SERVER_ERROR'),

  DatabaseError: (message = 'Database operation failed') =>
    errorResponse(message, 'DATABASE_ERROR'),

  ValidationError: (message = 'Validation failed', details?: Record<string, unknown>) =>
    errorResponse(message, 'VALIDATION_ERROR', details),
};

import { NextApiRequest, NextApiResponse } from 'next';
import { log } from '@/lib/logger';

/**
 * Standard API Response Types
 */
export interface ApiSuccessResponse<T = any> {
  success: true;
  data: T;
  message?: string;
  meta?: {
    timestamp?: string;
    requestId?: string;
    [key: string]: any;
  };
}

export interface ApiErrorResponse {
  success: false;
  error: {
    code: string;
    message: string;
    details?: any;
  };
  meta?: {
    timestamp?: string;
    requestId?: string;
    [key: string]: any;
  };
}

export interface ApiPaginatedResponse<T = any> extends ApiSuccessResponse<T[]> {
  pagination: {
    page: number;
    pageSize: number;
    total: number;
    totalPages: number;
  };
}

export type ApiResponse<T = any> = ApiSuccessResponse<T> | ApiErrorResponse;

/**
 * Standard error codes
 */
export enum ErrorCode {
  // Client errors (400-499)
  BAD_REQUEST = 'BAD_REQUEST',
  UNAUTHORIZED = 'UNAUTHORIZED',
  FORBIDDEN = 'FORBIDDEN',
  NOT_FOUND = 'NOT_FOUND',
  METHOD_NOT_ALLOWED = 'METHOD_NOT_ALLOWED',
  CONFLICT = 'CONFLICT',
  VALIDATION_ERROR = 'VALIDATION_ERROR',
  RATE_LIMIT = 'RATE_LIMIT',
  PAYLOAD_TOO_LARGE = 'PAYLOAD_TOO_LARGE',

  // Server errors (500-599)
  INTERNAL_ERROR = 'INTERNAL_ERROR',
  DATABASE_ERROR = 'DATABASE_ERROR',
  SERVICE_UNAVAILABLE = 'SERVICE_UNAVAILABLE',
  GATEWAY_TIMEOUT = 'GATEWAY_TIMEOUT',

  // Business logic errors
  BUSINESS_RULE_VIOLATION = 'BUSINESS_RULE_VIOLATION',
  INSUFFICIENT_PERMISSIONS = 'INSUFFICIENT_PERMISSIONS',
  RESOURCE_LOCKED = 'RESOURCE_LOCKED',
  DEPENDENCY_ERROR = 'DEPENDENCY_ERROR',
}

/**
 * HTTP status code mapping
 */
const STATUS_CODE_MAP: Record<ErrorCode, number> = {
  // Client errors
  [ErrorCode.BAD_REQUEST]: 400,
  [ErrorCode.UNAUTHORIZED]: 401,
  [ErrorCode.FORBIDDEN]: 403,
  [ErrorCode.NOT_FOUND]: 404,
  [ErrorCode.METHOD_NOT_ALLOWED]: 405,
  [ErrorCode.CONFLICT]: 409,
  [ErrorCode.VALIDATION_ERROR]: 422,
  [ErrorCode.RATE_LIMIT]: 429,
  [ErrorCode.PAYLOAD_TOO_LARGE]: 413,

  // Server errors
  [ErrorCode.INTERNAL_ERROR]: 500,
  [ErrorCode.DATABASE_ERROR]: 500,
  [ErrorCode.SERVICE_UNAVAILABLE]: 503,
  [ErrorCode.GATEWAY_TIMEOUT]: 504,

  // Business logic errors (usually 400 or 422)
  [ErrorCode.BUSINESS_RULE_VIOLATION]: 422,
  [ErrorCode.INSUFFICIENT_PERMISSIONS]: 403,
  [ErrorCode.RESOURCE_LOCKED]: 423,
  [ErrorCode.DEPENDENCY_ERROR]: 424,
};

/**
 * API Response Helper Class
 */
export class ApiResponseHelper {
  private static generateMeta(additionalMeta?: Record<string, any>) {
    return {
      timestamp: new Date().toISOString(),
      ...additionalMeta,
    };
  }

  /**
   * Send success response
   */
  static success<T>(
    res: NextApiResponse,
    data: T,
    message?: string,
    statusCode = 200,
    meta?: Record<string, any>
  ): void {
    const response: ApiSuccessResponse<T> = {
      success: true,
      data,
      ...(message && { message }),
      meta: this.generateMeta(meta),
    };

    res.status(statusCode).json(response);
  }

  /**
   * Send created response (201)
   */
  static created<T>(
    res: NextApiResponse,
    data: T,
    message = 'Resource created successfully',
    meta?: Record<string, any>
  ): void {
    this.success(res, data, message, 201, meta);
  }

  /**
   * Send no content response (204)
   */
  static noContent(res: NextApiResponse): void {
    res.status(204).end();
  }

  /**
   * Send paginated response
   */
  static paginated<T>(
    res: NextApiResponse,
    data: T[],
    pagination: {
      page: number;
      pageSize: number;
      total: number;
    },
    message?: string,
    meta?: Record<string, any>
  ): void {
    const totalPages = Math.ceil(pagination.total / pagination.pageSize);

    const response: ApiPaginatedResponse<T> = {
      success: true,
      data,
      pagination: {
        ...pagination,
        totalPages,
      },
      ...(message && { message }),
      meta: this.generateMeta(meta),
    };

    res.status(200).json(response);
  }

  /**
   * Send error response
   */
  static error(
    res: NextApiResponse,
    code: ErrorCode,
    message: string,
    details?: any,
    meta?: Record<string, any>
  ): void {
    const statusCode = STATUS_CODE_MAP[code] || 500;

    const response: ApiErrorResponse = {
      success: false,
      error: {
        code,
        message,
        ...(details && { details }),
      },
      meta: this.generateMeta(meta),
    };

    res.status(statusCode).json(response);
  }

  /**
   * Send bad request error response (400)
   */
  static badRequest(
    res: NextApiResponse,
    message: string,
    details?: any
  ): void {
    this.error(res, ErrorCode.BAD_REQUEST, message, details);
  }

  /**
   * Send validation error response
   */
  static validationError(
    res: NextApiResponse,
    errors: Record<string, string | string[]>,
    message = 'Validation failed'
  ): void {
    this.error(res, ErrorCode.VALIDATION_ERROR, message, errors);
  }

  /**
   * Send not found error response
   */
  static notFound(
    res: NextApiResponse,
    resource: string,
    identifier?: string | number
  ): void {
    const message = identifier
      ? `${resource} with identifier '${identifier}' not found`
      : `${resource} not found`;

    this.error(res, ErrorCode.NOT_FOUND, message);
  }

  /**
   * Send unauthorized error response
   */
  static unauthorized(
    res: NextApiResponse,
    message = 'Authentication required'
  ): void {
    this.error(res, ErrorCode.UNAUTHORIZED, message);
  }

  /**
   * Send forbidden error response
   */
  static forbidden(
    res: NextApiResponse,
    message = 'You do not have permission to perform this action'
  ): void {
    this.error(res, ErrorCode.FORBIDDEN, message);
  }

  /**
   * Send method not allowed error response
   */
  static methodNotAllowed(
    res: NextApiResponse,
    method: string,
    allowedMethods: string[]
  ): void {
    res.setHeader('Allow', allowedMethods.join(', '));
    this.error(
      res,
      ErrorCode.METHOD_NOT_ALLOWED,
      `Method ${method} not allowed. Allowed methods: ${allowedMethods.join(', ')}`
    );
  }

  /**
   * Send internal server error response
   */
  static internalError(
    res: NextApiResponse,
    error: Error | unknown,
    detailedMessage?: string
  ): void {
    // Log the actual error for debugging
    log.error('Internal Server Error', error instanceof Error ? { message: error.message, stack: error.stack } : { error }, 'ApiResponse');

    // In production, never expose internal error details
    const isDevelopment = process.env.NODE_ENV === 'development';
    const message = isDevelopment
      ? (detailedMessage || 'An internal error occurred')
      : 'An internal error occurred';
    const errorDetails = isDevelopment && error instanceof Error
      ? { stack: error.stack, originalMessage: error.message }
      : undefined;

    this.error(res, ErrorCode.INTERNAL_ERROR, message, errorDetails);
  }

  /**
   * Send database error response
   */
  static databaseError(
    res: NextApiResponse,
    error: Error | unknown,
    message = 'A database error occurred'
  ): void {
    // Log the actual error for debugging
    log.error('Database Error', error instanceof Error ? { message: error.message } : { error }, 'ApiResponse');

    // In production, don't expose database error details
    const isDevelopment = process.env.NODE_ENV === 'development';
    const errorDetails = isDevelopment && error instanceof Error
      ? { originalMessage: error.message }
      : undefined;

    this.error(res, ErrorCode.DATABASE_ERROR, message, errorDetails);
  }

  /**
   * Handle CORS headers
   */
  static setCorsHeaders(
    res: NextApiResponse,
    origin = '',
    methods = ['GET', 'POST', 'PUT', 'DELETE', 'PATCH', 'OPTIONS'],
    headers = ['Content-Type', 'Authorization']
  ): void {
    const allowedOrigins = [
      'https://fin.fibreflow.app',
      ...(process.env.NODE_ENV === 'development'
        ? ['http://localhost:3101', 'http://localhost:3004']
        : []),
    ];
    const safeOrigin = origin && allowedOrigins.includes(origin) ? origin : '';
    if (!safeOrigin) return;
    res.setHeader('Access-Control-Allow-Origin', safeOrigin);
    res.setHeader('Access-Control-Allow-Methods', methods.join(', '));
    res.setHeader('Access-Control-Allow-Headers', headers.join(', '));
  }

  /**
   * Handle OPTIONS request for CORS
   */
  static handleOptions(req: NextApiRequest, res: NextApiResponse): void {
    this.setCorsHeaders(res, req.headers.origin || '');
    res.status(200).end();
  }
}

/**
 * Convenience exports for common responses
 */
export const apiResponse = {
  success: ApiResponseHelper.success.bind(ApiResponseHelper),
  created: ApiResponseHelper.created.bind(ApiResponseHelper),
  noContent: ApiResponseHelper.noContent.bind(ApiResponseHelper),
  paginated: ApiResponseHelper.paginated.bind(ApiResponseHelper),
  error: ApiResponseHelper.error.bind(ApiResponseHelper),
  badRequest: ApiResponseHelper.badRequest.bind(ApiResponseHelper),
  validationError: ApiResponseHelper.validationError.bind(ApiResponseHelper),
  notFound: ApiResponseHelper.notFound.bind(ApiResponseHelper),
  unauthorized: ApiResponseHelper.unauthorized.bind(ApiResponseHelper),
  forbidden: ApiResponseHelper.forbidden.bind(ApiResponseHelper),
  methodNotAllowed: ApiResponseHelper.methodNotAllowed.bind(ApiResponseHelper),
  internalError: ApiResponseHelper.internalError.bind(ApiResponseHelper),
  databaseError: ApiResponseHelper.databaseError.bind(ApiResponseHelper),
  setCorsHeaders: ApiResponseHelper.setCorsHeaders.bind(ApiResponseHelper),
  handleOptions: ApiResponseHelper.handleOptions.bind(ApiResponseHelper),
};

export default apiResponse;

