/**
 * Bank Match Candidates API
 * GET /api/accounting/bank-match-candidates?bankTransactionId=<uuid>
 * Returns scored candidate matches from supplier invoices, purchase orders, and GL journal lines.
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import { sql } from '@/lib/neon';
import type { CandidateType, MatchCandidate } from '@/modules/accounting/types/bank-match.types';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

/** Score 0–50: how close the candidate amount is to the transaction amount */
function scoreAmount(txAmount: number, candidateAmount: number): number {
  const diff = Math.abs(Math.abs(txAmount) - Math.abs(candidateAmount));
  if (diff === 0) return 50;
  if (diff < 0.01) return 48;
  if (diff < 1) return 40;
  if (diff < 10) return 30;
  if (diff < 100) return 20;
  if (diff < 1000) return 10;
  return 0;
}

/** Score 0–30: how close the candidate date is to the transaction date */
function scoreDate(txDate: string, candidateDate: string): number {
  const tx = new Date(txDate).getTime();
  const cand = new Date(candidateDate).getTime();
  const diffDays = Math.abs(tx - cand) / (1000 * 60 * 60 * 24);
  if (diffDays === 0) return 30;
  if (diffDays <= 1) return 28;
  if (diffDays <= 3) return 24;
  if (diffDays <= 7) return 20;
  if (diffDays <= 14) return 14;
  if (diffDays <= 30) return 8;
  if (diffDays <= 60) return 4;
  return 0;
}

/** Score 0–20: simple word-overlap between description strings */
function scoreDescription(txDesc: string, candidateLabel: string): number {
  if (!txDesc || !candidateLabel) return 0;
  const txWords = new Set(txDesc.toLowerCase().split(/\W+/).filter(w => w.length > 2));
  const candWords = candidateLabel.toLowerCase().split(/\W+/).filter(w => w.length > 2);
  if (txWords.size === 0 || candWords.length === 0) return 0;
  const matches = candWords.filter(w => txWords.has(w)).length;
  const ratio = matches / Math.max(txWords.size, candWords.length);
  return Math.round(ratio * 20);
}

function fmtDate(val: unknown): string {
  if (val instanceof Date) return val.toISOString().split('T')[0]!;
  return val ? String(val).split('T')[0]! : '';
}

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method ?? 'UNKNOWN', ['GET']);
  }

  const { bankTransactionId } = req.query;
  if (!bankTransactionId || typeof bankTransactionId !== 'string') {
    return apiResponse.badRequest(res, 'bankTransactionId query param is required');
  }

  const { companyId } = req as CompanyApiRequest;

  try {
    // Fetch the bank transaction to get amount, date, description
    const txRows = (await sql`
      SELECT id, amount, transaction_date, description, reference
      FROM bank_transactions
      WHERE id = ${bankTransactionId}::UUID AND company_id = ${companyId}
    `) as Row[];

    if (txRows.length === 0) {
      return apiResponse.notFound(res, 'Bank transaction', bankTransactionId);
    }

    const tx = txRows[0]!;
    const txAmount = Number(tx.amount);
    const txDate = fmtDate(tx.transaction_date);
    const txDesc = String(tx.description ?? tx.reference ?? '');
    const absAmount = Math.abs(txAmount);

    const candidates: MatchCandidate[] = [];

    // ── 1. Supplier invoices ─────────────────────────────────────────────────
    const invoiceRows = (await sql`
      SELECT si.id, si.invoice_number, s.company_name AS supplier_name,
             si.total_amount, si.invoice_date
      FROM supplier_invoices si
      JOIN suppliers s ON s.id = si.supplier_id
      WHERE si.status IN ('approved', 'partially_paid')
        AND si.company_id = ${companyId}
      ORDER BY ABS(si.total_amount - ${absAmount}::NUMERIC) ASC
      LIMIT 20
    `) as Row[];

    for (const row of invoiceRows) {
      const label = `${String(row.supplier_name)} — Inv ${String(row.invoice_number)}`;
      const candAmount = Number(row.total_amount);
      const candDate = fmtDate(row.invoice_date);
      const score = scoreAmount(txAmount, candAmount)
        + scoreDate(txDate, candDate)
        + scoreDescription(txDesc, label);
      candidates.push({
        type: 'supplier_invoice',
        id: String(row.id),
        label,
        amount: candAmount,
        date: candDate,
        score,
      });
    }

    // ── 2. Purchase orders ───────────────────────────────────────────────────
    const poRows = (await sql`
      SELECT po.id, po.po_number, s.company_name AS supplier_name,
             po.total_amount, po.created_at
      FROM purchase_orders po
      JOIN suppliers s ON s.id = po.supplier_id
      WHERE po.status IN ('approved', 'partially_paid')
        AND po.bank_transaction_id IS NULL
      ORDER BY ABS(po.total_amount - ${absAmount}::NUMERIC) ASC
      LIMIT 20
    `) as Row[];

    for (const row of poRows) {
      const label = `${String(row.supplier_name)} — PO ${String(row.po_number)}`;
      const candAmount = Number(row.total_amount);
      const candDate = fmtDate(row.created_at);
      const score = scoreAmount(txAmount, candAmount)
        + scoreDate(txDate, candDate)
        + scoreDescription(txDesc, label);
      candidates.push({
        type: 'purchase_order',
        id: String(row.id),
        label,
        amount: candAmount,
        date: candDate,
        score,
      });
    }

    // ── 3. GL journal lines ──────────────────────────────────────────────────
    const jlRows = (await sql`
      SELECT jl.id, jl.description, jl.debit, jl.credit, je.entry_date
      FROM gl_journal_lines jl
      JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
      WHERE je.status = 'posted'
        AND je.company_id = ${companyId}
        AND jl.id NOT IN (
          SELECT matched_journal_line_id FROM bank_transactions
          WHERE matched_journal_line_id IS NOT NULL
        )
      ORDER BY ABS((jl.debit - jl.credit) - ${txAmount}::NUMERIC) ASC
      LIMIT 20
    `) as Row[];

    for (const row of jlRows) {
      const lineNet = Number(row.debit) - Number(row.credit);
      const label = String(row.description ?? 'Journal line');
      const candDate = fmtDate(row.entry_date);
      const score = scoreAmount(txAmount, lineNet)
        + scoreDate(txDate, candDate)
        + scoreDescription(txDesc, label);
      candidates.push({
        type: 'journal_line',
        id: String(row.id),
        label,
        amount: lineNet,
        date: candDate,
        score,
      });
    }

    // Sort all candidates by score descending
    candidates.sort((a, b) => b.score - a.score);

    log.info('Fetched bank match candidates', {
      bankTransactionId,
      count: candidates.length,
    }, 'accounting-api');

    return apiResponse.success(res, { candidates });
  } catch (err) {
    log.error('Failed to fetch bank match candidates', { bankTransactionId, error: err }, 'accounting-api');
    return apiResponse.internalError(res, err);
  }
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withCompany(withErrorHandler(handler as any));

/**
 * Bank Match Confirm API
 * POST /api/accounting/bank-match-confirm
 * Body: { bankTransactionId, candidateType, candidateId }
 * Confirms a manual match selection from the FindMatchModal.
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import { sql } from '@/lib/neon';
import {
  allocateTransaction,
  matchTransaction,
} from '@/modules/accounting/services/bankReconciliationService';
import type { CandidateType } from '@/modules/accounting/types/bank-match.types';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method ?? 'UNKNOWN', ['POST']);
  }

  const {
    bankTransactionId,
    candidateType,
    candidateId,
  } = req.body as {
    bankTransactionId?: string;
    candidateType?: CandidateType;
    candidateId?: string;
  };

  const { companyId } = req as CompanyApiRequest;
  // @ts-expect-error — auth middleware attaches user
  const userId: string = req.user?.id ?? req.user?.userId ?? 'system';

  if (!bankTransactionId) return apiResponse.badRequest(res, 'bankTransactionId is required');
  if (!candidateType) return apiResponse.badRequest(res, 'candidateType is required');
  if (!candidateId) return apiResponse.badRequest(res, 'candidateId is required');

  const validTypes: CandidateType[] = ['supplier_invoice', 'purchase_order', 'journal_line'];
  if (!validTypes.includes(candidateType)) {
    return apiResponse.badRequest(res, `candidateType must be one of: ${validTypes.join(', ')}`);
  }

  try {
    if (candidateType === 'supplier_invoice') {
      // Look up the supplier invoice to derive the supplier entity id
      const invRows = (await sql`
        SELECT id, supplier_id, total_amount FROM supplier_invoices WHERE id = ${candidateId}::UUID AND company_id = ${companyId}
      `) as Row[];
      if (invRows.length === 0) {
        return apiResponse.notFound(res, 'Supplier invoice', candidateId);
      }
      const inv = invRows[0]!;
      const supplierId = String(inv.supplier_id);

      // Allocate the bank transaction against the AP account for this supplier
      await allocateTransaction(
        companyId,
        bankTransactionId,
        '', // contraAccountId unused when allocType is 'supplier'
        userId,
        undefined,
        'supplier',
        supplierId,
      );

      // Mark invoice as paid
      await sql`
        UPDATE supplier_invoices SET status = 'paid', updated_at = NOW()
        WHERE id = ${candidateId}::UUID
      `;

      log.info('Confirmed match: supplier invoice', { bankTransactionId, candidateId }, 'accounting-api');
    } else if (candidateType === 'purchase_order') {
      // Look up the PO to derive the supplier entity id
      const poRows = (await sql`
        SELECT id, supplier_id, total_amount FROM purchase_orders WHERE id = ${candidateId}::UUID
      `) as Row[];
      if (poRows.length === 0) {
        return apiResponse.notFound(res, 'Purchase order', candidateId);
      }
      const po = poRows[0]!;
      const supplierId = String(po.supplier_id);

      // Allocate against AP account for this supplier
      await allocateTransaction(
        companyId,
        bankTransactionId,
        '',
        userId,
        undefined,
        'supplier',
        supplierId,
      );

      // Link PO to bank transaction and mark as paid
      await sql`
        UPDATE purchase_orders
        SET bank_transaction_id = ${bankTransactionId}::UUID,
            status = 'paid',
            updated_at = NOW()
        WHERE id = ${candidateId}::UUID
      `;

      // Link bank transaction back to the PO
      await sql`
        UPDATE bank_transactions
        SET linked_po_id = ${candidateId}::UUID, updated_at = NOW()
        WHERE id = ${bankTransactionId}::UUID
      `;

      log.info('Confirmed match: purchase order', { bankTransactionId, candidateId }, 'accounting-api');
    } else {
      // journal_line — use the existing matchTransaction function
      await matchTransaction(companyId, bankTransactionId, candidateId);
      log.info('Confirmed match: journal line', { bankTransactionId, candidateId }, 'accounting-api');
    }

    return apiResponse.success(res, { matched: true, candidateType, candidateId });
  } catch (err) {
    const message = err instanceof Error ? err.message : 'Match confirmation failed';
    log.error('Failed to confirm bank match', { bankTransactionId, candidateType, candidateId, error: err }, 'accounting-api');
    return apiResponse.badRequest(res, message);
  }
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withCompany(withErrorHandler(handler as any));

/**
 * Find & Match Modal — manually match a bank transaction to a candidate
 * (supplier invoice, purchase order, or GL journal line).
 * Fetches scored candidates from /api/accounting/bank-match-candidates and
 * confirms the selection via /api/accounting/bank-match-confirm.
 */

import { useState, useEffect } from 'react';
import { X, Search, CheckCircle, FileText, ShoppingCart, BookOpen, Loader2 } from 'lucide-react';
import { notify } from '@/utils/toast';
import { apiFetch } from '@/lib/apiFetch';
import type { MatchCandidate, CandidateType } from '@/modules/accounting/types/bank-match.types';

interface Transaction {
  id: string;
  description?: string;
  amount: number;
  transactionDate: string;
}

interface Props {
  transaction: Transaction;
  onClose: () => void;
  /** Called after a successful match — parent should refresh the transaction list */
  onMatch: (candidateType: CandidateType, candidateId: string) => void;
}

function fmtCurrency(n: number): string {
  return new Intl.NumberFormat('en-ZA', { style: 'currency', currency: 'ZAR' }).format(n);
}

const TYPE_META: Record<CandidateType, { label: string; icon: typeof FileText; colour: string }> = {
  supplier_invoice: { label: 'Invoice', icon: FileText, colour: 'text-blue-400 bg-blue-400/10' },
  purchase_order: { label: 'PO', icon: ShoppingCart, colour: 'text-amber-400 bg-amber-400/10' },
  journal_line: { label: 'Journal', icon: BookOpen, colour: 'text-purple-400 bg-purple-400/10' },
};

const GROUP_ORDER: CandidateType[] = ['supplier_invoice', 'purchase_order', 'journal_line'];
const GROUP_TITLES: Record<CandidateType, string> = {
  supplier_invoice: 'Supplier Invoices',
  purchase_order: 'Purchase Orders',
  journal_line: 'Journal Lines',
};

export function FindMatchModal({ transaction, onClose, onMatch }: Props) {
  const [candidates, setCandidates] = useState<MatchCandidate[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [selected, setSelected] = useState<MatchCandidate | null>(null);
  const [confirming, setConfirming] = useState(false);
  const [search, setSearch] = useState('');

  useEffect(() => {
    let cancelled = false;

    const fetchCandidates = async () => {
      setLoading(true);
      setError(null);
      try {
        const res = await apiFetch(
          `/api/accounting/bank-match-candidates?bankTransactionId=${encodeURIComponent(transaction.id)}`,
        );
        const json = await res.json() as { success: boolean; data?: { candidates: MatchCandidate[] }; error?: { message: string } };
        if (!res.ok || !json.success) {
          throw new Error(json.error?.message ?? 'Failed to load candidates');
        }
        if (!cancelled) {
          setCandidates(json.data?.candidates ?? []);
        }
      } catch (err) {
        if (!cancelled) {
          setError(err instanceof Error ? err.message : 'Failed to load candidates');
        }
      } finally {
        if (!cancelled) setLoading(false);
      }
    };

    void fetchCandidates();
    return () => { cancelled = true; };
  }, [transaction.id]);

  const filtered = candidates.filter(c => {
    if (!search) return true;
    const q = search.toLowerCase();
    return c.label.toLowerCase().includes(q) || fmtCurrency(c.amount).includes(q);
  });

  const grouped = GROUP_ORDER.reduce<Record<CandidateType, MatchCandidate[]>>((acc, type) => {
    acc[type] = filtered.filter(c => c.type === type);
    return acc;
  }, { supplier_invoice: [], purchase_order: [], journal_line: [] });

  const handleConfirm = async () => {
    if (!selected) return;
    setConfirming(true);
    try {
      const res = await apiFetch('/api/accounting/bank-match-confirm', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          bankTransactionId: transaction.id,
          candidateType: selected.type,
          candidateId: selected.id,
        }),
      });
      const json = await res.json() as { success: boolean; error?: { message: string } };
      if (!res.ok || !json.success) {
        throw new Error(json.error?.message ?? 'Match failed');
      }
      const matchedMeta = TYPE_META[selected.type];
      notify.success(`Matched to ${matchedMeta?.label ?? selected.type}: ${selected.label}`);
      onMatch(selected.type, selected.id);
    } catch (err) {
      notify.error(err instanceof Error ? err.message : 'Match confirmation failed');
    } finally {
      setConfirming(false);
    }
  };

  const txIsExact = (c: MatchCandidate) => Math.abs(Math.abs(c.amount) - Math.abs(transaction.amount)) < 0.01;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 p-4">
      <div className="w-full max-w-xl bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)] rounded-xl shadow-2xl flex flex-col max-h-[85vh]">

        {/* Header */}
        <div className="flex items-center gap-3 px-5 py-4 border-b border-[var(--ff-border-light)]">
          <div className="p-2 rounded-lg bg-teal-500/10">
            <Search className="h-4 w-4 text-teal-400" />
          </div>
          <div className="flex-1 min-w-0">
            <h2 className="text-sm font-semibold text-[var(--ff-text-primary)]">Find &amp; Match</h2>
            <p className="text-xs text-[var(--ff-text-tertiary)] truncate">
              {transaction.transactionDate} &middot; {transaction.description ?? 'No description'}
            </p>
          </div>
          <div className="text-right mr-2">
            <p className={`text-base font-bold font-mono ${transaction.amount < 0 ? 'text-red-400' : 'text-teal-400'}`}>
              {fmtCurrency(transaction.amount)}
            </p>
          </div>
          <button onClick={onClose} className="p-1.5 rounded hover:bg-[var(--ff-bg-primary)] text-[var(--ff-text-tertiary)]">
            <X className="h-4 w-4" />
          </button>
        </div>

        {/* Search bar */}
        <div className="px-4 pt-3 pb-2">
          <div className="relative">
            <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 h-3.5 w-3.5 text-[var(--ff-text-tertiary)]" />
            <input
              type="text"
              placeholder="Filter candidates…"
              value={search}
              onChange={e => setSearch(e.target.value)}
              className="w-full pl-8 pr-3 py-1.5 rounded bg-[var(--ff-bg-primary)] border border-[var(--ff-border-light)] text-xs text-[var(--ff-text-primary)] focus:outline-none focus:border-blue-500"
            />
          </div>
        </div>

        {/* Candidate list */}
        <div className="overflow-y-auto flex-1 px-4 pb-3 space-y-4">
          {loading && (
            <div className="flex items-center justify-center py-10 gap-2 text-[var(--ff-text-tertiary)]">
              <Loader2 className="h-4 w-4 animate-spin" />
              <span className="text-xs">Loading candidates…</span>
            </div>
          )}

          {error && (
            <div className="text-xs text-red-400 py-4 text-center">{error}</div>
          )}

          {!loading && !error && filtered.length === 0 && (
            <div className="text-xs text-[var(--ff-text-tertiary)] py-4 text-center">
              No candidates found. Try importing the corresponding document first.
            </div>
          )}

          {!loading && !error && GROUP_ORDER.map(type => {
            // Safe non-null lookups — GROUP_ORDER and TYPE_META are both keyed by CandidateType
            const group: MatchCandidate[] = grouped[type] ?? [];
            if (group.length === 0) return null;
            const meta = TYPE_META[type]!;
            const Icon = meta.icon;
            return (
              <div key={type}>
                <p className="text-[10px] font-semibold uppercase tracking-wide text-[var(--ff-text-tertiary)] mb-1.5">
                  {GROUP_TITLES[type]}
                </p>
                <div className="space-y-1">
                  {group.map(c => {
                    const exact = txIsExact(c);
                    const isSelected = selected?.id === c.id && selected?.type === c.type;
                    return (
                      <button
                        key={`${c.type}-${c.id}`}
                        onClick={() => setSelected(isSelected ? null : c)}
                        className={`w-full text-left rounded-lg border px-3 py-2 transition-colors ${
                          isSelected
                            ? 'border-blue-500 bg-blue-500/10'
                            : 'border-[var(--ff-border-light)] bg-[var(--ff-bg-primary)] hover:border-[var(--ff-border-medium)]'
                        }`}
                      >
                        <div className="flex items-center gap-2">
                          {/* Type badge */}
                          <span className={`inline-flex items-center gap-1 text-[10px] font-medium px-1.5 py-0.5 rounded ${meta.colour}`}>
                            <Icon className="h-2.5 w-2.5" />
                            {meta.label}
                          </span>

                          {/* Label */}
                          <span className="flex-1 text-xs text-[var(--ff-text-primary)] truncate">{c.label}</span>

                          {/* Amount */}
                          <span className={`text-xs font-mono font-semibold ${exact ? 'text-teal-400' : 'text-[var(--ff-text-primary)]'}`}>
                            {fmtCurrency(c.amount)}
                            {exact && <span className="ml-1 text-[10px] text-teal-400">exact</span>}
                          </span>
                        </div>

                        {/* Date + score bar */}
                        <div className="flex items-center gap-3 mt-1.5">
                          <span className="text-[10px] text-[var(--ff-text-tertiary)]">{c.date}</span>
                          <div className="flex-1 h-1 rounded-full bg-[var(--ff-bg-secondary)] overflow-hidden">
                            <div
                              className="h-full rounded-full bg-blue-500"
                              style={{ width: `${Math.min(100, c.score)}%` }}
                            />
                          </div>
                          <span className="text-[10px] text-[var(--ff-text-tertiary)] w-8 text-right">{c.score}pt</span>
                        </div>
                      </button>
                    );
                  })}
                </div>
              </div>
            );
          })}
        </div>

        {/* Footer */}
        <div className="border-t border-[var(--ff-border-light)] px-5 py-3 flex items-center justify-between">
          <p className="text-xs text-[var(--ff-text-tertiary)]">
            {selected
              ? `Selected: ${TYPE_META[selected.type]?.label ?? selected.type} — ${selected.label}`
              : 'Select a candidate to match'}
          </p>
          <div className="flex items-center gap-2">
            <button
              onClick={onClose}
              className="px-3 py-1.5 rounded text-xs text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] border border-[var(--ff-border-light)]"
            >
              Cancel
            </button>
            <button
              onClick={handleConfirm}
              disabled={!selected || confirming}
              className="inline-flex items-center gap-1.5 px-4 py-1.5 rounded text-xs font-medium bg-teal-600 hover:bg-teal-700 disabled:opacity-40 text-white transition-colors"
            >
              {confirming
                ? <><Loader2 className="h-3 w-3 animate-spin" /> Confirming…</>
                : <><CheckCircle className="h-3 w-3" /> Confirm Match</>
              }
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

