    }
    return null;
  });
  const [selectedClient, setSelectedClient] = useState<SelectOption | null>(() => {
    if (selection?.type === 'customer' && selection.entityId) {
      return clients.find(c => c.id === selection.entityId) || null;
    }
    return null;
  });

