RETURNS TRIGGER AS $$
DECLARE
  cn_year INT;
  next_seq INT;
BEGIN
  cn_year := EXTRACT(YEAR FROM NEW.credit_date);
  SELECT COALESCE(MAX(
    CAST(SPLIT_PART(credit_note_number, '-', 3) AS INT)
  ), 0) + 1 INTO next_seq
  FROM credit_notes
  WHERE credit_note_number LIKE 'CN-' || cn_year || '-%';

  NEW.credit_note_number := 'CN-' || cn_year || '-' || LPAD(next_seq::TEXT, 5, '0');
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

